#include <stdlib.h>
#include <string.h>

typedef struct Node {
    int data;
    struct Node *next;
} Node;

Node* traverseDOM(int *states, int numStates, FSA *fsa, int lastState) {
    // allocate memory for the state list
    Node *stateList = malloc(sizeof(Node) * numStates);
    if (stateList == NULL) {
        return NULL;
    }

    // initialize the state list
    for (int i = 0; i < numStates; i++) {
        stateList[i].data = states[i];
        stateList[i].next = &stateList[i + 1];
    }

    // set the last state in the list to point to the newly created state list
    stateList[lastState - 1].next = stateList;

    return stateList;
}
