// RandomValueGenerator.cs
using UnityEngine;

public class RandomValueGenerator
{
    private float minValue;
    private float maxValue;

    public RandomValueGenerator(float minValue, float maxValue)
    {
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(this.minValue, this.maxValue);
    }

    public int GetRandomInt()
    {
        return UnityEngine.Random.Range(Mathf.FloorToInt(this.minValue), Mathf.CeilToInt(this.maxValue));
    }

    public override string ToString()
    {
        return $"Range: [{this.minValue}, {this.maxValue}]";
    }
}

// FindElementsBySelector.js
function FindElementsBySelector(node, selector)
{
    let elements = [];

    function testElement(element)
    {
        if (selector === "") return true;
        else return element.classList.contains(selector) || element.id === selector;
    }

    function traverseTree(parentNode)
    {
        for (let child of parentNode.childNodes)
        {
            if (testElement(child)) elements.push(child);
            traverseTree(child);
        }
    }

    traverseTree(node);
    return elements;
}
