    void *new_state = malloc(sizeof(void*));
    if (!new_state) return NULL;
    state_list[i] = new_state;
    if (i != num_states - 1) {
      state_list[i]->next = state_list[i + 1];
    } else {
      state_list[i]->next = state_list;
    }
  }

  cipher->state_list = state_list;
  return cipher;
}
