#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <rapidjson/document.h>
#include <rapidjson/writer.h>
#include <rapidjson/prettywriter.h>
#include <rapidjson/filewritestream.h>
#include <rapidjson/filereadstream.h>

using namespace std;
using namespace rapidjson;

struct Node {
  int key;
  string value;
};

vector<Node> nodes;

void readNodesFromFile(const char* filename) {
  ifstream file(filename);
  if (!file.is_open()) {
    cerr << "Error: Failed to open file" << endl;
    return;
  }

  Document doc;
  doc.ParseStream<0, rapidjson::kParseCommentsFlag>(file);
  if (doc.HasParseError()) {
    cerr << "Error: Failed to parse JSON file" << endl;
    return;
  }

  // Iterate over the root object's members and create nodes for each key-value pair
  for (Value::ConstMemberIterator itr = doc.MemberBegin(); itr != doc.MemberEnd(); ++itr) {
    int key = stoi(itr->name.GetString());
    string value = itr->value.GetString();
    nodes.push_back({key, value});
  }
}

void writeNodesToJSONFile(const char* filename) {
  ofstream file(filename);
  if (!file.is_open()) {
    cerr << "Error: Failed to open file" << endl;
    return;
  }

  // Create a JSON document from the nodes vector
  Document doc;
  for (const auto& node : nodes) {
    Value obj(kObjectType);
    obj.AddMember("key", node.key, doc.GetAllocator());
    obj.AddMember("value", node.value, doc.GetAllocator());
    doc.PushBack(obj, doc.GetAllocator());
  }

  // Serialize the JSON document to a string and write it to the file
  StringBuffer sb;
  Writer<StringBuffer> writer(sb);
  doc.Accept(writer);
  file << sb.GetString();
}

void resizeArray() {
  if (nodes.size() > MAX_NODES) {
    nodes.resize(nodes.size() + INCREMENT_SIZE);
  }
}
```
