import java.net.Channel;

public class GameCharacter {
    private Channel channel;
    private int currentAttack = 0;
    private boolean isCooldownActive = false;
    private long lastAttackTime = 0L;

    public void connectToRemoteAddress() throws IOException {
        // Establish a connection to the remote address using a Java Channel
        channel = new Socket(remoteHost, remotePort);

        // Register a callback for state changes
        channel.addStateListener((newState) -> {
            switch (newState) {
                case CONNECTED:
                    System.out.println("Connected to remote address");
                    break;
                case LISTENING:
                    System.out.println("Waiting for incoming connections...");
                    break;
                case CLOSED:
                    System.out.println("Connection closed");
                    break;
            }
        });
    }

    public void handleAttackSelection() {
        // Select a random attack number between 1 and 2
        currentAttack = (int) (Math.random() * 2 + 1);

        // Print the selected attack number to the console
        System.out.println("Selected attack: " + currentAttack);

        // Activate the cooldown period for 9 seconds
        isCooldownActive = true;
        lastAttackTime = System.currentTimeMillis();
    }

    public void handleConnectionStateChange(int newState) {
        switch (newState) {
            case CONNECTED:
                // If the connection has been established and the cooldown period has expired, allow the game character to use an attack
                if (!isCooldownActive || System.currentTimeMillis() - lastAttackTime > 9000) {
                    handleAttackSelection();
                } else {
                    System.out.println("Waiting for cooldown period to expire...");
                }
                break;
            case LISTENING:
                // If the connection is waiting for incoming connections, do nothing
                break;
            case CLOSED:
                // If the connection has been closed, print an error message and reset the cooldown period
                System.out.println("Connection closed");
                isCooldownActive = false;
                lastAttackTime = 0L;
        }
    }
}
