function generateSecureRandomString($length = 16, $charset = '0-9a-zA-Z') {
    // Validate input parameters
    if (!is_int($length) || $length < 1) {
        throw new InvalidArgumentException('Invalid length for secure random string.');
    }
    if (!is_string($charset)) {
        throw new InvalidArgumentException('Invalid character set for secure random string.');
    }

    // Generate a secure random string using OpenSSL
    $randomString = openssl_random_pseudo_bytes(ceil($length / 2));

    // Use the custom hash algorithm and salting to hash the password
    $hashedPassword = hash('bcrypt', $password, ['cost' => 12]);

    // Create a secure token by combining the random string with the hashed password
    $token = $randomString . $hashedPassword;

    // Validate the generated token for errors during generation and hashing
    if (!$token || strlen($token) !== ($length + 60)) {
        throw new RuntimeException('Error generating secure random string.');
    }

    // Integrate with a session management system to store and retrieve tokens and hashed passwords
    $sessionManager->set('token', $token);
    $sessionManager->set('hashedPassword', $hashedPassword);

    return $token;
}
