using System;

public class AdvancedRandomGenerator
{
    private static Random _random = new Random();
    private static int _seed = 123456789;
    private static SeedCallback? _callback;

    public delegate void SeedCallback(int seed);

    // CustomRange method
    public float CustomRange(float min, float max, RangeType rangeType, bool seeded, int? seed = null, SeedCallback? callback = null)
    {
        if (seeded && seed != null)
        {
            _seed = seed.Value;
            _random = new Random(_seed);
        }

        switch (rangeType)
        {
            case RangeType.Closed:
                return (float)_random.Next((int)(min * 100), (int)(max * 100)) / 100;
            case RangeType.Open:
                return (float)_random.Next((int)(min * 100) + 1, (int)(max * 100)) / 100;
            case RangeType.HalfOpen:
                return (float)_random.Next((int)(min * 100), (int)(max * 100) - 1) / 100;
        }
    }

    // SeededRandom Generation
    public float CustomRange(int min, int max, RangeType rangeType, bool seeded, int? seed = null, SeedCallback? callback = null)
    {
        if (seeded && seed != null)
        {
            _seed = seed.Value;
            _random = new Random(_seed);
        }

        switch (rangeType)
        {
            case RangeType.Closed:
                return _random.Next(min, max);
            case RangeType.Open:
                return _random.Next(min + 1, max);
            case RangeType.HalfOpen:
                return _random.Next(min, max - 1);
        }
    }

    // Integration with External Systems
    public void SetSeedCallback(SeedCallback callback)
    {
        _callback = callback;
    }

    // Error Handling and Robustness
    private static bool ValidateInput(float min, float max, RangeType rangeType)
    {
        if (min > max || min < 0 || max < 0)
            throw new ArgumentException("Invalid input parameters for the range");

        if (!Enum.IsDefined(typeof(RangeType), rangeType))
            throw new ArgumentException($"Unknown RangeType: '{rangeType}'");
    }
}
