<?php

function updateClinicStatus($clinicId, $newStatus) {
    // Validate clinic ID before proceeding with update
    if (!isValidClinicId($clinicId)) {
        return ["error" => "Invalid clinic ID"];
    }

    // Start transaction to ensure data integrity
    $pdo = new PDO('mysql:host=localhost;dbname=my_database', 'username', 'password');
    $pdo->beginTransaction();

    // Update database table with new status, last modified IP address, and last modified date for given clinic ID
    try {
        $stmt = $pdo->prepare("UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = NOW() WHERE id = ?");
        $stmt->execute([$newStatus, $_SERVER['REMOTE_ADDR'], $clinicId]);
    } catch (Exception $e) {
        // Log any errors or exceptions and provide detailed error message
        error_log("Error updating clinic status: " . $e->getMessage());
        return ["error" => "Error updating clinic status"];
    }

    // Commit transaction if update was successful
    $pdo->commit();

    // Return success message with number of clinics updated
    return ["success" => true, "clinics_updated" => 1];
}

function isValidClinicId($clinicId) {
    // Validate clinic ID by checking if it exists in the database table
    $pdo = new PDO('mysql:host=localhost;dbname=my_database', 'username', 'password');
    $stmt = $pdo->prepare("SELECT id FROM clinics WHERE id = ?");
    $stmt->execute([$clinicId]);
    $result = $stmt->fetch();
