using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Text;

public class QueryExecutor
{
    private SqlConnection _connection;
    private string _commandTemplate;
    private Dictionary<string, object> _parameters;

    public QueryExecutor(SqlConnection connection, string commandTemplate, Dictionary<string, object> parameters)
    {
        _connection = connection;
        _commandTemplate = commandTemplate;
        _parameters = parameters;
    }

    public DataTable Execute()
    {
        var query = BuildQuery();
        var command = new SqlCommand(query, _connection);

        try
        {
            using (var reader = command.ExecuteReader())
            {
                var table = new DataTable();
                table.Load(reader);
                return table;
            }
        }
        catch (SqlException ex)
        {
            // Log error and throw appropriate exception
            Console.WriteLine($"SQL Error: {ex.Message}");
            throw new Exception("Error executing query", ex);
        }
    }

    private string BuildQuery()
    {
        var query = _commandTemplate;

        foreach (var parameter in _parameters)
        {
            // Validate input parameters to prevent SQL injection attacks
            if (!IsValidParameter(parameter.Value))
                throw new Exception($"Invalid parameter value: {parameter.Value}");

            var parameterName = $"@{parameter.Key}";
            query = query.Replace(parameterName, parameter.Value.ToString());
        }

        return query;
    }

    private bool IsValidParameter(object value)
    {
        // Validate input parameters to prevent SQL injection attacks
        if (value == null)
            return false;

        var type = value.GetType();

        if (type == typeof(int))
            return true;
        else if (type == typeof(string))
            return !string.IsNullOrEmpty((string)value);
        else if (type == typeof(DateTime))
            return true;
        else if (type == typeof(bool))
            return true;
        else
            return false;
    }
}
```
This code uses a `SqlConnection` object to connect to the SQL database, and a `SqlCommand` object to execute the query. It also uses a dictionary of parameter names and their corresponding values to dynamically generate the SQL query. The `BuildQuery()` method is used to replace the placeholders in the query template with the actual parameter values. The `Execute()` method is then called to execute the query and return the result set as a `DataTable`.

The code also includes error handling and resource disposal, using the `using` keyword to ensure that the database connection and reader are properly closed and disposed of when they are no longer needed. Additionally, the code includes validation for input parameters to prevent SQL injection attacks, by checking if the parameter value is null or an empty string for strings, and throwing an exception if any invalid values are found.

Note that this is just a basic example, and you may need to modify it to fit your specific needs and database schema.

