import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.AsynchronousServerSocketChannel;
import java.util.Random;

public class ConnectionManager {
    private AsynchronousServerSocketChannel serverSocketChannel;
    private boolean isConnected;
    private long cooldownPeriod;
    private long lastAttackTime;

    public ConnectionManager() throws IOException {
        this.serverSocketChannel = AsynchronousServerSocketChannel.open();
        this.isConnected = false;
        this.cooldownPeriod = 1000; // default cooldown period is 1 second
        this.lastAttackTime = System.currentTimeMillis() - this.cooldownPeriod;
    }

    public void connectToServer(InetSocketAddress serverAddress) throws IOException {
        if (!this.isConnected) {
            this.serverSocketChannel.connect(serverAddress);
            this.isConnected = true;
            System.out.println("Established connection to server");
        }
    }

    public void disconnectFromServer() throws IOException {
        if (this.isConnected) {
            this.serverSocketChannel.close();
            this.isConnected = false;
            System.out.println("Disconnected from server");
        }
    }

    public boolean isConnectedToServer() {
        return this.isConnected;
    }

    public void handleRetriesAndTimeouts() throws IOException {
        if (!this.isConnected) {
            try {
                connectToServer(new InetSocketAddress("localhost", 8080));
                cooldownPeriod = 1000; // default cooldown period is 1 second
            } catch (IOException e) {
                System.out.println("Error connecting to server, retrying in 5 seconds...");
                try {
                    Thread.sleep(5000); // sleep for 5 seconds before retrying
                } catch (InterruptedException ex) {
                    ex.printStackTrace();
                }
            }
        } else {
            if (System.currentTimeMillis() - lastAttackTime > cooldownPeriod) {
                selectAndMakeAttack();
            } else {
                System.out.println("Cooldown period not met, waiting...");
            }
        }
    }

    public void selectAndMakeAttack() throws IOException {
        // random selection mechanism for one of two types of attacks with a cooldown period between attacks
        Random rand = new Random();
        int attackType = rand.nextInt(2); // 0 or 1
        long attackPower = 0;
        if (attackType == 0) {
            attackPower = 500; // attack power level for type 0
        } else {
            attackPower = 1000; // attack power level for type 1
        }
        System.out.println("Selected attack type: " + attackType);
        System.out.println("Attack power level: " + attackPower);
        lastAttackTime = System.currentTimeMillis();
    }

    public void logEvent(String event) {
        // logging events for debugging purposes
        System.out.println(event);
    }
}
```
This code creates a `ConnectionManager` class that manages the connection to a remote server using NIO channels. The `connectToServer()` method establishes a connection to the server, and the `disconnectFromServer()` method disconnects from the server. The `isConnectedToServer()` method returns whether or not the client is connected to the server.

The `handleRetriesAndTimeouts()` method handles retries and timeouts gracefully by trying to connect to the server if it's not connected, and by retrying after 5 seconds if there's an error connecting. It also checks whether the cooldown period has been met before selecting and making an attack.

The `selectAndMakeAttack()` method selects one of two types of attacks randomly with a cooldown period between attacks. It logs the selected attack type and power level to the console. The `lastAttackTime` variable is used to keep track of the last time an attack was made, so that the cooldown period can be checked before making another attack.

The `logEvent()` method is used for logging events for debugging purposes.

