using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

namespace DynamicRandomNumberGenerator
{
    public class DynamicRandomNumberGenerator
    {
        private readonly Random _random = new Random();
        private readonly object _lockObject = new object();

        private Dictionary<int, int> _ranges = new Dictionary<int, int>();
        private Dictionary<int, float> _floatRanges = new Dictionary<int, float>();

        public DynamicRandomNumberGenerator() { }

        public void GenerateCustomRandom(int minValue, int maxValue, RandomType type)
        {
            lock (_lockObject)
            {
                int rangeLength = GetRangeLength(minValue, maxValue);

                switch (type)
                {
                    case RandomType.Closed:
                        _ranges[rangeLength] = minValue;
                        break;
                    case RandomType.Open:
                        _ranges[rangeLength] = minValue + 1;
                        break;
                    case RandomType.HalfOpen:
                        _ranges[rangeLength] = minValue + 2;
                        break;
                }
            }
        }

        public void GenerateCustomRandom(float minValue, float maxValue, RandomType type)
        {
            lock (_lockObject)
            {
                int rangeLength = GetRangeLength(minValue, maxValue);

                switch (type)
                {
                    case RandomType.Closed:
                        _floatRanges[rangeLength] = minValue;
                        break;
                    case RandomType.Open:
                        _floatRanges[rangeLength] = minValue + 1f;
                        break;
                    case RandomType.HalfOpen:
                        _floatRanges[rangeLength] = minValue + 2f;
                        break;
                }
            }
        }

        public int GenerateRandom(int minValue, int maxValue)
        {
            lock (_lockObject)
            {
                int rangeLength = GetRangeLength(minValue, maxValue);

                if (_ranges.TryGetValue(rangeLength, out int seed))
                {
                    return _random.Next(seed, minValue + 1);
                }
                else
                {
                    return _random.Next(minValue, maxValue + 1);
                }
            }
        }

        public float GenerateRandom(float minValue, float maxValue)
        {
            lock (_lockObject)
            {
                int rangeLength = GetRangeLength(minValue, maxValue);

                if (_floatRanges.TryGetValue(rangeLength, out float seed))
                {
                    return _random.NextFloat(seed, minValue + 1f);
                }
                else
                {
                    return _random.NextFloat(minValue, maxValue + 1f);
                }
            }
        }

        private int GetRangeLength(int minValue, int maxValue) => (maxValue - minValue) + 1;

        public void ConfigureExternalSystem() { }

        public void HandleConfigUpdate(Dictionary<string, string> configSettings)
        {
            lock (_lockObject)
            {
                foreach (var setting in configSettings)
                {
                    if (setting.Key == "seed")
                    {
                        int seed = Convert.ToInt32(setting.Value);
                        _random = new Random(seed);
                    }
                }
            }
        }

        public void UpdateConfiguration() { }

        public bool ValidateInput(int minValue, int maxValue) => true;

        public bool ValidateInput(float minValue, float maxValue) => true;

        public enum RandomType
        {
            Closed,
            Open,
            HalfOpen
        }
    }
}
