// Define the attack cooldown periods
const int ATTACK1_COOLDOWN = 9;
const int ATTACK2_COOLDOWN = 15;

// Define a mutex to ensure thread-safe access to shared variables
std::mutex attackMutex;

void selectAttack() {
    // Lock the mutex to prevent concurrent access
    std::lock_guard<std::mutex> lock(attackMutex);

    // Generate a random number between 1 and 2 to select an attack
    int attack = rand() % 2 + 1;

    // Print the selected attack to the console
    std::cout << "Selected Attack: " << attack << std::endl;

    // Check if the cooldown period for the selected attack has expired
    if (attack == 1) {
        // Check if the cooldown period has expired
        if (std::chrono::system_clock::now() - lastAttack1Time > std::chrono::seconds(ATTACK1_COOLDOWN)) {
            // Set the time for the next attack
            lastAttack1Time = std::chrono::system_clock::now();
        } else {
            // Wait until the cooldown period has expired
            std::this_thread::sleep_for(std::chrono::seconds(ATTACK1_COOLDOWN - (lastAttack1Time - std::chrono::system_clock::now()).count()));
        }
    } else if (attack == 2) {
        // Check if the cooldown period has expired
        if (std::chrono::system_clock::now() - lastAttack2Time > std::chrono::seconds(ATTACK2_COOLDOWN)) {
            // Set the time for the next attack
            lastAttack2Time = std::chrono::system_clock::now();
        } else {
            // Wait until the cooldown period has expired
            std::this_thread::sleep_for(std::chrono::seconds(ATTACK2_COOLDOWN - (lastAttack2Time - std::chrono::system_clock::now()).count()));
        }
    }
}

// Define the last attack times as global variables
time_point<system_clock> lastAttack1Time;
time_point<system_clock> lastAttack2Time;
  ```
This code uses a mutex to ensure thread-safe access to the shared variables `lastAttack1Time` and `lastAttack2Time`. It also uses a random number generator to select one of two attacks, and checks if the cooldown period for the selected attack has expired. If it has not, the function waits until the cooldown period has expired before returning. The `std::chrono` namespace is used for time-related operations, including calculating the difference between two `time_point` objects and converting them to seconds.

