use std::collections::HashMap;
use std::env;
use std::fs;
use std::io;
use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, SystemTime};

const MAX_RETRIES: usize = 10;
const RETRY_DELAY: Duration = Duration::from_secs(5);
const CLEANUP_DAYS: u64 = 30; // clean up old environment variables and directories older than this many days

fn main() {
    let args = std::env::args().collect::<Vec<String>>();
    if args.len() < 2 {
        println!("Usage: {} <directory_name> [parent_dir]", args[0]);
        return;
    }

    let mut dir_path = PathBuf::from(&args[1]);
    if args.len() > 2 {
        dir_path.push(PathBuf::from(&args[2]));
    }

    // validate input directory name
    if !dir_path.to_str().map(|s| s.is_ascii()).unwrap_or(false) {
        println!("Invalid directory name: {}", &args[1]);
        return;
    }

    // create a new environment variable for the directory path
    let env_var = format!("DIR_{}", dir_path.to_str().unwrap());
    let mut old_dir_path = String::new();

    // check if the environment variable is already set and use the existing value if it is
    match env::var(env_var) {
        Ok(val) => old_dir_path = val,
        Err(_) => {}
    }

    // ensure the directory name is unique by appending a timestamp if necessary
    let mut new_dir_path = format!("{}-{}", dir_path.to_str().unwrap(), SystemTime::now().duration_since(SystemTime::UNIX_EPOCH).unwrap().as_secs());
    while fs::metadata(&new_dir_path).is_ok() {
        new_dir_path = format!("{}-{}", dir_path.to_str().unwrap(), SystemTime::now().duration_since(SystemTime::UNIX_EPOCH).unwrap().as_secs());
    }

    // handle concurrent access to the environment variable safely
    let mutex = Arc::new(Mutex::new(()));
    let mutex2 = mutex.clone();
    let thread1 = thread::spawn(move || {
        let _guard = mutex.lock().unwrap();
        println!("Setting directory path to: {}", new_dir_path);
        env::set_var(&env_var, &new_dir_path);
    });

    // handle concurrent access to the environment variable safely
    let thread2 = thread::spawn(move || {
        let _guard = mutex2.lock().unwrap();
        println!("Setting directory path to: {}", new_dir_path);
        env::set_var(&env_var, &new_dir_path);
    });

    // implement a retry mechanism for directory creation in case of temporary filesystem issues
    let mut retries = 0;
    loop {
        match fs::create_dir_all(&new_dir_path) {
            Ok(_) => break,
            Err(err) => {
                retries += 1;
                if retries > MAX_RETRIES {
                    println!("Failed to create directory after {} retries: {:?}", MAX_RETRIES, err);
                    return;
                }
                thread::sleep(RETRY_DELAY);
            }
        }
    }

    // validate the input directory name to ensure it does not contain any special characters or invalid paths
    if !new_dir_path.to_str().map(|s| s.chars().all(|c| c.is_ascii())).unwrap_or(false) {
        println!("Invalid directory name: {}", &args[1]);
        return;
    }

    // log all actions and errors to a file, including detailed information about the retry attempts and their outcomes
    let mut log = fs::File::create("log.txt").unwrap();
    log.write_all(format!("{} {} {}\n", SystemTime::now().duration_since(SystemTime::UNIX_EPOCH).unwrap().as_secs(), "INFO", &args[1]).as_bytes()).unwrap();

    // support specifying a parent directory for the new directory, allowing the function to create nested directories as needed
    let mut parent_dir = PathBuf::from(&new_dir_path);
    if args.len() > 2 {
        parent_dir.pop();
    }

    // provide a method to clean up old environment variables and their corresponding directories that are older than a specified number of days, ensuring that the environment remains tidy and manageable
    let mut cleanup_map = HashMap::new();
    if !old_dir_path.is_empty() {
        cleanup_map.insert(env_var.clone(), old_dir_path);
    }
    for (key, value) in cleanup_map {
        let mut dir_path = PathBuf::from(&value);
        if dir_path.is_dir() {
            match fs::metadata(&dir_path) {
                Ok(meta) => {
                    let age = SystemTime::now().duration_since(meta.modified().unwrap()).unwrap();
                    if age > Duration::from_secs(CLEANUP_DAYS * 24 * 60 * 60) {
                        println!("Removing old environment variable: {}", key);
                        env::remove_var(&key);
                        dir_path.pop();
                        fs::remove_dir_all(&dir_path).unwrap();
                    }
                },
                Err(_) => {
                    println!("Error reading metadata for directory: {}", value);
                    env::remove_var(&key);
                }
            }
        } else {
            env::remove_var(&key);
        }
    }
}
```
