// Rust function to create a new directory and set an environment variable
fn create_directory_and_set_env_var(dir_name: &str) {
    // Check if the environment variable is already set
    let env_var = std::env::var("MY_DIRECTORY").unwrap();
    if !env_var.is_empty() {
        println!("Using existing directory {}", env_var);
    } else {
        // Create a new directory with the given name
        let dir_path = std::path::Path::new(dir_name);
        match std::fs::create_dir_all(dir_path) {
            Ok(_) => println!("Created directory {}", dir_name),
            Err(e) => println!("Failed to create directory: {}", e),
        };

        // Set the environment variable to the path of the newly created directory
        std::env::set_var("MY_DIRECTORY", &dir_path.to_str().unwrap());
    }
}
