const fs = require('fs');

function readFileSync(filePath) {
    if (!filePath || typeof filePath !== 'string') {
        throw new Error(`Invalid file path "${filePath}"`);
    }

    try {
        return fs.readFileSync(filePath, 'utf8');
    } catch (err) {
        if (err.code === 'ENOENT') {
            // File does not exist
            throw new Error(`File "${filePath}" does not exist`);
        } else {
            // Unknown error
            throw err;
        }
    }
}
