using System;
using System.IO;
using System.Threading.Tasks;
using Microsoft.Web.Administration;

public static class WebsiteHelper
{
    public static async Task<TaskResult> AddAndStartWebsite(string directoryPath, string siteName)
    {
        // Verify the presence of a web.config file
        if (!File.Exists(Path.Combine(directoryPath, "web.config")))
        {
            Console.WriteLine($"Missing web.config file at '{directoryPath}'. Unable to add and start website.");
            return new TaskResult();
        }

        // Get the IIS manager object for the current server
        using (ServerManager serverManager = new ServerManager())
        {
            try
            {
                // Create a new site and set its physical path
                Site newSite = serverManager.Sites.Add(siteName, directoryPath);
                newSite.ApplicationDefaults.VirtualDirectories.Add("/", directoryPath);

                // Start the site and log success
                Console.WriteLine($"Starting website '{siteName}' at {directoryPath}");
                await serverManager.CommitChangesAsync();
                return new TaskResult(true);
            }
            catch (Exception e)
            {
                Console.WriteLine($"Error adding and starting website '{siteName}': {e.Message}");
                return new TaskResult(false, e.ToString());
            }
        }
    }
}

// Define a custom TaskResult class for tracking the result of the task
public class TaskResult
{
    public bool Success { get; set; }
    public string ErrorMessage { get; set; }

    public TaskResult(bool success = false, string errorMessage = "")
    {
        Success = success;
        ErrorMessage = errorMessage;
    }
}
