```
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

namespace FileEncryption
{
    public class FileEncryptor
    {
        private readonly AesGcm _aesGcm;
        private readonly string _key;
        private readonly string _salt;
        private readonly IFileStorageService _fileStorageService;

        public FileEncryptor(string key, string salt, IFileStorageService fileStorageService)
        {
            _key = key;
            _salt = salt;
            _aesGcm = new AesGcm(_key);
            _fileStorageService = fileStorageService;
        }

        public byte[] Encrypt(string fileName, byte[] plainTextBytes)
        {
            // Generate nonce and tag
            byte[] nonce = new byte[12];
            byte[] tag = new byte[16];
            _aesGcm.GenerateNonceAndTag(nonce, tag);

            // Encrypt plain text
            byte[] cipherTextBytes = EncryptBytes(plainTextBytes);

            // Store encryption metadata
            var encryptionMetadata = new FileEncryptionMetadata
            {
                Nonce = nonce,
                Tag = tag,
                InitializationVector = _aesGcm.InitializationVector,
            };
            _fileStorageService.StoreFileEncryptionMetadata(fileName, encryptionMetadata);

            // Return encrypted bytes
            return cipherTextBytes;
        }

        public byte[] Decrypt(string fileName, byte[] cipherTextBytes)
        {
            // Retrieve encryption metadata
            var encryptionMetadata = _fileStorageService.RetrieveFileEncryptionMetadata(fileName);

            // Decrypt cipher text
            byte[] plainTextBytes = DecryptBytes(cipherTextBytes, encryptionMetadata);

            // Verify integrity of decrypted data
            if (!VerifyIntegrity(plainTextBytes))
            {
                throw new InvalidOperationException("Decrypted data is corrupted");
            }

            return plainTextBytes;
        }

        private byte[] EncryptBytes(byte[] plainTextBytes)
        {
            using (var memoryStream = new MemoryStream())
            {
                using (var encryptor = _aesGcm.CreateEncryptor())
                {
                    using (var cryptoStream = new CryptoStream(memoryStream, encryptor, CryptoStreamMode.Write))
                    {
                        cryptoStream.Write(plainTextBytes, 0, plainTextBytes.Length);
                        cryptoStream.FlushFinalBlock();
                    }
                }
                return memoryStream.ToArray();
            }
        }

        private byte[] DecryptBytes(byte[] cipherTextBytes, FileEncryptionMetadata encryptionMetadata)
        {
            using (var memoryStream = new MemoryStream())
            {
                using (var decryptor = _aesGcm.CreateDecryptor())
                {
                    using (var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Write))
                    {
                        cryptoStream.Write(cipherTextBytes, 0, cipherTextBytes.Length);
                        cryptoStream.FlushFinalBlock();
                    }
                }
                return memoryStream.ToArray();
            }
        }

        private bool VerifyIntegrity(byte[] plainTextBytes)
        {
            using (var hmacSha512 = new HMACSHA512(_key))
            {
                byte[] expectedTag = hmacSha512.ComputeHash(plainTextBytes);
                return _fileStorageService.VerifyFileIntegrity(expectedTag, encryptionMetadata.Tag);
            }
        }
    }
}
```
This is a simple example of how you could implement file encryption and decryption using AES-GCM with a key management service in C#. The `FileEncryptor` class provides an easy-to-use API for encrypting and decrypting files, while the underlying implementation uses AES-GCM to provide secure and efficient encryption.

The `Encrypt` method generates a nonce and tag using the `AesGcm` instance, encrypts the plain text bytes using the generated nonce and tag, stores the encryption metadata in the file storage service, and returns the encrypted bytes. The `Decrypt` method retrieves the encryption metadata from the file storage service, decrypts the cipher text bytes using the retrieved nonce and tag, verifies the integrity of the decrypted data using a HMAC-SHA512 hash function, and returns the plain text bytes.

The `EncryptBytes` and `DecryptBytes` methods use the `AesGcm` instance to encrypt and decrypt the input bytes, respectively. The `VerifyIntegrity` method uses a HMAC-SHA512 hash function to verify the integrity of the decrypted data by computing a tag from the plain text bytes and comparing it with the stored tag.

The `FileEncryptionMetadata` class is used to store and retrieve encryption metadata, which includes the nonce, tag, and initialization vector used for encryption. The `IFileStorageService` interface provides an abstraction layer for interacting with the file storage service, allowing for easy integration with different storage systems.

