#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
#include <thread>
#include <mutex>

class AdvancedOctreeInitializer {
public:
    // Initialize octree with feature size, number of leaf nodes, and data capacity
    void InitializeOctree(float featureSize, int numLeafNodes, int dataCapacity, bool seeded = false, int? seed = nullptr, SeedCallback? callback = nullptr) {
        if (seeded && seed == nullptr) {
            throw std::invalid_argument("Seed must be provided for seeded initialization");
        }

        // Update octree capacity if necessary to accommodate the requested number of leaf nodes
        if (numLeafNodes > dataCapacity) {
            dataCapacity = numLeafNodes;
        }

        // Initialize octree with feature size, number of leaf nodes, and data capacity
        std::vector<float> features(dataCapacity);
        std::generate(features.begin(), features.end(), [featureSize]() { return std::random_device()(); });

        // Seed the random engine if necessary
        if (seeded) {
            std::seed_seq seed_sequence(seed.value());
            std::mt19937 eng(seed_sequence);
            std::shuffle(features.begin(), features.end(), eng);
        }

        // Customize octree initialization with callback
        if (callback != nullptr) {
            callback(dataCapacity);
        }
    }

    // Seeded version of initialize octree
    void InitializeSeededOctree(float featureSize, int numLeafNodes, int dataCapacity, int seed) {
        std::mt19937 eng(seed);
        return InitializeOctree(featureSize, numLeafNodes, dataCapacity, true, seed, nullptr);
    }

    // Custom range with feature size, min, max, and range type
    void CustomRange(float min, float max, RangeType rangeType, bool seeded = false, int? seed = nullptr, SeedCallback? callback = nullptr) {
        if (seeded && seed == nullptr) {
            throw std::invalid_argument("Seed must be provided for seeded initialization");
        }

        // Calculate range size and update data capacity if necessary
        int rangeSize = max - min;
        if (rangeSize < 0) {
            throw std::runtime_error("Invalid range: maximum value is less than minimum value");
        }

        if (rangeType == RangeType::Inclusive) {
            dataCapacity += 1;
        }

        // Initialize octree with feature size, number of leaf nodes, and data capacity
        std::vector<float> features(dataCapacity);
        std::generate(features.begin(), features.end(), [featureSize]() { return std::random_device()(); });

        // Seed the random engine if necessary
        if (seeded) {
            std::seed_seq seed_sequence(seed.value());
            std::mt19937 eng(seed_sequence);
            std::shuffle(features.begin(), features.end(), eng);
        }

        // Customize octree initialization with callback
        if (callback != nullptr) {
            callback(dataCapacity);
        }
    }

    // Seeded version of custom range
    void CustomSeededRange(float min, float max, RangeType rangeType, int seed) {
        std::mt19937 eng(seed);
        return CustomRange(min, max, rangeType, true, seed, nullptr);
    }

private:
    // Mutex for thread-safe seeding mechanisms
    static std::mutex seedMutex;

    // Delegate type for customizing seed generation logic
    typedef void (*SeedCallback)(int capacity);
};
