#include <curl/curl.h>
#include <json/json.h>

bool verifyOAuth2AccessToken(const std::string& jsonString) {
    // Parse the JSON string into a JSON object
    Json::Value json;
    Json::Reader reader;
    if (!reader.parse(jsonString, json)) {
        return false;
    }

    // Check that all required fields are present and have valid values
    if (!json.isMember("access_token") || !json["access_token"].isString()) {
        return false;
    }
    if (!json.isMember("expires_in") || !json["expires_in"].isNumeric()) {
        return false;
    }
    if (!json.isMember("token_type") || !json["token_type"].isString() || json["token_type"] != "Bearer") {
        return false;
    }
    if (json.isMember("refresh_token")) {
        if (!json["refresh_token"].isString()) {
            return false;
