```java
import java.net.InetSocketAddress;
import java.nio.channels.AsynchronousSocketChannel;
import java.util.concurrent.TimeUnit;
import java.util.Random;

public class GameCharacter {
    private static final int COOLDOWN_PERIOD = 9; // seconds
    private AsynchronousSocketChannel channel;
    private long lastAttackTime;

    public void connect() {
        InetSocketAddress address = new InetSocketAddress("remote-address", 80);
        try {
            this.channel = AsynchronousSocketChannel.open(address);
            this.lastAttackTime = System.currentTimeMillis();
        } catch (Exception e) {
            // handle connection failure
            e.printStackTrace();
        }
    }

    public void disconnect() {
        if (this.channel != null) {
            try {
                this.channel.close();
            } catch (Exception e) {
                // handle channel close error
                e.printStackTrace();
            }
        }
    }

    public void attack() {
        long currentTime = System.currentTimeMillis();
        if (currentTime - this.lastAttackTime < COOLDOWN_PERIOD * 1000) {
            // cooldown period not yet expired, do nothing
            return;
        }

        Random random = new Random();
        int attackNumber = random.nextInt(2); // select an attack number (1 or 2) randomly

        try {
            // send the selected attack to the game server API
            String request = "ATTACK=" + attackNumber;
            this.channel.write(ByteBuffer.wrap(request.getBytes())).get();

            // log the attack event in the remote logging service
            LogEvent logEvent = new LogEvent("ATTACK", attackNumber, currentTime);
            RemoteLogger.log(logEvent);
        } catch (Exception e) {
            // handle channel write error or logging error
            e.printStackTrace();
        } finally {
            this.lastAttackTime = currentTime;
        }
    }
}
