#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <pthread.h>

// Structure to store information about a downloaded file
struct downloaded_file {
    char *url;
    char *output_path;
    size_t size;
};

// Function to download a file using libcurl
void* download_file(void *arg) {
    struct downloaded_file *file = (struct downloaded_file *) arg;

    // Initialize curl handle
    CURL *curl = curl_easy_init();
    if(!curl) {
        fprintf(stderr, "Failed to initialize curl handle\n");
        return NULL;
    }

    // Set URL and output file path
    curl_easy_setopt(curl, CURLOPT_URL, file->url);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, file->output_path);

    // Perform download
    CURLcode res = curl_easy_perform(curl);
    if(res != CURLE_OK) {
        fprintf(stderr, "Failed to download file: %s\n", curl_easy_strerror(res));
        return NULL;
    }

    // Get total downloaded size
    long download_size = 0;
    res = curl_easy_getinfo(curl, CURLINFO_SIZE_DOWNLOAD, &download_size);
    if(res != CURLE_OK) {
        fprintf(stderr, "Failed to get downloaded size: %s\n", curl_easy_strerror(res));
        return NULL;
    }

    // Close and release file
    fclose(file->output_path);
    curl_easy_cleanup(curl);

    return (void *) download_size;
}

// Function to manage thread pool for downloading files
int manage_threads(struct downloaded_file *files, int num_files) {
    pthread_t threads[num_files];
    int thread_ids[num_files];
    size_t total_downloaded = 0;

    // Create and start threads for downloading files
    for(int i = 0; i < num_files; i++) {
        if(pthread_create(&threads[i], NULL, download_file, (void *) &files[i]) != 0) {
            fprintf(stderr, "Failed to create thread %d\n", i);
            return -1;
        }
    }

    // Wait for threads to finish and sum up total downloaded size
    for(int i = 0; i < num_files; i++) {
        void *downloaded;
        pthread_join(threads[i], &downloaded);
        if(downloaded != NULL) {
            total_downloaded += (size_t) downloaded;
        }
    }

    return total_downloaded;
}

// Function to download files using libcurl and manage thread pool
void* download_files(struct downloaded_file *files, int num_files, char *output_path, int max_threads) {
    if(num_files <= 0 || output_path == NULL || max_threads <= 0) {
        fprintf(stderr, "Invalid input: num_files = %d, output_path = %s, max_threads = %d\n", num_files, output_path, max_threads);
        return NULL;
    }

    // Create thread pool for downloading files
    int thread_pool = manage_threads(files, num_files);
    if(thread_pool < 0) {
        fprintf(stderr, "Failed to create thread pool\n");
        return NULL;
    }

    // Download files and sum up total downloaded size
    int total_downloaded = manage_threads(files, num_files);
    if(total_downloaded < 0) {
        fprintf(stderr, "Failed to download files\n");
        return NULL;
    }

    // Create structure to store information about downloaded files
    struct download_info {
        size_t total_downloaded;
        int num_files;
        char *output_path;
        pthread_t threads[num_files];
    };
    struct download_info info = {total_downloaded, num_files, output_path, threads};

    return (void *) info;
}
```
This code block provides a function `download_file` that uses libcurl to download a file from a specified URL and save it to a file. The function takes a string parameter representing the URL and returns a pointer to a structure that contains information about the downloaded file, including the total size of the file and an array of thread IDs used for downloading the file.

The function `manage_threads` creates and manages a pool of threads for downloading files concurrently. It takes an array of `struct downloaded_file` as input and returns the total number of bytes downloaded by all the threads. If there is insufficient memory for the thread pool or the structure, the function returns NULL.

The function `download_files` takes an array of `struct downloaded_file` as input and creates a pool of threads to download files concurrently using the `manage_threads` function. It also saves the total number of bytes downloaded by all the threads and the number of files downloaded to a structure, which is then returned. If there is insufficient memory for the thread pool or the structure, the function returns NULL.

