  config = JSON.parse(fs.readFileSync(configFilePath, 'utf8'));
} catch (err) {
  console.error(`Failed to load configuration file: ${configFilePath}`);
  process.exit(1);
}

// Load modules concurrently with a maximum concurrency level of 5
const loadModule = util.promisify(vm.runInNewContext);
const loadModulesConcurrently = async (modules, maxConcurrency) => {
  const tasks = [];
  for (const modulePath of modules) {
    tasks.push(loadModule(modulePath));
  }
  return Promise.all(tasks).then((results) => results);
};

// Load and execute modules
async function main() {
  try {
    const modules = config.modules;
    console.log(`Loading ${modules.length} module${modules.length > 1 ? 's' : ''}`);
    const loadedModules = await loadModulesConcurrently(modules, 5);
    console.log('Loaded modules:', loadedModules);
    console.log('Executing modules');
    for (const module of loadedModules) {
      try {
        module.exports();
      } catch (err) {
        console.error(`Error executing module ${module.id}`, err);
      }
    }
  } catch (err) {
    console.error('Failed to load and execute modules', err);
  }
}

main().then(() => {
  console.log('Done');
}).catch((err) => {
  console.error('Error executing program', err);
});
