};

void insertAfterTarget(forward_list<string>& list, const string& targetString, const string& replacementString, bool caseInsensitive = false) {
    // Error handling for invalid input parameters
    if (list.empty() || targetString.empty() || replacementString.empty()) {
        throw invalid_argument("Invalid input parameters");
    }

    // Lock the forward list to prevent concurrent modifications
    std::lock_guard<std::mutex> lock(listMutex);

    // Find the first occurrence of the target string
    auto it = find(list.begin(), list.end(), targetString, [caseInsensitive](const string& s1, const string& s2) {
        if (caseInsensitive) {
            return regex_match(s1, regex(s2, regex::icase));
        } else {
            return s1 == s2;
        }
    });

    // If the target string is not found, insert at the end of the list
    if (it == list.end()) {
        it = list.insert_after(list.before_end(), replacementString);
    } else {
        // Insert the replacement string after the first occurrence of the target string
        it = list.insert_after(it, replacementString);
    }

    // Log each insertion operation for debugging and auditing purposes
    InsertionLog log;
    log.targetString = targetString;
    log.replacementString = replacementString;
    log.caseInsensitive = caseInsensitive;
    insertionLogs.push_back(log);

    // Integrate with an external database to store the modified list for future reference
    integrateWithDatabase();
}

