int log_service_api(const char*);

// Global variables
sem_t sem; // Semaphore to synchronize access to the shared data structure
int num_files = 0; // Number of log files to process
char **file_names; // Array of file names to process
log_line_t *lines; // Array of lines from each file
int *file_lengths; // Array of file lengths for each line
int *line_numbers; // Array of line numbers for each file
int *errors; // Array of error codes for each file

// Function to process a log file concurrently
void* process_log_file(void* args) {
    int i = (int)args;
    char *file_name = file_names[i];
    int fd = open(file_name, O_RDONLY);
    if (fd == -1) {
        errors[i] = errno;
        return NULL;
    }
    while (1) {
        sem_wait(&sem);
        // Check for error code in shared data structure
        if (errors[i]) {
            break;
        }
        int line_length = file_lengths[i];
        char *line = lines[i];
        double average = 0.0;
        // Extract the last two numerical fields from the line
        for (int j = line_length - 1; j >= 0; j--) {
            if (isdigit(line[j])) {
                int num = atoi(&line[j]);
                average += num / 10.0;
                break;
            }
        }
        // Log the average to the external logging service
        log_service_api("average: %lf\n", average);
    }
    close(fd);
    return NULL;
}

// Function to read and process a log file
int read_and_process_log_file(char* file_name) {
    int fd = open(file_name, O_RDONLY);
    if (fd == -1) {
        return errno;
    }
    while (1) {
        sem_wait(&sem);
        // Check for error code in shared data structure
        if (errors[i]) {
            break;
        }
        int line_length = file_lengths[i];
        char *line = lines[i];
        double average = 0.0;
        // Extract the last two numerical fields from the line
        for (int j = line_length - 1; j >= 0; j--) {
            if (isdigit(line[j])) {
                int num = atoi(&line[j]);
                average += num / 10.0;
                break;
            }
        }
        // Log the average to the external logging service
        log_service_api("average: %lf\n", average);
    }
    close(fd);
    return 0;
}

// Function to read and process all log files in a directory
void read_and_process_all_files() {
    // Iterate over the array of file names
    for (int i = 0; i < num_files; i++) {
        char *file_name = file_names[i];
        int error = read_and_process_log_file(file_name);
        if (error) {
            errors[i] = error;
        }
    }
}

int main(int argc, char* argv[]) {
    // Check command-line arguments
    if (argc < 3) {
        printf("Usage: %s [directory path] [logging service endpoint]\n", argv[0]);
        return 1;
    }

    // Initialize semaphore and array of file names
    sem_init(&sem, 0, 1);
    file_names = malloc(sizeof(char*) * 1000);
    lines = malloc(sizeof(log_line_t*) * 1000);
    file_lengths = malloc(sizeof(int)* 1000);
    line_numbers = malloc(sizeof(int) * 1000);
    errors = malloc(sizeof(int) * 1000);

    // Read and process all log files in the directory
    read_and_process_all_files();

    // Clean up resources
    sem_destroy(&sem);
    free(file_names);
    free(lines);
    free(file_lengths);
    free(line_numbers);
    free(errors);

    return 0;
}
