from dotenv import load_dotenv

def update_profile_picture(user, image):
    # Validate image file size and format
    if len(image) > 1000000 or not image.startswith('data:image'):
        raise ValueError('Invalid image file')

    # Cache updated profile picture for faster retrieval
    cache = {}
    cache['profile_picture'] = image
    os.environ['CACHE'] = json.dumps(cache)

    # Handle error conditions and retries for external API calls
    try:
        dao = ProfileDAO()
        dao.update_profile_picture(user, image)
    except Exception as e:
        print('Error updating profile picture:', e)
        return None

    # Support versioning to manage concurrent updates efficiently
    dao.versioning(user, image)

    # Integrate with external cloud storage service API for storing updated image
    try:
        storage = StorageService()
        storage.store_image(image)
    except Exception as e:
        print('Error storing image in cloud storage:', e)
        return None

    # Set environment variable to path of newly created directory
    dir_path = os.path.join(os.getenv('USER_DIR'), 'profile_pictures')
