        }
        Err(_) => {}
    };

    let mut dir_path = env_path;

    // Create new directory with given name if environment variable is not set
    if dir_path.is_none() {
        dir_path = Some(format!("{}/profile_pictures", os::getenv("USER_DIR")));

        // Set environment variable to path of newly created directory
        os::setenv("PROFILE_PICTURES", dir_path.unwrap());
    }

    return Ok(dir_path.unwrap());
}
```

