public class FileChunkProcessor
{
    private readonly object _syncRoot = new object();
    private int _bufferSize;
    private int _chunkSize;
    private Action<string> _loggingCallback;

    public FileChunkProcessor(int bufferSize, int chunkSize)
    {
        _bufferSize = bufferSize;
        _chunkSize = chunkSize;
    }

    public void SetLoggingCallback(Action<string> callback)
    {
        _loggingCallback = callback;
    }

    private async Task ProcessFileChunkAsync(string filePath, byte[] key, byte[] iv)
    {
        using (var fileStream = new FileStream(filePath, FileMode.Open))
        {
            var buffer = new byte[_bufferSize];
            var chunkCount = 0;
            while (fileStream.Position < fileStream.Length)
            {
                int bytesRead = await fileStream.ReadAsync(buffer, 0, _chunkSize);
                if (bytesRead == 0)
                    break;

                // Decrypt the chunk using Triple DES encryption
                var decryptedChunk = Decrypt(buffer, key, iv);

                // Process the decrypted chunk
                ProcessDecryptedChunk(decryptedChunk);

                ++chunkCount;
            }

            _loggingCallback?.Invoke($"Processed {chunkCount} chunks");
        }
    }

    private void Decrypt(byte[] buffer, byte[] key, byte[] iv)
    {
        var des = new TripleDESCryptoServiceProvider();
        var decryptedChunk = des.CreateDecryptor(key, iv).TransformFinalBlock(buffer, 0, _chunkSize);
        return decryptedChunk;
    }

    private void ProcessDecryptedChunk(byte[] decryptedChunk)
    {
        // TODO: Implement processing logic for the decrypted chunk here.
    }

    public Task DecryptFileAsync(string filePath, byte[] key, byte[] iv)
    {
        return Task.Run(() => ProcessFileChunkAsync(filePath, key, iv));
    }
}
