```c
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_DNS_SERVERS 10
#define DNS_PORT 53
#define DNS_TIMEOUT 2
#define DNS_RETRY_DELAY 2
#define LOG_FILE "dns_resolver.log"
#define RATE_LIMIT 100

// DNS record types
enum dns_record_type {
    A,
    MX,
    AAAA,
    CNAME,
};

// DNS server status
struct dns_server_status {
    bool available;
    time_t last_check_time;
};

// DNS cache entry
struct dns_cache_entry {
    char* hostname;
    in_addr ipv4;
    in6_addr ipv6;
    time_t expiry_time;
};

// DNS resolver context
struct dns_resolver_ctx {
    int sockfd;
    bool initialized;
    bool verbose;
    size_t num_dns_servers;
    struct sockaddr_in* dns_servers[MAX_DNS_SERVERS];
    time_t last_check_time;
    char** supplementary_records;
};

// Initialize the DNS resolver context
struct dns_resolver_ctx* dns_resolver_init(bool verbose) {
    struct dns_resolver_ctx* ctx = malloc(sizeof(struct dns_resolver_ctx));
    if (!ctx) {
        return NULL;
    }
    ctx->sockfd = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP);
    if (ctx->sockfd < 0) {
        free(ctx);
        return NULL;
    }
    ctx->initialized = true;
    ctx->verbose = verbose;
    ctx->num_dns_servers = 0;
    ctx->last_check_time = time(NULL);
    for (int i = 0; i < MAX_DNS_SERVERS; i++) {
        ctx->dns_servers[i] = NULL;
    }
    return ctx;
}

// Add a DNS server to the resolver context
bool dns_resolver_add_server(struct dns_resolver_ctx* ctx, const char* server) {
    if (ctx->num_dns_servers >= MAX_DNS_SERVERS) {
        return false;
    }
    struct sockaddr_in* addr = malloc(sizeof(struct sockaddr_in));
    if (!addr) {
        return false;
    }
    memset(addr, 0, sizeof(struct sockaddr_in));
    addr->sin_family = AF_INET;
    addr->sin_port = htons(DNS_PORT);
    if (inet_pton(AF_INET, server, &addr->sin_addr) <= 0) {
        free(addr);
        return false;
    }
    ctx->dns_servers[ctx->num_dns_servers++] = addr;
    return true;
}

// Remove a DNS server from the resolver context
bool dns_resolver_remove_server(struct dns_resolver_ctx* ctx, const char* server) {
    for (int i = 0; i < MAX_DNS_SERVERS; i++) {
        if (ctx->dns_servers[i] &&
            inet_pton(AF_INET, server, &ctx->dns_servers[i]->sin_addr) > 0) {
            free(ctx->dns_servers[i]);
            ctx->dns_servers[i] = NULL;
            return true;
        }
    }
    return false;
}

// Check the status of a DNS server
struct dns_server_status* dns_resolver_check_server(struct dns_resolver_ctx* ctx, const char* server) {
    struct dns_server_status* status = malloc(sizeof(struct dns_server_status));
    if (!status) {
        return NULL;
    }
    memset(status, 0, sizeof(struct dns_server_status));
    status->available = true;
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(struct sockaddr_in));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(DNS_PORT);
    if (inet_pton(AF_INET, server, &addr.sin_addr) <= 0) {
        status->available = false;
    } else {
        struct timeval timeout = { DNS_TIMEOUT, 0 };
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(ctx->sockfd, &readfds);
        if (select(ctx->sockfd + 1, &readfds, NULL, NULL, &timeout) > 0 &&
            FD_ISSET(ctx->sockfd, &readfds)) {
            status->available = true;
        } else {
            status->available = false;
        }
    }
    return status;
}

// Perform a DNS query
bool dns_resolver_query(struct dns_resolver_ctx* ctx, const char* hostname, in_addr* ipv4) {
    struct timeval timeout = { DNS_TIMEOUT, 0 };
    fd_set readfds;
    FD_ZERO(&readfds);
    FD_SET(ctx->sockfd, &readfds);
    if (select(ctx->sockfd + 1, &readfds, NULL, NULL, &timeout) <= 0 ||
        !FD_ISSET(ctx->sockfd, &readfds)) {
        return false;
    }
    char buffer[512];
    memset(&buffer, 0, sizeof(buffer));
    sprintf(buffer, "GET %s HTTP/1.1\r\nHost: %s\r\n", hostname, hostname);
    if (sendto(ctx->sockfd, buffer, strlen(buffer), MSG_CONFIRM,
               (const struct sockaddr*) &ctx->dns_servers[0], sizeof(struct sockaddr)) < 0) {
        return false;
    }
    memset(&buffer, 0, sizeof(buffer));
    if (recvfrom(ctx->sockfd, buffer, sizeof(buffer), MSG_WAITALL, NULL, NULL) <= 0) {
        return false;
    }
    char* ip = strtok(buffer, " ");
    while (ip) {
        char* colon = strrchr(ip, ':');
        if (colon && strcmp(colon + 1, "A") == 0) {
            *ipv4 = inet_addr(ip);
            return true;
        }
        ip = strtok(NULL, " ");
    }
    return false;
}

// Perform a DNS query with a specific DNS server
bool dns_resolver_query_server(struct dns_resolver_ctx* ctx, const char* hostname, in_addr* ipv4) {
    for (int i = 0; i < MAX_SERVERS; i++) {
        if (ctx->dns_servers[i] &&
            strcmp(hostname, &ctx->dns_servers[i]->sin_addr) == 0) {
            return true;
        }
    }
    return false;
}

// Perform a DNS query with a specific DNS server
bool dns_resolver_query_server_ipv6(struct dns_resolver_ctx* ctx, const char* hostname, in6_addr* ipv6) {
    for (int i = 0; i < MAX_SERVERS; i++) {
        if (ctx->dns_servers[i] &&
            strcmp(hostname, &ctx->dns_servers[i]->sin_addr) == 0) {
            return true;
        }
    }
    return false;
}

// Resolve a hostname to an IPv4 address
bool dns_resolver_resolve(struct dns_resolver_ctx* ctx, const char* hostname, in_addr* ipv4) {
    struct dns_server_status* status = dns_resolver_check_server(ctx, hostname);
    if (status->available) {
        return dns_resolver_query(ctx, hostname, ipv4);
    } else {
        return false;
    }
}

// Resolve a hostname to an IPv6 address
bool dns_resolver_resolve_ipv6(struct dns_resolver_ctx* ctx, const char* hostname, in6_addr* ipv6) {
    struct dns_server_status* status = dns_resolver_check_server(ctx, hostname);
    if (status->available) {
        return dns_resolver_query(ctx, hostname, ipv6);
    } else {
        return false;
    }
}

// Resolve a hostname to an IP address
bool dns_resolver_resolve_any(struct dns_resolver_ctx* ctx, const char* hostname, in_addr* ip) {
    struct dns_server_status* status = dns_resolver_check_server(ctx, hostname);
    if (status->available) {
        return dns_resolver_query(ctx, hostname, ip);
    } else {
        return false;
    }
}

// Get the DNS server status
struct dns_server_status* dns_resolver_get_dns_server_status(struct dns_resolver_ctx* ctx) {
    struct dns_server_status* status = malloc(sizeof(struct dns_server_status));
    memset(status, 0, sizeof(struct dns_server_status));
    for (int i = 0; i < MAX_SERVERS; i++) {
        if (ctx->dns_servers[i]) {
            status->available = true;
        } else {
            status->unavailable++;
        }
    }
    return status;
}
```

This code implements a DNS resolver with multiple servers support and basic query handling. The `dns_resolver_init()` function initializes the DNS resolver context, which is used for all subsequent DNS queries. The `dns_resolver_add_server()` function adds a new DNS server to the list of available servers. The `dns_resolver_remove_server()` function removes a DNS server from the list of available servers. The `dns_resolver_check_server()` function checks the status of a DNS server, i.e., whether it is available or not. The `dns_resolver_query()` function performs a DNS query and returns the IP address of the hostname provided. The `dns_resolver_resolve()` function performs a DNS query with a specific DNS server. The `dns_resolver_resolve_ipv6()` function performs a DNS query with a specific DNS server for an IPv6 address. The `dns_resolver_resolve_any()` function performs a DNS query with a specific DNS server for any type of address (IPv4, IPv6 or both). Finally, the `dns_resolver_get_dns_server_status()` function returns the status of all available DNS servers.

