function renderFooter(scripts) {
  // Create an empty string to store the rendered HTML
  let html = "";

  // Iterate over each script object in the array
  scripts.forEach((script) => {
    // Check if the script has a `code` and `type` property
    if (script.code && script.type) {
      // Create a `<script>` tag with the unique key and innerHTML set to the script's code
      const tag = document.createElement("script");
      tag.setAttribute("key", script.key);
      tag.innerHTML = script.code;

      // Add the tag to the HTML string
      html += `${tag}`;
    } else {
      console.error(`Missing essential properties for script with key ${script.key}`);
    }
  });

  return html;
}
