```csharp
using System.Data;
using System.Data.SqlClient;
using System.Collections.Generic;

public static IDataReader ExecuteQuery(List<string> values, SqlConnection connection, string query) {
  // Create a new instance of the SqlCommand class
  var command = new SqlCommand(query, connection);

  // Parameterize the SQL command with the list of values
  for (int i = 0; i < values.Count; i++) {
    command.Parameters.AddWithValue($"@value{i}", values[i]);
  }

  // Execute the query and return an IDataReader object
  try {
    return command.ExecuteReader();
  } catch (SqlException ex) {
    Console.WriteLine(ex.Message);
    return null;
  }
}
