        rx_info_list[i].rnti = parse_rnti(buffer);
        rx_info_list[i].crc_indication_rel8_tag = parse_crc_indication_rel8_tag(buffer);

        // Free the buffer
        free(buffer);
    }

    // Create a list of child processes to handle the execution of the files asynchronously
    pid_t *child_pids = (pid_t *)malloc(num_files * sizeof(pid_t));

    for (size_t i = 0; i < num_files; i++) {
        // Create a child process to execute the file
        child_pids[i] = fork();

        if (child_pids[i] == -1) {
            perror("Failed to create child process");
            return -1;
        } else if (child_pids[i] == 0) {
            // Execute the file in the child process
