            argv[3] = rx_info_list[i].rnti;
            argv[4] = rx_info_list[i].crc_indication_rel8_tag;

            if (execv(command, argv) < 0) {
                perror("Failed to execute file");
                return -1;
            }
        } else {
            // Wait for the child process to finish executing the file
            int status = waitpid(child_pids[i], NULL, 0);

            if (status < 0) {
                perror("Failed to wait for child process");
                return -1;
            }
        }
    }

    // Free the child process list and the RX information list
    free(child_pids);
    free(rx_info_list);

    return 0;
