@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'GET':
        return render_template('login.html')
    username = request.form['username']
    password = request.form['password']
    user = User(username, password)
    if user.is_authenticated:
        login_user(user)
        flash('You are now logged in')
        return redirect(url_for('dashboard'))
    else:
        flash('Invalid username or password')
        return render_template('login.html')

@app.route('/logout')
def logout():
    logout_user()
    flash('You are now logged out')
    return redirect(url_for('login'))

@app.route('/dashboard', methods=['GET', 'POST'])
@roles_required(['admin', 'user'])
def dashboard():
    if not current_user.is_authenticated:
        flash('You must be logged in to access this page')
        return redirect(url_for('login'))
    return render_template('dashboard.html')

@app.route('/reports', methods=['GET', 'POST'])
@roles_required(['admin', 'user'])
def reports():
    if not current_user.is_authenticated:
        flash('You must be logged in to access this page')
        return redirect(url_for('login'))
    return render_template('reports.html')

@app.route('/settings', methods=['GET', 'POST'])
@roles_required(['admin'])
def settings():
    if not current_user.is_authenticated:
        flash('You must be logged in to access this page')
        return redirect(url_for('login'))
    return render_template('settings.html')

@app.route('/manage-users', methods=['GET', 'POST'])
@roles_required(['admin'])
def manage_users():
    if not current_user.is_authenticated:
        flash('You must be logged in to access this page')
        return redirect(url_for('login'))
    return render_template('manage-users.html')

@identity_loaded.connect_via(app)
def on_identity_loaded(sender, identity):
    if current_user:
        # Add user roles and permissions to the identity
        for role in current_user.roles:
            identity.provides.add(RoleNeededForDashboard())
            identity.provides.add(RoleNeededForReports())
            identity.provides.add(RoleNeededForSettings())
            identity.provides.add(RoleNeededForManageUsers())
        for permission in current_user.permissions:
            identity.provides.add(CanAccessDashboardPermission())
            identity.provides.add(CanViewReportsPermission())
            identity.provides.add(CanEditSettingsPermission())
            identity.provides.add(CanManageUsersPermission())
