#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>

// Constants
#define MAX_FILENAME_LEN 256
#define MAX_LINE_LENGTH 1024
#define NUM_WORKER_THREADS 8
#define QUEUE_SIZE 1024

// Structures
typedef struct {
    char *filename;
    size_t file_size;
} logfile_info_t;

typedef struct {
    int line_num;
    char *line;
} logline_t;

// Global variables
sem_t sem;
int num_files = 0;
logfile_info_t *logfile_list = NULL;
pthread_mutex_t lock;
pthread_cond_t cond;

// Function declarations
void process_logfile(const char *filename);
void *process_line(void *data);
int read_line(FILE *fp, logline_t *line);
double calculate_average(const char *str);

int main(int argc, char **argv) {
    // Initialize semaphore and mutex
    sem_init(&sem, 0, num_files);
    pthread_mutex_init(&lock, NULL);
    pthread_cond_init(&cond, NULL);

    // Parse command-line arguments
    if (argc < 3) {
        printf("Usage: %s <directory> <external logging service endpoint>\n", argv[0]);
        return 1;
    }
    char *directory = argv[1];
    char *endpoint = argv[2];

    // Build list of log files in directory
    num_files = 0;
    DIR *dir = opendir(directory);
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strstr(entry->d_name, ".log") != NULL) {
            num_files++;
        }
    }
    logfile_list = malloc(num_files * sizeof(logfile_info_t));
    int i = 0;
    rewinddir(dir);
    while ((entry = readdir(dir)) != NULL) {
        if (strstr(entry->d_name, ".log") != NULL) {
            logfile_list[i].filename = malloc(MAX_FILENAME_LEN);
            strncpy(logfile_list[i].filename, entry->d_name, MAX_FILENAME_LEN);
            logfile_list[i].file_size = 0;
            i++;
        }
    }
    closedir(dir);

    // Initialize worker threads
    pthread_t workers[NUM_WORKER_THREADS];
    for (int i = 0; i < NUM_WORKER_THREADS; i++) {
        if (pthread_create(&workers[i], NULL, process_line, NULL) != 0) {
            fprintf(stderr, "Error creating worker thread\n");
            return 1;
        }
    }

    // Process log files concurrently
    for (int i = 0; i < num_files; i++) {
        sem_wait(&sem);
        pthread_mutex_lock(&lock);
        process_logfile(logfile_list[i].filename);
        pthread_cond_signal(&cond);
        pthread_mutex_unlock(&lock);
    }

    // Wait for worker threads to finish
    for (int i = 0; i < NUM_WORKER_THREADS; i++) {
        void *status;
        pthread_join(workers[i], &status);
    }

    // Clean up resources
    sem_destroy(&sem);
    pthread_mutex_destroy(&lock);
    pthread_cond_destroy(&cond);
    return 0;
}

void process_logfile(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening file");
        exit(1);
    }

    // Memory-map the file to improve performance with large files
    struct stat st;
    fstat(fileno(fp), &st);
    size_t file_size = st.st_size;
    void *mapped_file = mmap(NULL, file_size, PROT_READ, MAP_PRIVATE, fileno(fp), 0);

    // Process lines in the file concurrently
    logline_t line;
    while (read_line(fp, &line)) {
        sem_wait(&sem);
        pthread_mutex_lock(&lock);
        double average = calculate_average(line.line);
        // Send data to external logging service API
        if (average > 0) {
            // Logging code goes here
        }
        free(line.line);
        pthread_cond_signal(&cond);
        pthread_mutex_unlock(&lock);
    }

    // Clean up memory-mapped file
    munmap(mapped_file, file_size);

    // Close the file
    fclose(fp);
}

void *process_line(void *data) {
    while (1) {
        sem_wait(&sem);
        pthread_mutex_lock(&lock);
        logfile_info_t *logfile = logfile_list[0];
        FILE *fp = fopen(logfile->filename, "r");
        if (fp == NULL) {
            perror("Error opening file");
            exit(1);
        }
        // Memory-map the file to improve performance with large files
        struct stat st;
        fstat(fileno(fp), &st);
        size_t file_size = st.st_size;
        void *mapped_file = mmap(NULL, file_size, PROT_READ, MAP_PRIVATE, fileno(fp), 0);

        // Process lines in the file concurrently
        logline_t line;
        while (read_line(fp, &line)) {
            double average = calculate_average(line.line);
            // Send data to external logging service API
            if (average > 0) {
                // Logging code goes here
            }
            free(line.line);
        }

        // Clean up memory-mapped file
        munmap(mapped_file, file_size);

        // Close the file
        fclose(fp);

        // Remove the logfile from the list
        for (int i = 1; i < num_files; i++) {
            logfile_list[i - 1] = logfile_list[i];
        }
        num_files--;

        pthread_cond_signal(&cond);
        pthread_mutex_unlock(&lock);
    }
}

int read_line(FILE *fp, logline_t *line) {
    // Read a line from the file and parse it
    char buffer[1024];
    fgets(buffer, 1024, fp);
    if (ferror(fp)) {
        perror("Error reading file");
        exit(1);
    }
    // Parse the line and extract the relevant data
    char *token = strtok(buffer, " ");
    while (token != NULL) {
        int value = atoi(token);
        if (value > 0) {
            line->average = average;
            break;
        }
        token = strtok(NULL, " ");
    }
}

double calculate_average(char *line) {
    // Parse the line and calculate the average value
    int sum = 0;
    char *token = strtok(line, ",");
    while (token != NULL) {
        int value = atoi(token);
        if (value > 0) {
            sum += value;
        }
        token = strtok(NULL, ",");
    }
    return sum / num_values;
}

