                var xmlDocument = new XmlDocument();
                xmlDocument.LoadXml(request.HtmlContent);
                var validationResult = new List<ValidationResult>();
                xmlSchemaSet.Add("http://www.w3.org/2001/XMLSchema", "XMLSchema.xsd");
                var schemaValidator = new XmlSchemaValidator(xmlSchemaSet, validationResult);
                schemaValidator.Validate(xmlDocument);

