                {
                    return BadRequest($"Invalid HTML content: {String.Join(", ", validationResult)}");
                }

                // Update the element's HTML content using a service class
                await _elementService.UpdateElementHtmlAsync(request.PageId, request.ElementId, request.HtmlContent);

                // Log the changes to an external audit system
