import re
import json

def extract_book_titles(text, min_count=1):
    titles = {}
    for title in re.findall(r'\b[A-Z][a-z]+[A-Z][a-z]*\b', text):
        if not is_punctuation(title):
            if is_book_in_database(title):
                titles[title] = titles.get(title, 0) + 1
    return titles

def is_punctuation(word):
    for char in word:
        if not char.isalpha():
            return True
    return False

def is_book_in_database(title):
