        response = json.loads(requests.get('https://api.example.com/books', params={'title': title}).text)
        if response['success'] and len(response['data']) > 0:
            return True
        else:
            return False
    except requests.exceptions.RequestException:
        return False

def filter_titles(titles, min_count):
    filtered_titles = {}
    for title in titles:
        if titles[title] >= min_count:
            filtered_titles[title] = titles[title]
    return filtered_titles
