from flask_login import LoginManager
from flask_principal import Principal
from flask import Flask, redirect, url_for, session, request
import dao

app = Flask(__name__)
login_manager = LoginManager()
login_manager.init_app(app)
principal = Principal(app)

@app.route('/login', methods=['POST'])
def login():
    username = request.form['username']
    password = request.form['password']
    user = dao.authenticate(username, password)
    if user is None:
        return redirect(url_for('index'))
    session['user_id'] = user.id
    session['user_name'] = user.name
    principal.set_identity(user)
    return redirect(url_for('index'))

@app.route('/logout')
def logout():
    session.clear()
    return redirect(url_for('index'))

@app.route('/index')
def index():
    if 'user_id' not in session:
        return redirect(url_for('login'))
    user = dao.get_user_by_id(session['user_id'])
    return render_template('index.html', user=user)

@app.route('/profile', methods=['POST', 'GET'])
def profile():
    if request.method == 'POST':
        # Update profile picture
        file = request.files['file']
        if file and allowed_file(file.filename):
            filename = secure_filename(file.filename)
            dao.update_profile_picture(session['user_id'], filename)
        return redirect(url_for('index'))
    else:
        # Display profile picture
        user = dao.get_user_by_id(session['user_id'])
        return render_template('profile.html', user=user, picture=user.picture)

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def secure_filename(filename):
    return filename.replace(' ', '_')

@app.route('/api/v1/users/<int:user_id>/profile_picture', methods=['GET'])
def get_profile_picture(user_id):
    user = dao.get_user_by_id(user_id)
    if user is None:
        return 'User not found', 404
    return send_file(user.picture, attachment_filename=user.name + '_profile_picture')
```
