public static class DatabaseHelper {
    private const int BUFFER_SIZE = 4096;

    public async Task<List<CustomObject>> ExecuteStoredProcedureAsync(
        SqlConnection connection, string spName, List<SqlParameter> parameters)
    {
        // Create a new list to store the custom objects
        var result = new List<CustomObject>();

        // Set up the command object with the stored procedure name and input parameters
        using (var cmd = new SqlCommand(spName, connection)) {
            // Add the input parameters to the command object
            foreach (var parameter in parameters) {
                cmd.Parameters.Add(parameter);
            }

            // Set up the reader for the stored procedure results
