    private $rateLimiter;
    private $dbConnection;

    public function __construct(LoggerInterface $logger, RateLimiterInterface $rateLimiter, PDO $dbConnection) {
        $this->logger = $logger;
        $this->rateLimiter = $rateLimiter;
        $this->dbConnection = $dbConnection;
    }

    public function updateClinicStatus(int $clinicId, string $newStatus): bool {
        if (!$this->validateClinicId($clinicId)) {
            return false;
        }

        $lastModifiedIp = $_SERVER['REMOTE_ADDR'];
        $lastModifiedDate = new DateTime();

        try {
            // Start transaction
