            // Fetch and cache last modified information from external API
            $lastModifiedInfo = $this->fetchLastModifiedInformation($clinicId);

            // Update clinic status in database
            $updatedRows = $this->updateClinicStatusInDatabase($clinicId, $newStatus, $lastModifiedIp, $lastModifiedDate);

            // Commit transaction
            $this->dbConnection->commit();

            return $updatedRows > 0;
        } catch (Exception $e) {
            // Log error and roll back transaction
            $this->logger->error($e->getMessage());
            $this->dbConnection->rollBack();

            return false;
        }
    }

    private function validateClinicId(int $clinicId): bool {
        // Implement validation logic here
        return true;
    }

    private function fetchLastModifiedInformation(int $clinicId): ?array {
