        $lastModifiedInfo = [];
        try {
            $response = $this->sendRequestToExternalApi($clinicId);
            if ($response->isSuccessful()) {
                $lastModifiedInfo = $response->getBody()->getContents();
            }
        } catch (NetworkException $e) {
            // Log network error and return null
            $this->logger->error($e->getMessage());
            return null;
        } catch (TimeoutException $e) {
            // Log timeout error and return null
            $this->logger->error($e->getMessage());
            return null;
        } catch (UnexpectedResponseException $e) {
            // Log unexpected response error and return null
            $this->logger->error($e->getMessage());
            return null;
        }

        return $lastModifiedInfo;
    }

    private function updateClinicStatusInDatabase(int $clinicId, string $newStatus, string $lastModifiedIp, DateTime $lastModifiedDate): int {
        // Update clinic status in database
        $updatedRows = 0;
        try {
            $query = "UPDATE clinics SET status = :status, last_modified_ip = :lastModifiedIp, last_modified_date = :lastModifiedDate WHERE id = :clinicId";
            $statement = $this->dbConnection->prepare($query);
            $statement->bindValue(':status', $newStatus);
            $statement->bindValue(':lastModifiedIp', $lastModifiedIp);
            $statement->bindValue(':lastModifiedDate', $lastModifiedDate);
            $statement->bindValue(':clinicId', $clinicId);
            $updatedRows = $statement->execute();
        } catch (PDOException $e) {
            // Log database error and return 0
            $this->logger->error($e->getMessage());
            return 0;
        }

        return $updatedRows;
    }

    private function sendRequestToExternalApi(int $clinicId): ResponseInterface {
