public class VideoGameCharacter {
    private static final Logger LOGGER = Logger.getLogger(VideoGameCharacter.class.getName());
    private static final int COOLDOWN_SECONDS = 9;
    private static final Random RANDOM = new Random();

    public void selectAttack() {
        // Check if the cooldown has expired
        long currentTimeMillis = Instant.now().toEpochMilli();
        if (currentTimeMillis < lastAttackTimestamp + COOLDOWN_SECONDS * 1000) {
            LOGGER.log(Level.WARNING, "Cannot use attack yet, cooldown has not expired.");
            return;
        }

        // Select a random attack number between 1 and 2
        int attackNumber = RANDOM.nextInt(2) + 1;

        // Print the selected attack number to the console
        System.out.println("Selected attack: " + attackNumber);

        // Log the event in a remote logging service using a struct format
        Struct logStruct = new Struct();
        logStruct.put("attack_number", attackNumber);
        try {
            LOGGER.log(Level.INFO, MessageFormat.format("Attack selected: {0}", logStruct));
        } catch (IOException e) {
            LOGGER.log(Level.SEVERE, "Error logging attack selection.", e);
        }
    }

    private int lastAttackTimestamp;
}
