    if (access(input_path, R_OK) == -1) {
        printf("Error: Input file does not exist or cannot be read\n");
        return 0;
    }

    // Check if the cipher specified in the command line option is supported
    if (strcmp(cipher, "AES-256-CBC") != 0 && strcmp(cipher, "RSA-OAEP") != 0) {
        printf("Error: Specified cipher not supported\n");
        return 0;
    }

    // Return success if all input validations are successful
    return 1;
}

// Define the function to read the file in chunks and encrypt it using OpenSSL library
void encrypt_file(const char *input_path, const char *output_path, struct cipher_object *cipher) {
    // Open the input file for reading
    FILE *input = fopen(input_path, "r");

    // Check if the input file could not be opened
    if (input == NULL) {
        printf("Error: Input file could not be opened\n");
        return;
    }

    // Open the output file for writing
    FILE *output = fopen(output_path, "w");

    // Check if the output file could not be opened
    if (output == NULL) {
        printf("Error: Output file could not be opened\n");
        return;
    }

    // Define a buffer for reading and writing data in chunks
    char buffer[1024];

    // Define a variable to store the number of bytes read from the input file
    int bytes_read = 0;

    // Read the input file in chunks and encrypt it using the OpenSSL library
    while ((bytes_read = fread(buffer, sizeof(char), 1024, input)) > 0) {
        EVP_EncryptUpdate(cipher->ctx, buffer, bytes_read);
        fwrite(buffer, sizeof(char), bytes_read, output);
    }

    // Close the input and output files
    fclose(input);
    fclose(output);
}

// Define the function to handle encryption failures due to insufficient buffer sizes
void handle_encryption_failure(struct cipher_object *cipher) {
    printf("Error: Encryption failed due to insufficient buffer size\n");
    EVP_CIPHER_CTX_cleanup(cipher->ctx);
}

// Define the function to implement a progress callback function for notifying the user about the encryption process's status
void encrypt_progress_callback(struct cipher_object *cipher, long bytes) {
