struct key_storage *key_management(const char *key, size_t key_size) {
    // Allocate memory for the key storage structure
    struct key_storage *key_store = malloc(sizeof(struct key_storage));

    // Set the key and its size in the key storage structure
    key_store->key = key;
    key_store->key_size = key_size;

    return key_store;
}

