```
using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

namespace FileHasher
{
    public class FileHasher
    {
        private readonly ILogger _logger;

        public FileHasher(ILogger logger)
        {
            _logger = logger;
        }

        public async Task<string> ComputeFileHashAsync(string filePath, int chunkSize = 1024 * 1024)
        {
            using (var fileStream = new FileStream(filePath, FileMode.Open))
            {
                var hashAlgorithm = SHA256.Create();
                var hashBytes = await ComputeHashAsync(hashAlgorithm, fileStream, chunkSize);
                return BitConverter.ToString(hashBytes).Replace("-", string.Empty);
            }
        }

        private async Task<byte[]> ComputeHashAsync(HashAlgorithm hashAlgorithm, FileStream fileStream, int chunkSize)
        {
            try
            {
                var buffer = new byte[chunkSize];
                var totalBytesRead = 0;
                var totalBytesProcessed = 0;

                while (totalBytesRead < fileStream.Length)
                {
                    var bytesRead = await fileStream.ReadAsync(buffer, 0, chunkSize);
                    if (bytesRead == 0) break;

                    totalBytesRead += bytesRead;
                    totalBytesProcessed += hashAlgorithm.TransformBlock(buffer, 0, bytesRead, null, 0);
                }

                hashAlgorithm.TransformFinalBlock(buffer, 0, totalBytesProcessed);
                return hashAlgorithm.Hash;
            }
            catch (Exception ex)
            {
                _logger.LogError($"Failed to compute SHA-256 hash for file: {fileStream.Name}", ex);
                throw;
            }
        }
    }
}
```
This code creates a `FileHasher` class that provides an asynchronous method (`ComputeFileHashAsync`) to compute the SHA-256 hash of a file efficiently and with minimal memory usage. The class also handles large files by processing them in chunks, allowing for better performance and scalability. Additionally, the class integrates with an external logging service to record the hash computation time and any errors encountered during the process.

The `ComputeFileHashAsync` method takes two parameters: `filePath`, which is the path of the file to be hashed, and `chunkSize`, which is the size of the chunks to read from the file in bytes (defaults to 1 MiB). It uses an `ILogger` interface to log any errors that occur during the hashing process.

The method first opens the file using a `FileStream`. Then, it creates an instance of the `SHA256` class and passes it to the `ComputeHashAsync` method as a parameter. This method reads the contents of the file in chunks, passing each chunk to the `TransformBlock` method of the `SHA256` algorithm. The `TransformBlock` method updates the hash value for each chunk, while the `TransformFinalBlock` method finalizes the hash computation and returns the resulting hash value as a byte array.

The method then converts the hash bytes to a string representation using `BitConverter.ToString`, and returns the result. If an error occurs during the hashing process, the method logs it using the `ILogger` interface and throws an exception.

To ensure proper resource management and avoid leaks, the method uses the `using` statement with a `FileStream` object to dispose of it properly when it goes out of scope.

