// forward declaration of the function to be tested
void insert_after_first(const forward_list<string>& input, const string& target, const string& replacement, const fs::path& filePath);

// test cases for case-insensitive search and concurrent modifications
void test_case_insensitive_search() {
    // create a forward list of strings to be inserted into
    forward_list<string> input = {"Apple", "Orange", "Banana", "Mango"};

    // perform case-insensitive search for the target string
    auto it = find_if(input.begin(), input.end(), [](const string& s) { return icasecmp(s, "banana"); });

    // check that the iterator points to the correct position in the list
    assert(it != input.end() && *it == "Banana");
}

void test_concurrent_modifications() {
    // create a forward list of strings to be inserted into
    forward_list<string> input = {"Apple", "Orange", "Banana", "Mango"};

    // start two threads that concurrently modify the list
    thread t1([&input]() { input.push_front("Grape"); });
    thread t2([&input]() { input.insert_after(input.begin(), "Pear"); });

    // wait for both threads to finish
    t1.join();
    t2.join();

    // check that the list contains the correct elements
    assert(input == forward_list<string>{"Grape", "Apple", "Orange", "Banana", "Pear", "Mango"});
}

int main() {
    // test case for case-insensitive search
    test_case_insensitive_search();

    // test case for concurrent modifications
    test_concurrent_modifications();

    return 0;
}
