#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the maximum length of the new file name
#define MAX_LEN 256

// Function to modify the file's extension
void modify_extension(char* filename, char* new_ext) {
    // Get the original file name and its extension
    char* orig_filename = strtok(filename, ".");
    char* orig_ext = strrchr(orig_filename, '.');

    // Create a new string to store the modified file name
    char* new_filename = (char*)malloc(MAX_LEN);

    // Copy the original file name and append the new extension
    strcpy(new_filename, orig_filename);
    if (orig_ext != NULL) {
        strcat(new_filename, ".");
        strcat(new_filename, new_ext);
    } else {
        // If there is no original extension, append the new extension to the end of the file name
        strcat(new_filename, ".");
        strcat(new_filename, new_ext);
    }

    // Print the modified file name
    printf("Modified file name: %s\n", new_filename);
}
