use std::env;
use std::path::PathBuf;

// Function to create a new directory with a given name and set the environment variable
fn create_directory(dir_name: &str) {
    // Check if the environment variable is already set
    let env_var = env::var("MY_DIR");
    if !env_var.is_err() && env_var.unwrap() != "" {
        // If the environment variable is already set, use its existing value
        println!("Using existing directory: {}", env_var.unwrap());
    } else {
        // Create a new directory with the given name
        let mut path = PathBuf::from(dir_name);
        if !path.exists() {
            path.create_dir();
        }

        // Set the environment variable to the path of the newly created directory
        env::set_var("MY_DIR", &path.to_string());
    }
}
