class DynamicRandomStringGenerator {
    const DEFAULT_CHARSET = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    const DEFAULT_HASH_ALGO = 'sha512';

    private $charset;
    private $hashAlgo;
    private $seededRandom;

    public function __construct($charset = self::DEFAULT_CHARSET, $hashAlgo = self::DEFAULT_HASH_ALGO) {
        $this->charset = $charset;
        $this->hashAlgo = $hashAlgo;
        $this->seededRandom = new Random();
    }

    public function generateCustomRandomString($length, $seed = null) {
        if ($seed !== null) {
            $this->seededRandom->setSeed($seed);
        }

        $string = '';
        for ($i = 0; $i < $length; $i++) {
            $string .= $this->charset[mt_rand(0, strlen($this->charset) - 1)];
        }

        return $string;
    }

    public function hashPassword($password) {
        return password_hash($password, $this->hashAlgo);
