use std::collections::HashMap;
use std::process::exit;
use serde_json::Value;
use reqwest::{Client, Url};
use log::{Level, Record};

struct Config {
    functions: HashMap<String, FunctionConfig>,
}

struct FunctionConfig {
    function: String,
    settings: HashMap<String, String>,
}

struct FunctionResult {
    result: Value,
    error: Option<Value>,
}

struct HealthCheckEndpoint {
    status: String,
}

fn main() {
    let config_file = std::env::args().nth(1).unwrap();
    let config = read_config(&config_file);

    let mut functions = HashMap::new();
    for (name, function) in &config.functions {
        functions.insert(name.clone(), build_function(function));
    }

    let client = Client::new();

    // Start the health check endpoint
    let health_check_endpoint = HealthCheckEndpoint {
        status: "OK".to_string(),
    };

    loop {
        for (name, function) in &functions {
            match run_function(client.clone(), function) {
                Ok(result) => println!("{}", result),
                Err(error) => println!("Error running function: {}", error),
            }
        }
    }
}

fn read_config(file: &str) -> Config {
    let config = std::fs::read_to_string(file).unwrap();
    serde_json::from_str::<Config>(&config).unwrap()
}

fn build_function(config: &FunctionConfig) -> Function {
    Function {
        function: config.function.clone(),
        settings: config.settings.clone(),
    }
}

fn run_function(client: Client, function: &Function) -> Result<Value, Value> {
    let url = Url::parse(&format!("http://example.com/{}", function.function)).unwrap();
    let body = serde_json::to_string(&function.settings).unwrap();
    let request = client.post(url).body(body).build().unwrap();

    match client.execute(request).await {
        Ok(response) => {
            if response.status() != 200 {
                Err(Value::String("Invalid response status".to_string()))
            } else {
                let result = serde_json::from_str(&response.text().await.unwrap()).unwrap();
                Ok(result)
            }
        },
        Err(error) => {
            Err(Value::String(format!("Error executing request: {}", error)))
        }
    }
}

struct Function {
    function: String,
    settings: HashMap<String, String>,
}
