    public CompletableFuture<Void> connect(InetSocketAddress serverAddress) throws IOException {
        if (channel != null && channel.isOpen()) {
            return CompletableFuture.completedFuture(null);
        }

        channel = AsynchronousSocketChannel.open();
        LOGGER.info("Connecting to " + serverAddress.toString());
        return channel.connect(serverAddress).thenAccept(unused -> LOGGER.info("Connected!"));
    }

