// Structure to represent a record in the array
typedef struct {
    long offset;
    int key;
    double value;
} Record;

// Function to dynamically allocate memory for and initialize an array of records
Record* init_records(const char* config_file) {
    // Read initial offset and key values from configuration file
    FILE* fp = fopen(config_file, "r");
    if (fp == NULL) {
        printf("Error: unable to open configuration file %s\n", config_file);
        return NULL;
    }

    // Read offset and key values from configuration file
    long initial_offset = 0;
    int initial_key = 0;
    if (fscanf(fp, "%ld %d", &initial_offset, &initial_key) != 2) {
        printf("Error: unable to read offset and key values from configuration file\n");
        fclose(fp);
        return NULL;
    }

    // Close the configuration file
    fclose(fp);

    // Dynamically allocate memory for the arrays of records
    Record* records = (Record*)malloc(sizeof(Record) * initial_offset);
    if (records == NULL) {
        printf("Error: unable to allocate memory for record array\n");
        return NULL;
    }

    // Initialize the offset and key values in the arrays
    for (int i = 0; i < initial_offset; i++) {
        records[i].offset = initial_offset;
        records[i].key = initial_key;
    }

    // Set the value of each record's double field to a random value within a given range
    srand(time(NULL));
    for (int i = 0; i < initial_offset; i++) {
        records[i].value = (double)rand() / RAND_MAX * 10.0 - 5.0;
    }

    return records;
}

// Function to free memory allocated for the arrays of records
void free_records(Record* records) {
    if (records != NULL) {
        free(records);
    }
}

int main() {
    // Initialize an array of records using the init_records function
    Record* records = init_records("config.txt");
    if (records == NULL) {
        printf("Error: unable to initialize record array\n");
        return 1;
    }

    // Print the contents of the arrays
    for (int i = 0; i < initial_offset; i++) {
        printf("%ld %d %.2f\n", records[i].offset, records[i].key, records[i].value);
    }

    // Free memory allocated for the arrays
    free_records(records);

    return 0;
}

