typedef struct {
  RX_UE_INFORMATION_TAG rx_ue_information;
  uint16_t rnti;
  CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

int generateNFAPduList(int num_pdus, NFAPI_CRC_INDICATION_PDU_T **pdu_list, uint32_t *checksum) {
  // Check input parameters
  if (num_pdus <= 0 || pdu_list == NULL || checksum == NULL) {
    return -1;
  }

  // Allocate memory for the list of PDUs
  NFAPI_CRC_INDICATION_PDU_T *pdu_list_ptr = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
  if (pdu_list_ptr == NULL) {
    return -2;
  }

  // Initialize the list of PDUs
  for (int i = 0; i < num_pdus; i++) {
    pdu_list_ptr[i].rx_ue_information = /* valid RX_UE_INFORMATION_TAG */;
    pdu_list_ptr[i].rnti = /* valid RNTI */;
    pdu_list_ptr[i].crc_indication_rel8.crflag = (uint8_t) rand() % 2;
  }

  // Calculate the checksum of all CRCFLAG values in the list
  uint32_t crc_checksum = 0;
  for (int i = 0; i < num_pdus; i++) {
    crc_checksum += pdu_list_ptr[i].crc_indication_rel8.crflag;
  }

  // Store the checksum in the output parameter
  *checksum = crc_checksum;

  // Return the list of PDUs
  *pdu_list = pdu_list_ptr;
  return 0;
}
