// C function to dynamically load and execute multiple JavaScript files in the context of a web page
void dynamic_load_and_execute_files(const char* file_paths[], int num_files) {
    // create list of NFAPI_CRC_INDICATION_PDU_T structures
    struct NFAPI_CRC_INDICATION_PDU_T *crc_indications = malloc(num_files * sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_indications) {
        printf("Failed to allocate memory for CRC indications\n");
        return;
    }

    // populate list with valid RX_UE_INFORMATION_TAG and RNTI, as well as a randomly set CRCFLAG
    for (int i = 0; i < num_files; i++) {
        struct NFAPI_CRC_INDICATION_PDU_T *crc_indication = &crc_indications[i];
        crc_indication->rx_ue_information_tag = 1234; // set to a valid value
        crc_indication->rnti = rand(); // set to a random RNTI
        crc_indication->crc_indication_rel8_tag.crcflag = (rand() % 2) ? 1 : 0; // randomly set CRCFLAG
    }

    // load and execute files asynchronously, handling errors gracefully
    for (int i = 0; i < num_files; i++) {
        const char* file_path = file_paths[i];
        FILE *file = fopen(file_path, "r");
        if (!file) {
            printf("Failed to open file %s\n", file_path);
            continue;
        }

        char buffer[4096];
        size_t bytes_read = fread(buffer, 1, sizeof(buffer), file);
        if (bytes_read == 0) {
            printf("Failed to read from file %s\n", file_path);
            continue;
        }

        // execute loaded file
        int result = run_file(file_path, buffer, bytes_read);
        if (result != 0) {
            printf("Error executing file %s: %d\n", file_path, result);
        }
    }
}
