// JavaScript function to copy a specified number of bytes from a list of buffered data chunks and return the copied data in a new buffer
const copyBytesFromChunks = (chunks, startIndex, endIndex) => {
    // handle invalid arguments
    if (!Array.isArray(chunks) || !Number.isInteger(startIndex) || !Number.isInteger(endIndex)) {
        throw new Error('Invalid argument(s)');
    }

    // calculate total size of data to be copied
    let totalSize = 0;
    for (let i = startIndex; i <= endIndex; i++) {
        totalSize += chunks[i].length;
    }

    // create new buffer and copy data from chunks
    const copiedData = Buffer.alloc(totalSize);
    let copiedBytes = 0;
    for (let i = startIndex; i <= endIndex; i++) {
        const chunk = chunks[i];
        if (!Buffer.isBuffer(chunk)) {
            throw new Error('Invalid data chunk');
        }

        // copy data from chunk to copied buffer
        const bytesToCopy = Math.min(copiedBytes + chunk.length, totalSize) - copiedBytes;
        chunk.copy(copiedData, copiedBytes, 0, bytesToCopy);
        copiedBytes += bytesToCopy;
    }

    return copiedData;
};
