using System;
using UnityEngine;

public class DynamicRandomValueGenerator
{
    private float minValue;
    private float maxValue;

    public DynamicRandomValueGenerator(float minValue, float maxValue)
    {
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public float NextFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public int NextInt()
    {
        return (int)UnityEngine.Random.Range(minValue, maxValue + 1);
    }

    public float NextFloat(Func<float, bool> distribution)
    {
        return distribution((float)UnityEngine.Random.Range(minValue, maxValue));
    }

    public int NextInt(Func<int, bool> distribution)
    {
        return (int)distribution((int)UnityEngine.Random.Range(minValue, maxValue + 1));
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}] (Distribution: Type)";
    }
}
