function FindElementsBySelector(node, selector, callback) {
    if (!node || !selector) {
        throw new Error("Invalid input parameters");
    }

    let elements = [];

    // Traverse the DOM tree without recursion
    for (let child of node.childNodes) {
        if (child.matches(selector)) {
            elements.push(child);
        }

        elements.concat(FindElementsBySelector(child, selector));
    }

    return elements;
}
