```
using System;
using System.Xml.XPath;
using System.Xml.Schema;
using System.Collections.Generic;
using System.Linq;
using System.Threading;

namespace XMLParsing
{
    public class XMLParser
    {
        private static readonly Dictionary<string, XDocument> cache = new Dictionary<string, XDocument>();

        public static XElement ParseXML(string xmlPath, string xpathQuery)
        {
            if (!File.Exists(xmlPath))
            {
                throw new FileNotFoundException("Could not find XML file at the specified path.", xmlPath);
            }

            // Load XML document from disk using XDocument
            XDocument doc = null;
            bool cacheHit = false;

            lock (cache)
            {
                if (cache.ContainsKey(xmlPath))
                {
                    cacheHit = true;
                    doc = cache[xmlPath];
                }
            }

            if (!cacheHit)
            {
                // Load XML document from disk and validate against schema using XSD schema validation
                try
                {
                    doc = XDocument.Load(xmlPath);
                    ValidateXMLSchema(doc, xmlPath);
                }
                catch (Exception e)
                {
                    throw new Exception("Error loading XML file or validating against schema", e);
                }

                // Cache the document for future use
                lock (cache)
                {
                    cache[xmlPath] = doc;
                }
            }

            // Parse XML using XPath query and return first matching element
            var navigator = doc.CreateNavigator();
            var xpathResult = navigator.Select(xpathQuery);

            if (xpathResult != null && xpathResult.Count > 0)
            {
                foreach (XElement element in xpathResult)
                {
                    return element;
                }
            }
            else
            {
                throw new Exception("No element found with the specified name");
            }
        }

        private static void ValidateXMLSchema(XDocument doc, string xmlPath)
        {
            // Load schema from disk using XmlSchemaSet
            XmlReader reader = File.OpenText(xmlPath);
            var schemaSet = new XmlSchemaSet();
            schemaSet.Add("http://www.w3.org/2001/XMLSchema", reader);

            try
            {
                // Validate document against schema using XDocument's SchemaValidated property
                doc.Schemas = schemaSet;
                doc.Validate(out Exception[] exceptions);

                if (exceptions != null && exceptions.Length > 0)
                {
                    throw new XmlSchemaValidationException("Error validating XML file against schema", exceptions[0]);
                }
            }
            catch (Exception e)
            {
                throw new Exception("Error validating XML file against schema", e);
            }
        }
    }
}
```
