use std::env;
use std::fs;
use std::thread;
use std::time::Duration;

fn main() {
    let mut dir_path = env::var("MY_DIR_PATH").unwrap_or_else(|_| String::from("/tmp/my_dir"));
    if !dir_path.is_empty() && fs::metadata(dir_path).is_err() {
        println!("Environment variable MY_DIR_PATH points to a non-existent directory, creating a new one");
        dir_path = create_new_dir(&dir_path);
    }

    let mut cleanup_timer: Option<thread::JoinHandle<()>> = None;
    if fs::metadata(dir_path).is_ok() {
        // Start a background thread to clean up the directory after 10 minutes
        cleanup_timer = Some(thread::spawn(move || {
            let mut last_cleanup = Instant::now();
            loop {
                if last_cleanup.elapsed() >= Duration::from_secs(600) {
                    match fs::metadata(&dir_path) {
                        Ok(_) => (),
                        Err(_) => break,
                    }
                }
                thread::sleep(Duration::from_secs(10));
            }
        }));
    }

    // Set the environment variable to the path of the newly created or used directory
    env::set_var("MY_DIR_PATH", &dir_path);

    // Log all actions taken, including directory creation, environment variable setting, and cleanup attempts
    println!("Created or used directory at {}", &dir_path);
    println!("Set environment variable MY_DIR_PATH to {}", &dir_path);

    if let Some(cleanup_timer) = cleanup_timer {
        // Wait for the background thread to finish
        match cleanup_timer.join() {
            Ok(_) => (),
            Err(_) => println!("Failed to join cleanup timer"),
        }
        println!("Directory cleanup timer finished");
    } else {
        println!("No directory cleanup timer created");
    }
}

fn create_new_dir(path: &str) -> String {
    // Create a new directory at the specified location
    match fs::create_dir(&path) {
        Ok(_) => (),
        Err(err) => panic!("Failed to create new directory: {}", err),
    }

    // Return the path of the newly created directory
    path.to_string()
}
