using UnityEngine;

public class ValueGenerator : MonoBehaviour
{
    private int minValue;
    private int maxValue;

    public ValueGenerator(int min, int max)
    {
        if (min > max)
            throw new ArgumentException("Minimum value must be less than or equal to maximum value");
        this.minValue = min;
        this.maxValue = max;
    }

    public float GenerateFloat()
    {
        return UnityEngine.Random.value;
    }

    public int GenerateInt(int lowerBound = 0, int upperBound = 1)
    {
        return UnityEngine.Random.Range(lowerBound, upperBound);
    }

    public int[] GenerateIntArray(int size)
    {
        if (size < 0)
            throw new ArgumentException("Size must be positive");
        int[] array = new int[size];
        for (int i = 0; i < size; i++)
        {
            array[i] = GenerateInt();
        }
        return array;
    }

    public float[] GenerateFloatArray(int size)
    {
        if (size < 0)
            throw new ArgumentException("Size must be positive");
        float[] array = new float[size];
        for (int i = 0; i < size; i++)
        {
            array[i] = GenerateFloat();
        }
        return array;
    }

    public override string ToString()
    {
        return $"ValueGenerator: Range={minValue}-{maxValue}";
    }
}
