// Structures for the NFAPI_CRC_INDICATION_PDU_T and RX_UE_INFORMATION_TAG
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
