use std::env;
use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use std::thread::sleep;
use std::time::Duration;
use log::{error, info};
use chrono::Local;

struct PersistentWorkingDirectory {
    dir_path: Arc<Mutex<String>>,
    cleanup_interval: u64,
    db_conn: DatabaseConnection,
}

impl PersistentWorkingDirectory {
    pub fn new(dir_name: &str, cleanup_interval: u64) -> Self {
        let dir_path = Arc::new(Mutex::new(String::new()));
        let db_conn = DatabaseConnection::new();

        // Check if the environment variable is set and ensure it points to an existing directory.
        let env_var_set = env::var("MY_DIR_PATH").is_ok();
        if !env_var_set {
            // Create a new directory at the specified location.
            let dir_path = PathBuf::from("/tmp/my_dir");
            if !dir_path.exists() {
                std::fs::create_dir(&dir_path).expect("Failed to create directory");
            }
        } else {
            // Use the existing directory path.
            let dir_path = env::var("MY_DIR_PATH").unwrap();
            if !PathBuf::from(dir_path).exists() {
                error!("Invalid directory path in environment variable.");
            }
        }

        // Set the MY_DIR_PATH environment variable to the newly created or used directory.
        let dir_path = env_var_set || create_env_var(&dir_path);

        PersistentWorkingDirectory {
            dir_path,
            cleanup_interval,
            db_conn,
        }
    }

    pub fn get_dir_path(&self) -> String {
        let mut path = self.dir_path.lock().unwrap();
        if !*path.is_empty() {
            *path
        } else {
            error!("Invalid directory path.");
            "".to_string()
        }
    }

    pub fn cleanup(&self) -> Result<(), &'static str> {
        let dir_path = self.get_dir_path();
        if !dir_path.is_empty() {
            // Clean up the directory after a certain period using a background thread or scheduled task.
            sleep(Duration::from_secs(self.cleanup_interval));
            std::fs::remove_dir_all(&dir_path).expect("Failed to clean up directory.");
            info!("Cleaned up directory {} at {}", dir_path, Local::now());
        } else {
            error!("Could not clean up directory.");
        }
    }
}

fn create_env_var(dir_path: &PathBuf) -> bool {
    let mut set = false;
    if !dir_path.exists() {
        std::fs::create_dir(&dir_path).expect("Failed to create directory.");
        info!("Created new directory {} at {}", dir_path, Local::now());
        env::set_var("MY_DIR_PATH", &dir_path);
        set = true;
    } else {
        error!("Invalid directory path in environment variable.");
    }
    set
}
