function parseTiffImageFile(filePath, options = {}) {
  const image = parseTiffImage(fs.readFileSync(filePath));
  if (image.bitsPerSample !== 1 && image.bitsPerSample !== 2 && image.bitsPerSample !== 4 && image.bitsPerSample !== 8 && image.bitsPerSample !== 16) {
    throw new Error(`Unsupported bits per sample: ${image.bitsPerSample}`);
