      extraSamples.push({
        name: `extra_sample${i - 4}`,
        type: image.samples[i].type,
        value: image.samples[i].value,
      });
    }
  }
  return {
    bitsPerSample: image.bitsPerSample,
    samplesPerPixel: image.samplesPerPixel,
    extraSamples: extraSamples,
  };
}

