using System.Collections.Generic;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using System.Threading.Tasks;

public class Product
{
    public string Name { get; set; }
    public decimal Price { get; set; }
    public string Category { get; set; }
}

public static async Task<IEnumerable<Product>> LoadAndMergeDataAsync(string[] filePaths)
{
    // Initialize a new list to store the merged data
    var products = new List<Product>();

    // Iterate over each file path and load the data asynchronously
    foreach (var filePath in filePaths)
    {
        using (var stream = File.OpenRead(filePath))
        {
            try
            {
                var formatter = new BinaryFormatter();
                var productList = (List<Product>)formatter.Deserialize(stream);

                // Add the deserialized products to the merged list
                products.AddRange(productList);
            }
            catch (Exception ex)
            {
                // Log the error and continue with the next file
                Console.WriteLine($"Error loading data from '{filePath}': {ex.Message}");
            }
        }
    }

    return products;
}
