#include <time.h>

// Structure definitions
struct Node {
    int value;
    struct SubNode *subnodes;
};

struct SubNode {
    char *string;
    double value;
};

void init_node_array(int num_nodes, int min_value, int max_value) {
    // Allocate memory for the node array
    struct Node *nodes = malloc(num_nodes * sizeof(struct Node));
    if (!nodes) {
        printf("Error: Memory allocation failed\n");
        return;
    }

    // Initialize each node with a random integer value within the specified range
    for (int i = 0; i < num_nodes; i++) {
        nodes[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Allocate memory for the linked list of subnodes and initialize each one with a random string and double value
    for (int i = 0; i < num_nodes; i++) {
        nodes[i].subnodes = malloc(sizeof(struct SubNode));
        if (!nodes[i].subnodes) {
            printf("Error: Memory allocation failed\n");
            return;
        }
        nodes[i].subnodes->string = malloc(10 * sizeof(char)); // Randomly generated string of length 10
        if (!nodes[i].subnodes->string) {
            printf("Error: Memory allocation failed\n");
            return;
        }
        snprintf(nodes[i].subnodes->string, 10, "%s", "Hello, World!"); // Randomly generated string
        nodes[i].subnodes->value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Print the initialized node array and linked lists
    printf("Node array:\n");
    for (int i = 0; i < num_nodes; i++) {
        printf("%d: %d -> %s -> %.2f\n", i, nodes[i].value, nodes[i].subnodes->string, nodes[i].subnodes->value);
    }

    // Free all allocated memory when done
    for (int i = 0; i < num_nodes; i++) {
        free(nodes[i].subnodes->string);
        free(nodes[i].subnodes);
    }
    free(nodes);
}

int main() {
    srand(time(NULL)); // Initialize random seed
    int num_nodes = 5; // Specify number of nodes to allocate memory for
    int min_value = 10; // Specify minimum value range for integer values
    int max_value = 20; // Specify maximum value range for integer values

    init_node_array(num_nodes, min_value, max_value);

    return 0;
}
