// Static member variable for the random number generator
std::mt19937_64 RandomNumberGenerator::random;

// Constructor
RandomNumberGenerator::RandomNumberGenerator() {
  std::ifstream urandom("/dev/urandom", std::ios::binary);
  if (urandom.is_open()) {
    // Seed the random number generator with current time and additional entropy from /dev/urandom
    random.seed(std::chrono::high_resolution_clock::now().time_since_epoch().count() + urandom.read());
  } else {
    // Error handling for file access or database operations
    std::cout << "Error: Could not open /dev/urandom" << std::endl;
  }
}

// Destructor
RandomNumberGenerator::~RandomNumberGenerator() {}

// Method to generate a new session ID
std::string RandomNumberGenerator::generateSessionID() {
  // Generate a random number between 0 and 1e22 (inclusive)
  double r = std::uniform_real_distribution<double>(0, 1e22)(random);
  // Convert the random number to a base64 encoded string of length 22 characters
  std::stringstream ss;
  ss << std::setfill('0') << std::setw(22) << std::hex << r;
  std::string id = ss.str();

  // Check if the generated session ID is already in use within the application's database
  while (isDuplicate(id)) {
    // Regenerate a new session ID until a unique one is found
    id = generateSessionID();
  }
  return id;
}

