using System;
using System.Diagnostics;
using System.IO;
using System.Threading;
using System.Threading.Tasks;

public class WebsiteAdder
{
    private const string WebConfigFile = "web.config";
    private static readonly object _lockObj = new object();

    public async Task<Process> AddSiteAsync(string directoryPath, string siteName)
    {
        if (string.IsNullOrEmpty(directoryPath))
            throw new ArgumentException("Directory path is required.", nameof(directoryPath));

        if (string.IsNullOrEmpty(siteName))
            throw new ArgumentException("Site name is required.", nameof(siteName));

        var validName = ValidateSiteName(siteName);
        if (!validName)
            return null;

        // Ensure the directory path exists and is accessible.
        if (!Directory.Exists(directoryPath))
            throw new DirectoryNotFoundException($"The directory {directoryPath} does not exist.");

        var process = default(Process);
        try
        {
            // Check if a web.config file exists in the directory.
            if (File.Exists(Path.Combine(directoryPath, WebConfigFile)))
            {
                // Create a new process for the site.
                process = new Process()
                {
                    StartInfo = new ProcessStartInfo()
                    {
                        FileName = "cmd",
                        Arguments = $"/C \"cd /D {directoryPath} & start http://localhost:80\""
                    }
                };

                // Ensure the process is disposed of correctly.
                using (process)
                {
                    // Start the process asynchronously and wait for it to complete.
                    await process.StartAsync().ConfigureAwait(false);
                    await process.WaitForExitAsync().ConfigureAwait(false);
                }
            }
            else
            {
                Console.WriteLine($"The directory {directoryPath} does not contain a web.config file.");
                return null;
            }
        }
        catch (Exception ex)
        {
            // Log any errors that occur during the process of adding or starting the site.
            Console.WriteLine(ex.Message);
            return null;
        }
        finally
        {
            // Clean up any resources used by the process.
            if (process != null)
                process.Dispose();
        }

        return process;
    }

    private bool ValidateSiteName(string siteName)
    {
        var invalidChars = Path.GetInvalidFileNameChars();
        foreach (var c in siteName)
        {
            if (invalidChars.Contains(c))
                return false;
        }

        return true;
    }
}
