namespace RandomNumberGenerator {
  class Generator {
   public:
    // Constructor that reads the configuration file and initializes the generator
    Generator(const std::string& configFile) : m_configFile(configFile) {
      // Load the configuration settings from the JSON file
      loadConfig();

      // Initialize the random number generator with a seed based on time and system entropy
      initializeGenerator();
    }

    ~Generator() = default;

    // Generate a random number according to the specified distribution
    double generateRandomNumber(const std::string& distribution) {
      if (distribution == "uniform") {
        return generateUniform();
      } else if (distribution == "normal") {
        return generateNormal();
      } else if (distribution == "exponential") {
        return generateExponential();
      } else {
        throw std::invalid_argument("Invalid distribution: " + distribution);
      }
    }

   private:
    // Load the configuration settings from the JSON file
    void loadConfig() {
      std::ifstream configFile(m_configFile);
      if (!configFile.is_open()) {
        throw std::runtime_error("Could not open configuration file");
      }

      nlohmann::json config;
      configFile >> config;

      // Read the distribution settings from the JSON file
      m_distribution = config["distribution"].get<std::string>();
      m_mean = config["mean"].get<double>();
      m_sd = config["standard-deviation"].get<double>();
    }

    // Initialize the random number generator with a seed based on time and system entropy
    void initializeGenerator() {
      std::random_device rd;
      std::seed_seq seeds{ rd(), std::time(nullptr), static_cast<unsigned int>(std::clock()) };
      m_gen.seed(seeds);
    }

    // Generate a uniform random number between 0 and 1
    double generateUniform() {
      return m_gen();
    }

    // Generate a normal random number with the specified mean and standard deviation
    double generateNormal() {
      std::normal_distribution<double> dist(m_mean, m_sd);
      return dist(m_gen);
    }

    // Generate an exponential random number with the specified lambda value
    double generateExponential() {
      std::exponential_distribution<double> dist(m_lambda);
      return dist(m_gen);
    }

    std::string m_configFile;
    std::mt19937 m_gen;
    std::string m_distribution;
    double m_mean, m_sd, m_lambda;
  };
}
```
