```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

enum ResourceType { IMAGE, TEXT, AUDIO, NUM_TYPES };
typedef struct ResourceItem {
    enum ResourceType type;
    void* data;
} ResourceItem;

typedef struct ResourceBundle {
    ResourceItem* items;
    size_t itemCount[NUM_TYPES];
    size_t totalItemCount;
    pthread_mutex_t mutex; // For thread safety
} ResourceBundle;

ResourceBundle* loadResourceBundle(const char* filePath) {
    FILE *file = fopen(filePath, "rb");
    if (file == NULL) {
        perror("Failed to open resource file");
        return NULL;
    }

    // Allocate memory for the bundle
    ResourceBundle* bundle = malloc(sizeof(ResourceBundle));
    if (bundle == NULL) {
        fclose(file);
        perror("Failed to allocate memory for resource bundle");
        return NULL;
    }

    // Initialize mutex
    pthread_mutex_init(&bundle->mutex, NULL);

    // Read file and parse entries
    while (!feof(file)) {
        // Read 4-byte identifier
        uint32_t identifier;
        if (fread(&identifier, sizeof(uint32_t), 1, file) != 1) {
            fclose(file);
            perror("Failed to read resource identifier");
            freeResourceBundle(bundle);
            return NULL;
        }

        // Read 4-byte size
        uint32_t size;
        if (fread(&size, sizeof(uint32_t), 1, file) != 1) {
            fclose(file);
            perror("Failed to read resource size");
            freeResourceBundle(bundle);
            return NULL;
        }

        // Allocate memory for the resource item
        ResourceItem* item = malloc(sizeof(ResourceItem));
        if (item == NULL) {
            fclose(file);
            perror("Failed to allocate memory for resource item");
            freeResourceBundle(bundle);
            return NULL;
        }

        // Read the resource data
        void* data = malloc(size);
        if (data == NULL) {
            fclose(file);
            perror("Failed to allocate memory for resource data");
            freeResourceBundle(bundle);
            return NULL;
        }
        if (fread(data, size, 1, file) != 1) {
            fclose(file);
            perror("Failed to read resource data");
            freeResourceBundle(bundle);
            return NULL;
        }

        // Add the resource item to the bundle
        pthread_mutex_lock(&bundle->mutex);
        bundle->items = realloc(bundle->items, (bundle->totalItemCount + 1) * sizeof(ResourceItem));
        if (bundle->items == NULL) {
            fclose(file);
            perror("Failed to allocate memory for resource items");
            freeResourceBundle(bundle);
            return NULL;
        }
        bundle->items[bundle->totalItemCount].type = identifier;
        bundle->items[bundle->totalItemCount].data = data;
        bundle->itemCount[identifier]++;
        bundle->totalItemCount++;
        pthread_mutex_unlock(&bundle->mutex);
    }

    fclose(file);

    return bundle;
}

void freeResourceBundle(ResourceBundle* bundle) {
    if (bundle == NULL) {
        return;
    }

    // Free memory for the resource items
    pthread_mutex_lock(&bundle->mutex);
    for (size_t i = 0; i < bundle->totalItemCount; i++) {
        free(bundle->items[i].data);
    }
    free(bundle->items);
    pthread_mutex_unlock(&bundle->mutex);

    // Free memory for the bundle
    free(bundle);
}
```
This code defines a `ResourceBundle` struct that contains an array of `ResourceItem` structs, each representing a single resource. The `itemCount` member is used to keep track of the number of resources of each type, and the `totalItemCount` member is used to keep track of the total number of resources in the bundle. The `mutex` member is used for thread safety when accessing the bundle from multiple threads.

