        response = requests.get(url)
        if response.status_code == 200:
            data = json.loads(response.text)
            return data["main"]["temp"], data["main"]["humidity"], data["wind"]["speed"]
        else:
            raise Exception("Failed to fetch weather data")

    def get_weather_for_cities(self, cities, time_period):
        results = {}
        for city in cities:
            try:
                temp, humidity, wind_speed = self.fetch_weather(city)
                results[city] = {"temp": temp, "humidity": humidity, "wind_speed": wind_speed}
            except Exception as e:
                print(f"Failed to fetch weather data for {city}: {e}")
        return results

class WeatherAPIMockTest(mock.TestCase):
    def test_fetch_weather_success(self):
        api = WeatherAPI()
        city = "New York, US"
        url = f"{api.base_url}weather?q={city}&appid={api.api_key}"
        response = requests.get(url)
        self.assertEqual(response.status_code, 200)
        data = json.loads(response.text)
        self.assertIn("main", data)
        self.assertIn("humidity", data["main"])
        self.assertIn("wind", data["wind"])

    def test_fetch_weather_failure(self):
        api = WeatherAPI()
        city = "Fake City, US"
        url = f"{api.base_url}weather?q={city}&appid={api.api_key}"
        response = requests.get(url)
        self.assertNotEqual(response.status_code, 200)
