// C program to process large log file
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_FIELDS 1024 // maximum number of fields in a log entry
#define MAX_ENTRIES 1000000 // maximum number of log entries to process

// structure to represent a single log entry
struct LogEntry {
    char* timestamp;
    char* server;
    char* data[MAX_FIELDS];
};

// array to store all the log entries
struct LogEntry logEntries[MAX_ENTRIES];

// semaphore for synchronizing access to the log entry array
sem_t *logSem;

// function to parse a single log entry and calculate average of last two numeric fields
void processLogEntry(char* line) {
    char* token = strtok(line, ","); // get first field (timestamp)
    struct LogEntry entry;
    int i = 0;

    while (token != NULL && i < MAX_FIELDS) {
        if (i == 0) {
            entry.timestamp = token;
        } else if (i > 1 && isNumeric(token)) { // skip first two fields and any non-numeric fields
            double value = atof(token);
            if (value >= 0) {
                entry.data[i] = token;
            } else {
                entry.data[i] = "";
            }
        }
        i++;
    }
    pthread_mutex_lock(&logSem); // lock mutex to access log entry array
    logEntries[i - 2] = entry; // append the new log entry
    pthread_mutex_unlock(&logSem); // unlock mutex
}

// function to calculate average of last two numeric fields in a log entry
void calculateAverage(struct LogEntry* entry) {
    double sum = 0;
    int i = 1;
    while (entry->data[i] != NULL && isNumeric(entry->data[i])) {
        sum += atof(entry->data[i]);
        i++;
    }
    if (i > 1) {
        entry->data[i - 2] = malloc(50); // allocate memory for the average string
        sprintf(entry->data[i - 2], "%.2f", sum / (i - 1));
    } else {
        entry->data[i - 2] = "";
    }
}

// function to print all log entries in a comma-separated format
void printLogEntries() {
    for (int i = 0; i < MAX_ENTRIES; i++) {
        if (logEntries[i].timestamp != NULL) {
            printf("%s,%s,%s\n", logEntries[i].timestamp, logEntries[i].server, logEntries[i].data[3]);
        }
    }
}

// function to check if a string is numeric
int isNumeric(char* str) {
    char *p;
    double value = strtod(str, &p);
    return (*p == '\0' && value >= 0);
}

// main function to process the log file
int main() {
    FILE *file = fopen("log.txt", "r"); // open log file in read mode
    if (file != NULL) {
        while (!feof(file)) {
            char line[1024]; // allocate memory for a single line of the log file
            fgets(line, 1024, file); // read a single line from the file
            processLogEntry(line); // parse and calculate average of last two numeric fields in the log entry
        }
    }
    printLogEntries(); // print all log entries in a comma-separated format
}

// Java method to establish connection to remote address using Java Channel and handle connection state changes
public static void establishConnection(String host, int port) {
    try {
        SocketChannel socket = SocketChannel.open(new InetSocketAddress(host, port)); // open a new socket channel
        if (socket != null) {
            socket.configureBlocking(false); // configure socket as non-blocking
            while (!socket.isConnected()) { // wait for connection to be established
                Thread.sleep(1000); // sleep for 1 second
            }
        } else {
            System.out.println("Connection failed");
        }
    } catch (IOException | InterruptedException e) {
        e.printStackTrace();
    }
}

// Java method to manage cooldown period of video game character's attacks
public static void manageCooldown(int cooldown, int attack1, int attack2) {
    Random random = new Random();
    int choice; // variable to store the attack choice
    if (cooldown > 0) { // check if cooldown period is over
        cooldown--;
    } else { // choose an attack based on a random mechanism
        choice = random.nextInt(2);
        if (choice == 0) {
            System.out.println("Attack 1 selected");
        } else {
            System.out.println("Attack 2 selected");
        }
    }
}

// Java method to log an event in a remote logging service using struct format
public static void logEvent(String host, int port, String name, int value) {
    try {
        SocketChannel socket = SocketChannel.open(new InetSocketAddress(host, port)); // open a new socket channel
        if (socket != null) {
            socket.configureBlocking(false); // configure socket as non-blocking
            while (!socket.isConnected()) { // wait for connection to be established
                Thread.sleep(1000); // sleep for 1 second
            }
            String data = "Name: " + name + " Value: " + value;
            byte[] bytes = data.getBytes();
            socket.write(ByteBuffer.wrap(bytes)); // write the event to the socket channel
        } else {
            System.out.println("Connection failed");
        }
    } catch (IOException | InterruptedException e) {
        e.printStackTrace();
    }
}

// Java method to extract bits per sample and sample per pixel information from a TIFF image file
public static void getTIFFInfo(String filename) {
    try {
        FileInputStream in = new FileInputStream(filename); // open the input stream for the TIFF image file
        byte[] header = new byte[4]; // allocate memory for the TIFF header bytes
        in.read(header); // read the TIFF header from the input stream
        if (header[0] == 'I' && header[1] == 'I' && header[2] == '\0') { // check if the header is valid
            int bitsPerSample = 0; // variable to store the bits per sample value
            int samplesPerPixel = 0; // variable to store the samples per pixel value
            while (in.read(header) != -1) { // read the TIFF image data from the input stream
                if (header[0] == 'b' && header[1] == 'i' && header[2] == 't') { // check if the header is valid
                    bitsPerSample = header[3]; // extract the bits per sample value
                } else if (header[0] == 's' && header[1] == 'a' && header[2] == 'm') { // check if the header is valid
                    samplesPerPixel = header[3]; // extract the samples per pixel value
                }
            }
            System.out.println("Bits per sample: " + bitsPerSample);
            System.out.println("Samples per pixel: " + samplesPerPixel);
        } else {
            System.out.println("Invalid TIFF header");
        }
    } catch (IOException e) {
        e.printStackTrace();
    }
}

