```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
#include <sys/stat.h>
#include <dirent.h>
#include <pthread.h>
#include <semaphore.h>
#include <mqueue.h>
#include <errno.h>
#include "logging_service.h"

// Constants
const int NUM_THREADS = 4; // Number of concurrent threads for processing log files
const int BUFFER_SIZE = 1024 * 1024; // Size of the message buffer for the message queue
const int MAX_PRIORITY = 3; // Maximum priority level for log files

// Structures
typedef struct {
    char* file_name;
    time_t last_modified;
    long num_lines;
} FileMetadata;

typedef struct {
    double average;
    int line_num;
} AverageRecord;

// Global variables
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
sem_t semaphore = SEM_INITIALIZER;
mqueue_t message_queue = MQUEUE_INITIALIZER;
FileMetadata* file_metadata_list = NULL;
AverageRecord* average_record_list = NULL;
int num_files = 0;

// Function prototypes
void* process_file(void* arg);
double calculate_average(const char* line);
int compare_priorities(const void* a, const void* b);

int main() {
    // Initialize the message queue and semaphore
    mqueue_init(&message_queue, BUFFER_SIZE, NULL);
    sem_init(&semaphore, 0, 1);

    // Scan the directory for log files and store their metadata in a list
    DIR* dir = opendir("./logs");
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;
        FileMetadata* metadata = (FileMetadata*) malloc(sizeof(FileMetadata));
        metadata->file_name = entry->d_name;
        struct stat file_stat;
        if (stat(entry->d_name, &file_stat) != 0) {
            perror("Error getting file information");
            continue;
        }
        metadata->last_modified = file_stat.st_mtime;
        metadata->num_lines = file_stat.st_size / sizeof(char);
        num_files++;
    }

    // Create and start threads for each log file
    pthread_t* threads = (pthread_t*) malloc(sizeof(pthread_t) * NUM_THREADS);
    for (int i = 0; i < NUM_THREADS; i++) {
        int* thread_id = (int*) malloc(sizeof(int));
        *thread_id = i + 1;
        pthread_create(&threads[i], NULL, process_file, (void*) thread_id);
    }

    // Wait for all threads to finish and destroy the message queue and semaphore
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }
    mqueue_destroy(&message_queue);
    sem_destroy(&semaphore);

    // Print the average records and their corresponding line numbers
    for (int i = 0; i < num_files; i++) {
        printf("%s: %lf\n", file_metadata_list[i].file_name, average_record_list[i].average);
    }

    // Clean up the memory allocated for the list of files and their metadata
    free(file_metadata_list);
    free(average_record_list);

    return 0;
}

void* process_file(void* arg) {
    int thread_id = *((int*) arg);
    printf("Thread %d starting\n", thread_id);

    // Loop through the lines of the log file and calculate the average of the last two numerical fields
    char* line;
    while ((line = mqueue_receive(&message_queue)) != NULL) {
        double average = calculate_average(line);
        AverageRecord record = { average, 0 };
        sem_wait(&semaphore);
        file_metadata_list[thread_id].num_lines--;
        if (file_metadata_list[thread_id].num_lines > 0) {
            average_record_list[thread_id].average = calculate_average(line);
            record.line_num++;
            mqueue_send(&message_queue, &record, sizeof(AverageRecord));
        } else {
            // File has been processed completely
            pthread_exit(NULL);
        }
    }
}

double calculate_average(const char* line) {
    double average = 0;
    int num_fields = 0;
    const char* delim = " ";
    char* field = strtok((char*) line, delim);
    while (field != NULL && num_fields < 2) {
        if (!isdigit(field[0])) break; // Non-numerical field found, abort calculation
        average += atof(field);
        num_fields++;
        field = strtok(NULL, delim);
    }
    return num_fields > 1 ? average / num_fields : -1; // Return -1 if there are fewer than two numerical fields
}

int compare_priorities(const void* a, const void* b) {
    int priority_a = *((int*) a);
    int priority_b = *((int*) b);
    return priority_a > priority_b ? -1 : 1; // Return -1 if priority_a is higher than priority_b
}
```

This solution uses the `mqueue` library to implement a message queue that is used to communicate between the threads. The `process_file` function takes a `char*` pointer as an argument, which points to the line of text that needs to be processed. The function first calculates the average of the last two numerical fields in the line using the `calculate_average` function. If there are fewer than two numerical fields, then -1 is returned as the average value.

The main thread then initializes the message queue and semaphore, and starts the threads for each log file. Each thread processes its own log file by looping through its lines using the `mqueue_receive` function to retrieve the next line of text from the message queue. The `process_file` function is called with a `char*` pointer that points to the line of text, which calculates the average of the last two numerical fields in the line and sends the resulting `AverageRecord` structure back to the main thread using the `mqueue_send` function.

The main thread then waits for all threads to finish by using the `pthread_join` function, and destroys the message queue and semaphore using the `mqueue_destroy` and `sem_destroy` functions, respectively. The main thread then prints the average records and their corresponding line numbers.

Note that this solution assumes that each log file has at least one numerical field in it, and that the number of fields is greater than or equal to 2 for the average calculation to be valid. If a log file does not have enough fields to calculate an average, then -1 will be returned as the average value. This can cause errors when trying to print the results, so it's important to check the return values from the `calculate_average` function before attempting to use them.

