import org.example.connectionpool.ConnectionPoolConfig;
import org.example.connectionpool.ConnectionPoolStats;
import org.example.connectionpool.ConnectionPoolStats.ActiveConnections;
import org.example.connectionpool.ConnectionPoolStats.IdleConnections;
import org.example.connectionpool.ConnectionPoolStats.TotalConnections;
import org.example.connectionpool.ConnectionPoolStats.ConnectionAcquisitionTime;
