import org.example.connectionpool.ConnectionPoolStats.ConnectionEstablishmentLatency;
import org.example.connectionpool.ConnectionPoolStats.ConnectionClosureLatency;
import org.example.connectionpool.ConnectionPoolStats.ConnectionReopeningRate;

/**
 * A connection pool for establishing secure, high-performance connections to remote servers using NIO channels.
 */
public class ConnectionPool {
    private static final Logger LOGGER = Logger.getLogger(ConnectionPool.class.getName());

    /** The configuration of the connection pool. */
    private final ConnectionPoolConfig config;

    /** The asynchronous channel group for managing connections. */
    private final AsynchronousChannelGroup channelGroup;

    /** The list of active connections. */
    private final List<AsynchronousServerSocketChannel> activeConnections = new ArrayList<>();

    /** The list of idle connections. */
    private final List<AsynchronousServerSocketChannel> idleConnections = new ArrayList<>();

    /** The number of active connections. */
    private int numActiveConnections;

    /** The number of idle connections. */
    private int numIdleConnections;

    /** The total number of connections. */
    private int numTotalConnections;

    /** The statistics for the connection pool. */
    private final ConnectionPoolStats stats = new ConnectionPoolStats();

    /**
     * Creates a new instance of {@link ConnectionPool}.
     * @param config the configuration of the connection pool
     * @throws IOException if an I/O error occurs while creating the asynchronous channel group
     */
    public ConnectionPool(ConnectionPoolConfig config) throws IOException {
        this.config = config;
        this.channelGroup = AsynchronousChannelGroup.withFixedThreadPool(config.getNumThreads(), Executors.defaultThreadFactory());
    }

    /**
     * Establishes a secure, high-performance connection to a remote server using NIO channels.
     * @param host the hostname or IP address of the remote server
     * @param port the port number of the remote server
     * @param protocol the protocol for establishing the connection (e.g., "https")
     * @return a future that resolves to the established connection, or null if the connection establishment fails
     */
    public CompletableFuture<AsynchronousServerSocketChannel> connect(String host, int port, String protocol) {
        ActiveConnections.increment();
        TotalConnections.increment();

        try {
            AsynchronousServerSocketChannel channel = AsynchronousServerSocketChannel.open(channelGroup);
            CompletableFuture<AsynchronousServerSocketChannel> future = new CompletableFuture<>();

            // configure the SSL context for TLS/SSL encryption
            if (protocol.equals("https")) {
                SSLContext sslContext = config.getSslContext();
                SSLEngine engine = sslContext.createSSLEngine(host, port);
                engine.setUseClientMode(false);
                channel.configureBlocking(false);
                channel.connect(new InetSocketAddress(host, port), null, future);
            } else {
                // non-SSL protocols are not supported for now
                throw new IllegalArgumentException("Unsupported protocol: " + protocol);
            }

            return future;
        } catch (IOException e) {
            FailedConnections.increment();
            ConnectionEstablishmentLatency.record(0, TimeUnit.NANOSECONDS);
            LOGGER.log(Level.WARNING, "Failed to establish connection: " + e.getMessage());
            return null;
        }
    }

    /**
     * Closes a connection and returns it to the pool.
     * @param channel the connection to close
     */
    public void close(AsynchronousServerSocketChannel channel) {
        if (channel == null) {
            return;
        }

        try {
            channel.close();
        } catch (IOException e) {
            LOGGER.log(Level.WARNING, "Failed to close connection: " + e.getMessage());
        } finally {
            // increment the number of active connections and remove from the list of active connections
            numActiveConnections--;
            idleConnections.add(channel);
            IdleConnections.increment();

            ConnectionClosureLatency.record(System.nanoTime() - channel.getLastAccessedTime(), TimeUnit.NANOSECONDS);
        }
    }

    /**
     * Reopens a closed connection and returns it to the pool.
     * @param channel the connection to reopen
     */
    public void reopen(AsynchronousServerSocketChannel channel) {
        if (channel == null) {
            return;
        }

        try {
            channel.connect();
        } catch (IOException e) {
            LOGGER.log(Level.WARNING, "Failed to reopen connection: " + e.getMessage());
        } finally {
            // increment the number of active connections and remove from the list of idle connections
            numActiveConnections++;
            idleConnections.remove(channel);
            ActiveConnections.increment();

            ConnectionReopeningLatency.record(System.nanoTime() - channel.getLastAccessedTime(), TimeUnit.NANOSECONDS);
        }
    }

    /**
     * Gets a connection from the pool.
     * @return a connection, or null if no connections are available
     */
    public AsynchronousServerSocketChannel getConnection() {
        if (idleConnections.isEmpty()) {
            return null;
        } else {
            // increment the number of active connections and remove from the list of idle connections
            AsynchronousServerSocketChannel channel = idleConnections.remove(0);
            numActiveConnections++;
            ActiveConnections.increment();

            ConnectionBorrowingLatency.record(System.nanoTime() - channel.getLastAccessedTime(), TimeUnit.NANOSECONDS);

            return channel;
        }
    }

    /**
     * Returns a connection to the pool.
     * @param channel the connection to return
     */
    public void returnConnection(AsynchronousServerSocketChannel channel) {
        if (channel == null) {
            return;
        }

        // increment the number of active connections and remove from the list of idle connections
        numActiveConnections--;
        idleConnections.add(channel);
        IdleConnections.increment();

        ConnectionReturningLatency.record(System.nanoTime() - channel.getLastAccessedTime(), TimeUnit.NANOSECONDS);
    }
}

