public static class WebsiteManager
{
    private const string WebConfigFileName = "web.config";
    private const int DefaultBasePortNumber = 8080;
    private const int TimeoutMilliseconds = 30_000; // 30 seconds
    private const int RetryAttempts = 3;

    public static async Task<bool> AddSiteAsync(string directoryPath, string siteName, int basePortNumber)
    {
        try
        {
            if (string.IsNullOrWhiteSpace(directoryPath))
                throw new ArgumentException("Invalid directory path", nameof(directoryPath));

            if (!Directory.Exists(directoryPath))
                throw new DirectoryNotFoundException($"Directory '{directoryPath}' does not exist");

            if (string.IsNullOrWhiteSpace(siteName))
                throw new ArgumentException("Site name cannot be empty", nameof(siteName));

            // Validate site name meets naming conventions
            if (!Regex.IsMatch(siteName, "^[a-zA-Z0-9_-]+$"))
                throw new ArgumentException($"Invalid site name '{siteName}'. Site name can only contain letters (uppercase or lowercase), numbers, hyphens (-), and underscores (_)", nameof(siteName));

            // Check if web.config file exists in the directory
            var webConfigFilePath = Path.Combine(directoryPath, WebConfigFileName);
            if (!File.Exists(webConfigFilePath))
            {
                // Integrate with external configuration management system to retrieve default settings for the web server
                Console.WriteLine($"No web.config file found in directory '{directoryPath}'. Retrieving default settings from an external configuration management system.");

                var defaultSettings = await GetDefaultWebServerSettingsAsync();
                if (defaultSettings == null)
                    throw new Exception("Failed to retrieve default web server settings");

                // Create a new web.config file with the retrieved settings
                using (var writer = File.CreateText(webConfigFilePath))
                {
                    var xmlSerializer = new XmlSerializer(typeof(WebConfiguration));
                    xmlSerializer.Serialize(writer, defaultSettings);
                }
            }

            // Add a new site to the directory using the Process class
            var processStartInfo = new ProcessStartInfo()
            {
                FileName = "cmd",
                Arguments = $"/C \"%windir%\\system32\\inetsrv\\appcmd add site /name:{siteName} /bindings:*:{basePortNumber}: /physicalPath:\"{directoryPath}\"\"",
                UseShellExecute = false,
                RedirectStandardOutput = true,
                CreateNoWindow = true
            };

            var process = new Process() { StartInfo = processStartInfo };
            try
            {
                process.Start();
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Failed to start the site: {ex.Message}");
                return false;
            }

            // Wait for the process to finish and check if it succeeded
            var completed = process.WaitForExit(TimeoutMilliseconds);
            if (!completed)
            {
                Console.WriteLine($"Timed out waiting for the site to start");
                return false;
            }

            // Handle race conditions with concurrent access to the same directory
            lock (directoryPath)
            {
                var processOutput = process.StandardOutput.ReadToEnd();
                if (!string.IsNullOrWhiteSpace(processOutput))
                    Console.WriteLine($"Process output: {processOutput}");

                // Check if the site was added successfully by looking for the site in the IIS configuration
                var siteExists = await DoesSiteExistAsync(siteName);
                if (siteExists)
                {
                    Console.WriteLine($"Added new site '{siteName}' to directory '{directoryPath}' using base port number {basePortNumber}");
                    return true;
                }
                else
                {
                    Console.WriteLine($"Failed to add the site: {processOutput}");
                    return false;
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error adding new site: {ex.Message}");
            return false;
        }
        finally
        {
            // Clean up any resources used by the process
            process?.Dispose();
        }
    }

    private static async Task<bool> DoesSiteExistAsync(string siteName)
    {
        try
        {
            var processStartInfo = new ProcessStartInfo()
            {
                FileName = "cmd",
                Arguments = $"/C \"%windir%\\system32\\inetsrv\\appcmd list sites /name:{siteName}\"",
                UseShellExecute = false,
                RedirectStandardOutput = true,
                CreateNoWindow = true
            };

            var process = new Process() { StartInfo = processStartInfo };
            process.Start();
            var completed = process.WaitForExit(TimeoutMilliseconds);
            if (!completed)
            {
                Console.WriteLine($"Timed out waiting for the site to start");
                return false;
            }

            // Check if the site was added successfully by looking for the site in the IIS configuration
            var processOutput = process.StandardOutput.ReadToEnd();
            return !string.IsNullOrWhiteSpace(processOutput);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error checking if the site exists: {ex.Message}");
            return false;
        }
    }

