using System;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using System.Xml.Linq;

namespace DecryptionService
{
    class Program
    {
        static async Task Main(string[] args)
        {
            // Load configuration settings from XML file
            XDocument config = XDocument.Load("config.xml");
            int tileSize = Convert.ToInt32(config.Element("tileSize").Value);
            int worldWidth = Convert.ToInt32(config.Element("worldWidth").Value);
            int worldHeight = Convert.ToInt32(config.Element("worldHeight").Value);
            float cameraSpeed = Convert.ToSingle(config.Element("cameraSpeed").Value);

            // Define encryption parameters
            byte[] iv = Encoding.UTF8.GetBytes("init_vector");
            byte[] key = Encoding.UTF8.GetBytes("encryption_key");

            // Create AES-CBC decryptor
            using var aes = new AesCbc(key, iv);

            // Decrypt ciphertexts concurrently
            var tasks = new List<Task>();
            foreach (string ciphertext in args)
            {
                tasks.Add(DecryptAsync(ciphertext, aes));
            }
            await Task.WhenAll(tasks);
        }

        static async Task DecryptAsync(string ciphertext, AesCbc aes)
        {
            try
            {
                // Retrieve encryption key and IV from external API
                using var client = new HttpClient();
                string response = await client.GetStringAsync($"https://example.com/api/encryption?ciphertext={ciphertext}");
                dynamic jsonResponse = JsonConvert.DeserializeObject(response);
                iv = Encoding.UTF8.GetBytes((string)jsonResponse.iv);
                key = Encoding.UTF8.GetBytes((string)jsonResponse.key);

                // Create AES-CBC decryptor with new key and IV
                using var aes = new AesCbc(key, iv);

                // Decrypt ciphertext
                byte[] plaintext = await aes.DecryptAsync(Convert.FromBase64String(ciphertext));

                // Print decrypted text
                Console.WriteLine(Encoding.UTF8.GetString(plaintext));
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error: {ex.Message}");
            }
        }
    }
}
