import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class FileHasher {
    public static String computeMD5(String filePath) throws IOException, NoSuchAlgorithmException {
        // Create a MessageDigest instance for MD5 hashing
        MessageDigest digest = MessageDigest.getInstance("MD5");

        // Open the input stream to the file and read it in chunks
        try (FileInputStream fis = new FileInputStream(filePath)) {
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                // Update the digest with the read data
                digest.update(buffer, 0, bytesRead);
            }
        } catch (IOException e) {
            throw new IOException("Error reading file", e);
        }

        // Return the computed MD5 hash
        return digest.digest();
    }

    public static String verifyHash(String filePath, String expectedHash) throws IOException, NoSuchAlgorithmException {
        // Compute the MD5 hash of the file
        String actualHash = computeMD5(filePath);

        // Validate that the hashes match
        if (!actualHash.equals(expectedHash)) {
            throw new HashMismatchException("Expected hash does not match actual hash");
        }

        return actualHash;
    }

    public static List<String> verifyHashConcurrently(List<String> filePaths, String expectedHash) throws IOException, NoSuchAlgorithmException {
        // Create a list of CompletableFutures for each file path
        List<CompletableFuture<String>> futures = filePaths.stream()
                .map(filePath -> CompletableFuture.supplyAsync(() -> verifyHash(filePath, expectedHash)))
                .collect(Collectors.toList());

        // Wait for all futures to complete and retrieve the results
        List<String> actualHashes = futures.stream()
                .map(CompletableFuture::join)
                .collect(Collectors.toList());

        return actualHashes;
    }
}

class HashMismatchException extends Exception {
    public HashMismatchException(String message) {
        super(message);
    }
}
