Note that this code uses Triple DES encryption with a given key and initialization vector (IV) to decrypt the HTML content before updating the element's content. This provides an additional layer of security for your application, as it ensures that only authorized users can access the sensitive data. However, you should be aware that Triple DES is considered to be insecure by today's standards and should not be used for new applications. It is recommended to use a more modern encryption algorithm instead.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <pthread.h>
#include <sys/time.h>
#include <unistd.h>

// Define constants for command-line options
#define OPT_NUM_CONCURRENT_DOWNLOADS "--num-concurrent-downloads"
#define OPT_OUTPUT_FILEPATH "--output-filepath"
#define OPT_LOGGING_LEVEL "--logging-level"

// Define structures for holding data and meta information
struct DownloadInfo {
  char *url;
  char *outputFilePath;
  struct curl_slist *headers;
};

struct DownloadManager {
  int numConcurrentDownloads;
  int maxNumThreads;
  pthread_t *threads;
  struct DownloadInfo **downloads;
  struct timeval startTime;
  struct timeval endTime;
  FILE *logFile;
};

// Define functions for downloading and managing downloads
void download(struct DownloadManager *manager, int threadId);
int getNumConcurrentDownloads(struct DownloadManager *manager);
int getMaxNumThreads(struct DownloadManager *manager);
void setDownloadInfo(struct DownloadManager *manager, char *url, char *outputFilePath);
void addDownload(struct DownloadManager *manager, char *url, char *outputFilePath);
void startDownloads(struct DownloadManager *manager);
void stopDownloads(struct DownloadManager *manager);
int handleError(struct DownloadManager *manager, int errorCode);

// Define main function for running the web scraping tool
int main(int argc, char **argv) {
  // Initialize download manager with command-line options
  struct DownloadManager manager;
  manager.numConcurrentDownloads = getNumConcurrentDownloads(&manager);
  manager.maxNumThreads = getMaxNumThreads(&manager);
  manager.threads = (pthread_t *)malloc(sizeof(pthread_t) * manager.maxNumThreads);
  manager.downloads = (struct DownloadInfo **)malloc(sizeof(struct DownloadInfo *) * manager.maxNumThreads);
  manager.startTime = gettimeofday();
  manager.endTime = {0, 0};
  manager.logFile = fopen("web_scraper.log", "w");

  // Parse command-line options and add downloads to the manager
  for (int i = 1; i < argc - 1; i += 2) {
    if (strcmp(argv[i], OPT_NUM_CONCURRENT_DOWNLOADS) == 0) {
      manager.numConcurrentDownloads = atoi(argv[i + 1]);
    } else if (strcmp(argv[i], OPT_OUTPUT_FILEPATH) == 0) {
      setDownloadInfo(&manager, argv[i - 1], argv[i + 1]);
    }
  }

  // Start downloads and wait for them to finish
  startDownloads(&manager);
  stopDownloads(&manager);

  // Clean up memory and exit
  free(manager.threads);
  free(manager.downloads);
  fclose(manager.logFile);
  return 0;
}

// Define functions for downloading and managing downloads
void download(struct DownloadManager *manager, int threadId) {
  struct DownloadInfo *info = manager->downloads[threadId];
  CURL *curl = curl_easy_init();
  if (curl) {
    char url[1024];
    snprintf(url, sizeof(url), "%s", info->url);
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, NULL);
    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
      handleError(manager, res);
    } else {
      manager->endTime = gettimeofday();
      fprintf(manager->logFile, "Thread %d downloaded %s in %ld seconds\n", threadId, info->url, (long)(manager->endTime.tv_sec - manager->startTime.tv_sec));
    }
  } else {
    handleError(manager, res);
  }
}

int getNumConcurrentDownloads(struct DownloadManager *manager) {
  return manager->numConcurrentDownloads;
}

int getMaxNumThreads(struct DownloadManager *manager) {
  return manager->maxNumThreads;
}

void setDownloadInfo(struct DownloadManager *manager, char *url, char *outputFilePath) {
  struct DownloadInfo *info = malloc(sizeof(struct DownloadInfo));
  info->url = url;
  info->outputFilePath = outputFilePath;
  manager->downloads[getNumConcurrentDownloads(&manager)] = info;
}

void addDownload(struct DownloadManager *manager, char *url, char *outputFilePath) {
  setDownloadInfo(manager, url, outputFilePath);
}

void startDownloads(struct DownloadManager *manager) {
  for (int i = 0; i < getNumConcurrentDownloads(&manager); i++) {
    pthread_create(&manager->threads[i], NULL, download, &manager);
  }
}

void stopDownloads(struct DownloadManager *manager) {
  for (int i = 0; i < getMaxNumThreads(&manager); i++) {
    if (manager->downloads[i] != NULL) {
      pthread_join(manager->threads[i], NULL);
    }
  }
}

int handleError(struct DownloadManager *manager, int errorCode) {
  fprintf(manager->logFile, "Curl error: %d\n", errorCode);
  return -1;
}
```
