import json
import asyncio
from collections import defaultdict

class JsonObject:
    def __init__(self, data):
        self.data = data

    @staticmethod
    def from_json(json_string):
        return JsonObject(json.loads(json_string))

    def to_json(self):
        return json.dumps(self.data)

class JsonRegistry:
    def __init__(self):
        self.registry = defaultdict(list)

    def add_factory(self, id, factory):
        self.registry[id].append(factory)

    def get_factory(self, id):
        return self.registry[id][-1] if len(self.registry[id]) > 0 else None

class JsonLoader:
    def __init__(self, config_manager):
        self.config_manager = config_manager
        self.registry = JsonRegistry()
        self.loaded_files = set()

    async def load_file(self, file_path):
        if file_path in self.loaded_files:
            return
        try:
            with open(file_path) as f:
                data = json.load(f)
                self.register_factories(data)
                self.loaded_files.add(file_path)
        except Exception as e:
            print(f"Error loading file {file_path}: {e}")
            raise

    def register_factories(self, data):
        for id, factory in data.items():
            self.registry.add_factory(id, factory)

class JsonExecutor:
    def __init__(self, loader, config_manager):
        self.loader = loader
        self.config_manager = config_manager
        self.factories = defaultdict(list)

    async def execute(self):
        await self.loader.load_file("schema.json")
        while True:
            try:
                for file in self.loader.loaded_files:
                    data = await self.config_manager.get_data(file)
                    self.register_factories(data)
                break
            except Exception as e:
                print(f"Error executing file {file}: {e}")
                raise

    def register_factories(self, data):
        for id, factory in data.items():
            self.factories[id].append(factory)

class JsonScheduler:
    def __init__(self, executor):
        self.executor = executor

    async def run(self):
        while True:
            try:
                await self.executor.execute()
            except Exception as e:
                print("Error executing schedule: {e}")
                raise

async def main():
    config_manager = ConfigManager()
    loader = JsonLoader(config_manager)
    executor = JsonExecutor(loader, config_manager)
    scheduler = JsonScheduler(executor)
    await scheduler.run()

if __name__ == "__main__":
    asyncio.run(main())
```
