const fs = require('fs');
const path = require('path');
const { exec } = require('child_process');
const config = require('./config.json');

// Load and execute modules in specified order
function loadModules(modules, concurrency) {
  return Promise.all(modules.map((module) => {
    return new Promise((resolve, reject) => {
      const modulePath = path.join(__dirname, `modules/${module}.js`);
      fs.exists(modulePath, (exists) => {
        if (!exists) {
          reject(`Module ${module} does not exist.`);
        } else {
          exec(`node modules/${module}.js`, (err, stdout, stderr) => {
            if (err) {
              reject(err);
            } else {
              resolve(stdout);
            }
          });
        }
      });
    });
  })).then((results) => results.join('\n'));
}

// Load configuration file and execute modules
const config = require('./config.json');
loadModules(config.modules, config.concurrency);
