const TIFF = require('tiff');

function parseTiff(filepath) {
  try {
    const image = new TIFF.Image(filepath);
    if (image.bitsPerSample !== 1 && image.bitsPerSample !== 2 &&
        image.bitsPerSample !== 4 && image.bitsPerSample !== 8 &&
        image.bitsPerSample !== 16) {
      throw new Error(`Unsupported bits per sample: ${image.bitsPerSample}.`);
    }
    const samples = image.samples;
    if (samples > 0 && samples < 5) {
      throw new Error(`Too many extra samples present (${samples}).`);
    }
    return `Bits per sample: ${image.bitsPerSample}\nSamples per pixel: ${image.samples}`;
  } catch (err) {
    console.error(err);
    return err.message;
  }
}
