#include <iostream>
#include <string>
#include <vector>
#include <random>
#include <chrono>
#include <mutex>

namespace SessionManager {
  class SecureSessionIDGenerator {
  public:
    SecureSessionIDGenerator() : rand_gen(std::random_device{}()) { }

    std::string generateSessionID() {
      // Seed the random number generator with entropy from /dev/urandom and other nodes in the distributed system.
      std::vector<uint8_t> entropy;
      try {
        entropy = readEntropyFromFile("/dev/urandom");
      } catch (std::exception& e) {
        // Handle error reading entropy from /dev/urandom.
      }
      if (!entropy.empty()) {
        rand_gen.seed(entropy);
      }

      // Generate a random session ID using the secure seeding mechanism.
      std::uniform_int_distribution<uint64_t> dist;
      uint64_t id = dist(rand_gen);

      // Format the session ID as base64-encoded string of length 22 characters.
      return formatSessionID(id);
    }

    bool validateSessionID(const std::string& id) {
      if (isValidBase64String(id) && id.length() == 22) {
        return true;
      }
      return false;
    }

    void invalidateOldSessions() {
      // Implement a distributed locking mechanism to ensure atomicity when checking for duplicate session IDs across multiple nodes.
      std::lock_guard<std::mutex> lock(invalidation_mutex);

      // Mark old sessions as invalid and clear the cache.
      auto now = std::chrono::system_clock::now();
      for (auto& [session_id, timestamp] : session_cache) {
        if (std::chrono::duration_cast<std::chrono::minutes>(now - timestamp).count() >= 30) { // 30 minutes
          invalidateSessionID(session_id);
        }
      }
    }

  private:
    std::random_device rand_dev;
    std::mt19937_64 rand_gen;
    std::mutex invalidation_mutex;
    std::map<std::string, std::chrono::system_clock::time_point> session_cache;

    // Utility functions for base64 encoding and decoding.
    bool isValidBase64String(const std::string& str) {
      return str.length() % 4 == 0 && str.find_first_not_of("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=") == std::string::npos;
    }

    std::string formatSessionID(uint64_t id) {
      return base64Encode(id);
    }

    uint64_t parseSessionID(const std::string& str) {
      return base64Decode(str);
    }

    // Utility functions for reading and writing to the file /dev/urandom.
    std::vector<uint8_t> readEntropyFromFile(const std::string& filename) {
      std::ifstream entropy_file(filename, std::ios::binary);
      if (!entropy_file) {
        throw std::runtime_error("Error reading entropy from " + filename + ": " + strerror(errno));
      }

      std::vector<uint8_t> entropy;
      entropy_file.seekg(0, std::ios::end);
      size_t file_size = entropy_file.tellg();
      entropy_file.seekg(0, std::ios::beg);

      if (file_size >= 256) { // Read at least 256 bytes of entropy from /dev/urandom.
        entropy.resize(file_size);
        entropy_file.read((char*)&entropy[0], file_size);
        entropy_file.close();
      } else {
        throw std::runtime_error("Insufficient entropy in " + filename);
      }

      return entropy;
    }
  };
}
