#include <openssl/rand.h>
#include <openssl/x509v3.h>

// Define constants for the ciphers and modes supported by the function
#define CIPHER_AES_256_CBC 1
#define CIPHER_RSA_OAEP 2
#define MODE_ECB 0
#define MODE_CBC 1

// Define a struct to hold information about the encryption process
typedef struct {
    EVP_CIPHER_CTX *ctx; // The OpenSSL cipher context object
    unsigned char key[32]; // The encryption key (32 bytes)
    int cipher; // The cipher algorithm used for encryption
    int mode; // The encryption mode (ECB or CBC)
} EncryptionContext;

// Define a function to initialize the encryption context
void initEncryption(EncryptionContext *ctx, int cipher, int mode) {
    ctx->cipher = cipher;
    ctx->mode = mode;

    // Set up the encryption key using OpenSSL functions
    RAND_bytes(ctx->key, 32);
}

// Define a function to encrypt a file chunk by chunk
int encryptFile(const char *filePath, const char *outputPath) {
    // Open the input file and check for errors
    FILE *input = fopen(filePath, "rb");
    if (input == NULL) {
        printf("Error opening input file: %s\n", strerror(errno));
        return 1;
    }

    // Open the output file and check for errors
    FILE *output = fopen(outputPath, "wb");
    if (output == NULL) {
        printf("Error opening output file: %s\n", strerror(errno));
        return 1;
    }

    // Set up the encryption context using the chosen cipher and mode
    EncryptionContext ctx;
    initEncryption(&ctx, CIPHER_AES_256_CBC, MODE_CBC);

    // Read the input file in chunks and encrypt each chunk using OpenSSL functions
    unsigned char buffer[4096];
    int bytesRead;
    while ((bytesRead = fread(buffer, 1, sizeof(buffer), input)) > 0) {
        EVP_EncryptUpdate(&ctx.ctx, buffer, &bytesRead, buffer, bytesRead);
    }

    // Finalize the encryption and write the output to the file
    int finalBytes = 0;
    EVP_EncryptFinal(&ctx.ctx, buffer, &finalBytes);
    fwrite(buffer, 1, finalBytes, output);

    // Clean up the encryption context and close the files
    EVP_CIPHER_CTX_cleanup(&ctx.ctx);
    fclose(input);
    fclose(output);

    return 0;
}

// Define a function to handle command line options for the cipher and mode
int parseCommandLineOptions(const char *cipher, const char *mode) {
    // Validate the input options and set up the encryption context
    if (strcmp(cipher, "aes-256-cbc") == 0) {
        initEncryption(&ctx, CIPHER_AES_256_CBC, MODE_CBC);
    } else if (strcmp(cipher, "rsa-oaep") == 0) {
        initEncryption(&ctx, CIPHER_RSA_OAEP, MODE_ECB);
    } else {
        printf("Error: Invalid cipher option\n");
        return 1;
    }

    if (strcmp(mode, "ecb") == 0) {
        ctx.mode = MODE_ECB;
    } else if (strcmp(mode, "cbc") == 0) {
        ctx.mode = MODE_CBC;
    } else {
        printf("Error: Invalid mode option\n");
        return 1;
    }

    return 0;
}

// Define a function to handle the encryption process and output to file
int main(int argc, char **argv) {
    // Validate input parameters and set up the encryption context
    if (argc != 3) {
        printf("Usage: %s <input_file> <output_file>\n", argv[0]);
        return 1;
    }

    const char *inputFile = argv[1];
    const char *outputFile = argv[2];

    EncryptionContext ctx;
    initEncryption(&ctx, CIPHER_AES_256_CBC, MODE_ECB);

    // Read the input file and encrypt it chunk by chunk
    FILE *input = fopen(inputFile, "rb");
    if (input == NULL) {
        printf("Error opening input file: %s\n", strerror(errno));
        return 1;
    }

    // Set up the output file and check for errors
    FILE *output = fopen(outputFile, "wb");
    if (output == NULL) {
        printf("Error opening output file: %s\n", strerror(errno));
        return 1;
    }

    // Read the input file in chunks and encrypt each chunk using OpenSSL functions
    unsigned char buffer[4096];
    int bytesRead;
    while ((bytesRead = fread(buffer, 1, sizeof(buffer), input)) > 0) {
        EVP_EncryptUpdate(&ctx.ctx, buffer, &bytesRead, buffer, bytesRead);
    }

    // Finalize the encryption and write the output to the file
    int finalBytes = 0;
    EVP_EncryptFinal(&ctx.ctx, buffer, &finalBytes);
    fwrite(buffer, 1, finalBytes, output);

    // Clean up the encryption context and close the files
    EVP_CIPHER_CTX_cleanup(&ctx.ctx);
    fclose(input);
    fclose(output);

    return 0;
}
