using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using Microsoft.Extensions.DependencyInjection;

public static class DataLoader
{
    public static T LoadData<T>(string fileName, IServiceProvider serviceProvider) where T : class
    {
        var filePath = Path.Combine(Environment.CurrentDirectory, "data", fileName);
        if (!File.Exists(filePath))
        {
            throw new FileNotFoundException($"The data file '{fileName}' could not be found.");
        }

        using (var stream = File.OpenRead(filePath))
        {
            var formatter = serviceProvider.GetRequiredService<BinaryFormatter>();
            return (T)formatter.Deserialize(stream);
        }
    }
}
