using System;
using System.Text;
using System.Security.Cryptography;
using System.Web;
using System.IO;
using System.Collections.Generic;

public class HttpPostHandler {
    private readonly string _key;
    private readonly string _iv;
    private readonly List<string> _whitelist;
    private readonly Dictionary<int, DateTime> _rateLimits;

    public HttpPostHandler(string key, string iv, List<string> whitelist) {
        _key = key;
        _iv = iv;
        _whitelist = whitelist;
        _rateLimits = new Dictionary<int, DateTime>();
    }

    public void HandlePostRequest(int pageSectionId, int elementId, string htmlContent) {
        if (IsRateLimited(pageSectionId)) {
            return;
        }

        try {
            var decryptedHtml = DecryptHtml(htmlContent);
            var sanitizedHtml = SanitizeHtml(decryptedHtml);
            UpdateElementHtml(pageSectionId, elementId, sanitizedHtml);
        } catch (Exception e) {
            Console.WriteLine($"Error updating HTML content: {e}");
        }
    }

    private bool IsRateLimited(int pageSectionId) {
        var now = DateTime.Now;
        if (_rateLimits.TryGetValue(pageSectionId, out var lastUpdated)) {
            if (now - lastUpdated < TimeSpan.FromMinutes(1)) {
                return true;
            }
        }

        _rateLimits[pageSectionId] = now;
        return false;
    }

    private string DecryptHtml(string encryptedHtml) {
        var tripleDes = new TripleDESCryptoServiceProvider();
        var decryptedBytes = tripleDes.CreateDecryptor(_key, _iv).TransformFinalBlock(Convert.FromBase64String(encryptedHtml), 0, encryptedHtml.Length);
        return Encoding.UTF8.GetString(decryptedBytes);
    }

    private string SanitizeHtml(string html) {
        var sanitizer = new HtmlSanitizer();
        var allowedTags = _whitelist.Select(x => x.ToLower()).ToList();
        var allowedAttributes = _whitelist.SelectMany(x => x.Split(',')).Select(y => y.Trim().ToLower());
        return sanitizer.Sanitize(html, allowedTags, allowedAttributes);
    }

