// Define the octree node structure
struct OctreeNode {
    int x, y, z; // Coordinates of the node in 3D space
    std::vector<std::pair<int, int>> dataPoints; // List of data points stored in this node
    std::mutex mtx; // Mutex for thread safety
    OctreeNode* parent = nullptr; // Pointer to the parent node
    OctreeNode* children[8] = {nullptr}; // Array of child nodes (if any)
};

// Define the octree structure
struct Octree {
    int numNodes = 0; // Number of nodes in the tree
    int maxDepth = 0; // Maximum depth of the tree
    std::vector<OctreeNode*> nodes; // List of all nodes in the tree
};

// Function to initialize the octree
void initOctree(Octree& tree, const int numNodes, const int maxDepth) {
    tree.numNodes = 0;
    tree.maxDepth = maxDepth;
    tree.nodes.resize(numNodes); // Pre-allocate memory for all nodes
}

// Function to insert a data point into the octree
void insertDataPoint(Octree& tree, const int x, const int y, const int z, const int data) {
    // Find the node that contains the data point
    OctreeNode* node = findNode(tree, x, y, z);
    if (node == nullptr) {
        // If no node is found, create a new one at the root of the tree
        node = new OctreeNode();
        node->x = x;
        node->y = y;
        node->z = z;
        node->dataPoints.push_back(std::make_pair(data, 1)); // Store the data point with a count of 1
        tree.nodes[tree.numNodes++] = node; // Add the new node to the list of nodes in the tree
    } else {
        // If a node is found, increment the count for the data point
        bool foundDataPoint = false;
        for (int i = 0; i < node->dataPoints.size(); i++) {
            if (node->dataPoints[i].first == data) {
                node->dataPoints[i].second++; // Increment the count of the data point
                foundDataPoint = true;
                break;
            }
        }
        if (!foundDataPoint) {
            node->dataPoints.push_back(std::make_pair(data, 1)); // Store the new data point with a count of 1
        }
    }
}

// Function to find the node that contains the specified coordinates
OctreeNode* findNode(const Octree& tree, const int x, const int y, const int z) {
    std::vector<OctreeNode*> nodesToSearch; // List of nodes to search
    nodesToSearch.push_back(&tree.nodes[0]); // Start with the root node
    while (!nodesToSearch.empty()) {
        OctreeNode* currentNode = nodesToSearch.back();
        nodesToSearch.pop_back();
        if (currentNode->x == x && currentNode->y == y && currentNode->z == z) {
            return currentNode; // Return the found node
        } else if (currentNode->children[0] != nullptr) {
            for (int i = 0; i < 8; i++) {
                OctreeNode* childNode = currentNode->children[i];
                if (childNode != nullptr) {
                    nodesToSearch.push_back(childNode); // Add the child node to the list of nodes to search
                }
            }
        }
    }
    return nullptr; // Return null if no node is found
}

// Function to split a node into eight sub-nodes if its data capacity would be exceeded by more than 20%
void splitNode(Octree& tree, OctreeNode* node) {
    int newSize = node->dataPoints.size() + 1; // Calculate the new size of the node
    if (newSize > (node->maxSize * 1.2)) {
        for (int i = 0; i < 8; i++) {
            OctreeNode* childNode = new OctreeNode();
            childNode->parent = node;
            childNode->x = node->x + ((i % 2) * node->size);
            childNode->y = node->y + (((i / 2) % 2) * node->size);
            childNode->z = node->z + ((i / 4) * node->size);
            childNode->maxSize = node->maxSize;
            childNode->dataPoints.reserve(node->maxSize); // Pre-allocate memory for the data points in the child node
            childNode->children[0] = new OctreeNode();
            childNode->children[1] = new OctreeNode();
            childNode->children[2] = new OctreeNode();
            childNode->children[3] = new OctreeNode();
            childNode->children[4] = new OctreeNode();
            childNode->children[5] = new OctreeNode();
            childNode->children[6] = new OctreeNode();
            childNode->children[7] = new OctreeNode();
            for (int j = 0; j < node->dataPoints.size(); j++) {
                int data = node->dataPoints[j].first;
                if (data > childNode->maxSize) {
                    childNode->children[7]->dataPoints.push_back(std::make_pair(data, 1)); // Store the data point with a count of 1 in the new child node
                } else {
                    childNode->dataPoints.push_back(std::make_pair(data, 1)); // Store the data point with a count of 1 in the current child node
                }
            }
        }
        for (int i = 0; i < node->children[0]->dataPoints.size(); i++) {
            int data = node->children[0]->dataPoints[i].first;
            if (data > childNode->maxSize) {
                childNode->children[7]->dataPoints.push_back(std::make_pair(data, 1)); // Store the data point with a count of 1 in the new child node
            } else {
                childNode->dataPoints.push_back(std::make_pair(data, 1)); // Store the data point with a count of 1 in the current child node
            }
        }
    }
}

// Function to remove a node and its children from the tree if it is not needed anymore
void removeNode(Octree& tree, OctreeNode* node) {
    std::vector<OctreeNode*> nodesToRemove; // List of nodes to remove
    nodesToRemove.push_back(node); // Start with the specified node
    while (!nodesToRemove.empty()) {
        OctreeNode* currentNode = nodesToRemove.back();
        nodesToRemove.pop_back();
        for (int i = 0; i < 8; i++) {
            if (currentNode->children[i] != nullptr) {
                nodesToRemove.push_back(currentNode->children[i]); // Add the child node to the list of nodes to remove
            }
        }
    }
}

// Function to traverse the tree and print the contents of each node
void traverseTree(const Octree& tree) {
    for (int i = 0; i < tree.nodes[0].children[0]->dataPoints.size(); i++) {
