// Function to read integers from file and calculate largest integer and average
void processFile(const std::string& filename) {
  // Open the file in binary mode to avoid issues with end-of-line characters
  std::ifstream file(filename, std::ios::binary);

  if (!file.is_open()) {
    std::cerr << "Error: Could not open file: " << filename << std::endl;
    return;
  }

  // Use a vector to store the integers in the file
  std::vector<int> integers;

  // Read each line of the file and add the integer to the vector
  while (file.good()) {
    int value = 0;
    file >> value;
    if (file.fail()) {
      break;
    }
    integers.push_back(value);
  }

  // Calculate the largest and average of the integers in the vector
  int largest = INT_MIN;
  double average = 0;
  for (const auto& integer : integers) {
    if (integer > largest) {
      largest = integer;
    }
    average += integer;
  }
  average /= integers.size();

  // Print the results
  std::cout << "Largest integer in file: " << largest << std::endl;
  std::cout << "Average of all integers: " << average << std::endl;
}

// Command-line interface to call processFile function with filename as parameter
int main(int argc, char* argv[]) {
  if (argc != 2) {
    std::cerr << "Usage: " << argv[0] << " <filename>" << std::endl;
    return 1;
  }

  processFile(argv[1]);

  return 0;
}
