#include <semaphore.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>
#include <errno.h>
#include <sys/time.h>
#include <sys/types.h>
#include <unistd.h>

// Define the semaphore structure to hold the semaphore handle and value
struct Semaphore {
    int value;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
};

// Create a new semaphore with the specified initial value
int createSemaphore(struct Semaphore *sem, int initVal) {
    // Initialize the semaphore structure with the initial value and mutex/cond variables
    sem->value = initVal;
    pthread_mutex_init(&(sem->mutex), NULL);
    pthread_cond_init(&(sem->cond), NULL);

    return 0;
}

// Delete the semaphore and clean up resources
int deleteSemaphore(struct Semaphore *sem) {
    // Destroy the mutex/cond variables and free the memory used by the semaphore structure
    pthread_mutex_destroy(&(sem->mutex));
    pthread_cond_destroy(&(sem->cond));
    free(sem);

    return 0;
}

// Wait for the semaphore to become available, with a timeout in milliseconds
int sem_wait(struct Semaphore *sem, int timeout) {
    // Check if the semaphore value is negative (i.e., there are pending threads waiting)
    if (sem->value < 0) {
        // If so, wait for the condition variable to be signaled by another thread
        pthread_mutex_lock(&(sem->mutex));
        while (sem->value < 0) {
            int ret = pthread_cond_wait(&(sem->cond), &(sem->mutex));
            if (ret != 0) {
                // Handle error
            }
        }
        pthread_mutex_unlock(&(sem->mutex));
    }

    // Decrement the semaphore value and return success
    --(sem->value);
    return 0;
}

// Post to the semaphore, increasing its value by one
int sem_post(struct Semaphore *sem) {
    // Lock the mutex variable
    pthread_mutex_lock(&(sem->mutex));

    // Increment the semaphore value and signal the condition variable if it was negative (i.e., there were waiting threads)
    ++(sem->value);
    if (sem->value < 0) {
        int ret = pthread_cond_signal(&(sem->cond));
        if (ret != 0) {
            // Handle error
        }
    }

    // Unlock the mutex variable
    pthread_mutex_unlock(&(sem->mutex));

    return 0;
}

// Get the current value of the semaphore
int sem_getvalue(struct Semaphore *sem, int *value) {
    // Lock the mutex variable
    pthread_mutex_lock(&(sem->mutex));

    // Set the output parameter to the current semaphore value
    *value = sem->value;

    // Unlock the mutex variable
    pthread_mutex_unlock(&(sem->mutex));

    return 0;
}
