using System.Threading.Tasks;

namespace DataPointGenerator
{
    public class DataPointGenerator
    {
        private readonly double minimumValue;
        private readonly double maximumValue;

        public DataPointGenerator(double minimumValue, double maximumValue)
        {
            this.minimumValue = minimumValue;
            this.maximumValue = maximumValue;
        }

        public IEnumerable<float> GenerateRandomFloatValues(int count)
        {
            return Enumerable.Range(0, count).Select(i => (float)(random.NextDouble() * (maximumValue - minimumValue)) + minimumValue);
        }

        public IEnumerable<int> GenerateRandomIntegerValues(int count)
        {
            return Enumerable.Range(0, count).Select(i => random.Next((int)minimumValue, (int)maximumValue + 1));
        }

        public IEnumerable<string> SelectMatchingElements(HtmlNode node, string cssSelector)
        {
            if (node == null)
                throw new ArgumentNullException(nameof(node));

            if (cssSelector == null)
                throw new ArgumentNullException(nameof(cssSelector));

            var matchingElements = new List<string>();

            foreach (var element in node.ChildNodes.SelectMany(child => child.DescendantNodes()))
            {
                if (element is HtmlElement htmlElement && htmlElement.Attributes["class"] != null)
                {
                    if (htmlElement.Attributes["class"].Value.Split(' ').Any(c => c == cssSelector))
                        matchingElements.Add(element.OuterHtml);
                }
                else if (element is HtmlElement htmlElement && htmlElement.Id != null)
                {
                    if (htmlElement.Attributes["id"].Value == cssSelector)
                        matchingElements.Add(element.OuterHtml);
                }
            }

            return matchingElements;
        }

        public override string ToString()
        {
            return $"Range: [{minimumValue}, {maximumValue}]";
        }

        private void ValidateInputRange(double minimumValue, double maximumValue)
        {
            if (minimumValue > maximumValue)
                throw new ArgumentException("The specified range is invalid. The minimum value must be less than or equal to the maximum value.");
        }
    }
}
