#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <rapidjson/document.h>
#include <rapidjson/writer.h>
#include <rapidjson/stringbuffer.h>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

using namespace std;

struct Node {
    int key;
    string value;
};

class NodeArray {
public:
    // Constructor to initialize the array with a certain size
    NodeArray(size_t size) : nodes_(size, {0, ""}) {}

    // Adds a node to the end of the array
    void addNode(int key, string value) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (nodes_.size() == nodes_.capacity()) {
            resizeArray();
        }
        nodes_.push_back({key, value});
    }

    // Removes a node from the array by key
    void removeNode(int key) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto it = nodes_.begin(); it != nodes_.end(); ++it) {
            if (it->key == key) {
                nodes_.erase(it);
                return;
            }
        }
    }

    // Updates a node in the array by key
    void updateNode(int key, string value) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto& node : nodes_) {
            if (node.key == key) {
                node.value = value;
                return;
            }
        }
    }

    // Returns the serialized JSON representation of the array
    string serialize() {
        rapidjson::Document doc;
        rapidjson::Value nodes(rapidjson::kArrayType);
        for (const auto& node : nodes_) {
            rapidjson::Value obj(rapidjson::kObjectType);
            obj.AddMember("key", rapidjson::Value().SetInt(node.key), doc.GetAllocator());
            obj.AddMember("value", rapidjson::Value().SetString(node.value.c_str(), doc.GetAllocator()), doc.GetAllocator());
            nodes.PushBack(obj, doc.GetAllocator());
        }
        return doc.Accept(rapidjson::Writer<rapidjson::StringBuffer>(nodes));
    }

    // Deserializes the JSON representation of the array
    void deserialize(string json) {
        rapidjson::Document doc;
        doc.Parse(json);
        for (const auto& node : doc["nodes"].GetArray()) {
            int key = node["key"].GetInt();
            string value = node["value"].GetString();
            addNode(key, value);
        }
    }

private:
    // Resizes the array to a certain size
    void resizeArray() {
        std::lock_guard<std::mutex> lock(mutex_);
        nodes_.reserve(nodes_.size() * 2);
    }

    vector<Node> nodes_;
    mutex mutex_;
};

int main() {
    // Initialize the node array with a certain size
    NodeArray arr(10);

    // Add, remove, and update nodes in the array
    arr.addNode(1, "value1");
    arr.addNode(2, "value2");
