    this.client = new OkHttpClient();
    this.executor = Executors.newFixedThreadPool(THREAD_POOL_SIZE);
  }

  private Map<String, List<String>> loadWeaknessesMapping() {
    try (InputStream inputStream = getClass().getResourceAsStream(WEAKNESS_MAPPING_FILE)) {
      JSONObject jsonObj = new JSONObject(inputStream);
      Map<String, List<String>> weaknessesMap = new HashMap<>();

      for (String type : jsonObj.keySet()) {
        String weaknessesStr = jsonObj.getString(type);
        List<String> weaknessesList = Arrays.asList(weaknessesStr.split(","));
        weaknessesMap.put(type, weaknessesList);
      }

      return weaknessesMap;
    } catch (IOException | JSONException e) {
      e.printStackTrace();
      return null;
    }
  }

  public List<Pokemon> getPokemons() {
    List<Pokemon> pokemons = new ArrayList<>();

    try {
      URL url = new URL("https://pokeapi.co/api/v2/pokemon");
      HttpURLConnection connection = (HttpURLConnection) url.openConnection();
      connection.setRequestMethod("GET");

      int responseCode = connection.getResponseCode();
      if (responseCode == 200) {
        InputStream inputStream = connection.getInputStream();
        JSONObject jsonObj = new JSONObject(inputStream);

        for (String type : jsonObj.keySet()) {
          Pokemon pokemon = new Pokemon(type, jsonObj.getString("name"), jsonObj.getString("evolution_chain"));
          pokemons.add(pokemon);
        }
      } else {
        System.out.println("Error: " + responseCode);
      }

    } catch (IOException | JSONException e) {
      e.printStackTrace();
    }

    return pokemons;
  }

  public void generateReport(List<Pokemon> pokemons) {
    String report = "<html><head></head><body>";

    for (Pokemon pokemon : pokemons) {
      report += "<h2>" + pokemon.getName() + "</h2>";

      List<String> weaknessesList = getWeaknesses(pokemon);
      if (!weaknessesList.isEmpty()) {
        report += "<ul>";
        for (String weakness : weaknessesList) {
          report += "<li>" + weakness + "</li>";
        }
        report += "</ul>";
      } else {
        report += "No known weaknesses.";
      }

      report += "<br><br>";
    }

    report += "</body></html>";
    System.out.println(report);
  }

  private List<String> getWeaknesses(Pokemon pokemon) {
