public class SecureCipherService
{
    private const string OAuth2TokenEndpoint = "https://auth-server.com/token";
    private const string AesDecryptionKey = "your_aes_decryption_key_here";
    private const string AesEncryptionIv = "your_aes_encryption_iv_here";

    private readonly HttpClient _httpClient;
    private readonly Dictionary<string, string> _tokenCache = new Dictionary<string, string>();

    public SecureCipherService()
    {
        _httpClient = new HttpClient();
    }

    public async Task<byte[]> DecryptMessageAsync(byte[] ciphertext, byte[] encryptionKey, byte[] iv)
    {
        // Validate input lengths
        if (ciphertext.Length % 16 != 0 || encryptionKey.Length != 32 || iv.Length != 16)
        {
            throw new ArgumentException("Invalid input length");
        }

        // Retrieve token from cache or refresh if about to expire
        string accessToken;
        if (!_tokenCache.TryGetValue("access_token", out accessToken))
        {
            var tokenRequest = new HttpRequestMessage(HttpMethod.Post, OAuth2TokenEndpoint);
            tokenRequest.Content = new FormUrlEncodedContent(new[]
            {
                new KeyValuePair<string, string>("grant_type", "client_credentials"),
                new KeyValuePair<string, string>("scope", "decrypt")
            });
            var tokenResponse = await _httpClient.SendAsync(tokenRequest);
            if (!tokenResponse.IsSuccessStatusCode)
            {
                throw new Exception($"Error retrieving access token: {tokenResponse.ReasonPhrase}");
            }

            var tokenJson = JsonConvert.DeserializeObject<OAuth2Token>(await tokenResponse.Content.ReadAsStringAsync());
            accessToken = tokenJson.AccessToken;
        }

        // Cache token for future use
        _tokenCache["access_token"] = accessToken;

        // Decrypt ciphertext using AES-CBC with authentication tag
        var decryptionKey = new Key(encryptionKey);
        var iv = new IV(iv);
        var aesDecryptor = new AesCbcDecryptor(decryptionKey, iv);
        var plaintext = await aesDecryptor.DecryptAsync(ciphertext, true);

        // Check for padding oracle attacks and throw exception if detected
        if (!IsValidPadding(plaintext))
        {
            throw new Exception("Invalid padding detected");
        }

        return plaintext;
    }

    private bool IsValidPadding(byte[] plaintext)
    {
        // Implement padding oracle protection here
    }

    public async Task<byte[]> DecryptMessageAsync(byte[] ciphertext, byte[] encryptionKey, byte[] iv, int offset)
    {
        // Resume decryption from the specified offset
        var partialDecrypter = new PartialAesCbcDecrypter(encryptionKey, iv, offset);
        return await partialDecrypter.DecryptAsync(ciphertext, true);
    }

    private class OAuth2Token
    {
        public string AccessToken { get; set; }
        public int ExpiresIn { get; set; }
        public string TokenType { get; set; }
        public string Scope { get; set; }
    }
}
```
