import os
import logging
import csv
from datetime import datetime
from typing import Dict, List, Optional

logger = logging.getLogger(__name__)

class FileStatistics:
    def __init__(self):
        self.total_lines = 0
        self.total_words = 0
        self.total_characters = 0
        self.file_types = {}

    def add_line(self, line: str) -> None:
        """Adds a line to the statistics."""
        self.total_lines += 1
        self.total_words += len(line.split())
        self.total_characters += len(line)

    def add_file(self, file: str) -> None:
        """Adds a file to the statistics."""
        with open(file, "r", encoding="utf-8") as f:
            for line in f:
                self.add_line(line)

    def get_stats(self) -> Dict[str, int]:
        """Returns the current statistics as a dictionary."""
        return {
            "total_lines": self.total_lines,
            "total_words": self.total_words,
            "total_characters": self.total_characters,
        }

class CSVStatistics:
    def __init__(self):
        self.columns = []
        self.data = {}

    def add_column(self, column_name: str) -> None:
        """Adds a column to the statistics."""
        if column_name not in self.columns:
            self.columns.append(column_name)
            self.data[column_name] = []

    def add_row(self, row: List[str]) -> None:
        """Adds a row to the statistics."""
        for i, column in enumerate(row):
            self.add_column(column)
            self.data[column].append(row[i])

    def get_stats(self) -> Dict[str, List[str]]:
        """Returns the current statistics as a dictionary."""
        return {column: self.data[column] for column in self.columns}

class FileProcessor:
    def __init__(self, exclude: Optional[List[str]] = None):
        self.exclude = exclude or []
        self.statistics = FileStatistics()
        self.csv_statistics = CSVStatistics()

    def process_file(self, file: str) -> None:
        """Processes a single file and updates the statistics."""
        if os.path.splitext(file)[1] in [".txt", ".log"]:
            self.statistics.add_file(file)
        elif os.path.splitext(file)[1] == ".csv":
            with open(file, "r", encoding="utf-8") as f:
                reader = csv.reader(f)
                header = next(reader)
                self.csv_statistics.add_column(header[0])
                for row in reader:
                    self.csv_statistics.add_row(row)
        else:
            logger.warning("Unsupported file type: %s", file)

    def get_stats(self) -> Dict[str, int]:
        """Returns the current statistics as a dictionary."""
        return self.statistics.get_stats()

    def get_csv_stats(self) -> Dict[str, List[str]]:
        """Returns the CSV statistics as a dictionary."""
        return self.csv_statistics.get_stats()

class FileManager:
    def __init__(self):
        self.files = []

    def add_file(self, file: str) -> None:
        """Adds a file to the list of files."""
        if file not in self.files:
            self.files.append(file)

    def get_files(self) -> List[str]:
        """Returns the list of files."""
        return self.files

class FileProcessorPlugin:
    def __init__(self, plugin_name: str):
        self.plugin_name = plugin_name

    def process_file(self, file: str) -> None:
        """Processes a single file and updates the statistics."""
        logger.info("Processing file %s with plugin %s", file, self.plugin_name)
        # Implement specific logic for each plugin here

class FileProcessorApp:
    def __init__(self):
        self.file_manager = FileManager()
        self.processors = {}

    def add_processor(self, name: str, processor: FileProcessorPlugin) -> None:
        """Adds a file processor plugin to the application."""
        self.processors[name] = processor

    def process_files(self, directory: str, exclude: Optional[List[str]] = None) -> Dict[str, int]:
        """Processes all files in the specified directory and updates the statistics."""
        if not os.path.isdir(directory):
            raise ValueError("Invalid directory path")
        self.file_manager.add_file(directory)
        for file in os.listdir(directory):
            file = os.path.join(directory, file)
            if os.path.isfile(file) and file not in exclude:
                processor = self.processors.get(os.path.splitext(file)[1][1:])
                if processor is not None:
                    processor.process_file(file)
                else:
                    logger.warning("Unsupported file type: %s", file)
        return self.file_manager.get_files()
