#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <algorithm>
#include <iterator>
#include <cstdlib>
#include <thread>
#include <mutex>

using namespace std;

int main(int argc, char* argv[]) {
    // Validate command-line parameters
    if (argc < 2) {
        cerr << "Usage: " << argv[0] << " <input files>" << endl;
        return 1;
    }

    // Initialize variables for processing
    vector<int> integers;
    int largest = INT_MIN;
    long sum = 0;
    long count = 0;

    // Process input files concurrently using threads
    mutex mtx;
    thread t[argc - 1];
    for (int i = 1; i < argc; ++i) {
        t[i - 1] = thread([&]() {
            ifstream file(argv[i]);
            int num;
            while (file >> num) {
                mtx.lock();
                integers.push_back(num);
                sum += num;
                ++count;
                largest = max(largest, num);
                mtx.unlock();
            }
        });
    }

    // Wait for all threads to finish
    for (auto& t : t) {
        if (t.joinable()) {
            t.join();
        }
    }

    // Report progress and calculate average
    cerr << "Processed " << count << " integers." << endl;
    double avg = static_cast<double>(sum) / count;
    cout << "Largest integer: " << largest << endl;
    cout << "Average: " << avg << endl;

    return 0;
}
