  function FieldRefreshService($http, $q) {
    var service = this;

    // Array of field names to be refreshed
    var fieldsToRefresh = [];

    // Map of field IDs to their corresponding REST API URLs
    var fieldIdUrlMap = {};

    // Function to identify fields that need to be refreshed based on the provided array of field names
    service.identifyFields = function(fieldNames) {
      fieldsToRefresh = [];

      angular.forEach(fieldNames, function(fieldName) {
        var fieldId = getFieldIdFromName(fieldName);

        if (fieldId !== null) {
          fieldsToRefresh.push(fieldId);
        }
      });
    };

    // Function to send messages to an external service (e.g., REST API) to fetch updated data for each field
    service.fetchUpdatedData = function() {
      var deferred = $q.defer();

      angular.forEach(fieldsToRefresh, function(fieldId) {
        // Send message to external service to fetch updated data for the current field
        $http({
          method: 'GET',
          url: fieldIdUrlMap[fieldId]
        }).then(function(response) {
          // Handle successful response
          deferred.resolve();
        }, function(error) {
          // Handle error response
          deferred.reject(error);
        });
      });

      return deferred.promise;
    };

    // Function to handle various error scenarios, including network failures, incorrect field names, and unexpected responses from the external service
    service.handleError = function(error) {
      console.log('Error refreshing fields:', error);

      if (error.status === 0) {
        // Network failure occurred
        deferred.reject('Network error occurred while fetching updated data');
      } else if (error.data && error.data.message) {
        // Error message returned from the external service
        deferred.reject(error.data.message);
      } else {
        // Unexpected response from the external service
        deferred.reject('Unexpected error occurred while fetching updated data');
      }
    };

    // Function to support concurrent processing of multiple fields to improve user experience during refresh operations
    service.concurrentlyRefreshFields = function(fields) {
      var promises = [];

      angular.forEach(fields, function(field) {
        promises.push(service.fetchUpdatedData(field));
