#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <json-parser.h>

// Struct to store the cached OAuth2 access tokens
struct TokenCache {
    char* token;
    int expires_in;
    bool is_valid;
};

// Global cache of OAuth2 access tokens
TokenCache* token_cache = NULL;
size_t token_cache_size = 0;

// Function to add a new entry to the cache or update an existing one
void cache_token(char* token, int expires_in) {
    TokenCache* new_entry = malloc(sizeof(TokenCache));
    new_entry->token = strdup(token);
    new_entry->expires_in = expires_in;
    new_entry->is_valid = true;

    // Check if the cache is full and needs to be resized
    if (token_cache_size >= MAX_TOKEN_CACHE_SIZE) {
        TokenCache* old_entry = token_cache[0];
        for (int i = 1; i < token_cache_size; i++) {
            if (!token_cache[i].is_valid) {
                free(old_entry);
                break;
            } else {
                old_entry = token_cache[i];
            }
        }
    }

    // Add the new entry to the cache or update an existing one
    if (token_cache == NULL) {
        token_cache_size++;
        token_cache = realloc(token_cache, sizeof(TokenCache) * token_cache_size);
    } else {
        for (int i = 0; i < token_cache_size; i++) {
            if (!strcmp(token_cache[i].token, new_entry->token)) {
                free(new_entry->token);
                new_entry->token = strdup(token_cache[i].token);
                new_entry->expires_in = token_cache[i].expires_in;
                new_entry->is_valid = true;
            }
        }
    }
}

// Function to check if a given OAuth2 access token is valid and return it if it is
char* check_token(char* token) {
    // Check if the token is in the cache
    for (int i = 0; i < token_cache_size; i++) {
        if (!strcmp(token, token_cache[i].token)) {
            return token_cache[i].token;
        }
    }

    // If the token is not in the cache, check it with the OAuth2 provider
    CURL* curl = curl_easy_init();
    if (curl) {
        struct curl_slist* headers = NULL;
        char* url = "https://oauth.example.com/token";
        char* json_data = "{\"access_token\":\"%s\", \"expires_in\":%d, \"token_type\":\"Bearer\"}";
        sprintf(json_data, token);
        headers = curl_slist_append(headers, "Content-Type: application/json");
        headers = curl_slist_append(headers, "Accept: application/json");
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_SSL_VERIFYPEER, 0L);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
        CURLcode res = curl_easy_perform(curl);

        if (res != CURLE_OK) {
            printf("Failed to check token: %s\n", curl_easy_strerror(res));
            return NULL;
        }

        long http_code = 0;
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
        if (http_code != 200) {
            printf("Failed to check token: HTTP status code %ld\n", http_code);
            return NULL;
        }

        // Parse the response JSON object
        json_t* json = json_loads(curl_easy_strerror(res), 0, &json_error);
        if (!json) {
            printf("Failed to parse token response: %s\n", json_error.text);
            return NULL;
        }

        // Check the token fields and cache it if valid
        int expires_in = 0;
        char* token_type = NULL;
        json_t* access_token = json_object_get(json, "access_token");
        json_t* token_expires_in = json_object_get(json, "expires_in");
        json_t* token_type = json_object_get(json, "token_type");
        if (!access_token || !token_expires_in || !token_type) {
            printf("Missing required fields in token response\n");
            return NULL;
        }

        if (strcmp(token_type, "Bearer")) {
            printf("Invalid token type %s\n", token_type);
            return NULL;
        }

        if (!json_is_integer(token_expires_in)) {
            printf("Expires in field is not an integer\n");
            return NULL;
        }

        expires_in = json_integer_value(token_expires_in);
        if (expires_in <= 0) {
            printf("Invalid expiration time %d\n", expires_in);
            return NULL;
        }

        cache_token(access_token, expires_in);
    }
}

// Function to construct a `RequestBuilder` for a given URL
CURL* request_builder(char* url) {
    // Check if the token is in the cache and return it if it's valid
    char* token = check_token();
    if (token != NULL) {
        CURL* curl = curl_easy_init();
        if (curl) {
            struct curl_slist* headers = NULL;
            headers = curl_slist_append(headers, "Authorization: Bearer %s", token);
            headers = curl_slist_append(headers, "Accept: application/json");
            curl_easy_setopt(curl, CURLOPT_URL, url);
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
            curl_easy_setopt(curl, CURLOPT_SSL_VERIFYPEER, 0L);
            return curl;
        }
    }
}

