struct Transaction {
    int id;
    long long weighted_sum;
};

struct Metrics {
    int num_transactions;
    long long max_weighted_sum;
    struct Transaction* transactions;
};

void filter_transactions(struct Metrics* metrics) {
    // Filter transactions based on the specified criteria
    for (int i = 0; i < metrics->num_transactions; i++) {
        if (metrics->transactions[i].age > 3 * 1000 ||
            metrics->transactions[i].weighted_sum > metrics->max_weighted_sum) {
            // Remove the transaction from the list of transactions
            struct Transaction* temp = &metrics->transactions[i];
            memcpy(&metrics->transactions[i], &metrics->transactions[i + 1],
                   sizeof(struct Transaction));
            metrics->num_transactions--;
        }
    }
}
