# Define the dependencies and imports
from flask import Flask, render_template, request, redirect, url_for, session, flash
from werkzeug.security import check_password_hash, generate_password_hash
from flask_sqlalchemy import SQLAlchemy
import os

# Define the database configuration
app = Flask(__name__)
app.config["SQLALCHEMY_DATABASE_URI"] = "sqlite:///db.sqlite3"
db = SQLAlchemy(app)

# Define the User model
class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    email = db.Column(db.String(100), unique=True)
    password = db.Column(db.String(100))
    role = db.Column(db.String(100))

# Define the Role model
class Role(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), unique=True)
    description = db.Column(db.String(255))

# Define the Permission model
class Permission(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), unique=True)
    description = db.Column(db.String(255))

# Define the UserRoles model
class UserRoles(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    user_id = db.Column(db.Integer, db.ForeignKey("user.id"))
    role_id = db.Column(db.Integer, db.ForeignKey("role.id"))

# Define the UserPermissions model
class UserPermissions(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    user_id = db.Column(db.Integer, db.ForeignKey("user.id"))
    permission_id = db.Column(db.Integer, db.ForeignKey("permission.id"))

# Define the cache configuration
app.config["CACHE_TYPE"] = "simple"
cache = Cache()

# Define the logging configuration
log = logging.getLogger('werkzeug')
log.setLevel(logging.DEBUG)
file_handler = logging.FileHandler('error.log')
file_handler.setFormatter(logging.Formatter('%(asctime)s %(levelname)s: %(message)s [in %(pathname)s:%(lineno)d]'))
file_handler.setLevel(logging.INFO)
app.logger.addHandler(file_handler)

# Define the login route
@app.route("/login", methods=["GET", "POST"])
def login():
    if request.method == "POST":
        email = request.form["email"]
        password = request.form["password"]
        user = User.query.filter_by(email=email).first()
        if user and check_password_hash(user.password, password):
            session["logged_in"] = True
            flash("Logged in successfully!")
            return redirect("/profile")
        else:
            flash("Invalid email or password!")
            return render_template("login.html")
    elif request.method == "GET":
        return render_template("login.html")

# Define the profile route
@app.route("/profile", methods=["GET", "POST"])
def profile():
    if request.method == "GET":
        user = User.query.filter_by(email=session["email"]).first()
        return render_template("profile.html", user=user)
    elif request.method == "POST":
        user = User.query.filter_by(email=session["email"]).first()
        if user:
            user.password = generate_password_hash(request.form["new_password"])
            db.session.commit()
            flash("Profile updated successfully!")
            return redirect("/profile")
        else:
            flash("Invalid email or password!")
            return render_template("login.html")

# Define the upload route
@app.route("/upload", methods=["POST"])
def upload():
    if "file" not in request.files:
        flash("No file part in the request")
        return redirect(request.url)
    file = request.files["file"]
    if file.filename == "":
        flash("No selected file")
        return redirect(request.url)
    if file and allowed_file(file.filename):
        filename = secure_filename(file.filename)
        f = open(os.path.join(app.config["UPLOAD_FOLDER"], filename), "wb")
        for chunk in file.chunks():
            f.write(chunk)
        f.close()
        flash("File successfully uploaded!")
        return redirect("/profile")
    else:
        flash("Invalid file type!")
        return render_template("upload.html")

# Define the allowed file types
def allowed_file(filename):
    return "." in filename and filename.rsplit(".", 1)[1].lower() in ALLOWED_EXTENSIONS

# Define the secure filename function
def secure_filename(filename):
    return "".join(c for c in filename if c not in ("\\", "/"))

# Define the logout route
@app.route("/logout")
def logout():
    session["logged_in"] = False
    flash("Logged out successfully!")
    return redirect("/login")

if __name__ == "__main__":
    app.run(debug=True)
