```rust
use std::env;
use std::fs::{DirBuilder, File};
use std::path::PathBuf;
use std::process::Command;
use std::thread;
use std::time::Duration;

struct FileManager {
    work_dir: String,
    cleanup_interval: u64,
}

impl FileManager {
    fn new() -> Self {
        let work_dir = env::var("WORK_DIR").unwrap_or_else(|_| "/tmp/".to_string());
        let cleanup_interval = 3600; // 1 hour in seconds

        FileManager { work_dir, cleanup_interval }
    }

    fn validate_work_dir(&self) -> Result<String, String> {
        let mut work_dir = self.work_dir.clone();

        if !File::exists(PathBuf::from(&work_dir)) {
            return Err(format!("Working directory '{}' does not exist", &work_dir));
        }

        if !self.has_permissions(&work_dir) {
            return Err(format!(
                "Insufficient permissions to access working directory '{}'",
                &work_dir
            ));
        }

        work_dir = self.cleanup_work_dir(&work_dir)?;

        Ok(work_dir)
    }

    fn cleanup_work_dir(&self, work_dir: &str) -> Result<String, String> {
        let mut file_list = vec![];

        for entry in std::fs::read_dir(work_dir).unwrap() {
            file_list.push(entry.unwrap().path());
        }

        if !file_list.is_empty() {
            self.delete_files(&file_list)?;
        }

        Ok(String::from(work_dir))
    }

    fn delete_files(&self, file_list: &[PathBuf]) -> Result<(), String> {
        for file in file_list {
            if let Err(e) = std::fs::remove_file(file) {
                return Err(format!("Failed to delete file '{}': {}", file.display(), e));
            }
        }

        Ok(())
    }

    fn has_permissions(&self, work_dir: &str) -> bool {
        let metadata = std::fs::metadata(work_dir).unwrap();
        let permissions = metadata.permissions().mode();
        permissions & 0o777 == 0o755
    }
}
