#include <iostream>
#include <string>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <future>
#include <chrono>

using namespace std;

// Octree Node Structure
struct OctreeNode {
    int x, y, z; // Coordinates of the node in the octree grid
    vector<int> data; // Vector to store spatial data points
    vector<OctreeNode*> children; // Pointers to child nodes
};

// Octree Class
class Octree {
public:
    Octree(int size) : root_(new OctreeNode()), size_(size) {}

    // Function to initialize the octree with a given size
    void init(int size);

    // Function to insert a spatial data point into the octree
    void insert(const int& x, const int& y, const int& z, const int& data);

    // Function to remove a spatial data point from the octree
    void remove(const int& x, const int& y, const int& z);

    // Function to query for a spatial data point in the octree
    vector<int> query(const int& x, const int& y, const int& z);

    // Function to rebalance the octree after a certain number of insertions or deletions
    void rebalance();

private:
    OctreeNode* root_; // Pointer to the root node of the octree
    int size_; // Size of the octree grid

    // Vector to store data points for query optimization
    vector<int> query_data;

    // Mutex and condition variable for thread-safe inserts and deletes
    mutex insert_mutex_, delete_mutex_;
    condition_variable insert_cv_, delete_cv_;

    // Queue for pending inserts and deletes
    queue<pair<int, int>> insert_queue_, delete_queue_;

    // Function to split a node into child nodes when its capacity is exceeded
    void splitNode(OctreeNode* node);

    // Function to merge child nodes into their parent node when they fall below a certain threshold
    void mergeNodes(vector<OctreeNode*>& nodes);

    // Function to update the bounding volume hierarchies (BVHs) for the octree
    void updateBVHs();
};
```
### External Data Source Integration
To integrate an external data source with the octree, you can create a separate thread that reads data points from the source and inserts them into the octree using the `insert` function. Here's an example of how to do this:
```cpp
// Create a new thread for reading data from the external source
auto t = std::thread([&]() {
    // Read data points from the external source
    vector<int> data_points;
    readDataPoints(data_points);

    // Insert data points into the octree
    for (const auto& point : data_points) {
        int x = point[0];
        int y = point[1];
        int z = point[2];
        int data = point[3];

        root_->insert(x, y, z, data);
    }
});

// Start the thread and wait for it to finish
t.detach();
```
### Dynamic Rebalancing
To implement dynamic rebalancing, you can use a configurable threshold to trigger the rebalance operation after a certain number of insertions or deletions. Here's an example of how to do this:
```cpp
// Set the threshold for triggering rebalancing
int rebalance_threshold = 10;

// Increment the counter for each insertion or deletion
insertion_count += 1;
deletion_count += 1;

// Check if the threshold has been reached
if (insertion_count >= rebalance_threshold || deletion_count >= rebalance_threshold) {
    // Rebalance the octree asynchronously in a separate thread
    auto t = std::thread([&]() { root_->rebalance(); });

    // Start the thread and wait for it to finish
    t.detach();
}
```
### Resource Management
To limit the maximum number of concurrent inserts and deletes, you can use a queue to manage these operations. Here's an example of how to do this:
```cpp
// Create a queue for pending inserts and deletes
queue<pair<int, int>> insert_queue_, delete_queue_;

// Lock the mutex for insertions and deletions
std::unique_lock<mutex> lock(insert_mutex_);

// Insert data points into the octree
for (const auto& point : data_points) {
    int x = point[0];
    int y = point[1];
    int z = point[2];
    int data = point[3];

    root_->insert(x, y, z, data);
}

// Unlock the mutex and notify all waiting threads
lock.unlock();
insert_cv_.notify_all();
```
### Custom Node Capacity
To set custom capacity limits for each octree node, you can use a vector to store the maximum number of data points allowed in each node. Here's an example of how to do this:
```cpp
// Vector to store the maximum number of data points allowed in each node
vector<int> node_capacity;

// Initialize the capacity for each node based on the given size
for (int i = 0; i < size_; ++i) {
    node_capacity.push_back(size_);
}
```
### Query Optimization
To optimize query performance by precomputing and storing bounding volume hierarchies (BVHs) for the octree, you can create a separate thread that updates the BVHs in the background. Here's an example of how to do this:
```cpp
// Create a new thread for updating the BVHs
auto t = std::thread([&]() {
    // Update the bounding volume hierarchies (BVHs) for the octree
    root_->updateBVHs();
});

// Start the thread and wait for it to finish
t.detach();
```
