Here are the function definitions for the `Octree` class:
```cpp
class Octree {
public:
    // Constructor
    Octree(int size);

    // Destructor
    ~Octree();

    // Insert a data point into the octree
    void insert(int x, int y, int z, int data);

    // Delete a data point from the octree
    void delete(int x, int y, int z);

    // Query the octree for all data points within a given bounding volume
    vector<pair<int, int>> query(int x_min, int x_max, int y_min, int y_max, int z_min, int z_max);

private:
    // The size of the octree
    int size_;

    // The root node of the octree
    OctreeNode* root_;

    // The maximum number of data points allowed in each node
    vector<int> node_capacity;

    // The bounding volume hierarchies (BVHs) for the octree
    vector<pair<int, int>> bvh_;

    // Function to split a node into child nodes when its capacity is exceeded
    void splitNode(OctreeNode* node);

    // Function to merge child nodes into their parent node when they fall below a certain threshold
    void mergeNodes(vector<OctreeNode*>& nodes);

    // Function to update the bounding volume hierarchies (BVHs) for the octree
    void updateBVHs();
};
