```csharp
using System;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Identity;
using Microsoft.Extensions.Logging;
using MyProject.Models;
using MyProject.Services;

namespace MyProject.Controllers
{
    public class UserAccountController : ControllerBase
    {
        private readonly ILogger<UserAccountController> _logger;
        private readonly UserManager<ApplicationUser> _userManager;
        private readonly SignInManager<ApplicationUser> _signInManager;
        private readonly IPasswordValidator<ApplicationUser> _passwordValidator;
        private readonly ILockoutService<ApplicationUser> _lockoutService;
        private readonly IMfaService _mfaService;

        public UserAccountController(ILogger<UserAccountController> logger, UserManager<ApplicationUser> userManager, SignInManager<ApplicationUser> signInManager, IPasswordValidator<ApplicationUser> passwordValidator, ILockoutService<ApplicationUser> lockoutService, IMfaService mfaService)
        {
            _logger = logger;
            _userManager = userManager;
            _signInManager = signInManager;
            _passwordValidator = passwordValidator;
            _lockoutService = lockoutService;
            _mfaService = mfaService;
        }

        [HttpPost]
        public async Task<IActionResult> CreateUser([FromBody] UserCreateModel model)
        {
            if (!ModelState.IsValid)
            {
                return BadRequest(ModelState);
            }

            var user = new ApplicationUser()
            {
                Email = model.Email,
                PasswordHash = _passwordValidator.ValidatePassword(model.Password),
                SecurityStamp = Guid.NewGuid().ToString(),
                LockoutEnabled = true
            };

            IdentityResult result = await _userManager.CreateAsync(user);

            if (result.Succeeded)
            {
                return Ok();
            }

            return BadRequest(new { errors = result.Errors });
        }

        [HttpPost]
        public async Task<IActionResult> Login([FromBody] UserLoginModel model)
        {
            if (!ModelState.IsValid)
            {
                return BadRequest(ModelState);
            }

            var user = await _userManager.FindByNameAsync(model.Email);

            if (user == null)
            {
                return Unauthorized();
            }

            var isPasswordValid = _passwordValidator.ValidatePassword(user, model.Password);

            if (!isPasswordValid)
            {
                return BadRequest("Invalid password");
            }

            var lockoutResult = await _lockoutService.IsLockedOutAsync(user);

            if (lockoutResult == LockoutResult.LockedOut)
            {
                return LockedOut();
            }

            await _signInManager.SignInAsync(user, model.RememberMe);

            return Ok();
        }

        [HttpPost]
        public async Task<IActionResult> Logout()
        {
            await _signInManager.SignOutAsync();
            return NoContent();
        }

        [HttpGet]
        public async Task<IActionResult> IsLockedOut([FromQuery] string email)
        {
            var user = await _userManager.FindByNameAsync(email);

            if (user == null)
            {
                return Unauthorized();
            }

            var lockoutResult = await _lockoutService.IsLockedOutAsync(user);

            switch (lockoutResult)
            {
                case LockoutResult.NotLockedOut:
                    return Ok();
                case LockoutResult.LockedOut:
                    return LockedOut();
                case LockoutResult.TooManyAttempts:
                    return TooManyAttempts();
            }
        }

        [HttpPost]
        public async Task<IActionResult> RegisterMfaDevice([FromBody] MfaRegistrationModel model)
        {
            if (!ModelState.IsValid)
            {
                return BadRequest(ModelState);
            }

            var user = await _userManager.FindByNameAsync(model.Email);

            if (user == null)
            {
                return Unauthorized();
            }

            var mfaDevice = new MfaDevice()
            {
                UserId = user.Id,
                DeviceType = model.DeviceType,
                DeviceName = model.DeviceName,
                SecretKey = Guid.NewGuid().ToString()
            };

            await _mfaService.RegisterMfaDeviceAsync(user, mfaDevice);

            return Ok();
        }

        [HttpPost]
        public async Task<IActionResult> VerifyMfaCode([FromBody] MfaVerificationModel model)
        {
            if (!ModelState.IsValid)
            {
                return BadRequest(ModelState);
            }

            var user = await _userManager.FindByNameAsync(model.Email);

            if (user == null)
            {
                return Unauthorized();
            }

            var mfaDevice = await _mfaService.GetMfaDeviceForUserAsync(user, model.DeviceType, model.DeviceName);

            if (mfaDevice == null)
            {
                return BadRequest("Invalid device type or name");
            }

            var isCodeValid = _mfaService.VerifyMfaCode(user, mfaDevice, model.Code);

            if (!isCodeValid)
            {
                return BadRequest("Invalid code");
            }

            await _signInManager.SignInAsync(user, false);

            return Ok();
        }
    }
}
