```c#
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;

namespace ConsoleApplication
{
    class Program
    {
        static void Main(string[] args)
        {
            if (args.Length == 0)
            {
                Console.WriteLine("Please specify the file paths as command-line arguments");
                return;
            }

            List<int> allInts = new List<int>();
            foreach (string filePath in args)
            {
                if (!File.Exists(filePath))
                {
                    Console.WriteLine($"{filePath} does not exist");
                    continue;
                }

                try
                {
                    List<int> ints = File.ReadAllText(filePath).Split(',').Select(x => Convert.ToInt32(x)).ToList();
                    allInts.AddRange(ints);
                }
                catch (Exception e)
                {
                    Console.WriteLine($"Error reading file {filePath}: {e.Message}");
                }
            }

            if (allInts.Count == 0)
            {
                Console.WriteLine("No valid files found");
                return;
            }

            int largest = allInts.Max();
            Console.WriteLine($"Largest integer: {largest}");

            double average = allInts.Average();
            Console.WriteLine($"Average of all integers: {average}");
        }
    }
}
