#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/stat.h>
#include <unistd.h>
#include <dirent.h>
#include <pthread.h>

#define MAX_FILES 100 // maximum number of files that can be loaded
#define MAX_DEPENDENCIES 50 // maximum number of dependencies for each file

typedef struct {
    char *filename; // filename of the script
    int handle; // file handle used to load the script
    unsigned long size; // size of the script
    char *script; // pointer to the loaded script
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char *filename; // filename of the dependency
    int handle; // file handle used to load the dependency
    unsigned long size; // size of the dependency
    char *script; // pointer to the loaded script
} NFAPI_CRC_INDICATION_DEPENDENCY_T;

typedef struct {
    char *filename; // filename of the file being loaded
    int handle; // file handle used to load the file
    unsigned long size; // size of the file
} NFAPI_CRC_INDICATION_FILE_T;

int main() {
    // create a list of NFAPI_CRC_INDICATION_PDU_T structures for each file
    NFAPI_CRC_INDICATION_PDU_T *files[MAX_FILES];
    int num_files = 0;

    // create a list of dependencies for each file
    NFAPI_CRC_INDICATION_DEPENDENCY_T *dependencies[MAX_DEPENDENCIES];
    int num_dependencies = 0;

    // create a list of files to be loaded
    NFAPI_CRC_INDICATION_FILE_T *files_to_load[MAX_FILES];
    int num_files_to_load = 0;

    // loop through each file and load its dependencies
    for (int i = 0; i < MAX_FILES; i++) {
        // check if the file is already loaded
        if (files[i] != NULL) {
            continue;
        }

        // open the file handle
        int handle = open(files[i]->filename, O_RDONLY);
        if (handle < 0) {
            perror("Failed to open file");
            return 1;
        }

        // get the file size
        struct stat st;
        fstat(handle, &st);

        // allocate memory for the script
        char *script = malloc(st.st_size + 1);
        if (script == NULL) {
            perror("Failed to allocate memory");
            return 1;
        }

        // read the file into the script
        int bytes_read = read(handle, script, st.st_size);
        if (bytes_read < 0) {
            perror("Failed to read file");
            return 1;
        }

        // close the file handle
        close(handle);

        // populate the NFAPI_CRC_INDICATION_PDU_T structure
        NFAPI_CRC_INDICATION_PDU_T *file = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        file->filename = strdup(files[i]->filename);
        file->handle = handle;
        file->size = st.st_size;
        file->script = script;

        // add the file to the list of loaded files
        files[i] = file;
    }

    // loop through each dependency and load its dependencies recursively
    for (int i = 0; i < num_dependencies; i++) {
        // check if the dependency is already loaded
        if (dependencies[i] != NULL) {
            continue;
        }

        // open the file handle
        int handle = open(dependencies[i]->filename, O_RDONLY);
        if (handle < 0) {
            perror("Failed to open file");
            return 1;
        }

        // get the file size
        struct stat st;
        fstat(handle, &st);

        // allocate memory for the script
        char *script = malloc(st.st_size + 1);
        if (script == NULL) {
            perror("Failed to allocate memory");
            return 1;
        }

        // read the file into the script
        int bytes_read = read(handle, script, st.st_size);
        if (bytes_read < 0) {
            perror("Failed to read file");
            return 1;
        }

        // close the file handle
        close(handle);

        // populate the NFAPI_CRC_INDICATION_DEPENDENCY_T structure
        NFAPI_CRC_INDICATION_DEPENDENCY_T *dependency = malloc(sizeof(NFAPI_CRC_INDICATION_DEPENDENCY_T));
        dependency->filename = strdup(dependencies[i]->filename);
        dependency->handle = handle;
        dependency->size = st.st_size;
        dependency->script = script;

        // add the dependency to the list of loaded dependencies
        dependencies[i] = dependency;
    }

    // loop through each file and execute its script
    for (int i = 0; i < num_files_to_load; i++) {
        // create a new thread for the file
        pthread_t thread;
        int ret = pthread_create(&thread, NULL, execute_script, files[i]);
        if (ret != 0) {
            perror("Failed to create thread");
            return 1;
        }
    }

    // join all the threads
    for (int i = 0; i < num_files_to_load; i++) {
        pthread_join(threads[i], NULL);
    }

    // cleanup memory
    for (int i = 0; i < num_files_to_load; i++) {
        free(files[i]);
    }

    return 0;
}

void *execute_script(NFAPI_CRC_INDICATION_PDU_T *file) {
    // execute the script in a new thread
    int ret = system(file->script);
    if (ret != 0) {
        perror("Failed to execute script");
    }
}
