import java.io.File;
import java.io.IOException;
import java.util.concurrent.*;
import java.util.logging.Logger;

public class FileUploadHandler {
    private static final Logger LOGGER = Logger.getLogger(FileUploadHandler.class.getName());
    private static final int MAX_CONCURRENCY = 10; // adjust this value based on your needs

    public void processFileUploads(Queue<MultipartFile> uploadQueue, int maxConcurrency) {
        ExecutorService executor = Executors.newFixedThreadPool(MAX_CONCURRENCY);
        try {
            while (!uploadQueue.isEmpty()) {
                MultipartFile file = uploadQueue.poll(); // retrieve the next file to be uploaded
                File tempFile = new File(file.getOriginalFilename()); // create a temporary file for storing the uploaded file
                executor.execute(() -> { // submit the task for asynchronous execution
                    try (InputStream inputStream = file.getInputStream()) { // open an input stream to read the file content
                        Files.copy(inputStream, tempFile.toPath(), StandardCopyOption.REPLACE_EXISTING); // copy the file content to the temporary file
                        LOGGER.info("Uploaded " + file.getOriginalFilename() + " in " + (System.currentTimeMillis() - start) + "ms"); // log the upload duration
                    } catch (IOException e) {
                        LOGGER.severe("Failed to upload " + file.getOriginalFilename());
                        throw new RuntimeException(e);
                    } finally {
                        tempFile.delete(); // delete the temporary file after use
                    }
                });
            }
        } catch (InterruptedException e) {
            LOGGER.severe("Error while processing uploads");
        } finally {
            executor.shutdownNow(); // shut down the thread pool immediately to avoid leaking resources
        }
    }
}
