    private readonly string _iv;
    private readonly IdentityDbContext<IdentityUser> _identityDbContext;
    private readonly CloudStorageService _cloudStorageService;

    public HandleWebUpdatesAndFileOperations(string key, string iv, IdentityDbContext<IdentityUser> identityDbContext, CloudStorageService cloudStorageService)
    {
        _key = key;
        _iv = iv;
        _identityDbContext = identityDbContext;
        _cloudStorageService = cloudStorageService;
    }

    public async Task HandleWebUpdateRequest(int pageSectionId, int elementId, string htmlContent)
    {
        try
        {
            // Validate the request and extract the necessary data
            if (pageSectionId < 1 || elementId < 1 || string.IsNullOrEmpty(htmlContent))
            {
                throw new ArgumentException("Invalid arguments passed to HandleWebUpdateRequest");
            }

            // Decrypt the HTML content using Triple DES encryption with the given key and initialization vector (IV)
            var decryptedHtml = DecryptHtmlContent(_key, _iv, htmlContent);

            // Validate the decrypted HTML content against a whitelist of allowed tags and attributes to prevent XSS attacks
            if (!IsValidHtml(decryptedHtml))
            {
                throw new Exception("The decrypted HTML content is not valid");
            }

            // Log all updates with timestamps for auditing purposes
            _identityDbContext.AddLogEntry(new IdentityLogEntry()
            {
                PageSectionId = pageSectionId,
                ElementId = elementId,
                HtmlContent = decryptedHtml,
                Timestamp = DateTime.UtcNow
            });

            // Save the updated HTML content to the database
            await _identityDbContext.SaveChangesAsync();
        }
        catch (Exception ex)
        {
            // Handle errors gracefully and provide meaningful error messages
            Console.WriteLine($"Error occurred while handling web update request: {ex}");
        }
    }

    private string DecryptHtmlContent(string key, string iv, string htmlContent)
    {
        using (var tripleDes = new TripleDESCryptoServiceProvider())
        {
            var bytes = Encoding.UTF8.GetBytes(htmlContent);
            var decryptedBytes = tripleDes.CreateDecryptor(key, iv).TransformFinalBlock(bytes, 0, bytes.Length);
            return Encoding.UTF8.GetString(decryptedBytes);
        }
    }

    private bool IsValidHtml(string htmlContent)
    {
        // Implement custom validation logic for the HTML content against a whitelist of allowed tags and attributes
        // to prevent XSS attacks. This is just an example, you can add your own validation logic as needed.

        var doc = new XmlDocument();
        doc.LoadXml(htmlContent);

        var whitelistTags = new[] { "p", "h1", "h2", "ul", "li" };
        var whitelistAttributes = new[] { "id", "class", "style" };

        foreach (var node in doc.DocumentElement.ChildNodes)
        {
            if (node is XmlElement element && !whitelistTags.Contains(element.Name))
            {
                return false;
            }

            foreach (var attribute in element.Attributes)
            {
                if (!whitelistAttributes.Contains(attribute.Name))
                {
                    return false;
                }
            }
        }

        return true;
    }
}
