// Function to initialize an array of Nodes with random integer values within a given range
void init_node_array(int* node_array, int size, int min_value, int max_value) {
    // Allocate memory for the Node array and linked lists
    Node *nodes = (Node*)malloc(size * sizeof(Node));
    if (!nodes) {
        printf("Error: could not allocate memory for Node array\n");
        return;
    }

    // Initialize the linked lists in each Node structure
    for (int i = 0; i < size; i++) {
        nodes[i].sub_nodes = (SubNode*)malloc(sizeof(SubNode));
        if (!nodes[i].sub_nodes) {
            printf("Error: could not allocate memory for linked list in Node %d\n", i);
            return;
        }
    }

    // Populate the Node array with random integer values within the given range
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        nodes[i].value = rand() % (max_value - min_value + 1) + min_value;
        // Initialize the linked list in each Node structure with random SubNode structures
        for (int j = 0; j < 5; j++) {
            nodes[i].sub_nodes[j].string[rand() % 10];
            nodes[i].sub_nodes[j].value = rand() % 100.0;
        }
    }

    // Serialize the Node and SubNode data structures to a file or database
    FILE *file = fopen("node_array.bin", "wb");
    if (!file) {
        printf("Error: could not open file for serialization\n");
        return;
    }
    fwrite(nodes, sizeof(Node), size, file);
    fclose(file);

    // Free memory allocated for the Node array and linked lists
    free(nodes);
}

int main() {
    int node_array[5] = {0};
    init_node_array(node_array, 5, -10, 10);
    return 0;
}
