    char* data; // Pointer to the chunk data
} parsed_chunk_t;

// Function to parse a binary file and write it to an output file, using chunks for efficient memory usage
void parse_binary(const char* input_file, const char* output_file, const char* rules, int chunk_size) {
    // Check if the input and output files exist
    struct stat buffer;
    if (stat(input_file, &buffer) == -1 || !S_ISREG(buffer.st_mode)) {
        fprintf(stderr, "Invalid input file: %s\n", input_file);
        return;
    }

    if (stat(output_file, &buffer) == -1 || !S_ISREG(buffer.st_mode)) {
        fprintf(stderr, "Invalid output file: %s\n", output_file);
        return;
    }

    // Open the input and output files
    FILE* in = fopen(input_file, "rb");
    if (!in) {
        perror("Error opening input file");
        return;
    }

    FILE* out = fopen(output_file, "wb");
    if (!out) {
        perror("Error opening output file");
        fclose(in);
        return;
    }

    // Check if the chunk size is valid
    if (chunk_size <= 0) {
        fprintf(stderr, "Invalid chunk size: %d\n", chunk_size);
        fclose(in);
        fclose(out);
        return;
    }

    // Read the input file in chunks
    int chunk_number = 0;
    char* buffer = malloc(chunk_size);
    if (!buffer) {
        perror("Error allocating memory");
        fclose(in);
        fclose(out);
        return;
    }

    size_t bytes_read = 0;
    while ((bytes_read = fread(buffer, sizeof(char), chunk_size, in)) > 0) {
        // Parse the current chunk using the rules and database metadata
        parsed_chunk_t* parsed_chunk = parse_chunk(buffer, bytes_read, rules);
        if (!parsed_chunk) {
            fprintf(stderr, "Error parsing chunk %d\n", chunk_number);
            free(buffer);
            fclose(in);
            fclose(out);
            return;
        }

        // Write the parsed chunk to the output file
        size_t bytes_written = 0;
        while ((bytes_written = fwrite(parsed_chunk->data, sizeof(char), parsed_chunk->size, out)) < parsed_chunk->size) {
            if (ferror(out)) {
                perror("Error writing to output file");
                free(buffer);
                free(parsed_chunk);
                fclose(in);
                fclose(out);
                return;
            }
        }

        // Free the parsed chunk and increment the chunk number
        free(parsed_chunk->data);
        free(parsed_chunk);
        chunk_number++;
    }

    // Clean up resources
    free(buffer);
    fclose(in);
    fclose(out);
}

