```javascript
interface ElementMetadata {
  id: string;
  class: string;
  description: Promise<string>;
}

async function getMatchingElements(rootElement: HTMLElement, selector: string, filterFn: (element: ElementMetadata) => boolean): Promise<HTMLElement[]> {
  const matchingElements = [];
  // Iterate over the root element's child nodes and recurse on each child node that matches the given selector
  await forEachAsync(rootElement.childNodes, async (node: Node) => {
    if (node instanceof HTMLElement && node.matches(selector)) {
      // Filter the element using the provided filter function and add it to the list of matching elements
      const filteredElement = filterFn(node);
      if (filteredElement !== false) {
        matchingElements.push(node);
      }
    }
  });
  // Recurse on each child node that is an HTMLElement and matches the given selector
  await forEachAsync(rootElement.children, async (child: Node) => {
    if (child instanceof HTMLElement && child.matches(selector)) {
      const filteredChild = filterFn(child);
      if (filteredChild !== false) {
        matchingElements.push(child);
      }
    }
  });
  // Return the list of matching elements
  return matchingElements;
}
```
