#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <pthread.h>

// Define the struct for the semaphore manager
typedef struct {
    int current_permits; // The number of permits currently available
    int max_permits; // The maximum number of permits allowed
    pthread_mutex_t lock; // A mutex to protect the shared state
} semaphore_manager_t;

// Define a function to initialize the semaphore manager
void init_semaphore(semaphore_manager_t* semaphore) {
    semaphore->current_permits = 0;
    semaphore->max_permits = MAX_PERMITS;
    pthread_mutex_init(&semaphore->lock, NULL);
}

// Define a function to acquire a permit from the semaphore manager
void acquire_permit(semaphore_manager_t* semaphore) {
    // Lock the mutex to access the shared state
    pthread_mutex_lock(&semaphore->lock);

    // If there are no permits available, wait until one becomes available
    while (semaphore->current_permits == 0) {
        pthread_cond_wait(&semaphore->lock);
    }

    // Decrement the number of permits and signal any waiting threads
    semaphore->current_permits--;
    pthread_cond_signal(&semaphore->lock);

    // Unlock the mutex to release access to the shared state
    pthread_mutex_unlock(&semaphore->lock);
}

// Define a function to release a permit back to the semaphore manager
void release_permit(semaphore_manager_t* semaphore) {
    // Lock the mutex to access the shared state
    pthread_mutex_lock(&semaphore->lock);

    // Increment the number of permits and signal any waiting threads
    semaphore->current_permits++;
    pthread_cond_signal(&semaphore->lock);

    // Unlock the mutex to release access to the shared state
    pthread_mutex_unlock(&semaphore->lock);
}

// Define a function to check if the semaphore manager is at its maximum permits
int is_full(semaphore_manager_t* semaphore) {
    return (semaphore->current_permits >= semaphore->max_permits);
}

// Define a function to check if the semaphore manager has any available permits
int is_empty(semaphore_manager_t* semaphore) {
    return (semaphore->current_permits == 0);
}
```
This code defines a struct for the semaphore manager, which includes the current number of permits and the maximum number of permits allowed. It also includes a mutex to protect the shared state, and functions to acquire and release permits, as well as check if the semaphore manager is at its maximum permits or has any available permits.

The `init_semaphore` function initializes the semaphore manager by setting the current number of permits to 0 and the maximum number of permits to the maximum allowed. It also initializes the mutex.

The `acquire_permit` function acquires a permit from the semaphore manager by locking the mutex, checking if there are any available permits, and decrementing the current number of permits if there are any. If there are no available permits, the function waits until one becomes available. Finally, the function signals any waiting threads to continue.

The `release_permit` function releases a permit back to the semaphore manager by locking the mutex, incrementing the current number of permits, and signaling any waiting threads to continue. Finally, the function unlocks the mutex to release access to the shared state.

The `is_full` function checks if the semaphore manager is at its maximum permits by returning 1 if the current number of permits is greater than or equal to the maximum number of permits allowed. Otherwise, it returns 0.

The `is_empty` function checks if the semaphore manager has any available permits by returning 1 if the current number of permits is 0. Otherwise, it returns 0.

