using System;
using System.Security.Cryptography;
using System.Text;
using System.Data;
using System.Data.SqlClient;

public class PasswordHasher
{
    private const string DEFAULT_HASHING_ALGORITHM = "SHA-256";
    private const string DEFAULT_SALT_PREFIX = "$2a$10$";
    private const int SALT_LENGTH = 16;
    private const int ITERATIONS = 10000;

    public static string HashPassword(string password)
    {
        return HashPassword(password, DEFAULT_HASHING_ALGORITHM);
    }

    public static string HashPassword(string password, string hashingAlgorithm)
    {
        var salt = GenerateSalt();
        var hashedPassword = ComputeHash(salt + password, hashingAlgorithm);
        return salt + hashedPassword;
    }

    public static bool VerifyPassword(string storedPassword, string providedPassword)
    {
        var salt = GetSaltFromStoredPassword(storedPassword);
        var hashedProvidedPassword = ComputeHash(salt + providedPassword, hashingAlgorithm);
        return hashedProvidedPassword == storedPassword;
    }

    private static string GenerateSalt()
    {
        var randomBytes = new byte[SALT_LENGTH];
        using (var rngCsp = new RNGCryptoServiceProvider())
        {
            rngCsp.GetNonZeroBytes(randomBytes);
        }
        return Convert.ToBase64String(randomBytes);
    }

    private static string ComputeHash(string input, string hashingAlgorithm)
    {
        var hash = new StringBuilder();
        using (var algorithm = HashAlgorithm.Create(hashingAlgorithm))
        {
            byte[] inputBuffer = Encoding.UTF8.GetBytes(input);
            byte[] outputBuffer = algorithm.ComputeHash(inputBuffer);
            foreach (byte b in outputBuffer)
            {
                hash.Append(b.ToString("x2"));
            }
        }
        return hash.ToString();
    }

    private static string GetSaltFromStoredPassword(string storedPassword)
    {
        var saltLength = DEFAULT_HASHING_ALGORITHM.Length + 1; // 32 + 1 for the dollar sign
        return storedPassword.Substring(0, saltLength);
    }
}
