import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class Octree {
    private final ConcurrentHashMap<Long, Node> nodes = new ConcurrentHashMap<>();
    private AtomicInteger currentCapacity = new AtomicInteger(0);
    private int maxCapacity = 1000; // maximum capacity of the octree
    private int minCapacity = 500; // minimum capacity of the octree
    private boolean rebalancing = false; // flag to indicate if rebalancing is in progress
    private final Object lock = new Object(); // object for synchronization

    public void add(long id, double[] position) {
        Node node = new Node(id, position);
        nodes.put(node.getId(), node);
        currentCapacity.incrementAndGet();
        if (currentCapacity.get() > maxCapacity) {
            rebalance();
        }
    }

    public void remove(long id) {
        Node node = nodes.remove(id);
        if (node != null) {
            currentCapacity.decrementAndGet();
        }
        if (currentCapacity.get() < minCapacity && !rebalancing) {
            rebalance();
        }
    }

    public boolean contains(long id) {
        return nodes.containsKey(id);
    }

    public List<Node> getNodes() {
        return new ArrayList<>(nodes.values());
    }

    public int size() {
        return currentCapacity.get();
    }

    private void rebalance() {
        if (rebalancing) {
            return;
        }
        rebalancing = true;
        Thread thread = new Thread(() -> {
            synchronized (lock) {
                List<Node> nodesToMove = getNodes();
                int targetCapacity = maxCapacity / 2;
                while (nodesToMove.size() > targetCapacity) {
                    Node nodeToMove = nodesToMove.remove(0);
                    Node targetNode = findLeaf(nodeToMove, targetCapacity);
                    if (targetNode == null) {
                        // create a new leaf node if no suitable target found
                        targetNode = new Node();
                        nodes.put(targetNode.getId(), targetNode);
                    }
                    moveNodes(nodeToMove, targetNode);
                }
                rebalancing = false;
            }
        });
        thread.start();
    }

    private Node findLeaf(Node node, int targetCapacity) {
        if (node.getChildren().isEmpty()) {
            return node;
        } else {
            for (Node child : node.getChildren()) {
                Node targetNode = findLeaf(child, targetCapacity);
                if (targetNode != null) {
                    return targetNode;
                }
            }
            return null;
        }
    }

    private void moveNodes(Node nodeToMove, Node targetNode) {
        // update the octree structure to reflect the move
        nodes.remove(nodeToMove.getId());
        targetNode.getChildren().add(nodeToMove);
        // update the capacity of the moved nodes
        for (Node child : nodeToMove.getChildren()) {
            currentCapacity.incrementAndGet();
        }
    }
}

class Node {
    private long id;
    private double[] position;
    private List<Node> children = new ArrayList<>();

    public Node(long id, double[] position) {
        this.id = id;
        this.position = position;
    }

    public long getId() {
        return id;
    }

    public double[] getPosition() {
        return position;
    }

    public List<Node> getChildren() {
        return children;
    }
}
