public class DistributedCacheSystem {
    private Map<String, CacheNode> cacheNodes;
    private List<ClientConnection> clientConnections;
    private int totalCapacity;
    private int currentSize;
    private int cacheTTL;
    private int cacheRebalancingInterval;

    public DistributedCacheSystem(int capacity, int ttl, int rebalancingInterval) {
        this.cacheNodes = new HashMap<>();
        this.clientConnections = new ArrayList<>();
        this.totalCapacity = capacity;
        this.currentSize = 0;
        this.cacheTTL = ttl;
        this.cacheRebalancingInterval = rebalancingInterval;
    }

    public void addClientConnection(ClientConnection connection) {
        clientConnections.add(connection);
    }

    public void removeClientConnection(ClientConnection connection) {
        clientConnections.remove(connection);
    }

    public void setCacheNode(String nodeId, CacheNode cacheNode) {
        cacheNodes.put(nodeId, cacheNode);
    }

    public void removeCacheNode(String nodeId) {
        cacheNodes.remove(nodeId);
    }

    public void addToCache(String key, String value) {
        // Check if the key already exists in the cache
        if (cacheNodes.containsKey(key)) {
            return;
        }

        // Get the current cache size and check if it exceeds 15% of the total capacity
        int currentSize = getCurrentCacheSize();
        if (currentSize > totalCapacity * 0.15) {
            // Rebalance the cache by removing expired entries or evicting least recently used entries
            rebalanceCache();
        }

        // Set the TTL for the key-value pair
        int ttl = calculateTTL(key);

        // Add the key-value pair to all cache nodes
        cacheNodes.values().forEach((cacheNode) -> {
            cacheNode.addToCache(key, value, ttl);
        });
    }

    public void removeFromCache(String key) {
        // Remove the key from all cache nodes
        cacheNodes.values().forEach((cacheNode) -> {
            cacheNode.removeFromCache(key);
        });
    }

    public String getValueFromCache(String key) {
        // Return null if the key is not found in any cache node
        for (CacheNode cacheNode : cacheNodes.values()) {
            String value = cacheNode.getValueFromCache(key);
            if (value != null) {
                return value;
            }
        }
        return null;
    }

    public void updateTTL(String key, int ttl) {
        // Update the TTL for the key-value pair in all cache nodes
        cacheNodes.values().forEach((cacheNode) -> {
            cacheNode.updateTTL(key, ttl);
        });
    }

    public void evictExpiredEntries() {
        // Evict expired entries from all cache nodes
        cacheNodes.values().forEach((cacheNode) -> {
            cacheNode.evictExpiredEntries();
        });
    }

    public int getCurrentCacheSize() {
        // Return the current size of the cache
        return currentSize;
    }

    public void rebalanceCache() {
        // Rebalance the cache by removing expired entries or evicting least recently used entries
        cacheNodes.values().forEach((cacheNode) -> {
            cacheNode.rebalanceCache();
        });
    }

    private int calculateTTL(String key) {
        // Calculate the TTL for the key-value pair based on the cache TTL and the current time
        return cacheTTL;
    }
}
