                // Seed the random number generator with high-quality entropy
                std::random_device rd;
                std::seed_seq seed{ rd(), std::time(nullptr), rand() };
                randomGen.seed(seed);
            }

            ~RandomNumberGenerator() {
                // No-op destructor to maintain a consistent interface
            }

            static std::string generateSessionId() {
                // Generate a new session ID and encode it as a base64 string
                const int base64Chars = 22;
                std::stringstream ss;
                for (int i = 0; i < base64Chars; ++i) {
                    ss << randomGen() % ('z' - 'a') + 'a';
                }
                return ss.str();
            }
    };
}
