#include <semaphore.h>
#include <thread>
#include <chrono>
#include <iostream>
#include <string>
#include <vector>
#include <future>
#include <map>

using namespace std;

class SemaphoreManager {
private:
    string semaphoreName;
    int initialPermits = 0;
    int maxPermits = 10;
    int minPermits = 1;
    int currentPermits = 0;
    bool isCloudServiceAvailable = true;
    chrono::steady_clock::time_point lastUpdateTime;
    map<string, int> threadCounts;
    vector<string> activeThreads;

public:
    SemaphoreManager(string semaphoreName) {
        this->semaphoreName = semaphoreName;
        currentPermits = initialPermits;
        lastUpdateTime = chrono::steady_clock::now();
    }

    ~SemaphoreManager() {
        // Clean up the semaphore and thread counts when the manager is destroyed
        cleanUp();
    }

    void initialize(int initialPermits, int maxPermits, int minPermits) {
        this->initialPermits = initialPermits;
        this->maxPermits = maxPermits;
        this->minPermits = minPermits;
        currentPermits = initialPermits;
    }

    void createSemaphore() {
        // Create the semaphore on the cloud service if it doesn't exist
        if (!isCloudServiceAvailable) {
            throw runtime_error("Cloud service is unavailable");
        }
        string url = "https://cloud-service.com/semaphores/" + semaphoreName;
        http::Request request(url, http::Method::POST);
        request.setBody(json::parse(fmt::format("{{ \"name\": \"{}\", \"initialPermits\": {}, \"maxPermits\": {}, \"minPermits\": {} }}", semaphoreName, initialPermits, maxPermits, minPermits)));
        http::Response response = request.send();
        if (response.getStatusCode() != 201) {
            throw runtime_error(fmt::format("Failed to create semaphore: {}", response.getBody().as<string>()));
        }
    }

    void deleteSemaphore() {
        // Delete the semaphore on the cloud service if it exists
        if (!isCloudServiceAvailable) {
            throw runtime_error("Cloud service is unavailable");
        }
        string url = "https://cloud-service.com/semaphores/" + semaphoreName;
        http::Request request(url, http::Method::DELETE);
        http::Response response = request.send();
        if (response.getStatusCode() != 204) {
            throw runtime_error(fmt::format("Failed to delete semaphore: {}", response.getBody().as<string>()));
        }
    }

    void updatePermits(int permits) {
        // Update the number of permits on the cloud service if necessary
        if (!isCloudServiceAvailable) {
            throw runtime_error("Cloud service is unavailable");
        }
        string url = "https://cloud-service.com/semaphores/" + semaphoreName;
        http::Request request(url, http::Method::PATCH);
        json body = json{{"permits", permits}};
        request.setBody(body);
        http::Response response = request.send();
        if (response.getStatusCode() != 204) {
            throw runtime_error(fmt::format("Failed to update semaphore: {}", response.getBody().as<string>()));
        }
    }

    void acquire() {
        // Acquire a permit from the cloud service if available
        if (!isCloudServiceAvailable) {
            throw runtime_error("Cloud service is unavailable");
        }
        string url = "https://cloud-service.com/semaphores/" + semaphoreName;
        http::Request request(url, http::Method::GET);
        http::Response response = request.send();
        if (response.getStatusCode() == 204) {
            // There are no permits available, try again later
            throw runtime_error("No permits available");
        } else if (response.getStatusCode() != 200) {
            throw runtime_error(fmt::format("Failed to acquire permit: {}", response.getBody().as<string>()));
        }
        // Update the number of active threads and permits on the cloud service
        json body = response.getBody();
        int newPermits = body["permits"].as<int>();
        currentPermits = newPermits;
        threadCounts[thread::this_thread::get_id()]++;
        activeThreads.push_back(to_string(thread::this_thread::get_id()));
        // If there are too many threads, reduce the number of permits on the cloud service
        if (activeThreads.size() > maxPermits) {
            updatePermits(newPermits - 1);
        }
    }

    void release() {
        // Release a permit on the cloud service and decrement the number of active threads
        string threadId = to_string(thread::this_thread::get_id());
        if (activeThreads.size() > 0 && activeThreads[activeThreads.size() - 1] == threadId) {
            activeThreads.pop_back();
        }
        currentPermits++;
        threadCounts[threadId]--;
        // If there are too many threads, increase the number of permits on the cloud service
        if (activeThreads.size() > maxPermits) {
            updatePermits(currentPermits + 1);
        }
    }

    void fallbackSemaphoreManagement() {
        // If the cloud service becomes unavailable, manage the semaphore locally
        isCloudServiceAvailable = false;
        int localPermits = currentPermits;
        for (string threadId : activeThreads) {
            if (threadCounts[threadId] > 0) {
                localPermits--;
            }
        }
        currentPermits = localPermits;
    }

    void cleanUp() {
        // Clean up the semaphore and thread counts when the manager is destroyed
        deleteSemaphore();
        activeThreads.clear();
        threadCounts.clear();
    }
};
