import { import } from 'module';
import blueslip from 'blueslip';
import { describe, it, beforeEach, afterEach } from 'mocha';

const runModuleTests = (moduleLabel, testSuite, loggingLevel) => {
  // Initialize the mocking library
  blueslip.init();

  // Dynamically load the module
  import(moduleLabel).then((module) => {
    // Define a suite of tests for each test function in the test suite
    const testSuiteDef = testSuite.map((test) => {
      return describe(`${test.label}`, () => {
        beforeEach(() => {
          blueslip.reset();
        });

        it(`should ${test.label}`, (done) => {
          module.runTest(test).then(() => {
            done();
          }).catch((error) => {
            // Log the error message to the console
            console.log(`${moduleLabel}: ${test.label} failed with an error`);
            console.log(error.message);
            done(error);
          });
        });
      });
    });

    // Run the tests using Mocha or Jest
    describe('Module Tests', () => {
      testSuiteDef.forEach((test) => {
        test();
      });
    });

    // Reset and clean up the blueslip mocking library after each test
    afterEach(() => {
      blueslip.reset();
    });
  }).catch((error) => {
    console.log(`Failed to load module ${moduleLabel}`);
    console.log(error.message);
  });
};
