namespace SimpleRandomNumberGenerator
{
    public class Program
    {
        private static Random _mersenneTwister = new Random(DateTime.Now.Millisecond);

        public static void Main(string[] args)
        {
            // Check if the web.config file exists in the directory
            string webConfigPath = Path.Combine(args[0], "web.config");
            if (!File.Exists(webConfigPath))
            {
                Console.WriteLine("Error: web.config file not found.");
                return;
            }

            // Check if all site names meet naming conventions
            foreach (string siteName in args)
            {
                if (!Regex.IsMatch(siteName, "^[a-zA-Z0-9_]+$"))
                {
                    Console.WriteLine("Error: Site name does not meet naming conventions.");
                    return;
                }
            }

            // Create a list to store the largest integer across all files
            List<int> largestInts = new List<int>();

            // Process each file and find the largest integer
            foreach (string filePath in args)
            {
                try
                {
                    // Check if the file is valid and accessible
                    if (!File.Exists(filePath))
                    {
                        Console.WriteLine($"Error: File '{filePath}' not found.");
                        continue;
                    }

                    // Read the integers from the file
                    List<int> ints = File.ReadAllLines(filePath).Select(line => Convert.ToInt32(line)).ToList();

                    // Find the largest integer in the list
                    int largestInt = ints.Max();

                    // Add the largest integer to the list
                    largestInts.Add(largestInt);
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error: Exception occurred while processing file '{filePath}'. Details: {ex.Message}");
                }
            }

            // Print the largest integer across all files
            Console.WriteLine($"Largest integer across all files: {largestInts.Max()}");

            // Calculate the average of all integers
            int total = largestInts.Sum();
            double average = (double)total / largestInts.Count;
            Console.WriteLine($"Average of all integers: {average}");
        }
    }
}

