// readDynamicFiles.js
(function() {
    var fs = require('fs');
    var path = require('path');

    function readFile(filePath) {
        try {
            return fs.readFileSync(filePath, 'utf8');
        } catch (error) {
            if (error.code === 'ENOENT') {
                console.log(`Error: File not found at ${filePath}.`);
                return null;
            } else if (error.code === 'EACCES') {
                console.log(`Error: Permission denied for file at ${filePath}.`);
                return null;
            } else {
                throw error;
            }
        }
    }

    function readDirectory(directory) {
        try {
            var files = fs.readdirSync(directory);
            var contents = [];

            for (var i = 0; i < files.length; i++) {
                var filePath = path.join(directory, files[i]);
                if (fs.lstatSync(filePath).isFile()) {
                    var content = readFile(filePath);
                    if (content !== null) {
                        contents.push(content);
                    }
                } else {
                    contents.push(readDirectory(filePath));
                }
            }

            return contents;
        } catch (error) {
            if (error.code === 'ENOENT') {
                console.log(`Error: Directory not found at ${directory}.`);
                return null;
            } else if (error.code === 'EACCES') {
                console.log(`Error: Permission denied for directory at ${directory}.`);
                return null;
            } else {
                throw error;
            }
        }
    }

    module.exports = readDirectory;
})();
