import threading
import logging
from collections import deque
from bs4 import BeautifulSoup

class ElementCache:
    def __init__(self):
        self.cache = {}
        self.lock = threading.Lock()

    def add(self, key, value):
        with self.lock:
            self.cache[key] = value
            if len(self.cache) > 500:
                self.cache.popitem(last=False)

    def get(self, key):
        with self.lock:
            return self.cache.get(key, None)

class ElementExtractor:
    def __init__(self, html_doc, tag, attribute, value):
        self.html_doc = html_doc
        self.tag = tag
        self.attribute = attribute
        self.value = value
        self.cache = ElementCache()

    def extract(self):
        key = (self.tag, self.attribute, self.value)
        cached_elements = self.cache.get(key)
        if cached_elements is not None:
            logging.info("Cache hit for %s", key)
            return cached_elements
        else:
            logging.info("Cache miss for %s", key)
            soup = BeautifulSoup(self.html_doc, "html.parser")
            elements = soup.find_all(self.tag, {self.attribute: self.value})
            if len(elements) > 0:
                self.cache.add(key, elements)
            return elements

def extract_and_cache_elements(html_doc, tag, attribute, value):
    try:
        extractor = ElementExtractor(html_doc, tag, attribute, value)
        return extractor.extract()
    except Exception as e:
        logging.error("Invalid input parameters for element extraction")
        raise e
```
