const { require } = require('blueslip');
const mocha = require('mocha');
const jest = require('jest');

function runTests(moduleName, numRetries = 0) {
  const blueslip = require('blueslip');
  const testFramework = moduleName.endsWith('.js') ? mocha : jest;

  let failedTests = [];
  let passedTests = [];

  for (const test of tests) {
    try {
      const testResult = testFramework.run(test);
      if (testResult.passed()) {
        passedTests.push(test);
      } else {
        failedTests.push(test);
        if (numRetries > 0) {
          console.log(`Test ${test} failed, retrying...`);
          numRetries--;
          continue;
        }
        break;
      }
    } catch (error) {
      console.error(error);
    } finally {
      blueslip.reset();
    }
  }

  if (failedTests.length > 0) {
    console.log(`${failedTests.length} tests failed:`);
    for (const test of failedTests) {
      console.log(`- ${test}`);
    }
  } else {
    console.log('All tests passed!');
  }

  if (passedTests.length > 0) {
    console.log(`${passedTests.length} tests passed:`);
    for (const test of passedTests) {
      console.log(`- ${test}`);
    }
  }

  return failedTests.length;
}

module.exports = runTests;
```
