import os
import yaml
from docker import DockerClient
from kubernetes import KubernetesClient

class DeploymentManager:
    def __init__(self, config_file):
        self.config_file = config_file
        self.client = DockerClient()
        self.kube_client = KubernetesClient()

    def deploy(self):
        with open(self.config_file) as f:
            config = yaml.load(f, Loader=yaml.FullLoader)

        for app in config['apps']:
            # Check if image is available and pull it if necessary
            try:
                self.client.images.pull(app['image'])
            except docker.errors.ImageNotFound as e:
                print(f'Image {app["image"]} not found')

            # Create a container for the application
            container = self.client.containers.run(
                image=app['image'],
                detach=True,
                ports=app['ports'],
                environment=app['environment']
            )

            # Set up dependency relationships between applications
            if 'dependencies' in app:
                for dependency in app['dependencies']:
                    self.kube_client.wait_for(dependency)

            # Scale the application based on its configuration
            if 'replicas' in app:
                container.scale(app['replicas'])

            # Log deployment status and any errors encountered
            try:
                print(f'Deployed {app["name"]}')
            except docker.errors.DockerException as e:
                print(f'Error deploying {app["name"]}: {e}')

        return True

    def scale(self, app_name, replicas):
        # Scale the specified application to the given number of replicas
        container = self.client.containers.get(f'{app_name}-container')
        if container is None:
            raise RuntimeError(f'Container for {app_name} not found')

        return container.scale(replicas)

    def stop(self, app_name):
        # Stop the specified application and remove its container
        container = self.client.containers.get(f'{app_name}-container')
        if container is None:
            raise RuntimeError(f'Container for {app_name} not found')

        return container.stop()

    def status(self):
        # Get the status of all deployed applications
        containers = self.client.containers.list()
        statuses = {}

        for container in containers:
            app_name = container.get('Labels', {})['app']
            if app_name not in statuses:
                statuses[app_name] = {'status': 'running'}

            if container.is_failed():
                statuses[app_name]['status'] = 'error'

        return statuses

    def healthcheck(self, app_name):
        # Perform a health check on the specified application
        container = self.client.containers.get(f'{app_name}-container')
        if container is None:
            raise RuntimeError(f'Container for {app_name} not found')

        return container.healthcheck()
