int main() {
    // Create a client to send GET requests to the server
    io_context context;
    tcp::resolver resolver(context);
    tcp::socket socket(context);
    beast::http::response<beast::http::string_body> response;
    beast::error_code ec;

    // Set the URL and expected values for the request
    string url = "https://www.example.com";
    vector<string> expectedValues = {"value1", "value2"};

    // Send a GET request to the server and verify the response
    socket.connect(resolver.resolve(url));
    http::request<http::string_body> request;
    request.method(http::verb::get);
    request.target("/");
    request.set(http::field::user_agent, BOOST_BEAST_VERSION_STRING);
    beast::http::write(socket, request);
    beast::http::read(socket, response);
    if (response.result() != http::status::ok) {
        cerr << "Error: " << response.result_int() << ": " << response.reason() << endl;
        return 1;
    }

    // Check the response against expected values
    vector<string> actualValues = response.body();
    for (const string& value : actualValues) {
        if (expectedValues.find(value) == expectedValues.end()) {
            cerr << "Error: Actual value '" << value << "' not found in expected values." << endl;
            return 1;
        }
    }

    // Upload a file using File Uploader library and get the URL of the uploaded file
    string filePath = "/path/to/file.txt";
    string uploadedFileUrl = uploadFile(url, filePath);
    if (uploadedFileUrl.empty()) {
        cerr << "Error: Failed to upload file." << endl;
        return 1;
    }

    // Print the number of requests, proxy sessions, and internal errors
    cout << "Number of requests: " << response.result_int() << endl;
    cout << "Proxy sessions: " << response.reason() << endl;
    cout << "Internal errors: " << ec.message() << endl;

    return 0;
}
