import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.AsynchronousServerSocketChannel;
import java.nio.channels.AsynchronousSocketChannel;
import java.nio.channels.CompletionHandler;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.function.Consumer;

public class AsyncMicroservice {
    private final List<InetSocketAddress> serverList;
    private final ExecutorService executorService;

    public AsyncMicroservice(List<InetSocketAddress> serverList) {
        this.serverList = serverList;
        this.executorService = Executors.newFixedThreadPool(serverList.size());
    }

    public void start() throws IOException {
        // Create and bind an AsynchronousServerSocketChannel to a random free port on the local machine
        AsynchronousServerSocketChannel serverChannel = AsynchronousServerSocketChannel.open();
        InetSocketAddress address = new InetSocketAddress("localhost", 0);
        serverChannel.bind(address);

        // Create a completion handler for accepting incoming connections and processing tasks
        CompletionHandler<AsynchronousSocketChannel, AsyncMicroservice> handler = new CompletionHandler<AsynchronousSocketChannel, AsyncMicroservice>() {
            @Override
            public void completed(AsynchronousSocketChannel channel, AsyncMicroservice self) {
                try {
                    // Accept an incoming connection and process it asynchronously
                    self.executorService.submit(() -> {
                        try {
                            // Read the task from the client socket
                            String task = channel.read(ByteBuffer.allocate(1024)).toString();

                            // Invoke the task method on the server and get the result
                            Object result = self.invokeTask(task);

                            // Write the result back to the client socket
                            channel.write(ByteBuffer.wrap((result + "\n").getBytes()));
                        } catch (IOException | ExecutionException | InterruptedException e) {
                            e.printStackTrace();
                        } finally {
                            // Close the client socket
                            channel.close();
                        }
                    });
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }

            @Override
            public void failed(Throwable exc, AsyncMicroservice self) {
                exc.printStackTrace();
            }
        };

        // Handle incoming connections asynchronously using the completion handler
        serverChannel.accept(this, handler);
    }

    private Object invokeTask(String task) throws IOException, ExecutionException, InterruptedException {
        // Split the task into method name and parameters
        String[] parts = task.split(" ");
        String methodName = parts[0];
        String[] params = Arrays.copyOfRange(parts, 1, parts.length);

        // Create a proxy object for each server in the pool and invoke the method on it
        Object result = null;
        for (InetSocketAddress server : serverList) {
            try (AsynchronousSocketChannel channel = AsynchronousSocketChannel.open()) {
                channel.connect(server).get();
                result = channel.write(ByteBuffer.wrap((methodName + "(" + String.join(", ", params) + ")" + "\n").getBytes()));
                if (result != null) {
                    break;
                }
            } catch (IOException | ExecutionException | InterruptedException e) {
                // Ignore exceptions and try the next server in the pool
                continue;
            }
        }

        return result;
    }
}
