    for (int i = 0; i < num_selectors; i++) {
        if (match(node->data, selectors[i].selector) && depth <= selectors[i].depth) {
            callback(node); // Invoke the callback function on a matching node
        }
    }

    // Recursively traverse the child nodes of the current node
    if (node->next != NULL) {
        traverse(node->next, depth + 1, selectors, num_selectors, callback);
    }
}

int match(char* data, char* selector) {
