<?php

namespace ConfigManager;

use Database\Connection;
use VendorAutoloader\DependencyLoader;
use Logging\Logger;

class ConfigurationManager {
    private $dbConn;
    private $dependencyLoader;
    private $configData;

    public function __construct(Connection $dbConn, DependencyLoader $dependencyLoader) {
        $this->dbConn = $dbConn;
        $this->dependencyLoader = $dependencyLoader;
        $this->configData = [];
    }

    public function loadConfig() {
        // Load configuration from database
        try {
            $query = "SELECT * FROM configurations WHERE environment = :env";
            $result = $this->dbConn->executeQuery($query, ['env' => getServerEnvironment()]);
            $configData = $result->fetchAll(PDO::FETCH_ASSOC);
        } catch (Exception $e) {
            // Log error and use fallback settings
            Logger::error("Failed to load configuration from database: " . $e->getMessage());
            return [];
        }

        // Load dependencies using vendor autoloader
        try {
            $this->dependencyLoader->loadDependencies($configData['dependencies']);
        } catch (Exception $e) {
            Logger::error("Failed to load dependencies: " . $e->getMessage());
        }

        return $configData;
    }

    public function getConfig($key) {
        // Get value from config data or use fallback value
        if (isset($this->configData[$key])) {
            return $this->configData[$key];
        } else {
            return null;
        }
    }

    public function setConfig($key, $value) {
        // Set value in config data and save to database
        $this->configData[$key] = $value;
        try {
            $query = "INSERT INTO configurations (environment, key, value) VALUES (:env, :key, :value) ON DUPLICATE KEY UPDATE value = :value";
            $this->dbConn->executeQuery($query, ['env' => getServerEnvironment(), 'key' => $key, 'value' => $value]);
        } catch (Exception $e) {
            // Log error and use fallback settings
            Logger::error("Failed to set configuration: " . $e->getMessage());
        }
    }

    public function validateConfig($configData) {
        // Validate config data against predefined standards
        try {
            $query = "SELECT * FROM validation_rules WHERE environment = :env";
            $result = $this->dbConn->executeQuery($query, ['env' => getServerEnvironment()]);
            $validationRules = $result->fetchAll(PDO::FETCH_ASSOC);
        } catch (Exception $e) {
            // Log error and use fallback settings
            Logger::error("Failed to load validation rules: " . $e->getMessage());
            return true;
        }

        foreach ($validationRules as $rule) {
            if (!$this->dependencyLoader->validateConfig($configData, $rule['key'], $rule['value'])) {
                Logger::error("Validation failed for key " . $rule['key'] . ": " . $rule['value']);
                return false;
            }
        }

        return true;
    }
}
