import json
import os
from typing import List, Dict

class JsonLoader:
    def __init__(self):
        self.factory_functions: Dict[str, Callable[[], object]] = {}
        self.files: List[str] = []
        self.objects: List[object] = []

    def add_factory_function(self, id: str, factory: Callable[[], object]) -> None:
        self.factory_functions[id] = factory

    def create_instance(self, id: str) -> object:
        if id not in self.factory_functions:
            raise ValueError(f"Factory function with ID {id} is not registered")
        return self.factory_functions[id]()

    def load_files(self, files: List[str]) -> None:
        for file in files:
            if not os.path.exists(file):
                raise FileNotFoundError(f"File {file} does not exist")
            with open(file) as f:
                try:
                    self.objects.append(json.loads(f.read()))
                except json.JSONDecodeError as e:
                    raise ValueError(f"Failed to parse JSON file {file}: {e}")
        for obj in self.objects:
            if not isinstance(obj, dict):
                raise ValueError(f"Object loaded from {file} is not a dictionary")

    def execute_files(self) -> None:
        for obj in self.objects:
            try:
                exec(obj)
            except Exception as e:
                print(f"Failed to execute object loaded from {file}: {e}")
                raise

    def insert_element_in_forward_list(self, forward_list: List[str], element: str, position: int = None) -> None:
        if position is not None and (position < 0 or position > len(forward_list)):
            raise ValueError(f"Position {position} is out of bounds for forward list")
        if position is None:
            forward_list.append(element)
        else:
            forward_list.insert(position, element)

    def read_string_pairs_from_file(self, file: str) -> List[Tuple[str, str]]:
        with open(file) as f:
            return [line.split() for line in f]

class JsonObject:
    def __init__(self):
        self.forward_list = []

    def insert_element_in_forward_list(self, element: str, position: int = None) -> None:
        self.parent.insert_element_in_forward_list(self.forward_list, element, position)

    def __getitem__(self, key):
        return self.forward_list[key]

class JsonSerialization:
    @staticmethod
    def deserialize(data: bytes) -> object:
        try:
            obj = json.loads(data)
        except json.JSONDecodeError as e:
            raise ValueError(f"Failed to parse JSON data: {e}")
        return obj

    @staticmethod
    def serialize(obj):
        return json.dumps(obj).encode()

class PasswordHashing:
    @staticmethod
    def hash_password(password: str) -> str:
        salt = os.urandom(16)
        password_hash = hashlib.sha256(salt + password.encode()).hexdigest()
        return f"{salt}{password_hash}"
```
