namespace FileEncryption
{
    public static class EncryptionUtility
    {
        // AES-GCM parameters
        private const int NonceSize = 12;
        private const int TagSize = 16;
        private const int InitializationVectorSize = 16;

        // HSM key management
        private const string HsmKeyLabel = "my_key";
        private const string HsmModuleName = "HSM_MODULE";

        public static async Task<byte[]> EncryptFileAsync(string filePath, byte[] encryptionKey)
        {
            // Check input parameters
            if (filePath == null)
                throw new ArgumentNullException(nameof(filePath));
            if (encryptionKey == null || encryptionKey.Length != 32)
                throw new ArgumentException("Invalid encryption key", nameof(encryptionKey));

            // Generate random nonce and initialization vector
            byte[] nonce = new byte[NonceSize];
            byte[] initializationVector = new byte[InitializationVectorSize];
            new Random().NextBytes(nonce);
            new Random().NextBytes(initializationVector);

            // Open file stream for reading
            using (FileStream inputStream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
            {
                // Create AES-GCM encryptor
                var aesGcmEncryptor = AesGcm.Create();
                aesGcmEncryptor.KeySize = 256;
                aesGcmEncryptor.BlockSize = 128;
                aesGcmEncryptor.GenerateKey(encryptionKey);
                aesGcmEncryptor.GenerateIV(initializationVector);

                // Create output stream for encrypted data
                using (MemoryStream outputStream = new MemoryStream())
                {
                    // Encrypt file content
                    await inputStream.CopyToAsync(aesGcmEncryptor, nonce, TagSize).ConfigureAwait(false);

                    // Generate authentication tag
                    byte[] tag = aesGcmEncryptor.GetTag();

                    // Save encryption metadata to output stream
                    outputStream.Write(nonce, 0, nonce.Length);
                    outputStream.Write(tag, 0, tag.Length);

                    // Return encrypted data as byte array
                    return outputStream.ToArray();
                }
            }
        }

