            {
                // Read encryption metadata from file header
                byte[] nonce = new byte[NonceSize];
                byte[] tag = new byte[TagSize];
                await inputStream.ReadAsync(nonce, 0, NonceSize).ConfigureAwait(false);
                await inputStream.ReadAsync(tag, 0, TagSize).ConfigureAwait(false);

                // Create AES-GCM decryptor
                var aesGcmDecryptor = AesGcm.Create();
                aesGcmDecryptor.KeySize = 256;
                aesGcmDecryptor.BlockSize = 128;
                aesGcmDecryptor.GenerateKey(encryptionKey);
                aesGcmDecryptor.GenerateIV(nonce);
                aesGcmDecryptor.SetTag(tag);

                // Create output stream for decrypted data
                using (MemoryStream outputStream = new MemoryStream())
                {
                    // Decrypt file content
                    await inputStream.CopyToAsync(aesGcmDecryptor, null).ConfigureAwait(false);

                    // Return decrypted data as byte array
                    return outputStream.ToArray();
                }
            }
