```rust
use std::env;
use std::fs::{create_dir, remove_dir};
use std::io::Result;
use std::path::PathBuf;
use std::thread::sleep;
use std::time::Duration;

fn main() -> Result<()> {
    let work_dir = env::var("WORK_DIR").ok();
    let mut temp_dir = PathBuf::new();

    if work_dir.is_none() {
        temp_dir = create_temp_dir().await?;
    } else {
        temp_dir = work_dir.unwrap();
    }

    // Clean up the temporary directory after a certain time interval.
    let cleanup_interval = Duration::from_secs(3600); // 1 hour
    sleep(cleanup_interval);

    // Remove the temporary directory.
    remove_dir(&temp_dir).await?;

    Ok(())
}

async fn create_temp_dir() -> Result<PathBuf> {
    let mut temp_dir = PathBuf::new();
    let mut is_unique = false;

    while !is_unique {
        let mut rng = rand::thread_rng();
        let random_string: String = rng.gen_ascii_chars().take(10).collect();

        temp_dir = PathBuf::from("/tmp").join(random_string);
        is_unique = !temp_dir.exists() && !temp_dir.is_file();
    }

    create_dir(&temp_dir).await?;

    Ok(temp_dir)
}
```
The `create_temp_dir` function creates a new temporary directory under `/tmp` with a unique name using the `rand::thread_rng()` function from the `rand` crate. The `is_unique` variable is set to `false` initially, and the loop continues until a unique directory path is found.

The `main` function checks if the `WORK_DIR` environment variable is set and validates its existence and permissions using the `env::var()` function. If the `WORK_DIR` is not valid or does not exist, a new temporary directory is created using the `create_temp_dir` function. Otherwise, the `WORK_DIR` is used as the working directory.

The utility implements a mechanism to automatically clean up the working directory after the pipeline completes execution by sleeping for a certain time interval and then removing the directory using the `remove_dir()` function from the `std::fs` module. The cleanup interval can be customized using the `cleanup_interval` variable, which is set to 1 hour in this example.

