            // Obtain the file path or byte array from the input parameter.
            var uploadRequest = new UploadRequest()
            {
                FilePathOrByteArray = filePathOrByteArray,
                AccessToken = accessToken
            };

            // Add the upload request to the queue and return an empty result for now.
            lock (_syncLock)
            {
                _uploadQueue.Enqueue(uploadRequest);
            }
            return new UploadResult() { Success = true };
        }

        public async Task<UploadResult> ProcessNextAsync()
        {
            // Dequeue the next upload request from the queue and process it.
            lock (_syncLock)
            {
                if (_uploadQueue.Count == 0)
                {
                    return null;
                }
                var uploadRequest = _uploadQueue.Dequeue();
            }

            // Calculate the file size in bytes and use it to determine the optimal chunking strategy.
            var fileSizeInBytes = GetFileSizeInBytes(uploadRequest.FilePathOrByteArray);
            var optimalChunkSize = CalculateOptimalChunkSize(fileSizeInBytes, uploadRequest.AccessToken);

            // Upload the file in chunks using a custom chunking algorithm that adjusts based on network conditions and cloud storage service limitations.
            var currentOffset = 0;
            var totalUploadTime = 0L;
            while (currentOffset < fileSizeInBytes)
            {
                var chunkSize = Math.Min(optimalChunkSize, fileSizeInBytes - currentOffset);
                var chunkBuffer = GetFileDataChunk(uploadRequest.FilePathOrByteArray, currentOffset, chunkSize);
                var uploadResponse = await UploadChunkAsync(chunkBuffer, uploadRequest.AccessToken);
                if (!uploadResponse.IsSuccessStatusCode)
                {
                    return new UploadResult()
                    {
                        Success = false,
                        ErrorMessage = "Failed to upload the file chunk."
                    };
                }
                currentOffset += chunkSize;
            }

            // Return a successful result after the file has been uploaded.
            return new UploadResult()
            {
                Success = true
            };
        }

        private async Task<HttpResponseMessage> UploadChunkAsync(byte[] chunkBuffer, string accessToken)
        {
            // Prepare the HTTP request and set the appropriate headers.
            var uploadUrl = _configuration["CloudStorage:UploadUrl"];
            var httpRequest = new HttpRequestMessage(HttpMethod.Post, uploadUrl);
            httpRequest.Headers.Authorization = new AuthenticationHeaderValue("Bearer", accessToken);
            httpRequest.Content = new ByteArrayContent(chunkBuffer);
            httpRequest.Content.Headers.ContentType = MediaTypeHeaderValue.Parse("application/octet-stream");

            // Send the HTTP request and handle the response.
