        private long GetFileSizeInBytes(string filePathOrByteArray)
        {
            // Calculate the file size in bytes based on whether the input parameter is a file path or a byte array.
            if (IsFilePath(filePathOrByteArray))
            {
                return new FileInfo(filePathOrByteArray).Length;
            }
            else
            {
                return filePathOrByteArray.Length;
            }
        }

        private bool IsFilePath(string input) => !string.IsNullOrEmpty(input) && Path.GetFullPath(input) == input;

        private byte[] GetFileDataChunk(string filePathOrByteArray, int offset, int chunkSize)
        {
            // Retrieve the file data chunk based on whether the input parameter is a file path or a byte array.
            if (IsFilePath(filePathOrByteArray))
            {
                using var fileStream = new FileStream(filePathOrByteArray, FileMode.Open, FileAccess.Read);
                fileStream.Seek(offset, SeekOrigin.Begin);
                return ReadBytesFromStream(fileStream, chunkSize);
            }
            else
            {
                var byteArray = filePathOrByteArray.Split(',');
                var base64String = new string(byteArray[1].ToCharArray());
                using var memoryStream = new MemoryStream(Convert.FromBase64String(base64String));
                memoryStream.Seek(offset, SeekOrigin.Begin);
                return ReadBytesFromStream(memoryStream, chunkSize);
            }
        }

        private byte[] ReadBytesFromStream(Stream stream, int length)
        {
            // Read the specified number of bytes from the input stream and return them as a byte array.
            var buffer = new byte[length];
            var totalRead = 0;
            while (totalRead < length)
            {
                var read = stream.Read(buffer, totalRead, length - totalRead);
                if (read == 0)
                {
                    break;
                }
                totalRead += read;
            }
            return buffer;
        }

        private int CalculateOptimalChunkSize(long fileSizeInBytes, string accessToken)
        {
            // Determine the optimal chunk size based on the file size and the response time of the upload URL.
            var optimalChunkSize = 0;
            for (var i = 1; i <= 10; i++)
            {
                var currentOptimalChunkSize = (int)Math.Ceiling(fileSizeInBytes / Math.Pow(2, i));
                var currentUploadTime = CalculateFileUploadTime(currentOptimalChunkSize);
                if (currentUploadTime < totalUploadTime)
                {
                    optimalChunkSize = currentOptimalChunkSize;
                    totalUploadTime = currentUploadTime;
                }
            }
            return optimalChunkSize;
        }

        private long CalculateFileUploadTime(int chunkSize)
        {
