            var uploadUrl = _configuration["CloudStorage:UploadUrl"];
            var httpRequest = new HttpRequestMessage(HttpMethod.Get, uploadUrl);
            var httpResponse = await _httpClient.SendAsync(httpRequest);
            var responseTime = (long)httpResponse.Headers.Date.Subtract(DateTime.UtcNow).TotalMilliseconds;
            return responseTime * chunkSize / 1024 / 1024;
        }
    }
}
