package com.example;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class TaskScheduler {
    private static final int MAX_CONCURRENT_TASKS = 10;
    private ExecutorService executorService;
    private List<Task> taskList;

    public TaskScheduler() {
        this.executorService = Executors.newFixedThreadPool(MAX_CONCURRENT_TASKS);
        this.taskList = new ArrayList<>();
    }

    public void scheduleTask(String taskType, int priority, long executionTime) {
        Task task = new Task(taskType, priority, executionTime);
        taskList.add(task);
        executorService.execute(new Runnable() {
            @Override
            public void run() {
                try {
                    // Implement the task execution logic here
                } catch (Exception e) {
                    System.out.println("Task " + task.getId() + " failed: " + e.getMessage());
                } finally {
                    executorService.shutdown();
                }
            }
        });
    }

    public void cancelTask(String taskType, int priority) {
        Task task = new Task(taskType, priority);
        if (taskList.contains(task)) {
            taskList.remove(task);
            executorService.shutdown();
        }
    }

    public void executeTask(String taskType, int priority) {
        Task task = new Task(taskType, priority);
        if (taskList.contains(task)) {
            executorService.execute(new Runnable() {
                @Override
                public void run() {
                    try {
                        // Implement the task execution logic here
                    } catch (Exception e) {
                        System.out.println("Task " + task.getId() + " failed: " + e.getMessage());
                    } finally {
                        executorService.shutdown();
                    }
                }
            });
        }
    }

    public void clearTasks() {
        taskList.clear();
        executorService.shutdown();
    }
}

class Task {
    private String taskType;
    private int priority;
    private long executionTime;
    private int id; // Unique identifier for the task

    public Task(String taskType, int priority, long executionTime) {
        this.taskType = taskType;
        this.priority = priority;
        this.executionTime = executionTime;
        this.id = generateId();
    }

    private int generateId() {
        return (int) System.currentTimeMillis();
    }

    // Getters and setters for the task properties
}
