```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <pthread.h>
#include <time.h>

// Define the thread pool manager and its functions
struct thread_pool {
    int num_threads; // Number of threads in the pool
    pthread_t* threads; // Array of thread IDs
    int num_urls; // Number of URLs to scrape
    char** urls; // Array of URL strings
    int current_url; // Current URL index
    CURLM* curlm; // cURL multi handle
};

void* thread_pool_init(void) {
    struct thread_pool* tp = malloc(sizeof(struct thread_pool));
    if (!tp) {
        perror("Failed to allocate memory for thread pool");
        return NULL;
    }
    tp->num_threads = 0;
    tp->threads = NULL;
    tp->num_urls = 0;
    tp->urls = NULL;
    tp->current_url = 0;
    tp->curlm = curl_multi_init();
    return tp;
}

void thread_pool_free(struct thread_pool* tp) {
    free(tp->threads);
    free(tp->urls);
    curl_multi_cleanup(tp->curlm);
    free(tp);
}

int thread_pool_add_thread(struct thread_pool* tp) {
    if (tp->num_threads >= tp->num_urls) {
        return -1;
    }
    pthread_t thread = 0;
    if (pthread_create(&thread, NULL, thread_pool_worker, (void*)tp)) {
        perror("Failed to create thread");
        return -2;
    }
    tp->num_threads++;
    return 0;
}

int thread_pool_remove_thread(struct thread_pool* tp) {
    if (tp->num_threads <= 0) {
        return -1;
    }
    pthread_t thread = 0;
    if (pthread_join(thread, NULL)) {
        perror("Failed to join thread");
        return -2;
    }
    tp->num_threads--;
    return 0;
}

void* thread_pool_worker(void* data) {
    struct thread_pool* tp = (struct thread_pool*)data;
    while (1) {
        int url_index = tp->current_url++;
        if (url_index >= tp->num_urls) {
            break;
        }
        CURL* curl = curl_easy_init();
        if (!curl) {
            perror("Failed to initialize cURL");
            return NULL;
        }
        curl_easy_setopt(curl, CURLOPT_URL, tp->urls[url_index]);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        CURLcode res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "cURL error: %s\n", curl_easy_strerror(res));
            return NULL;
        }
        curl_easy_cleanup(curl);
    }
    return NULL;
}

size_t write_callback(void* contents, size_t size, size_t nmemb, void* userp) {
    ((struct thread_pool*)userp)->current_url--;
    return size * nmemb;
}

int main(int argc, char** argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s [options]\n", argv[0]);
        return -1;
    }
    struct thread_pool* tp = thread_pool_init();
    if (!tp) {
        perror("Failed to initialize thread pool");
        return -2;
    }
    // Set up cURL multi handle and configure options
    curl_multi_setopt(tp->curlm, CURLMOPT_SOCKETFUNCTION, sock_callback);
    curl_multi_setopt(tp->curlm, CURLMOPT_PIPELINING, 1L);
    // Add threads to the pool based on the number of URLs
    for (int i = 0; i < tp->num_urls; i++) {
        thread_pool_add_thread(tp);
    }
    // Set up URL list and start scraping
    tp->urls = malloc(sizeof(char*) * tp->num_urls);
    for (int i = 0; i < tp->num_urls; i++) {
        tp->urls[i] = strdup(argv[i+1]);
    }
    // Loop until all URLs have been scraped
    while (tp->current_url < tp->num_urls) {
        curl_multi_perform(tp->curlm, &tp->num_threads);
        if (tp->num_threads <= 0) {
            break;
        }
    }
    // Clean up and exit
    thread_pool_free(tp);
    return 0;
}
```
