<?php

class UserAuthentication {
    private $db;
    private $emailService;

    public function __construct($db, $emailService) {
        $this->db = $db;
        $this->emailService = $emailService;
    }

    public function authenticateUser($username, $password) {
        $salt = $this->retrieveSalt($username);
        if (!$salt) {
            return new UserNotFoundException("Invalid username");
        }

        // Verify the password using bcrypt and the retrieved salt
        $hashedPassword = crypt($password, $salt);
        if ($this->db->getUser($username)->getHashedPassword() === $hashedPassword) {
            return true;
        } else {
            return new PasswordIncorrectException("Invalid password");
        }
    }

    public function changeUserPassword($username, $newPassword) {
        // Generate a new salt and hash the new password using bcrypt with cost parameter 12
        $salt = bin2hex(openssl_random_pseudo_bytes(64));
        $hashedPassword = crypt($newPassword, $salt);

        // Update the user's password in the database
        $this->db->updateUserPassword($username, $hashedPassword, $salt);
    }

    public function forgotPassword($email) {
        // Validate the email format and check if the email exists in the simulated database
        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
            return new InvalidEmailException("Invalid email address");
        }

        $user = $this->db->getUserByEmail($email);
        if (!$user) {
            return new UserNotFoundException("The email does not exist in the database");
        }

        // Generate a unique token and store it in the database along with an expiration time
        $token = bin2hex(openssl_random_pseudo_bytes(64));
        $expiresAt = new DateTime('+1 day');
        $this->db->insertPasswordResetToken($user->getId(), $token, $expiresAt);

        // Send a password reset email to the user using the simulated email service API
        $this->emailService->sendPasswordResetEmail($user->getEmail(), $token);
    }

    public function resetPasswordUsingToken($token, $newPassword) {
        // Validate the token against the one stored in the database, ensuring it has not expired
        if (!$this->db->verifyPasswordResetToken($token)) {
            return new TokenExpiredException("The password reset token has expired");
        }

        $user = $this->db->getUserByPasswordResetToken($token);

        // Generate a new salt and hash the new password using bcrypt with cost parameter 12
        $salt = bin2hex(openssl_random_pseudo_bytes(64));
        $hashedPassword = crypt($newPassword, $salt);

        // Update the user's password in the database
        $this->db->updateUserPassword($user->getId(), $hashedPassword, $salt);
    }

    public function retrieveSalt($username) {
        $user = $this->db->getUser($username);
        if (!$user) {
            throw new UserNotFoundException("Invalid username");
        }

        return $user->getSalt();
    }
}
```
