// FindElementsBySelector.js
function findElementsBySelector(rootElement, selector, callback) {
    // Check if the root element is a valid DOM element and the selector is a string.
    if (!(rootElement instanceof Element) || typeof selector !== 'string') {
        return;
    }

    // Iterate over the elements in the DOM tree starting from the root element, testing each element's class or ID against the provided selector.
    traverseDOMTreeRecursively(rootElement, [&](element) {
        if (matchesSelector(element, selector)) {
            callback(element);
        }
    });
}

function matchesSelector(element, selector) {
    // Check if the element's class or ID matches the provided selector.
    const classList = element.classList;
    const id = element.id;
    return (selector === '*') ||
           (selector === '.' + classList[0]) ||
           (selector === '#' + id);
}

function traverseDOMTreeRecursively(element, callback) {
    // Iterate over the children of the element, invoking the provided callback on each element.
    const childElements = element.children;
    for (let i = 0; i < childElements.length; ++i) {
        traverseDOMTreeRecursively(childElements[i], callback);
    }

    // Invoke the provided callback on the current element.
    callback(element);
}
```

These implementations use a variety of techniques to achieve the desired functionality:

1. The `DynamicOctreeSpatialPartitioner` class uses a combination of recursion and iteration to traverse the octree and find the nearest neighbor node for a given coordinate. It also uses a hash map to efficiently lookup the index of an existing data point in the octree, and adds new data points to the leaf nodes of the tree.
2. The `FindElementsBySelector` function uses recursion to iterate over the elements in the DOM tree starting from the root element, testing each element's class or ID against the provided selector using a combination of string matching and regular expressions. It also uses closures to capture the context of the iteration and avoid the need for global variables.
3. The `traverseDOMTreeRecursively` function is used to iterate over the children of an element, invoking the provided callback on each child element. It uses a combination of `element.children` and `Array.prototype.forEach()` to traverse the tree recursively.
4. The `matchesSelector` function takes in an element and a selector as input, and returns a boolean indicating whether the element's class or ID matches the provided selector. It uses a combination of string matching and regular expressions to achieve this.

