using System;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json;

namespace ConsoleApp1
{
    class Program
    {
        static async Task Main(string[] args)
        {
            // Validate command-line arguments
            if (args == null || args.Length < 2)
            {
                throw new ArgumentException("Missing required command-line arguments.");
            }

            // Get the list of files to process from the command-line arguments
            var filePaths = args.Skip(1).ToList();

            // Create a logger instance
            var logger = LoggerFactory.CreateLogger<Program>();

            // Validate each file's directory path, accessibility, and .NET Core version
            foreach (var filePath in filePaths)
            {
                if (!Directory.Exists(Path.GetDirectoryName(filePath)))
                {
                    logger.LogError("Invalid directory path: {Path}", Path.GetDirectoryName(filePath));
                    return;
                }

                if (!File.Exists(filePath))
                {
                    logger.LogError("Invalid file path: {Path}", filePath);
                    return;
                }

                // Check if the .NET Core version is installed in the system
                var coreVersion = await GetDotNetCoreVersion();
                if (coreVersion == null)
                {
                    logger.LogError("Invalid .NET Core version");
                    return;
                }
            }

            // Process each file asynchronously using Task Parallel Library (TPL)
            var tasks = new List<Task>();
            foreach (var filePath in filePaths)
            {
                tasks.Add(ProcessFileAsync(filePath));
            }

            await Task.WhenAll(tasks);

            // Print the largest integer across all files
            Console.WriteLine("Largest integer: " + GetMaxInteger());

            // Calculate the average of all integers
            var sum = GetSum();
            Console.WriteLine("Average: " + (sum / filePaths.Count));
        }

        private static async Task ProcessFileAsync(string filePath)
        {
            try
            {
