class UserAuthentication {
    private $salt;
    private $bcrypt;
    private $database;

    public function __construct() {
        $this->salt = new Salt();
        $this->bcrypt = new Bcrypt(12);
        $this->database = new Database();
    }

    public function authenticateUser($username, $password) {
        if (!$this->validateUsernameAndPassword($username, $password)) {
            return false;
        }

        // Retrieve salt from database
        $salt = $this->database->getSalt($username);
        if ($salt === null) {
            throw new UserNotFoundException("User not found");
        }

        // Verify password using bcrypt and salt
        $hashedPassword = $this->bcrypt->hash($password, $salt);
        if (!$this->verifyPassword($username, $hashedPassword)) {
            throw new InvalidCredentialsException("Invalid credentials");
        }

        // Rate limiting mechanism
        $rateLimiter = new RateLimiter();
        if ($rateLimiter->isRateLimitExceeded()) {
            throw new RateLimitExceededException("Rate limit exceeded");
        }

        return true;
    }

    public function changeUserPassword($username, $newPassword) {
        if (!$this->validateUsernameAndPassword($username, $newPassword)) {
            return false;
        }

        // Generate new salt and hash new password using bcrypt
        $salt = $this->salt->generate();
        $hashedNewPassword = $this->bcrypt->hash($newPassword, $salt);

        // Pessimistic locking to handle potential race conditions
        $this->database->lock("users");

        // Update user's password in database
        if (!$this->updateUserPassword($username, $hashedNewPassword)) {
            $this->database->unlock();
            return false;
        }

        // Update salt in database
        if (!$this->updateSalt($username, $salt)) {
            $this->database->unlock();
            return false;
        }

        // Unlock database
        $this->database->unlock();

        return true;
    }

    public function forgotPassword($email) {
        if (!$this->validateEmailFormat($email)) {
            return false;
        }

        // Check if email exists in database
        $user = $this->database->getUserByEmail($email);
        if ($user === null) {
            throw new InvalidCredentialsException("Invalid credentials");
        }

        // Generate and send password reset token
        $token = $this->generateToken();
        $expirationTime = time() + 60 * 60; // 1 hour expiration time
        if (!$this->sendPasswordResetEmail($user, $token, $expirationTime)) {
            return false;
        }

        return true;
    }

    public function resetPasswordUsingToken($token, $newPassword) {
        if (!$this->validateUsernameAndPassword($username, $newPassword)) {
            return false;
        }

        // Validate token against database
        $user = $this->database->getUserByToken($token);
        if ($user === null) {
            throw new TokenInvalidException("Invalid token");
        }

        // Invalidate token after successful use
        if (!$this->invalidateToken($token)) {
            return false;
        }

        // Generate new salt and hash new password using bcrypt
        $salt = $this->salt->generate();
        $hashedNewPassword = $this->bcrypt->hash($newPassword, $salt);

        // Optimistic locking to handle potential race conditions during token validation and password reset process
        $this->database->lock("users");

        // Update user's password in database
        if (!$this->updateUserPassword($username, $hashedNewPassword)) {
            $this->database->unlock();
            return false;
        }

        // Update salt in database
        if (!$this->updateSalt($username, $salt)) {
            $this->database->unlock();
            return false;
        }

        // Unlock database
        $this->database->unlock();

        return true;
    }

    private function validateUsernameAndPassword($username, $password) {
