function copyBuffer(bufferList, byteCount) {
    let totalByteCount = 0;
    let currentChunkIndex = 0;
    let currentChunkOffset = 0;
    let newBuffer = Buffer.alloc(byteCount);
    let copiedBytes = 0;
    while (copiedBytes < byteCount) {
        const chunkSize = bufferList[currentChunkIndex].length - currentChunkOffset;
        const bytesToCopy = Math.min(chunkSize, byteCount - copiedBytes);
        bufferList[currentChunkIndex].copy(newBuffer, copiedBytes, currentChunkOffset, currentChunkOffset + bytesToCopy);
        totalByteCount += bytesToCopy;
        copiedBytes += bytesToCopy;
        currentChunkOffset += bytesToCopy;
        if (currentChunkOffset >= chunkSize) {
            currentChunkIndex++;
            currentChunkOffset = 0;
        }
    }
    return newBuffer;
}

