        return false;
    }

    // Start a transaction to ensure data integrity and handle exceptions
    try {
        // Update the status, last modified IP address, and last modified date in a single query
        $query = "UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = NOW() WHERE id = ?";
        $stmt = $this->db->prepare($query);
        $stmt->bind_param("iss", $newStatus, $ipAddress, $clinicId);
        $stmt->execute();

        // If the update was successful, commit the transaction and log the success
        if ($stmt->affected_rows > 0) {
            $this->db->commit();
            return true;
        }

        // If the update failed, rollback the transaction and log the error
        else {
            $this->db->rollback();
            $errorMessage = "Error updating clinic status: " . $stmt->error;
            logError($errorMessage);
            return false;
        }
    } catch (Exception $e) {
        // If an exception is thrown, rollback the transaction and log the error
        $this->db->rollback();
        $errorMessage = "Error updating clinic status: " . $e->getMessage();
        logError($errorMessage);
        return false;
    }
