# Caching mechanism to prevent re-uploading the same image within 24 hours
image_cache = {}

def upload_image(url, user):
    # Check if the image is already in the cache
    if url in image_cache:
        return image_cache[url]

    # Upload the image to S3 and add it to the cache
    response = s3_client.upload_file(url, s3_bucket)
    image_cache[url] = response["ETag"]

    # Return the ETag of the uploaded image
    return response["ETag"]

