static const char *TOKEN_VALIDATION_URL = "https://your-token-validation-server.com/api/validate";
static const int MAX_RETRIES = 3;

bool validateToken(const char *token) {
    json_object *jobj = NULL;
    CURL *curl = curl_easy_init();

    if (!curl) {
        fprintf(stderr, "Failed to initialize cURL\n");
        return false;
    }

    for (int i = 0; i < MAX_RETRIES; ++i) {
        curl_easy_setopt(curl, CURLOPT_URL, TOKEN_VALIDATION_URL);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, token);

        CURLcode res = curl_easy_perform(curl);
        if (res == CURLE_OK) {
            // Parse the JSON response
            jobj = json_tokener_parse(curl_easy_strerror(res));
            if (!jobj) {
                fprintf(stderr, "Failed to parse JSON response\n");
                curl_slist_free_all(curl_slist);
                return false;
            }
        } else {
            // Handle failed connection
            fprintf(stderr, "Connection failed: %s\n", curl_easy_strerror(res));
            if (i == MAX_RETRIES - 1) {
                // All retries failed, return false
                json_object_put(jobj);
                curl_slist_free_all(curl_slist);
                return false;
            } else {
                // Sleep and retry
                sleep(pow(2, i));
            }
        }
    }

    // Check for presence of required fields
    if (!json_object_get_string(jobj, "access_token")) {
        fprintf(stderr, "Missing access token\n");
        json_object_put(jobj);
        curl_slist_free_all(curl_slist);
        return false;
    }

    if (!json_object_get_int(jobj, "expires_in")) {
        fprintf(stderr, "Missing expiration time\n");
        json_object_put(jobj);
        curl_slist_free_all(curl_slist);
        return false;
    }

    if (!json_object_get_string(jobj, "token_type")) {
        fprintf(stderr, "Missing token type\n");
        json_object_put(jobj);
        curl_slist_free_all(curl_slist);
        return false;
    }

    if (!json_object_get_string(jobj, "access_token")) {
        fprintf(stderr, "Missing access token\n");
        json_object_put(jobj);
        curl_slist_free_all(curl_slist);
        return false;
    }

    // Check for validity of required fields
    if (!json_is_string(jobj, "access_token")) {
        fprintf(stderr, "Invalid access token\n");
        json_object_put(jobj);
        curl_slist_free_all(curl_slist);
        return false;
    }

    if (!json_is_number(jobj, "expires_in")) {
        fprintf(stderr, "Invalid expiration time\n");
        json_object_put(jobj);
        curl_slist_free_all(curl_slist);
        return false;
    }

    if (!json_is_string(jobj, "token_type")) {
        fprintf(stderr, "Invalid token type\n");
        json_object_put(jobj);
        curl_slist_free_all(curl_slist);
        return false;
    }

    if (!json_is_string(jobj, "refresh_token")) {
        fprintf(stderr, "Missing refresh token\n");
        json_object_put(jobj);
        curl_slist_free_all(curl_slist);
        return false;
    }

    // Check for validity of optional fields
    if (!json_is_string(jobj, "refresh_token")) {
        fprintf(stderr, "Invalid refresh token\n");
        json_object_put(jobj);
        curl_slist_free_all(curl_slist);
        return false;
    }

    // Handle any other edge cases or complex validation rules here

    // Clean up and return success
    json_object_put(jobj);
    curl_slist_free_all(curl_slist);
    return true;
}
