#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>
#include <algorithm>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

using namespace std;

struct ProcessingResult {
    int largestInteger;
    double average;
};

int main(int argc, char** argv) {
    if (argc != 3) {
        cerr << "Usage: " << argv[0] << " <input_directory> <output_directory>" << endl;
        return 1;
    }

    string inputDirectory = argv[1];
    string outputDirectory = argv[2];

    // Check if input and output directories exist
    struct stat st = {0};
    if (stat(inputDirectory.c_str(), &st) == -1 || !S_ISDIR(st.st_mode)) {
        cerr << "Input directory does not exist or is not a directory" << endl;
        return 2;
    }
    if (stat(outputDirectory.c_str(), &st) == -1 || !S_ISDIR(st.st_mode)) {
        cerr << "Output directory does not exist or is not a directory" << endl;
        return 3;
    }

    // Initialize logging system
    initLogging();

    // Get list of files in input directory
    vector<string> fileNames;
    getFilesInDirectory(inputDirectory, fileNames);

    // Process each file concurrently to improve performance
    vector<thread> threads;
    mutex mtx;
    condition_variable cv;
    int totalNumThreads = 0;
    for (const string& fileName : fileNames) {
        thread t([&]() {
            // Open file and read data
            ifstream fin(fileName, ios::binary);
            if (!fin.is_open()) {
                logError("Failed to open file " + fileName);
                return;
            }
            vector<int> integers;
            while (true) {
                int integer;
                fin >> integer;
                if (fin.eof()) {
                    break;
                } else if (fin.fail()) {
                    logError("Failed to read from file " + fileName);
                    return;
                }
                integers.push_back(integer);
            }
            fin.close();

            // Process data and update results
            ProcessingResult result = processData(integers);
            mtx.lock();
            totalNumThreads++;
            cv.notify_one();
            mtx.unlock();
        });
        threads.push_back(move(t));
    }

    // Wait for all threads to finish and calculate final results
    for (thread& t : threads) {
        t.join();
    }
    ProcessingResult finalResult = processData(totalNumThreads);

    // Write output file
    ofstream fout(outputDirectory + "/results.txt", ios::trunc);
    if (!fout.is_open()) {
        logError("Failed to open output file");
        return 4;
    }
    fout << "Largest integer: " << finalResult.largestInteger << endl;
    fout << "Average: " << finalResult.average << endl;
    fout.close();

    // Log processing details and end program
    logInfo("Processing completed successfully");
    return 0;
}

// Helper functions

void getFilesInDirectory(const string& directory, vector<string>& fileNames) {
    DIR* dir = opendir(directory.c_str());
    if (dir == nullptr) {
        throw runtime_error("Failed to open directory");
    }
    while (struct dirent* entry = readdir(dir)) {
        fileNames.push_back(entry->d_name);
    }
    closedir(dir);
}

void initLogging() {
    // Initialize logging system here
}

void logError(const string& message) {
    cerr << "ERROR: " << message << endl;
}

void logInfo(const string& message) {
    cout << "INFO: " << message << endl;
}

ProcessingResult processData(const vector<int>& integers) {
    // Process data here and return results
    int largestInteger = 0;
    double average = 0.0;
    for (const int& integer : integers) {
        if (integer > largestInteger) {
            largestInteger = integer;
        }
        average += integer;
    }
    return {largestInteger, average / integers.size()};
}
```
