const renderFooterScripts = async (scripts) => {
  const scriptElements = [];

  // Handle missing properties
  scripts.forEach((script) => {
    if (!script.code) {
      console.warn(`Missing "code" property for script ${script.src}. Using default value.`);
      script.code = "";
    }
    if (!script.type) {
      console.warn(`Missing "type" property for script ${script.src}. Using default value.`);
      script.type = "text/javascript";
    }
  });

  // Fetch scripts dynamically
  const fetchScripts = async () => {
    try {
      const response = await fetch("/api/scripts");
      if (!response.ok) {
        throw new Error(`Failed to fetch scripts: ${response.statusText}`);
      }
      return response.json();
    } catch (error) {
      console.error(error);
      return [];
    }
  };

  // Implement caching
  const cachedScripts = {};
  const getCachedScript = (src) => {
    if (!cachedScripts[src]) {
      cachedScripts[src] = fetchScripts().then((scripts) => scripts.find((script) => script.src === src));
    }
    return cachedScripts[src];
  };

  // Load scripts asynchronously
  const loadScripts = async () => {
    for (const script of scripts) {
      const src = script.src || "";
      if (!scriptElements[src]) {
        scriptElements[src] = document.createElement("script");
        scriptElements[src].setAttribute("type", script.type);
        scriptElements[src].innerHTML = script.code;
        document.body.appendChild(scriptElements[src]);
      }
    }
  };

  // DOM optimization
  const cleanupOldScripts = () => {
    for (const src in scriptElements) {
      if (!scripts.find((script) => script.src === src)) {
        document.body.removeChild(scriptElements[src]);
        delete scriptElements[src];
      }
    }
  };

  // Error handling and logging
  const handleError = (error) => {
    console.error(error);
    return [];
  };

  // User experience
  const loadingSpinner = document.createElement("div");
  loadingSpinner.innerHTML = "Loading scripts...";
  document.body.appendChild(loadingSpinner);

  // Modular design and script dependencies
  const loadScriptDependencies = (scripts) => {
    const dependencies = new Set();
    for (const script of scripts) {
      if (script.src) {
        dependencies.add(script.src);
      } else {
        dependencies.add(""); // Use empty string as a placeholder for inline scripts
      }
    }
    return Array.from(dependencies).map((src) => getCachedScript(src));
  };

  // Logging and performance considerations
  const logError = (error) => {
    console.error(error);
    return [];
  };

  try {
    const fetchedScripts = await fetchScripts();
    const dependencies = loadScriptDependencies(fetchedScripts);
    await Promise.allSettled(dependencies);
    cleanupOldScripts();
    loadingSpinner.remove();
    return fetchedScripts;
  } catch (error) {
    handleError(error);
  } finally {
    logError("Failed to load scripts");
  }
};
