            }

            // Initialize the random number generator
            MersenneTwister rng = new MersenneTwister();

            // Get the list of files to process
            List<string> filePaths = args.ToList();

            // Check if all files exist and are accessible
            foreach (var path in filePaths)
            {
                if (!File.Exists(path))
                {
                    Console.WriteLine($"Error: File not found - {path}");
                    return;
                }
                else if (!Directory.Exists(path))
                {
                    Console.WriteLine($"Error: Directory not found - {path}");
                    return;
                }
            }

            // Read the files and process the data
            var largest = 0L;
            long sum = 0L;
            foreach (var path in filePaths)
            {
                var numbers = File.ReadAllLines(path).Select(long.Parse);
                foreach (var number in numbers)
                {
                    if (number > largest)
                        largest = number;
                    sum += number;
                }
            }

            // Print the results
            Console.WriteLine("Largest integer: " + largest);
            Console.WriteLine("Average of all integers: " + (sum / filePaths.Count));

            // Clean up resources
            rng.Dispose();
        }
    }
}
```
This is a simple console application that implements a random number generator using the Mersenne Twister algorithm and reads large lists of integers from multiple files specified via command-line parameters, processes the data to find and print the largest integer across all files, and calculates the average of all integers. The program also ensures that each file's directory path is valid, accessible, and that a web.config file exists in the directory; if not, the program should return null and log any errors. It must also validate that each site name meets naming conventions and implement a timeout mechanism to prevent hanging indefinitely if the site fails to start. Furthermore, the application should support adding multiple sites to the same directory, each with their own unique port number, using asynchronous programming for improved responsiveness. The program must clean up any resources (such as processes) used after the operation completes and provide a user-friendly message when the site addition fails due to missing dependencies or configuration issues. To handle concurrent access to directories and files, the solution should be thread-safe. Additionally, the application should integrate with an external database to log the processed data and generate reports. The random number generator implementation should be encapsulated within the class and optimized for generating a specific range of numbers based on user input. Finally, the application should include unit tests to ensure the correctness of the random number generation and file processing logic, and the database integration should follow best practices for data security and transaction management.

