using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace SemaphoreManager
{
    public static class AESCBCEncryptionWithSemaphore
    {
        private const string SEMAPHORE_NAME = "my-semaphore";
        private const int MAX_SEMAPHORE_PERMITS = 100;

        public static async Task<string> DecryptAsync(string ciphertext, byte[] encryptionKey, byte[] iv, PaddingMode padding)
        {
            // Create and initialize the semaphore
            var semaphore = new Semaphore(MAX_SEMAPHORE_PERMITS, MAX_SEMAPHORE_PERMITS);

            try
            {
                // Acquire a permit from the semaphore
                await semaphore.WaitAsync();

                // Decrypt the ciphertext using AES-CBC
                var decrypted = Decrypt(ciphertext, encryptionKey, iv, padding);

                return decrypted;
            }
            finally
            {
                // Release the permit from the semaphore
                semaphore.Release();
            }
        }

        private static string Decrypt(string ciphertext, byte[] encryptionKey, byte[] iv, PaddingMode padding)
        {
            using (var aes = Aes.Create())
            {
                aes.Key = encryptionKey;
                aes.IV = iv;
                aes.Padding = padding;

                var decryptedBytes = aes.Decrypt(Encoding.UTF8.GetBytes(ciphertext));

                return Encoding.UTF8.GetString(decryptedBytes);
            }
        }
    }
}
