#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <sys/types.h>
#include <dirent.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

// Resource types enum
enum resource_type {
  RESOURCE_TYPE_IMAGE,
  RESOURCE_TYPE_TEXT,
  RESOURCE_TYPE_AUDIO
};

// Struct to hold the loaded resources and their counts
struct resource_bundle {
  int num_resources;
  struct resource_item *items;
};

// Struct to hold a single resource item
struct resource_item {
  enum resource_type type;
  void *data;
  size_t data_size;
  int count;
};

// Function to load the resource bundle from a file
struct resource_bundle *loadResourceBundle(const char *filepath) {
  // Open the file for reading
  FILE *fp = fopen(filepath, "r");
  if (!fp) {
    return NULL;
  }

  // Read the file into a buffer
  size_t bufsize = 0;
  char *buf = (char *)malloc(bufsize);
  while ((!feof(fp)) && (fread(buf, 1, bufsize, fp) > 0)) {
    bufsize += 1024;
    buf = (char *)realloc(buf, bufsize);
  }

  // Close the file
  fclose(fp);

  // Create a list of resource items
  struct resource_item *items = (struct resource_item *)malloc(sizeof(struct resource_item) * num_resources);
  int num_items = 0;

  // Parse the buffer and populate the resource items list
  char *line = buf;
  while ((line = strtok(line, "\n")) != NULL) {
    enum resource_type type;
    void *data;
    size_t data_size;
    int count;

    // Parse the line and extract the relevant information
    if (sscanf(line, "%d %s %zu", &count, "RESOURCE_TYPE_IMAGE", &data, &data_size) == 4) {
      type = RESOURCE_TYPE_IMAGE;
    } else if (sscanf(line, "%d %s %zu", &count, "RESOURCE_TYPE_TEXT", &data, &data_size) == 4) {
      type = RESOURCE_TYPE_TEXT;
    } else if (sscanf(line, "%d %s %zu", &count, "RESOURCE_TYPE_AUDIO", &data, &data_size) == 4) {
      type = RESOURCE_TYPE_AUDIO;
    } else {
      // Invalid resource format
      free(buf);
      return NULL;
    }

    // Create a new resource item and add it to the list
    items[num_items].type = type;
    items[num_items].data = data;
    items[num_items].data_size = data_size;
    items[num_items].count = count;
    num_items++;
  }

  // Create a resource bundle structure and populate it with the list of resource items
  struct resource_bundle *bundle = (struct resource_bundle *)malloc(sizeof(struct resource_bundle));
  bundle->num_resources = num_items;
  bundle->items = items;

  return bundle;
}
