// Struct to hold the parsed HTTP request information
struct http_request {
  const char *method;
  const char *path;
  const char *query_string;
  struct {
    const char *key;
    const char *value;
  } headers[];
};

// Function to parse an incoming HTTP request and extract relevant information
struct http_request *parse_http_request(const char *request) {
  // Create a new HTTP request structure
  struct http_request *req = (struct http_request *)malloc(sizeof(struct http_request));

  // Initialize the request method, path, and query string to empty strings
  req->method = "";
  req->path = "";
  req->query_string = "";

  // Parse the HTTP request line and extract the relevant information
  const char *line = strstr(request, "GET ");
  if (line) {
    // Extract the path from the request line
    size_t path_len = strcspn(line, "HTTP/");
    req->path = malloc(path_len + 1);
    memcpy(req->path, line, path_len);

    // Skip past the HTTP version string
    line += path_len;

    // Extract the query string if present
    if (*line == '?') {
      const char *query = strstr(line + 1, "HTTP/");
      if (query) {
        size_t query_len = strcspn(query, " HTTP/");
        req->query_string = malloc(query_len + 1);
        memcpy(req->query_string, query, query_len);
      }
    }
  } else {
    // Invalid HTTP request line
    free(req);
    return NULL;
  }

  return req;
}
