import os
import time
import threading
import random
from concurrent.futures import ThreadPoolExecutor

class MessageQueueClient:
    def __init__(self, brokers, queue_name):
        self.brokers = brokers
        self.queue_name = queue_name
        self.executor = ThreadPoolExecutor(max_workers=10)

    def _create_directory(self, directory_name):
        # Create a new directory with the given name and set an environment variable to its path
        os.makedirs(directory_name)
        os.environ["DIRECTORY_PATH"] = directory_name

    def _delete_temporary_files(self):
        # Delete any temporary files or directories left behind during the operation
        if os.path.exists("temp"):
            shutil.rmtree("temp")

    def _retry_directory_creation(self, directory_name):
        # Retry creating the directory in case of transient errors
        for i in range(5):
            try:
                self._create_directory(directory_name)
                return True
            except Exception as e:
                time.sleep(random.uniform(0, 2))
        return False

    def _connect_to_broker(self, broker):
        # Connect to a RabbitMQ or Kafka broker and return a connection object
        if broker == "RabbitMQ":
            from pika import BlockingConnection
            return BlockingConnection(pika.ConnectionParameters("localhost"))
        elif broker == "Kafka":
            from kafka import KafkaProducer
            return KafkaProducer(bootstrap_servers=["localhost:9092"])

    def _handle_connection_error(self, connection):
        # Handle connection errors by retrying up to 5 times with exponential backoff
        for i in range(5):
            try:
                return connection.connect()
            except Exception as e:
                time.sleep(random.uniform(0, 2) ** i)
        return False

    def _send_message(self, connection, message):
        # Send a message to the RabbitMQ or Kafka broker using the provided connection object
        if connection == "RabbitMQ":
            channel = connection.channel()
            channel.queue_declare(queue=self.queue_name)
            channel.basic_publish(exchange="", routing_key=self.queue_name, body=message)
        elif connection == "Kafka":
            producer = connection.send(self.queue_name, message)

    def _retry_message_sending(self, connection, message):
        # Retry sending a message in case of transient errors
        for i in range(5):
            try:
                self._send_message(connection, message)
                return True
            except Exception as e:
                time.sleep(random.uniform(0, 2))
        return False

    def _handle_message_delivery_error(self, connection, message):
        # Handle message delivery errors by retrying up to 5 times with exponential backoff
        for i in range(5):
            try:
                if connection == "RabbitMQ":
                    channel = connection.channel()
                    channel.basic_ack(message.delivery_tag)
                elif connection == "Kafka":
                    producer = connection.send(self.queue_name, message)
            except Exception as e:
                time.sleep(random.uniform(0, 2) ** i)
        return False

    def _filter_transaction(self, transaction):
        # Filter transactions based on criteria such as age, number of transactions in the past 3 seconds, and weighted sum
        if transaction["age"] > 3600:
            return False
        elif len(transaction["last_transactions"]) > 3:
            return False
        else:
            return True

    def _update_metrics(self, transaction):
        # Update a set of metrics with the maximum weighted sum and the corresponding transaction ID
        metrics = {"max_weighted_sum": transaction["weighted_sum"], "transaction_id": transaction["id"]}
        return metrics

    def _call_c_function(self, transaction):
        # Call the C function to filter transactions based on criteria such as age, number of transactions in the past 3 seconds, and weighted sum
        result = call_C_filtering_function(transaction)
        return result

    def _process_message(self, message):
        # Process a message using the C function to filter transactions based on criteria such as age, number of transactions in the past 3 seconds, and weighted sum
        transaction = json.loads(message.body)
        if self._filter_transaction(transaction):
            result = self._call_c_function(transaction)
            metrics = self._update_metrics(result)
            return metrics
        else:
            return None

    def _handle_message_failure(self, message):
        # Handle message failure by retrying up to 5 times with exponential backoff
        for i in range(5):
            try:
                self._process_message(message)
                break
            except Exception as e:
                time.sleep(random.uniform(0, 2) ** i)
        else:
            return False

    def run(self):
        # Run the message queue client using a mutex to prevent concurrent access and retries for failed messages
        with threading.Lock():
            while True:
                try:
                    connection = self._connect_to_broker(self.brokers)
                    if not self._handle_connection_error(connection):
                        continue
                    else:
                        for message in connection.consume(queue=self.queue_name, no_ack=True):
                            try:
                                metrics = self._process_message(message)
                                if metrics is not None:
                                    print("Max weighted sum:", metrics["max_weighted_sum"])
                                    print("Transaction ID:", metrics["transaction_id"])
                            except Exception as e:
                                self._handle_message_failure(message)
                except KeyboardInterrupt:
                    break
