int handle_http_post_request(const std::string& url, const std::vector<std::string>& input_parameters, const std::string& stored_procedure_name, ConnectionPool& connection_pool) {
    // Validate input parameters
    if (!validate_input_parameters(input_parameters)) {
        return 0;
    }

    // Check if stored procedure name is valid and exists in the database
    if (!stored_procedure_name.empty() && !connection_pool.is_stored_procedure_exists(stored_procedure_name)) {
        std::cerr << "Stored procedure does not exist: " << stored_procedure_name << std::endl;
        return 0;
    }

    // Check if connection pool is valid and has available connections
    if (connection_pool.is_empty()) {
        std::cerr << "No available database connections" << std::endl;
        return 0;
    }

    // Fork a child process to run the stored procedure in background
    pid_t child_pid = fork();
    if (child_pid == 0) {
        // Child process: run the stored procedure and exit
        int status = connection_pool.run_stored_procedure(stored_procedure_name, input_parameters);
        if (status != 0) {
            std::cerr << "Failed to execute stored procedure: " << stored_procedure_name << std::endl;
        }
        exit(status);
    } else if (child_pid < 0) {
        // Error forking child process
        std::cerr << "Error forking child process" << std::endl;
        return 0;
    }

    // Parent process: wait for the child process to finish and update the HTML content asynchronously
    int status = -1;
    while (waitpid(child_pid, &status, WNOHANG) == 0) {
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
    }

    if (!WIFEXITED(status)) {
        // Child process did not exit normally
        std::cerr << "Child process did not exit normally" << std::endl;
        return 0;
    }

    // Check if stored procedure execution was successful
    if (WEXITSTATUS(status) != 0) {
        std::cerr << "Stored procedure failed with status: " << WEXITSTATUS(status) << std::endl;
        return 0;
    }

    // Update HTML content asynchronously
    update_html_content(url, input_parameters);

    return 1;
}

