// Function to load a resource bundle from a file and return the number of items in the bundle
int load_resource_bundle(char *filepath) {
    int fd, num_items = 0;
    json_object *json_data = NULL;

    // Open the file for reading
    fd = open(filepath, O_RDONLY);
    if (fd < 0) {
        perror("Error opening file");
        return -1;
    }

    // Read the contents of the file into a JSON object
    char *json_str = malloc(sizeof(char) * 256);
    int read_bytes = read(fd, json_str, 256);
    if (read_bytes < 0) {
        perror("Error reading from file");
        close(fd);
        return -1;
    }
    json_str[read_bytes] = '\0';
    json_data = json_tokener_parse(json_str);
    free(json_str);
    if (json_data == NULL) {
        fprintf(stderr, "Error parsing JSON data\n");
        close(fd);
        return -1;
    }

    // Get the number of items in the bundle
    num_items = json_object_array_length(json_data);

    // Close the file descriptor
    close(fd);

    return num_items;
}

// Function to load a resource bundle from a file and return the number of items in the bundle, with AES-GCM encryption
int load_resource_bundle_encrypted(char *filepath, char *encryption_key) {
    int fd, num_items = 0;
    json_object *json_data = NULL;
    unsigned char iv[AES_BLOCK_SIZE], key[AES_KEY_SIZE];
    EVP_CIPHER_CTX *ctx;

    // Open the file for reading
    fd = open(filepath, O_RDONLY);
    if (fd < 0) {
        perror("Error opening file");
        return -1;
    }

    // Read the contents of the file into a JSON object
    char *json_str = malloc(sizeof(char) * 256);
    int read_bytes = read(fd, json_str, 256);
    if (read_bytes < 0) {
        perror("Error reading from file");
        close(fd);
        return -1;
    }
    json_str[read_bytes] = '\0';
    json_data = json_tokener_parse(json_str);
    free(json_str);
    if (json_data == NULL) {
        fprintf(stderr, "Error parsing JSON data\n");
        close(fd);
        return -1;
    }

    // Get the number of items in the bundle
    num_items = json_object_array_length(json_data);

    // Set up AES-GCM encryption with the provided key and IV
    ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        perror("Error creating cipher context");
        close(fd);
        return -1;
    }
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv)) {
        ERR_print_errors_fp(stderr);
        EVP_CIPHER_CTX_free(ctx);
        close(fd);
        return -1;
    }
    if (!EVP_CIPHER_CTX_set_padding(ctx, 0)) {
        ERR_print_errors_fp(stderr);
        EVP_CIPHER_CTX_free(ctx);
        close(fd);
        return -1;
    }

    // Encrypt the JSON data using AES-GCM
    unsigned char *ciphertext = malloc(sizeof(unsigned char) * (read_bytes + AES_BLOCK_SIZE));
    int ciphertext_len = 0;
    if (!EVP_EncryptUpdate(ctx, ciphertext, &ciphertext_len, json_str, read_bytes)) {
        ERR_print_errors_fp(stderr);
        EVP_CIPHER_CTX_free(ctx);
        close(fd);
        return -1;
    }
    ciphertext_len += AES_BLOCK_SIZE;
    if (!EVP_EncryptFinal_ex(ctx, ciphertext + ciphertext_len, &ciphertext_len)) {
        ERR_print_errors_fp(stderr);
        EVP_CIPHER_CTX_free(ctx);
        close(fd);
        return -1;
    }
    ciphertext_len += AES_BLOCK_SIZE;
    EVP_CIPHER_CTX_free(ctx);

    // Write the encrypted data back to the file
    write(fd, ciphertext, ciphertext_len);
    free(ciphertext);

    // Close the file descriptor
    close(fd);

    return num_items;
}

// Function to decrypt a resource bundle using AES-GCM and return the number of items in the bundle
int load_resource_bundle_decrypted(char *filepath, char *encryption_key) {
    int fd, num_items = 0;
    json_object *json_data = NULL;
    unsigned char iv[AES_BLOCK_SIZE], key[AES_KEY_SIZE];
    EVP_CIPHER_CTX *ctx;

    // Open the file for reading
    fd = open(filepath, O_RDONLY);
    if (fd < 0) {
        perror("Error opening file");
        return -1;
    }

    // Read the contents of the file into a JSON object
    char *json_str = malloc(sizeof(char) * 256);
    int read_bytes = read(fd, json_str, 256);
    if (read_bytes < 0) {
        perror("Error reading from file");
        close(fd);
        return -1;
    }
    json_str[read_bytes] = '\0';
    json_data = json_tokener_parse(json_str);
    free(json_str);
    if (json_data == NULL) {
        fprintf(stderr, "Error parsing JSON data\n");
        close(fd);
        return -1;
    }

    // Get the number of items in the bundle
    num_items = json_object_array_length(json_data);

    // Set up AES-GCM decryption with the provided key and IV
    ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        perror("Error creating cipher context");
        close(fd);
        return -1;
    }
    if (!EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv)) {
        ERR_print_errors_fp(stderr);
        EVP_CIPHER_CTX_free(ctx);
        close(fd);
        return -1;
    }
    if (!EVP_CIPHER_CTX_set_padding(ctx, 0)) {
        ERR_print_errors_fp(stderr);
        EVP_CIPHER_CTX_free(ctx);
        close(fd);
        return -1;
    }

    // Decrypt the JSON data using AES-GCM
    unsigned char *plaintext = malloc(sizeof(unsigned char) * (read_bytes + AES_BLOCK_SIZE));
    int plaintext_len = 0;
    if (!EVP_DecryptUpdate(ctx, plaintext, &plaintext_len, json_str, read_bytes)) {
        ERR_print_errors_fp(stderr);
        EVP_CIPHER_CTX_free(ctx);
        close(fd);
        return -1;
    }
    plaintext_len += AES_BLOCK_SIZE;
    if (!EVP_DecryptFinal_ex(ctx, plaintext + plaintext_len, &plaintext_len)) {
        ERR_print_errors_fp(stderr);
        EVP_CIPHER_CTX_free(ctx);
        close(fd);
        return -1;
    }
    plaintext_len += AES_BLOCK_SIZE;
    EVP_CIPHER_CTX_free(ctx);

    // Parse the decrypted JSON data as a JSON object
    json_data = json_tokener_parse(plaintext);
    free(plaintext);
    if (json_data == NULL) {
        fprintf(stderr, "Error parsing JSON data\n");
        close(fd);
        return -1;
    }

    // Get the number of items in the bundle
    num_items = json_object_array_length(json_data);

    // Close the file descriptor
    close(fd);

    return num_items;
}
