import java.io.File;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.logging.Level;
import java.util.logging.Logger;

public class FileProcessor {
    private static final Logger LOGGER = Logger.getLogger(FileProcessor.class.getName());

    public void processFileBatchWithValidation(String inputDirectory, String outputDirectory, List<Rule> validationRules) throws Exception {
        // Dynamically load and instantiate validation rule classes from the provided list of rules using reflection
        List<Validator> validators = new ArrayList<>();
        for (Rule rule : validationRules) {
            Validator validator = (Validator) Class.forName(rule.getClass().getName()).newInstance();
            validators.add(validator);
        }

        // Process files in parallel using a thread pool to manage concurrency and avoid overloading the system
        ExecutorService executor = Executors.newFixedThreadPool(10); // adjust this value based on your needs

        File inputDirectoryFile = new File(inputDirectory);
        File[] files = inputDirectoryFile.listFiles();

        for (File file : files) {
            String fileName = file.getName();
            executor.submit(() -> {
                try {
                    // Validate each file against all loaded validation rules, logging the start and end of each validation process
                    LOGGER.log(Level.INFO, "Starting validation for file: " + fileName);
                    for (Validator validator : validators) {
                        validator.validate(fileName);
                    }
                    LOGGER.log(Level.INFO, "Finished validation for file: " + fileName);
                } catch (Exception e) {
                    // Handle exceptions gracefully by logging the error and continuing with the next file in the batch
                    LOGGER.log(Level.SEVERE, "Error processing file: " + fileName, e);
                }
            });
        }

        executor.shutdown();
        while (!executor.isTerminated()) {
            // Wait for all threads to complete before continuing with the next step
        }
    }
}
