public class RandomValueGenerator {
    private static final Logger logger = Logger.getLogger(RandomValueGenerator.class.getName());

    public float generateRandomFloat() {
        return (float) Math.random();
    }

    public float generateRandomFloatNormal(float mean, float standardDeviation) {
        float x1 = generateRandomFloat();
        float x2 = generateRandomFloat();
        return mean + standardDeviation * Math.sqrt(-2 * Math.log(x1)) * Math.cos(2 * Math.PI * x2);
    }

    public float generateRandomFloatLogarithmic(float base, float exponent) {
        float randomValue = (float) Math.random();
        return (float) Math.pow(base, exponent * randomValue);
    }
}

public class FindElementsBySelector {
    private static final Logger logger = Logger.getLogger(FindElementsBySelector.class.getName());

    public List<WebElement> findElementsBySelector(WebDriver driver, String selector) {
        return driver.findElements(By.cssSelector(selector));
    }

    public List<WebElement> findElementsByAsyncSelector(WebDriver driver, String selector) {
        WebDriverWait wait = new WebDriverWait(driver, 10);
        FluentWait<WebDriver> fluentWait = wait.until((ExpectedConditions.presenceOfAllElementsLocatedBy(By.cssSelector(selector))));
        return fluentWait.get();
    }
}

