#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define LOG_INFO(...) fprintf(stderr, "[INFO] " __VA_ARGS__)
#define LOG_WARNING(...) fprintf(stderr, "[WARNING] " __VA_ARGS__)
#define LOG_ERROR(...) fprintf(stderr, "[ERROR] " __VA_ARGS__)

// Define the log level for the program
#define LOG_LEVEL_INFO

typedef struct {
    float *values;
    int count;
} line_t;

void read_line(char *line, line_t *l);
void parse_line(line_t *l);
float compute_average(line_t *l);
void write_results(line_t *l);

int main(int argc, char **argv) {
    FILE *input_file = NULL;
    FILE *output_file = NULL;
    char *input_filename = NULL;
    char *output_filename = NULL;

    // Initialize the input and output files
    if (argc < 3) {
        LOG_ERROR("Usage: %s <input_file> <output_file>\n", argv[0]);
        return 1;
    }
    input_filename = argv[1];
    output_filename = argv[2];
    if ((input_file = fopen(input_filename, "r")) == NULL) {
        LOG_ERROR("Failed to open input file %s\n", input_filename);
        return 1;
    }
    if ((output_file = fopen(output_filename, "w")) == NULL) {
        LOG_ERROR("Failed to create output file %s\n", output_filename);
        fclose(input_file);
        return 1;
    }

    // Read the input file line by line and process each line
    char line[2048];
    while (fgets(line, sizeof(line), input_file) != NULL) {
        line_t l;
        read_line(line, &l);
        parse_line(&l);
        if (l.count >= 3) {
            float average = compute_average(&l);
            write_results(&l);
            LOG_INFO("Line %d: Average: %.2f\n", l.count, average);
        } else {
            LOG_WARNING("Skipping line %d with less than 3 values\n", l.count);
        }
    }

    // Close the input and output files
    fclose(input_file);
    fclose(output_file);
    return 0;
}

void read_line(char *line, line_t *l) {
    l->count = 0;
    char *token = strtok(line, " ");
    while (token != NULL && l->count < 2048) {
        if (isdigit(token[0])) {
            l->values[l->count++] = atof(token);
        } else {
            LOG_WARNING("Skipping non-numeric value in line %d\n", l->count);
            return;
        }
        token = strtok(NULL, " ");
    }
}

void parse_line(line_t *l) {
    // Compute the average of the last three fields
    float sum = 0.0f;
    int i;
    for (i = l->count - 3; i < l->count; i++) {
        sum += l->values[i];
    }
    l->average = sum / 3.0f;
}

float compute_average(line_t *l) {
    return l->average;
}

void write_results(line_t *l) {
    fprintf(output_file, "%d,%.2f\n", l->count, l->average);
}
