// Rust function for creating directories and setting environment variables
fn create_directory(path: &str, dirname: &str) -> Result<(), String> {
    // Check if environment variable is already set
    let env = std::env::var(dirname);
    if !env.is_empty() {
        return Ok(());
    }

    // Create new directory with given name and permissions
    let mut builder = DirBuilder::new();
    builder.recursive(true);
    builder.mode(0o755);
    match builder.create(path) {
        Err(_) => return Err("Error: could not create directory".to_string()),
        Ok(_) => {}
    }

    // Set environment variable to path of newly created directory
    std::env::set_var(dirname, path);

    return Ok(());
}
