import java.util.concurrent.TimeUnit;

public class ServiceManager {
  private static final int HEARTBEAT_INTERVAL = 60; // seconds
  private static final int RETRY_DELAY = 10; // seconds
  private static final int MAX_RETRIES = 5;
  private static final String API_ENDPOINT = "https://example.com/api";
  private static final String LOGGING_ENDPOINT = "https://example.com/log";
