// Python Program using Flask-Login, Flask-Principal, and a DAO class
from flask import Flask, request, redirect, url_for, session, abort
from flask_login import LoginManager, UserMixin, login_user, logout_user, current_user
from flask_principal import Principal, RoleNeed, Permission, Need
from dao import DAO
from PIL import Image
import requests

# Initialize Flask app and configure extensions
