from typing import Dict, List, Union

class BookTitleExtractor:
    def __init__(self, corpus: str, api_urls: List[str], rate_limit: int = 10):
        self.corpus = corpus
        self.api_urls = api_urls
        self.rate_limit = rate_limit

    def extract_titles(self) -> Dict[str, int]:
        titles = {}

        # Process text corpus in batches to improve performance and efficiency
        for chunk in self._batch_corpus():
            # Extract book titles from current chunk of text
            for title in self._extract_titles(chunk):
                # Check if title is a valid book
                if self._is_valid_book(title):
                    # Increment count for title if already present, otherwise set to 1
                    titles[title] = titles.get(title, 0) + 1

        return titles

    def _batch_corpus(self) -> List[str]:
        # Split text corpus into batches of size <rate_limit> to avoid exceeding rate limit
        batch_size = self.rate_limit
        batches = [self.corpus[i:i+batch_size] for i in range(0, len(self.corpus), batch_size)]
        return batches

    def _extract_titles(self, chunk: str) -> List[str]:
        # Use optimized regular expressions to match book titles with high precision
        pattern = r"\b\w+(?:[: -]\w+)*\b"
        titles = re.findall(pattern, chunk)
        return titles

    def _is_valid_book(self, title: str) -> bool:
        # Verify book existence and details using external APIs
        for api_url in self.api_urls:
            response = self._query_api(api_url, title)
            if response:
                return True
        return False

    def _query_api(self, api_url: str, title: str) -> Union[None, Dict]:
        # Implement rate limiting and caching to handle API requests efficiently
        cache = {}
        key = (api_url, title)
        if key in cache:
            return cache[key]
        response = None
        try:
            response = json.loads(requests.get(api_url, params={"title": title}).text)
        except requests.exceptions.RequestException:
            pass
        cache[key] = response
        return response

    def _validate_token(self, token: str) -> bool:
        # Verify JWT token fields and values using external validation API
        try:
            payload = json.loads(jwt.decode(token, verify=False))
            required_fields = ["sub", "exp", "iat", "aud", "scope"]
            if all([field in payload for field in required_fields]):
                return True
        except jwt.InvalidTokenError:
            pass
        return False

    def _is_valid_token(self, token: str) -> bool:
        # Implement caching mechanisms to store frequently validated tokens and minimize API calls
        cache = {}
        key = token
        if key in cache:
            return cache[key]
        is_valid = self._validate_token(token)
        cache[key] = is_valid
        return is_valid

    def _log_error(self, message: str):
        # Log errors during API requests and validation for further analysis
        pass

if __name__ == "__main__":
    corpus = "This is a sample text corpus with book titles like 'To Kill a Mockingbird' by Harper Lee and 'The Great Gatsby' by F. Scott Fitzgerald."
