Finite State Automaton (FSA) Function:
```java
import java.util.ArrayList;
import java.util.List;

public class FSA {
  private final List<Integer> states;
  private final List<Integer> transitions;

  public FSA(int[] states, int size, List<Integer> transitions) {
    this.states = new ArrayList<>();
    for (int i = 0; i < size; i++) {
      this.states.add(i);
    }
    this.transitions = transitions;
  }

  public boolean isReachable(int startState, int endState) {
    // Check if the end state is reachable from the start state by iterating over the transitions and checking for each one
    for (Integer transition : transitions) {
      if (transition == endState) {
        return true;
      }
    }
    return false;
  }
}
