// JavaScript non-recursive function for traversing a DOM tree and returning elements that match a provided selector
function FindElementsBySelector(node, selector) {
    const results = [];

    // Test each element in the node against the provided selector
    if (node.matches(selector)) {
        results.push(node);
    }

    // Recursively traverse child nodes
    for (let i = 0; i < node.children.length; i++) {
        const childNode = node.children[i];
        FindElementsBySelector(childNode, selector).forEach((element) => results.push(element));
    }

    return results;
}
