    // Read input file in chunks and process entries concurrently
    size_t chunk_size = 128 * 1024; // 128KB
    size_t num_chunks = file_size / chunk_size;
    for (int i = 0; i < num_chunks; i++) {
        char* buffer = malloc(chunk_size);
        if (buffer == NULL) {
            perror("malloc");
            break;
        }

        // Read chunk from input file
