        }

        // Join all threads to ensure they complete
        for (int i = 0; i < concurrency; i++) {
            void* status;
            int error = pthread_join(thread[i], &status);
            if (error != 0) {
                perror("pthread_join");
            }
        }

        // Free buffer and continue reading next chunk
        free(buffer);
    }

    fclose(input_fp);
    fclose(output_fp);
}

