    private long cooldownPeriod = 1000;

    // Last time an attack was selected for a game character
    private Map<Integer, Long> lastAttackTime = new ConcurrentHashMap<>();

    public GameServerConnection() {
        // Initialize the asynchronous socket channel for establishing a connection to the game server
        clientChannel = AsynchronousSocketChannel.open();
    }

    /**
     * Establishes a connection to the game server using asynchronous non-blocking I/O operations and a Java Channel.
     * The method handles connection state changes and supports multiple concurrent connections.
     */
    public CompletableFuture<Void> connect(int characterId) {
        // Create a new asynchronous socket channel for the given character ID if it doesn't already exist
        if (!connections.containsKey(characterId)) {
            AsynchronousSocketChannel clientChannel = AsynchronousSocketChannel.open();
            connections.put(characterId, clientChannel);
        }

        // Get the asynchronous socket channel for the given character ID
        AsynchronousSocketChannel clientChannel = connections.get(characterId);

        // Connect to the game server using the asynchronous socket channel
        return clientChannel.connect("game-server:8080")
                .whenComplete((void, throwable) -> {
                    if (throwable != null) {
                        logger.log(Level.SEVERE, "Failed to connect to game server", throwable);
                    } else {
                        logger.info("Successfully connected to game server");
                    }
                });
    }

    /**
     * Disconnects from the game server using asynchronous non-blocking I/O operations and a Java Channel.
     */
    public CompletableFuture<Void> disconnect(int characterId) {
        // Get the asynchronous socket channel for the given character ID
        AsynchronousSocketChannel clientChannel = connections.get(characterId);

        // Disconnect from the game server using the asynchronous socket channel
        return clientChannel.close()
                .whenComplete((void, throwable) -> {
                    if (throwable != null) {
                        logger.log(Level.SEVERE, "Failed to disconnect from game server", throwable);
                    } else {
                        logger.info("Successfully disconnected from game server");
                    }
                });
    }

