        // Get the last time an attack was selected for the given character ID
        Long lastAttackTime = this.lastAttackTime.getOrDefault(characterId, 0L);

        // If the cooldown period has not yet elapsed, do nothing
        if (System.currentTimeMillis() - lastAttackTime < cooldownPeriod) {
            return;
        }

        // Select one of two attacks for the game character using the random selection mechanism
