import json
from typing import List, Optional

class JSONParser:
    def __init__(self):
        self.registry = {}

    def register_factory(self, id: str, factory: callable):
        self.registry[id] = factory

    def create_instance(self, id: str, data: dict) -> object:
        if id in self.registry:
            return self.registry[id](data)
        else:
            raise ValueError(f"Factory for ID {id} not found")

    @staticmethod
    def deserialize_object(bytes: bytes) -> dict:
        return json.loads(bytes)

    @staticmethod
    def generate_random_string(length: int = 16) -> str:
        import secrets
        import hashlib

        alphabet = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ'
        return ''.join(secrets.choice(alphabet) for _ in range(length))

    def insert_element(self, element: str, position: int = None) -> None:
        if not isinstance(element, str):
            raise ValueError("Element must be a string")
        if position is not None and not isinstance(position, int):
            raise ValueError("Position must be an integer or None")
        if position is None:
            self.forward_list.append(element)
        else:
            for i in range(len(self.forward_list)):
                if self.forward_list[i] == element:
                    break
            else:
                raise ValueError("Element not found")
            self.forward_list.insert(position, element)

    def search_element(self, element: str) -> int:
        for i in range(len(self.forward_list)):
            if self.forward_list[i] == element:
                return i
        else:
            raise ValueError("Element not found")

class JSONObject:
    def __init__(self, data: dict):
        self.data = data

    @staticmethod
    def serialize(instance: object) -> bytes:
        return json.dumps(instance.data).encode()

    @staticmethod
    def deserialize(bytes: bytes) -> object:
        return JSONObject(JSONParser.deserialize_object(bytes))
