<?php

// Generate secure random string using a given character set
function generateRandomString($length, $charset) {
    $randomString = '';
    for ($i = 0; $i < $length; $i++) {
        $randomString .= $charset[rand(0, strlen($charset))];
    }
    return $randomString;
}

// Hash a given password with a customizable hash algorithm (e.g., bcrypt, Argon2id) and include salting for added security
function hashPassword($password, $algorithm = 'bcrypt') {
    if (!in_array($algorithm, hash_algos())) {
        throw new Exception('Invalid hashing algorithm');
    }
    $salt = random_bytes(22);
    return hash($algorithm, $password . $salt) . '{' . $salt . '}';
}

// Validate input parameters and handle any potential errors during the generation and hashing processes
function generateAndHashPassword($password, $algorithm = 'bcrypt') {
    if (empty($password)) {
        throw new Exception('Password is required');
    }
    try {
        return hashPassword($password, $algorithm);
    } catch (Exception $e) {
        throw new Exception('Error generating and hashing password: ' . $e->getMessage());
    }
}

// Validate input parameters and handle any potential errors during the generation and hashing processes
function generateAndHashPasswordWithSalt($password, $algorithm = 'bcrypt') {
    if (empty($password)) {
        throw new Exception('Password is required');
    }
    try {
        return hashPassword($password, $algorithm) . '{salt}';
    } catch (Exception $e) {
        throw new Exception('Error generating and hashing password with salt: ' . $e->getMessage());
    }
}

// Read a file synchronously from a directory and return its contents as a string using the `fs` library
function readFileSync($path, $encoding = 'UTF-8') {
    if (!file_exists($path)) {
        throw new Exception('File not found');
    }
    try {
        return file_get_contents($path, false, null, 0, filesize($path));
    } catch (Exception $e) {
        throw new Exception('Error reading file: ' . $e->getMessage());
    }
}
