#include <iostream>
#include <fstream>
#include <vector>
#include <algorithm>
#include <numeric>
#include <map>
#include <string>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <functional>

using namespace std;

const int MAX_INTEGER = 1000000;
const int MIN_INTEGER = -MAX_INTEGER;

struct HistogramBin {
    int lowerBound;
    int upperBound;
    size_t count;
};

vector<HistogramBin> generateHistogram(const vector<int>& integers) {
    // Generate histogram bins based on integer range.
    vector<HistogramBin> histogramBins;
    for (int i = MIN_INTEGER; i <= MAX_INTEGER; i += 100) {
        HistogramBin bin;
        bin.lowerBound = i;
        bin.upperBound = min(i + 99, MAX_INTEGER);
        histogramBins.push_back(bin);
    }
    return histogramBins;
}

void processFile(ifstream& file) {
    // Read integers from file and store in vector.
    vector<int> integers;
    int integer;
    while (file >> integer && integer >= MIN_INTEGER && integer <= MAX_INTEGER) {
        integers.push_back(integer);
    }

    // Calculate largest integer and average of all integers.
    auto largestInteger = *max_element(integers.begin(), integers.end());
    auto average = accumulate(integers.begin(), integers.end(), 0) / static_cast<double>(integers.size());

    // Generate histogram of integer frequencies.
    vector<HistogramBin> histogramBins = generateHistogram(integers);

    // Print results to console.
    cout << "Largest integer: " << largestInteger << endl;
    cout << "Average of all integers: " << average << endl;
    for (const auto& bin : histogramBins) {
        cout << "Histogram bin (" << bin.lowerBound << ", " << bin.upperBound << "): " << bin.count << endl;
    }
}

int main(int argc, char** argv) {
    // Check command-line parameters for input files.
    if (argc < 2) {
        cerr << "Usage: " << argv[0] << " input_files..." << endl;
        return 1;
    }

    // Create vector of threads to process each file concurrently.
    vector<thread> threads;
    for (int i = 1; i < argc; ++i) {
        string filename = argv[i];
        ifstream file(filename);
        if (!file.is_open()) {
            cerr << "Error opening file: " << filename << endl;
            return 1;
        }
        threads.push_back(thread(processFile, ref(file)));
    }

    // Join threads to ensure all files are processed before exiting.
    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
