#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <semaphore.h>
#include <pthread.h>
#include <time.h>

// Macro for generating a random integer within a given range
#define RAND_INT(min, max) (rand() % ((max) + 1 - (min)) + (min))

// Struct to hold the information of a PDU for CRC indication
typedef struct {
    int rx_ue_information_tag; // Tag for RX UEs
    int rnti; // RNTI of the UE
    int crc_indication_rel8_tag; // Tag for CRC indication
    int crcflag; // Flag for CRC calculation
} NFAPI_CRC_INDICATION_PDU_T;

// Function to load and initialize JavaScript files asynchronously
void async_load_javascript_files(char **file_list, int num_files) {
    // Create a semaphore to synchronize the loading of the files
    sem_t *sem = sem_open("file_loading", O_CREAT | O_EXCL, 0644, 1);

    // Initialize an array to hold the pointers to the loaded JavaScript files
    char **js_files = malloc(sizeof(char*) * num_files);

    // Loop through the file list and load each file asynchronously
    for (int i = 0; i < num_files; ++i) {
        // Create a new thread to load the file
        pthread_t thread;
        pthread_create(&thread, NULL, load_javascript_file, (void*)&file_list[i]);

        // Wait for the semaphore to be signaled before proceeding
        sem_wait(sem);
    }

    // Clean up the semaphore and the array of file pointers
    sem_close(sem);
    free(js_files);
}

// Function to load a JavaScript file asynchronously
void* load_javascript_file(void *file) {
    // Get the name of the file to be loaded
    char *filename = (char*)file;

    // Load the file into memory and initialize it
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening file: ");
        return NULL;
    }
    fseek(fp, 0L, SEEK_END);
    long file_size = ftell(fp);
    rewind(fp);
    char *file_data = malloc(sizeof(char) * (file_size + 1));
    if (!file_data) {
        perror("Error allocating memory for file: ");
        fclose(fp);
        return NULL;
    }
    fread(file_data, sizeof(char), file_size, fp);
    fclose(fp);
    file_data[file_size] = '\0';

    // Initialize the JavaScript engine and evaluate the file
    JsEngine *engine = js_create_engine();
    if (!engine) {
        perror("Error creating JavaScript engine: ");
        free(file_data);
        return NULL;
    }
    JsValue *value = js_eval_string(engine, file_data);
    if (!value) {
        perror("Error evaluating JavaScript code: ");
        js_destroy_engine(engine);
        free(file_data);
        return NULL;
    }
    js_destroy_engine(engine);
    free(file_data);

    // Signal the semaphore to indicate that the file has been loaded
    sem_post(sem);
}

// Function to generate a list of random integers within a given range
void rand_int_list(int *array, int num_ints, int min, int max) {
    // Loop through the array and set each element to a random integer
    for (int i = 0; i < num_ints; ++i) {
        array[i] = RAND_INT(min, max);
    }
}

// Function to create and initialize an array of 'record' structures
void create_record_array(NFAPI_CRC_INDICATION_PDU_T **record_array, int num_records) {
    // Allocate memory for the array of record structures
    *record_array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_records);

    // Initialize each record structure with a random RX UEs and CRCFLAG
    for (int i = 0; i < num_records; ++i) {
        (*record_array)[i].rx_ue_information_tag = RAND_INT(1, 256);
        (*record_array)[i].rnti = RAND_INT(1, 4096);
        (*record_array)[i].crc_indication_rel8_tag = RAND_INT(1, 256);
        (*record_array)[i].crcflag = RAND_INT(0, 1);
    }
}

// Main function to read a list of integers from standard input, store them in an array, and use a semaphore for thread synchronization
int main() {
    // Get the number of records to be created
    int num_records;
    printf("Enter the number of records: ");
    scanf("%d", &num_records);

    // Create an array to hold the record structures
    NFAPI_CRC_INDICATION_PDU_T *record_array = NULL;

    // Initialize the semaphore and create the array of 'record' structures
    sem_t *sem = sem_open("record_lock", O_CREAT | O_EXCL, 0644, 1);
    create_record_array(&record_array, num_records);

    // Loop through the record array and set each element to a random integer within a given range
    for (int i = 0; i < num_records; ++i) {
        rand_int_list(record_array[i].rx_ue_information_tag, 1);
        rand_int_list(record_array[i].rnti, 1);
        rand_int_list(record_array[i].crc_indication_rel8_tag, 1);
        record_array[i].crcflag = RAND_INT(0, 1);
    }

    // Load the specified JavaScript files asynchronously
    char *file_list[] = {"file1.js", "file2.js", "file3.js"};
    int num_files = sizeof(file_list) / sizeof(char*);
    for (int i = 0; i < num_files; ++i) {
        char *filename = file_list[i];
        pthread_t thread;
        if (pthread_create(&thread, NULL, load_file, filename)) {
            perror("Error creating thread");
            return 1;
        }
    }

    // Wait for all threads to finish
    void *status;
    for (int i = 0; i < num_files; ++i) {
        if (pthread_join(thread, &status)) {
            perror("Error joining thread");
            return 1;
        }
    }

    // Destroy the semaphore and free the memory allocated to the record array
    sem_close(sem);
    free(record_array);

    return 0;
}
