#include <stdio.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <sys/socket.h>
#include <unistd.h>
#include <errno.h>

// Assume u_char and error code definitions are provided

int resolveHostWithTimeout(const char *hostname, u_char *ipAddress, size_t ipAddressLength, const char *dnsServers[], int timeout) {
    // Validate input parameters
    if (hostname == NULL || ipAddress == NULL || ipAddressLength < 16 || dnsServers == NULL || timeout <= 0) {
        return ERROR;
    }

    // Initialize DNS servers and timeout
    struct addrinfo hints, *servinfo, *p;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to return IPv4 or IPv6 address
    hints.ai_socktype = SOCK_STREAM;
    if (getaddrinfo(dnsServers[0], "domain", &hints, &servinfo) != 0) {
        // Handle error
        printf("Failed to get DNS server info\n");
        return ERROR;
    }

    // Iterate through DNS servers and try to resolve hostname
    int i = 0;
    for (p = servinfo; p != NULL; p = p->ai_next) {
        // Create socket and set timeout
        int sock = socket(p->ai_family, p->ai_socktype, p->ai_protocol);
        if (setsockopt(sock, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(timeout)) < 0) {
            // Handle error
            printf("Failed to set socket timeout\n");
            return ERROR;
        }

        // Resolve hostname and get IP address
        struct addrinfo *res = NULL;
        if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
            // Handle error
            printf("Failed to resolve hostname\n");
            return ERROR;
        }

        // Copy IP address to output parameter
        memcpy(ipAddress, res->ai_addr->sa_data+2, 16);
        freeaddrinfo(res);

        // Close socket and return success
        close(sock);
        return SUCCESS;
    }

    // All DNS servers failed to resolve hostname
    printf("Failed to resolve hostname using all DNS servers\n");
    return ERROR;
}

int main() {
    const char *hostname = "example.com";
    u_char ipAddress[16];
    int timeout = 3000; // milliseconds
    const char *dnsServers[] = {"8.8.8.8", "8.8.4.4"};

    // Resolve hostname with DNS servers and timeout
    int result = resolveHostWithTimeout(hostname, ipAddress, 16, dnsServers, timeout);
    if (result == SUCCESS) {
        printf("Resolved %s to %s\n", hostname, inet_ntop(AF_INET, ipAddress, NULL, 0));
    } else {
        printf("Failed to resolve %s\n", hostname);
    }

    return 0;
}

