// Database of attacks, stored in memory for efficiency
struct AttackDatabase {
  std::string name;
  int cooldownPeriod;
};
std::unordered_map<std::string, AttackDatabase> attackDB;

// Caching mechanism to minimize redundant database queries
std::mutex cacheMutex;
std::unordered_map<std::string, AttackDatabase> cache;

// Real-time updates through WebSockets
std::vector<WebSocket*> websockets;

// Thread-safe function to update the attack database and notify all connected WebSockets
void updateAttackDatabase(const std::string& attackName, int cooldownPeriod) {
  std::lock_guard<std::mutex> lock(cacheMutex);

  // Update the attack database in memory
  AttackDatabase db = {attackName, cooldownPeriod};
  cache[attackName] = db;

  // Notify all connected WebSockets of the update
  for (WebSocket* ws : websockets) {
    ws->send(Json::encode({{"type", "update"}, {"data", {{"name", attackName}, {"cooldown", cooldownPeriod}}}}));
  }
}

// Thread-safe function to retrieve an attack from the database based on its name
AttackDatabase getAttack(const std::string& attackName) {
  std::lock_guard<std::mutex> lock(cacheMutex);

  // Check if the attack is in the cache
  if (cache.find(attackName) != cache.end()) {
    return cache[attackName];
  }

  // If not, retrieve it from the database and add it to the cache
  std::string json = httpRequest("GET", "/api/attacks/" + attackName);
  Json::Value root = Json::parse(json);
  AttackDatabase db;
  db.name = root["name"].asString();
  db.cooldownPeriod = root["cooldown_period"].asInt();
  cache[attackName] = db;

  return db;
}

// Thread-safe function to select an attack for a character based on its type and cooldown period
std::string selectAttack(const std::string& characterType, int cooldownPeriod) {
  // Retrieve the list of available attacks from the database
  std::vector<AttackDatabase> attacks = getAllAttacks();

  // Filter the list based on the character type and cooldown period
  std::vector<AttackDatabase> filteredAttacks;
  for (const AttackDatabase& attack : attacks) {
    if (attack.cooldownPeriod == cooldownPeriod && attack.name.find(characterType) != std::string::npos) {
      filteredAttacks.push_back(attack);
    }
  }

  // Select a random attack from the filtered list
  if (filteredAttacks.size() > 0) {
    return filteredAttacks[rand() % filteredAttacks.size()].name;
  } else {
    return "";
  }
}
