public class StringHasher
{
    private readonly ILogger _logger = LogManager.CreateLogger(typeof(StringHasher));
    private readonly HashAlgorithm _md5 = MD5.Create();
    private readonly HashAlgorithm _sha256 = SHA256.Create();
    private readonly Dictionary<string, string> _hashCache;
    private readonly int _threadPoolSize;

    public StringHasher(int threadPoolSize)
    {
        _threadPoolSize = threadPoolSize;
        _hashCache = new Dictionary<string, string>();
    }

    // Compute the MD5 hash of a single string
    public string GetMD5Hash(string input)
    {
        if (input == null) throw new ArgumentNullException(nameof(input));

        var md5 = _md5.ComputeHash(Encoding.UTF8.GetBytes(input));
        return BitConverter.ToString(md5).Replace("-", "").ToLowerInvariant();
    }

    // Compute the SHA-256 hash of a single string
    public string GetSHA256Hash(string input)
    {
        if (input == null) throw new ArgumentNullException(nameof(input));

        var sha256 = _sha256.ComputeHash(Encoding.UTF8.GetBytes(input));
        return BitConverter.ToString(sha256).Replace("-", "").ToLowerInvariant();
    }

    // Compute the hash of a single string using a custom hashing algorithm
    public string GetCustomHash(string input, HashAlgorithm algorithm)
    {
        if (input == null) throw new ArgumentNullException(nameof(input));

        var bytes = Encoding.UTF8.GetBytes(input);
        var hash = algorithm.ComputeHash(bytes);
        return BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
    }

    // Hash an array of strings in parallel for improved throughput, with dynamic thread pool size management
    public async Task<List<string>> GetHashesAsync(string[] inputs)
    {
        var hashes = new List<string>(inputs.Length);
        var tasks = new List<Task<string>>(inputs.Length);

        foreach (var input in inputs)
        {
            if (input == null) throw new ArgumentNullException(nameof(input));

            tasks.Add(GetHashAsync(input));
        }

        await Task.WhenAll(tasks);

        foreach (var task in tasks)
        {
            hashes.Add(task.Result);
        }

        return hashes;
    }

    // Validate the correctness of generated hashes against known hash values
    public bool ValidateHash(string input, string expectedHash)
    {
        if (input == null) throw new ArgumentNullException(nameof(input));

        var actualHash = GetMD5Hash(input);
        return actualHash.Equals(expectedHash, StringComparison.OrdinalIgnoreCase);
    }

    // Validate the correctness of generated hashes against known hash values using a custom hashing algorithm
    public bool ValidateCustomHash(string input, string expectedHash, HashAlgorithm algorithm)
    {
        if (input == null) throw new ArgumentNullException(nameof(input));

        var actualHash = GetCustomHash(input, algorithm);
        return actualHash.Equals(expectedHash, StringComparison.OrdinalIgnoreCase);
    }

    // Manage resources effectively by caching previously computed hashes for improved performance
    public string GetCachedHash(string input)
    {
        if (input == null) throw new ArgumentNullException(nameof(input));

        if (_hashCache.ContainsKey(input)) return _hashCache[input];

        var hash = GetMD5Hash(input);
        _hashCache.Add(input, hash);

        return hash;
    }

    // Handle input validation to ensure that only non-null strings are processed and handle extremely long strings efficiently
    public string ProcessInput(string input)
    {
        if (input == null) throw new ArgumentNullException(nameof(input));

        var sb = new StringBuilder();
        foreach (var c in input)
        {
            if (char.IsWhiteSpace(c)) continue;
            sb.Append(c);
        }

        return sb.ToString();
    }

    // Log errors and exceptions during hashing operations to a specified log file and integrate with an external logging service
    public void LogError(Exception ex)
    {
        _logger.Error(ex, "An error occurred while hashing a string");
    }

    // Implement a thread-safe caching mechanism for previously computed hashes to improve performance
    private readonly object _cacheLock = new object();
    public void AddHashToCache(string input, string hash)
    {
        lock (_cacheLock)
        {
            _hashCache.Add(input, hash);
        }
    }

    // Implement a thread-safe mechanism to handle multi-threaded database access and ensure data integrity during concurrent hashing and storage operations
    private readonly object _dbLock = new object();
    public void StoreHashesInDatabase(List<string> hashes)
    {
        lock (_dbLock)
