using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Linq;
using System.Threading.Tasks;

public class DynamicQueryExecutor
{
    private readonly SqlConnection _connection;
    private readonly Dictionary<string, object> _parameters;
    private readonly string _queryTemplate;
    private readonly int _pageSize;
    private readonly bool _paginateResults;

    public DynamicQueryExecutor(SqlConnection connection, string queryTemplate, Dictionary<string, object> parameters, int pageSize = 1000, bool paginateResults = true)
    {
        _connection = connection;
        _queryTemplate = queryTemplate;
        _parameters = parameters;
        _pageSize = pageSize;
        _paginateResults = paginateResults;
    }

    public async Task<List<dynamic>> ExecuteQueryAsync()
    {
        using var command = _connection.CreateCommand();
        command.CommandText = BuildQuery(_queryTemplate, _parameters);
        command.CommandType = CommandType.Text;

        ValidateInputParameters(command);

        await OpenConnectionIfClosedAsync(command);
        await BeginTransactionIfNecessaryAsync(command);

        var resultSet = new List<dynamic>();
        using (var reader = command.ExecuteReader())
        {
            while (await reader.ReadAsync())
            {
                var row = new Dictionary<string, object>();
                for (int i = 0; i < reader.FieldCount; i++)
                {
                    row.Add(reader.GetName(i), reader[i]);
                }
                resultSet.Add(row);
            }
        }

        if (_paginateResults)
        {
            var pageCount = (int)Math.Ceiling((double)resultSet.Count / _pageSize);
            return resultSet.Skip((_currentPage - 1) * _pageSize).Take(_pageSize).ToList();
        }

        return resultSet;
    }

    public void Dispose()
    {
        _connection?.Dispose();
    }

    private async Task OpenConnectionIfClosedAsync(SqlCommand command)
    {
        if (_connection.State == ConnectionState.Closed)
        {
            await _connection.OpenAsync();
        }
    }

    private void ValidateInputParameters(SqlCommand command)
    {
        foreach (var parameter in _parameters)
        {
            // Check for SQL injection attacks by validating the input parameters against a whitelist of allowed types and values
            if (!IsValidParameterValue(parameter.Value))
            {
                throw new Exception($"Invalid input parameter '{parameter.Key}' with value '{parameter.Value}'. This may be an attempt to perform a SQL injection attack.");
            }
        }
    }

    private bool IsValidParameterValue(object value)
    {
        // TODO: Implement your own logic for validating input parameters against a whitelist of allowed types and values.
        // This should include things like checking for SQL injection attacks, as well as ensuring that the parameter value is within an acceptable range.
        return true;
    }

    private async Task BeginTransactionIfNecessaryAsync(SqlCommand command)
    {
        if (_connection.State == ConnectionState.Closed || _connection.AutoEnlist)
        {
            await _connection.BeginTransactionAsync();
        }
    }

    private string BuildQuery(string queryTemplate, Dictionary<string, object> parameters)
    {
        var query = queryTemplate;

        // Replace parameter placeholders with their corresponding values
        foreach (var parameter in parameters)
        {
            if (parameter.Value is null)
            {
                continue;
            }

            var value = parameter.Value;
            var parameterName = $"@{parameter.Key}";

            // Handle multiple data types for parameters
            switch (value)
            {
                case string stringValue:
                    query = query.Replace(parameterName, stringValue);
                    break;
                case int intValue:
                    query = query.Replace(parameterName, intValue.ToString());
                    break;
                case bool boolValue:
                    query = query.Replace(parameterName, boolValue ? "1" : "0");
                    break;
                case decimal decimalValue:
                    query = query.Replace(parameterName, decimalValue.ToString());
                    break;
                case DateTime dateTimeValue:
                    query = query.Replace(parameterName, dateTimeValue.ToString("yyyy-MM-dd HH:mm:ss"));
                    break;
                case Guid guidValue:
                    query = query.Replace(parameterName, guidValue.ToString());
                    break;
            }
        }

        return query;
    }
}
