import java.util.Base64;
import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import org.json.*;

public class DynamicContentManagement {
  private static final String AES_KEY = "YOUR_AES_KEY"; // Replace with your AES key
  private static final String AES_IV = "YOUR_AES_IV"; // Replace with your AES initialization vector

  public void handleRequest(String request) {
    try {
      JSONObject jsonRequest = new JSONObject(request);
      int pageId = jsonRequest.getInt("pageId");
      int sectionId = jsonRequest.getInt("sectionId");
      int elementId = jsonRequest.getInt("elementId");
      String encryptedContent = jsonRequest.getString("content");

      // Validate JSON format
      if (!jsonRequest.has("pageId") || !jsonRequest.has("sectionId") || !jsonRequest.has("elementId")) {
        throw new IllegalArgumentException("Invalid JSON format.");
      }

      // Decrypt content using AES encryption
      SecretKeySpec key = new SecretKeySpec(AES_KEY.getBytes(), "AES");
      IvParameterSpec iv = new IvParameterSpec(AES_IV.getBytes());
      Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
      cipher.init(Cipher.DECRYPT_MODE, key, iv);
      byte[] decryptedContent = cipher.doFinal(Base64.getDecoder().decode(encryptedContent));

      // Update element in database
      String updatedContent = new String(decryptedContent, "UTF-8");
      DatabaseConnection connection = new DatabaseConnection();
      connection.updateElement(pageId, sectionId, elementId, updatedContent);
      connection.close();

      // Send acknowledgment to client
      JSONObject response = new JSONObject();
      response.put("status", "success");
      response.put("message", "Element updated successfully.");
      System.out.println(response.toString());
    } catch (Exception e) {
      // Handle exceptions gracefully
      e.printStackTrace();
      JSONObject error = new JSONObject();
      error.put("status", "error");
      error.put("message", e.getMessage());
      System.out.println(error.toString());
    }
  }
}
