class FileHandler:
    def read_file(self, filename: str) -> List[str]:
        try:
            with open(filename, "r") as f:
                return [line.strip() for line in f.readlines()]
        except Exception as e:
            print(f"Error reading file {filename}: {e}")
            return []

    def sort_lines(self, lines: List[str]) -> List[str]:
        try:
            return sorted(lines)
        except Exception as e:
            print(f"Error sorting lines: {e}")
            return []

    def extract_sequence_number(self, line: str) -> int:
        try:
            match = re.search(r"\d+", line)
            if not match:
                raise ValueError("No sequence number found in line")
            return int(match.group())
        except Exception as e:
            print(f"Error extracting sequence number from {line}: {e}")
            return 0

    def handle_exceptions(self, func):
        def wrapper(*args, **kwargs):
            try:
                return func(*args, **kwargs)
            except Exception as e:
                print(f"Error in function {func.__name__}: {e}")
                return []
        return wrapper

    @handle_exceptions
    def modify_file_extension(self, filename: str, new_extension: str) -> str:
        if not new_extension.startswith("."):
            new_extension = "." + new_extension
        return os.path.splitext(filename)[0] + new_extension

    @handle_exceptions
    def get_file_size(self, filename: str) -> int:
        try:
            stat = os.stat(filename)
            return stat.st_size
        except Exception as e:
            print(f"Error getting file size for {filename}: {e}")
            return 0

    @handle_exceptions
    def get_file_last_modified(self, filename: str) -> int:
        try:
            stat = os.stat(filename)
            return stat.st_mtime
        except Exception as e:
            print(f"Error getting file last modified for {filename}: {e}")
            return 0

    @handle_exceptions
    def check_file_exists(self, filename: str) -> bool:
        try:
            return os.path.exists(filename)
        except Exception as e:
            print(f"Error checking if file {filename} exists: {e}")
            return False

    @handle_exceptions
    def check_file_is_empty(self, filename: str) -> bool:
        try:
            with open(filename, "r") as f:
                return not bool(f.read())
        except Exception as e:
            print(f"Error checking if file {filename} is empty: {e}")
            return True

    @handle_exceptions
    def check_file_contains(self, filename: str, pattern: str) -> bool:
        try:
            with open(filename, "r") as f:
                return re.search(pattern, f.read()) is not None
        except Exception as e:
            print(f"Error checking if file {filename} contains {pattern}: {e}")
            return False

    @handle_exceptions
    def get_file_lines(self, filename: str) -> List[str]:
        try:
            with open(filename, "r") as f:
                return [line.strip() for line in f.readlines()]
        except Exception as e:
            print(f"Error reading file {filename}: {e}")
            return []

    @handle_exceptions
    def get_file_content(self, filename: str) -> str:
        try:
            with open(filename, "r") as f:
                return f.read()
        except Exception as e:
            print(f"Error reading file {filename}: {e}")
            return ""

    @handle_exceptions
    def write_file(self, filename: str, content: str) -> bool:
        try:
            with open(filename, "w") as f:
                f.write(content)
            return True
        except Exception as e:
            print(f"Error writing to file {filename}: {e}")
            return False

    @handle_exceptions
    def append_to_file(self, filename: str, content: str) -> bool:
        try:
            with open(filename, "a") as f:
                f.write(content)
            return True
        except Exception as e:
            print(f"Error appending to file {filename}: {e}")
            return False

    @handle_exceptions
    def create_file(self, filename: str) -> bool:
        try:
            with open(filename, "w") as f:
                pass
            return True
        except Exception as e:
            print(f"Error creating file {filename}: {e}")
            return False

    @handle_exceptions
