class ContainerManager:
    def __init__(self):
        self.container_configs = {}
        self.k8s_client = client.CoreV1Api()

    def get_container_config(self, container_name: str) -> Dict[str, Any]:
        return self.container_configs.get(container_name)

    def set_container_config(self, container_name: str, config: Dict[str, Any]):
        self.container_configs[container_name] = config

    def start_container(self, container_name: str):
        try:
            config = self.get_container_config(container_name)
            if not config:
                raise ValueError("No configuration found for container")
            deployment = client.V1Deployment(
                metadata=client.V1ObjectMeta(name=container_name),
                spec=client.V1DeploymentSpec(
                    replicas=config["replicas"],
                    selector=client.V1LabelSelector(match_labels={"app": container_name}),
                    template=client.V1PodTemplateSpec(
                        metadata=client.V1ObjectMeta(labels={"app": container_name}),
                        spec=client.V1PodSpec(containers=[config["container"]])
                    )
                )
            )
            self.k8s_client.create_deployment(deployment)
        except Exception as e:
            print(f"Error starting container {container_name}: {e}")

    def stop_container(self, container_name: str):
        try:
            config = self.get_container_config(container_name)
            if not config:
                raise ValueError("No configuration found for container")
            deployment = client.V1Deployment(
                metadata=client.V1ObjectMeta(name=container_name),
                spec=client.V1DeploymentSpec(
                    replicas=0,
                    selector=client.V1LabelSelector(match_labels={"app": container_name}),
                    template=client.V1PodTemplateSpec(
                        metadata=client.V1ObjectMeta(labels={"app": container_name}),
                        spec=client.V1PodSpec(containers=[config["container"]])
                    )
                )
            )
            self.k8s_client.replace_deployment(name=container_name, body=deployment)
        except Exception as e:
            print(f"Error stopping container {container_name}: {e}")

    def get_container_status(self, container_name: str) -> Dict[str, Any]:
        try:
            config = self.get_container_config(container_name)
            if not config:
                raise ValueError("No configuration found for container")
            pods = self.k8s_client.list_namespaced_pod(namespace="default", label_selector=f"app={container_name}")
            if not pods or len(pods.items) == 0:
                return {"status": "Not Found"}
            else:
                status = pods.items[0].status
                return {
                    "status": status,
                    "phase": status.phase,
                    "containerStatuses": status.container_statuses
                }
        except Exception as e:
            print(f"Error getting container status for {container_name}: {e}")

    def get_logs(self, container_name: str) -> str:
        try:
            config = self.get_container_config(container_name)
            if not config:
                raise ValueError("No configuration found for container")
            pods = self.k8s_client.list_namespaced_pod(namespace="default", label_selector=f"app={container_name}")
            if not pods or len(pods.items) == 0:
                return ""
            else:
                logs = self.k8s_client.read_namespaced_pod_log(pods.items[0].metadata.name, "default", container=config["container"]["name"])
                return logs
        except Exception as e:
            print(f"Error getting logs for {container_name}: {e}")

    def create_persistent_volume(self, volume_name: str, size: int) -> bool:
        try:
            pv = client.V1PersistentVolume()
            pv.metadata = client.V1ObjectMeta(name=volume_name)
            pv.spec = {
                "accessModes": ["ReadWriteOnce"],
                "capacity": {"storage": f"{size}Gi"},
                "hostPath": {"path": "/mnt/data"}
            }
            self.k8s_client.create_persistent_volume(pv)
            return True
        except Exception as e:
            print(f"Error creating persistent volume {volume_name}: {e}")

    def delete_persistent_volume(self, volume_name: str) -> bool:
        try:
            self.k8s_client.delete_collection_namespaced_persistent_volume(f"{volume_name}", "default", grace_period=0)
            return True
        except Exception as e:
            print(f"Error deleting persistent volume {volume_name}: {e}")

    def create_persistent_volume_claim(self, claim_name: str, size: int) -> bool:
        try:
            pvc = client.V1PersistentVolumeClaim()
            pvc.metadata = client.V1ObjectMeta(name=claim_name)
            pvc.spec = {
                "accessModes": ["ReadWriteOnce"],
                "resources": {"requests": {"storage": f"{size}Gi"}}
            }
            self.k8s_client.create_namespaced_persistent_volume_claim("default", pvc)
            return True
        except Exception as e:
            print(f"Error creating persistent volume claim {claim_name}: {e}")

    def delete_persistent_volume_claim(self, claim_name: str) -> bool:
        try:
            self.k8s_client.delete_collection_namespaced_persistent_volume_claim(f"{claim_name}", "default", grace_period=0)
            return True
        except Exception as e:
            print(f"Error deleting persistent volume claim {claim_name}: {e}")

    def get_persistent_volume_status(self, volume_name: str) -> Dict[str, Any]:
        try:
            pv = self.k8s_client.read_namespaced_persistent_volume(volume_name, "default")
            return {
                "status": pv.status,
                "phase": pv.status.phase,
                "capacity": pv.spec.capacity["storage"]
            }
        except Exception as e:
            print(f"Error getting persistent volume status for {volume_name}: {e}")

    def get_persistent_volume_claim_status(self, claim_name: str) -> Dict[str, Any]:
        try:
            pvc = self.k8s_client.read_namespaced_persistent_volume_claim(claim_name, "default")
            return {
                "status": pvc.status,
                "phase": pvc.status.phase,
                "capacity": pvc.spec.resources["requests"]["storage"]
            }
        except Exception as e:
