    if image_file.size > 1024 * 1024:
        raise ValueError('Image file is too large')
    elif not image_file.content_type == 'image/jpeg' or 'image/png':
        raise ValueError('Invalid image format')

    # Cache the updated profile picture for faster retrieval
    user.profile_picture = image_file

    # Store the updated profile picture in the distributed database system
    try:
        dao.update_user_profile_picture(user)
    except ExternalAPIError:
        logging.error('Failed to update user profile picture')
        raise ValueError('Failed to update user profile picture')

# Define a function for handling asynchronous loading of JSON files
async def load_files(filenames):
    return await FileLoader(app.config['JSON_PATH']).load_files(filenames)

# Define a function for handling error conditions during asynchronous file loading
