```java
import java.net.*;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import javax.net.ssl.SSLEngineResult;
import javax.net.ssl.SSLHandshakeException;
import javax.net.ssl.SSLSocketFactory;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import com.google.common.util.concurrent.RateLimiter;

public class SecureHighPerformanceConnectionPool {
  private static final Logger LOGGER = LoggerFactory.getLogger(SecureHighPerformanceConnectionPool.class);

  // Connection pool settings
  private int maxActiveConnections = 100;
  private int connectionTimeoutMillis = 30_000;
  private int idleConnectionTimeoutMillis = 60_000;
  private int sslHandshakeTimeoutMillis = 20_000;
  private int maxConnectionsPerHost = 10;

  // SSL/TLS settings
  private SSLSocketFactory sslSocketFactory;
  private String[] cipherSuites;
  private boolean enableCipherSuiteBlacklisting;
  private String[] protocols;
  private boolean enableProtocolBlacklisting;
  private int sessionCacheSize = 50_000;
  private int sessionTimeoutMillis = 1800_000; // 30 minutes

  // Connection pool and SSL/TLS engine
  private ScheduledExecutorService connectionPoolScheduler;
  private Executors.newFixedThreadPool(maxActiveConnections);
  private SSLEngine sslEngine;

  public SecureHighPerformanceConnectionPool() {
    // Initialize SSL/TLS engine
    sslSocketFactory = SSLSocketFactory.getDefault();
    cipherSuites = null;
    enableCipherSuiteBlacklisting = false;
    protocols = new String[] {"TLSv1.3", "TLSv1.2"};
    enableProtocolBlacklisting = true;

    // Initialize connection pool and SSL/TLS engine
    connectionPoolScheduler = Executors.newFixedThreadPool(maxActiveConnections);
    sslEngine = sslSocketFactory.createSSLEngine();
  }

  public void establishConnection(String host, int port) throws IOException {
    // Validate input parameters
    if (host == null || host.isEmpty()) {
      throw new IllegalArgumentException("Invalid host: " + host);
    }
    if (port <= 0 || port > 65535) {
      throw new IllegalArgumentException("Invalid port: " + port);
    }

    // Create a new connection pool entry and start the connection process
    ConnectionPoolEntry connectionPoolEntry = new ConnectionPoolEntry(host, port);
    connectionPoolScheduler.execute(() -> connect(connectionPoolEntry));
  }

  private void connect(ConnectionPoolEntry connectionPoolEntry) {
    // Establish a secure, high-performance connection to the remote server using NIO channels
    SocketChannel socketChannel = null;
    SSLSocketChannel sslSocketChannel = null;
    try {
      // Create a new socket channel and configure it for non-blocking I/O
      socketChannel = SocketChannel.open(new InetSocketAddress(connectionPoolEntry.host, connectionPoolEntry.port));
      socketChannel.configureBlocking(false);

      // Create an SSLSocketChannel using the specified SSL/TLS engine and configure it for non-blocking I/O
      sslSocketChannel = (SSLSocketChannel) sslEngine.wrap(socketChannel, null, 0);
      sslSocketChannel.configureBlocking(false);

      // Perform an SSL/TLS handshake with the remote server
      SSLHandshakeException sslHandshakeException = null;
      for (int i = 0; i < 5; i++) {
        try {
          SSLEngineResult result = sslEngine.wrap(null, ByteBuffer.allocate(0), null);
          if (result.getStatus() == SSLEngineResult.HandshakeStatus.FINISHED) {
            break;
          } else if (result.getStatus() == SSLEngineResult.HandshakeStatus.NEED_WRAP ||
                  result.getStatus() == SSLEngineResult.HandshakeStatus.NEED_UNWRAP) {
            sslSocketChannel.write(ByteBuffer.allocate(0));
          } else if (result.getStatus() == SSLEngineResult.HandshakeStatus.NEED_TASK) {
            Runnable task = sslEngine.delegatedTask();
            task.run();
          } else {
            throw new SSLHandshakeException("Unexpected SSL/TLS handshake status: " + result.getStatus());
          }
        } catch (SSLHandshakeException e) {
          sslHandshakeException = e;
        }
      }

      // If an SSL/TLS handshake failure occurred, throw the exception
      if (sslHandshakeException != null) {
        throw sslHandshakeException;
      }

      // Register the newly established connection with the connection pool
      connectionPoolEntry.registerConnection(sslSocketChannel);
    } catch (IOException | SSLHandshakeException e) {
      if (socketChannel != null) {
        try {
          socketChannel.close();
        } catch (IOException ex) {
          LOGGER.error("Failed to close socket channel", ex);
        }
      }
      if (sslSocketChannel != null) {
        try {
          sslSocketChannel.close();
        } catch (IOException ex) {
          LOGGER.error("Failed to close SSL/TLS socket channel", ex);
        }
      }
      throw e;
    }
  }

  public void closeConnection(String host, int port) {
    // Validate input parameters
    if (host == null || host.isEmpty()) {
      throw new IllegalArgumentException("Invalid host: " + host);
    }
    if (port <= 0 || port > 65535) {
      throw new IllegalArgumentException("Invalid port: " + port);
    }

    // Find the connection pool entry for the specified host and port and close it
    ConnectionPoolEntry connectionPoolEntry = findConnectionPoolEntry(host, port);
    if (connectionPoolEntry != null) {
      try {
        connectionPoolEntry.close();
      } catch (IOException e) {
        LOGGER.error("Failed to close connection pool entry", e);
      }
    }
  }

  private ConnectionPoolEntry findConnectionPoolEntry(String host, int port) {
    // Iterate through the connection pool and search for a matching host and port
    synchronized (connectionPoolScheduler) {
      for (ConnectionPoolEntry connectionPoolEntry : connectionPoolEntries) {
        if (host.equals(connectionPoolEntry.host) && port == connectionPoolEntry.port) {
          return connectionPoolEntry;
        }
      }
    }
    return null;
  }

  private class ConnectionPoolEntry {
    private String host;
    private int port;
    private SSLSocketChannel sslSocketChannel;
    private long creationTime;

    public ConnectionPoolEntry(String host, int port) {
      this.host = host;
      this.port = port;
      this.creationTime = System.currentTimeMillis();
    }

    public void registerConnection(SSLSocketChannel sslSocketChannel) {
      synchronized (connectionPoolScheduler) {
        // Add the new connection to the connection pool and mark it as active
        this.sslSocketChannel = sslSocketChannel;
        this.creationTime = System.currentTimeMillis();
        connectionPoolEntries.add(this);
      }
    }

    public void close() throws IOException {
      synchronized (connectionPoolScheduler) {
        // Close the SSLSocketChannel and remove it from the connection pool
        this.sslSocketChannel.close();
        connectionPoolEntries.remove(this);
      }
    }
  }
}
