namespace Example
{
    static class Program
    {
        static void Main(string[] args)
        {
            // Create a new SSL/TLS client and connect to the remote server
            var sslClient = new SslClient("www.example.com", 443, false);
            sslClient.Connect();

            // Send an HTTP GET request to the server
            var httpRequest = "GET / HTTP/1.0\r\nHost: www.example.com\r\n\r\n";
            var bytes = Encoding.ASCII.GetBytes(httpRequest);
            sslClient.Write(bytes, 0, bytes.Length);

            // Read the server's response
            var buffer = new byte[sslClient.ReceiveBufferSize];
            var readCount = sslClient.Read(buffer, 0, buffer.Length);
            Console.WriteLine("Received {0} bytes from server", readCount);

            // Close the SSL/TLS connection
            sslClient.Disconnect();
        }
    }

    class SslClient
    {
        private TcpClient tcpClient;
        private SslStream sslStream;

        public SslClient(string host, int port, bool ignoreCertificateErrors)
        {
            // Create a new TCP/IP client and connect to the remote server
            tcpClient = new TcpClient(host, port);

            // Create an SSL/TLS stream and authenticate with the server
            sslStream = new SslStream(tcpClient.GetStream(), false,
                (sender, certificate, chain, errors) => ignoreCertificateErrors ? true : false);
            sslStream.AuthenticateAsClient(host);
        }

        public void Connect()
        {
            // Start the SSL/TLS handshake
            sslStream.BeginWrite(new byte[0], 0, 0, null, null);
        }

        public void Disconnect()
        {
            // Shutdown and close the SSL/TLS stream
            sslStream.Close();

            // Close the TCP/IP client
            tcpClient.Close();
        }

        public int Read(byte[] buffer, int offset, int count)
        {
            return sslStream.Read(buffer, offset, count);
        }

        public void Write(byte[] buffer, int offset, int count)
        {
            sslStream.Write(buffer, offset, count);
        }
    }
}
