#include <openssl/err.h>

int main() {
    // Create an SSL context and load the CA certificates
    SSL_CTX* ctx = SSL_CTX_new(TLSv1_client_method());
    if (!ctx) {
        std::cout << "Error: Failed to create SSL context" << std::endl;
        return 1;
    }

    // Load the CA certificates
    if (SSL_CTX_load_verify_locations(ctx, "path/to/ca-bundle.crt", NULL) != 1) {
        SSL_CTX_free(ctx);
        std::cout << "Error: Failed to load CA certificates" << std::endl;
        return 1;
    }

    // Create a new socket and connect to the remote server using SSL/TLS
    SSL* ssl = SSL_new(ctx);
    if (!ssl) {
        SSL_CTX_free(ctx);
        std::cout << "Error: Failed to create SSL object" << std::endl;
        return 1;
    }

    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock == -1) {
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        std::cout << "Error: Failed to create socket" << std::endl;
        return 1;
    }

    struct sockaddr_in server_addr = {
        AF_INET, htons(443), inet_addr("www.example.com")
    };

    if (connect(sock, (struct sockaddr*)&server_addr, sizeof(server_addr)) == -1) {
        close(sock);
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        std::cout << "Error: Failed to connect to server" << std::endl;
        return 1;
    }

    // Send an HTTP GET request to the server
    SSL_set_fd(ssl, sock);
    if (SSL_connect(ssl) != 1) {
        close(sock);
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        std::cout << "Error: Failed to establish SSL connection" << std::endl;
        return 1;
    }

    // Send the HTTP request
    char httpRequest[] = "GET / HTTP/1.0\r\nHost: www.example.com\r\n\r\n";
    if (SSL_write(ssl, httpRequest, sizeof(httpRequest)) != sizeof(httpRequest)) {
        close(sock);
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        std::cout << "Error: Failed to send HTTP request" << std::endl;
        return 1;
    }

    // Read the server's response
    char buffer[4096];
    int bytesRead = SSL_read(ssl, buffer, sizeof(buffer));
    if (bytesRead <= 0) {
        close(sock);
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        std::cout << "Error: Failed to read response from server" << std::endl;
        return 1;
    }

    // Print the server's response
    buffer[bytesRead] = '\0';
    std::cout << buffer << std::endl;

    // Close the SSL/TLS connection and socket
    SSL_free(ssl);
    SSL_CTX_free(ctx);
    close(sock);

    return 0;
}
