```
public static class DatabaseHelper
{
    private static readonly ConcurrentDictionary<string, object> _cache = new ConcurrentDictionary<string, object>();

    public static async Task<IEnumerable<T>> QueryAsync<T>(DbConnection connection, string commandTemplate, IDictionary<string, object> parameters) where T : class
    {
        // Validate input parameters to prevent SQL injection attacks
        if (connection == null || string.IsNullOrEmpty(commandTemplate))
        {
            throw new ArgumentException("Invalid input parameters");
        }

        // Build a dictionary of parameter names and their corresponding values
        var paramDictionary = parameters?.ToDictionary(p => p.Key, p => p.Value);

        // Prepare the SQL query using the command template and parameters
        var query = new StringBuilder();
        query.Append(commandTemplate);
        foreach (var parameter in paramDictionary)
        {
            var value = parameter.Value;
            if (value == null || value is DBNull)
            {
                continue;
            }
            else if (value is string || value is char)
            {
                query.Append($"'{value}'");
            }
            else if (value is DateTime dateTimeValue)
            {
                query.Append($@"'{dateTimeValue:yyyy-MM-dd HH:mm:ss}'");
            }
            else if (value is IEnumerable enumerableValue)
            {
                var array = ((IEnumerable)value).ToArray();
                foreach (var item in array)
                {
                    query.Append($"'{item}'");
                }
            }
        }

        // Check if the generated SQL query is in the cache
        string cachedQueryKey = $"{query}";
        if (_cache.ContainsKey(cachedQueryKey))
        {
            return (IEnumerable<T>)_cache[cachedQueryKey];
        }

        // Execute the SQL query and store the results in the cache
        var result = await connection.QueryAsync<T>(query.ToString());
        _cache.TryAdd(cachedQueryKey, result);

        return result;
    }

    public static async Task<int> ExecuteAsync(DbConnection connection, string commandTemplate, IDictionary<string, object> parameters)
    {
        // Validate input parameters to prevent SQL injection attacks
        if (connection == null || string.IsNullOrEmpty(commandTemplate))
        {
            throw new ArgumentException("Invalid input parameters");
