class PaymentProcessor:
    def __init__(self):
        self.payment_gateways = {
            'credit_card': CreditCardGateway(),
            'paypal': PayPalGateway()
        }
        self.order_statuses = {
            'pending',
            'shipped',
            'canceled'
        }

    def processPayment(self, order_id, payment_method, amount):
        # Validate inputs
        if not order_id or not payment_method or not amount:
            return "Invalid input"

        # Handle different payment gateways
        gateway = self.payment_gateways[payment_method]
        try:
            result = gateway.process(order_id, amount)
        except Exception as e:
            # Retry logic
            for _ in range(5):
                time.sleep(1)
                try:
                    result = gateway.process(order_id, amount)
                    break
                except Exception as e:
                    pass
            else:
                return "Payment failed"
        if result != "success":
            return "Payment pending"
        return "Payment successful"

    def refundPayment(self, order_id, refund_amount):
        # Validate inputs
        if not order_id or not refund_amount:
            return "Invalid input"

        # Query transaction details and calculate refund amount
        gateway = self.payment_gateways[order.payment_method]
        try:
            txn = gateway.get_transaction(order_id)
        except Exception as e:
            return "Refund failed"
        if not txn:
            return "No transaction found"
        refund_amount = min(txn.amount, refund_amount)

        # Initiate refund process
        try:
            result = gateway.refund(order_id, refund_amount)
        except Exception as e:
            return "Refund failed"
        if result != "success":
            return "Refund pending"
        return "Refund successful"

    def createOrder(self, customer_id, items, total_amount):
        # Validate inputs
        if not customer_id or not items or not total_amount:
            return "Invalid input"

        # Insert order into database
        try:
            order = Order.objects.create(customer_id=customer_id, items=items, total_amount=total_amount)
        except Exception as e:
            return "Order creation failed"
        if not order:
            return "Order creation failed"
        return order.id

    def getOrderDetails(self, order_id):
        # Validate input
        if not order_id:
            return "Invalid input"

        # Query database for order details
        try:
            order = Order.objects.get(id=order_id)
        except Exception as e:
            return "Order not found"
        if not order:
            return "Unauthorized access"
        return {
            'customer_id': order.customer_id,
            'items': order.items,
            'total_amount': order.total_amount,
            'status': order.status
        }

    def updateOrderStatus(self, order_id, new_status):
        # Validate inputs
        if not order_id or not new_status:
            return "Invalid input"

        # Handle potential race conditions
        while True:
            try:
                with transaction.atomic():
                    order = Order.objects.select_for_update().get(id=order_id)
                    if order.status not in self.order_statuses:
                        return "Invalid status"
                    order.status = new_status
                    order.save()
                break
            except OperationalError as e:
                # Retry on concurrent modification errors
                if e.args[0] == 1062:
                    continue
                raise
        return "Order status updated"
