        bool removeDataPoint(const std::vector<double>& point);
    };

    // Root node of the octree
    std::unique_ptr<OctreeNode> root_;

    // Mutex and condition variable for synchronizing access to the octree
    std::mutex mutex_;
    std::condition_variable cv_;

    // Number of threads used for updating the octree
