function BatchProcessElementsBySelector(rootNode, selector, callback) {
    let elements = rootNode.querySelectorAll(selector);
    for (let i = 0; i < elements.length; ++i) {
        const element = elements[i];
        if (element.classList.contains('skip')) continue;
        callback(element);
    }
