using System;
using System.IO;
using System.Security.Cryptography;
using System.Xml;

namespace DecryptionApp
{
    class Program
    {
        // Environment variable for the path to the XML configuration file
        const string ConfigFilePathEnvVar = "ConfigFilePath";

        static void Main(string[] args)
        {
            // Load configuration settings from an external source (e.g., a remote server or local file)
            var configFilePath = Environment.GetEnvironmentVariable(ConfigFilePathEnvVar);
            if (configFilePath == null || !File.Exists(configFilePath))
            {
                throw new InvalidOperationException($"Configuration file not found at path: {configFilePath}");
            }
            var config = LoadConfiguration(configFilePath);

            // Decrypt the ciphertext using AES-CBC and the specified encryption key and initialization vector (IV)
            var ciphertext = GetCiphertextFromInput();
            byte[] decryptedPlaintext;
            using (var aes = new AesCbc(config.EncryptionKey, config.InitializationVector))
            {
                decryptedPlaintext = aes.Decrypt(ciphertext);
            }

            // Validate the decrypted plaintext against a known hash or signature to ensure data integrity
            var validationResult = ValidatePlaintext(decryptedPlaintext, config.KnownHashOrSignature);
            if (!validationResult)
            {
                throw new InvalidOperationException("Decrypted plaintext is invalid");
            }

            // Print the decrypted plaintext to the console
            Console.WriteLine($"Decrypted plaintext: {Encoding.ASCII.GetString(decryptedPlaintext)}");
        }

        private static Configuration LoadConfiguration(string configFilePath)
        {
            using (var reader = new XmlTextReader(configFilePath))
            {
                var serializer = new XmlSerializer(typeof(Configuration));
                return (Configuration)serializer.Deserialize(reader);
            }
        }

        private static byte[] GetCiphertextFromInput()
        {
            // Read the ciphertext from stdin or a file
            string input;
            if (!string.IsNullOrEmpty(args) && File.Exists(args))
            {
                input = File.ReadAllText(args);
            }
            else
            {
                input = Console.In.ReadToEnd();
            }

            // Decode the ciphertext from Base64 to bytes
            return Convert.FromBase64String(input);
        }

        private static bool ValidatePlaintext(byte[] plaintext, byte[] knownHashOrSignature)
        {
            using (var sha256 = new SHA256Managed())
            {
                var hash = sha256.ComputeHash(plaintext);
                return hash.SequenceEqual(knownHashOrSignature);
            }
        }
    }

    public class Configuration
    {
        [XmlAttribute("tileSize")]
        public int TileSize { get; set; }

        [XmlAttribute("worldWidth")]
        public int WorldWidth { get; set; }

        [XmlAttribute("worldHeight")]
        public int WorldHeight { get; set; }

        [XmlAttribute("encryptionKey")]
        public byte[] EncryptionKey { get; set; }

        [XmlAttribute("initializationVector")]
        public byte[] InitializationVector { get; set; }

        [XmlAttribute("knownHashOrSignature")]
        public byte[] KnownHashOrSignature { get; set; }
    }
}
