#include <random>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <vector>
#include <iostream>
#include <fstream>

// Forward declarations
namespace Random {
    class RandomGenerator;
}

namespace Logging {
    class Logger;
}

// Define the random number generator namespace and its classes
namespace Random {
    // A class to represent a single random number generator instance
    class RandomGenerator {
    public:
        // Constructor initializes the random number generator with a robust seeding mechanism
        explicit RandomGenerator(const std::string& configFile) {
            // Load the configuration file and parse its contents
            std::ifstream configStream(configFile);
            if (!configStream.is_open()) {
                throw std::runtime_error("Failed to open configuration file");
            }
            Json::Value root;
            configStream >> root;

            // Initialize the random number generator with the specified seed source
            std::string seedSource = root["seedSource"].asString();
            if (seedSource == "time") {
                seed_ = std::chrono::system_clock::now().time_since_epoch().count();
            } else if (seedSource == "systemEntropy") {
                std::random_device rd;
                seed_ = rd() * static_cast<uint64_t>(std::numeric_limits<int>::max()) + 1;
            } else if (seedSource == "userSeed") {
                seed_ = root["userSeed"].asUInt();
            } else {
                throw std::runtime_error("Invalid seed source");
            }

            // Set the random number generator's state to its initial value
            state_ = std::mt19937_64(seed_);
        }

        // Destructor releases any resources used by the generator
        ~RandomGenerator() {
            // Nothing to do, as the std::mt19937_64 object is automatically destroyed when it goes out of scope
        }

        // Generate random numbers according to the specified distribution
        int uniformInt(int min, int max) {
            return std::uniform_int_distribution<>(min, max)(state_);
        }

        double normalDouble() {
            return std::normal_distribution<>()(state_);
        }

        double exponentialDouble(double lambda) {
            return -std::log(1.0 - uniformDouble()) / lambda;
        }

        int poissonInt(double lambda) {
            return std::poisson_distribution<> (lambda)(state_);
        }

        int geometricInt(double p) {
            return std::geometric_distribution<>(p)(state_);
        }

    private:
        // The current state of the random number generator
        std::mt19937_64 state_;

        // The seed used to initialize the random number generator
        uint64_t seed_;
    };
}

// Define the logging namespace and its classes
namespace Logging {
    class Logger {
    public:
        // Constructor initializes the logger with a file output stream for logging events
        explicit Logger(const std::string& logFile) {
            // Create a file output stream for the specified log file
            logStream_ = new std::ofstream(logFile);
            if (!logStream_->is_open()) {
                throw std::runtime_error("Failed to open log file");
            }
        }

        ~Logger() {
            // Close the output stream when the logger goes out of scope
            logStream_->close();
        }

        // Log a random number generation event with the specified distribution type, parameters, and timestamp
        void logEvent(const std::string& distType, const std::vector<std::string>& params, double timestamp) {
            // Output the log event to the file output stream
            *logStream_ << "Random Number Generation Event: Dist Type=" << distType;
            for (const auto& param : params) {
                *logStream_ << ", Param=" << param;
            }
            *logStream_ << ", Timestamp=" << timestamp << std::endl;
        }

    private:
        // The file output stream used for logging events
        std::ofstream* logStream_;
    };
}

// Define a class to represent the random number generator with external logging support
class RandomNumberGeneratorWithLogging {
public:
    // Constructor initializes the random number generator and its logger
    explicit RandomNumberGeneratorWithLogging(const std::string& configFile, const std::string& logFile) :
        gen_(configFile),
        log_(logFile) {}

    ~RandomNumberGeneratorWithLogging() {
        // Nothing to do, as the std::mt19937_64 object and the Logger objects are automatically destroyed when they go out of scope
    }

    // Generate random numbers according to the specified distribution
    int uniformInt(int min, int max) {
        // Log the random number generation event
        log_.logEvent("uniform", std::vector<std::string>{"min=" + std::to_string(min), "max=" + std::to_string(max)}, gen_.state_.time());

        // Generate a uniform random integer within the specified range
        return gen_.uniformInt(min, max);
    }

    double normalDouble() {
        // Log the random number generation event
        log_.logEvent("normal", std::vector<std::string>{}, gen_.state_.time());

        // Generate a normal random double
        return gen_.normalDouble();
    }

    double exponentialDouble(double lambda) {
        // Log the random number generation event
        log_.logEvent("exponential", std::vector<std::string>{"lambda=" + std::to_string(lambda)}, gen_.state_.time());

        // Generate an exponential random double with the specified parameter
        return gen_.exponentialDouble(lambda);
    }

    int poissonInt(double lambda) {
        // Log the random number generation event
        log_.logEvent("poisson", std::vector<std::string>{"lambda=" + std::to_string(lambda)}, gen_.state_.time());

        // Generate a Poisson random integer with the specified parameter
        return gen_.poissonInt(lambda);
    }

    int geometricInt(double p) {
        // Log the random number generation event
        log_.logEvent("geometric", std::vector<std::string>{"p=" + std::to_string(p)}, gen_.state_.time());

        // Generate a geometric random integer with the specified parameter
        return gen_.geometricInt(p);
    }

private:
    // The random number generator and its logger
    RandomNumberGenerator::RandomNumberGenerator gen_;
    Logging::Logger log_;
};

int main() {
    const std::string configFile = "config.txt";
    const std::string logFile = "log.txt";

    // Create a random number generator with external logging support using the specified configuration file and log file
    RandomNumberGeneratorWithLogging gen(configFile, logFile);

    // Generate some uniform random integers within the specified range
    for (int i = 0; i < 10; i++) {
        int r = gen.uniformInt(1, 6);
        std::cout << "Uniform Random Integer: " << r << std::endl;
    }

    // Generate some normal random doubles
    for (int i = 0; i < 5; i++) {
        double r = gen.normalDouble();
        std::cout << "Normal Random Double: " << r << std::endl;
    }

    // Generate some exponential random doubles with the specified parameter
    for (int i = 0; i < 3; i++) {
        double r = gen.exponentialDouble(2.0);
        std::cout << "Exponential Random Double (lambda=2.0): " << r << std::endl;
    }

    // Generate some Poisson random integers with the specified parameter
    for (int i = 0; i < 3; i++) {
        int r = gen.poissonInt(3.0);
        std::cout << "Poisson Random Integer (lambda=3.0): " << r << std::endl;
    }

    // Generate some geometric random integers with the specified parameter
    for (int i = 0; i < 3; i++) {
