using System;
using System.Collections.Generic;
using System.Threading.Tasks;

namespace DynamicRandomValueGenerator
{
    public class RandomValueGenerator
    {
        private readonly string _externalDataSourceUrl;
        private readonly int? _seed;
        private readonly Dictionary<string, Tuple<int, int>> _cachedIntervals = new Dictionary<string, Tuple<int, int>>();

        public RandomValueGenerator(string externalDataSourceUrl, int? seed)
        {
            _externalDataSourceUrl = externalDataSourceUrl;
            _seed = seed;
        }

        private async Task<Tuple<int, int>> GetIntervalBoundariesAsync(string intervalName)
        {
            if (!_cachedIntervals.ContainsKey(intervalName))
            {
                var response = await HttpGetAsync(_externalDataSourceUrl + "/" + intervalName);
                _cachedIntervals[intervalName] = Tuple.Create(response["min"], response["max"]);
            }

            return _cachedIntervals[intervalName];
        }

        private async Task<int> CustomRangeAsync(string intervalName, bool isExclusive, bool seeded)
        {
            var boundaries = await GetIntervalBoundariesAsync(intervalName);
            if (seeded && _seed.HasValue)
            {
                Random random = new Random(_seed.Value);
                return random.Next((int)boundaries.Item1, (int)boundaries.Item2 + 1, isExclusive);
            }
            else
            {
                return ThreadSafeRandom.Next((int)boundaries.Item1, (int)boundaries.Item2 + 1, isExclusive);
            }
        }

        private async Task<float> CustomRangeAsync(string intervalName, bool isExclusive, bool seeded)
        {
            var boundaries = await GetIntervalBoundariesAsync(intervalName);
            if (seeded && _seed.HasValue)
            {
                Random random = new Random(_seed.Value);
                return random.NextFloat((float)boundaries.Item1, (float)boundaries.Item2 + 1, isExclusive);
            }
            else
            {
                return ThreadSafeRandom.NextFloat((float)boundaries.Item1, (float)boundaries.Item2 + 1, isExclusive);
            }
        }
    }
}
