function copyBytes(bufferList, byteCount) {
  const newBuffer = Buffer.allocUnsafe(byteCount);
  let copiedByteCount = 0;
  for (const buffer of bufferList) {
    if (!(buffer instanceof Buffer)) {
      throw new Error("Incorrect data type: expected Buffer");
    }
    const bufferSize = buffer.length;
    if (copiedByteCount + bufferSize > byteCount) {
      throw new Error("Requested byte count exceeds available data");
    }
    buffer.copy(newBuffer, copiedByteCount, 0, bufferSize);
    copiedByteCount += bufferSize;
  }
  return newBuffer;
}
```
