        self.session_registry = {} # registry of session factories

    def update_session_data(self, user_id: int, data: Dict[str, any]) -> None:
        if user_id not in self.sessions:
            return

        session = self.sessions[user_id]
        for key, value in data.items():
            setattr(session, key, value)

        self.sessions[user_id] = session

    def validate_user_session(self, user_id: int) -> bool:
        if user_id not in self.sessions:
            return False

        session = self.sessions[user_id]
        last_activity = session.last_activity
        ip_address = session.ip_address
        device_type = session.device_type

        if datetime.now() - last_activity > timedelta(minutes=30):
            return False

        if ip_address != request.remote_addr:
            return False

        if device_type != request.user_agent.platform:
            return False

        return True

    def session_to_json(self, session: Dict[str, any]) -> str:
        return json.dumps(session)

    def json_to_session(self, json_data: str) -> Dict[str, any]:
        return json.loads(json_data)

    def add_factory(self, factory):
        self.session_registry[factory.name] = factory

    def create_session(self, session_type: str, data: Dict[str, any]) -> any:
        if session_type not in self.session_registry:
            raise ValueError("Invalid session type")

        return self.session_registry[session_type].create(data)

    def clear_expired_sessions(self):
        for user_id, session in self.sessions.items():
            if datetime.now() - session.last_activity > timedelta(minutes=30):
                del self.sessions[user_id]

    def log_validation_failure(self, user_id: int):
        print(f"Session validation failed for user {user_id}")

class UserSessionFactory:
    def __init__(self, name):
        self.name = name

    def create(self, data: Dict[str, any]) -> any:
        return Session(data)
```
