using System;
using System.Data;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

namespace PasswordHasher
{
    public class Hasher
    {
        private readonly IHashAlgorithm _hashAlgorithm;
        private readonly ISaltGenerator _saltGenerator;

        public Hasher(IHashAlgorithm hashAlgorithm, ISaltGenerator saltGenerator)
        {
            _hashAlgorithm = hashAlgorithm;
            _saltGenerator = saltGenerator;
        }

        public string HashPassword(string password)
        {
            if (password == null)
                throw new ArgumentNullException(nameof(password));

            var salt = _saltGenerator.GenerateSalt();
            return GenerateHashedPassword(password, salt);
        }

        public bool VerifyPassword(string password, string hashedPassword)
        {
            if (password == null || hashedPassword == null)
                throw new ArgumentNullException(nameof(password), nameof(hashedPassword));

            return VerifyHashedPassword(password, hashedPassword);
        }

        public string GenerateSalt()
        {
            return _saltGenerator.GenerateSalt();
        }

        private string GenerateHashedPassword(string password, byte[] salt)
        {
            var hash = _hashAlgorithm.ComputeHash(password, salt);
            return Convert.ToBase64String(hash);
        }

        private bool VerifyHashedPassword(string password, string hashedPassword)
        {
            if (password == null || hashedPassword == null)
                throw new ArgumentNullException(nameof(password), nameof(hashedPassword));

            var salt = GetSaltFromHashedPassword(hashedPassword);
            var expectedHash = GenerateHashedPassword(password, salt);
            return expectedHash.Equals(hashedPassword);
        }

        private byte[] GetSaltFromHashedPassword(string hashedPassword)
        {
            var base64String = Convert.FromBase64String(hashedPassword);
            return base64String.Take(16).ToArray(); // Salt is the first 16 bytes of the hash
        }
    }
}
