#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <curl/curl.h>

// Define a structure to store the download information
struct DownloadInfo {
  char *url;
  char *output_file;
  long expected_size;
  int timeout;
};

// Define a function to handle the download of a file
void *download_file(void *arg) {
  struct DownloadInfo *info = (struct DownloadInfo *)arg;

  // Initialize curl
  CURL *curl = curl_easy_init();

  if (curl) {
    // Set the URL, output file, and timeout for the download
    curl_easy_setopt(curl, CURLOPT_URL, info->url);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, info->output_file);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, info->timeout);

    // Perform the download and get the response code
    CURLcode res = curl_easy_perform(curl);

    // Check for errors
    if (res != CURLE_OK) {
      fprintf(stderr, "Error: %s\n", curl_easy_strerror(res));
    } else {
      // Print the response code and URL
      printf("Response code: %d\n", res);
      printf("Downloaded file: %s\n", info->output_file);
    }

    // Clean up curl
    curl_easy_cleanup(curl);
  }

  return NULL;
}

// Define a function to manage the thread pool and download files concurrently
void download_files(struct DownloadInfo *info, int num_downloads) {
  // Initialize the thread pool
  pthread_t threads[num_downloads];

  // Loop through each URL and start a new thread for each download
  for (int i = 0; i < num_downloads; i++) {
    // Create a new thread for the download
    pthread_create(&threads[i], NULL, download_file, &info[i]);
  }

  // Loop through each thread and join them to wait for completion
  for (int i = 0; i < num_downloads; i++) {
    pthread_join(threads[i], NULL);
  }
}

// Define a function to parse the configuration file and create an array of DownloadInfo structures
struct DownloadInfo *parse_config(const char *file, int *num_downloads) {
  // Open the configuration file for reading
  FILE *fp = fopen(file, "r");

  if (!fp) {
    fprintf(stderr, "Error: could not open configuration file\n");
    return NULL;
  }

  // Read the number of downloads from the first line of the file
  char *line = NULL;
  size_t len = 0;
  ssize_t read;
  int n = 1;
  while ((read = getline(&line, &len, fp)) != -1) {
    if (n == 1) {
      *num_downloads = atoi(line);
    } else {
      // Create a new DownloadInfo structure for each URL in the file
      struct DownloadInfo *info = malloc(sizeof(struct DownloadInfo));
      info->url = strdup(line);
      char *output_file = strrchr(line, '/');
      if (output_file) {
        output_file++; // skip the slash
      } else {
        output_file = line;
      }
      info->output_file = strdup(output_file);
      info->expected_size = 0;
      info->timeout = 30;
      printf("Downloading file: %s\n", info->url);
    }
  }

  // Close the configuration file
  fclose(fp);

  return info;
}

int main(int argc, char *argv[]) {
  if (argc < 3) {
    printf("Usage: %s output_dir num_downloads [config_file]\n", argv[0]);
    return 1;
  }

  // Get the output directory and maximum number of concurrent downloads from the command line arguments
  const char *output_dir = argv[1];
  int max_downloads = atoi(argv[2]);

  // Create an array to store the DownloadInfo structures for each URL
  struct DownloadInfo *info;
  int num_downloads = 0;

  if (argc > 3) {
    // Parse the configuration file and create an array of DownloadInfo structures
    info = parse_config(argv[3], &num_downloads);
  } else {
    printf("No configuration file provided, using default settings\n");
    num_downloads = max_downloads;
    info = malloc(sizeof(struct DownloadInfo) * num_downloads);
  }

  // Loop through each URL and start a new thread for each download
  for (int i = 0; i < num_downloads; i++) {
    char output_file[1024];
    snprintf(output_file, sizeof(output_file), "%s/%d.tmp", output_dir, i);
    info[i].output_file = strdup(output_file);
  }

  // Download the files concurrently using a thread pool
  download_files(info, num_downloads);

  // Clean up the memory allocated for the DownloadInfo structures
  free(info);

  return 0;
}
