public class SecurityService
{
    private readonly string _externalToken;
    private readonly string _encryptionKey;
    private readonly string _initializationVector;

    public SecurityService(string externalToken, string encryptionKey, string initializationVector)
    {
        _externalToken = externalToken;
        _encryptionKey = encryptionKey;
        _initializationVector = initializationVector;
    }

    public async Task<byte[]> DecryptMessageAsync(byte[] ciphertext)
    {
        // Authenticate with the external token-based service
        if (!await AuthenticateWithExternalService(_externalToken))
        {
            throw new SecurityException("Failed to authenticate with the external service");
        }

        try
        {
            using (Aes aes = Aes.Create())
            {
                aes.KeySize = 256;
                aes.BlockSize = 128;
                aes.Mode = CipherMode.CBC;
                aes.Padding = PaddingMode.PKCS7;

                byte[] keyBytes = Convert.FromBase64String(_encryptionKey);
                byte[] ivBytes = Convert.FromBase64String(_initializationVector);

                aes.Key = keyBytes;
                aes.IV = ivBytes;

                ICryptoTransform decryptor = aes.CreateDecryptor();

                return await Task.Run(() => {
                    using (MemoryStream memoryStream = new MemoryStream())
                    {
                        using (CryptoStream cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Write))
                        {
                            cryptoStream.Write(ciphertext);
                            cryptoStream.FlushFinalBlock();

                            return memoryStream.ToArray();
                        }
                    }
                });
            }
        }
        catch (Exception e)
        {
            throw new SecurityException("Failed to decrypt message", e);
        }
    }

    public byte[] HashPassword(string password)
