// ScriptLoader.js
class ScriptLoader {
  constructor(config) {
    this.config = config;
    this.scripts = {};
  }

  async loadScript(scriptSrc, options) {
    const script = document.createElement('script');
    script.src = scriptSrc;
    if (options && options.async) {
      script.async = true;
    }
    return new Promise((resolve, reject) => {
      script.addEventListener('load', resolve);
      script.addEventListener('error', reject);
      document.head.appendChild(script);
    });
  }

  async loadScripts(scripts) {
    const promises = [];
    scripts.forEach((scriptSrc, priority) => {
      const options = this.config.getOptions(scriptSrc);
      if (priority === 'high') {
        promises.push(this.loadScript(scriptSrc, options));
      } else {
        promises.push(this.loadScript(scriptSrc, options));
      }
    });
    await Promise.all(promises);
  }

  async executeScripts(scripts) {
    scripts.forEach((scriptSrc) => {
      const script = this.scripts[scriptSrc];
      if (script && script.readyState === 'complete') {
        console.log('Executing script:', scriptSrc);
        script.execute();
      } else {
        console.warn(`Script ${scriptSrc} is not ready, skipping`);
      }
    });
  }

  async loadAndExecuteScripts(scripts) {
    await this.loadScripts(scripts);
    this.executeScripts(scripts);
  }

  setConfig(config) {
    this.config = config;
  }
}
```

