// ScriptLoaderConfig.js
class ScriptLoaderConfig {
  constructor() {
    this.priorities = {};
    this.options = {};
  }

  addPriority(scriptSrc, priority) {
    if (!this.priorities[scriptSrc]) {
      this.priorities[scriptSrc] = priority;
    } else if (this.priorities[scriptSrc] !== priority) {
      console.warn(`Script ${scriptSrc} has conflicting priorities`);
    }
  }

  getPriority(scriptSrc) {
    return this.priorities[scriptSrc];
  }

  addOption(scriptSrc, option) {
    if (!this.options[scriptSrc]) {
      this.options[scriptSrc] = [];
    }
    this.options[scriptSrc].push(option);
  }

  getOptions(scriptSrc) {
    return this.options[scriptSrc];
  }
}
