        FILTERS.put("blur", new BlurFilter());
        // Add more filter types as needed...
    }

    public static void main(String[] args) throws IOException {
        // Read the image file from disk
        File inputFile = new File(args[0]);
        BufferedImage inputImage = ImageIO.read(inputFile);

        // Resize the image to the target size using the specified interpolation method
        int targetWidth = Integer.parseInt(args[1]);
        int targetHeight = Integer.parseInt(args[2]);
        InterpolationMethod method = InterpolationMethod.valueOf(args[3]);
        BufferedImage outputImage = resizeImage(inputImage, targetWidth, targetHeight, method);

        // Apply the specified filter to the resized image
        String filterName = args[4];
        Filter filter = FILTERS.get(filterName);
        if (filter == null) {
            throw new IllegalArgumentException("Invalid filter name: " + filterName);
        }
        outputImage = filter.applyFilter(outputImage);

        // Write the processed image to disk
        ImageIO.write(outputImage, "PNG", inputFile);
    }

    public static BufferedImage resizeImage(BufferedImage image, int targetWidth, int targetHeight, InterpolationMethod method) {
        // Use the interpolation method to scale the image to the target size
        BufferedImageOp op = INTERPOLATION_METHODS.get(method);
        if (op == null) {
            throw new IllegalArgumentException("Invalid interpolation method: " + method);
        }
        return op.filter(image, null);
    }

    public static class GrayscaleFilter implements Filter {
        @Override
        public BufferedImage applyFilter(BufferedImage image) {
            // Apply the grayscale filter to the input image
            int width = image.getWidth();
            int height = image.getHeight();
            BufferedImage outputImage = new BufferedImage(width, height, BufferedImage.TYPE_BYTE_GRAY);
            for (int y = 0; y < height; y++) {
                for (int x = 0; x < width; x++) {
                    int rgb = image.getRGB(x, y);
                    int red = (rgb >> 16) & 0xFF;
                    int green = (rgb >> 8) & 0xFF;
                    int blue = rgb & 0xFF;
                    int gray = (red + green + blue) / 3;
                    outputImage.setRGB(x, y, gray);
                }
            }
            return outputImage;
        }
    }

    public static class BlurFilter implements Filter {
        @Override
        public BufferedImage applyFilter(BufferedImage image) {
            // Apply the blur filter to the input image
            int width = image.getWidth();
            int height = image.getHeight();
            BufferedImage outputImage = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
            for (int y = 0; y < height; y++) {
                for (int x = 0; x < width; x++) {
                    int rgb = image.getRGB(x, y);
                    int red = (rgb >> 16) & 0xFF;
                    int green = (rgb >> 8) & 0xFF;
                    int blue = rgb & 0xFF;
                    int avg = (red + green + blue) / 3;
                    outputImage.setRGB(x, y, avg);
                }
            }
            return outputImage;
        }
    }
}
```
Note that this code uses the `BufferedImage` class from the Java AWT library to perform image processing operations. You will need to add the appropriate dependencies and include the necessary imports in your project for this code to work correctly.

Here is an example of how you can implement a JavaScript function that dynamically renders a footer of a web page using an array of script objects:
```
function renderFooter(scripts) {
  // Create an empty string to hold the rendered HTML
  let html = '';

  // Loop through each script object in the array
  scripts.forEach((script) => {
    // Check if the script has all the necessary properties
    if (!script.code || !script.type) {
      return;
    }

    // Create a <script> tag with the unique key and innerHTML set to the script's code
    const scriptTag = document.createElement('script');
    scriptTag.setAttribute('key', script.key);
    scriptTag.innerHTML = script.code;

    // Append the <script> tag to the HTML string
    html += scriptTag.outerHTML;
  });

  return html;
}
```
Here is an example of how you can implement a C# method that parameterizes a SQL command with a list of values, supports connection pooling, and returns an IDataReader for the result set:
```
using System.Data;
using System.Data.SqlClient;
using System.Threading.Tasks;

public static async Task<IDataReader> ExecuteQuery(List<object> parameters, string connectionString, SqlConnection connection = null)
{
    // Create a new SQL command object
    var cmd = new SqlCommand();

    // Set the command text and connection to the provided values
    cmd.CommandText = "SELECT * FROM MyTable";
    cmd.Connection = connection;

    // Set the parameters on the command object
    foreach (var parameter in parameters)
    {
        var param = new SqlParameter();
        param.ParameterName = "@param1";
        param.Value = parameter;
        cmd.Parameters.Add(param);
    }

    // Open the connection if it is not already open
    if (cmd.Connection.State != ConnectionState.Open)
    {
        await cmd.Connection.OpenAsync();
    }

    // Execute the command and return an IDataReader for the result set
    using (var reader = await cmd.ExecuteReaderAsync())
    {
        return reader;
    }
}
```
In this example, we use a `List<object>` to represent the parameters that will be passed to the SQL command. The method takes in three parameters: `parameters`, which is the list of parameters for the SQL query, `connectionString`, which is the connection string used to connect to the database, and `connection`, which is an optional parameter for a pre-established connection object.

To execute the SQL query, we create a new `SqlCommand` object and set its `CommandText` property to the SQL query string. We then set the `Connection` property of the command object to the provided connection string.

Next, we loop through each parameter in the `parameters` list and add it as a new `SqlParameter` object to the `Parameters` collection of the command object. We also set the `ParameterName` property of each parameter object to the corresponding `@param1`, `@param2`, etc. value.

Finally, we open the connection if it is not already open and execute the SQL query using the `ExecuteReaderAsync()` method. The method returns an `IDataReader` object that we use to read the result set from the database.

```javascript
function renderFooter(scripts) {
  // 1. Handle missing essential properties
  scripts = scripts.map((script) => {
    if (!script.code || !script.type || !script.src) return null;
    return script;
  });

  // 2. Dynamically load scripts from an external API endpoint
  const fetchScripts = async () => {
    try {
      const response = await fetch("/api/scripts");
      if (response.ok) {
        const scriptsResponse = await response.json();
        return scriptsResponse.scripts;
      } else {
        throw new Error(`Failed to fetch scripts: ${response.statusText}`);
      }
    } catch (error) {
      console.error(error);
      return [];
    }
  };

  // 3. Caching fetched scripts
  const cache = {};
  const getScriptFromCache = (key) => cache[key];
  const setScriptInCache = (key, value) => (cache[key] = value);
  const fetchAndCacheScripts = async () => {
    try {
      const scripts = await fetchScripts();
      scripts.forEach((script) => setScriptInCache(script.src, script));
    } catch (error) {
      console.error(error);
    }
  };

  // 4. Ensure asynchronous loading of scripts and correct order of operations
  const loadScripts = async () => {
    try {
      if (!cache.hasOwnProperty("scripts")) await fetchAndCacheScripts();
      return cache.scripts;
    } catch (error) {
      console.error(error);
      return [];
    }
  };

  // 5. Manage and clean up old or unused script elements to optimize DOM size and improve performance
  const getScriptElement = (src) => document.querySelector(`script[src="${src}"]`);
  const removeScriptElement = (element) => element.remove();
  const manageScriptElements = async () => {
    try {
      const scripts = await loadScripts();
      scripts.forEach((script) => {
        const scriptElement = getScriptElement(script.src);
        if (!scriptElement) return;
        removeScriptElement(scriptElement);
      });
    } catch (error) {
      console.error(error);
    }
  };

  // 6. Error handling for network issues, timeouts, and unexpected responses from the external API
  const handleError = (error) => {
    console.error(error);
    return [];
  };

  // 7. Loading spinner or progress indicator for enhance user experience while scripts are being fetched and rendered
  const showSpinner = () => document.body.innerHTML += `<div class="spinner"></div>`;
  const hideSpinner = () => document.querySelector(".spinner").remove();

  // 8. Organizing the code into modular functions, including one for fetching scripts, another for managing cache, and a third for rendering the scripts
  const fetchAndRenderFooter = async () => {
    try {
      showSpinner();
      await manageScriptElements();
      await loadScripts();
      hideSpinner();
      return renderFooter(scripts);
    } catch (error) {
      console.error(error);
      return handleError(error);
    }
  };

  // 9. Implementing logging mechanisms to log errors encountered during script fetching or rendering for debugging purposes
  const logError = (error) => console.error(error);

  // 10. Optimizing the function to handle large arrays of script objects efficiently, considering potential delays in script execution and ensuring the footer updates smoothly as new scripts are added
  const optimizeScriptExecution = () => {
    let isExecuting = false;
    return (script) => {
      if (isExecuting) {
        setTimeout(() => optimizeScriptExecution()(script), 0);
      } else {
        isExecuting = true;
        const scriptElement = document.createElement("script");
        scriptElement.innerHTML = script.code;
        document.body.appendChild(scriptElement);
        setTimeout(() => {
          isExecuting = false;
          scriptElement.remove();
        }, 0);
      }
    };
  };

  return fetchAndRenderFooter().then((html) => html).catch(logError);
}
```
