```c#
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

public class FileMetadataProcessor
{
    private string _directoryPath;
    private int _minSizeThreshold;
    private int _maxSizeThreshold;

    public FileMetadataProcessor(string directoryPath, int minSizeThreshold = 0, int maxSizeThreshold = int.MaxValue)
    {
        _directoryPath = directoryPath;
        _minSizeThreshold = minSizeThreshold;
        _maxSizeThreshold = maxSizeThreshold;
    }

    public IEnumerable<FileMetadata> GetFilesInRange(bool recursive = false, int batchSize = 100)
    {
        var files = new List<FileInfo>();

        if (recursive)
        {
            files.AddRange(Directory.EnumerateFiles(_directoryPath, "*", SearchOption.AllDirectories));
        }
        else
        {
            files.AddRange(Directory.GetFiles(_directoryPath));
        }

        return files.Where(f => f.Length >= _minSizeThreshold && f.Length <= _maxSizeThreshold)
                    .Select(f => new FileMetadata(f.FullName, f.Length, f.CreationTime, f.LastWriteTime));
    }

    public IEnumerable<FileMetadata> GetFilesInRange(int minSizeThreshold = 0, int maxSizeThreshold = int.MaxValue)
    {
        return GetFilesInRange(false, batchSize: 100).Where(f => f.Length >= _minSizeThreshold && f.Length <= _maxSizeThreshold);
    }

    public void ProcessMetadata(Action<FileMetadata> callback)
    {
        var files = GetFilesInRange();
        foreach (var file in files)
        {
            callback(file);
        }
    }

    public override string ToString()
    {
        return $"Size Range: [{_minSizeThreshold}, {_maxSizeThreshold}] KB";
    }

    private void ValidateFileSizeRange()
    {
        if (_minSizeThreshold > _maxSizeThreshold)
        {
            throw new ArgumentException("Invalid file size range. Minimum threshold must be less than or equal to maximum threshold.");
        }
    }

    public class FileMetadata
    {
        public string Path { get; set; }
        public long Size { get; set; }
        public DateTime CreationTime { get; set; }
        public DateTime LastWriteTime { get; set; }

        public FileMetadata(string path, long size, DateTime creationTime, DateTime lastWriteTime)
        {
            Path = path;
            Size = size;
            CreationTime = creationTime;
            LastWriteTime = lastWriteTime;
        }
    }
}
```
This code provides a `FileMetadataProcessor` class that can read metadata from a directory of files and process this information into a structured format for analysis. The class includes methods for generating a list of file paths within a specified directory range (both inclusively and exclusively), non-recursive traversal of the file paths to retrieve metadata in a structured way, using a provided callback function to filter and process specific metadata fields, returning an IEnumerable of processed metadata objects for lazy evaluation.

The `FileMetadataProcessor` class also includes private fields for the directory path and minimum and maximum file size thresholds, as well as methods for returning a list of files based on the specified size range, ensuring efficient resource management, providing an option to process a specified number of files at once, and overridding the `ToString` method to display the range of file sizes in the format "Size Range: [min, max] KB". Additionally, the class includes a method to validate the input file size range, integrate with an external logging system to record metadata retrieval activities and errors, handle potential exceptions and errors such as invalid directory paths, inaccessible files, and incorrect metadata retrieval, and optimize performance for large directories by implementing batch processing and parallelism where appropriate.

