    public static class CryptoSQLUtilities
    {
        private const int DEFAULT_TIMEOUT = 30000; // 30 seconds
        private const int MAX_RETRIES = 5;

        public static IDataReader ExecuteSqlQuery(List<string> values, string sqlCommandTemplate, DESAlgorithm algorithm)
        {
            try
            {
                // Validate input values to prevent SQL injection risks
                foreach (var value in values)
                {
                    if (!IsValidInputValue(value))
                    {
                        throw new ArgumentException("Invalid input value");
                    }
                }

                // Create a parameterized SQL command based on the given template and values
                var sqlCommand = BuildParameterizedSqlCommand(values, sqlCommandTemplate);

                // Execute the SQL query using a cryptographic function that supports multiple modes of operation
                switch (algorithm)
                {
                    case DESAlgorithm.ECB:
                        return ExecuteCryptoQuery(sqlCommand, new ECBCipher());
                    case DESAlgorithm.EDE:
                        return ExecuteCryptoQuery(sqlCommand, new EDECipher());
                    case DESAlgorithm.EDE3:
                        return ExecuteCryptoQuery(sqlCommand, new EDE3Cipher());
                    case DESAlgorithm.CFB:
                        return ExecuteCryptoQuery(sqlCommand, new CFBCipher());
                    default:
                        throw new NotSupportedException("Unsupported cryptographic algorithm");
                }
            }
            catch (Exception ex)
            {
                // Log errors for future analysis
                Console.WriteLine($"Error executing SQL query: {ex}");

                // Retry logic for transient errors
                int retryCount = 0;
                while (retryCount < MAX_RETRIES)
                {
                    try
                    {
                        return ExecuteSqlQuery(values, sqlCommandTemplate, algorithm);
                    }
                    catch (Exception ex) when (ex is TransientError || ex is IOException)
                    {
                        Console.WriteLine($"Transient error executing SQL query: {ex}");
                        retryCount++;
                    }
                }

                // Throw exception if all retries fail
                throw new IOException("Failed to execute SQL query after multiple attempts", ex);
            }
