<?php

function authenticateUserUsingOAuth($oauthProvider) {
    // Check if user is already authenticated
    $session = new Session();
    $accessToken = $session->get('access_token');

    // If access token is not set, redirect to OAuth provider's login page
    if (!$accessToken) {
        header("Location: {$oauthProvider['loginUrl']}");
        exit;
    }

    // Handle rate limiting and caching
    $rateLimit = 10; // Maximum number of requests per minute
    $cacheDuration = 300; // Duration to cache user information in seconds

    // Retrieve user information from OAuth provider using access token
    $userInfo = retrieveUserInfo($accessToken);

    // If user information is not available, handle error and redirect to login page
    if (!$userInfo) {
        header("Location: {$oauthProvider['loginUrl']}");
        exit;
    }

    // Update session variable with user information
    $session->put('user_id', $userInfo['id']);
    $session->put('name', $userInfo['name']);
    $session->put('email', $userInfo['email']);

    // Handle error and redirect to login page if user information is not available
    if (!$userInfo) {
        header("Location: {$oauthProvider['loginUrl']}");
        exit;
    }

    // Return user information
    return $userInfo;
}

// Retrieve user information from OAuth provider using access token
function retrieveUserInfo($accessToken) {
    $userInfo = null;

    // Handle different OAuth providers with varying response formats and scopes
    if ($oauthProvider === 'Google') {
        $userInfo = getGoogleUserInfo($accessToken);
    } elseif ($oauthProvider === 'Facebook') {
        $userInfo = getFacebookUserInfo($accessToken);
    } elseif ($oauthProvider === 'GitHub') {
        $userInfo = getGithubUserInfo($accessToken);
    }

    // Handle error and return null if user information is not available
    if (!$userInfo) {
        header("Location: {$oauthProvider['loginUrl']}");
        exit;
    }

    return $userInfo;
}

// Get Google user information using access token
function getGoogleUserInfo($accessToken) {
    // Retrieve user information from Google API using access token
    $userInfo = json_decode(file_get_contents("https://www.googleapis.com/oauth2/v3/userinfo?access_token={$accessToken}"), true);

    return $userInfo;
}

// Get Facebook user information using access token
function getFacebookUserInfo($accessToken) {
    // Retrieve user information from Facebook API using access token
    $userInfo = json_decode(file_get_contents("https://graph.facebook.com/me?fields=id,name,email&access_token={$accessToken}"), true);

    return $userInfo;
}

// Get GitHub user information using access token
function getGithubUserInfo($accessToken) {
    // Retrieve user information from GitHub API using access token
    $userInfo = json_decode(file_get_contents("https://api.github.com/user?access_token={$accessToken}"), true);

    return $userInfo;
}

// Handle error and redirect to login page if user information is not available
function handleError($error) {
    header("Location: {$oauthProvider['loginUrl']}");
    exit;
}
