        # Cache updated profile picture for faster retrieval
        cache[user.username] = user.profile_picture

        # Store updated profile picture in external cloud storage service
        try:
            requests.post("https://api.cloudstorage.com/upload", data={"file": file})
        except Exception as e:
            print(f"Failed to store profile picture in external cloud storage: {e}")

        return {"message": "Profile picture updated successfully"}
    else:
        return {"message": "No file provided"}, 400

@app.route("/get-profile-picture", methods=["GET"])
@login_required
def get_profile_picture():
    user = current_user
    if user is None:
        raise ValueError("Invalid username")

    # Check cache for updated profile picture
    if user.username in cache:
        return send_file(cache[user.username], mimetype="image/jpeg")

    # Retrieve profile picture from external cloud storage service
    try:
        response = requests.get("https://api.cloudstorage.com/download", params={"file": user.profile_picture})
        if response.status_code == 200:
            return send_file(response.content, mimetype="image/jpeg")
    except Exception as e:
        print(f"Failed to retrieve profile picture from external cloud storage: {e}")

    # Return default profile picture if no updated picture found
    return send_file("default-profile-picture.jpg", mimetype="image/jpeg")

@app.route("/change-password", methods=["POST"])
@login_required
def change_password():
    new_password = request.form["new_password"]
    old_password = request.form["old_password"]
    if current_user.check_password(old_password):
        current_user.set_password(new_password)
        user_dao.update(current_user)
        return {"message": "Password updated successfully"}
    else:
        return {"message": "Invalid old password"}, 403

@app.route("/manage-groups", methods=["POST"])
@login_required
def manage_groups():
    action = request.form["action"]
    group_name = request.form["group_name"]
    user = current_user
    if action == "add":
        # Add user to group
        user_dao.add_to_group(user, group_name)
        return {"message": "User added to group successfully"}
    elif action == "remove":
        # Remove user from group
        user_dao.remove_from_group(user, group_name)
        return {"message": "User removed from group successfully"}
    else:
        return {"message": "Invalid action"}, 400

@app.route("/manage-roles", methods=["POST"])
@login_required
def manage_roles():
    action = request.form["action"]
    role_name = request.form["role_name"]
    user = current_user
    if action == "add":
        # Add user to role
        user_dao.add_to_role(user, role_name)
