import os
import threading
import time
from pathlib import Path

class DirectoryManager:
    def __init__(self, root_dir):
        self.root_dir = root_dir
        self.lock = threading.Lock()
        self.directory_map = {}
        self.temporary_directory_map = {}

    def create_directory(self, directory_name):
        with self.lock:
            if directory_name in self.directory_map:
                return self.directory_map[directory_name]
            else:
                try:
                    os.makedirs(os.path.join(self.root_dir, directory_name))
                    self.directory_map[directory_name] = directory_name
                    return directory_name
                except OSError as e:
                    if e.errno == errno.EEXIST:
                        return self.create_directory(directory_name)
                    else:
                        raise

    def delete_directory(self, directory_name):
        with self.lock:
            try:
                os.rmdir(os.path.join(self.root_dir, directory_name))
                del self.directory_map[directory_name]
            except OSError as e:
                if e.errno == errno.ENOENT:
                    pass
                else:
                    raise

    def get_directory(self, directory_name):
        with self.lock:
            return self.directory_map[directory_name]

    def create_temporary_directory(self, suffix="", prefix="tmp"):
        with self.lock:
            directory_name = f"{prefix}{os.getpid()}{suffix}"
            try:
                os.mkdir(os.path.join(self.root_dir, directory_name))
                self.temporary_directory_map[directory_name] = directory_name
                return directory_name
            except OSError as e:
                if e.errno == errno.EEXIST:
                    return self.create_temporary_directory(suffix, prefix)
                else:
                    raise

    def delete_temporary_directory(self, directory_name):
        with self.lock:
            try:
                os.rmdir(os.path.join(self.root_dir, directory_name))
                del self.temporary_directory_map[directory_name]
            except OSError as e:
                if e.errno == errno.ENOENT:
                    pass
                else:
                    raise

    def get_temporary_directory(self, directory_name):
        with self.lock:
            return self.temporary_directory_map[directory_name]

class DirectoryManagerTest(unittest.TestCase):
    def setUp(self):
        self.root_dir = "/tmp"
        self.manager = DirectoryManager(self.root_dir)

    def test_create_directory(self):
        directory_name = "test_directory"
        self.assertIsNone(self.manager.get_directory(directory_name))
        self.manager.create_directory(directory_name)
        self.assertEqual(self.manager.get_directory(directory_name), directory_name)
        self.manager.delete_directory(directory_name)
        self.assertIsNone(self.manager.get_directory(directory_name))

    def test_create_temporary_directory(self):
        suffix = "test_suffix"
        prefix = "tmp"
        directory_name = f"{prefix}{os.getpid()}{suffix}"
        self.assertIsNone(self.manager.get_temporary_directory(directory_name))
        self.manager.create_temporary_directory(suffix, prefix)
        self.assertEqual(self.manager.get_temporary_directory(directory_name), directory_name)
        self.manager.delete_temporary_directory(directory_name)
        self.assertIsNone(self.manager.get_temporary_directory(directory_name))

    def test_create_concurrently(self):
        directory_name = "test_directory"
        threads = []
        for i in range(10):
            thread = threading.Thread(target=self.manager.create_directory, args=(directory_name,))
            threads.append(thread)
            thread.start()
        for thread in threads:
            thread.join()
        self.assertEqual(self.manager.get_directory(directory_name), directory_name)
        self.manager.delete_directory(directory_name)
        self.assertIsNone(self.manager.get_directory(directory_name))

    def test_create_concurrently_temporary(self):
        suffix = "test_suffix"
        prefix = "tmp"
        directory_name = f"{prefix}{os.getpid()}{suffix}"
        threads = []
        for i in range(10):
            thread = threading.Thread(target=self.manager.create_temporary_directory, args=(suffix, prefix))
            threads.append(thread)
            thread.start()
        for thread in threads:
            thread.join()
        self.assertEqual(self.manager.get_temporary_directory(directory_name), directory_name)
        self.manager.delete_temporary_directory(directory_name)
        self.assertIsNone(self.manager.get_temporary_directory(directory_name))

    def test_retry(self):
        directory_name = "test_directory"
        self.assertIsNone(self.manager.get_directory(directory_name))
        with patch("os.makedirs", side_effect=Exception()) as makedirs:
            self.manager.create_directory(directory_name)
            self.assertEqual(makedirs.call_count, 10)
        self.manager.delete_directory(directory_name)
        self.assertIsNone(self.manager.get_directory(directory_name))

    def test_retry_temporary(self):
        suffix = "test_suffix"
        prefix = "tmp"
        directory_name = f"{prefix}{os.getpid()}{suffix}"
        self.assertIsNone(self.manager.get_temporary_directory(directory_name))
        with patch("os.mkdir", side_effect=Exception()) as mkdir:
            self.manager.create_temporary_directory(suffix, prefix)
            self.assertEqual(mkdir.call_count, 10)
        self.manager.delete_temporary_directory(directory_name)
        self.assertIsNone(self.manager.get_temporary_directory(directory_name))
