const path = require('path');
const fs = require('fs');
const vm = require('vm');
const crypto = require('crypto');
const Module = require('module');

class DynamicModuleLoader {
  constructor(options) {
    this.options = options || {};
    this.modules = new Map();
    this.pendingModules = new Set();
    this.dependents = new Map();
    this.circularDependencies = new Set();
    this.errorLog = [];
  }

  loadModule(filePath) {
    const moduleId = path.basename(filePath);
    if (this.modules.has(moduleId)) {
      return this.modules.get(moduleId);
    }

    const module = new Module(moduleId, this.options.parentModule);
    module.filename = filePath;
    module.paths = Module._nodeModulePaths(path.dirname(filePath));
    module.require = createRequireFromPath(filePath);

    try {
      const sourceCode = fs.readFileSync(filePath, 'utf8');
      vm.runInContext(sourceCode, module.context, {
        filename: filePath,
      });
    } catch (error) {
      this.handleError(error);
    }

    this.modules.set(moduleId, module);
    return module;
  }

  executeModule(moduleId, options = {}) {
    const module = this.getModule(moduleId);
    if (!module) {
      throw new Error(`Module ${moduleId} not found`);
    }

    const context = Object.assign({}, global, options.context || {});
    return module.executeInContext(context);
  }

  getModule(moduleId) {
    return this.modules.get(moduleId);
  }

  getPendingModules() {
    return Array.from(this.pendingModules).map((id) => this.modules.get(id));
  }

  hasCircularDependencies() {
    return this.circularDependencies.size > 0;
  }

  getCircularDependencies() {
    return Array.from(this.circularDependencies);
  }

  handleError(error) {
    const errorMessage = `${error.stack || error}`;
    this.errorLog.push(errorMessage);
    console.log(`[${crypto.randomBytes(16).toString('hex')}] ${errorMessage}`);
  }

  resolveDependencies(moduleId) {
    const module = this.getModule(moduleId);
    if (!module) {
      return [];
    }

    const dependencies = [...module.dependencies];
    for (const dependency of dependencies) {
      if (!this.modules.has(dependency)) {
        continue;
      }

      this.resolveDependencies(dependency).forEach((depModuleId) => {
        const depModule = this.getModule(depModuleId);
        if (depModule && !this.dependents.has(depModuleId)) {
          this.dependents.set(depModuleId, new Set([moduleId]));
        } else if (depModule) {
          const dependents = this.dependents.get(depModuleId);
          dependents.add(moduleId);
        }
      });
    }

    return dependencies;
  }

  loadDependencies(moduleId, options = {}) {
    const module = this.getModule(moduleId);
    if (!module) {
      throw new Error(`Module ${moduleId} not found`);
    }

    const context = Object.assign({}, global, options.context || {});
    for (const dependency of this.resolveDependencies(moduleId)) {
      this.loadModule(dependency, context);
    }
  }

  executePendingModules() {
    while (this.pendingModules.size > 0) {
      const module = Array.from(this.pendingModules)[0];
      this.pendingModules.delete(module);
      this.executeModule(module, { context: { require: createRequireFromPath(path.dirname(module)) } });
    }
  }
}

function createRequireFromPath(from) {
  return (id) => {
    const moduleId = path.resolve(from, id);
    if (!fs.existsSync(moduleId)) {
      throw new Error(`Cannot find module '${id}'`);
    }
    return DynamicModuleLoader.getModule(moduleId).exports;
  };
}

module.exports = DynamicModuleLoader;

