using System;
using System.IO;
using System.Xml;
using System.Xml.XPath;
using System.Xml.Schema;
using System.Collections.Generic;
using System.Diagnostics;

namespace XMLParser
{
    public class XMLParser
    {
        private readonly XmlDocument _document;
        private readonly XPathNavigator _navigator;
        private readonly XmlSchemaSet _schema;
        private readonly Dictionary<string, XmlNode> _cache = new Dictionary<string, XmlNode>();

        public XMLParser(string filepath)
        {
            _document = new XmlDocument();
            _document.Load(filepath);
            _navigator = _document.CreateNavigator();
            _schema = new XmlSchemaSet();
            _schema.Add("http://www.w3.org/2001/XMLSchema", "file://your_xsd_file_path.xsd");
        }

        public void ParseAndValidate(string xsdPath)
        {
            _schema.Compile();
            _document.Schemas = _schema;

            var validator = new XmlDocumentValidator(_document);
            var result = validator.Validate();

            if (!result.IsValid)
            {
                throw new Exception("XML document is not valid according to the provided XSD schema.");
            }
        }

        public XmlNode GetElement(string xpathQuery)
        {
            var navigator = _navigator.SelectSingleNode(xpathQuery);
            if (navigator == null)
            {
                throw new Exception($"No element found that matches the XPath query '{xpathQuery}'.");
            }

            return navigator.Current;
        }

        public void CacheElement(string xpathQuery)
        {
            var node = GetElement(xpathQuery);
            _cache[xpathQuery] = node;
        }

        public XmlNode GetCachedElement(string xpathQuery)
        {
            if (_cache.TryGetValue(xpathQuery, out XmlNode node))
            {
                return node;
            }

            throw new Exception($"The cache does not contain an element that matches the XPath query '{xpathQuery}'.");
        }

        public void InvalidateCache()
        {
            _cache.Clear();
        }

        public void ValidateUserInput(string xpathQuery)
        {
            try
            {
                var navigator = _navigator.SelectSingleNode(xpathQuery);
                if (navigator == null)
                {
                    throw new Exception($"No element found that matches the XPath query '{xpathQuery}'.");
                }
            }
            catch (Exception ex)
            {
                throw new ArgumentException("The provided XPath query is not valid.", nameof(xpathQuery));
            }
        }

        public void LogOperation(string operation, TimeSpan executionTime, bool validationSuccessful, Exception exception = null)
        {
            var logMessage = $"{operation} executed in {executionTime.TotalMilliseconds:0.00} ms";
            if (exception != null)
            {
                logMessage += $", with error message '{exception.Message}'.";
            }
            else if (!validationSuccessful)
            {
                logMessage += ", but the XML document failed to validate against the XSD schema.";
            }

            Console.WriteLine(logMessage);
        }
    }
}
