using System;
using System.Threading;
using UnityEngine;

public class AdvancedRandomGenerator
{
    // Enum for specifying the range type (inclusive, exclusive, or half-open)
    public enum RangeType { Closed, Open, HalfOpen }

    // Class to represent different types of ranges (e.g., [min, max], (min, max], [min, max))
    private class CustomInterval
    {
        public int Min { get; set; }
        public int Max { get; set; }
        public RangeType Type { get; set; }

        public CustomInterval(int min, int max, RangeType type)
        {
            this.Min = min;
            this.Max = max;
            this.Type = type;
        }
    }

    // Manager class to handle the distribution and synchronization of seeds across different instances of AdvancedRandomGenerator
    private class SeedManager
    {
        private static readonly object _lockObject = new object();
        private static int[] _seeds = new int[10];

        public static void GenerateSeed()
        {
            lock (_lockObject)
            {
                var seed = UnityEngine.Random.Range(1, 1000);
                for (var i = 0; i < _seeds.Length; i++)
                {
                    if (_seeds[i] == seed)
                    {
                        continue;
                    }
                    else
                    {
                        _seeds[i] = seed;
                        return;
                    }
                }
            }
        }

        public static int GetSeed()
        {
            lock (_lockObject)
            {
                return _seeds[_seeds.Length - 1];
            }
        }
    }

    private readonly Random _random;

    // CustomRange method that generates a random value based on the specified range type (inclusive, exclusive, or half-open) and supports various types of ranges, including open intervals, closed intervals, and half-open intervals.
    public int CustomRange(int min, int max, RangeType type = RangeType.Closed)
    {
        // Validate input parameters for the range
        if (min > max || min < 0 || max < 1)
        {
            throw new ArgumentException("Invalid range inputs");
        }

        // Implement a CustomInterval class to represent different types of ranges
        var interval = new CustomInterval(min, max, type);

        // Generate the random value based on the specified range type and return it
        switch (interval.Type)
        {
            case RangeType.Closed:
                return _random.Next(interval.Min, interval.Max + 1);
            case RangeType.Open:
                return _random.Next(interval.Min, interval.Max);
            case RangeType.HalfOpen:
                return _random.Next(interval.Min, interval.Max);
        }
    }

    // SeededRandom generation that allows setting a seed for reproducibility using UnityEngine.Random.Seed
    public int SeededCustomRange(int min, int max, RangeType type = RangeType.Closed, int seed = 0)
    {
        if (seed == 0)
        {
            // Generate a new seed if one is not provided
            seed = UnityEngine.Random.Range(1, 1000);
        }

        // Validate input parameters for the range
        if (min > max || min < 0 || max < 1)
        {
            throw new ArgumentException("Invalid range inputs");
        }

        // Implement a CustomInterval class to represent different types of ranges
        var interval = new CustomInterval(min, max, type);

        // Set the seed for reproducibility using UnityEngine.Random.Seed
        _random = new Random(seed);

        // Generate the random value based on the specified range type and return it
        switch (interval.Type)
        {
            case RangeType.Closed:
                return _random.Next(interval.Min, interval.Max + 1);
            case RangeType.Open:
                return _random.Next(interval.Min, interval.Max);
            case RangeType.HalfOpen:
                return _random.Next(interval.Min, interval.Max);
        }
    }

    // Integration with external systems for customizing the random number generation logic
    private static SeedCallback _seedCallback;
    public delegate void SeedCallback(int seed);

    // Provide a mechanism for external systems to register their own SeedCallback functions
    public static void RegisterSeedCallback(SeedCallback callback)
    {
        _seedCallback = callback;
    }

    // Implement caching mechanisms to store frequently used range configurations and avoid redundant calculations
    private readonly Dictionary<CustomInterval, int> _cachedValues = new Dictionary<CustomInterval, int>();

    // Utilize precomputed tables or other data structures to speed up the random value generation process
    private readonly int[] _precomputedValues = new int[100];
}
