import json
from datetime import datetime, timedelta
from flask import Flask, request, make_response, session
from flask_session import Session
from flask_sqlalchemy import SQLAlchemy
from sqlalchemy import Column, Integer, String, DateTime
from sqlalchemy.orm import relationship
from werkzeug.security import generate_password_hash, check_password_hash

app = Flask(__name__)

# Configure session management
app.config["SESSION_TYPE"] = "sqlalchemy"
Session(app)

# Define the database model for sessions
class SessionModel(db.Model):
    __tablename__ = "sessions"

    id = Column(Integer, primary_key=True)
    user_id = Column(String, nullable=False)
    expiration = Column(DateTime, default=datetime.utcnow() + timedelta(days=365))
    token = Column(String, unique=True)
    version = Column(Integer)

# Define the session creation endpoint
@app.route("/sessions", methods=["POST"])
def create_session():
    # Validate the request body
    if not request.json or "user_id" not in request.json:
        return make_response("Invalid request body", 400)

    # Generate a unique token for the session
    token = generate_password_hash(request.json["user_id"])

    # Create a new session in the database
    session = SessionModel(user_id=request.json["user_id"], token=token, version=1)
    db.session.add(session)
    db.session.commit()

    # Return the created session
    return jsonify({"token": token})

# Define the session update endpoint
@app.route("/sessions", methods=["PUT"])
def update_session():
    # Validate the request body
    if not request.json or "user_id" not in request.json:
        return make_response("Invalid request body", 400)

    # Retrieve the session from the database
    session = SessionModel.query.filter_by(user_id=request.json["user_id"]).first()

    # Check if the session exists and has not expired
    if not session or session.expiration < datetime.utcnow():
        return make_response("Session does not exist or has expired", 401)

    # Validate the provided token against the stored token
    if request.json["token"] != session.token:
        return make_response("Invalid token", 401)

    # Update the session version and expiration time
    session.version += 1
    session.expiration = datetime.utcnow() + timedelta(days=365)
    db.session.commit()

    # Return a success response
    return make_response("Session updated successfully", 204)

# Define the session deletion endpoint
@app.route("/sessions", methods=["DELETE"])
def delete_session():
    # Validate the request body
    if not request.json or "user_id" not in request.json:
        return make_response("Invalid request body", 400)

    # Retrieve the session from the database
    session = SessionModel.query.filter_by(user_id=request.json["user_id"]).first()

    # Check if the session exists and has not expired
    if not session or session.expiration < datetime.utcnow():
        return make_response("Session does not exist or has expired", 401)

    # Validate the provided token against the stored token
    if request.json["token"] != session.token:
        return make_response("Invalid token", 401)

    # Check if the session has been modified since the last fetch
    if session.version > request.json["version"]:
        return make_response("Session has been modified since the last fetch", 409)

    # Delete the session from the database
    db.session.delete(session)
    db.session.commit()

    # Return a success response
    return make_response("Session deleted successfully", 204)

# Define the error handling mechanism
@app.errorhandler(Exception)
def handle_error(error):
    print(f"An error occurred: {str(error)}")
    return make_response("An error occurred", 500)
