Here is an example of how you might implement this functionality in JavaScript:
```
const fs = require('fs');
const path = require('path');
const mongodb = require('mongodb');
const protocolsDir = 'protocols'; // directory where protocol implementations are stored
const droneConfigFile = 'drone_config.json'; // file where drone configurations are stored

class Drone {
  constructor(name, implementationClass, description, supportedFeatures) {
    this.name = name;
    this.implementationClass = implementationClass;
    this.description = description;
    this.supportedFeatures = supportedFeatures;
  }
}

class DroneController {
  constructor() {
    this.drones = []; // list of drones
    this.protocols = {}; // map of protocol implementations by name
    this.droneConfigs = {}; // map of drone configurations by name
  }

  // loadProtocols loads the protocol implementations from a specified directory
  async loadProtocols() {
    const protocolDir = path.join(__dirname, protocolsDir);
    const files = await fs.readdir(protocolDir);
    for (const file of files) {
      const protocolName = path.basename(file, '.js');
      this.protocols[protocolName] = require(path.join(protocolDir, file));
    }
  }

  // loadDroneConfigs loads the drone configurations from a specified JSON file
  async loadDroneConfigs() {
    const configFilePath = path.join(__dirname, droneConfigFile);
    const data = await fs.readFile(configFilePath);
    this.droneConfigs = JSON.parse(data);
  }

  // addDrone adds a new drone to the list of drones
  async addDrone(name, implementationClass, description, supportedFeatures) {
    const drone = new Drone(name, implementationClass, description, supportedFeatures);
    this.drones.push(drone);
  }

  // startDrone starts a drone and begins collecting data from the network stream
  async startDrone(name) {
    const drone = this.drones.find((d) => d.name === name);
    if (!drone) {
      throw new Error(`Drone with name ${name} does not exist`);
    }

    // initialize the drone's protocol implementation
    const ProtocolImpl = this.protocols[drone.implementationClass];
    const protocolInstance = new ProtocolImpl();

    // start collecting data from the network stream
    await protocolInstance.startCollectingData(drone.supportedFeatures);

    // save the drone's status to the database
    await this.saveDroneStatus(name, 'active');
  }

  // pauseDrone pauses a drone and stops collecting data from the network stream
  async pauseDrone(name) {
    const drone = this.drones.find((d) => d.name === name);
    if (!drone) {
      throw new Error(`Drone with name ${name} does not exist`);
    }

    // stop collecting data from the network stream
    await drone.protocolInstance.stopCollectingData();

    // save the drone's status to the database
    await this.saveDroneStatus(name, 'paused');
  }

  // resumeDrone resumes a paused drone and begins collecting data from the network stream again
  async resumeDrone(name) {
    const drone = this.drones.find((d) => d.name === name);
    if (!drone) {
      throw new Error(`Drone with name ${name} does not exist`);
    }

    // start collecting data from the network stream again
    await drone.protocolInstance.startCollectingData(drone.supportedFeatures);

    // save the drone's status to the database
    await this.saveDroneStatus(name, 'active');
  }

  // saveDroneStatus saves a drone's status to the database
  async saveDroneStatus(name, status) {
    const collection = await mongodb.connect('mongodb://localhost:27017/drones');
    const db = collection.db();
    const result = await db.collection('drone_status').insertOne({ name, status });
  }

  // logMissionEvent logs a mission event to the remote service
  async logMissionEvent(name, eventType, data) {
    try {
      const response = await fetch(`http://localhost:3000/mission-event`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ name, eventType, data })
      });
      if (!response.ok) {
        throw new Error(`Error logging mission event: ${response.statusText}`);
      }
    } catch (error) {
      console.log('Error logging mission event', error);
    }
  }

  // updateDroneStatus updates a drone's status via the control server API
  async updateDroneStatus(name, status) {
    try {
      const response = await fetch(`http://localhost:3001/drones/${name}/status`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ status })
      });
      if (!response.ok) {
        throw new Error(`Error updating drone status: ${response.statusText}`);
      }
    } catch (error) {
      console.log('Error updating drone status', error);
    }
  }
}
```
