class FileHandler:
    def __init__(self, file_paths):
        self.async_file_loader = AsyncFileLoader(file_paths)

    def load_files(self):
        # Load the JSON and JavaScript files asynchronously
        future_objects = []
        for file_path in self.async_file_loader.file_paths:
            extension = path.extname(file_path)
            if extension == '.json':
                # Load the JSON file asynchronously
                future_objects.append(self.async_file_loader.add_json_file(file_path))
            elif extension == '.js':
                # Load the JavaScript file asynchronously
                future_objects.append(self.async_file_loader.add_js_file(file_path))
            else:
                raise ValueError(f'Unsupported file extension: {extension}')

        # Wait for all files to be loaded before continuing
        for future_object in future_objects:
            if not future_object.valid:
                raise RuntimeError(f'Failed to load file: {str(future_object)}')

    def execute_files(self):
        # Execute the JSON and JavaScript files asynchronously
        future_results = []
        for file_path in self.async_file_loader.file_paths:
            extension = path.extname(file_path)
            if extension == '.json':
                # Execute the JSON file asynchronously
                future_results.append(self.async_file_loader.execute_json_file(file_path))
            elif extension == '.js':
                # Execute the JavaScript file asynchronously
                future_results.append(self.async_file_loader.execute_js_file(file_path))
            else:
                raise ValueError(f'Unsupported file extension: {extension}')

        # Wait for all files to be executed before continuing
        for future_result in future_results:
