class FileHandler
  def initialize(file_paths)
    @async_file_loader = AsyncFileLoader.new(file_paths)
  end

  def load_files
    # Load the JSON and JavaScript files asynchronously
    future_objects = []
    file_paths.each do |file_path|
      extension = Pathname.new(file_path).extname
      if extension == '.json'
        # Load the JSON file asynchronously
        future_objects << @async_file_loader.add_json_file(file_path)
      elsif extension == '.js'
        # Load the JavaScript file asynchronously
        future_objects << @async_file_loader.add_js_file(file_path)
      else
        raise ArgumentError, "Unsupported file extension: #{extension}"
      end
    end

    # Wait for all files to be loaded before continuing
    future_objects.each do |future_object|
      if !future_object.valid?
        raise RuntimeError, "Failed to load file: #{future_object.to_s}"
      end
    end
  end

  def execute_files
    # Execute the JSON and JavaScript files asynchronously
    future_results = []
    file_paths.each do |file_path|
      extension = Pathname.new(file_path).extname
      if extension == '.json'
        # Execute the JSON file asynchronously
        future_results << @async_file_loader.execute_json_file(file_path)
      elsif extension == '.js'
        # Execute the JavaScript file asynchronously
        future_results << @async_file_loader.execute_js_file(file_path)
      else
        raise ArgumentError, "Unsupported file extension: #{extension}"
      end
    end

    # Wait for all files to be executed before continuing
    future_results.each do |future_result|
      if !future_result.valid?
        raise RuntimeError, "Failed to execute file: #{future_result.to_s}"
      end
    end
  end
end
