using System;
using System.Data;
using System.Threading.Tasks;

namespace DatabaseConnectionManager
{
    public class DatabaseConnectionManager
    {
        private readonly string _connectionStringTemplate;
        private readonly Dictionary<string, string> _tenantIdentifierMapping;
        private readonly ConcurrentBag<IDbConnection> _pool = new ConcurrentBag<IDbConnection>();

        public DatabaseConnectionManager(string connectionStringTemplate, Dictionary<string, string> tenantIdentifierMapping)
        {
            _connectionStringTemplate = connectionStringTemplate;
            _tenantIdentifierMapping = tenantIdentifierMapping;
        }

        public IDbConnection EstablishConnection(string tenantIdentifier)
        {
            if (!_tenantIdentifierMapping.ContainsKey(tenantIdentifier))
            {
                throw new ArgumentException($"Invalid tenant identifier: {tenantIdentifier}");
            }

            var connectionString = GetTenantConnectionString(tenantIdentifier);
            var connection = CreateConnection(connectionString);

            _pool.Add(connection);

            return connection;
        }

        public async Task<IDbDataReader> ExecuteQueryAsync(string tenantIdentifier, string query)
        {
            var connection = EstablishConnection(tenantIdentifier);

            try
            {
                using (var command = connection.CreateCommand())
                {
                    command.CommandText = query;
                    return await command.ExecuteReaderAsync();
                }
            }
            catch (Exception ex)
            {
                throw new DatabaseConnectionException("Failed to execute query", ex);
            }
            finally
            {
                CloseConnection(connection);
            }
        }

        public void BeginTransaction(IDbConnection connection, string tenantIdentifier)
        {
            if (!_tenantIdentifierMapping.ContainsKey(tenantIdentifier))
            {
                throw new ArgumentException($"Invalid tenant identifier: {tenantIdentifier}");
            }

            if (connection == null)
            {
                throw new ArgumentNullException(nameof(connection));
            }

            connection.BeginTransaction();
        }

        public void CommitTransaction(IDbConnection connection, string tenantIdentifier)
        {
            if (!_tenantIdentifierMapping.ContainsKey(tenantIdentifier))
            {
                throw new ArgumentException($"Invalid tenant identifier: {tenantIdentifier}");
            }

            if (connection == null)
            {
                throw new ArgumentNullException(nameof(connection));
            }

            connection.CommitTransaction();
        }

        public void RollbackTransaction(IDbConnection connection, string tenantIdentifier)
        {
            if (!_tenantIdentifierMapping.ContainsKey(tenantIdentifier))
            {
                throw new ArgumentException($"Invalid tenant identifier: {tenantIdentifier}");
            }

            if (connection == null)
            {
                throw new ArgumentNullException(nameof(connection));
            }

            connection.RollbackTransaction();
        }

        public string GetTenantConnectionString(string tenantIdentifier)
        {
            if (!_tenantIdentifierMapping.ContainsKey(tenantIdentifier))
            {
                throw new ArgumentException($"Invalid tenant identifier: {tenantIdentifier}");
            }

            return _tenantIdentifierMapping[tenantIdentifier];
        }

        public void CloseConnection(IDbConnection connection)
        {
            if (connection == null)
            {
                throw new ArgumentNullException(nameof(connection));
            }

            _pool.Remove(connection);
            connection.Close();
        }

        private IDbConnection CreateConnection(string connectionString)
        {
            var factory = DbProviderFactories.GetFactory(connectionString);
            return factory.CreateConnection();
        }

        public override string ToString()
        {
            return $"Active connections: {_pool.Count}, Tenants: {_tenantIdentifierMapping.Keys.Count}";
        }
    }
}
