    def create_namespace(self, namespace_name):
        with self.lock:
            try:
                response = self.client.create_namespace(body=namespace_name)
                return response
            except Exception as e:
                print("Error creating namespace:", e)
                raise

    def deploy_application_manifest(self, manifest):
        with self.lock:
            try:
                response = self.client.create_deployment(body=manifest)
                return response
            except Exception as e:
                print("Error deploying application manifest:", e)
                raise

    def manage_resources(self, namespace, resources):
        with self.lock:
            try:
                for resource in resources:
                    response = self.client.create_resource(namespace=namespace, body=resource)
                    if not response.successful():
                        print("Error creating resource:", response)
                        raise
            except Exception as e:
                print("Error managing resources:", e)
                raise

class ResourceUtilizationMonitor:
    def __init__(self, client):
        self.client = client
        self.lock = Lock()

    def monitor_resources(self):
        with self.lock:
            try:
                response = self.client.list_namespaces()
                namespaces = response.items
                for namespace in namespaces:
                    pods = self.client.list_pods(namespace=namespace.metadata.name).items
                    for pod in pods:
                        if pod.status.phase == "Running":
                            cpu_usage = pod.metrics.cpu_usage
                            memory_usage = pod.metrics.memory_usage
                            print(f"Pod {pod.metadata.name} is using {cpu_usage}% CPU and {memory_usage}% memory.")
                        else:
                            print(f"Pod {pod.metadata.name} is not running.")
                return response
            except Exception as e:
                print("Error monitoring resources:", e)
                raise
