public class DynamicResourcePoolManager {
    private static final int MIN_CONNECTIONS = 10;
    private static final int MAX_CONNECTIONS = 50;
    private static final long CONNECTION_TIMEOUT = 30L;
    private static final int SEED = 42;

    private ConcurrentHashMap<String, CopyOnWriteArrayList<Connection>> poolMap = new ConcurrentHashMap<>();
    private ConnectionConfigCallback connectionConfigCallback = null;

    public DynamicResourcePoolManager(int minConnections, int maxConnections, long connectionTimeout) {
        this.MIN_CONNECTIONS = minConnections;
        this.MAX_CONNECTIONS = maxConnections;
        this.CONNECTION_TIMEOUT = connectionTimeout;
