            throw new IllegalArgumentException("Invalid number of connections: " + numConnections);
        }
        CopyOnWriteArrayList<Connection> pool = poolMap.computeIfAbsent(poolName, k -> new CopyOnWriteArrayList<>());
        synchronized (pool) {
