    public Connection acquireResource(String poolName, long timeout) throws InterruptedException {
        CopyOnWriteArrayList<Connection> pool = poolMap.get(poolName);
        if (pool == null) {
            throw new IllegalArgumentException("Invalid resource pool name: " + poolName);
        }
        synchronized (pool) {
            for (int i = 0; i < pool.size(); i++) {
                Connection connection = pool.get(i);
                if (!validateConnection(connection)) {
                    continue;
                }
                pool.remove(i);
                return connection;
            }
        }
        if (timeout > 0) {
            throw new InterruptedException("Timeout while acquiring resource");
        }
        return null;
    }

    public void releaseResource(String poolName, Connection connection) {
        CopyOnWriteArrayList<Connection> pool = poolMap.get(poolName);
        if (pool == null || !validateConnection(connection)) {
            throw new IllegalArgumentException("Invalid resource pool name or connection");
        }
        synchronized (pool) {
            pool.add(connection);
        }
    }

