from typing import List, Dict, Any

class JSONLoader:
    def __init__(self):
        self.registry = {}  # type: Dict[str, Callable[[Dict[str, Any]], Any]]
        self.files = []  # type: List[str]
        self.lock = threading.Lock()

    def add_factory(self, id: str, factory: Callable[[Dict[str, Any]], Any]):
        with self.lock:
            self.registry[id] = factory

    def create_instance(self, id: str, data: Dict[str, Any]) -> Any:
        with self.lock:
            if id not in self.registry:
                raise ValueError(f"Invalid ID {id}")
            return self.registry[id](data)

    def load_files(self, files: List[str]):
        self.files = []
        for file in files:
            if not os.path.exists(file):
                raise FileNotFoundError(f"File {file} does not exist")
            with open(file, "r") as f:
                data = json.load(f)
                self.files.append(data)

    def execute_files(self):
        for file in self.files:
            self.create_instance("main", file)

    def deserialize(self, data: bytes) -> Any:
        obj = json.loads(data.decode())
        return self.create_instance("main", obj)

    def hash_password(self, password: str) -> str:
        salt = b"random string"
        key = hashlib.pbkdf2_hmac("sha256", password.encode(), salt, 100000)
        return base64.b64encode(key).decode()

    def log(self, message: str):
        logging.info(message)

    def run(self):
        try:
            self.load_files(["file1.json", "file2.json"])
            self.execute_files()
            obj = self.deserialize(b"random bytes")
            hashed_password = self.hash_password("password")
            self.log(f"Hashed password: {hashed_password}")
        except Exception as e:
            self.log(f"Error occurred: {e}")
