import logging
from concurrent.futures import ThreadPoolExecutor
from typing import List

class LogProcessor:
    def __init__(self, filters: List[str]):
        self.filters = filters
        self.executor = ThreadPoolExecutor(max_workers=5)

    def process_logs(self, log_stream: Iterable[dict]) -> Iterable[dict]:
        for log in log_stream:
            if any(log['message'].startswith(filter_) for filter_ in self.filters):
                yield log

class LogStorage:
    def __init__(self, database):
        self.database = database

    def store_logs(self, logs: Iterable[dict]):
        with self.database.session() as session:
            for log in logs:
                session.add(log)
            session.commit()

class LogManagementService:
    def __init__(self, log_processor: LogProcessor, log_storage: LogStorage):
        self.log_processor = log_processor
        self.log_storage = log_storage

    def process_and_store_logs(self, log_stream: Iterable[dict]):
        processed_logs = self.log_processor.process_logs(log_stream)
        self.log_storage.store_logs(processed_logs)

class LogPipeline:
    def __init__(self, filters: List[str], database, log_management_service):
        self.filters = filters
        self.database = database
        self.log_management_service = log_management_service

    def process_and_store_logs(self, log_stream: Iterable[dict]):
        self.log_management_service.process_and_store_logs(log_stream)

# Example usage:
log_pipeline = LogPipeline(filters=['error', 'warning'], database=<database>, log_management_service=LogManagementService(LogProcessor(filters), LogStorage(database)))
log_pipeline.process_and_store_logs(iterable_of_logs)

