import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;
import java.net.SocketAddress;
import java.nio.channels.AsynchronousChannelGroup;
import java.nio.channels.AsynchronousServerSocketChannel;
import java.nio.channels.AsynchronousSocketChannel;
import java.nio.channels.CompletionHandler;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.logging.Logger;

public class ConnectionPool {
    private static final Logger logger = Logger.getLogger(ConnectionPool.class.getName());
    private static final int INITIAL_POOL_SIZE = 10;
    private static final int MAX_POOL_SIZE = 50;
    private static final long CONNECTION_TIMEOUT = 30000L; // 30 seconds
    private static final long RECONNECT_INTERVAL = 60000L; // 1 minute
    private static final int HEALTH_CHECK_INTERVAL = 5000; // 5 seconds

    private ConcurrentHashMap<SocketAddress, AtomicInteger> serverStatuses;
    private CopyOnWriteArrayList<AsynchronousServerSocketChannel> serverChannels;
    private AsynchronousChannelGroup channelGroup;
    private ExecutorService connectionExecutor;
    private Lock connectionLock;
    private volatile boolean shutdown = false;

    public ConnectionPool() {
        this.serverStatuses = new ConcurrentHashMap<>();
        this.serverChannels = new CopyOnWriteArrayList<>();
        this.connectionExecutor = Executors.newFixedThreadPool(INITIAL_POOL_SIZE);
        this.channelGroup = AsynchronousChannelGroup.withFixedThreadPool(INITIAL_POOL_SIZE, connectionExecutor);
        this.connectionLock = new ReentrantLock();
    }

    public void start() {
        for (int i = 0; i < INITIAL_POOL_SIZE; i++) {
            connectToServer(i);
        }
    }

    public void stop() {
        shutdown = true;
        connectionExecutor.shutdown();
        channelGroup.close();
    }

    public AsynchronousSocketChannel getConnection(SocketAddress serverAddress) throws InterruptedException {
        if (shutdown) {
            throw new IllegalStateException("Connection pool is shut down");
        }

        connectionLock.lock();
        try {
            // Check if the connection is already established and available
            AsynchronousSocketChannel channel = serverChannels.stream()
                    .filter(c -> c.isConnected() && !c.isConnectionPending())
                    .findFirst()
                    .orElse(null);

            // If no connection is available, create a new one
            if (channel == null) {
                channel = AsynchronousSocketChannel.open(channelGroup);
                connectionExecutor.submit(() -> connectToServer(channel));
            }

            return channel;
        } finally {
            connectionLock.unlock();
        }
    }

    private void connectToServer(AsynchronousServerSocketChannel server) throws InterruptedException {
        logger.info("Connecting to server " + server.getRemoteAddress());
        server.connect(server.getRemoteAddress(), null, new CompletionHandler<Void, Void>() {
            @Override
            public void completed(Void result, Void attachment) {
                connectionLock.lock();
                try {
                    // Add the connected channel to the list of available channels
                    serverChannels.add(server);
                } finally {
                    connectionLock.unlock();
                }
            }

            @Override
            public void failed(Throwable exc, Void attachment) {
                logger.severe("Failed to connect to server " + server.getRemoteAddress());
                try {
                    // Try to reconnect to the server after a short interval
                    connectionExecutor.schedule(() -> connectToServer(server), RECONNECT_INTERVAL, TimeUnit.MILLISECONDS);
                } catch (Exception e) {
                    logger.severe("Error scheduling reconnection: " + e.getMessage());
                }
            }
        });
    }

    private void connectToServer(int index) throws InterruptedException {
        // Get the next server address from the load balancer
        SocketAddress serverAddress = getNextServerAddress();

        // Create a new asynchronous socket channel and connect to the server
        AsynchronousSocketChannel channel = AsynchronousSocketChannel.open(channelGroup);
        channel.connect(serverAddress, null, new CompletionHandler<Void, Void>() {
            @Override
            public void completed(Void result, Void attachment) {
                connectionLock.lock();
                try {
                    // Add the connected channel to the list of available channels
                    serverChannels.add(channel);

                    // Check if there are any pending connections and create a new channel for each one
                    if (!pendingConnections.isEmpty()) {
                        Iterator<SocketAddress> iterator = pendingConnections.iterator();
                        while (iterator.hasNext()) {
                            connectToServer(iterator.next());
                            iterator.remove();
                        }
                    }
                } finally {
                    connectionLock.unlock();
                }
            }

            @Override
            public void failed(Throwable exc, Void attachment) {
                logger.severe("Failed to connect to server " + serverAddress);
                try {
                    // Try to reconnect to the server after a short interval
                    connectionExecutor.schedule(() -> connectToServer(serverAddress), RECONNECT_INTERVAL, TimeUnit.MILLISECONDS);
                } catch (Exception e) {
                    logger.severe("Error scheduling reconnection: " + e.getMessage());
                }
            }
        });
    }

    private void disconnectFromServer(AsynchronousSocketChannel channel) {
        connectionLock.lock();
        try {
            // Remove the channel from the list of available channels
            serverChannels.remove(channel);

            // Close the channel to release any resources it is holding
            channel.close();
        } finally {
            connectionLock.unlock();
        }
    }

    private void disconnectFromServer(SocketAddress serverAddress) {
        connectionLock.lock();
        try {
            // Find the channel associated with the given address and close it
            for (AsynchronousSocketChannel channel : serverChannels) {
                if (channel.getRemoteAddress().equals(serverAddress)) {
                    disconnectFromServer(channel);
                    break;
                }
            }
        } finally {
            connectionLock.unlock();
        }
    }

    private void checkConnectionTimeout() {
        // Check if any of the connections have timed out and close them
        for (AsynchronousSocketChannel channel : serverChannels) {
            long lastActiveTime = channel.socket().getLastAktivityTime();
            if (System.currentTimeMillis() - lastActiveTime > CONNECTION_TIMEOUT) {
                disconnectFromServer(channel);
            }
        }
    }

    private void checkConnectionLiveness() {
        // Check if any of the connections are no longer active and close them
        for (AsynchronousSocketChannel channel : serverChannels) {
            if (!channel.isConnected()) {
                disconnectFromServer(channel);
            }
        }
    }
}

