<?php

namespace App\Services;

use App\Models\User;
use Illuminate\Support\Facades\Cache;
use Illuminate\Http\Request;
use GuzzleHttp\Client as HttpClient;
use League\OAuth2\Client\Provider\GenericProvider;

class OAuthAuthenticationService
{
    private $provider;

    public function __construct(GenericProvider $provider)
    {
        $this->provider = $provider;
    }

    public function authenticate(Request $request)
    {
        // Get the authorization code from the request
        $code = $request->input('code');

        // Exchange the authorization code for an access token
        $token = $this->provider->getAccessToken('authorization_code', ['code' => $code]);

        // Use the access token to make a request to get user information
        $userInfo = $this->provider->getResourceOwner($token);

        // Store the access token and user information in the session
        session(['access_token' => $token->getToken()]);
        session(['user_info' => $userInfo->toArray()]);

        // Cache the user information for later use
        Cache::put('user-info', $userInfo, 1440); // cache for 24 hours
    }

    public function getUser(Request $request)
    {
        if (!session()->has('access_token')) {
            return null;
        }

        // Get the cached user information from the session
        $userInfo = session('user-info');

        if ($userInfo instanceof User) {
            return $userInfo;
        }

        // If the cache is not available, make a request to get the user information
        $token = session('access_token');
        $userInfo = $this->provider->getResourceOwner($token);
        session(['user-info' => $userInfo]);

        return $userInfo;
    }
}
```
This code uses the Guzzle HTTP client to make requests to the OAuth provider. It also uses Laravel's built-in cache system to store user information for later use. The `OAuthAuthenticationService` class has a method called `authenticate` that handles the authentication process and stores the access token and user information in the session. It also has a method called `getUser` that retrieves the cached user information from the session or makes a request to get it if necessary.

