using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using System.Net.Http;
using System.Text;
using Newtonsoft.Json;
using Redis;

public class UserProfileCache
{
    private readonly IConnectionMultiplexer _redis;
    private readonly HttpClient _httpClient;
    private readonly string _apiUrl;
    private readonly int _cacheExpirationTime;
    private readonly List<string> _userIds;

    public UserProfileCache(IConnectionMultiplexer redis, HttpClient httpClient, string apiUrl, int cacheExpirationTime)
    {
        _redis = redis;
        _httpClient = httpClient;
        _apiUrl = apiUrl;
        _cacheExpirationTime = cacheExpirationTime;
        _userIds = new List<string>();
    }

    public async Task<List<UserProfile>> GetUserProfilesAsync(List<string> userIds)
    {
        // Validate the input data
        foreach (var userId in userIds)
        {
            if (!IsValidUserId(userId))
                throw new ArgumentException("Invalid user ID", nameof(userIds));
        }

        var cachedProfiles = new List<UserProfile>();

        // Retrieve profiles from cache
        foreach (var userId in userIds)
        {
            var profileJson = await _redis.GetStringAsync($"{userId}");
            if (!string.IsNullOrEmpty(profileJson))
            {
                cachedProfiles.Add(JsonConvert.DeserializeObject<UserProfile>(profileJson));
            }
        }

        // Fetch profiles from API and cache them
        foreach (var userId in userIds)
        {
            if (!cachedProfiles.Any(p => p.UserId == userId))
            {
                var profile = await FetchProfileAsync(userId);
                cachedProfiles.Add(profile);
                _redis.SetString($"{userId}", JsonConvert.SerializeObject(profile));
            }
        }

        // Return the cached profiles
        return cachedProfiles;
    }

    private bool IsValidUserId(string userId)
    {
        // Implement your custom validation logic here
        return true;
    }

    private async Task<UserProfile> FetchProfileAsync(string userId)
    {
        var request = new HttpRequestMessage(HttpMethod.Get, $"{_apiUrl}/users/{userId}");
        var response = await _httpClient.SendAsync(request);

        if (response.StatusCode == HttpStatusCode.OK)
        {
            var profileJson = await response.Content.ReadAsStringAsync();
            return JsonConvert.DeserializeObject<UserProfile>(profileJson);
        }
        else
        {
            // Handle failed requests and retries
            var attempt = 0;
            while (attempt < 3)
            {
                response = await _httpClient.SendAsync(request);
                if (response.StatusCode == HttpStatusCode.OK)
                {
                    var profileJson = await response.Content.ReadAsStringAsync();
                    return JsonConvert.DeserializeObject<UserProfile>(profileJson);
                }
                else
                {
                    attempt++;
                }
            }

            // Log failed attempts and mark them as failures
            _logger.LogError($"Failed to fetch user profile for user ID: {userId}");
            return null;
        }
    }
}
```
