import json
import os
import logging
from collections import deque

class JsonObject:
    def __init__(self, data):
        self.data = data

    @staticmethod
    def from_json(json_string):
        return JsonObject(json.loads(json_string))

    def to_json(self):
        return json.dumps(self.data)

class FileManager:
    def __init__(self, directory):
        self.directory = directory
        self.files = {}
        self.factories = {}
        self.load_files()

    def load_files(self):
        for filename in os.listdir(self.directory):
            if not os.path.isfile(os.path.join(self.directory, filename)):
                continue
            filepath = os.path.join(self.directory, filename)
            with open(filepath, "r") as f:
                data = f.read()
            self.files[filename] = JsonObject(data)

    def load_factory(self, factory):
        if not callable(factory):
            raise ValueError("Factory must be a callable function.")
        self.factories[factory.__name__] = factory

    def create_object(self, filename, position=None):
        if filename not in self.files:
            raise FileNotFoundError(f"File '{filename}' not found in directory '{self.directory}'.")
        data = self.files[filename].data
        if position is None:
            return JsonObject(data)
        if position < 0 or position >= len(data):
            raise ValueError("Position index out of bounds.")
        return JsonObject(data[position])

    def insert_object(self, filename, obj, position=None):
        if filename not in self.files:
            raise FileNotFoundError(f"File '{filename}' not found in directory '{self.directory}'.")
        data = self.files[filename].data
        if position is None:
            position = len(data) - 1
        data.insert(position, obj.to_json())

    def read_file(self, filename):
        if filename not in self.files:
            raise FileNotFoundError(f"File '{filename}' not found in directory '{self.directory}'.")
        with open(os.path.join(self.directory, filename), "r") as f:
            return f.read()

    def write_file(self, filename, data):
        if filename not in self.files:
            raise FileNotFoundError(f"File '{filename}' not found in directory '{self.directory}'.")
        with open(os.path.join(self.directory, filename), "w") as f:
            f.write(data)

class JsonDeserializer:
    def __init__(self):
        self.logger = logging.getLogger("JsonDeserializer")

    def deserialize_json(self, json_string):
        try:
            data = json.loads(json_string)
        except ValueError as e:
            self.logger.error(f"Failed to deserialize JSON string: {e}")
            return None
        return JsonObject(data)

    def serialize_object(self, obj):
        try:
            json_string = obj.to_json()
        except ValueError as e:
            self.logger.error(f"Failed to serialize object: {e}")
            return None
        return json_string

class StringUtility:
    def __init__(self):
        self.logger = logging.getLogger("StringUtility")

    def hash_password(self, password):
        try:
            salt = os.urandom(16)
            hashed_password = hashlib.pbkdf2_hmac("sha256", password.encode(), salt, 100000)
            random_string = binascii.hexlify(os.urandom(32))
            return (random_string, hashed_password)
        except ValueError as e:
            self.logger.error(f"Failed to hash password: {e}")
            return None

class JsonForwardList:
    def __init__(self):
        self.forward_list = deque()

    def insert(self, obj, position=None):
        if not isinstance(obj, JsonObject):
            raise ValueError("Obj must be an instance of JsonObject.")
        if position is None:
            position = len(self.forward_list) - 1
        self.forward_list.insert(position, obj)

    def pop(self, index=None):
        return self.forward_list.popleft()

    def __len__(self):
        return len(self.forward_list)

class JsonObjectFactory:
    def __init__(self, factory):
        if not callable(factory):
            raise ValueError("Factory must be a callable function.")
        self.factory = factory

    def create_object(self, data):
        return self.factory(data)
```
