public static void ExecuteQuery(SqlConnection connection, string commandTemplate, Dictionary<string, object> parameters)
{
    // Validate input parameters to prevent SQL injection attacks
    if (connection == null || commandTemplate == null || parameters == null)
    {
        throw new ArgumentNullException("Invalid input parameter");
    }

    // Create a new command from the template and set its connection
    SqlCommand command = new SqlCommand(commandTemplate, connection);

    // Add the parameters to the command
    foreach (var parameter in parameters)
    {
        command.Parameters.AddWithValue(parameter.Key, parameter.Value);
    }

    // Execute the query and retrieve the results
    var result = command.ExecuteReader();

    // Handle any errors that may occur during query execution
    if (result.HasRows)
    {
        while (result.Read())
        {
            Console.WriteLine(string.Join(", ", result));
        }
    }
    else
    {
        Console.WriteLine("No results found");
    }

    // Close the connection and clean up resources
    connection.Close();
}
