public static void establishConnection(String host, int port, String username, String password) throws IOException {
    SocketChannel channel = SocketChannel.open(new InetSocketAddress(host, port));
    channel.configureBlocking(false);
    ByteBuffer buffer = ByteBuffer.allocateDirect(1024);
    buffer.put(("GET / HTTP/1.1\r\nHost: " + host + "\r\nAuthorization: Basic " + username + ":" + password + "\r\n\r\n").getBytes());
    channel.write(buffer, 0, buffer.capacity(), null, new CompletionHandler<Integer, Object>() {
        @Override
        public void completed(Integer result, Object attachment) {
            if (result != 0) {
                System.out.println("Connection established");
            } else {
                System.out.println("Error establishing connection");
            }
        }

        @Override
        public void failed(Throwable exc, Object attachment) {
            System.out.println("Failed to establish connection: " + exc);
        }
    });
}
