    if (!script.code) {
      // Handle missing essential properties such as `code`
      return null;
    }

    const type = script.type || "text/javascript";
    const key = script.key || "";
    const src = script.src || "";

    return `<script key="${key}" type="${type}">${script.code}</script>`;
  }).join("\n");
};

