using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Web;
using System.Xml;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;

public class WebAppManager : IWebAppManager
{
    private readonly string _directoryPath;
    private readonly ILogger<WebAppManager> _logger;
    private readonly IConfiguration _config;

    public WebAppManager(string directoryPath, ILogger<WebAppManager> logger, IConfiguration config)
    {
        _directoryPath = directoryPath;
        _logger = logger;
        _config = config;
    }

    public async Task AddSiteAsync(string siteName, int basePortNumber)
    {
        ValidateInputs(siteName, basePortNumber);

        var siteDirectory = GetSiteDirectory(siteName, basePortNumber);
        if (Directory.Exists(siteDirectory))
        {
            throw new Exception($"Site with name '{siteName}' and port number {basePortNumber} already exists.");
        }

        try
        {
            Directory.CreateDirectory(siteDirectory);
            _logger.LogInformation("Created site directory: {0}", siteDirectory);
        }
        catch (Exception ex)
        {
            throw new Exception($"Failed to create site directory: {ex.Message}");
        }

        var webConfigFile = Path.Combine(siteDirectory, "web.config");
        if (!File.Exists(webConfigFile))
        {
            await IntegrateWithExternalServiceAsync(siteName, basePortNumber);
        }

        OptimisticLocking.Acquire();
        try
        {
            var portMap = GetPortMap();
            var portAssignment = AssignPortNumber(portMap, basePortNumber);

            UpdateSiteDirectory(siteDirectory, portAssignment.PortNumber, portAssignment.Allocated);
            _logger.LogInformation("Added site: {0} (port number: {1})", siteName, portAssignment.PortNumber);
        }
        finally
        {
            OptimisticLocking.Release();
        }
    }

    public async Task RemoveSiteAsync(string siteName)
    {
        var siteDirectory = GetSiteDirectory(siteName);
        if (!Directory.Exists(siteDirectory))
        {
            throw new Exception($"Site with name '{siteName}' not found.");
        }

        OptimisticLocking.Acquire();
        try
        {
            Directory.Delete(siteDirectory, true);
            _logger.LogInformation("Removed site: {0}", siteName);
        }
        finally
        {
            OptimisticLocking.Release();
        }
    }

    public async Task UpdateSiteAsync(string siteName, int newBasePortNumber)
    {
        ValidateInputs(siteName, newBasePortNumber);

        var siteDirectory = GetSiteDirectory(siteName);
        if (!Directory.Exists(siteDirectory))
        {
            throw new Exception($"Site with name '{siteName}' not found.");
        }

        OptimisticLocking.Acquire();
        try
        {
            var portMap = GetPortMap();
            var currentPortAssignment = GetCurrentPortAssignment(siteDirectory);
            if (currentPortAssignment == null)
            {
                throw new Exception($"Site '{siteName}' has not been added to the manager.");
            }

            var newPortAssignment = AssignPortNumber(portMap, newBasePortNumber);
            if (newPortAssignment.Allocated && currentPortAssignment.PortNumber != newPortAssignment.PortNumber)
            {
                throw new Exception($"Site '{siteName}' cannot be updated to use a different port number.");
            }

            UpdateSiteDirectory(siteDirectory, newPortAssignment.PortNumber, newPortAssignment.Allocated);
            _logger.LogInformation("Updated site: {0} (port number: {1})", siteName, newPortAssignment.PortNumber);
        }
        finally
        {
            OptimisticLocking.Release();
        }
    }

    public async Task<IList<Site>> GetSitesAsync()
    {
        var siteDirectories = Directory.GetDirectories(_directoryPath);
        return siteDirectories.Select(d => new Site
        {
            Name = Path.GetFileName(d),
            PortNumber = GetCurrentPortAssignment(d).PortNumber,
        }).ToList();
    }

    private void ValidateInputs(string siteName, int basePortNumber)
    {
        if (string.IsNullOrEmpty(siteName))
        {
            throw new ArgumentException("Site name cannot be empty.", nameof(siteName));
        }

        if (basePortNumber < 1024 || basePortNumber > 65535)
        {
            throw new ArgumentOutOfRangeException(nameof(basePortNumber), "Base port number must be between 1024 and 65535.");
        }
    }

    private string GetSiteDirectory(string siteName, int basePortNumber = -1)
    {
        var directoryPath = Path.Combine(_directoryPath, siteName);
        if (basePortNumber > 0)
        {
            return Path.Combine(directoryPath, $"{basePortNumber}");
        }

        return directoryPath;
    }

    private async Task IntegrateWithExternalServiceAsync(string siteName, int basePortNumber)
    {
        //TODO: Implement external service integration for configuration management.
    }

    private Dictionary<int, bool> GetPortMap()
    {
        var portMap = new Dictionary<int, bool>();
        foreach (var directory in Directory.GetDirectories(_directoryPath))
        {
            var portString = Path.GetFileName(directory);
            if (!int.TryParse(portString, out var portNumber)) continue;

            var allocated = File.Exists(Path.Combine(directory, "web.config"));
            portMap[portNumber] = allocated;
        }

        return portMap;
    }

    private PortAssignment AssignPortNumber(Dictionary<int, bool> portMap, int basePortNumber)
    {
        var portAvailable = false;
        for (var i = basePortNumber; i < 65535; i++)
        {
            if (!portMap.ContainsKey(i)) continue;
            if (portMap[i]) continue;

            portMap[i] = true;
            portAvailable = true;
            break;
        }

        if (!portAvailable)
        {
            throw new Exception("No available ports.");
        }

        return new PortAssignment
        {
            PortNumber = i,
            Allocated = true,
        };
    }

    private void UpdateSiteDirectory(string siteDirectory, int portNumber, bool allocated)
    {
        var webConfigPath = Path.Combine(siteDirectory, "web.config");
        if (allocated && !File.Exists(webConfigPath))
        {
            File.Create(webConfigPath);
        }
        else if (!allocated && File.Exists(webConfigPath))
        {
            File.Delete(webConfigPath);
        }
    }

    private PortAssignment GetCurrentPortAssignment(string siteDirectory)
    {
        var portString = Path.GetFileName(siteDirectory);
        if (!int.TryParse(portString, out var portNumber)) return null;

        return new PortAssignment
        {
            PortNumber = portNumber,
            Allocated = File.Exists(Path.Combine(siteDirectory, "web.config")),
        };
    }
}

