use std::env;
use std::fs;
use std::path::PathBuf;
use std::time::Duration;

struct WorkDirManager {
    work_dir: PathBuf,
    temp_dir: PathBuf,
    cleanup_interval: Duration,
}

impl WorkDirManager {
    fn new() -> Self {
        // Initialize the work directory and temporary directory
        let work_dir = env::var("WORK_DIR").unwrap_or_else(|_| {
            fs::create_temp_dir(None, None, None).map_err(|e| e.to_string()).unwrap()
        });
        let temp_dir = fs::create_temp_dir(None, None, None).map_err(|e| e.to_string()).unwrap();

        Self { work_dir, temp_dir, cleanup_interval: Duration::from_secs(3600) } // 1 hour
    }

    fn validate_work_dir(&self) -> Result<(), String> {
        if !self.work_dir.exists() || !self.work_dir.is_dir() || !self.work_dir.can_read() || !self.work_dir.can_write() {
            return Err(format!("Invalid work directory: {}", self.work_dir.display()));
        }

        Ok(())
    }

    fn set_work_dir(&mut self, new_dir: PathBuf) -> Result<(), String> {
        if !new_dir.exists() || !new_dir.is_dir() || !new_dir.can_read() || !new_dir.can_write() {
            return Err(format!("Invalid work directory: {}", new_dir.display()));
        }

        self.work_dir = new_dir;

        Ok(())
    }

    fn get_work_dir(&self) -> &PathBuf {
        &self.work_dir
    }

    fn create_temp_dir(&mut self, name: Option<&str>) -> Result<(), String> {
        let temp_dir = fs::create_temp_dir(None, None, None).map_err(|e| e.to_string()).unwrap();

        if !temp_dir.exists() || !temp_dir.is_dir() || !temp_dir.can_read() || !temp_dir.can_write() {
            return Err(format!("Failed to create temporary directory: {}", temp_dir.display()));
        }

        self.temp_dir = temp_dir;

        Ok(())
    }

    fn get_temp_dir(&self) -> &PathBuf {
        &self.temp_dir
    }

    fn cleanup_work_dir(&mut self, interval: Duration) {
        // Remove the work directory after a specified time
        if let Some(cleaner) = &self.cleaner {
            cleaner.cancel();
        }

        self.cleaner = Some(tokio::time::sleep_until(std::time::Instant::now() + interval).await);
    }

    fn configure_plugin(&mut self, plugin: &str, config: &Value) -> Result<(), String> {
        // TODO: Implement the configuration of the external CI/CD system
        Ok(())
    }
}
