```
use std::path::Path;
use std::fs::{create_dir, remove_dir};
use std::time::{SystemTime, Duration};
use std::env;

const MY_DIR_PATH: &str = "MY_DIR_PATH";
const CLEANUP_INTERVAL: u64 = 10 * 60; // 10 minutes in seconds
const MAX_DISK_USAGE: f64 = 0.8; // 80% of available space

struct Directory {
    path: Path,
    cleanup_interval: Duration,
    last_cleanup: SystemTime,
}

impl Directory {
    fn new(path: &str) -> Self {
        let mut dir = create_dir(path).unwrap();
        let cleanup_interval = Duration::from_secs(CLEANUP_INTERVAL);
        let last_cleanup = SystemTime::now();
        Self { path, cleanup_interval, last_cleanup }
    }

    fn check_dir(&self) -> Result<(), String> {
        if !self.path.exists() || !self.path.is_dir() {
            return Err("Directory does not exist or is not a directory".to_string());
        }
        Ok(())
    }

    fn create(&mut self) -> Result<(), String> {
        if self.check_dir().is_err() {
            let mut dir = create_dir(self.path).unwrap();
            self.last_cleanup = SystemTime::now();
            Ok(())
        } else {
            Err("Directory already exists".to_string())
        }
    }

    fn set_env(&mut self) -> Result<(), String> {
        env::set_var(MY_DIR_PATH, &self.path).map_err(|e| e.to_string())?;
        Ok(())
    }

    fn cleanup(&mut self) -> Result<(), String> {
        let mut dir = remove_dir(&self.path).unwrap();
        self.last_cleanup = SystemTime::now();
        Ok(())
    }

    fn check_disk_usage(&self) -> Result<(), String> {
        if (self.path.metadata()?.len() as f64 / self.path.metadata()?.available_space() as f64) > MAX_DISK_USAGE {
            return Err("Disk usage exceeded".to_string());
        }
        Ok(())
    }

    fn monitor(&mut self) -> Result<(), String> {
        if self.check_disk_usage().is_err() {
            self.cleanup().unwrap();
        }
        Ok(())
    }
}
