function fetchDynamicContent(selector) {
  // Initialize variables for API calls and DOM elements
  const apiCalls = [];
  let domElements = document.querySelectorAll(selector);

  // Iterate over each element in the DOM tree that matches the selector
  domElements.forEach((element) => {
    // Determine which API to use based on the element's attributes or data-* properties
    const apiName = getApiName(element);

    // Create a new API call object and add it to the list of calls
    const apiCall = {
      name: apiName,
      endpoint: getEndpointUrl(apiName, element),
      params: getParams(apiName, element),
      dataType: getDataType(apiName),
      headers: getHeaders(apiName),
    };
    apiCalls.push(apiCall);
  });

  // Perform all API calls in parallel and prioritize critical content
  Promise.allSettled(apiCalls).then((responses) => {
