public class PaymentProcessor {
    private static final Map<String, Order> orders = new HashMap<>();
    private static final int MAX_RETRIES = 5;

    public void processPayment(String paymentMethod, double amount, String orderId) throws PaymentException {
        if (!orders.containsKey(orderId)) {
            throw new OrderNotFoundException("Order not found");
        }

        // Validate payment method and amount
        validatePaymentMethod(paymentMethod);
        validateAmount(amount);

        int retries = 0;
        while (retries < MAX_RETRIES) {
            try {
                updateOrderStatus(orderId, "paid");
                break;
            } catch (ExternalServiceException e) {
                retries++;
                if (retries >= MAX_RETRIES) {
                    log.error("Failed to process payment after {} retries", retries);
                    throw new PaymentException(e.getMessage());
                }
            }
        }

        // Log successful payment
        log.info("Payment processed successfully for order ID: {}", orderId);
    }

    public void cancelOrder(String orderId) throws OrderNotFoundException, ExternalServiceException {
        if (!orders.containsKey(orderId)) {
            throw new OrderNotFoundException("Order not found");
        }

        // Validate order is not already cancelled
        Order order = orders.get(orderId);
        if (order.isCancelled()) {
            log.info("Order {} is already cancelled", orderId);
            return;
        }

        // Cancel order and update status in database
        updateOrderStatus(orderId, "cancelled");

        // Log successful cancellation
        log.info("Cancelled order {} successfully", orderId);
    }

    public void refundOrder(String orderId, double refundAmount) throws OrderNotFoundException, ExternalServiceException {
        if (!orders.containsKey(orderId)) {
