public class DynamicResourcePoolManager {
    private final int minConnections;
    private final int maxConnections;
    private final long connectionTimeout;
    private final Map<String, ConnectionConfig> resourcePools;
    private final ConnectionConfigCallback connectionConfigCallback;

    public DynamicResourcePoolManager(int minConnections, int maxConnections, long connectionTimeout) {
        this.minConnections = minConnections;
        this.maxConnections = maxConnections;
        this.connectionTimeout = connectionTimeout;
        this.resourcePools = new ConcurrentHashMap<>();
    }

    public DynamicResourcePoolManager(int minConnections, int maxConnections, long connectionTimeout, ConnectionConfigCallback connectionConfigCallback) {
        this(minConnections, maxConnections, connectionTimeout);
        this.connectionConfigCallback = connectionConfigCallback;
    }

    private void initializeResourcePool(String resourceName, int minConnections, int maxConnections, long connectionTimeout) {
        // Validate input parameters
        if (minConnections < 0 || minConnections > maxConnections) {
            throw new IllegalArgumentException("Invalid minimum or maximum number of connections");
        }
        if (connectionTimeout <= 0) {
            throw new IllegalArgumentException("Invalid connection timeout");
        }

        // Update pool configuration if necessary
        ConnectionConfig config = new ConnectionConfig(minConnections, maxConnections, connectionTimeout);
        resourcePools.computeIfAbsent(resourceName, k -> config);
    }

    private void seedConnectionPool(String resourceName, int numSeeds) {
        // Validate input parameters
        if (numSeeds <= 0) {
            throw new IllegalArgumentException("Invalid number of seeds");
        }

        // Handle concurrent seeding attempts to avoid race conditions and ensure consistency
        synchronized (resourcePools.get(resourceName)) {
            for (int i = 0; i < numSeeds; i++) {
                // Set up initial connections before other threads start accessing the pool
                ConnectionConfig config = resourcePools.get(resourceName);
                config.incrementConnectionCount();
            }
        }
    }

    private void configureResourcePool(String resourceName, int minConnections, int maxConnections, long connectionTimeout) {
        // Update pool configuration if necessary
        ConnectionConfig config = new ConnectionConfig(minConnections, maxConnections, connectionTimeout);
        resourcePools.computeIfPresent(resourceName, (k, v) -> config);
    }

    private void configureResourcePoolWithCallback(String resourceName, ConnectionConfigCallback callback) {
        // Use the provided callback to update the pool configuration
        ConnectionConfig config = callback.configureConnectionConfig(resourcePools.get(resourceName));
        resourcePools.computeIfPresent(resourceName, (k, v) -> config);
    }

    public synchronized void acquireResource(String resourceName, long timeout) {
        // Validate input parameters
        if (timeout <= 0) {
            throw new IllegalArgumentException("Invalid timeout");
        }

        // Handle failed resource acquisitions with exponential backoff and retry logic
        int numRetries = 1;
        while (true) {
            try {
                // Acquire a connection from the pool
                ConnectionConfig config = resourcePools.get(resourceName);
                if (config == null) {
                    throw new ResourceNotFoundException("Resource pool not found: " + resourceName);
                }
                int currentConnectionCount = config.getCurrentConnectionCount();
                if (currentConnectionCount >= config.getMaxConnections()) {
                    // Pool is full, sleep and retry
                    try {
                        Thread.sleep(Math.pow(2, numRetries) * 100);
                    } catch (InterruptedException e) {
                        // Ignore interrupts
                    }
                } else {
                    config.incrementConnectionCount();
                    break;
                }
            } catch (ResourceNotFoundException e) {
                throw new ResourceNotFoundException("Resource pool not found: " + resourceName);
            } finally {
                // Ensure the connection is released if an exception occurs
                try {
                    releaseResource(resourceName);
                } catch (ResourceNotFoundException | ResourceExhaustedException e) {
                    // Ignore exceptions, as we are already handling a failure
                }
            }
        }
    }

    public synchronized void releaseResource(String resourceName) throws ResourceNotFoundException, ResourceExhaustedException {
        // Validate input parameters
        if (resourceName == null || resourceName.isEmpty()) {
            throw new IllegalArgumentException("Invalid resource name");
        }

        // Release the connection from the pool
        ConnectionConfig config = resourcePools.get(resourceName);
        if (config == null) {
            throw new ResourceNotFoundException("Resource pool not found: " + resourceName);
        }
        int currentConnectionCount = config.getCurrentConnectionCount();
        if (currentConnectionCount <= 0) {
            throw new ResourceExhaustedException("No connections available in pool: " + resourceName);
        }
        config.decrementConnectionCount();
    }
}
