const loadScripts = (scripts, callback) => {
  const loadedScripts = {};
  let loadingCount = 0;
  scripts.forEach((script) => {
    if (script.code) {
      // Load script from code
      const newScript = document.createElement('script');
      newScript.type = script.type || 'text/javascript';
      newScript.innerHTML = script.code;
      loadedScripts[script.key] = newScript;
    } else if (script.src) {
      // Load script from external API endpoint
      fetch(script.src)
        .then((response) => response.json())
        .then((data) => {
          const newScript = document.createElement('script');
          newScript.type = data.type || 'text/javascript';
          newScript.innerHTML = data.code;
          loadedScripts[script.key] = newScript;
        })
        .catch((error) => {
          console.log(`Error loading script: ${error}`);
        });
    } else {
      // Handle missing essential properties
      console.log(`Missing essential properties in script object`);
    }
  });

  let executeScripts = () => {
    for (let i = 0; i < scripts.length; i++) {
      const script = loadedScripts[scripts[i].key];
      if (script) {
        document.body.appendChild(script);
      } else {
        console.log(`Missing script with key ${scripts[i].key}`);
      }
    }
  };

  // Load scripts asynchronously and only execute after all previous scripts have been fully executed to maintain the correct order of operations
  for (let i = 0; i < scripts.length; i++) {
    const script = loadedScripts[scripts[i].key];
    if (script) {
      loadingCount++;
      document.body.appendChild(script);
      script.onload = () => {
        loadingCount--;
        if (loadingCount === 0) {
          executeScripts();
        }
      };
    } else {
      console.log(`Missing script with key ${scripts[i].key}`);
    }
  }
};

