public static CompletableFuture<List<UserProfile>> fetchAndCacheProfiles(List<String> userIds, List<ApiClient> apiClients, CacheManager cacheManager) {
    // Validate input parameters
    if (userIds == null || apiClients == null || cacheManager == null) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    // Create a list to store the fetched profiles
    List<UserProfile> profiles = new ArrayList<>();

    // Iterate over the user IDs and API clients, fetching and caching each profile asynchronously
    for (int i = 0; i < userIds.size(); i++) {
        String userId = userIds.get(i);
        ApiClient apiClient = apiClients.get(i);

        // Fetch the profile from the API client
        CompletableFuture<UserProfile> future = apiClient.fetchProfile(userId);

        // Cache the profile if it was fetched successfully
        future.whenComplete((profile, error) -> {
            if (error == null && profile != null) {
                cacheManager.cacheProfile(userId, profile);
                profiles.add(profile);
            } else {
                log.warn("Failed to fetch profile for user ID {}", userId);
            }
        });
    }

    // Return the list of fetched profiles
    return CompletableFuture.completedFuture(profiles);
}
