#define MAX_LOG_FILE_SIZE 1024 * 1024 * 1024 // 1 GB

// Define the log file name prefix and suffix
#define LOG_FILE_PREFIX "encryption_"
#define LOG_FILE_SUFFIX ".log"

// Define the encryption key length in bits
