LOG_ROTATION_SETTINGS *log_rotation_settings;

// Define the function to encrypt a file
void encrypt_file(FILE *input_file, FILE *output_file) {
  // Initialize the encryption key and IV
  unsigned char key[KEY_LENGTH / 8];
  unsigned char iv[AES_BLOCK_SIZE];
  EVP_BytesToKey(cipher_option, mode_option, key, iv, KEY_LENGTH);

  // Encrypt the file using the OpenSSL library
  EVP_CIPHER_CTX *ctx;
  int encrypted_size = 0;
  if (!EVP_EncryptInit_ex(ctx, cipher_option, NULL, key, iv)) {
    printf("Error initializing encryption context\n");
    return;
  }
  if (!EVP_EncryptUpdate(ctx, output_file, &encrypted_size, input_file, BUFSIZ)) {
    printf("Error encrypting file\n");
    return;
  }
}

// Define the function to decrypt a file
void decrypt_file(FILE *input_file, FILE *output_file) {
  // Initialize the encryption key and IV
  unsigned char key[KEY_LENGTH / 8];
  unsigned char iv[AES_BLOCK_SIZE];
  EVP_BytesToKey(cipher_option, mode_option, key, iv, KEY_LENGTH);

  // Decrypt the file using the OpenSSL library
  EVP_CIPHER_CTX *ctx;
  int decrypted_size = 0;
  if (!EVP_DecryptInit_ex(ctx, cipher_option, NULL, key, iv)) {
    printf("Error initializing decryption context\n");
    return;
  }
  if (!EVP_DecryptUpdate(ctx, output_file, &decrypted_size, input_file, BUFSIZ)) {
    printf("Error decrypting file\n");
    return;
  }
}

