  unsigned char key[KEY_LENGTH / 8];
  unsigned char iv[AES_BLOCK_SIZE];
  EVP_BytesToKey(cipher_option, mode_option, key, iv, KEY_LENGTH);

  // Encrypt/decrypt the input files and write the output to the corresponding files
  int encrypted_size = 0;
  int decrypted_size = 0;
  for (i = 0; i < argc - 1; i++) {
    if (!strcmp(argv[2], "encrypt")) {
      // Encrypt the input file using the OpenSSL library
      encrypt_file(input_file_list[i], output_tuple_list[i]);
      // Update the encryption key and IV for each thread
      EVP_EncryptUpdate(ctx, key, iv);
    } else if (!strcmp(argv[2], "decrypt")) {
      // Decrypt the input file using the OpenSSL library
      decrypt_file(input_file_list[i], output_tuple_list[i]);
      // Update the encryption key and IV for each thread
      EVP_DecryptUpdate(ctx, key, iv);
    } else {
      printf("Invalid command\n");
      exit(-1);
    }
  }

  // Close all open files and free memory
  for (i = 0; i < argc - 1; i++) {
    fclose(input_file_list[i]);
    fclose(output_tuple_list[i]);
  }
  return 0;
}

