class Program
{
    static void Main(string[] args)
    {
        // Load configuration settings from XML file
        XmlDocument config = new XmlDocument();
        config.Load("config.xml");

        // Validate configuration settings
        int tileSize = int.Parse(config.SelectSingleNode("/configuration/tile_size").InnerText);
        int worldWidth = int.Parse(config.SelectSingleNode("/configuration/world_width").InnerText);
        int worldHeight = int.Parse(config.SelectSingleNode("/configuration/world_height").InnerText);
        int cameraSpeed = int.Parse(config.SelectSingleNode("/configuration/camera_speed").InnerText);

        if (tileSize <= 0 || worldWidth <= 0 || worldHeight <= 0 || cameraSpeed <= 0)
        {
            Console.WriteLine("Invalid configuration settings");
            return;
        }

        // Start the service with a random delay between starts
        Random rng = new Random();
        int startDelay = rng.Next(1, 60);
        Thread.Sleep(startDelay * 1000);

        while (true)
        {
            Console.WriteLine("Starting service...");

            // Perform some task using the configuration settings
            for (int i = 0; i < cameraSpeed; i++)
            {
                Console.WriteLine($"Taking a picture of the world, zoom level {i}");
                Thread.Sleep(500);
            }

            // Stop the service with a random delay between stops
            int stopDelay = rng.Next(1, 60);
            Thread.Sleep(stopDelay * 1000);

            Console.WriteLine("Stopping service...");
        }
    }
}
