                throw new InvalidOperationException($"Site with name '{siteName}' already exists");
            }

            // Create a new web application instance and add it to the list of managed sites
            WebApplication webApp = new WebApplication(_directoryPath, siteName);
            _webApplications.Add(webApp);
            _webApplicationMap[siteName] = webApp;
        }

        public void RemoveSite(string siteName)
        {
            // Validate site name
            if (string.IsNullOrEmpty(siteName))
            {
                throw new ArgumentException("Site name cannot be null or empty", nameof(siteName));
            }
            else if (!ValidateSiteName(siteName))
            {
                throw new ArgumentException($"Invalid site name: {siteName}", nameof(siteName));
            }

            // Check for existing site with the same name
            if (!_webApplicationMap.ContainsKey(siteName))
            {
                throw new InvalidOperationException($"Site with name '{siteName}' does not exist");
            }

            // Remove the web application instance from the list of managed sites
            WebApplication webApp = _webApplicationMap[siteName];
            _webApplications.Remove(webApp);
            _webApplicationMap.Remove(siteName);
        }

        public void StartSite(string siteName)
        {
            // Validate site name
            if (string.IsNullOrEmpty(siteName))
            {
                throw new ArgumentException("Site name cannot be null or empty", nameof(siteName));
            }
            else if (!ValidateSiteName(siteName))
            {
                throw new ArgumentException($"Invalid site name: {siteName}", nameof(siteName));
            }

            // Check for existing site with the same name
            if (!_webApplicationMap.ContainsKey(siteName))
            {
                throw new InvalidOperationException($"Site with name '{siteName}' does not exist");
            }

            // Start the web application instance
            WebApplication webApp = _webApplicationMap[siteName];
            webApp.Start();
        }

        public void StopSite(string siteName)
        {
            // Validate site name
            if (string.IsNullOrEmpty(siteName))
            {
                throw new ArgumentException("Site name cannot be null or empty", nameof(siteName));
            }
            else if (!ValidateSiteName(siteName))
            {
                throw new ArgumentException($"Invalid site name: {siteName}", nameof(siteName));
            }

            // Check for existing site with the same name
            if (!_webApplicationMap.ContainsKey(siteName))
            {
                throw new InvalidOperationException($"Site with name '{siteName}' does not exist");
            }

            // Stop the web application instance
            WebApplication webApp = _webApplicationMap[siteName];
            webApp.Stop();
        }

        public void UpdateConfiguration(string siteName, XElement configuration)
        {
            // Validate site name and configuration
            if (string.IsNullOrEmpty(siteName))
            {
                throw new ArgumentException("Site name cannot be null or empty", nameof(siteName));
            }
            else if (!ValidateSiteName(siteName))
            {
                throw new ArgumentException($"Invalid site name: {siteName}", nameof(siteName));
            }
            else if (configuration == null)
            {
                throw new ArgumentNullException(nameof(configuration), "Configuration cannot be null");
            }

            // Check for existing site with the same name
            if (!_webApplicationMap.ContainsKey(siteName))
            {
                throw new InvalidOperationException($"Site with name '{siteName}' does not exist");
            }

            // Update the configuration of the web application instance
            WebApplication webApp = _webApplicationMap[siteName];
            webApp.UpdateConfiguration(configuration);
        }

        public void LogMessage(string message)
        {
            // Validate message
            if (message == null)
            {
                throw new ArgumentNullException(nameof(message), "Message cannot be null");
            }

            // Log the message
            Console.WriteLine($"{DateTime.Now:yyyy-MM-dd HH:mm:ss} - {message}");
        }

        private bool ValidateSiteName(string siteName)
        {
            if (string.IsNullOrEmpty(siteName))
            {
                return false;
            }
            else if (siteName.Length > 32)
            {
                return false;
            }
            else if (!char.IsLetter(siteName[0]))
            {
                return false;
            }
            else
            {
                for (int i = 1; i < siteName.Length; i++)
                {
                    if (!char.IsLetterOrDigit(siteName[i]) && siteName[i] != '-')
                    {
                        return false;
                    }
                }
            }

            return true;
        }
    }
}

