package com.example;

import java.net.*;
import java.util.concurrent.*;
import javax.xml.bind.*;
import org.w3c.dom.*;

public class WebSocketConfigParser {
  private static final String CONFIG_URL = "https://api.example.com/websocket-config";
  private static final int DEFAULT_SERVER_PORT = 80;
  private static final String DEFAULT_ALLOWED_ORIGINS = "*";
  private static final int DEFAULT_MAX_CONNECTIONS = 1024;
  private static final long DEFAULT_TIMEOUT = 30L;
  private static final String[] DEFAULT_CIPHER_SUITES = {"TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384"};

  public static WebSocketConfig parseWebSocketConfig(String url) throws MalformedURLException, JAXBException {
    URL configUrl = new URL(url);
    HttpURLConnection conn = (HttpURLConnection) configUrl.openConnection();
    conn.setRequestMethod("GET");
    conn.setDoOutput(true);
    conn.connect();

    if (conn.getResponseCode() != 200) {
      throw new RuntimeException("Failed to fetch WebSocket configuration: " + conn.getResponseMessage());
    }

    DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
    Document doc = factory.parse(conn.getInputStream());

    Node serverPortNode = doc.getElementsByTagName("server-port").item(0).getTextContent();
    int serverPort = (serverPortNode != null) ? Integer.parseInt(serverPortNode) : DEFAULT_SERVER_PORT;

    Node allowedOriginsNode = doc.getElementsByTagName("allowed-origins").item(0).getTextContent();
    String[] allowedOrigins = (allowedOriginsNode != null) ? allowedOriginsNode.split(",") : new String[]{DEFAULT_ALLOWED_ORIGINS};

    Node maxConnectionsNode = doc.getElementsByTagName("max-connections").item(0).getTextContent();
    int maxConnections = (maxConnectionsNode != null) ? Integer.parseInt(maxConnectionsNode) : DEFAULT_MAX_CONNECTIONS;

    Node timeoutNode = doc.getElementsByTagName("timeout").item(0).getTextContent();
    long timeout = (timeoutNode != null) ? Long.parseLong(timeoutNode) : DEFAULT_TIMEOUT;

    Node cipherSuiteDetailsNode = doc.getElementsByTagName("cipher-suite-details").item(0).getTextContent();
    String[] cipherSuites = (cipherSuiteDetailsNode != null) ? cipherSuiteDetailsNode.split(",") : DEFAULT_CIPHER_SUITES;

    Node sslCertPathNode = doc.getElementsByTagName("ssl-cert-path").item(0).getTextContent();
    String sslCertPath = (sslCertPathNode != null) ? sslCertPathNode : null;

    Node sslKeyPathNode = doc.getElementsByTagName("ssl-key-path").item(0).getTextContent();
    String sslKeyPath = (sslKeyPathNode != null) ? sslKeyPathNode : null;

    Node heartbeatIntervalNode = doc.getElementsByTagName("heartbeat-interval").item(0).getTextContent();
    long heartbeatInterval = (heartbeatIntervalNode != null) ? Long.parseLong(heartbeatIntervalNode) : 0L;

    return new WebSocketConfig(serverPort, allowedOrigins, maxConnections, timeout, cipherSuites, sslCertPath, sslKeyPath, heartbeatInterval);
  }

  public static class WebSocketConfig {
    private final int serverPort;
    private final String[] allowedOrigins;
    private final int maxConnections;
    private final long timeout;
    private final String[] cipherSuites;
    private final String sslCertPath;
    private final String sslKeyPath;
    private final long heartbeatInterval;

    public WebSocketConfig(int serverPort, String[] allowedOrigins, int maxConnections, long timeout, String[] cipherSuites, String sslCertPath, String sslKeyPath, long heartbeatInterval) {
      this.serverPort = serverPort;
      this.allowedOrigins = allowedOrigins;
      this.maxConnections = maxConnections;
      this.timeout = timeout;
      this.cipherSuites = cipherSuites;
      this.sslCertPath = sslCertPath;
      this.sslKeyPath = sslKeyPath;
      this.heartbeatInterval = heartbeatInterval;
    }
  }
}
```
This code uses the `javax.xml.bind` package to parse an XML file and extract the necessary configuration settings for a WebSocket server. The XML file is fetched from a remote URL using HTTPS, and the response is validated for correctness and handled gracefully in case of errors or invalid data.

The program also includes a `WebSocketConfig` class that represents the configuration settings for a WebSocket server, with fields for `serverPort`, `allowedOrigins`, `maxConnections`, `timeout`, `cipherSuites`, `sslCertPath`, `sslKeyPath`, and `heartbeatInterval`. The `parseWebSocketConfig` method returns an instance of this class after extracting the necessary configuration settings from the XML file.

