import java.io.File;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class FileProcessor {
    private static final int THREAD_POOL_SIZE = 10; // adjust as needed
    private static final ExecutorService executor = Executors.newFixedThreadPool(THREAD_POOL_SIZE);

    public static void processFileBatchWithValidationAndMetadata(String inputDirectory, String outputDirectory, List<Rule> validationRules, MetadataExtractionService metadataService) {
        // Dynamically load and instantiate validation rule classes from the provided validation rules list using reflection
        List<ValidationRule> loadedRules = new ArrayList<>();
        for (Rule rule : validationRules) {
            try {
                Class<? extends ValidationRule> ruleClass = (Class<? extends ValidationRule>) Class.forName(rule.getClassName());
                ValidationRule instance = ruleClass.newInstance();
                loadedRules.add(instance);
            } catch (ClassNotFoundException | InstantiationException | IllegalAccessException e) {
                // handle exception gracefully
            }
        }

        // Process files in parallel using a thread pool to manage the concurrency
        File[] inputFiles = new File(inputDirectory).listFiles();
        List<FileProcessingTask> tasks = new ArrayList<>();
        for (File file : inputFiles) {
            ValidationRule[] rulesToApply = loadedRules.toArray(new ValidationRule[0]);
            MetadataExtractionService metadataServiceInstance = metadataService; // avoid creating a new instance every time
            FileProcessingTask task = new FileProcessingTask(file, rulesToApply, metadataServiceInstance);
            tasks.add(task);
        }

        executor.invokeAll(tasks);
    }
}

class FileProcessingTask implements Callable<Void> {
    private final File file;
    private final ValidationRule[] rulesToApply;
    private final MetadataExtractionService metadataServiceInstance;

    public FileProcessingTask(File file, ValidationRule[] rulesToApply, MetadataExtractionService metadataServiceInstance) {
        this.file = file;
        this.rulesToApply = rulesToApply;
        this.metadataServiceInstance = metadataServiceInstance;
    }

    @Override
    public Void call() throws Exception {
        // Validate each file against all the loaded validation rules and extract metadata
        for (ValidationRule rule : rulesToApply) {
            try {
                if (!rule.validate(file)) {
                    System.out.println("File " + file.getName() + " failed validation with rule " + rule.getClass().getSimpleName());
                    continue;
                }
                Map<String, String> metadata = metadataServiceInstance.extractMetadata(file);
                if (metadata != null) {
                    System.out.println("File " + file.getName() + " extracted metadata: " + metadata);
                } else {
                    System.out.println("File " + file.getName() + " failed metadata extraction with rule " + rule.getClass().getSimpleName());
                }
            } catch (Exception e) {
                // handle exception gracefully
            }
        }
        return null;
    }
}
