namespace CustomRandomGenerator
{
    public static class RandomGenerator
    {
        private const int DefaultSeed = 1234567890;
        private const int DefaultMinRangeLimit = -100;
        private const int DefaultMaxRangeLimit = 100;
        private const bool DefaultInclusiveRange = false;
        private const bool DefaultUseCustomDistribution = false;
        private const string CustomDistributionFunction = "";

        private static int _seed = DefaultSeed;
        private static int _minRangeLimit = DefaultMinRangeLimit;
        private static int _maxRangeLimit = DefaultMaxRangeLimit;
        private static bool _inclusiveRange = DefaultInclusiveRange;
        private static bool _useCustomDistribution = DefaultUseCustomDistribution;

        public static void CustomRange(int min, int max, bool inclusive)
        {
            // Validate input parameters
            if (min < 0 || max <= min)
            {
                throw new ArgumentException("Invalid range limits.");
            }

            _minRangeLimit = min;
            _maxRangeLimit = max;
            _inclusiveRange = inclusive;
        }

        public static void SeededRandom(int seed)
        {
            // Validate input parameter
            if (seed < 0)
            {
                throw new ArgumentException("Invalid seed value.");
            }

            _seed = seed;
        }

        public static int GenerateRandomValue()
        {
            // Use UnityEngine.Random.Range to generate random values based on the current range limits and inclusion setting
            int randomValue = UnityEngine.Random.Range(_minRangeLimit, _maxRangeLimit);

            // If a custom distribution function is set, use it to transform the generated value
            if (_useCustomDistribution)
            {
                randomValue = CustomDistributionFunction(randomValue);
            }

            return randomValue;
        }

