public static class AesGcmEncryption
{
    private const int KEY_SIZE = 256; // Size of the encryption key in bits
    private const int NONCE_LENGTH = 12; // Length of the nonce in bytes
    private const int TAG_LENGTH = 16; // Length of the authentication tag in bytes
    private const string KEY_MANAGEMENT_SERVICE_URL = "https://key-management.example.com"; // URL of the external key management service

    public static async Task<byte[]> EncryptAsync(string data, string aad, CancellationToken cancellationToken)
    {
        using var aesGcm = new AesGcm(KEY_SIZE); // Create an instance of the AES-GCM algorithm
        var keyBytes = await GetEncryptionKeyAsync(cancellationToken); // Retrieve the encryption key from the external service
        var nonce = CryptoRandom.CreateRandomByteArray(NONCE_LENGTH); // Generate a random nonce for the encryption process
        var ciphertext = aesGcm.Encrypt(keyBytes, data, aad, nonce, TAG_LENGTH); // Encrypt the data using AES-GCM
        return ciphertext;
    }

    public static async Task<byte[]> DecryptAsync(string data, string aad, CancellationToken cancellationToken)
    {
        using var aesGcm = new AesGcm(KEY_SIZE); // Create an instance of the AES-GCM algorithm
        var keyBytes = await GetEncryptionKeyAsync(cancellationToken); // Retrieve the encryption key from the external service
        var nonce = CryptoRandom.CreateRandomByteArray(NONCE_LENGTH); // Generate a random nonce for the decryption process
        var plaintext = aesGcm.Decrypt(keyBytes, data, aad, nonce, TAG_LENGTH); // Decrypt the data using AES-GCM
        return plaintext;
    }

    private static async Task<byte[]> GetEncryptionKeyAsync(CancellationToken cancellationToken)
    {
        var keyManagementService = new KeyManagementServiceClient(); // Create a client for the external key management service
        try
        {
            return await keyManagementService.GetKeyAsync(KEY_MANAGEMENT_SERVICE_URL, cancellationToken); // Retrieve the encryption key from the external service
        }
        catch (Exception ex)
        {
            var errorMessage = $"Error retrieving encryption key from external service: {ex.Message}"; // Log an error message if there was a problem retrieving the key
            Console.WriteLine(errorMessage);
            return null;
        }
    }
}

