namespace DynamicXmlManager
{
    public class XmlManager
    {
        private readonly Dictionary<string, XmlDocument> _documents = new Dictionary<string, XmlDocument>();
        private readonly ILogger _logger;

        public XmlManager(ILogger logger)
        {
            _logger = logger;
        }

        public void ParseAndValidateXml(string xml, string xsdSchema)
        {
            try
            {
                var schemaSet = new XmlSchemaSet();
                schemaSet.Add(string.Empty, new XmlTextReader(new StringReader(xsdSchema)));
                schemaSet.Compile();

                var xmlDoc = new XmlDocument();
                xmlDoc.LoadXml(xml);
                xmlDoc.Schemas.Add(schemaSet);

                foreach (var error in xmlDoc.GetErrors())
                {
                    _logger.LogError($"XML validation error: {error}");
                }
            }
            catch (Exception ex)
            {
                _logger.LogError($"Failed to parse and validate XML document: {ex}");
                throw;
            }
        }

        public XmlElement GetFirstElement(string xPathQuery, string documentName)
        {
            try
            {
                var xmlDoc = GetDocument(documentName);
                var navigator = xmlDoc.CreateNavigator();
                var node = navigator.SelectSingleNode(xPathQuery);

                if (node == null)
                {
                    _logger.LogWarning($"No element found for XPath query '{xPathQuery}' in document '{documentName}'");
                    throw new Exception("No elements found");
                }

                return node as XmlElement;
            }
            catch (Exception ex)
            {
                _logger.LogError($"Failed to get first element for XPath query '{xPathQuery}' in document '{documentName}': {ex}");
                throw;
            }
        }

        public void CacheDocument(string documentName, XmlDocument xmlDoc)
        {
            try
            {
                _documents[documentName] = xmlDoc;
            }
            catch (Exception ex)
            {
                _logger.LogError($"Failed to cache document '{documentName}': {ex}");
                throw;
            }
        }

        public XmlDocument GetCachedDocument(string documentName)
        {
            try
            {
                return _documents[documentName];
            }
            catch (Exception ex)
            {
                _logger.LogError($"Failed to get cached document '{documentName}': {ex}");
                throw;
            }
        }

        public void InvalidateCache(string documentName)
        {
            try
            {
                if (_documents.ContainsKey(documentName))
                {
                    _documents.Remove(documentName);
                }
            }
            catch (Exception ex)
            {
                _logger.LogError($"Failed to invalidate cache for document '{documentName}': {ex}");
                throw;
            }
        }

        public void UpdateCacheFromExternalSource(string documentName, string externalUrl)
        {
            try
            {
                var xmlDoc = new XmlDocument();
                xmlDoc.Load(externalUrl);
                CacheDocument(documentName, xmlDoc);
            }
            catch (Exception ex)
            {
                _logger.LogError($"Failed to update cache for document '{documentName}' from external source '{externalUrl}': {ex}");
                throw;
            }
        }

        public void ConvertToInMemoryRepresentation(string documentName)
        {
            try
            {
                var xmlDoc = GetDocument(documentName);
                var navigator = xmlDoc.CreateNavigator();
                var fragment = navigator.SelectSingleNode("/*");

                // TODO: convert the XmlDocument to an in-memory representation (e.g., XML fragments)
            }
            catch (Exception ex)
            {
                _logger.LogError($"Failed to convert document '{documentName}' to an in-memory representation: {ex}");
                throw;
            }
        }

        private XmlDocument GetDocument(string documentName)
        {
            try
            {
                if (_documents.ContainsKey(documentName))
                {
                    return _documents[documentName];
                }
                else
                {
                    throw new Exception($"No document found with name '{documentName}'");
                }
            }
            catch (Exception ex)
            {
                _logger.LogError($"Failed to get document '{documentName}': {ex}");
                throw;
            }
        }
    }
}
