import json
from typing import Dict, List, Union
from random import randint
from hashlib import sha256

class JSONParser:
    def __init__(self):
        self.factory_registry = {}

    def register_factory(self, id: str, factory_func: callable) -> None:
        self.factory_registry[id] = factory_func

    def create_instance(self, id: str, data: dict) -> object:
        if id not in self.factory_registry:
            raise ValueError(f"No such factory function registered for ID '{id}'")
        return self.factory_registry[id](data)

    def parse_json(self, json_str: str) -> Union[dict, list]:
        try:
            return json.loads(json_str)
        except ValueError as e:
            print(f"Failed to parse JSON: {e}")
            return {}

    def serialize_json(self, data: dict or list) -> str:
        try:
            return json.dumps(data)
        except ValueError as e:
            print(f"Failed to serialize JSON: {e}")
            return ""

class CircularDependencyDetector:
    def __init__(self, max_depth: int = 10):
        self.max_depth = max_depth
        self.visited = set()

    def detect(self, data: dict or list) -> bool:
        if isinstance(data, dict):
            for key in data:
                if self._detect(key, 0):
                    return True
            return False
        elif isinstance(data, list):
            for item in data:
                if self.detect(item):
                    return True
            return False
        else:
            raise ValueError("Invalid data type")

    def _detect(self, key: str, depth: int) -> bool:
        if key in self.visited:
            return True
        self.visited.add(key)
        if depth >= self.max_depth:
            return False
        if isinstance(data[key], dict):
            for subkey in data[key]:
                if self._detect(subkey, depth + 1):
                    return True
        elif isinstance(data[key], list):
            for item in data[key]:
                if self.detect(item):
                    return True
        return False

class DynamicLoader:
    def __init__(self, file_paths: List[str]):
        self.file_paths = file_paths
        self.factory_registry = {}

    def register_factory(self, id: str, factory_func: callable) -> None:
        self.factory_registry[id] = factory_func

    async def load_files(self):
        for file_path in self.file_paths:
            try:
                with open(file_path, "r") as f:
                    data = json.load(f)
                    if isinstance(data, dict):
                        for key in data:
                            if key not in self.factory_registry:
                                raise ValueError(f"No such factory function registered for ID '{key}'")
                            self.factory_registry[key](data[key])
                    elif isinstance(data, list):
                        for item in data:
                            if isinstance(item, dict) and "id" in item:
                                if item["id"] not in self.factory_registry:
                                    raise ValueError(f"No such factory function registered for ID '{item['id']}'")
                                self.factory_registry[item["id"]](item)
            except ValueError as e:
                print(f"Failed to load file {file_path}: {e}")
            except FileNotFoundError as e:
                print(f"File not found: {e}")
            except Exception as e:
                print(f"Unknown error while loading file {file_path}: {e}")

    def create_instance(self, id: str, data: dict) -> object:
        if id not in self.factory_registry:
            raise ValueError(f"No such factory function registered for ID '{id}'")
        return self.factory_registry[id](data)

class RandomStringGenerator:
    def generate_random_string(self, byte_array: bytes) -> str:
        random_bytes = randint(0, 256)
        for i in range(random_bytes):
            random_char = chr(randint(97, 122))
            byte_array.append(ord(random_char))
        return "".join(chr(x) for x in byte_array)

class PasswordHasher:
    def hash_password(self, password: str) -> bytes:
        salt = b"salt1234567890"
        return sha256((password + salt).encode()).digest()

class ForwardListManipulator:
    def insert_after(self, forward_list: list, key: str, value: str, position: int = 0) -> None:
        if position < 0 or position > len(forward_list):
            raise ValueError("Invalid position index")
        for i in range(position, len(forward_list)):
            forward_list[i] = forward_list[i + 1]
        forward_list[len(forward_list)] = value

class DataManager:
    def __init__(self):
        self.data = []

    def add_item(self, item: dict) -> None:
        self.data.append(item)

    def get_items(self) -> list:
        return self.data

class LoggingService:
    def log(self, message: str) -> None:
        print(message)

class DynamicApplication:
    def __init__(self):
        self.loader = DynamicLoader([])
        self.parser = JSONParser()
        self.hasher = PasswordHasher()
        self.string_generator = RandomStringGenerator()
        self.logger = LoggingService()
        self.manipulator = ForwardListManipulator()
        self.manager = DataManager()
        self.loader.register_factory("user", self.parser.create_instance)
        self.loader.register_factory("item", self.parser.create_instance)
        self.logger.log("Application initialized")

    def load_files(self, file_paths: List[str]) -> None:
        self.loader.load_files(file_paths)

    def hash_passwords(self) -> None:
        for user in self.manager.get_items():
            if "password" in user:
                password = user["password"]
                salted_password = self.hasher.hash_password(password)
                user["password"] = salted_password

    def generate_random_strings(self) -> None:
        for item in self.manager.get_items():
            if "id" in item and "description" in item:
                description = item["description"]
                random_string = self.string_generator.generate_random_string(description.encode())
                item["description"] = random_string

    def manipulate_forward_lists(self) -> None:
        for user in self.manager.get_items():
            if "forwardList" in user and isinstance(user["forwardList"], list):
                key = "name"
                value = "John Doe"
                position = 0
                self.manipulator.insert_after(user["forwardList"], key, value, position)

    def log_data(self) -> None:
        for user in self.manager.get_items():
            if "name" in user and isinstance(user["name"], str):
                name = user["name"]
                self.logger.log(f"User {name} loaded")
            elif "description" in user and isinstance(user["description"], str):
                description = user["description"]
                self.logger.log(f"Item {description} loaded")

if __name__ == "__main__":
    app = DynamicApplication()
    file_paths = ["path/to/file1", "path/to/file2"]
    app.load_files(file_paths)
    app.hash_passwords()
    app.generate_random_strings()
    app.manipulate_forward_lists()
    app.log_data()

