using namespace std;

// Custom Node class to store integer key and string value
class Node {
public:
    int key;
    string value;

    Node(int k, string v) : key(k), value(v) {}
};

// Function to manage allocation, initialization, and serialization of dynamic array of custom Node objects
void manageNodes(vector<Node>& nodes, ifstream& configFile, map<string, int>& versionMap) {
    // Initialize mutex for thread safety
    mutex mtx;

    // Open configuration file and read key-value pairs
    rapidjson::Document doc;
    ifstream fin(configFile);
    string jsonStr((std::istreambuf_iterator<char>(fin)), std::istreambuf_iterator<char>());
    doc.Parse(jsonStr.c_str());
    if (doc.HasParseError()) {
        cout << "Error parsing JSON file" << endl;
        return;
    }

    // Iterate through key-value pairs and initialize nodes
    for (rapidjson::Value::ConstMemberIterator itr = doc.MemberBegin(); itr != doc.MemberEnd(); ++itr) {
        int key = stoi(itr->name.GetString());
        string value = itr->value.GetString();
        Node node(key, value);
        nodes.push_back(node);
    }

    // Update version map with latest version IDs
    for (int i = 0; i < nodes.size(); ++i) {
        versionMap[nodes[i].value] = i + 1;
    }

    // Serialize nodes to JSON format using RapidJSON library
    rapidjson::StringBuffer sb;
    rapidjson::Writer<rapidjson::StringBuffer> writer(sb);
    writer.StartObject();
    for (int i = 0; i < nodes.size(); ++i) {
        writer.Key("key");
        writer.Int(nodes[i].key);
        writer.Key("value");
        writer.String(nodes[i].value.c_str());
        writer.EndObject();
    }
    writer.EndArray();

    // Output serialized JSON to console
    cout << sb.GetString() << endl;
}

// Function to handle dynamic resizing of nodes array for memory optimization and performance
void resizeNodes(vector<Node>& nodes, int newSize) {
    mutex mtx;
    Node* newNodes = new Node[newSize];
    for (int i = 0; i < newSize; ++i) {
        newNodes[i] = nodes[i];
    }
    delete[] nodes;
    nodes = newNodes;
}

