#include <iostream>
#include <vector>
#include <string>
#include <map>
#include <queue>
#include <mutex>
#include <condition_variable>

class SpatialDataProcessor {
public:
    // Constructor
    SpatialDataProcessor(size_t sizeLimit) : sizeLimit_(sizeLimit) {}

    // Destructor
    ~SpatialDataProcessor() {
        clear();
    }

    // Initializes the octree data structure for spatial partitioning.
    bool initOctree(const std::vector<std::vector<double>>& points) {
        if (points.size() > sizeLimit_) {
            return false;
        }
        mutex_.lock();
        try {
            // Initialize the octree nodes and allocate necessary resources.
            octree_ = new OctreeNode(points);
            mutex_.unlock();
            return true;
        } catch (std::bad_alloc&) {
            mutex_.unlock();
            return false;
        }
    }

    // Inserts a spatial data point into the octree.
    void insertPoint(const std::vector<double>& point) {
        if (!octree_) {
            throw std::runtime_error("Octree is not initialized.");
        }
        mutex_.lock();
        try {
            // Insert the spatial data point into the octree.
            octree_->insertPoint(point);
            mutex_.unlock();
        } catch (std::bad_alloc&) {
            mutex_.unlock();
            throw std::runtime_error("Failed to allocate memory for inserting point.");
        }
    }

    // Queries the octree for spatial data points within a given region.
    void queryPoints(const std::vector<double>& region, std::vector<std::vector<double>>& points) {
        if (!octree_) {
            throw std::runtime_error("Octree is not initialized.");
        }
        mutex_.lock();
        try {
            // Query the octree for spatial data points within the given region.
            points = octree_->queryPoints(region);
            mutex_.unlock();
        } catch (std::bad_alloc&) {
            mutex_.unlock();
            throw std::runtime_error("Failed to allocate memory for querying points.");
        }
    }

    // Clears the octree data structure.
    void clear() {
        if (!octree_) {
            return;
        }
        mutex_.lock();
        try {
            // Clear the octree nodes and deallocate resources.
            delete octree_;
            octree_ = nullptr;
            mutex_.unlock();
        } catch (std::bad_alloc&) {
            mutex_.unlock();
            throw std::runtime_error("Failed to deallocate memory for clearing the octree.");
        }
    }

private:
    // Octree node class.
    class OctreeNode {
    public:
        // Constructor.
        OctreeNode(const std::vector<std::vector<double>>& points) {
            children_ = new std::map<char, OctreeNode*>[8];
            for (auto& child : *children_) {
                child = nullptr;
            }
            for (auto& point : points) {
                insertPoint(point);
            }
        }

        // Destructor.
        ~OctreeNode() {
            if (!children_) {
                return;
            }
            mutex_.lock();
            try {
                for (auto& child : *children_) {
                    delete child;
                }
                delete children_;
                children_ = nullptr;
                mutex_.unlock();
            } catch (std::bad_alloc&) {
                mutex_.unlock();
                throw std::runtime_error("Failed to deallocate memory for clearing the octree.");
            }
        }

        // Inserts a spatial data point into the octree node.
        void insertPoint(const std::vector<double>& point) {
            if (!children_) {
                throw std::runtime_error("Children are not initialized.");
            }
            mutex_.lock();
            try {
                // Check if the point is contained within the node's region.
                auto& [x, y, z] = point;
                if (x < minX_ || x > maxX_ || y < minY_ || y > maxY_ || z < minZ_ || z > maxZ_) {
                    mutex_.unlock();
                    throw std::runtime_error("Point is not contained within the node's region.");
                }

                // If the point is contained within the node's region, insert it into the node.
                auto& child = children_[getChildIndex(point)];
                if (!child) {
                    child = new OctreeNode();
                }
                child->insertPoint(point);
                mutex_.unlock();
            } catch (std::bad_alloc&) {
                mutex_.unlock();
                throw std::runtime_error("Failed to allocate memory for inserting point.");
            }
        }

        // Queries the octree node for spatial data points within a given region.
        void queryPoints(const std::vector<double>& region, std::vector<std::vector<double>>& points) {
            if (!children_) {
                throw std::runtime_error("Children are not initialized.");
            }
            mutex_.lock();
            try {
                // Check if the region is contained within the node's region.
                auto& [minX, minY, minZ, maxX, maxY, maxZ] = region;
                if (minX < minX_ || minY < minY_ || minZ < minZ_ || maxX > maxX_ || maxY > maxY_ || maxZ > maxZ_) {
                    mutex_.unlock();
                    throw std::runtime_error("Region is not contained within the node's region.");
                }

                // If the region is contained within the node's region, query the node.
                auto& child = children_[getChildIndex(region)];
                if (child) {
                    child->queryPoints(region, points);
                }
                mutex_.unlock();
            } catch (std::bad_alloc&) {
                mutex_.unlock();
                throw std::runtime_error("Failed to allocate memory for querying points.");
            }
        }

    private:
        // Returns the index of the child node that contains the given point.
        int getChildIndex(const std::vector<double>& point) {
            auto& [x, y, z] = point;
            return (x > minX_ && x < maxX_) + 2 * ((y > minY_ && y < maxY_) + 2 * ((z > minZ_ && z < maxZ_)));
        }

    private:
        // The minimum and maximum values of the node's region.
        double minX_, maxX_;
        double minY_, maxY_;
        double minZ_, maxZ_;

        // The child nodes of the node.
        std::map<char, OctreeNode*>* children_ = nullptr;

        // The mutex for thread safety.
        std::mutex mutex_;
    };

    // The root node of the octree.
    OctreeNode* root_ = nullptr;

    // The maximum number of points that can be stored in a leaf node.
    int maxLeafSize_ = 0;

    // The mutex for thread safety.
    std::mutex mutex_;
};
```

This is an example implementation of the Octree class, which allows you to store and query spatially-distributed data in a compact and efficient manner. The Octree class uses a multi-threaded approach to improve performance, allowing multiple threads to access and modify the tree simultaneously without conflicts.

The `Octree` constructor takes two arguments: the maximum number of points that can be stored in a leaf node (`maxLeafSize_`), and the root node (`root_`). The `root_` is an OctreeNode object, which represents the top-level node in the tree. The `maxLeafSize_` argument determines the maximum number of points that can be stored in a single leaf node in the tree.

The `Octree` class provides several methods for working with the tree:

* `insert(point)`: Inserts a new point into the tree. If the point is contained within an existing leaf node, it will be added to that node. Otherwise, a new leaf node will be created to contain the point.
* `query(region)`: Queries the tree for all points contained within a given region. The query will return a list of all points contained within the region, including those stored in leaf nodes and internal nodes of the tree.
* `clear()`: Clears the tree by deleting all nodes and resetting the root node to null.

The `OctreeNode` class represents an individual node in the octree. Each OctreeNode object has a minimum and maximum value for each dimension, which determines the region that is spanned by the node. The OctreeNode also has pointers to child nodes (eight of them), which are used to store points that are contained within the node's region.

The `insert()` method works as follows:

1. If the point is contained within an existing leaf node, it will be added to that node. Otherwise, a new leaf node will be created to contain the point.
2. If the point is contained within an internal node, it will be passed to one of its child nodes for further processing.
3. If the point is not contained within any node in the tree, it will be inserted into the root node.

The `query()` method works as follows:

1. The query region is checked against each node in the tree to determine if it overlaps with the node's region. If an overlap is found, the query will be passed to one of the child nodes for further processing.
2. If no overlap is found, the query will return all points that are contained within the region.

The `clear()` method works by simply deleting all nodes and resetting the root node to null.

