using System;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class PasswordService
{
    private readonly HttpClient _httpClient;
    private readonly string _apiUrl;
    private readonly string _apiKey;

    public PasswordService(HttpClient httpClient, string apiUrl, string apiKey)
    {
        _httpClient = httpClient;
        _apiUrl = apiUrl;
        _apiKey = apiKey;
    }

    public async Task<string> GetHashAsync(string password)
    {
        var hash = MD5.Create().ComputeHash(Encoding.UTF8.GetBytes(password));
        return BitConverter.ToString(hash).Replace("-", "").ToLower();
    }

    public async Task<bool> VerifyPasswordAsync(string password, string storedHash)
    {
        var computedHash = await GetHashAsync(password);
        return storedHash == computedHash;
    }

    public async Task<bool> StoreHashAsync(string password)
    {
        try
        {
            var hash = await GetHashAsync(password);
            var response = await _httpClient.PostAsync(_apiUrl, new StringContent($"{{ \"hash\": \"{hash}\" }}", Encoding.UTF8, "application/json"));
            if (response.IsSuccessStatusCode)
            {
                return true;
            }
            else
            {
                throw new Exception("Failed to store hash.");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error storing hash: {ex}");
            return false;
        }
    }
}
```
