#include <functional>
#include <memory>
#include <utility>

// Sandesh client library
#include "sandesh/sandesh.h"

// Load balancer API
#include "load_balancer/load_balancer.h"

// External authentication service
#include "oauth/oauth2.h"

// Cache eviction policy
#include "cache/lru_cache.h"

// Distributed tracing system
#include "tracing/distributed_tracing.h"

using namespace std;

namespace {
  // Global variable for the load balancer instance
  LoadBalancer<MetadataServer>* lb = nullptr;

  // Global variable for the cache instance
  LRUCache<string, MetadataResponse>* cache = nullptr;

  // Global variable for the distributed tracing system
  DistributedTracing* tracer = nullptr;
}

class SandeshClient {
 public:
  // Constructor
  SandeshClient(const string& server_url, const string& auth_token) {
    this->server_url = server_url;
    this->auth_token = auth_token;
  }

  // Destructor
  ~SandeshClient() {}

  // Fetch metadata from the remote server using HTTPS
  MetadataResponse fetchMetadata(const string& ip) {
    // Initialize the Sandesh client with the appropriate URL and authentication token
    sandesh::SandeshClient client(this->server_url, this->auth_token);

    // Set up custom session persistence and connection pooling
    SessionManager<MetadataServer>* sm = new SessionManager<MetadataServer>();
    ConnectionPool<MetadataServer>* cp = new ConnectionPool<MetadataServer>(sm);

    // Set up a test double for the InterfaceTable class
    TestDouble<InterfaceTable> td(new InterfaceTable());

    // Override the FindVmUuidFromMetadataIp function to simulate different network conditions and test edge cases
    td.overrideFunction("FindVmUuidFromMetadataIp", [](const string& ip) {
      // Simulate a slow network condition by sleeping for a random amount of time between 10 and 20 milliseconds
      this_thread::sleep_for(chrono::milliseconds(rand() % 10 + 10));

      // Simulate an edge case where the IP address is not found in the metadata server
      if (ip == "192.168.1.1") {
        return "";
      }

      // Return the VM UUID associated with the given IP address
      return ip + "_vm_uuid";
    });

    // Initialize the load balancer instance if it has not already been initialized
    if (!lb) {
      lb = new LoadBalancer<MetadataServer>(cp, sm);
    }

    // Initialize the cache instance if it has not already been initialized
    if (!cache) {
      cache = new LRUCache<string, MetadataResponse>();
    }

    // Initialize the distributed tracing system if it has not already been initialized
    if (!tracer) {
      tracer = new DistributedTracing(cp);
    }

    // Get a connection from the load balancer instance
    auto conn = lb->getConnection();

    // Set up a custom authentication handler for the connection
    auto auth_handler = make_unique<OAuth2Handler>(conn, this->auth_token);

    // Set up a custom cache handler for the connection
    auto cache_handler = make_unique<CacheHandler>(cache);

    // Set up a custom tracing handler for the connection
    auto tracing_handler = make_unique<DistributedTracingHandler>(tracer, conn);

    // Create a new request object with the appropriate URL and headers
    Request req(this->server_url + "/metadata/" + ip);
    req.setHeader("Content-Type", "application/json");
    req.setHeader("Authorization", this->auth_token);

    // Set up retry logic for failed requests, with exponential backoff and jitter
    int attempts = 0;
    while (attempts < 5) {
      try {
        auto res = client.sendRequest(req, auth_handler, cache_handler, tracing_handler);
        return res->getBody();
      } catch (const runtime_error& e) {
        // Log the error message and increment the attempts counter
        cerr << "Error: " << e.what() << endl;
        ++attempts;

        // Exponentially back off between attempts, with jitter to avoid overwhelming the server
        chrono::milliseconds delay(attempts * 100);
        this_thread::sleep_for(delay + chrono::milliseconds(rand() % (int)delay.count()));
      }
    }

    // Return an empty response if all attempts failed
    return {};
  }
};
