using System;
using System.Threading;
using System.Collections.Generic;
using System.Linq;

namespace AdvancedRandomGenerator
{
    public class RandomNumberGenerator
    {
        // Dynamic range management:
        private readonly object _rangeLock = new object();
        private Range<int> _range = new Range<int>(0, 1);
        private int _seed = 42;

        // Customizable random algorithms:
        private enum Algorithm { MersenneTwister, Xorshift }
        private readonly Dictionary<Algorithm, Random> _algorithms = new Dictionary<Algorithm, Random>();

        // External system integration:
        private readonly string _configUrl;

        // Resource management:
        private readonly int _maxRandomValuesPerThread = 1000;
        private readonly int _randomValueGenerationTimeout = 500;

        // Custom distribution functions:
        private readonly Dictionary<string, Func<double>> _customDistributions = new Dictionary<string, Func<double>>();

        public RandomNumberGenerator(string configUrl)
        {
            _configUrl = configUrl;

            // Initialize algorithms:
            _algorithms.Add(Algorithm.MersenneTwister, new MersenneTwister(_seed));
            _algorithms.Add(Algorithm.Xorshift, new Xorshift(_seed));
        }

        public int NextInt()
        {
            // Acquire lock on range limits:
            lock (_rangeLock)
            {
                // Generate random integer within current range limits:
                var value = _algorithms[Algorithm.MersenneTwister].Next(_range.Min, _range.Max + 1);
                return value;
            }
        }

        public double NextDouble()
        {
            // Acquire lock on range limits:
            lock (_rangeLock)
            {
                // Generate random double within current range limits:
                var value = _algorithms[Algorithm.MersenneTwister].NextDouble(_range.Min, _range.Max);
                return value;
            }
        }

        public void SetRange(int min, int max)
        {
            // Acquire lock on range limits:
            lock (_rangeLock)
            {
                // Update range limits:
                _range = new Range<int>(min, max);
            }
        }

        public void SetSeed(int seed)
        {
            // Acquire lock on seed value:
            lock (_seed)
            {
                // Update seed value:
                _seed = seed;

                // Update random number generator with new seed value:
                foreach (var algorithm in _algorithms.Values)
                {
                    algorithm.Seed(_seed);
                }
            }
        }

        public void SetAlgorithm(Algorithm algorithm)
        {
            // Acquire lock on selected algorithm:
            lock (_algorithms[algorithm])
            {
                // Update selected algorithm:
                _algorithms[algorithm].Seed(_seed);
            }
        }

        public void AddCustomDistribution(string name, Func<double> distribution)
        {
            // Acquire lock on custom distributions:
            lock (_customDistributions)
            {
                // Add new custom distribution:
                _customDistributions.Add(name, distribution);
            }
        }

        public void RemoveCustomDistribution(string name)
        {
            // Acquire lock on custom distributions:
            lock (_customDistributions)
            {
                // Remove existing custom distribution:
                _customDistributions.Remove(name);
            }
        }

        public double GetRandomValue(string distributionName)
        {
            if (distributionName == null || !_customDistributions.ContainsKey(distributionName))
            {
                throw new ArgumentException("Invalid distribution name");
            }

            // Acquire lock on custom distributions:
            lock (_customDistributions)
            {
                // Get random value using custom distribution:
                var value = _customDistributions[distributionName]();
                return value;
            }
        }

        public void Start()
        {
            // Acquire lock on range limits and seed value:
            lock (_rangeLock)
            {
                // Update random number generator with current range limits and seed value:
                foreach (var algorithm in _algorithms.Values)
                {
                    algorithm.Seed(_seed);
                }
            }
        }

        public void Stop()
        {
            // Acquire lock on range limits and seed value:
            lock (_rangeLock)
            {
                // Update random number generator with current range limits and seed value:
                foreach (var algorithm in _algorithms.Values)
                {
                    algorithm.Dispose();
                }
            }
        }
    }
}
