using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;

public class DynamicFileMetadataAnalyzer
{
    private readonly string _directoryPath;
    private readonly int _minimumFileSizeThreshold;
    private readonly int _maximumFileSizeThreshold;
    private readonly int _batchSize;
    private readonly Func<ProcessedMetadata, bool> _filterCallback;
    private readonly IEnumerable<string> _files;

    public DynamicFileMetadataAnalyzer(string directoryPath, int minimumFileSizeThreshold = 0, int maximumFileSizeThreshold = int.MaxValue, int batchSize = 100, Func<ProcessedMetadata, bool> filterCallback = null)
    {
        _directoryPath = directoryPath;
        _minimumFileSizeThreshold = minimumFileSizeThreshold;
        _maximumFileSizeThreshold = maximumFileSizeThreshold;
        _batchSize = batchSize;
        _filterCallback = filterCallback;
    }

    public async Task<IEnumerable<ProcessedMetadata>> AnalyzeAsync()
    {
        if (!Directory.Exists(_directoryPath))
        {
            throw new DirectoryNotFoundException($"The directory '{_directoryPath}' does not exist.");
        }

        var files = GetFiles().Where(f => f.Length >= _minimumFileSizeThreshold && f.Length <= _maximumFileSizeThreshold);
        if (_filterCallback != null)
        {
            files = files.Where(_filterCallback);
        }

        return await Task.WhenAll(files.Select(async file =>
        {
            var metadata = await GetMetadataAsync(file);
            return new ProcessedMetadata
            {
                FilePath = file,
                Size = metadata.Length,
                CreationDate = metadata.CreationTimeUtc,
                LastModifiedDate = metadata.LastWriteTimeUtc
            };
        }));
    }

    private IEnumerable<string> GetFiles()
    {
        return Directory.EnumerateFiles(_directoryPath, "*", SearchOption.TopDirectoryOnly);
    }

    private async Task<FileInfo> GetMetadataAsync(string filePath)
    {
        try
        {
            var metadata = new FileInfo(filePath);
            await metadata.RefreshAsync();
            return metadata;
        }
        catch (Exception ex)
        {
            // Log error
            throw new InvalidOperationException($"Failed to retrieve metadata for file '{filePath}'.", ex);
        }
    }
}
