#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>

// Structure for storing filtered transactions
typedef struct {
    int transaction_id;
    int weighted_sum;
} FilteredTransaction;

// Function to filter and collect states based on criteria
FilteredTransaction* filterAndCollectStates(int* states, int num_states, FSA* fsa, int last_state, time_t current_time, TransactionCriteria* criteria) {
    // Initialize variables
    int state_list_size = 0;
    FilteredTransaction* filtered_transactions = NULL;
    int max_weighted_sum = 0;
    int transaction_id = -1;

    // Depth-first search traversal of the FSA to collect states and filter transactions
    for (int i = 0; i < num_states; i++) {
        int state = states[i];
        if (!isStateValid(state)) continue;

        // Filter transactions based on criteria
        Transaction* transaction = getTransaction(state);
        while (transaction != NULL) {
            if (checkTransactionCriteria(transaction, criteria)) {
                int weighted_sum = calculateWeightedSum(transaction);
                if (weighted_sum > max_weighted_sum) {
                    max_weighted_sum = weighted_sum;
                    transaction_id = transaction->id;
                }
            }
            transaction = getNextTransaction(state);
        }

        // Add state to the filtered state list if it has filtered transactions
        if (transaction_id != -1) {
            FilteredTransaction* new_filtered_transactions = realloc(filtered_transactions, sizeof(FilteredTransaction) * (++state_list_size));
            if (new_filtered_transactions == NULL) return NULL;
            filtered_transactions = new_filtered_transactions;
            filtered_transactions[state_list_size - 1].transaction_id = transaction_id;
            filtered_transactions[state_list_size - 1].weighted_sum = max_weighted_sum;
        }
    }

    // Free dynamically allocated memory for the transaction records and update metrics
    free(filtered_transactions);

    return filtered_transactions;
}
