Here is an example of a Python function that efficiently converts temperatures between Celsius, Fahrenheit, and Kelvin, handling large datasets and providing real-time conversion capabilities:
```
def convert_temperature(temperature, source_scale, target_scale):
    # Handle edge cases
    if temperature is None or source_scale is None or target_scale is None:
        raise ValueError("Invalid input")

    # Convert temperatures to Kelvin
    kelvin = 273.15
    temperature += kelvin

    # Perform conversion based on source and target scales
    if source_scale == "C" and target_scale == "F":
        return (temperature - kelvin) * 9/5 + 32
    elif source_scale == "F" and target_scale == "C":
        return (temperature - 32) * 5/9 - kelvin
    elif source_scale == "K" and target_scale == "C":
        return temperature - kelvin
    elif source_scale == "C" and target_scale == "K":
        return temperature + kelvin
    else:
        raise ValueError("Unsupported conversion")
```
And here is an example of a Node.js application that integrates this temperature conversion service via an HTTP API, allowing external applications to make requests for temperature conversions:
```
const express = require("express");
const app = express();

// Set up caching mechanism
const cache = new Map();

app.get("/convert", (req, res) => {
    // Get input parameters from request
    const temperature = parseFloat(req.query.temperature);
    const source_scale = req.query.source_scale;
    const target_scale = req.query.target_scale;

    // Handle edge cases
    if (isNaN(temperature) || source_scale === null || target_scale === null) {
        res.status(400).send("Invalid input");
        return;
    }

    // Check cache for previously converted temperature
    const cached_temperature = cache.get(source_scale + "-" + target_scale);
    if (cached_temperature !== undefined) {
        res.status(200).send(cached_temperature);
        return;
    }

    // Perform conversion and store result in cache
    const converted_temperature = convert_temperature(temperature, source_scale, target_scale);
    cache.set(source_scale + "-" + target_scale, converted_temperature);

    res.status(200).send(converted_temperature);
});

app.listen(3000, () => {
    console.log("Temperature conversion service started on port 3000");
});
```
