const fs = require('fs');
const path = require('path');
const { spawn } = require('child_process');

// Load module metadata from a JSON file
function loadModuleMetadata(moduleDir) {
  const metadataPath = path.join(moduleDir, 'metadata.json');
  if (!fs.existsSync(metadataPath)) {
    throw new Error(`Metadata file not found: ${metadataPath}`);
  }
  return JSON.parse(fs.readFileSync(metadataPath));
}

// Dynamically load and execute modules in the specified directory
function executeModules(moduleDir) {
  const metadata = loadModuleMetadata(moduleDir);
  // Iterate over the modules and execute them in the correct order
  metadata.modules.forEach((module, index) => {
    // Check if the module has dependencies
    if (module.dependencies && module.dependencies.length > 0) {
      // Execute the dependent modules first
      for (const dependency of module.dependencies) {
        const depIndex = metadata.modules.findIndex(m => m.name === dependency);
        if (depIndex === -1) {
          throw new Error(`Dependency not found: ${dependency}`);
        }
        executeModules(metadata.modules[depIndex].path);
      }
    }
    // Execute the current module
    const modulePath = path.join(moduleDir, `${module.name}.js`);
    if (!fs.existsSync(modulePath)) {
      throw new Error(`Module not found: ${modulePath}`);
    }
    spawn('node', [modulePath], { stdio: 'inherit' });
  });
}

// Update module versions without restarting the application
function updateModules(moduleDir, version) {
  const metadata = loadModuleMetadata(moduleDir);
  metadata.modules.forEach((module) => {
    // Check if the module has a new version available
    if (module.version !== version) {
      // Update the module version
      module.version = version;
      // Save the updated metadata to disk
      fs.writeFileSync(path.join(moduleDir, 'metadata.json'), JSON.stringify(metadata));
    }
  });
}

// Monitor changes in the directory and automatically reload modules if there are updates
function monitorModules(moduleDir) {
  const watcher = fs.watch(moduleDir);
  watcher.on('change', (eventType, filename) => {
    // Check if a module has been updated or deleted
    if (filename && filename.endsWith('.js')) {
      console.log(`Module updated: ${filename}`);
      executeModules(moduleDir);
    } else if (!filename) {
      console.log('Module deleted');
    }
  });
}

// Main function to load and execute modules
function main(moduleDir, version) {
  try {
    // Load the module metadata from disk
    const metadata = loadModuleMetadata(moduleDir);
    // Execute the modules in the correct order based on their dependencies
    executeModules(moduleDir);
    // Update the module versions without restarting the application
    updateModules(moduleDir, version);
    // Monitor changes in the directory and automatically reload modules if there are updates
    monitorModules(moduleDir);
  } catch (error) {
    console.log(`Error: ${error.message}`);
  }
}

// Start the application with a specific module version
main('modules', '1.0.0');
