// Rust function for handling directory creation and environment variable setting
fn create_directory(name: &str) -> Result<(), String> {
    let env_var = os::getenv("DIR_PATH");
    if env_var.is_some() && !env_var.unwrap().is_empty() {
        return Err("Directory already exists".to_string());
    }

    fs::create_dir(name).map_err(|e| format!("Failed to create directory: {}", e))?;
    os::setenv("DIR_PATH", name);

    Ok(())
}
