import java.util.*;

public class ChatApplication {
    private static final String THIRD_PARTY_API_URL = "https://api.example.com";
    private static final String SESSION_STORAGE_KEY = "chat-session";

    public static void main(String[] args) {
        // Initialize third-party API client
        ThirdPartyApiClient apiClient = new ThirdPartyApiClient();

        // Initialize session storage
        SessionStorage sessionStorage = new SessionStorage();

        // Initialize message validation rules
        MessageValidationRules validationRules = new MessageValidationRules();

        while (true) {
            // Read input from user
            String input = readInput();

            // Validate input against validation rules
            if (!validationRules.validate(input)) {
                continue;
            }

            // Send message to third-party API
            try {
                apiClient.sendMessage(input);
            } catch (ApiException e) {
                System.out.println("Error sending message: " + e.getMessage());
                continue;
            }

            // Store session in storage for later retrieval
            sessionStorage.storeSession(input);
        }
    }

    private static String readInput() {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter message: ");
        return scanner.nextLine();
    }
}

class SessionStorage {
    private Map<String, String> sessions = new HashMap<>();

    public void storeSession(String input) {
        sessions.put(input, "");
    }

    public boolean hasSession(String sessionId) {
        return sessions.containsKey(sessionId);
    }

    public void removeSession(String sessionId) {
        sessions.remove(sessionId);
    }
}

class MessageValidationRules {
    private Map<String, List<String>> validationRules = new HashMap<>();

    public boolean validate(String input) {
        if (validationRules.containsKey("admin-encryption") && validationRules.get("admin-encryption").contains(input)) {
            // Require end-to-end encryption for messages sent by administrators
            return true;
        } else if (validationRules.containsKey("user-encryption") && validationRules.get("user-encryption").contains(input)) {
            // Do not require end-to-end encryption for regular users
            return false;
        }

        return true;
    }
}

class ThirdPartyApiClient {
    private String apiUrl = THIRD_PARTY_API_URL;

    public void sendMessage(String message) throws ApiException {
        // Send HTTP POST request to third-party API with message data
        HttpRequest request = new HttpRequest();
        request.setMethod("POST");
        request.setUrl(apiUrl);
        request.addHeader("Content-Type", "application/json");
        request.setBody(message);

        try {
            HttpResponse response = request.send();
            if (response.getStatusCode() == 200) {
                System.out.println("Message sent successfully!");
            } else {
                throw new ApiException(response.getStatusCode(), "Error sending message: " + response.getBody());
            }
        } catch (IOException e) {
            throw new ApiException(e);
        }
    }
}

class HttpRequest {
    private String method;
    private URL url;
    private Map<String, String> headers = new HashMap<>();
    private String body;

    public void setMethod(String method) {
        this.method = method;
    }

    public void setUrl(URL url) {
        this.url = url;
    }

    public void addHeader(String key, String value) {
        headers.put(key, value);
    }

    public void setBody(String body) {
        this.body = body;
    }

    public HttpResponse send() throws IOException {
        URLConnection connection = url.openConnection();
        for (Map.Entry<String, String> entry : headers.entrySet()) {
            connection.setRequestProperty(entry.getKey(), entry.getValue());
        }

        InputStream inputStream;
        if (body != null) {
            byte[] bodyBytes = body.getBytes();
            int length = bodyBytes.length;
            connection.setDoOutput(true);
            OutputStream outputStream = connection.getOutputStream();
            outputStream.write(bodyBytes, 0, length);
            inputStream = connection.getInputStream();
        } else {
            inputStream = connection.getInputStream();
        }

        String responseBody;
        if (connection instanceof HttpURLConnection) {
            int statusCode = ((HttpURLConnection) connection).getResponseCode();
            responseBody = IOUtils.toString(inputStream, StandardCharsets.UTF_8);
            return new HttpResponse(statusCode, responseBody);
        } else {
            throw new IOException("Unknown URL protocol");
        }
    }
}

class HttpResponse {
    private int statusCode;
    private String body;

    public HttpResponse(int statusCode, String body) {
        this.statusCode = statusCode;
        this.body = body;
    }

    public int getStatusCode() {
        return statusCode;
    }

    public String getBody() {
        return body;
    }
}

class ApiException extends Exception {
    private final int statusCode;

    public ApiException(int statusCode, String message) {
        super(message);
        this.statusCode = statusCode;
    }

    public ApiException(IOException e) {
        super(e);
    }
}
