async def process_sensor_data():
    # Set up asynchronous socket connections to all devices
    device_connections = {}
    for device in DEVICES:
        device_connections[device] = asyncio.create_connection((device['ip'], device['port']))

    while True:
        try:
            # Read sensor data from each device and handle retries, timeouts, and disconnections
            for device in DEVICES:
                response = await device_connections[device]['socket'].recv(1024)
                if response is not None:
                    data = json.loads(response)
                    process_data(data)
