```csharp
using System;
using System.Threading;
using UnityEngine;

public class AdvancedRandomGenerator : MonoBehaviour
{
    private static readonly SeedManager _seedManager = new SeedManager();

    public enum RangeType
    {
        Closed,
        Open,
        HalfOpen
    }

    public static float CustomRange(float min, float max, RangeType rangeType)
    {
        return (float)_seedManager.GetRandomValue(min, max, rangeType);
    }

    public static int CustomRange(int min, int max, RangeType rangeType)
    {
        return (int)_seedManager.GetRandomValue(min, max, rangeType);
    }

    private class SeedManager
    {
        private readonly object _syncRoot = new object();
        private int _seed;
        private bool _isSeeded;

        public void Seed()
        {
            lock (_syncRoot)
            {
                if (!_isSeeded)
                {
                    UnityEngine.Random.InitState(UnityEngine.Random.Range(int.MinValue, int.MaxValue));
                    _isSeeded = true;
                }
            }
        }

        public void Reset()
        {
            lock (_syncRoot)
            {
                _seed = UnityEngine.Random.Range(int.MinValue, int.MaxValue);
                _isSeeded = false;
            }
        }

        public float GetRandomValue(float min, float max, RangeType rangeType)
        {
            Seed();
            float randomValue = UnityEngine.Random.Range(min, max);
            if (rangeType == RangeType.Open && randomValue == min)
            {
                randomValue++;
            }
            else if (rangeType == RangeType.HalfOpen && randomValue <= min)
            {
                randomValue++;
            }
            return randomValue;
        }

        public int GetRandomValue(int min, int max, RangeType rangeType)
        {
            Seed();
            int randomValue = UnityEngine.Random.Range(min, max);
            if (rangeType == RangeType.Open && randomValue == min)
            {
                randomValue++;
            }
            else if (rangeType == RangeType.HalfOpen && randomValue <= min)
            {
                randomValue++;
            }
            return randomValue;
        }
    }
}
