import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.logging.Logger;
import javax.imageio.ImageIO;
import org.apache.commons.imaging.Imaging;

public class ImageDownloader {
  private static final Logger logger = Logger.getLogger(ImageDownloader.class.getName());

  private static final int MAX_DOWNLOAD_THREADS = 10;
  private static final int RETRY_COUNT = 3;
  private static final long BACKOFF_INTERVAL = 5000L; // 5 seconds
  private static final long TIMEOUT = 10000L; // 10 seconds

  public static void downloadImageResources(List<String> imageUrls) {
    ExecutorService executor = Executors.newFixedThreadPool(MAX_DOWNLOAD_THREADS);

    for (String imageUrl : imageUrls) {
      executor.execute(() -> {
        try {
          downloadImageResource(imageUrl);
        } catch (Exception e) {
          logger.log(Level.SEVERE, "Failed to download image: " + imageUrl, e);
        }
      });
    }

    executor.shutdown();

    try {
      executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
    } catch (InterruptedException e) {
      logger.log(Level.WARNING, "Interrupted while waiting for downloads to complete", e);
    }
  }

  private static void downloadImageResource(String imageUrl) throws Exception {
    boolean success = false;
    int retryCount = RETRY_COUNT;

    while (retryCount > 0 && !success) {
      try {
        URL url = new URL(imageUrl);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setConnectTimeout((int) TIMEOUT);
        connection.setReadTimeout((int) TIMEOUT);
        connection.connect();

        int responseCode = connection.getResponseCode();
        if (responseCode == 200) {
          InputStream inputStream = connection.getInputStream();
          byte[] imageData = IOUtils.toByteArray(inputStream, 4096);
          ImageIO.write(imageData, "jpg", new File("images/" + UUID.randomUUID() + ".jpg"));
          success = true;
        } else {
          logger.log(Level.SEVERE, "Failed to download image: " + imageUrl + ", response code: " + responseCode);
        }
      } catch (SocketTimeoutException e) {
        logger.log(Level.INFO, "Timed out while downloading image: " + imageUrl, e);
      } catch (IOException e) {
        if (retryCount > 0) {
          retryCount--;
          Thread.sleep(BACKOFF_INTERVAL);
        } else {
          throw new Exception("Failed to download image: " + imageUrl, e);
        }
      }
    }
  }
}
