using System;
using System.Collections.Generic;
using System.Data;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using MySql.Data.MySqlClient;

public class DynamicDatabaseConnectionManager {
  private static readonly Logger logger = LogManager.GetLogger(typeof(DynamicDatabaseConnectionManager));

  private readonly string _connectionString;
  private readonly int _poolSize;
  private readonly int _maxIdleConnections;

  public DynamicDatabaseConnectionManager(IConfiguration configuration) {
    _connectionString = configuration["ConnectionString"];
    _poolSize = int.Parse(configuration["PoolSize"]);
    _maxIdleConnections = int.Parse(configuration["MaxIdleConnections"]);
  }

  public async Task<IDbConnection> GetDbConnectionAsync() {
    // Create a new connection pool if necessary
    if (_pool == null) {
      _pool = new DbConnectionPool(_connectionString, _poolSize, _maxIdleConnections);
    }

    // Get a free connection from the pool
    return await _pool.GetFreeConnectionAsync();
  }

  public async Task ReturnDbConnectionAsync(IDbConnection connection) {
    if (connection == null) {
      throw new ArgumentNullException(nameof(connection));
    }

    // Return the connection to the pool
    await _pool.ReturnConnectionAsync(connection);
  }

  private class DbConnectionPool {
    private readonly string _connectionString;
    private readonly int _poolSize;
    private readonly int _maxIdleConnections;
    private readonly Queue<IDbConnection> _freeConnections = new Queue<IDbConnection>();

    public DbConnectionPool(string connectionString, int poolSize, int maxIdleConnections) {
      _connectionString = connectionString;
      _poolSize = poolSize;
      _maxIdleConnections = maxIdleConnections;
    }

    public async Task<IDbConnection> GetFreeConnectionAsync() {
      // If there are free connections available, get one from the queue
      if (_freeConnections.Count > 0) {
        return _freeConnections.Dequeue();
      }

      // Create a new connection if necessary
      if (_connections.Count < _poolSize) {
        IDbConnection connection = await CreateDbConnectionAsync();
        _connections.Add(connection);
        return connection;
      }

      // If there are no free connections available, wait for one to be returned
      while (true) {
        if (_freeConnections.Count > 0) {
          return _freeConnections.Dequeue();
        } else {
          await Task.Delay(100);
        }
      }
    }

    public async Task ReturnConnectionAsync(IDbConnection connection) {
      // If the connection is still valid, add it to the queue of free connections
      if (connection != null && !connection.IsDisposed && !connection.State.Equals(ConnectionState.Closed)) {
        _freeConnections.Enqueue(connection);
      }
    }

    private async Task<IDbConnection> CreateDbConnectionAsync() {
      // Create a new connection using the connection string
      IDbConnection connection = new MySqlConnection(_connectionString);
      await connection.OpenAsync();
      return connection;
    }
  }
}
