#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

// Define Node structure
typedef struct Node {
    int value;
    struct SubNode* subnodes;
} Node;

// Define SubNode structure
typedef struct SubNode {
    char* string;
    double value;
    struct NestedSubNode* nested_subnodes;
} SubNode;

// Define NestedSubNode structure
typedef struct NestedSubNode {
    char* array;
    float value;
} NestedSubNode;

void initialize_array(int size, int min, int max) {
    // Allocate memory for the Node array
    Node** nodes = malloc(size * sizeof(Node*));
    if (nodes == NULL) {
        fprintf(stderr, "Memory allocation error\n");
        return;
    }

    // Initialize each Node in the array with a random integer value within the given range
    for (int i = 0; i < size; i++) {
        nodes[i] = malloc(sizeof(Node));
        if (nodes[i] == NULL) {
            fprintf(stderr, "Memory allocation error\n");
            return;
        }
        nodes[i]->value = min + rand() % (max - min);
    }

    // Allocate memory for the SubNode linked list in each Node
    for (int i = 0; i < size; i++) {
        nodes[i]->subnodes = malloc(sizeof(SubNode) * MAX_SUBNODES);
        if (nodes[i]->subnodes == NULL) {
            fprintf(stderr, "Memory allocation error\n");
            return;
        }
    }

    // Allocate memory for the NestedSubNode linked list in each SubNode
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < MAX_SUBNODES; j++) {
            nodes[i]->subnodes[j].nested_subnodes = malloc(sizeof(NestedSubNode) * MAX_NESTED_SUBNODES);
            if (nodes[i]->subnodes[j].nested_subnodes == NULL) {
                fprintf(stderr, "Memory allocation error\n");
                return;
            }
        }
    }

    // Populate the SubNode linked list with random strings and double values
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < MAX_SUBNODES; j++) {
            nodes[i]->subnodes[j].string = malloc(100 * sizeof(char));
            if (nodes[i]->subnodes[j].string == NULL) {
                fprintf(stderr, "Memory allocation error\n");
                return;
            }
            sprintf(nodes[i]->subnodes[j].string, "%d", rand() % 10);
            nodes[i]->subnodes[j].value = (float)rand() / RAND_MAX * MAX_FLOAT;
        }
    }

    // Populate the NestedSubNode linked list with random strings and double values
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < MAX_SUBNODES; j++) {
            for (int k = 0; k < MAX_NESTED_SUBNODES; k++) {
                nodes[i]->subnodes[j].nested_subnodes[k].array = malloc(100 * sizeof(char));
                if (nodes[i]->subnodes[j].nested_subnodes[k].array == NULL) {
                    fprintf(stderr, "Memory allocation error\n");
                    return;
                }
                sprintf(nodes[i]->subnodes[j].nested_subnodes[k].array, "%d", rand() % 10);
                nodes[i]->subnodes[j].nested_subnodes[k].value = (float)rand() / RAND_MAX * MAX_FLOAT;
            }
        }
    }
}

int main(void) {
    // Initialize the Node array with 10 elements and random integer values within the range [1, 5]
    initialize_array(10, 1, 5);

    return 0;
}
