// JavaScript code
const findElementsBySelector = (root, selector, testFunc) => {
    let elements = [];
    const queue = [root];
    while (queue.length > 0) {
        const node = queue.shift();
        if (node.matches(selector)) {
            elements.push(node);
        }
        node.childNodes.forEach((childNode) => queue.push(childNode));
    }
    return elements;
};

