Here is an example of how you could implement the C function that parses a TIFF image file and extracts information about the image's bits per sample and sample per pixel:
```
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <tiffio.h>

// Define the struct to hold the extracted information
struct tiff_info {
    int bits_per_sample;
    int samples_per_pixel;
};

// Function to parse a TIFF image file and extract information about its bits per sample and sample per pixel
struct tiff_info *parse_tiff(const char *filename) {
    // Open the TIFF file using libtiff
    TIFF *tif = TIFFOpen(filename, "r");
    if (!tif) {
        printf("Error: unable to open TIFF file\n");
        return NULL;
    }

    // Get the number of samples per pixel
    uint16_t samples_per_pixel = 0;
    TIFFGetField(tif, TIFFTAG_SAMPLES_PER_PIXEL, &samples_per_pixel);

    // Get the bits per sample for each sample
    uint8_t *bits_per_sample = NULL;
    TIFFGetField(tif, TIFFTAG_BITS_PER_SAMPLE, &bits_per_sample);

    // Create a struct to hold the extracted information
    struct tiff_info *info = (struct tiff_info *)malloc(sizeof(struct tiff_info));
    if (!info) {
        printf("Error: unable to allocate memory\n");
        return NULL;
    }

    // Fill in the extracted information
    info->samples_per_pixel = samples_per_pixel;
    info->bits_per_sample = bits_per_sample[0];

    // Close the TIFF file
    TIFFClose(tif);

    return info;
}
```
This function uses libtiff to open and read a TIFF image file, and then extracts information about its bits per sample and sample per pixel. It returns a struct containing this information, or NULL if there was an error.

Here is an example of how you could implement the asynchronous version of the `reduce()` method for an array of numbers in JavaScript:
```
// Function to reduce an array of numbers asynchronously using multiple CPU cores
async function reduce(array, initialValue, callback) {
    // Create a semaphore to limit the number of concurrent reduction tasks
    const semaphore = new Semaphore(2);

    // Initialize the reduction result and error message
    let result = initialValue;
    let error = null;

    // Split the array into smaller chunks for parallel processing
    const chunks = splitArray(array, 100);

    // Create a promise to handle each chunk of the array asynchronously
    Promise.all(chunks.map((chunk) => {
        return new Promise((resolve, reject) => {
            semaphore.acquire(() => {
                // Reduce the chunk asynchronously using the callback function
                const reduction = reduceAsync(chunk, initialValue, (result, value) => {
                    return result + value;
                });

                // Release the semaphore when the reduction is complete
                semaphore.release();

                if (reduction.error) {
                    reject(reduction.error);
                } else {
                    resolve(reduction.result);
                }
            });
        });
    })).then((values) => {
        // Combine the results from each chunk of the array
        result = values.reduce((a, b) => a + b, initialValue);
    }).catch((error) => {
        // Handle any errors that occurred during the reduction
        console.log("Error:", error);
    });

    return result;
}

// Function to split an array into smaller chunks for parallel processing
function splitArray(array, size) {
    const chunks = [];
    let chunk = [];
    for (let i = 0; i < array.length; i++) {
        chunk.push(array[i]);
        if (chunk.length === size) {
            chunks.push(chunk);
            chunk = [];
        }
    }
    return chunks;
}
```
This function uses a semaphore to limit the number of concurrent reduction tasks, and then splits an array into smaller chunks for parallel processing using the `splitArray()` function. It then creates a promise for each chunk and reduces it asynchronously using the `reduceAsync()` function. Finally, it combines the results from each chunk and returns the final reduced value or an error if one occurs during the process.

