        try {
            $access_token = $provider->getAccessToken($_GET['code']);
            $_SESSION['access_token'] = $access_token;

            // Step 3: Retrieve user information using access token
            $user_info = $provider->getUserInfo($access_token);

            // Step 4: Store user information securely in session variable
            $_SESSION['user_info'] = $user_info;

            // Step 5: Handle rate limiting to prevent abuse and ensure fair usage
            $rate_limit = $provider->getRateLimit();
            if ($rate_limit) {
                sleep($rate_limit);
            }

            // Step 6: Log successful authentication attempt
            logger('info', 'Authentication successful');
        } catch (Exception $e) {
            // Step 7: Handle failed authentication attempt and log it
            logger('error', 'Authentication failed: ' . $e->getMessage());
            return false;
