import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Semaphore;
import java.util.logging.Logger;
import java.net.URL;

public class ImageDownloader {
    private static final Logger LOGGER = Logger.getLogger(ImageDownloader.class.getName());

    // Cache of downloaded images, mapped by URL
    private static Map<String, BufferedImage> imageCache = new HashMap<>();

    // Thread pool for downloading images
    private static ExecutorService executorService;

    // Semaphore to control the number of concurrent downloads
    private static Semaphore semaphore = new Semaphore(10);

    // Configuration parameters
    private int cacheSize = 1000;
    private int timeout = 30000;

    public ImageDownloader() {
        executorService = Executors.newFixedThreadPool(5);
    }

    public void downloadImageResources(List<String> imageUrls) {
        // Validate the input image URLs
        for (String url : imageUrls) {
            if (!isValidImageUrl(url)) {
                throw new IllegalArgumentException("Invalid image URL: " + url);
            }
        }

        // Download images in parallel
        List<DownloadTask> downloadTasks = new ArrayList<>();
        for (String url : imageUrls) {
            downloadTasks.add(new DownloadTask(url));
        }
        executorService.invokeAll(downloadTasks);

        // Cache downloaded images
        for (DownloadTask task : downloadTasks) {
            if (task.isSuccessful()) {
                BufferedImage image = task.getImage();
                imageCache.put(image.getUrl(), image);
            } else {
                LOGGER.warning("Failed to download image: " + task.getUrl());
            }
        }
    }

    public void clearCache() {
        imageCache.clear();
    }

    private boolean isValidImageUrl(String url) {
        try {
            new URL(url);
            return true;
        } catch (MalformedURLException e) {
            return false;
        }
    }

    private static class DownloadTask implements Callable<Boolean> {
        private String url;

        public DownloadTask(String url) {
            this.url = url;
        }

        @Override
        public Boolean call() throws Exception {
            try {
                // Download the image from the URL
                BufferedImage image = downloadImage(url);

                // Check if the download was successful
                if (image != null) {
                    return true;
                } else {
                    LOGGER.warning("Failed to download image: " + url);
                    return false;
                }
            } catch (IOException e) {
                LOGGER.severe("Error downloading image: " + url);
                return false;
            }
        }

        private BufferedImage downloadImage(String url) throws IOException {
            // Download the image from the URL using a GET request
            HttpURLConnection connection = (HttpURLConnection) new URL(url).openConnection();
            connection.setConnectTimeout(timeout);
            connection.setReadTimeout(timeout);
            InputStream inputStream = connection.getInputStream();

            // Decode the image from the input stream
            BufferedImage image = ImageIO.read(inputStream);

            // Close the input stream and return the decoded image
            inputStream.close();
            return image;
        }
    }
}
