import requests
from bs4 import BeautifulSoup
import time
import random
import logging
import yaml

class WebScraper:
    def __init__(self, config_path):
        with open(config_path, 'r') as f:
            self.config = yaml.safe_load(f)
        self.proxies = []
        self.proxy_index = 0
        self.logger = logging.getLogger(__name__)

    def scrape(self, url):
        # Create a request with the current proxy
        try:
            response = requests.get(url, proxies=self.proxies[self.proxy_index], timeout=10)
        except requests.exceptions.Timeout as e:
            self.logger.error(f'Proxy {self.proxies[self.proxy_index]} timed out while scraping {url}')
            # Rotate to the next proxy in the list if there are any remaining proxies
            if len(self.proxies) > 0:
                self.proxy_index = (self.proxy_index + 1) % len(self.proxies)
        except requests.exceptions.ProxyError as e:
            # If there are no remaining proxies, create a new one and add it to the list
            if len(self.proxies) == self.proxy_index:
                self.create_new_proxy()
            else:
                self.logger.error(f'Proxy {self.proxies[self.proxy_index]} failed while scraping {url}')
            # Rotate to the next proxy in the list if there are any remaining proxies
            if len(self.proxies) > 0:
                self.proxy_index = (self.proxy_index + 1) % len(self.proxies)
        except requests.exceptions.RequestException as e:
            # If there are no remaining proxies, create a new one and add it to the list
            if len(self.proxies) == self.proxy_index:
                self.create_new_proxy()
            else:
                self.logger.error(f'Proxy {self.proxies[self.proxy_index]} failed while scraping {url}')
            # Rotate to the next proxy in the list if there are any remaining proxies
            if len(self.proxies) > 0:
                self.proxy_index = (self.proxy_index + 1) % len(self.proxies)
        else:
            return response

    def create_new_proxy(self):
        # Create a new proxy using the configured proxy type and port
        if self.config['proxy']['type'] == 'http':
            self.proxies.append({'http': f'{self.config["proxy"]["address"]}:{self.config["proxy"]["port"]}'})
        elif self.config['proxy']['type'] == 'socks5':
            self.proxies.append({'https': f'{self.config["proxy"]["address"]}:{self.config["proxy"]["port"]}'})
        else:
            raise ValueError(f'Invalid proxy type {self.config["proxy"]["type"]}')

    def get_html(self, url):
        # Send a request to the URL and return the HTML response
        response = self.scrape(url)
        if response is None:
            return None
        else:
            return response.text

    def extract_data(self, html):
        # Parse the HTML using BeautifulSoup and extract the data
        soup = BeautifulSoup(html, 'lxml')
        data = []
        for element in soup.find_all('div'):
            data.append({'attribute': element['id'], 'value': element.text})
        return data

    def log_scrape(self, url):
        # Log the scrape activity using the configured logging service
        if self.config['logging']['enabled']:
            self.logger.info(f'Scraped {url} at {time.strftime("%Y-%m-%d %H:%M:%S")}')

class WebRateLimiter:
    def __init__(self, config_path):
        with open(config_path, 'r') as f:
            self.config = yaml.safe_load(f)
        self.requests = 0
        self.time = time.time()
        self.logger = logging.getLogger(__name__)

    def check_rate_limit(self):
        # Check if the rate limit has been exceeded and sleep for a random amount of time before continuing if necessary
        if self.requests >= self.config['rate_limit']['max']:
            time_since_reset = (time.time() - self.time) % self.config['rate_limit']['interval']
            if time_since_reset > 0:
                sleep_time = random.uniform(self.config['rate_limit']['sleep'], self.config['rate_limit']['sleep'] * 2)
                self.logger.info(f'Rate limit exceeded, sleeping for {sleep_time} seconds')
                time.sleep(sleep_time)
            else:
                self.requests = 0
                self.time = time.time()
        self.requests += 1

class ProxyManager:
    def __init__(self, config_path):
        with open(config_path, 'r') as f:
            self.config = yaml.safe_load(f)
        self.proxies = []
        for proxy in self.config['proxy']['list']:
            self.proxies.append({'http': f'{self.config["proxy"]["address"]}:{self.config["proxy"]["port"]}'})
        self.logger = logging.getLogger(__name__)

    def get_proxy(self):
        # Get a random proxy from the list of proxies
        return random.choice(self.proxies)

class Scraper:
    def __init__(self, config_path, rate_limiter, proxy_manager):
        with open(config_path, 'r') as f:
            self.config = yaml.safe_load(f)
        self.rate_limiter = rate_limiter
        self.proxy_manager = proxy_manager
        self.logger = logging.getLogger(__name__)

    def scrape(self, url):
        # Scrape the URL using the configured scraping parameters and return the extracted data
        while True:
            try:
                self.rate_limiter.check_rate_limit()
                proxy = self.proxy_manager.get_proxy()
                response = requests.get(url, proxies=proxy)
                if response is None or response.status_code != 200:
                    continue
                else:
                    break
            except Exception as e:
                self.logger.error(f'Error while scraping {url}: {e}')
        return response.text

if __name__ == '__main__':
    logging.basicConfig(level=logging.INFO)
    rate_limiter = WebRateLimiter('config.yaml')
    proxy_manager = ProxyManager('config.yaml')
    scraper = Scraper('config.yaml', rate_limiter, proxy_manager)
    url = 'https://www.example.com'
    html = scraper.scrape(url)
    if html is None:
        print('Error while scraping')
    else:
        soup = BeautifulSoup(html, 'lxml')
        for element in soup.find_all('div'):
            print(element['id'], element.text)

