namespace RandomNumbers {
    class Distribution {
    public:
        virtual double generate() = 0;
    };

    class UniformDistribution : public Distribution {
    private:
        std::uniform_real_distribution<double> distribution;

    public:
        explicit UniformDistribution(double min, double max) : distribution(min, max) {}

        double generate() override { return distribution(std::random_device()); }
    };

    class NormalDistribution : public Distribution {
    private:
        std::normal_distribution<double> distribution;

    public:
        explicit NormalDistribution(double mean, double stdev) : distribution(mean, stdev) {}

        double generate() override { return distribution(std::random_device()); }
    };

    class ExponentialDistribution : public Distribution {
    private:
        std::exponential_distribution<double> distribution;

    public:
        explicit ExponentialDistribution(double lambda) : distribution(lambda) {}

        double generate() override { return distribution(std::random_device()); }
    };
}

// Source file for random number generation library
#include "RandomNumbers.h"

namespace RandomNumbers {
    std::vector<Distribution*> distributions;

    void init() {
        distributions.push_back(new UniformDistribution(0, 1));
        distributions.push_back(new NormalDistribution(0, 1));
        distributions.push_back(new ExponentialDistribution(1));
    }

    void shutdown() {
        for (auto distribution : distributions) {
            delete distribution;
        }
        distributions.clear();
    }

    Distribution* getDistribution(std::string name) {
        if (name == "uniform") {
            return distributions[0];
        } else if (name == "normal") {
            return distributions[1];
        } else if (name == "exponential") {
            return distributions[2];
        }
        throw std::invalid_argument("Invalid distribution name");
    }

    double generate(std::string name) {
        return getDistribution(name)->generate();
    }
}
