namespace MyService
{
    public class Service
    {
        private readonly string _connectionString;
        private readonly bool _useCache;
        private readonly TimeSpan _cacheExpirationPolicy;
        private readonly ILogger _logger;

        public Service(string connectionString, bool useCache = true, TimeSpan cacheExpirationPolicy = default, ILogger logger = null)
        {
            _connectionString = connectionString;
            _useCache = useCache;
            _cacheExpirationPolicy = cacheExpirationPolicy == default ? TimeSpan.FromHours(1) : cacheExpirationPolicy;
            _logger = logger ?? new ConsoleLogger();
        }

        public async Task<List<MyObject>> ExecuteStoredProcedureAsync(string procedureName, object parameters)
        {
            if (string.IsNullOrWhiteSpace(procedureName))
                throw new ArgumentException("Invalid procedure name", nameof(procedureName));

            // Validate input parameters to prevent SQL injection
            var validatedParameters = ValidateInputParameters(parameters);

            List<MyObject> result;

            if (_useCache)
            {
                // Check cache for existing result
                result = GetCachedResult(procedureName, validatedParameters);

                if (result != null)
                {
                    _logger.LogInformation($"Serving result from cache: {procedureName}");
                    return result;
                }
            }

            // Open a new connection to the database
            using (var connection = new SqlConnection(_connectionString))
            {
                try
                {
                    await connection.OpenAsync();

                    // Create a command for the stored procedure
                    using (var command = new SqlCommand(procedureName, connection))
                    {
                        // Add input parameters to the command
                        AddInputParameters(command, validatedParameters);

                        // Execute the command asynchronously
                        var dataTable = await command.ExecuteReaderAsync();

                        result = ParseDataTable(dataTable);

                        if (_useCache)
                        {
                            // Cache the results for future use
                            AddCachedResult(procedureName, validatedParameters, result);
                        }

                        _logger.LogInformation($"Executed stored procedure: {procedureName}");
                    }
                }
                catch (SqlException ex)
                {
                    _logger.LogError(ex, $"An error occurred while executing the stored procedure: {procedureName}");
                    throw;
                }
            }

            return result;
        }

        private List<MyObject> ParseDataTable(SqlDataReader dataTable)
        {
            var result = new List<MyObject>();

            while (dataTable.Read())
            {
                // Extract the values from the data reader and create a new object instance
                MyObject obj = CreateNewObjectFromValues(dataTable);
                result.Add(obj);
            }

            return result;
        }

        private void AddInputParameters(SqlCommand command, object parameters)
        {
            // Iterate through the input parameters and add them to the command
            foreach (var param in parameters)
            {
                var name = param.Key;
                var value = param.Value;

                if (value == null || value == DBNull.Value)
                    continue;

                command.Parameters.AddWithValue(name, value);
            }
        }

