struct CompilationResult {
    stdout: String,
    stderr: String,
}

struct FileCompilationResult {
    file_path: PathBuf,
    result: CompilationResult,
}

struct CachingSystem {
    cache: HashMap<PathBuf, CompilationResult>,
}

impl CachingSystem {
    fn new() -> Self {
        Self {
            cache: HashMap::new(),
        }
    }

    fn get_compiled_file(&mut self, file_path: &PathBuf) -> Option<&CompilationResult> {
        if let Some(result) = self.cache.get(file_path) {
            return Some(result);
        } else {
            return None;
        }
    }

    fn cache_compiled_file(&mut self, file_path: &PathBuf, result: CompilationResult) {
        self.cache.insert(file_path.clone(), result);
    }
}

fn compile_files<I>(files: I, compilation_system: &mut CachingSystem) -> Vec<FileCompilationResult>
where
    I: Iterator<Item = PathBuf>,
{
    let mut results = vec![];

    for file in files {
        if let Some(result) = compilation_system.get_compiled_file(&file) {
            results.push(FileCompilationResult { file_path: file, result: result.clone() });
        } else {
            let mut stdout = String::new();
            let mut stderr = String::new();

            // TODO: Compile the file using the `Command` API and capture its output
