            } else {
                // TODO: Handle compilation failures gracefully by skipping problematic files and continuing with the remaining ones
            }

            let result = CompilationResult { stdout, stderr };
            results.push(FileCompilationResult { file_path, result });
        }
    }

    return results;
}

