import threading
import time
from typing import List, Dict, Any, Optional

class FileManagementSystem:
    def __init__(self) -> None:
        self._services: Dict[str, Any] = {}
        self._queue: List[Any] = []
        self._thread_pool: List[threading.Thread] = []
        self._thread_count: int = 0
        self._service_lock: threading.Lock = threading.Lock()
        self._queue_lock: threading.Lock = threading.Lock()
        self._shutdown: bool = False

    def _get_service(self, service_name: str) -> Optional[Any]:
        if not self._services or not service_name:
            return None
        return self._services.get(service_name, None)

    def _set_service(self, service_name: str, service: Any) -> None:
        with self._service_lock:
            if self._services is None:
                self._services = {}
            self._services[service_name] = service

    def _get_thread_count(self) -> int:
        with self._thread_pool_lock:
            return len(self._thread_pool)

    def _add_thread(self, thread: threading.Thread) -> None:
        with self._thread_pool_lock:
            self._thread_pool.append(thread)

    def _remove_thread(self, thread: threading.Thread) -> None:
        with self._thread_pool_lock:
            if thread in self._thread_pool:
                self._thread_pool.remove(thread)

    def _shutdown_threads(self) -> None:
        with self._thread_pool_lock:
            for thread in self._thread_pool:
                thread.join()

    def upload_file(self, file_path: str, service_name: str = None) -> bool:
        if not file_path or not service_name:
            return False
        service = self._get_service(service_name)
        if not service:
            return False
        with self._queue_lock:
            self._queue.append((file_path, service))
        return True

    def download_file(self, file_path: str, service_name: str = None) -> bool:
        if not file_path or not service_name:
            return False
        service = self._get_service(service_name)
        if not service:
            return False
        with self._queue_lock:
            self._queue.append((file_path, service))
        return True

    def _run_loop(self) -> None:
        while not self._shutdown:
            time.sleep(0.5)
            with self._queue_lock:
                if len(self._queue) > 0:
                    file_path, service = self._queue.pop()
            try:
                service.upload_file(file_path)
            except Exception as e:
                print("Error uploading file", file_path, "to", service.name, ":", str(e))
                self._add_thread(threading.Thread(target=self._run_loop, daemon=True))
            try:
                service.download_file(file_path)
            except Exception as e:
                print("Error downloading file", file_path, "from", service.name, ":", str(e))

    def start(self) -> None:
        with self._thread_pool_lock:
            for i in range(self._get_thread_count()):
                thread = threading.Thread(target=self._run_loop, daemon=True)
                self._add_thread(thread)
                thread.start()

    def stop(self) -> None:
        with self._shutdown_threads():
            self._shutdown = True
