import redis.clients.jedis.JedisPoolConfig;

@Component
public class RedisCacheManager implements CacheManager {
    @Autowired
    private JedisPool jedisPool;

    public RedisCacheManager() {}

    public RedisCacheManager(JedisPool jedisPool) {
        this.jedisPool = jedisPool;
    }

    @Bean
    public JedisPoolConfig jedisPoolConfig() {
        return new JedisPoolConfig();
    }

    @Override
    public Cache getCache(String cacheName) {
        return new RedisCache(cacheName, jedisPool);
    }

    @Bean
    public JedisPool jedisPool() {
        return new JedisPool(jedisPoolConfig(), "redis://localhost:6379/0");
    }
}

class RedisCache implements Cache {
    private String cacheName;
    private JedisPool jedisPool;

    public RedisCache(String cacheName, JedisPool jedisPool) {
        this.cacheName = cacheName;
        this.jedisPool = jedisPool;
    }

    @Override
    public Object get(Object key) {
        return jedisPool.getResource().get(key);
    }

    @Override
    public void put(Object key, Object value) {
        jedisPool.getResource().set(key, value);
    }

    @Override
    public void evict(Object key) {
        jedisPool.getResource().del(key);
    }
}

public class ProductService {
    @Autowired
    private RedisCacheManager redisCacheManager;

    public Product getProductById(Long productId) {
        String cacheKey = "product-" + productId;
