// Node.js Application for Dynamic Module Execution with Dependency Management
const fs = require('fs');
const path = require('path');
const { spawn } = require('child_process');
const config = require('config');
const logger = require('logger');

class ModuleExecutor {
  constructor(modules, dependencies) {
    this.modules = modules;
    this.dependencies = dependencies;
  }

  async executeModules() {
    const moduleNames = Object.keys(this.modules);
    const dependencyGraph = {};
    for (const name of moduleNames) {
      if (!dependencyGraph[name]) {
        dependencyGraph[name] = [];
      }
      const dependencies = this.dependencies[name];
      for (const depName of dependencies) {
        if (dependencyGraph[depName]) {
          dependencyGraph[depName].push(name);
        } else {
          logger.error(`Dependency '${depName}' not found`);
        }
      }
    }

    const modulesToExecute = [];
    for (const name of moduleNames) {
      if (!dependencyGraph[name]) {
        modulesToExecute.push(name);
      }
    }

    while (modulesToExecute.length > 0) {
      const currentModule = modulesToExecute.shift();
      const dependenciesMet = this.dependencies[currentModule].every((depName) => dependencyGraph[depName]);
      if (!dependenciesMet) {
        continue;
      }
      logger.info(`Executing module '${currentModule}'`);
      try {
        const childProcess = spawn(this.modules[currentModule], { stdio: 'inherit' });
        await new Promise((resolve, reject) => {
          childProcess.on('exit', (code, signal) => {
            if (code === 0) {
              resolve();
            } else {
              reject(new Error(`Module '${currentModule}' exited with code ${code}`));
            }
          });
        });
      } catch (err) {
        logger.error(`Error executing module '${currentModule}': ${err}`);
      }
    }
  }
}

class ModuleManager {
  constructor(modules, dependencies) {
    this.modules = modules;
    this.dependencies = dependencies;
  }

  async executeModules() {
    const moduleExecutor = new ModuleExecutor(this.modules, this.dependencies);
    await moduleExecutor.executeModules();
  }
}

module.exports = ModuleManager;
