        blueslip.reset();
      });

      afterEach(() => {
        blueslip.cleanup();
      });

      // Iterate over the test suite and execute each test
      testSuite.forEach(({ label, testFunction }) => {
        it(`${label}`, () => {
          // Log information to the console
          console.log(`Running test ${label}...`);

          // Execute the test function and handle any errors that may occur
          try {
            const result = testFunction();
            expect(result).toBeTruthy();
          } catch (error) {
            console.log(`Error running test ${label}:`, error);
            reject(`Test failed: ${label}`);
          }
        });
      });
    });

    // Resolve the promise with a success message
    resolve(`Tests for ${moduleLabel} passed!`);
  });
}

// C#: ExecuteQueryAndReturnReader method
async Task<DataTableReader> ExecuteQueryAndReturnReader(byte[] query) {
  try {
    // Create a new SQL connection and open it
    using (var conn = new SqlConnection()) {
      await conn.OpenAsync();

      // Create a new SQL command and set the query
      using (var cmd = new SqlCommand(query, conn)) {
        // Execute the query and store the result in a data table
        var reader = await cmd.ExecuteReaderAsync();

        // Return the data table reader
        return reader;
      }
    }
  } catch (Exception e) {
    Console.WriteLine($"Error executing query: {e.Message}");
  }
}

