#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <dirent.h>
#include <pthread.h>
#include <errno.h>
#include <assert.h>

// Define a data structure to hold the resource bundle
typedef struct {
    char* file_path; // The path of the file containing the resource bundle
    char* format; // The format of the resource bundle (e.g., JSON, XML, binary)
    void* data; // A pointer to the data contained in the resource bundle
} ResourceBundle;

// Define a data structure to hold the cache of loaded resource bundles
typedef struct {
    char* file_path; // The path of the file containing the cached resource bundle
    char* format; // The format of the cached resource bundle
    void* data; // A pointer to the data contained in the cached resource bundle
} ResourceCache;

// Define a function to load a dynamic resource bundle from a configurable file path
void load_resource_bundle(const char* file_path, const char* format) {
    // Initialize the resource bundle with default values
    ResourceBundle* bundle = calloc(1, sizeof(ResourceBundle));
    bundle->file_path = strdup(file_path);
    bundle->format = strdup(format);
    bundle->data = NULL;

    // Check if the file exists and is accessible
    struct stat buffer;
    if (stat(bundle->file_path, &buffer) != 0 || !S_ISREG(buffer.st_mode)) {
        fprintf(stderr, "Error: File %s does not exist or is not a regular file\n", bundle->file_path);
        return;
    }

    // Check if the format is supported
    if (strcmp(bundle->format, "JSON") && strcmp(bundle->format, "XML") && strcmp(bundle->format, "binary")) {
        fprintf(stderr, "Error: Format %s is not supported\n", bundle->format);
        return;
    }

    // Load the resource bundle data from the file
    FILE* fp = fopen(bundle->file_path, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open file %s\n", bundle->file_path);
        return;
    }

    // Allocate memory for the data based on the format
    if (!strcmp(bundle->format, "JSON")) {
        bundle->data = malloc(sizeof(char*) * 100);
    } else if (!strcmp(bundle->format, "XML")) {
        bundle->data = malloc(sizeof(char*) * 200);
    } else if (!strcmp(bundle->format, "binary")) {
        bundle->data = malloc(sizeof(char*) * 500);
    }

    // Read the data from the file into the buffer
    char* buf = calloc(1, 1024);
    while (fgets(buf, 1024, fp) != NULL) {
        if (!strcmp(bundle->format, "JSON")) {
            // JSON format: each line is a JSON object
            char* token = strtok(buf, "\n");
            ((char**)bundle->data)[(int)(token - buf)] = strdup(token);
        } else if (!strcmp(bundle->format, "XML")) {
            // XML format: each line is a XML element
            char* token = strtok(buf, "\n");
            ((char**)bundle->data)[(int)(token - buf)] = strdup(token);
        } else if (!strcmp(bundle->format, "binary")) {
            // Binary format: each line is a byte array
            char* token = strtok(buf, "\n");
            ((char**)bundle->data)[(int)(token - buf)] = strdup(token);
        }
    }

    // Close the file and free the buffer
    fclose(fp);
    free(buf);
}

// Define a function to manage concurrent access for multiple threads
void* load_resource_bundle_threadsafe(const char* file_path, const char* format) {
    pthread_mutex_lock(&mutex);
    load_resource_bundle(file_path, format);
    pthread_mutex_unlock(&mutex);
}

// Define a function to handle concurrent access for multiple threads and detect changes in the resource files
void* load_resource_bundle_threadsafe_with_detection(const char* file_path, const char* format) {
    pthread_mutex_lock(&mutex);
    if (stat(file_path, &buffer) == 0 && !S_ISREG(buffer.st_mode)) {
        // The resource bundle has changed since the last load: reload it
        load_resource_bundle(file_path, format);
    } else {
        // The resource bundle has not changed since the last load: return the cached data
        return get_cached_data(file_path, format);
    }
    pthread_mutex_unlock(&mutex);
}

// Define a function to detect changes in the resource files and trigger automatic reloading
void* check_for_resource_bundle_changes() {
    while (1) {
        // Check if any of the resource files have changed since the last load
        struct stat buffer;
        for (int i = 0; i < num_files; i++) {
            if (stat(file_paths[i], &buffer) != 0 || !S_ISREG(buffer.st_mode)) {
                // The resource file has changed since the last load: reload it
                pthread_mutex_lock(&mutex);
                load_resource_bundle(file_paths[i], formats[i]);
                pthread_mutex_unlock(&mutex);
            }
        }
        // Sleep for a short period of time before checking again
        sleep(10);
    }
}

// Define a function to integrate the resource loading function with an external database
void* load_resource_bundle_from_db() {
    // Load the data from the database and cache it in memory
    void* db_data = get_db_data(file_path, format);
    if (db_data == NULL) {
        // Failed to load data from the database: return an error code
        return -1;
    }
    pthread_mutex_lock(&mutex);
    cache_resource_bundle(file_path, format, db_data);
    pthread_mutex_unlock(&mutex);
}

// Define a function to manage concurrent access for multiple threads and cache the resource bundle in memory
void* load_resource_bundle_threadsafe_with_caching() {
    pthread_mutex_lock(&mutex);
    if (get_cached_data(file_path, format) == NULL) {
        // No cached data found: load the resource bundle from disk
        load_resource_bundle(file_path, format);
    }
    pthread_mutex_unlock(&mutex);
}

// Define a function to manage concurrent access for multiple threads and detect changes in the resource files and cache the resource bundle in memory
void* load_resource_bundle_threadsafe_with_detection_and_caching() {
    pthread_mutex_lock(&mutex);
    if (stat(file_path, &buffer) == 0 && !S_ISREG(buffer.st_mode)) {
        // The resource bundle has changed since the last load: reload it and cache it in memory
        load_resource_bundle(file_path, format);
        cache_resource_bundle(file_path, format, data);
    } else {
        // The resource bundle has not changed since the last load: return the cached data
        return get_cached_data(file_path, format);
    }
    pthread_mutex_unlock(&mutex);
}

// Define a function to cache the resource bundle in memory
void* cache_resource_bundle(const char* file_path, const char* format, void* data) {
    // Create a new entry in the cache for this resource bundle
    struct cache_entry* entry = malloc(sizeof(struct cache_entry));
    entry->file_path = strdup(file_path);
    entry->format = strdup(format);
    entry->data = data;
    // Add the new entry to the end of the cache
    pthread_mutex_lock(&mutex);
    struct cache_entry** last_entry = &head;
    while (*last_entry != NULL) {
        last_entry = &(*last_entry)->next;
    }
    *last_entry = entry;
    num_entries++;
    pthread_mutex_unlock(&mutex);
}

// Define a function to get the cached data for a resource bundle
void* get_cached_data(const char* file_path, const char* format) {
    // Search the cache for an entry that matches the given file path and format
    pthread_mutex_lock(&mutex);
    struct cache_entry* entry = head;
    while (entry != NULL && !strcmp(file_path, entry->file_path) && !strcmp(format, entry->format)) {
        // Found a matching entry: return the cached data
        pthread_mutex_unlock(&mutex);
        return entry->data;
    }
    // No matching entry found: load the resource bundle from disk and cache it in memory
    load_resource_bundle(file_path, format);
    cache_resource_bundle(file_path, format, data);
    pthread_mutex_unlock(&mutex);
}

// Define a function to handle errors during the resource loading process
void* handle_error(const char* error) {
    // Print the error message and return an error code
    printf("Error: %s\n", error);
    return -1;
}
```

### 2.6 절차적 언어 vs 고급 언어

프로그래밍 언어에는 다양한 종류가 있지만, 대부분의 언어들은 두 가지 주요 분류로 나뉩니다.

* **절차적(Procedural)**: 프로그램을 명령어의 시퀀스로 구성하는 언어들로, 기계어나 어셈블리 언어와 유사합니다.
* **고급(Object-Oriented)**: 객체지향 언어들로, 클래스와 객체를 통해 프로그램을 구성하는 언어들입니다.

고급 언어의 장점은 프로그램의 유지보수성, 재사용성, 확장성이 좋다는 것입니다. 기본적으로 절차적 언어에서는 하나의 프로그램을 여러 부분으로 구성하지만, 고급 언어에서는 하나의 프로그램을 여러 개의 모듈로 구성하여 재사용성을 높일 수 있습니다.

### 2.7 절차적 언어 vs 고급 언어의 차이

절차적 언어와 고급 언어의 가장 큰 차이는 프로그램을 구성하는 방식입니다. 절차적 언어에서는 명령어를 시퀀스로 실행하고, 고급 언어에서는 객체를 이용해 프로그램을 구성합니다.

#### 2.7.1 명령어의 시퀀스 사용 vs 객체지향 프로그래밍

절차적 언어는 프로그램을 명령어의 시퀀스로 구성하고, 객체지향 언어는 객체와 클래스를 이용해 프로그램을 구성합니다.

##### 2.7.1.1 명령어의 시퀀스

```c
int main() {
    // 명령어의 시퀀스를 사용해 프로그램을 구성
    int x = 5;
    int y = 10;
    int result = add(x, y);
    printf("result: %d\n", result);
    return 0;
}

int add(int a, int b) {
    // 명령어의 시퀀스를 이용해 함수를 구현
    return a + b;
}
```

##### 2.7.1.2 객체지향 프로그래밍

```c++
class Calculator {
public:
    int add(int a, int b) {
        // 객체지향 프로그램을 사용해 함수를 구현
        return a + b;
    }
};

int main() {
    Calculator calculator;
    int result = calculator.add(5, 10);
    printf("result: %d\n", result);
    return 0;
}
```

#### 2.7.2 프로그램의 유지보수성과 재사용성

절차적 언어는 하나의 프로그램을 명령어의 시퀀스로 구성하기 때문에, 각 부분을 재사용하기가 어렵습니다. 고급 언어는 객체를 이용해 프로그램을 구성하기 때문에, 각 부분을 재사용할 수 있습니다.

#### 2.7.3 확장성

절차적 언어는 명령어의 시퀀스를 이용해 프로그램을 구성하기 때문에, 프로그램을 확장하기가 어렵습니다. 고급 언어는 객체를 이용해 프로그램을 구성하기 때문에, 프로그램을 확장하기가 쉽습니다.

### 2.8 고급 언어의 특징

고급 언어는 명령어의 시퀀스를 사용하지 않고, 객체를 이용해 프로그램을 구성합니다. 이러한 고급 언어의 특징은 다음과 같습니다.

#### 2.8.1 객체지향 프로그래밍

고급 언어는 객체지향 프로그래밍을 이용합니다. 객체지향 프로그래밍은 프로그램을 객체의 모음으로 구성하는 방식입니다. 각 객체는 상태(state)를 가지고, 동작(behavior)을 수행합니다.

#### 2.8.2 상속과 다형성

고급 언어는 상속과 다형성을 지원합니다. 상속은 하나의 클래스에서 다른 클래스를 확장하는 것을 말합니다. 다형성은 동일한 타입의 객체들이 다른 방식으로 다루어지는 것을 말합니다.

#### 2.8.3 클래스와 객체

고급 언어에서는 클래스(class)와 객체(object)를 구분합니다. 클래스는 객체의 타입을 정의하고, 객체는 클래스의 인스턴스(instance)를 의미합니다.

#### 2.8.4 인터페이스와 추상 클래스

고급 언어에서는 인터페이스(interface)와 추상 클래스를 지원합니다. 인터페이스는 객체의 공용 부분을 정의하고, 추상 클래스는 객체의 공용 부분과 개인 부분을 모두 정의합니다.

### 2.9 고급 언어의 장단점

고급 언어에는 장점과 단점이 있습니다.

#### 장점

* 고급 언어는 객체지향 프로그래밍을 지원하기 때문에, 프로그램을 모듈화시켜서 쉽게 재사용할 수 있습니다.
* 고급 언어는 상속과 다형성을 지원하기 때문에, 새로운 타입을 쉽게 정의하고 구현할 수 있습니다.
* 고급 언어는 인터페이스를 지원하기 때문에, 개발자가 쉽게 구현을 변경하고 확장할 수 있습니다.
* 고급 언어는 추상 클래스를 지원하기 때문에, 개발자가 쉽게 모듈을 만들 수 있고, 재사용할 수도 있습니다.

#### 단점

* 고급 언어는 명령문의 시퀀스를 이용해서 프로그램을 구현하기 때문에, 명령문의 개수가 많아지면 가독성과 유지보수성이 떨어집니다.
* 고급 언어는 모듈화시킬 수 있지만, 모듈의 개수가 많아지면 프로그램의 성능이 저하됩니다.
* 고급 언어는 명령문을 사용해서 프로그램을 구현하기 때문에, 프로그래밍의 자유도가 낮아집니다.

