import json
import logging
from typing import Dict, List, Optional, Union
from uuid import UUID, uuid4
from abc import ABC, abstractmethod
from concurrent.futures import Future
from collections import defaultdict

logger = logging.getLogger(__name__)

class JsonSerializable(ABC):
    """Base class for JSON serialization"""

    @abstractmethod
    def to_json(self) -> Dict[str, Union[str, int, float]]:
        """Serialize the object to a JSON dictionary"""
        pass

    @classmethod
    def from_json(cls, json_dict: Dict[str, Union[str, int, float]]) -> "JsonSerializable":
        """Deserialize a JSON dictionary to an instance of this class"""
        raise NotImplementedError()

class User(JsonSerializable):
    def __init__(self, id: UUID, name: str, age: int):
        self.id = id
        self.name = name
        self.age = age

    def to_json(self) -> Dict[str, Union[str, int, float]]:
        return {
            "id": self.id,
            "name": self.name,
            "age": self.age
        }

    @classmethod
    def from_json(cls, json_dict: Dict[str, Union[str, int, float]]) -> "User":
        return User(
            id=UUID(json_dict["id"]),
            name=json_dict["name"],
            age=json_dict["age"]
        )

class Product(JsonSerializable):
    def __init__(self, id: UUID, name: str, price: float):
        self.id = id
        self.name = name
        self.price = price

    def to_json(self) -> Dict[str, Union[str, int, float]]:
        return {
            "id": self.id,
            "name": self.name,
            "price": self.price
        }

    @classmethod
    def from_json(cls, json_dict: Dict[str, Union[str, int, float]]) -> "Product":
        return Product(
            id=UUID(json_dict["id"]),
            name=json_dict["name"],
            price=json_dict["price"]
        )

class Order(JsonSerializable):
    def __init__(self, user: User, product: Product, quantity: int):
        self.user = user
        self.product = product
        self.quantity = quantity

    def to_json(self) -> Dict[str, Union[str, int, float]]:
        return {
            "user": self.user.to_json(),
            "product": self.product.to_json(),
            "quantity": self.quantity
        }

    @classmethod
    def from_json(cls, json_dict: Dict[str, Union[str, int, float]]) -> "Order":
        return Order(
            user=User.from_json(json_dict["user"]),
            product=Product.from_json(json_dict["product"]),
            quantity=json_dict["quantity"]
        )

class JsonFileLoader:
    def __init__(self, file_paths: List[str]):
        self.file_paths = file_paths
        self._loaded_files: Dict[str, Future[JsonSerializable]] = defaultdict(lambda: None)

    @staticmethod
    def _load_file(file_path: str) -> JsonSerializable:
        with open(file_path, "r") as f:
            json_string = f.read()
            return JsonSerializable.from_json(json.loads(json_string))

    @property
    def loaded_files(self) -> List[Future[JsonSerializable]]:
        return [f for f in self._loaded_files.values() if f is not None]

    def load_file(self, file_path: str) -> Future[JsonSerializable]:
        if file_path not in self._loaded_files:
            future = Future()
            self._loaded_files[file_path] = future
            try:
                entity = self._load_file(file_path)
                future.set_result(entity)
            except Exception as e:
                future.set_exception(e)
        return self._loaded_files[file_path]

class JsonFileManager:
    def __init__(self, file_paths: List[str], dependencies: Dict[str, str] = None):
        self.file_paths = file_paths
        self.dependencies = dependencies or {}
        self._loaded_files: Dict[str, JsonSerializable] = defaultdict(lambda: None)

    @property
    def loaded_files(self) -> List[JsonSerializable]:
        return [f for f in self._loaded_files.values() if f is not None]

    def load_file(self, file_path: str) -> JsonSerializable:
        if file_path not in self._loaded_files:
            future = JsonFileLoader(self.file_paths).load_file(file_path)
            self._loaded_files[file_path] = future.result()
        return self._loaded_files[file_path]

class JsonSerializer:
    def __init__(self, file_manager: JsonFileManager):
        self.file_manager = file_manager

    @staticmethod
    def serialize(entity: JsonSerializable) -> Dict[str, Union[str, int, float]]:
        return entity.to_json()

    @staticmethod
    def deserialize(json_dict: Dict[str, Union[str, int, float]]) -> JsonSerializable:
        if "type" not in json_dict or json_dict["type"] not in ["User", "Product", "Order"]:
            raise ValueError("Invalid entity type")
        return {
            "User": User.from_json(json_dict),
            "Product": Product.from_json(json_dict),
            "Order": Order.from_json(json_dict)
        }[json_dict["type"]]

class JsonDeserializer:
    def __init__(self, file_manager: JsonFileManager):
        self.file_manager = file_manager

    @staticmethod
    def deserialize(json_string: str) -> JsonSerializable:
        return JsonSerializer(file_manager).deserialize(JsonSerializer.serialize(JsonSerializer.deserialize(json_string)))

def main():
    # Load the JSON files and create a file manager
    file_paths = ["user1.json", "product1.json", "order1.json"]
    dependencies = {
        "user1.json": ["product1.json"],
        "order1.json": ["user1.json", "product1.json"]
    }
    file_manager = JsonFileManager(file_paths, dependencies)

    # Load the files and deserialize them into entities
    user = file_manager.load_file("user1.json")
    product = file_manager.load_file("product1.json")
    order = file_manager.load_file("order1.json")

    print(f"Loaded entities: {user}, {product}, {order}")

if __name__ == "__main__":
    main()

