2. **Image Processing**: Implement a C function that parses a TIFF image file and extracts information about the image's bits per sample, sample per pixel, and color profile. The function should use standard library functions and return the extracted information in the form of a struct. Handle cases where the image has 1, 2, 4, 8, or 16 bits per sample, and return an error message if the bits per sample is not supported. If the image has extra samples, the function should return the number of extra samples and the sample information along with the color profile.
```c
#include <stdint.h>
#include <stdio.h>

struct tiff_image {
  uint16_t bits_per_sample;
  uint32_t samples_per_pixel;
  char *color_profile;
};

struct tiff_image parse_tiff(FILE *file) {
  struct tiff_image image = { .bits_per_sample = 0, .samples_per_pixel = 0, .color_profile = NULL };

  // Check if the file is a TIFF image by checking for the magic number
  uint32_t magic_number;
  fread(&magic_number, sizeof(uint32_t), 1, file);
  if (magic_number != 0x4949) {
    return image;
  }

  // Parse the TIFF header and extract the bits per sample and samples per pixel values
  uint16_t version, height, width, samples, planes;
  fread(&version, sizeof(uint16_t), 1, file);
  fread(&height, sizeof(uint32_t), 1, file);
  fread(&width, sizeof(uint32_t), 1, file);
  fread(&samples, sizeof(uint16_t), 1, file);
  fread(&planes, sizeof(uint16_t), 1, file);

  if (samples > 4) {
    return image;
  }

  // Allocate memory for the color profile and read it from the file
  uint32_t color_profile_size = width * height * samples * planes;
  char *color_profile = malloc(color_profile_size);
  fread(color_profile, sizeof(char), color_profile_size, file);

  // Return the struct with the extracted information
  image.bits_per_sample = bits_per_sample;
  image.samples_per_pixel = samples;
  image.color_profile = color_profile;
  return image;
}
```
