#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>

typedef enum {
    IMAGE,
    TEXT_FILE,
    AUDIO_FILE
} ResourceType;

struct Resource {
    ResourceType type;
    char *data;
};

struct ResourceBundle {
    struct Resource *resources[10];
    int num_resources;
};

void loadResourceBundle(char *filepath, struct ResourceBundle *bundle) {
    // Initialize the resource bundle with 10 resources
    for (int i = 0; i < 10; i++) {
        bundle->resources[i] = NULL;
    }
    bundle->num_resources = 0;

    FILE *fp = fopen(filepath, "r");
    if (!fp) {
        perror("fopen");
        return;
    }

    // Read the file line by line and parse each entry
    char line[1024];
    while (fgets(line, sizeof(line), fp)) {
        ResourceType type = IMAGE;
        int count = 0;

        // Parse the resource type and count from the line
        char *type_str = strtok(line, ":");
        if (!type_str) continue;
        type = parseResourceType(type_str);
        char *count_str = strtok(NULL, "\n");
        if (!count_str) continue;
        count = atoi(count_str);

        // Allocate memory for the resource and store it in the bundle
        struct Resource *resource = malloc(sizeof(struct Resource));
        resource->type = type;
        resource->data = malloc(count * sizeof(char*));
        if (!resource->data) {
            perror("malloc");
            return;
        }

        // Read the resource data from the file
        for (int i = 0; i < count; i++) {
            fgets(resource->data[i], sizeof(line), fp);
        }

        // Add the resource to the bundle
        bundle->resources[bundle->num_resources++] = resource;
    }

    fclose(fp);
}

ResourceType parseResourceType(char *str) {
    if (strcmp(str, "image") == 0) return IMAGE;
    else if (strcmp(str, "text_file") == 0) return TEXT_FILE;
    else if (strcmp(str, "audio_file") == 0) return AUDIO_FILE;
    else return -1;
}
```

