public static class GraphQLQueryHelper
{
    public static async Task<QueryResult> ExecuteQueryAsync(GraphQLClient client, string queryTemplate, Dictionary<string, object> parameters)
    {
        // Validate input parameters to prevent injection attacks
        foreach (var parameter in parameters)
        {
            if (!ValidateParameter(parameter.Value))
            {
                throw new ArgumentException($"Invalid parameter value: {parameter.Key}");
            }
        }

        // Construct the query based on the input parameters
        var query = GenerateQuery(queryTemplate, parameters);

        // Execute the query and handle any errors that occur
        try
        {
            return await client.ExecuteQueryAsync(query);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error executing GraphQL query: {ex.Message}");
            return null;
        }
    }

    private static bool ValidateParameter(object parameterValue)
    {
        // Implement your own validation logic here to ensure the input parameters are safe and secure
        // For example, you can use a regular expression to check if the parameter value is a valid email address
        return true;
    }

    private static string GenerateQuery(string queryTemplate, Dictionary<string, object> parameters)
    {
        // Use string interpolation to construct the query based on the input parameters
        var query = $"{queryTemplate}";
        foreach (var parameter in parameters)
        {
            query = query.Replace($"{{{parameter.Key}}}", parameter.Value.ToString());
        }
        return query;
    }
}
