// Define a function to validate a DNS server name
bool is_valid_dns_server(const char *name) {
    return (strlen(name) > 0 && strlen(name) < MAX_DOMAIN_NAME_LENGTH && isalnum(name[0]));
}

// Define a function to validate an IP address
bool is_valid_ip_address(const char *address, int family) {
    struct in_addr ip;
    if (family == AF_INET) {
        return (inet_pton(AF_INET, address, &ip) == 1);
    } else {
        return (inet_pton(AF_INET6, address, &ip) == 1);
    }
}

// Define a function to validate a domain name
bool is_valid_domain_name(const char *name) {
    // Check if the domain name is not empty and has no more than MAX_DOMAIN_NAME_LENGTH characters
    if (strlen(name) == 0 || strlen(name) > MAX_DOMAIN_NAME_LENGTH) {
        return false;
    }
    // Check if the first character is a letter or a digit
    if (!isalnum(name[0])) {
        return false;
    }
    // Check if the domain name contains only letters, digits, hyphens, and dots
    for (int i = 1; i < strlen(name); ++i) {
        char c = name[i];
        if (!isalnum(c) && c != '-' && c != '.') {
            return false;
        }
    }
    return true;
}

// Define a function to validate a username
bool is_valid_username(const char *username) {
    // Check if the username is not empty and has no more than MAX_DOMAIN_NAME_LENGTH characters
    if (strlen(username) == 0 || strlen(username) > MAX_DOMAIN_NAME_LENGTH) {
        return false;
    }
    // Check if the first character is a letter or a digit
    if (!isalnum(username[0])) {
        return false;
    }
    // Check if the username contains only letters, digits, hyphens, and underscores
    for (int i = 1; i < strlen(username); ++i) {
        char c = username[i];
        if (!isalnum(c) && c != '-' && c != '_') {
            return false;
        }
    }
    return true;
}

// Define a function to validate a password
bool is_valid_password(const char *password) {
    // Check if the password is not empty and has no more than MAX_DOMAIN_NAME_LENGTH characters
    if (strlen(password) == 0 || strlen(password) > MAX_DOMAIN_NAME_LENGTH) {
        return false;
    }
    // Check if the password contains only letters, digits, hyphens, and underscores
    for (int i = 0; i < strlen(password); ++i) {
        char c = password[i];
        if (!isalnum(c) && c != '-' && c != '_') {
            return false;
        }
    }
    return true;
}

// Define a function to validate an email address
bool is_valid_email(const char *email) {
    // Check if the email address has no more than MAX_DOMAIN_NAME_LENGTH characters
    if (strlen(email) > MAX_DOMAIN_NAME_LENGTH) {
        return false;
    }
    // Check if the email address contains only letters, digits, hyphens, and dots
    for (int i = 0; i < strlen(email); ++i) {
        char c = email[i];
        if (!isalnum(c) && c != '-' && c != '.') {
            return false;
        }
    }
    return true;
}

// Define a function to validate a request for creating or updating an account
bool is_valid_account_request(const char *username, const char *password) {
    if (!is_valid_username(username)) {
        return false;
    }
    if (!is_valid_password(password)) {
        return false;
    }
    return true;
}

// Define a function to validate a request for deleting an account
bool is_valid_delete_request(const char *username) {
    if (!is_valid_username(username)) {
        return false;
    }
    return true;
}

// Define a function to perform DNS resolution using the given DNS server
struct in_addr resolve_dns(const char *dns, const char *name) {
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_DGRAM;
    int rc = getaddrinfo(dns, NULL, &hints, &res);
    if (rc != 0) {
        printf("getaddrinfo failed: %s\n", gai_strerror(rc));
        return INADDR_NONE;
    }
    struct in_addr addr = {};
    rc = getnameinfo(res->ai_addr, res->ai_addrlen, name, MAX_DOMAIN_NAME_LENGTH, NULL, 0, NI_NUMERICHOST);
    if (rc != 0) {
        printf("getnameinfo failed: %s\n", gai_strerror(rc));
        return INADDR_NONE;
    }
    freeaddrinfo(res);
    return addr;
}

// Define a function to perform DNS resolution using the system's default DNS servers
struct in_addr resolve_dns(const char *name) {
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_DGRAM;
    int rc = getaddrinfo(NULL, NULL, &hints, &res);
    if (rc != 0) {
        printf("getaddrinfo failed: %s\n", gai_strerror(rc));
        return INADDR_NONE;
    }
    struct in_addr addr = {};
    rc = getnameinfo(res->ai_addr, res->ai_addrlen, name, MAX_DOMAIN_NAME_LENGTH, NULL, 0, NI_NUMERICHOST);
    if (rc != 0) {
        printf("getnameinfo failed: %s\n", gai_strerror(rc));
        return INADDR_NONE;
    }
    freeaddrinfo(res);
    return addr;
}

// Define a function to perform DNS resolution using the system's default DNS servers and cache the results
struct in_addr resolve_dns_cached(const char *name) {
    // Check if the name is already in the cache
    if (strlen(name) > 0 && strcmp(name, "localhost") != 0) {
        struct in_addr addr = {};
        addr.s_addr = ntohl(inet_addr(name));
        if (addr.s_addr != INADDR_NONE) {
            return addr;
        }
    }
    // Perform DNS resolution using the system's default DNS servers
    struct in_addr addr = resolve_dns(name);
    // Check if the resolution was successful
    if (addr.s_addr == INADDR_NONE) {
        return addr;
    }
    // Cache the result
    char cache_filename[MAX_PATH_LENGTH];
    snprintf(cache_filename, MAX_PATH_LENGTH, "/var/run/%s_cache", name);
    FILE *cache_file = fopen(cache_filename, "w");
    if (cache_file != NULL) {
        fprintf(cache_file, "%d\n", addr.s_addr);
        fclose(cache_file);
    }
    return addr;
}

