import json
from typing import Dict, List, Optional

class JSONConfigModule:
    def __init__(self):
        self.registry = {}  # registry of factory functions, keyed by ID
        self.configs = []  # list of loaded config files

    @staticmethod
    def create_factory(cls):
        """Creates a factory function that can create a new instance of the given class from a JSON string."""
        def factory(json_str: str) -> cls:
            return cls.from_json(json_str)
        return factory

    @staticmethod
    def parse_json(json_str: str, cls=None) -> Optional[Dict]:
        """Parses a JSON string and returns the corresponding dictionary."""
        try:
            data = json.loads(json_str)
            if cls is not None and not isinstance(data, cls):
                raise TypeError(f"Invalid type for {cls.__name__}.")
            return data
        except ValueError as e:
            print(f"Failed to parse JSON string: {e}")
            return None

    def load_config(self, filename: str) -> bool:
        """Loads a JSON configuration file from disk and adds it to the registry."""
        try:
            with open(filename, "r") as f:
                data = self.parse_json(f.read())
                if data is None:
                    raise ValueError("Failed to parse JSON string.")
                self.registry[data["id"]] = self.create_factory(data["class"])
                self.configs.append(filename)
                return True
        except (FileNotFoundError, IOError, ValueError) as e:
            print(f"Failed to load config file {filename}: {e}")
            return False

    def unload_config(self, filename: str):
        """Removes a JSON configuration file from the registry."""
        if filename in self.configs:
            self.configs.remove(filename)
            del self.registry[data["id"]]

    def get_factory(self, id: str) -> Optional[callable]:
        """Returns a factory function for the given ID, or None if not found."""
        return self.registry.get(id)

    @classmethod
    def from_json(cls, json_str: str) -> cls:
        """Creates a new instance of this class from a JSON string."""
        data = cls.parse_json(json_str)
        if data is None:
            raise ValueError("Failed to parse JSON string.")
        return cls(data["id"], data["class"])

    @staticmethod
    def hash_password(password: str, algorithm="sha256") -> str:
        """Hashes a password using the given algorithm."""
        import hashlib
        if not isinstance(algorithm, str):
            raise ValueError("Invalid type for 'algorithm'.")
        return hashlib.new(algorithm, password.encode()).hexdigest()

    def serialize(self) -> bytes:
        """Serializes the object into a byte array."""
        return json.dumps(self.to_dict()).encode()

    @classmethod
    def deserialize(cls, data: bytes):
        """Deserializes an object from a byte array."""
        if not isinstance(data, bytes):
            raise ValueError("Invalid type for 'data'.")
        return cls.from_json(data.decode())
```
