#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>
#include <cstdlib>
#include <ctime>
#include <openssl/aes.h>
#include <openssl/camellia.h>
#include <openssl/md5.h>
#include <openssl/sha.h>
#include <openssl/rsa.h>
#include <openssl/rand.h>
#include <openssl/err.h>
#include <unordered_map>
#include <queue>
#include <mutex>
#include <condition_variable>

using namespace std;

class Octree {
private:
    // Node structure for the octree
    struct Node {
        bool isLeaf;
        int dataSize;
        vector<Node*> children;
        unordered_map<string, vector<string>> data;
        mutex mtx;
        condition_variable cv;

        // Constructor to initialize a node with the given data size and number of children
        Node(int dataSize, int numChildren) {
            isLeaf = false;
            this->dataSize = dataSize;
            children.resize(numChildren);
        }

        // Destructor to release memory for the node and its children
        ~Node() {
            for (auto child : children) {
                delete child;
            }
        }
    };

    // Root of the octree
    Node* root = nullptr;

    // Mutex to protect concurrent access to the octree
    mutex mtx;

    // Condition variable to signal updates to the octree
    condition_variable cv;

    // Function to initialize a node and its children with the given data size and number of children
    Node* initNode(int dataSize, int numChildren) {
        return new Node(dataSize, numChildren);
    }

    // Function to insert a data point into the octree at the given position
    void insertDataPoint(string data, string position, Node* node) {
        if (node->isLeaf) {
            node->data[position].push_back(data);
            return;
        }

        int childIndex = calculateChildIndex(position, node->dataSize);
        insertDataPoint(data, position.substr(childIndex), node->children[childIndex]);
    }

    // Function to update a data point in the octree at the given position
    void updateDataPoint(string data, string position, Node* node) {
        if (node->isLeaf) {
            node->data[position].clear();
            insertDataPoint(data, position, node);
            return;
        }

        int childIndex = calculateChildIndex(position, node->dataSize);
        updateDataPoint(data, position.substr(childIndex), node->children[childIndex]);
    }

    // Function to delete a data point from the octree at the given position
    void deleteDataPoint(string position, Node* node) {
        if (node->isLeaf) {
            node->data.erase(position);
            return;
        }

        int childIndex = calculateChildIndex(position, node->dataSize);
        deleteDataPoint(position.substr(childIndex), node->children[childIndex]);
    }

    // Function to query the octree for data points within a given range
    vector<string> queryRange(string start, string end, Node* node) {
        if (node->isLeaf) {
            return node->data.queryRange(start, end);
        }

        int childIndex = calculateChildIndex(start, node->dataSize);
        vector<string> data;
        for (auto child : node->children) {
            auto subData = queryRange(start.substr(childIndex), end.substr(childIndex), child);
            data.insert(data.end(), subData.begin(), subData.end());
        }
        return data;
    }

    // Function to calculate the index of the child node for a given position
    int calculateChildIndex(string position, int dataSize) {
        return position[0] % (dataSize * 2);
    }
};

// Function to generate a random string with the given length
string generateRandomString(int len) {
    static const char alphanum[] = "0123456789" "ABCDEFGHIJKLMNOPQRSTUVWXYZ" "abcdefghijklmnopqrstuvwxyz";
    thread_local std::random_device rd;
    thread_local std::mt19937 gen(rd());
    thread_local std::uniform_int_distribution<int> dis(0, sizeof(alphanum) - 1);
    string randomString;
    for (int i = 0; i < len; ++i) {
        randomString += alphanum[dis(gen)];
    }
    return randomString;
}

// Function to encrypt a given string using AES encryption with the specified key and initialization vector
string encryptAES(string data, string key, string iv) {
    // Initialize the AES encryption with the specified key and initialization vector
    AES_KEY encKey;
    AES_set_encrypt_key(key.c_str(), 128, &encKey);
    unsigned char* encryptedData = new unsigned char[data.size()];
    int outLen;
    AES_ctr128_encrypt((unsigned char*)data.c_str(), encryptedData, data.size(), &encKey, iv.c_str(), &outLen);

    // Return the encrypted data as a base64-encoded string
    return Base64Encode(encryptedData, outLen);
}

// Function to decrypt a given string using AES encryption with the specified key and initialization vector
string decryptAES(string data, string key, string iv) {
    // Initialize the AES decryption with the specified key and initialization vector
    AES_KEY decKey;
    AES_set_decrypt_key(key.c_str(), 128, &decKey);
    unsigned char* decryptedData = new unsigned char[data.size()];
    int outLen;
    AES_ctr128_encrypt((unsigned char*)data.c_str(), decryptedData, data.size(), &decKey, iv.c_str(), &outLen);

    // Return the decrypted data as a string
    return std::string(decryptedData, outLen);
}

// Function to calculate the hash of a given string using the specified hashing algorithm (MD5, SHA, or RSA)
string calculateHash(string data, string hashAlgo) {
    if (hashAlgo == "MD5") {
        unsigned char digest[MD5_DIGEST_LENGTH];
        MD5((unsigned char*)data.c_str(), data.size(), digest);
        return Base64Encode(digest, sizeof(digest));
    } else if (hashAlgo == "SHA") {
        unsigned char digest[SHA_DIGEST_LENGTH];
        SHA1((unsigned char*)data.c_str(), data.size(), digest);
        return Base64Encode(digest, sizeof(digest));
    } else if (hashAlgo == "RSA") {
        RSA* rsa = RSA_new();
        BIGNUM* n = BN_new();
        BIGNUM* e = BN_new();
        // Generate a random key and initialize the RSA structure with it
        string key = generateRandomString(256);
        RSA_generate_key_ex(rsa, 2048, n, e);
        // Return the public key as a base64-encoded string
        return Base64Encode((unsigned char*)RSA_public_encrypt(key.size(), (unsigned char*)key.c_str(), NULL, rsa, RSA_PKCS1_PADDING).c_str(), key.size());
    } else {
        // Return an empty string if the specified hashing algorithm is not supported
        return "";
    }
}

// Function to perform a given operation (encryption, decryption, or hashing) on a given input using the specified settings and parameters
string performOperation(string data, string opType, string encAlgo, string hashAlgo, string key, string iv) {
    if (opType == "ENCRYPT") {
        return encryptAES(data, key, iv);
    } else if (opType == "DECRYPT") {
        return decryptAES(data, key, iv);
    } else if (opType == "HASH") {
        return calculateHash(data, hashAlgo);
    } else {
        // Return an empty string if the specified operation is not supported
        return "";
    }
}

// Function to perform a given operation (encryption, decryption, or hashing) on a given input using the specified settings and parameters in the context of an OctoPrint server
string performOperation(string data, string opType, string encAlgo, string hashAlgo, string key, string iv, OctoPrintServer server) {
    if (server.getOctoPrintVersion() >= 1.5) {
        return performOperation(data, opType, encAlgo, hashAlgo, key, iv);
    } else {
        // Return an empty string if the specified operation is not supported on the OctoPrint server
        return "";
    }
}
