class PaymentGatewayIntegration:
    def __init__(self):
        self.payment_history = {}  # Dictionary of order IDs and their corresponding payment statuses
        self.retry_attempts = 3  # Number of retry attempts for transient errors
        self.retry_backoff = [0.1, 0.25, 0.5]  # Exponential backoff values for retry attempts

    def processPayment(self, orderId: int, cardNumber: str, expirationDate: str, cvv: int) -> None:
        """Processes a payment for a given order ID using the provided card details."""
        # Validate card details
        self.validateCardDetails(cardNumber, expirationDate, cvv)

        # Simulate call to external payment gateway API
        payment_status = self._simulatePaymentGatewayCall(orderId, cardNumber, expirationDate, cvv)

        # Handle transient errors by retrying the request with exponential backoff
        for i in range(self.retry_attempts):
            if payment_status == "failed":
                time.sleep(random.uniform(0, self.retry_backoff[i]))  # Exponential backoff
                payment_status = self._simulatePaymentGatewayCall(orderId, cardNumber, expirationDate, cvv)

        if payment_status == "failed":
            raise Exception("Payment failed due to transient error.")
        else:
            self.payment_history[orderId] = payment_status  # Update local payment history dictionary

