import os
from flask import Flask, request, render_template, jsonify, session, redirect, url_for, flash, Blueprint
from flask_login import LoginManager, UserMixin, login_user, logout_user, login_required, current_user
from flask_security import Security, SQLAlchemyUserDatastore
from flask_security.forms import ConfirmRegisterForm, ForgotPasswordForm, ChangePasswordForm, RegisterForm
from flask_security.models import Role
from flask_cors import CORS
import datetime
from sqlalchemy import create_engine
from sqlalchemy.orm import sessionmaker

app = Flask(__name__)
app.config["SECRET_KEY"] = os.environ["SECRET_KEY"]
app.config["SQLALCHEMY_DATABASE_URI"] = os.environ["DATABASE_URL"]
app.config["SQLALCHEMY_TRACK_MODIFICATIONS"] = False
app.config["WTF_CSRF_ENABLED"] = True
app.config["WTF_CSRF_SECRET_KEY"] = os.environ["CSRF_SECRET_KEY"]
CORS(app)

# Initialize Flask-Login and Flask-Security
login_manager = LoginManager()
login_manager.init_app(app)
login_manager.login_view = "security.login"

# Initialize SQLAlchemy for user management
engine = create_engine(app.config["SQLALCHEMY_DATABASE_URI"])
db_session = sessionmaker(bind=engine)
User = db_session()

@login_manager.user_loader
def load_user(username):
    return User.query.get(username)

# Initialize Flask-Security user datastore
user_datastore = SQLAlchemyUserDatastore(db_session, User, Role)
security = Security(app, user_datastore)

# Register blueprints for authentication and authorization
auth = Blueprint("auth", __name__)
security.init_app(app, anonymous_user=None)

# Define routes for authentication and authorization
@auth.route("/login", methods=["GET", "POST"])
def login():
    form = LoginForm()
    if form.validate_on_submit():
        user = User.query.filter_by(username=form.username.data).first()
        if user and user.check_password(form.password.data):
            login_user(user)
            flash("You have been logged in!")
            return redirect(url_for("auth.login"))
        else:
            flash("Invalid username or password.")
