#include <functional>

struct State {
  int id;
  std::string class_or_id;
  std::vector<State*> children;
};

struct FSA {
  std::unordered_map<int, State*> states;
};

void traverseDOMTree(FSA& fsa, int last_state) {
  std::vector<int> matched_states;

  // Traverse the DOM tree recursively
  for (auto state : fsa.states) {
    if (testSelector(state.second->class_or_id)) {
      matched_states.push_back(state.first);
    }

    traverseDOMTree(fsa, last_state);
  }

  // Store the result in dynamically allocated memory
  int* result = new int[matched_states.size()];
  std::copy(matched_states.begin(), matched_states.end(), result);
  delete[] result;
}

bool testSelector(const std::string& selector) {
  // Use a provided function to test each element's class or ID against the selector
  // For example: return (selector == "class" && element->getAttribute("class") == selector) || (selector == "id" && element->getAttribute("id") == selector);
}
