#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>

// Structures to represent a product and its reviews
typedef struct Product {
    char *name;
    double price;
    struct Review *reviews;
} Product;

typedef struct Review {
    int rating;
    char *text;
    struct Review *next;
} Review;

// Function to create a new product
Product* create_product(const char *name, double price) {
    // Allocate memory for the product structure
    Product *product = malloc(sizeof(Product));
    if (product == NULL) {
        perror("Failed to allocate memory for product");
        return NULL;
    }

    // Set the name and price of the product
    product->name = strdup(name);
    product->price = price;

    // Initialize the reviews list as an empty linked list
    product->reviews = NULL;

    return product;
}

// Function to add a review to a product
int add_review(Product *product, int rating, const char *text) {
    // Allocate memory for the new review structure
    Review *new_review = malloc(sizeof(Review));
    if (new_review == NULL) {
        perror("Failed to allocate memory for review");
        return -1;
    }

    // Set the rating and text of the review
    new_review->rating = rating;
    new_review->text = strdup(text);

    // Add the new review to the end of the reviews list
    if (product->reviews == NULL) {
        product->reviews = new_review;
    } else {
        Review *cur = product->reviews;
        while (cur->next != NULL) {
            cur = cur->next;
        }
        cur->next = new_review;
    }

    return 0;
}

// Function to calculate the average rating for a product based on its reviews
double get_average_rating(Product *product) {
    // Calculate the total rating of all reviews
    double total_rating = 0.0;
    Review *cur = product->reviews;
    while (cur != NULL) {
        total_rating += cur->rating;
        cur = cur->next;
    }

    // Calculate the average rating and return it
    double num_reviews = get_num_reviews(product);
    return total_rating / num_reviews;
}

// Function to get the number of reviews for a product
int get_num_reviews(Product *product) {
    int count = 0;
    Review *cur = product->reviews;
    while (cur != NULL) {
        count++;
        cur = cur->next;
    }

    return count;
}

// Function to serialize and deserialize the product data to/from a file using JSON format
int save_products(const char *filename, Product *product) {
    // Allocate memory for the JSON string
    json_auto_t *json = json_auto((char *) filename);
    if (json == NULL) {
        perror("Failed to create JSON object");
        return -1;
    }

    // Add the product structure to the JSON object
    json_object_add(json, "product", json_object());
    json_object_set(json, "name", json_string(product->name));
    json_object_set(json, "price", json_double(product->price));

    // Add the reviews list to the JSON object
    Review *cur = product->reviews;
    while (cur != NULL) {
        json_object_add(json, "review", json_array());
        json_array_append(json, "rating", json_int(cur->rating));
        json_array_append(json, "text", json_string(cur->text));
        cur = cur->next;
    }

    // Save the JSON string to a file
    int ret = json_save(json, filename);
    if (ret < 0) {
        perror("Failed to save JSON object");
        return -1;
    }

    return 0;
}

int load_products(const char *filename, Product **product) {
    // Open the JSON file and create a JSON object from it
    json_auto_t *json = json_open_file((char *) filename);
    if (json == NULL) {
        perror("Failed to open JSON file");
        return -1;
    }

    // Parse the JSON string into a product structure
    Product *new_product = malloc(sizeof(Product));
    if (new_product == NULL) {
        perror("Failed to allocate memory for product");
        return -1;
    }

    json_object_t *root = json_get_root(json);
    json_value_t *product_obj = json_find(root, "product");
    if (product_obj == NULL) {
        perror("Failed to find product object in JSON string");
        return -1;
    }

    // Get the name and price of the product from the JSON object
    new_product->name = json_find_string(product_obj, "name");
    new_product->price = json_find_double(product_obj, "price");

    // Parse the reviews list from the JSON string
    json_value_t *reviews_array = json_find(root, "review");
    if (reviews_array == NULL) {
        perror("Failed to find review array in JSON string");
        return -1;
    }

    // Add the reviews to the linked list
    for (int i = 0; i < json_array_size(reviews_array); i++) {
        Review *new_review = malloc(sizeof(Review));
        if (new_review == NULL) {
            perror("Failed to allocate memory for review");
            return -1;
        }

        json_value_t *review_obj = json_array_get(reviews_array, i);
        new_review->rating = json_find_int(review_obj, "rating");
        new_review->text = json_find_string(review_obj, "text");
        new_product->reviews = new_review;
    }

    // Return the product structure to the caller
    *product = new_product;

    return 0;
}
