using System;
using UnityEngine;

public class CustomRandomGenerator
{
    private Random _random;
    private int _seed;

    public CustomRandomGenerator()
    {
        this._random = new Random(UnityEngine.Random.Seed());
    }

    public CustomRandomGenerator(int seed)
    {
        this._random = new Random(seed);
    }

    public int GenerateIntegerInclusive(int min, int max)
    {
        return this._random.Next(min, max + 1);
    }

    public float GenerateFloatInclusive(float min, float max)
    {
        return (float)(this._random.NextDouble() * (max - min)) + min;
    }

    public int GenerateIntegerExclusive(int min, int max)
    {
        return this._random.Next(min, max);
    }

    public float GenerateFloatExclusive(float min, float max)
    {
        return (float)(this._random.NextDouble() * (max - min)) + min;
    }

    public CustomRange GenerateCustomRange(int min, int max, bool isExclusive = false, int seed = 0)
    {
        if (seed == 0)
        {
            seed = UnityEngine.Random.Seed();
        }
        this._random = new Random(seed);
        return new CustomRange(min, max, isExclusive);
    }

    public void Seed(int seed)
    {
        this._random = new Random(seed);
    }

    public string ToString()
    {
        return $"CustomRandomGenerator({this._random.Seed})";
    }
}

public class CustomRange
{
    private int _min;
    private int _max;
    private bool _isExclusive;

    public CustomRange(int min, int max, bool isExclusive)
    {
        this._min = min;
        this._max = max;
        this._isExclusive = isExclusive;
    }

    public int GenerateIntegerInclusive()
    {
        return _random.Next(_min, _max + 1);
    }

    public float GenerateFloatInclusive()
    {
        return (float)(_random.NextDouble() * (_max - _min)) + _min;
    }

    public int GenerateIntegerExclusive()
    {
        return _random.Next(_min, _max);
    }

    public float GenerateFloatExclusive()
    {
        return (float)(_random.NextDouble() * (_max - _min)) + _min;
    }
}
