#include <openssl/evp.h>
#include <openssl/aes.h>
#include <openssl/rand.h>

EVP_CIPHER_CTX* initAESCipher(int keySize, int mode) {
    EVP_CIPHER_CTX *ctx = NULL;

    // Validate input parameters
    if (keySize != 128 && keySize != 192 && keySize != 256) {
        fprintf(stderr, "Invalid key size specified. Supported sizes are 128, 192 and 256 bits.\n");
        return NULL;
    }
    if (mode != EVP_aes_128_gcm() && mode != EVP_aes_192_cbc() && mode != EVP_aes_256_cbc()) {
        fprintf(stderr, "Invalid cipher mode specified. Supported modes are AES-128-GCM, AES-192-CBC and AES-256-CBC.\n");
        return NULL;
    }

    // Generate key and IV securely
    unsigned char *key = malloc(keySize / 8);
    if (RAND_bytes(key, keySize / 8) != 1) {
        fprintf(stderr, "Failed to generate random key.\n");
        return NULL;
    }
    unsigned char *iv = malloc(EVP_MAX_IV_LENGTH);
    if (RAND_bytes(iv, EVP_MAX_IV_LENGTH) != 1) {
        fprintf(stderr, "Failed to generate random IV.\n");
        free(key);
        return NULL;
    }

    // Initialize AES-GCM/CBC cipher context
    ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        fprintf(stderr, "Failed to create new cipher context.\n");
        free(key);
        free(iv);
        return NULL;
    }
    if (EVP_EncryptInit_ex(ctx, mode, NULL, key, iv) != 1) {
        fprintf(stderr, "Failed to initialize cipher context.\n");
        EVP_CIPHER_CTX_free(ctx);
        free(key);
        free(iv);
        return NULL;
    }

    // Set custom salt value during key derivation (if applicable)
    if (mode == EVP_aes_128_gcm() || mode == EVP_aes_192_cbc() || mode == EVP_aes_256_cbc()) {
        unsigned char *salt = malloc(EVP_MAX_IV_LENGTH);
        if (RAND_bytes(salt, EVP_MAX_IV_LENGTH) != 1) {
            fprintf(stderr, "Failed to generate random salt.\n");
            EVP_CIPHER_CTX_free(ctx);
            free(key);
            free(iv);
            return NULL;
        }
        if (EVP_CipherInit_ex(ctx, NULL, NULL, NULL, salt, -1) != 1) {
            fprintf(stderr, "Failed to set custom salt value.\n");
            EVP_CIPHER_CTX_free(ctx);
            free(key);
            free(iv);
            return NULL;
        }
    }

    // Clean up
    free(key);
    free(iv);

    // Return initialized cipher context
    return ctx;
}
