using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Azure.Storage.Blobs;
using Azure.Core;

public class MediaAssetManager
{
    private readonly BlobServiceClient _blobServiceClient;
    private readonly IConfiguration _configuration;

    public MediaAssetManager(IConfiguration configuration)
    {
        _configuration = configuration;

        // Create a new BlobServiceClient instance with the specified credentials and endpoint.
        var blobServiceClient = new BlobServiceClient(new Uri(_configuration["StorageAccount:ConnectionString"]));

        _blobServiceClient = blobServiceClient;
    }

    public async Task<UploadResult> UploadFileAsync(string filePath, string bucketName)
    {
        // Validate the input parameters.
        if (string.IsNullOrEmpty(filePath))
            throw new ArgumentException("The file path cannot be null or empty.", nameof(filePath));
        if (string.IsNullOrEmpty(bucketName))
            throw new ArgumentException("The bucket name cannot be null or empty.", nameof(bucketName));

        // Get the blob container client for the specified bucket.
        var blobContainerClient = _blobServiceClient.GetBlobContainerClient(bucketName);

        try
        {
            // Create a new blob client for the input file.
            var blobClient = blobContainerClient.GetBlobClient(filePath);

            // Upload the file to the cloud storage provider.
            await blobClient.UploadAsync(filePath);

            return new UploadResult(true, "The file was uploaded successfully.");
        }
        catch (Exception ex)
        {
            return new UploadResult(false, $"An error occurred while uploading the file: {ex.Message}");
        }
    }

    public async Task<UploadResult> UploadBytesAsync(byte[] bytes, string bucketName, string blobName = null)
    {
        // Validate the input parameters.
        if (bytes == null || bytes.Length == 0)
            throw new ArgumentException("The byte array cannot be null or empty.", nameof(bytes));
        if (string.IsNullOrEmpty(bucketName))
            throw new ArgumentException("The bucket name cannot be null or empty.", nameof(bucketName));

        // Get the blob container client for the specified bucket.
        var blobContainerClient = _blobServiceClient.GetBlobContainerClient(bucketName);

        try
        {
            // Create a new blob client for the input file.
            var blobClient = blobContainerClient.GetBlobClient(blobName ?? "blob");

            // Upload the byte array to the cloud storage provider.
            await blobClient.UploadAsync(bytes);

            return new UploadResult(true, "The byte array was uploaded successfully.");
        }
        catch (Exception ex)
        {
            return new UploadResult(false, $"An error occurred while uploading the byte array: {ex.Message}");
        }
    }

    public async Task<bool> DownloadFileAsync(string filePath, string bucketName)
    {
        // Validate the input parameters.
        if (string.IsNullOrEmpty(filePath))
            throw new ArgumentException("The file path cannot be null or empty.", nameof(filePath));
        if (string.IsNullOrEmpty(bucketName))
            throw new ArgumentException("The bucket name cannot be null or empty.", nameof(bucketName));

        // Get the blob container client for the specified bucket.
        var blobContainerClient = _blobServiceClient.GetBlobContainerClient(bucketName);

        try
        {
            // Create a new blob client for the input file.
            var blobClient = blobContainerClient.GetBlobClient(filePath);

            // Download the file from the cloud storage provider.
            await blobClient.DownloadToAsync(filePath);

            return true;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred while downloading the file: {ex.Message}");
            return false;
        }
    }

    public async Task<bool> DownloadBytesAsync(string bucketName, string blobName = null)
    {
        // Validate the input parameters.
        if (string.IsNullOrEmpty(bucketName))
            throw new ArgumentException("The bucket name cannot be null or empty.", nameof(bucketName));

        // Get the blob container client for the specified bucket.
        var blobContainerClient = _blobServiceClient.GetBlobContainerClient(bucketName);

        try
        {
            // Create a new blob client for the input file.
            var blobClient = blobContainerClient.GetBlobClient(blobName ?? "blob");

            // Download the byte array from the cloud storage provider.
