package com.example.chat;

import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import com.example.chat.protocols.WebSocketProtocol;
import com.example.chat.protocols.HttpLongPollingProtocol;
import com.example.chat.protocols.MessageQueue;
import com.example.chat.notifications.SmsNotificationService;
import com.example.chat.notifications.EmailNotificationService;

public class ChatBackendService {
  private static final Logger logger = LoggerFactory.getLogger(ChatBackendService.class);

  private Map<String, MessageQueue> messageQueues = new HashMap<>();
  private Map<String, ProtocolHandler> protocolHandlers = new HashMap<>();
  private NotificationService notificationService;
  private ScheduledExecutorService scheduledExecutorService;

  public ChatBackendService() {
    this.scheduledExecutorService = Executors.newSingleThreadScheduledExecutor();
    this.notificationService = new SmsNotificationService();
  }

  public void start() {
    // Initialize message queues and protocol handlers
    this.messageQueues.put("websocket", new MessageQueue(WebSocketProtocol.class));
    this.protocolHandlers.put("websocket", new WebSocketProtocol());

    this.messageQueues.put("http-long-polling", new MessageQueue(HttpLongPollingProtocol.class));
    this.protocolHandlers.put("http-long-polling", new HttpLongPollingProtocol());

    // Start message queue and protocol handler threads
    for (Map.Entry<String, MessageQueue> entry : this.messageQueues.entrySet()) {
      String protocol = entry.getKey();
      MessageQueue messageQueue = entry.getValue();
      ProtocolHandler protocolHandler = this.protocolHandlers.get(protocol);

      // Start message queue thread
      Thread messageQueueThread = new Thread(messageQueue);
      messageQueueThread.start();

      // Start protocol handler thread
      Thread protocolHandlerThread = new Thread(protocolHandler);
      protocolHandlerThread.start();
    }

    // Schedule notification service for sending notifications to users
    this.scheduledExecutorService.scheduleAtFixedRate(() -> {
      try {
        this.notificationService.sendNotifications();
      } catch (Exception e) {
        logger.error("Failed to send notifications", e);
      }
    }, 0, 10, TimeUnit.SECONDS);
  }

  public void stop() {
    // Stop message queue and protocol handler threads
    for (Map.Entry<String, MessageQueue> entry : this.messageQueues.entrySet()) {
      String protocol = entry.getKey();
      MessageQueue messageQueue = entry.getValue();
      ProtocolHandler protocolHandler = this.protocolHandlers.get(protocol);

      // Stop message queue thread
      messageQueue.stop();

      // Stop protocol handler thread
      protocolHandler.stop();
    }

    // Shut down notification service
    this.notificationService.shutdown();

    // Shut down scheduled executor service
    this.scheduledExecutorService.shutdown();
  }

  public void handleMessage(String message, String protocol) {
    MessageQueue messageQueue = this.messageQueues.get(protocol);
    ProtocolHandler protocolHandler = this.protocolHandlers.get(protocol);

    // Add message to message queue
    messageQueue.addMessage(message);

    // Notify protocol handler of new message
    protocolHandler.notifyNewMessage();
  }
}
```
This code implements a Java-based backend service for a real-time chat application that supports multiple messaging protocols (e.g., WebSocket, HTTP long-polling). The service dynamically switches between these protocols based on client capabilities and network conditions. It also ensures message queuing and delivery guarantees to prevent messages from being lost during server outages or network disruptions.

The `ChatBackendService` class is the main entry point for the service, and it manages a map of message queues and protocol handlers. The `start()` method initializes the service by starting the message queue and protocol handler threads, and scheduling the notification service to send notifications to users. The `stop()` method stops the message queue and protocol handler threads, and shuts down the scheduled executor service and notification service.

The `handleMessage(String message, String protocol)` method is called whenever a new message is received by the service. It adds the message to the appropriate message queue based on the protocol, and notifies the corresponding protocol handler of the new message.

The `MessageQueue` class is responsible for managing the messages in a specific protocol's message queue. It provides methods for adding and removing messages from the queue, as well as sending and receiving messages. The `ProtocolHandler` class handles the low-level communication with clients using a specific protocol (e.g., WebSocket or HTTP long-polling).

The `NotificationService` class is responsible for sending notifications to users when they receive messages while offline. It provides methods for adding and removing notification recipients, as well as sending notifications.

This codebase is designed to be modular and maintainable, allowing for easy updates to the protocol switching logic and notification service integrations. The use of a single-threaded scheduled executor service ensures that the notification service is properly synchronized with the message queue and protocol handler threads.

