import java.nio.channels.SocketChannel;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.Callable;

public class Character {
    private SocketChannel channel;
    private Map<String, Integer> attackCooldowns = new HashMap<>();
    private int energyLevel;

    public Character() {}

    public void connect(String hostname, int port) throws Exception {
        channel = SocketChannel.open();
        channel.connect(new InetSocketAddress(hostname, port));
    }

    public void disconnect() throws Exception {
        channel.close();
    }

    public void updateEnergyLevel(int newEnergyLevel) {
        energyLevel = newEnergyLevel;
    }

    public String selectAttack() {
        List<String> availableAttacks = Arrays.asList("attack1", "attack2", "attack3");
        int attackPower = 0;
        for (String attack : availableAttacks) {
            Integer cooldown = attackCooldowns.get(attack);
            if (cooldown == null || cooldown <= 0) {
                attackCooldowns.put(attack, getCooldownPeriod());
                return attack;
            }
            if (attackPower < getAttackPower(attack)) {
                attackPower = getAttackPower(attack);
            }
        }
        return "attack" + (energyLevel > 0 ? "" : "3");
    }

    public void sendAttackCommand(String attackType) throws Exception {
        channel.writeAndFlush(Unpooled.copiedBuffer("ATTACK " + attackType, CharsetUtil.UTF_8));
        attackCooldowns.put(attackType, getCooldownPeriod());
    }

    private int getAttackPower(String attack) {
        switch (attack) {
            case "attack1": return 50;
            case "attack2": return 80;
            case "attack3": return 100;
            default: throw new IllegalArgumentException("Invalid attack type");
        }
    }

    private int getCooldownPeriod() {
        int cooldown = (int) (Math.random() * 5 + 2); // Random value between 2 and 7
        return cooldown;
    }

    public void handleConnectionLoss(Throwable e) throws Exception {
        attackCooldowns.clear();
        channel.close();
    }

    public void handleAttackResponse(String response) {
        if (response.startsWith("ATTACK")) {
            String[] parts = response.split(" ");
            if (parts[1].equals("success")) {
                attackCooldowns.put(parts[2], getCooldownPeriod());
            } else {
                System.out.println("Attack " + parts[2] + " failed");
            }
        }
    }
}
