```c++
#include <iostream>
#include <vector>
#include <mutex>
#include <thread>
#include <condition_variable>
#include <unordered_map>
#include <algorithm>
#include <chrono>
#include <limits>

struct OctreeNode {
    std::unordered_map<int, int> data;
    std::vector<OctreeNode*> children;
    bool isLeaf;
};

class Octree {
public:
    Octree();
    ~Octree();

    void addData(const std::vector<int>& data);
    void updateData(const std::vector<int>& data);
    std::unordered_map<int, int> query(const std::vector<int>& queryData);
private:
    OctreeNode* root;
    std::mutex mutex;
    std::condition_variable cv;
    std::thread thread;
    bool isRunning;
};

Octree::Octree() {
    root = new OctreeNode();
    isRunning = true;
    thread = std::thread(&Octree::run, this);
}

Octree::~Octree() {
    delete root;
}

void Octree::addData(const std::vector<int>& data) {
    std::lock_guard<std::mutex> lock(mutex);
    if (!isRunning) return;
    updateData(data, root);
}

void Octree::updateData(const std::vector<int>& data, OctreeNode* node) {
    for (auto& item : data) {
        auto it = node->data.find(item);
        if (it == node->data.end()) {
            node->data[item]++;
        } else {
            it->second++;
        }
    }
}

std::unordered_map<int, int> Octree::query(const std::vector<int>& queryData) {
    std::lock_guard<std::mutex> lock(mutex);
    if (!isRunning) return {};
    auto result = queryInternal(queryData, root);
    cv.notify_all();
    return result;
}

void Octree::run() {
    while (isRunning) {
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock);
        if (!isRunning) break;
        updateDataInternal(root);
    }
}

void Octree::updateDataInternal(OctreeNode* node) {
    for (auto& item : node->data) {
        auto it = node->data.find(item);
        if (it == node->data.end()) {
            node->data[item]++;
        } else {
            it->second++;
        }
    }
}

std::unordered_map<int, int> Octree::queryInternal(const std::vector<int>& queryData, OctreeNode* node) {
    std::unordered_map<int, int> result;
    for (auto& item : queryData) {
        auto it = node->data.find(item);
        if (it != node->data.end()) {
            result[item]++;
        }
        if (!node->isLeaf && !queryData.empty()) {
            for (auto& child : node->children) {
                auto childResult = queryInternal(queryData, child);
                for (auto& entry : childResult) {
                    result[entry.first] += entry.second;
                }
            }
        }
    }
    return result;
}
