import java.io.FileInputStream;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class FileProcessor {
    public static String processFileChunksParallelly(String fileName, int chunkSize, int numWorkers) throws IOException {
        // Create an executor service with the specified number of worker threads
        ExecutorService executor = Executors.newFixedThreadPool(numWorkers);

        // Initialize a list to store the results of each chunk processing task
        List<ChunkProcessingResult> results = new ArrayList<>();

        try (FileInputStream fileStream = new FileInputStream(fileName)) {
            // Get the size of the file in bytes
            long fileSize = fileStream.available();

            // Divide the file into manageable chunks based on the chunk size
            int numChunks = (int)Math.ceil(fileSize / (double)chunkSize);

            // Create a list of Callable tasks for each chunk processing task
            List<Callable<ChunkProcessingResult>> tasks = new ArrayList<>();
            for (int i = 0; i < numChunks; i++) {
                int startPosition = i * chunkSize;
                int endPosition = Math.min(startPosition + chunkSize, fileSize);
                Callable<ChunkProcessingResult> task = new ChunkProcessingTask(fileStream, startPosition, endPosition);
                tasks.add(task);
            }

            // Submit the tasks to the executor service and wait for them to complete
            List<Future<ChunkProcessingResult>> futures = executor.invokeAll(tasks);

            // Collect the results of each task from the futures
            for (Future<ChunkProcessingResult> future : futures) {
                ChunkProcessingResult result = future.get();
                if (result.isSuccessful()) {
                    results.add(result);
                } else {
                    System.err.println("Failed to process chunk: " + result.getErrorMessage());
                }
            }
        } catch (InterruptedException | ExecutionException e) {
            System.err.println("Error processing file chunks: " + e.getMessage());
        } finally {
            executor.shutdown();
        }

        // Log the results to a specified file and return them as a string for further analysis
        String report = "";
        for (ChunkProcessingResult result : results) {
            report += result.getErrorMessage() + "\n";
        }
        FileUtils.writeStringToFile(report, "file-processing-report.txt");
        return report;
    }
}
