function processClinicUpdates($clinic_ids, $new_statuses) {
  // Start a transaction
  $conn = new mysqli($servername, $username, $password, $dbname);
  $conn->begin_transaction(MYSQLI_TRANS_START_READ_WRITE);

  // Detect and prevent bulk updates from a single source IP within a short time frame
  $ip = $_SERVER['REMOTE_ADDR'];
  $last_update = getLastUpdateTime($ip);
  if ($last_update !== false && (time() - $last_update) < 60 * 15) { // 15 minutes
    return "ERROR: Bulk updates from this IP are not allowed within a short time frame. Please try again later.";
  }

  // Update multiple clinics in a single transaction to minimize the risk of partial updates
  foreach ($clinic_ids as $key => $id) {
    $sql = "UPDATE clinics SET status = ? WHERE id = ?";
    if (!$stmt = $conn->prepare($sql)) {
      return "ERROR: Could not prepare statement. " . $conn->error;
    }

    // Set the parameters and execute the statement
    $new_status = $new_statuses[$key];
    $stmt->bind_param("si", $new_status, $id);
    if (!$stmt->execute()) {
      return "ERROR: Could not execute statement. " . $conn->error;
    }

    // Log the update and send a notification to the clinic administrator
    $old_status = $conn->query("SELECT status FROM clinics WHERE id = ?", $id);
    if ($old_status === false) {
      return "ERROR: Could not retrieve old status. " . $conn->error;
    }

    // Send a notification to the clinic administrator
    $email = getClinicAdminEmail($id);
    $body = "The clinic with ID {$id} has been updated from '{$old_status}' to '{$new_status}'.";
    sendEmail($email, $body);
  }

  // Commit the transaction and return a success message
  if ($conn->commit()) {
    return "SUCCESS: Clinic updates have been successfully processed.";
  } else {
    return "ERROR: Could not commit changes to the database. " . $conn->error;
  }
}

// Get the last update time for a specific IP address
function getLastUpdateTime($ip) {
  // Connect to the database
  $conn = new mysqli($servername, $username, $password, $dbname);

  // Query the database for the last update time
  $sql = "SELECT MAX(timestamp) FROM updates WHERE ip_address = ?";
  if (!$stmt = $conn->prepare($sql)) {
    return false;
  }

  // Set the parameters and execute the statement
  $stmt->bind_param("s", $ip);
  if (!$stmt->execute()) {
    return false;
  }

  // Retrieve the results
  $result = $stmt->get_result();
  if ($row = $result->fetch_assoc()) {
    return $row["MAX(timestamp)"];
  } else {
    return false;
  }
}

// Get the email address of the clinic administrator for a specific clinic ID
function getClinicAdminEmail($id) {
  // Connect to the database
  $conn = new mysqli($servername, $username, $password, $dbname);

  // Query the database for the clinic administrator's email address
  $sql = "SELECT email FROM clinics WHERE id = ?";
  if (!$stmt = $conn->prepare($sql)) {
    return false;
  }

  // Set the parameters and execute the statement
  $stmt->bind_param("i", $id);
  if (!$stmt->execute()) {
    return false;
  }

  // Retrieve the results
  $result = $stmt->get_result();
  if ($row = $result->fetch_assoc()) {
    return $row["email"];
  } else {
    return false;
  }
}

// Send an email notification to a clinic administrator
function sendEmail($to, $body) {
  // Connect to the email server
  $host = "smtp.example.com";
  $username = "user@example.com";
  $password = "password";

  // Set the email headers
  $from = "no-reply@example.com";
  $subject = "Clinic Status Update Notification";
  $headers = "From: {$from}\r\nReply-To: {$from}\r\nX-Mailer: PHP/" . phpversion();

  // Send the email using SMTP
  if (!mail($to, $subject, $body, $headers)) {
    return false;
  } else {
    return true;
  }
}
