                {
                    if (column != null && !this.schemaDefinition.ContainsKey(column))
                    {
                        // Handle missing values
                        continue;
                    }

                    // Normalize data based on schema definition
                    var value = row[column];
                    switch (value.GetType().Name)
                    {
                        case "Int32":
                            // Convert to float if necessary
                            break;
                        case "String":
                            // Convert to lowercase and trim whitespace if necessary
                            break;
                    }
                }
            }

            return data;
        }

        // ValidateSchema method
        public bool ValidateSchema(List<Dictionary<string, object>> data)
        {
            foreach (var row in data)
            {
                foreach (var column in row.Keys)
                {
                    if (!this.schemaDefinition.ContainsKey(column))
                    {
                        // Validation failed
                        return false;
                    }
                }
            }

            return true;
        }

        // GetSampleData method
        public List<Dictionary<string, object>> GetSampleData()
        {
            var sampleSize = 1000;
            if (data.Count < sampleSize)
            {
                sampleSize = data.Count;
            }

            return data.OrderBy(x => Guid.NewGuid()).Take(sampleSize).ToList();
        }

        // SavePreprocessedData method
        public void SavePreprocessedData(string path)
        {
            using (var writer = new StreamWriter(path))
            {
                foreach (var row in preprocessedData)
                {
                    var line = string.Join(",", row.Keys);
                    writer.WriteLine(line);
                }
            }
        }

        // ToString method override
        public override string ToString()
        {
            return $"{this.dataSourceType} | {this.connectionString} | {this.schemaDefinition}";
        }
    }
}
