#define MAX_NUM_RECORDS 10000
#define MIN_RANDOM_VALUE 1
#define MAX_RANDOM_VALUE 1000
#define DEFAULT_CONCURRENCY_LEVEL 5
#define DEFAULT_CACHING_STRATEGY "lru"
#define DEFAULT_VCS_PROVIDER "git"
#define DEFAULT_VCS_POLLING_INTERVAL 30
#define DEFAULT_LOGGING_LEVEL "info"

