typedef struct file_list {
    char** files;
    size_t num_files;
} file_list;

typedef struct loaded_file {
    char* filename;
    int status;
} loaded_file;

void load_javascript_files(char** files, size_t num_files, int concurrency_level) {
    // Initialize the list of loaded files
    loaded_file* loaded_files = malloc(sizeof(loaded_file*) * num_files);
    for (int i = 0; i < num_files; i++) {
        loaded_files[i].filename = files[i];
        loaded_files[i].status = -1; // status of -1 means the file is not yet loaded
    }

    // Initialize the list of pending files
    char** pending_files = malloc(sizeof(char*) * num_files);
    for (int i = 0; i < num_files; i++) {
        pending_files[i] = files[i];
    }

    // Load and execute the JavaScript files concurrently
    int num_loaded_files = 0;
    while (num_loaded_files < num_files) {
        for (int i = 0; i < concurrency_level && pending_files[i]; i++) {
            loaded_file* file = &loaded_files[i];
            char* filename = pending_files[i];

            // Load the JavaScript file
            FILE* fp = fopen(filename, "r");
            if (!fp) {
                printf("Failed to open file %s: %s\n", filename, strerror(errno));
                file->status = -1;
                continue;
            }
            fseek(fp, 0, SEEK_END);
            long length = ftell(fp);
            rewind(fp);
            char* buffer = malloc(length + 1);
            size_t read_count = fread(buffer, 1, length, fp);
            if (read_count != length) {
                printf("Failed to read file %s: %s\n", filename, strerror(errno));
                file->status = -1;
                continue;
            }
            buffer[length] = '\0';
            fclose(fp);

            // Execute the JavaScript code
            int result = execute_javascript_code(buffer);
            if (result != 0) {
                printf("Failed to execute file %s: %s\n", filename, strerror(errno));
                file->status = -1;
                continue;
            }

            // Mark the file as loaded
            file->status = 1;
            num_loaded_files++;
        }

        // Remove the loaded files from the pending list
        for (int i = 0; i < concurrency_level && pending_files[i]; i++) {
            char* filename = pending_files[i];
            int found = 0;
            for (int j = 0; j < num_loaded_files && !found; j++) {
                loaded_file* file = &loaded_files[j];
                if (!strcmp(filename, file->filename)) {
                    found = 1;
                }
            }
            if (found) {
                memmove(&pending_files[i], &pending_files[i + 1], sizeof(char*) * (num_files - i));
                num_files--;
            } else {
                i++;
            }
        }
    }

    // Clean up the memory
    free(loaded_files);
    free(pending_files);
}

