using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Threading;
using System.Threading.Tasks;

namespace EncryptionConsoleApp
{
    class Program
    {
        static async Task Main(string[] args)
        {
            // Check if web.config file exists in the directory
            var webConfigFilePath = Path.Combine(Directory.GetCurrentDirectory(), "web.config");
            if (!File.Exists(webConfigFilePath))
            {
                Console.WriteLine("Error: web.config file not found.");
                return;
            }

            // Load the web.config file and validate site names against naming conventions
            var config = ConfigurationManager.OpenExeConfiguration(webConfigFilePath);
            var sites = new List<string>();
            foreach (var site in config.AppSettings.Settings)
            {
                if (!IsValidSiteName(site.Key))
                {
                    Console.WriteLine($"Error: invalid site name '{site.Key}'");
                    return;
                }
                sites.Add(site.Value);
            }

            // Verify that directory paths are valid and accessible
            foreach (var path in args)
            {
                if (!Directory.Exists(path))
                {
                    Console.WriteLine($"Error: directory '{path}' not found.");
                    return;
                }
            }

            // Initialize the OpenSSL library with specified cipher and mode options
            using (var openssl = new Openssl())
            {
                var cipher = "aes-256-cbc";
                var mode = CipherMode.CBC;
                var keySize = 32; // in bytes
                var ivSize = 16; // in bytes
                openssl.Initialize(cipher, mode, keySize, ivSize);

                // Load the secure key storage mechanism and the log file for auditing purposes
                using (var keyStorage = new KeyStorage())
                {
                    var key = await keyStorage.LoadKeyAsync();
                    var logFilePath = Path.Combine(Directory.GetCurrentDirectory(), "encryption-log.txt");
                    using (var logFile = File.AppendText(logFilePath))
                    {
                        // Iterate over the input file paths and encrypt each file in parallel using a dynamic work-stealing algorithm
                        foreach (var path in args)
                        {
                            var fileSize = new FileInfo(path).Length;
                            Console.WriteLine($"Encrypting '{path}' ({fileSize} bytes)");

                            // Load the file and get its MD5 checksum before encryption
                            using (var inputStream = File.OpenRead(path))
                            {
                                var md5Hash = MD5.Create();
                                var hashBytes = await md5Hash.ComputeHashAsync(inputStream);
                                var hashString = BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
                                logFile.WriteLine($"{path}: {hashString}");
                            }

                            // Encrypt the file using the OpenSSL library and save it to a new file with a ".encrypted" extension
                            using (var inputStream = File.OpenRead(path))
                            using (var encryptedOutputStream = File.Create($"{path}.encrypted"))
                            {
                                await openssl.EncryptAsync(inputStream, encryptedOutputStream, key);
                            }

                            // Check the file's MD5 checksum after encryption to ensure it has not been modified during encryption
                            using (var inputStream = File.OpenRead($"{path}.encrypted"))
                            {
                                var md5Hash = MD5.Create();
                                var hashBytes = await md5Hash.ComputeHashAsync(inputStream);
                                var hashString = BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
                                if (hashString != logFile[path])
                                {
                                    Console.WriteLine($"Error: file '{path}' has been modified during encryption.");
                                }
                            }
                        }
                    }
                }
            }
        }

        private static bool IsValidSiteName(string siteName)
        {
            return !string.IsNullOrWhiteSpace(siteName) && Regex.IsMatch(siteName, @"^[a-z0-9_]+$");
        }
    }
}
