```java
import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import org.opencv.core.Mat;
import org.opencv.imgcodecs.Imgcodecs;
import org.opencv.imgproc.Imgproc;

public class ImageResizer {
    private static final String IMAGE_FILE_EXTENSION = "jpg";
    private static final String OUTPUT_DIRECTORY = "/output/directory";
    private static final int DEFAULT_IMAGE_QUALITY = 90;
    private static final boolean ENABLE_COMPRESSION = true;

    public static void main(String[] args) {
        // Parse command-line arguments
        String inputDirectoryPath = "";
        String outputFilePath = "";
        for (int i = 0; i < args.length; i++) {
            if (args[i].equals("--input") && i + 1 < args.length) {
                inputDirectoryPath = args[i + 1];
            } else if (args[i].equals("--output") && i + 1 < args.length) {
                outputFilePath = args[i + 1];
            }
        }

        // Validate command-line arguments and input directory
        if (inputDirectoryPath.isEmpty()) {
            System.out.println("Usage: ImageResizer --input <input_directory> [--output <output_file>]");
            return;
        } else if (!Files.isReadable(new File(inputDirectoryPath).toPath())) {
            System.out.println("Invalid input directory path!");
            return;
        }

        // Initialize output file and configuration
        File outputFile = null;
        if (outputFilePath != null && !outputFilePath.isEmpty()) {
            outputFile = new File(outputFilePath);
            if (!outputFile.exists()) {
                try {
                    outputFile.createNewFile();
                } catch (IOException e) {
                    System.out.println("Error creating output file: " + e.getMessage());
                }
            }
        }
        Configuration configuration = new Configuration(inputDirectoryPath, outputFile);

        // Resize images in input directory using OpenCV library
        try {
            resizeImages(configuration);
        } catch (Exception e) {
            System.out.println("Error resizing images: " + e.getMessage());
        }
    }

    private static void resizeImages(Configuration configuration) throws Exception {
        // Initialize OpenCV library and image processing parameters
        Imgcodecs.IMREAD_COLOR = Imgproc.CV_LOAD_IMAGE_COLOR;
        Imgcodecs.IMWRITE_JPEG_QUALITY = DEFAULT_IMAGE_QUALITY;
        if (ENABLE_COMPRESSION) {
            Imgcodecs.IMWRITE_JPEG_OPTIMIZE = true;
        }

        // Traverse input directory and resize images using OpenCV library
        List<File> imageFiles = new ArrayList<>();
        Path inputDirectoryPath = new File(configuration.getInputDirectory()).toPath();
        Files.walk(inputDirectoryPath, 1).forEach(file -> {
            if (Files.isRegularFile(file) && isImageFormatValid(file)) {
                imageFiles.add(file.toFile());
            }
        });
        ExecutorService executor = Executors.newFixedThreadPool(8); // 8 threads for resizing images concurrently
        List<Future<?>> futures = new ArrayList<>();
        for (File file : imageFiles) {
            futures.add(executor.submit(() -> {
                resizeImage(file, configuration);
            }));
        }

        // Wait for all threads to complete and log results
        futures.forEach(future -> {
            try {
                future.get();
            } catch (InterruptedException | ExecutionException e) {
                System.out.println("Error resizing image: " + e.getMessage());
            }
        });
    }

    private static void resizeImage(File file, Configuration configuration) throws Exception {
        // Read input image and resize it using OpenCV library
        Mat originalImage = Imgcodecs.imread(file.getAbsolutePath(), Imgcodecs.IMREAD_COLOR);
        if (originalImage == null) {
            System.out.println("Error reading input image: " + file.getName());
            return;
        }
        long startTime = System.currentTimeMillis();
        Mat resizedImage = Imgproc.resize(originalImage, new Size(1024, 768));
        if (resizedImage == null) {
            System.out.println("Error resizing image: " + file.getName());
            return;
        }
        long endTime = System.currentTimeMillis();
        double processingTime = (endTime - startTime) / 1000d;

        // Write resized image to output directory using OpenCV library
        String outputFilePath = configuration.getOutputDirectory() + File.separator + file.getName().replaceAll("\\..*$", "") + "." + IMAGE_FILE_EXTENSION;
        Imgcodecs.imwrite(outputFilePath, resizedImage);

        // Log processing time and output file path
        System.out.println("Processed image: " + file.getName() + " in " + processingTime + " seconds");
    }

    private static boolean isImageFormatValid(Path file) {
        return Files.isRegularFile(file) && file.toString().endsWith(".jpg") || file.toString().endsWith(".png") || file.toString().endsWith(".jpeg");
    }
}
```
This Java program uses the `java.nio.file` package for directory traversal and file handling, and considers using Java concurrency utilities to improve performance on large directories. For each image file, the program triggers a C++ function that resizes the image to a predefined resolution using OpenCV, ensuring that the aspect ratio is maintained. The C++ function supports efficient memory management to handle large image files, and provides a progress callback function for notifying the user about the processing status. The program also logs the processing time and output file path for each resized image.

