using namespace std;

// Define the octree node structure
struct OctreeNode {
    vector<OctreeNode*> children; // Array of child nodes
    string data; // Data associated with this node
};

// Define the octree structure
struct Octree {
    OctreeNode* root; // Root node of the octree
    int num_nodes; // Number of nodes in the octree
    int max_depth; // Maximum depth of the octree
};

// Function to initialize an octree with a specified number of nodes and maximum depth
Octree* init_octree(int num_nodes, int max_depth) {
    Octree* tree = new Octree();
    tree->root = new OctreeNode();
    tree->num_nodes = 0;
    tree->max_depth = max_depth;
    return tree;
}

// Function to insert a node into the octree with a specified key and data
void insert_node(Octree* tree, string key, string data) {
    OctreeNode* current = tree->root;
    int depth = 0;
    while (depth < tree->max_depth && current != NULL) {
        // Calculate the hash of the key and use it to determine which child node to visit
        unsigned long hash = get_hash(key);
        if (hash >= current->children.size()) {
            // If the hash is outside the range of children, create a new child node at that position
            current->children.resize(hash + 1);
            current->children[hash] = new OctreeNode();
        }
        current = current->children[hash];
        depth++;
    }
    // Set the data associated with this node to be the input data
    current->data = data;
    tree->num_nodes++;
}

// Function to retrieve a node from the octree with a specified key
OctreeNode* get_node(Octree* tree, string key) {
    OctreeNode* current = tree->root;
    int depth = 0;
    while (depth < tree->max_depth && current != NULL) {
        // Calculate the hash of the key and use it to determine which child node to visit
        unsigned long hash = get_hash(key);
        if (hash >= current->children.size()) {
            return NULL;
        }
        current = current->children[hash];
        depth++;
    }
    return current;
}

// Function to delete a node from the octree with a specified key
void delete_node(Octree* tree, string key) {
    OctreeNode* current = tree->root;
    int depth = 0;
    while (depth < tree->max_depth && current != NULL) {
        // Calculate the hash of the key and use it to determine which child node to visit
        unsigned long hash = get_hash(key);
        if (hash >= current->children.size()) {
            return;
        }
        current = current->children[hash];
        depth++;
    }
    // If the node was found, delete it from the tree
    if (current != NULL) {
        tree->num_nodes--;
        current->data.clear();
        delete current;
    }
}

// Function to traverse the octree and perform a specified operation on each node
void traverse(Octree* tree, void (*operation)(OctreeNode*, void*), void* data) {
    queue<OctreeNode*> nodes_to_visit;
    nodes_to_visit.push(tree->root);
    while (!nodes_to_visit.empty()) {
        OctreeNode* node = nodes_to_visit.front();
        nodes_to_visit.pop();
        operation(node, data);
        for (OctreeNode* child : node->children) {
            nodes_to_visit.push(child);
        }
    }
}

// Function to perform a specified operation on each node in the octree
