        }
    }
    return result;
}

// Function to get the hash of a string using AES encryption
unsigned long get_hash(string str) {
    // Use AES encryption to generate a hash from the input string
    unsigned char key[16];
    for (int i = 0; i < 16; i++) {
        key[i] = rand() % 256;
    }
    AES_KEY aes_key;
    AES_set_encrypt_key(key, sizeof(key), &aes_key);
    unsigned char plaintext[16];
    for (int i = 0; i < str.length(); i++) {
        plaintext[i] = str[i];
    }
    AES_encrypt(plaintext, key);
    return *((unsigned long*)key);
}

// Function to get the hash of a string using SHA-256 encryption
unsigned long get_hash(string str) {
    // Use SHA-256 encryption to generate a hash from the input string
    unsigned char key[32];
    for (int i = 0; i < 32; i++) {
        key[i] = rand() % 256;
    }
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, str.c_str(), str.length());
    SHA256_Final(key, &ctx);
    return *((unsigned long*)key);
}
```

