    public FileProcessor(int threadPoolSize) {
        this.threadPoolSize = threadPoolSize;
        this.executor = Executors.newFixedThreadPool(threadPoolSize);
    }

    public void processFileBatchWithValidation(String inputDirectory, String outputDirectory, List<Rule> validationRules) {
        executor.execute(() -> {
            try {
                File[] files = new File(inputDirectory).listFiles();
                for (File file : files) {
                    if (file.isFile()) {
                        String fileName = file.getName();
                        boolean validationPassed = false;
                        for (Rule rule : validationRules) {
                            try {
                                rule.validate(fileName);
                                validationPassed = true;
                                break;
                            } catch (Exception e) {
                                // Handle exception gracefully
                            }
                        }

                        if (!validationPassed) {
                            System.out.println("Validation failed for file " + fileName);
                        } else {
                            System.out.println("Validation passed for file " + fileName);
                        }
                    }
                }
            } catch (Exception e) {
                // Handle exception gracefully
            } finally {
                executor.shutdown();
            }
        });
    }
}

