#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <unordered_map>
#include <set>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <memory>
#include <future>
#include <random>

using namespace std;

class Ability {
public:
    string name;
    int level;
    set<string> requirements;
};

class Player {
public:
    string name;
    int level;
    set<string> roles;
    unordered_map<string, Ability> abilities;
};

class AbilityDatabase {
public:
    void update(const vector<Player>& players) {
        // Query the external ability database via RESTful API and get JSON payload
        auto json = queryAbilityDatabase();

        // Parse the JSON payload into a map of ability names to levels
        unordered_map<string, int> abilities;
        for (const auto& player : players) {
            for (const auto& ability : player.abilities) {
                abilities[ability.first] = ability.second.level;
            }
        }

        // Update the cached ability levels and requirements
        for (auto& it = abilities_.begin(); it != abilities_.end(); ++it) {
            if (it->second != abilities.find(it->first)->second) {
                it->second = abilities[it->first];
                break;
            }
        }
    }

private:
    unordered_map<string, int> abilities_;
};

class AbilityAssigner {
public:
    void assignAbilities(vector<Player>& players) {
        // Create a cache of all available abilities in the game
        unordered_map<string, Ability> cache;
        for (const auto& ability : abilities_) {
            cache[ability.first] = ability.second;
        }

        // Assign abilities to players based on their level and team composition
        for (auto& player : players) {
            unordered_map<string, int> requirements;
            for (const auto& role : player.roles) {
                const auto& it = cache.find(role);
                if (it != cache.end()) {
                    requirements[role] = it->second.level;
                }
            }

            // Iterate through the abilities and find the first one that satisfies all requirements
            for (const auto& ability : cache) {
                bool meetsRequirements = true;
                for (const auto& req : ability.second.requirements) {
                    const auto& it = requirements.find(req);
                    if (it == requirements.end() || it->second < cache[req].level) {
                        meetsRequirements = false;
                        break;
                    }
                }

                if (meetsRequirements) {
                    player.abilities[ability.first] = ability.second;
                    break;
                }
            }
        }
    }

private:
    unordered_map<string, Ability> abilities_;
};

class WebSocketServer {
public:
    void update(const vector<Player>& players) {
        // Send the updated ability information to all connected clients
        for (auto& client : clients_) {
            sendUpdate(client.get(), players);
        }
    }

private:
    vector<unique_ptr<Client>> clients_;
};

class Client {
public:
