            for (const auto& player : json["players"]) {
                Player p;
                p.name = player["name"].asString();
                p.level = player["level"].asInt();
                p.roles = player["roles"].asArray<string>();
                players.push_back(p);
            }
            abilityAssigner_.assignAbilities(players);
        }
    }

private:
    AbilityAssigner abilityAssigner_;
};
