    for (const auto& attackName : attackNames) {
        if (attackDatabase.find(attackName) != attackDatabase.end()) {
            optimalAttack = attackName;
            break;
        }
    }

    // Release the lock on the cache mutex before returning
    lck.unlock();

    return optimalAttack;
}

void updateCachedAttacks() {
    // Create a new cache of the attack database
    auto start = chrono::high_resolution_clock::now();
    unordered_map<string, string> newCache;
    for (const auto& [attackName, attackInfo] : attackDatabase) {
        newCache[attackName] = attackInfo;
    }
    cachedAttacks = move(newCache);
    auto end = chrono::high_resolution_clock::now();
    cout << "Updated attacks in " << chrono::duration<double>(end - start).count() << " seconds" << endl;

    // Notify all threads waiting for the attack cache to be populated
    cvAttacksCached.notify_all();
}

