import os
import tempfile
from typing import List

class DirectoryManager:
    def __init__(self):
        self.directories = {}

    def create_directory(self, name: str) -> str:
        if name in self.directories:
            return None
        else:
            directory = tempfile.mkdtemp()
            self.directories[name] = directory
            return directory

    def get_directory(self, name: str) -> str:
        return self.directories[name] if name in self.directories else None

    def delete_directory(self, name: str) -> bool:
        try:
            os.rmdir(self.get_directory(name))
            del self.directories[name]
            return True
        except OSError as e:
            print(f"Error deleting directory {name}: {e}")
            return False

    def list_directories(self) -> List[str]:
        return list(self.directories.keys())

class EnvironmentVariableManager:
    def __init__(self):
        self.variables = {}

    def set_variable(self, name: str, value: str) -> bool:
        if name in self.variables:
            self.variables[name] = value
            return True
        else:
            print(f"Error setting environment variable {name}: {value}")
            return False

    def get_variable(self, name: str) -> str:
        return self.variables[name] if name in self.variables else None

    def delete_variable(self, name: str) -> bool:
        try:
            del self.variables[name]
            return True
        except KeyError as e:
            print(f"Error deleting environment variable {name}: {e}")
            return False

    def list_variables(self) -> List[str]:
        return list(self.variables.keys())
```
