struct CryptographicHashFunction {
    char *name;
    void *implementation;
};

static int is_available(const struct CryptographicHashFunction *hash) {
    return hash->implementation != NULL;
}

static void free_cryptographic_hash_function(struct CryptographicHashFunction *hash) {
    if (hash == NULL) {
        return;
    }
    if (hash->implementation != NULL) {
        OPENSSL_free(hash->implementation);
    }
    free(hash);
}

static void print_cryptographic_hash_functions(const struct CryptographicHashFunction *hashes, size_t n_hashes) {
