        printf("%s\n", hashes[i].name);
    }
}

static void print_cryptographic_ciphers(const struct CryptographicHashFunction *ciphers, size_t n_ciphers) {
    for (size_t i = 0; i < n_ciphers; i++) {
        printf("%s\n", ciphers[i].name);
    }
}

static struct CryptographicHashFunction *get_cryptographic_hash_functions() {
