        hashes[i].implementation = OPENSSL_malloc(sizeof(EVP_MD));
        if (hashes[i].implementation == NULL) {
            free_cryptographic_hash_function(hashes);
            return NULL;
        }
    }
    return hashes;
}

static struct CryptographicHashFunction *get_cryptographic_ciphers() {
    const int MAX_CIPHERS = 10;
    struct CryptographicHashFunction *ciphers = malloc(MAX_CIPHERS * sizeof(*ciphers));
    if (ciphers == NULL) {
        return NULL;
    }
    for (int i = 0; i < MAX_CIPHERS; i++) {
        ciphers[i].name = "AES";
        ciphers[i].implementation = OPENSSL_malloc(sizeof(EVP_CIPHER));
        if (ciphers[i].implementation == NULL) {
            free_cryptographic_hash_function(ciphers);
            return NULL;
        }
    }
    return ciphers;
}

int main() {
    struct CryptographicHashFunction *hashes = get_cryptographic_hash_functions();
    if (hashes == NULL) {
        fprintf(stderr, "Error: unable to obtain cryptographic hash functions\n");
        return 1;
    }
