public class ServiceCluster {
    private static final Logger LOGGER = Logger.getLogger(ServiceCluster.class.getName());

    // Map of service instances to their heartbeat timestamps
    private ConcurrentHashMap<String, Long> instanceHeartbeats = new ConcurrentHashMap<>();

