                // Simulate time taken to start instance
                TimeUnit.SECONDS.sleep(10);
                LOGGER.info("Started instance " + instance);
                instanceHeartbeats.put(instance, System.currentTimeMillis());
            } catch (InterruptedException e) {
                LOGGER.log(Level.WARNING, "Failed to start instance", e);
            }
        });
    }

    /**
     * Stop a service instance in the cluster.
     */
    public void stopInstance(String instance) {
        executorService.execute(() -> {
            try {
                // Simulate time taken to stop instance
                TimeUnit.SECONDS.sleep(10);
                LOGGER.info("Stopped instance " + instance);
                instanceHeartbeats.remove(instance);
            } catch (InterruptedException e) {
                LOGGER.log(Level.WARNING, "Failed to stop instance", e);
            }
        });
    }

    /**
     * Send heartbeat messages at regular intervals to monitor the health of each service instance.
     */
    public void sendHeartbeats() {
        for (String instance : instances) {
            executorService.execute(() -> {
                try {
                    // Simulate time taken to send heartbeat
                    TimeUnit.SECONDS.sleep(10);
                    LOGGER.info("Sent heartbeat to instance " + instance);
                    Long lastHeartbeat = instanceHeartbeats.get(instance);
                    if (lastHeartbeat == null || System.currentTimeMillis() - lastHeartbeat > TimeUnit.SECONDS.toMillis(retryInterval)) {
                        LOGGER.log(Level.WARNING, "Missed heartbeat from instance " + instance);
                        // Trigger failover mechanism here
                    } else {
                        instanceHeartbeats.put(instance, System.currentTimeMillis());
                    }
                } catch (InterruptedException e) {
                    LOGGER.log(Level.WARNING, "Failed to send heartbeat", e);
                }
            });
        }
    }

    /**
     * Load balance across service instances using a load balancing strategy.
     */
    public String getNextInstance() {
        return loadBalancingStrategy.getNextInstance(instances, instanceHeartbeats);
    }
}
