import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Level;
import java.util.logging.Logger;

public class RoundRobinLoadBalancingStrategy implements LoadBalancingStrategy {
    private static final Logger LOGGER = Logger.getLogger(RoundRobinLoadBalancingStrategy.class.getName());

    // Map of service instances to their load balancing weights
    private ConcurrentHashMap<String, Integer> instanceWeights = new ConcurrentHashMap<>();

    /**
     * Update the load balancing weights for each instance in the cluster.
     */
    @Override
    public void updateLoadBalancingWeights(List<String> instances) {
        for (String instance : instances) {
            if (!instanceWeights.containsKey(instance)) {
                instanceWeights.put(instance, 0);
            }
        }
        LOGGER.info("Updated load balancing weights");
    }

    /**
     * Get the next service instance to be used for a request based on the current load balancing strategy.
     */
    @Override
    public String getNextInstance(List<String> instances, ConcurrentHashMap<String, Long> instanceHeartbeats) {
        List<String> availableInstances = new ArrayList<>();
        for (String instance : instances) {
            if (!instanceHeartbeats.containsKey(instance)) {
                availableInstances.add(instance);
            }
        }
        int nextIndex = 0;
        while (true) {
            String nextInstance = availableInstances.get(nextIndex);
            LOGGER.info("Next instance to be used: " + nextInstance);
            if (!instanceWeights.containsKey(nextInstance)) {
                instanceWeights.put(nextInstance, 0);
            }
            int weight = instanceWeights.get(nextInstance) + 1;
            instanceWeights.put(nextInstance, weight);
            nextIndex = (nextIndex + 1) % availableInstances.size();
            if (!availableInstances.isEmpty()) {
                return nextInstance;
            } else {
                LOGGER.log(Level.WARNING, "No instances available for load balancing");
                // Trigger failover mechanism here
            }
        }
    }
}
