import java.io.IOException;
import java.nio.channels.AsynchronousSocketChannel;
import java.security.KeyStore;
import java.security.NoSuchAlgorithmException;
import java.security.UnrecoverableKeyException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import javax.net.ssl.SSLContext;
import javax.net.ssl.SSLEngine;
import javax.net.ssl.TrustManagerFactory;
import org.apache.http.conn.ssl.NoopHostnameVerifier;
import org.apache.http.conn.ssl.TrustSelfSignedStrategy;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class ConnectionManager {
  private static final Logger LOGGER = LoggerFactory.getLogger(ConnectionManager.class);

  // Configuration parameters
  private int maxConnections = 5000;
  private long idleTimeout = 60 * 1000; // 1 minute
  private ExecutorService executor = Executors.newCachedThreadPool();
  private List<AsynchronousSocketChannel> channels = new ArrayList<>();

  /**
   * Creates a new connection manager instance with the specified parameters.
   */
  public ConnectionManager(int maxConnections, long idleTimeout) {
    this.maxConnections = maxConnections;
    this.idleTimeout = idleTimeout;
  }

  /**
   * Establishes a new connection to the remote server using Non-blocking I/O (NIO) channels and OAuth2 authentication.
   */
  public CompletableFuture<AsynchronousSocketChannel> establishConnection(String hostname, int port) {
    // Create a new NIO channel for the connection
    AsynchronousSocketChannel channel = AsynchronousSocketChannel.open();

    // Configure SSL/TLS settings for the connection
    SSLContext sslContext = null;
    try {
      sslContext = SSLContext.getInstance("TLS");
      TrustManagerFactory trustManagerFactory = TrustManagerFactory
          .getInstance(TrustManagerFactory.getDefaultAlgorithm());
      KeyStore keyStore = KeyStore.getInstance(KeyStore.getDefaultType());
      keyStore.load(null, null);
      trustManagerFactory.init(keyStore);
      sslContext.init(null, trustManagerFactory.getTrustManagers(), new SecureRandom());
    } catch (NoSuchAlgorithmException | KeyStoreException | IOException e) {
      LOGGER.error("Failed to initialize SSL/TLS context", e);
      return null;
    }
    SSLEngine sslEngine = sslContext.createSSLEngine(hostname, port);
    sslEngine.setUseClientMode(true);
    sslEngine.setNeedClientAuth(false);

    // Configure OAuth2 authentication settings for the connection
    OAuth2Authenticator authenticator = new OAuth2Authenticator();
    CompletableFuture<String> authTokenFuture = authenticator.getAccessToken();

    return channel.connect(hostname, port).thenCompose((v) -> {
      // Send the SSL/TLS handshake and wait for the response
      sslEngine.beginHandshake();
      return new HandshakeFuture(channel, sslEngine);
    }).thenCompose((v) -> {
      // Send the OAuth2 authentication request and wait for the response
      return authTokenFuture.thenApply((authToken) -> {
        ByteBuffer buffer = ByteBuffer.allocate(1024);
        buffer.putInt(authToken.length());
        buffer.put(authToken.getBytes());
        buffer.flip();
        return channel.write(buffer).thenApply((v) -> buffer);
      });
    }).handle((response, error) -> {
      // Handle any SSL/TLS or OAuth2 errors
      if (error != null) {
        LOGGER.error("Failed to establish connection", error);
        return null;
      }

      // Return the established channel for further use
      return channel;
    });
  }

  /**
   * Closes a specific connection in the connection pool, returning it to the idle state.
   */
  public void closeConnection(AsynchronousSocketChannel channel) {
    channels.remove(channel);
    executor.execute(() -> {
      try {
        channel.close();
      } catch (IOException e) {
        LOGGER.error("Failed to close connection", e);
      }
    });
  }

  /**
   * Closes all connections in the connection pool, invalidating them and returning them to the idle state.
   */
  public void closeAllConnections() {
    channels.forEach((channel) -> {
      try {
        channel.close();
      } catch (IOException e) {
        LOGGER.error("Failed to close connection", e);
      }
    });
    channels.clear();
  }

  /**
   * Establishes a new connection in the connection pool, either using an existing idle connection or creating a new one if necessary.
   */
  public CompletableFuture<AsynchronousSocketChannel> getConnection(String hostname, int port) {
    return CompletableFuture.supplyAsync(() -> {
      // Check for an idle connection in the pool first
      AsynchronousSocketChannel channel = channels.stream()
          .filter((c) -> c.isOpen() && c.isConnected())
          .findFirst()
          .orElse(null);

      if (channel != null) {
        // If an idle connection is available, return it and update its timestamp
        channel.lastUsedTime = System.currentTimeMillis();
        LOGGER.debug("Reusing existing connection");
        return channel;
      }

      // If no idle connections are available, create a new one
      try {
        return establishConnection(hostname, port);
      } catch (IOException e) {
        LOGGER.error("Failed to establish connection", e);
        return null;
      }
    });
  }

  /**
   * Returns the number of active connections in the connection pool.
   */
  public int getConnectionCount() {
    return channels.size();
  }
}
