const fs = require('fs');
const path = require('path');
const util = require('util');
const asyncLib = require('async');
const { promisify } = require('util');
const exec = promisify(require('child_process').exec);
const npm = require('npm');

// Define the modules to be loaded and their dependencies
const modules = [
  { name: 'module1', deps: ['module2'] },
  { name: 'module2', deps: [] },
  { name: 'module3', deps: ['module1'] },
];

// Define the loading order of the modules
const loadingOrder = [
  'module1',
  'module2',
  'module3',
];

// Define a function to load and execute a module
function loadModule(name) {
  const modulePath = path.join(__dirname, `modules/${name}.js`);
  if (fs.existsSync(modulePath)) {
    return require(modulePath);
  } else {
    throw new Error(`Module ${name} not found.`);
  }
}

// Define a function to execute a module with dependencies
function executeModule(name, deps) {
  const module = loadModule(name);
  if (deps.length > 0) {
    // Execute the dependencies first
    asyncLib.forEachSeries(deps, (dep, callback) => {
      return executeModule(dep, []).then(() => {
        // Once all dependencies have been executed, execute the module
        module().then(() => {
          callback();
        }).catch((err) => {
          console.error(`Error executing module ${name}:`, err);
          callback(err);
        });
      });
    }, () => {
      // Once all dependencies have been executed, execute the module
      module().then(() => {
        console.log(`Module ${name} executed successfully.`);
      }).catch((err) => {
        console.error(`Error executing module ${name}:`, err);
      });
    });
  } else {
    // Execute the module directly if it has no dependencies
    return module().then(() => {
      console.log(`Module ${name} executed successfully.`);
    }).catch((err) => {
      console.error(`Error executing module ${name}:`, err);
    });
  }
}

// Define a function to handle errors during module execution
function handleError(err, name) {
  console.error(`Error executing module ${name}:`, err);
  // Log the error and move on to the next module in the loading order
  return executeModule(loadingOrder[0], []).then(() => {
    console.log(`Continuing with next module ${loadingOrder[0]}...`);
  });
}

// Define a function to load and execute all modules
async function loadModules() {
  // Load and execute each module in the loading order
  for (const name of loadingOrder) {
    try {
      await executeModule(name, []).then(() => {
        console.log(`${name} executed successfully.`);
      }).catch((err) => {
        handleError(err, name);
      });
    } catch (err) {
      handleError(err, name);
    }
  }
}

// Load and execute all modules
loadModules();
