public class DynamicXPathProcessor
{
    private const int DefaultCacheSize = 1024;
    private const float DefaultCacheHitRateThreshold = 0.5f;
    private readonly Dictionary<string, XDocument> _cache = new Dictionary<string, XDocument>(DefaultCacheSize);
    private readonly List<string> _cacheKeys = new List<string>(DefaultCacheSize);
    private readonly object _lock = new object();
    private readonly int _maxRetries;
    private readonly float _retryBackoffFactor;
    private readonly IXmlSchemaValidator _schemaValidator;
    private readonly XmlNamespaceManager _nsMgr;

    public DynamicXPathProcessor(IXmlSchemaValidator schemaValidator, XmlNamespaceManager nsMgr, int maxRetries = 3, float retryBackoffFactor = 2.0f)
    {
        _schemaValidator = schemaValidator;
        _nsMgr = nsMgr;
        _maxRetries = maxRetries;
        _retryBackoffFactor = retryBackoffFactor;
    }

    public XElement Process(string url, string xpathQuery)
    {
        if (url == null) throw new ArgumentNullException(nameof(url));
        if (xpathQuery == null) throw new ArgumentNullException(nameof(xpathQuery));

        XDocument document = GetFromCacheOrFetch(url);
        return document.XPathSelectElement(xpathQuery, _nsMgr);
    }

    private XDocument GetFromCacheOrFetch(string url)
    {
        // Check cache for existing document
        if (_cache.TryGetValue(url, out XDocument document))
            return document;

        // Fetch document from API
        int retryCount = 0;
        while (retryCount < _maxRetries)
        {
            try
            {
                document = FetchDocumentFromApi(url);
                break;
            }
            catch (Exception ex) when (ex is HttpRequestException || ex is XmlSchemaValidationException)
            {
                retryCount++;
                Thread.Sleep((int)(retryCount * _retryBackoffFactor));
            }
        }

        if (document == null)
            throw new Exception($"Failed to fetch document from API after {_maxRetries} retries");

        // Validate document against schema
        try
        {
            _schemaValidator.Validate(document);
        }
        catch (XmlSchemaValidationException ex)
        {
            throw new Exception($"Failed to validate document against schema: {ex.Message}", ex);
        }

        // Cache document for future use
        lock (_lock)
        {
            _cache[url] = document;
            if (_cacheKeys.Count >= DefaultCacheSize)
                _cacheKeys.RemoveAt(0);
            _cacheKeys.Add(url);
        }

        return document;
    }

    private XDocument FetchDocumentFromApi(string url)
    {
        // TODO: Implement fetching document from API
        throw new NotImplementedException();
    }
}
