using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

namespace FileTransferService
{
    public class FileUploadService : IFileUploadService
    {
        private readonly ILogger _logger;
        private readonly HttpClient _httpClient;
        private readonly string _uploadUrl;
        private readonly string _tokenUrl;
        private readonly string _token;
        private readonly int _chunkSize;
        private readonly int _retryCount;
        private readonly int _retryDelay;
        private readonly bool _useQueueSystem;
        private readonly IMessageQueueClient _queueClient;

        public FileUploadService(ILogger<FileUploadService> logger, HttpClient httpClient, string uploadUrl, string tokenUrl, string token, int chunkSize, int retryCount, int retryDelay, bool useQueueSystem, IMessageQueueClient queueClient)
        {
            _logger = logger;
            _httpClient = httpClient;
            _uploadUrl = uploadUrl;
            _tokenUrl = tokenUrl;
            _token = token;
            _chunkSize = chunkSize;
            _retryCount = retryCount;
            _retryDelay = retryDelay;
            _useQueueSystem = useQueueSystem;
            _queueClient = queueClient;
        }

        public async Task<bool> UploadFileAsync(string filePath, byte[] encryptionKey, byte[] iv, CancellationToken cancellationToken = default)
        {
            try
            {
                if (!File.Exists(filePath))
                    throw new FileNotFoundException("The specified file does not exist.", filePath);

                var fileSize = new System.IO.FileInfo(filePath).Length;
                var chunkCount = (int)Math.Ceiling((double)fileSize / _chunkSize);
                var totalBytesTransferred = 0L;

                if (_useQueueSystem)
                {
                    await _queueClient.SendMessageAsync(new UploadFileMessage()
                    {
                        FilePath = filePath,
                        EncryptionKey = encryptionKey,
                        IV = iv,
                        ChunkCount = chunkCount,
                        TotalBytesTransferred = totalBytesTransferred,
                        CancellationToken = cancellationToken
                    });
                }
                else
                {
                    using (var fileStream = new FileStream(filePath, FileMode.Open))
                    {
                        await UploadFileChunkAsync(fileStream, encryptionKey, iv, 0, chunkCount - 1, totalBytesTransferred, cancellationToken);
                    }
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to upload file");
                throw;
            }
        }

        public async Task<bool> UploadFileAsync(byte[] fileBytes, byte[] encryptionKey, byte[] iv, CancellationToken cancellationToken = default)
        {
            try
            {
                var fileSize = fileBytes.Length;
                var chunkCount = (int)Math.Ceiling((double)fileSize / _chunkSize);
                var totalBytesTransferred = 0L;

                if (_useQueueSystem)
                {
                    await _queueClient.SendMessageAsync(new UploadFileMessage()
                    {
                        FilePath = null,
                        EncryptionKey = encryptionKey,
                        IV = iv,
                        ChunkCount = chunkCount,
                        TotalBytesTransferred = totalBytesTransferred,
                        CancellationToken = cancellationToken
                    });
                }
                else
                {
                    using (var fileStream = new MemoryStream(fileBytes))
                    {
                        await UploadFileChunkAsync(fileStream, encryptionKey, iv, 0, chunkCount - 1, totalBytesTransferred, cancellationToken);
                    }
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to upload file");
                throw;
            }
        }

        private async Task UploadFileChunkAsync(Stream fileStream, byte[] encryptionKey, byte[] iv, int chunkIndex, int chunkCount, long totalBytesTransferred, CancellationToken cancellationToken = default)
        {
            try
            {
                var chunkSize = Math.Min(_chunkSize, fileStream.Length - (chunkIndex * _chunkSize));
                var currentChunkBytes = await ReadChunkAsync(fileStream, chunkSize);

                if (!_useQueueSystem)
                {
                    totalBytesTransferred += currentChunkBytes.Length;

                    var uploadUrl = $"{_uploadUrl}?token={Uri.EscapeDataString(_token)}&chunkIndex={chunkIndex}&chunkCount={chunkCount}";
                    using (var request = new HttpRequestMessage(HttpMethod.Put, uploadUrl))
                    {
                        request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", _token);
                        request.Content = new ByteArrayContent(currentChunkBytes);

                        if (cancellationToken != default)
                            cancellationToken.Register(() => request.Dispose());

                        var response = await _httpClient.SendAsync(request, cancellationToken);
                        if (!response.IsSuccessStatusCode)
                            throw new HttpRequestException($"Failed to upload file chunk {chunkIndex + 1} of {chunkCount}. Status code: {response.StatusCode}");
                    }
                }
                else
                {
                    await _queueClient.SendMessageAsync(new UploadFileChunkMessage()
                    {
                        FilePath = null,
                        EncryptionKey = encryptionKey,
                        IV = iv,
                        ChunkIndex = chunkIndex,
                        ChunkCount = chunkCount,
                        TotalBytesTransferred = totalBytesTransferred,
                        CurrentChunkBytes = currentChunkBytes,
                        CancellationToken = cancellationToken
                    });
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to upload file chunk");
                throw;
            }
        }

        private async Task<byte[]> ReadChunkAsync(Stream stream, int length)
        {
            var buffer = new byte[length];
            var bytesRead = await stream.ReadAsync(buffer);
            return buffer.Take(bytesRead).ToArray();
        }
    }
}
```
In this example, we have a `UploadFileService` class that provides two methods for uploading files: `UploadFileAsync` and `UploadFileChunkAsync`. These methods are responsible for sending the file to the server in chunks, with each chunk containing a maximum of 1 MB of data.

The `UploadFileAsync` method takes a `filePath` parameter that specifies the path to the file to be uploaded, as well as an `encryptionKey` and an `iv` parameters that specify the encryption key and initialization vector for encrypting the file data before uploading it.

The `UploadFileChunkAsync` method takes a `stream` parameter that represents the stream of the file to be uploaded, as well as an `encryptionKey`, `iv`, `chunkIndex`, and `chunkCount` parameters that specify the encryption key, initialization vector, chunk index, and chunk count for encrypting the file data before uploading it.

The `ReadChunkAsync` method is used to read a chunk of data from the file stream with a maximum size of 1 MB. The `UploadFileChunkAsync` method then sends each chunk of data to the server using an HTTP PUT request, along with the encryption key and initialization vector for encrypting the data before uploading it.

The `UploadFileService` class also has a `TotalBytesTransferred` property that returns the total number of bytes transferred during the file upload process. This property can be used to monitor the progress of the file upload operation.

