use std::env;
use std::fs;
use std::path::Path;
use std::sync::{Arc, Mutex};
use std::thread;

struct WorkingDirectory {
    path: String,
    is_temporary: bool,
    created_at: SystemTime,
    last_accessed_at: SystemTime,
}

impl WorkingDirectory {
    fn new(path: &str) -> Self {
        let is_temporary = path.starts_with("/tmp");
        let created_at = SystemTime::now();
        let last_accessed_at = created_at;

        WorkingDirectory {
            path: path.to_string(),
            is_temporary,
            created_at,
            last_accessed_at,
        }
    }

    fn exists(&self) -> bool {
        Path::new(&self.path).exists()
    }

    fn validate(&self) -> Result<(), String> {
        if !self.exists() {
            return Err(format!("Working directory {} does not exist", &self.path));
        }

        let metadata = fs::metadata(&self.path).map_err(|e| e.to_string())?;
        let permissions = metadata.permissions();

        if !permissions.readonly() {
            return Err(format!("Working directory {} is not readable", &self.path));
        }

        if permissions.mode().unwrap() < 0o755 {
            return Err(format!("Working directory {} has invalid permissions ({}): expected minimum of 0o755", &self.path, permissions.mode().unwrap()));
        }

        Ok(())
    }

    fn create(&self) -> Result<(), String> {
        fs::create_dir_all(&self.path).map_err(|e| e.to_string())?;
        self.validate()
    }

    fn delete(&self) -> Result<(), String> {
        fs::remove_dir_all(&self.path).map_err(|e| e.to_string())?;
        Ok(())
    }

    fn cleanup(&self) -> Result<(), String> {
        if self.is_temporary && !self.exists() {
            self.delete()
        } else {
            Ok(())
        }
    }

    fn access(&mut self) {
        self.last_accessed_at = SystemTime::now();
    }
}

struct WorkingDirectories {
    directories: Arc<Mutex<HashMap<String, WorkingDirectory>>>,
}

impl WorkingDirectories {
    fn new() -> Self {
        WorkingDirectories {
            directories: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    fn get(&self, path: &str) -> Option<WorkingDirectory> {
        self.directories.lock().unwrap().get(path).cloned()
    }

    fn put(&mut self, path: &str, directory: WorkingDirectory) {
        let mut directories = self.directories.lock().unwrap();
        directories.insert(path.to_string(), directory);
    }

    fn remove(&mut self, path: &str) -> Option<WorkingDirectory> {
        let mut directories = self.directories.lock().unwrap();
        directories.remove(path)
    }
}

fn main() {
    // Initialize the working directories map
    let mut working_directories = WorkingDirectories::new();

    // Create a new working directory for the pipeline execution
    let work_dir = env::var("WORK_DIR").unwrap_or_else(|_| "/tmp/rust-work-dir".to_string());
    let mut working_directory = WorkingDirectory::new(&work_dir);

    // Validate and create the working directory if it does not exist or has invalid permissions
    match working_directory.validate() {
        Ok(_) => (),
        Err(e) => {
            working_directory = WorkingDirectory::new("/tmp/rust-work-dir");
            working_directory.create().unwrap();
        }
    }

    // Add the working directory to the map for cleanup and access tracking
    working_directories.put(&work_dir, working_directory);

    // Create a thread for automatic cleanup of the working directory after pipeline execution
    thread::spawn(move || {
        loop {
            sleep(Duration::from_secs(30));
            let mut directories = working_directories.directories.lock().unwrap();
            let directory = directories.get(&work_dir);

            if let Some(directory) = directory {
                directory.cleanup().unwrap();
            }
        }
    });
}
