def test_reachable_states():
    # Test case 1: Empty FSA and empty initial state
    fsa = FSA()
    reachableStates = getReachableStates([], 0, fsa, 0)
    assert reachableStates == []

    # Test case 2: FSA with one state and one transition
    fsa = FSA(['A'])
    fsa.addTransition('A', 'B')
    reachableStates = getReachableStates(['A'], 1, fsa, 0)
    assert reachableStates == ['A', 'B']

    # Test case 3: FSA with multiple states and transitions
    fsa = FSA(['A', 'B', 'C'])
    fsa.addTransition('A', 'B')
    fsa.addTransition('A', 'C')
    fsa.addTransition('B', 'C')
    reachableStates = getReachableStates(['A'], 1, fsa, 0)
    assert reachableStates == ['A', 'B', 'C']

    # Test case 4: FSA with multiple states and transitions (backward search)
    fsa = FSA(['A', 'B', 'C'])
    fsa.addTransition('A', 'B')
    fsa.addTransition('A', 'C')
    fsa.addTransition('B', 'C')
    reachableStates = getReachableStates(['A'], 1, fsa, 2)
    assert reachableStates == ['A', 'B', 'C']
