#include <iostream>
#include <vector>
#include <string>
#include <chrono>
#include <thread>
#include <future>
#include <mutex>
#include <condition_variable>

using namespace std;

struct TestResult {
  int attackNumber;
  chrono::duration<double> executionTime;
};

vector<TestResult> runModuleTests(const string& moduleLabel, const vector<function<void()>>& testSuite, const string& loggingLevel, int cooldown, ResourceManager& resourceManager, DatabaseConnection& databaseConnection, int maxConcurrentTests, int testTimeout) {
  // Initialize the mocking library and load test configurations from the database
  MockingLibrary mockingLibrary;
  vector<TestConfiguration> testConfigurations = databaseConnection.getTestConfigurations(moduleLabel);

  // Create a mutex to protect concurrent access to the resource manager and the test results
  mutex resultMutex;
  vector<TestResult> results;

  // Schedule the tests using a condition variable to manage concurrency
  condition_variable cv;
  bool isRunning = false;
  int runningTests = 0;
  for (int i = 0; i < testSuite.size(); ++i) {
    function<void()> testFunction = [&]() {
      // Initialize the mocking library and load the current configuration
      TestConfiguration configuration = testConfigurations[i];
      mockingLibrary.initialize(configuration);

      // Run the test and measure its execution time
      chrono::time_point<chrono::high_resolution_clock> startTime = chrono::high_resolution_clock::now();
      testSuite[i](configuration);
      chrono::duration<double> executionTime = chrono::high_resolution_clock::now() - startTime;

      // Clean up the mocking library and reset to its initial state
      resourceManager.cleanup();
      mockingLibrary.reset();

      // Add the test result to the results vector
      TestResult result = { i, executionTime };
      lock_guard<mutex> guard(resultMutex);
      results.push_back(result);
    };

    // Schedule the test and wait for it to complete
    future<void> future = async(launch::async, testFunction);
    while (future.wait_for(chrono::seconds(0)) != future_status::ready) {
      if (runningTests >= maxConcurrentTests) {
        cv.wait(lock);
      } else {
        isRunning = true;
        runningTests++;
        break;
      }
    }

    // Handle any timeouts or errors for the test
    try {
      future.get();
    } catch (exception& e) {
      cerr << "Test " << i << " failed: " << e.what() << endl;
    }

    // Decrement the number of running tests and notify any waiting threads
    lock_guard<mutex> guard(resultMutex);
    isRunning = false;
    runningTests--;
    cv.notify_all();
  }

  // Print the test results to the console
  if (loggingLevel == "info") {
    for (const TestResult& result : results) {
      cout << "Test " << result.attackNumber << ": execution time = " << result.executionTime.count() << "s" << endl;
    }
  } else if (loggingLevel == "warn") {
    for (const TestResult& result : results) {
      cerr << "Test " << result.attackNumber << ": execution time = " << result.executionTime.count() << "s" << endl;
    }
  } else if (loggingLevel == "error") {
    for (const TestResult& result : results) {
      cerr << "Error: test " << result.attackNumber << ": execution time = " << result.executionTime.count() << "s" << endl;
    }
  }

  return results;
}
```
