// Structure to hold context for the cipher
typedef struct {
  EVP_CIPHER_CTX *ctx;
  unsigned char key[32]; // 256 bits
  unsigned char iv[16]; // 128 bits
} CipherContext;

// Function to generate a random key and IV
void generateKeyAndIV(unsigned char *key, unsigned char *iv) {
  RAND_bytes(key, 32); // Generate 256-bit key
  RAND_bytes(iv, 16); // Generate 128-bit IV
}

// Function to initialize the EVP_CIPHER_CTX structure for a given cipher and key size
EVP_CIPHER_CTX *initializeCipherContext(int cipherType, int keySize) {
  // Create a new EVP_CIPHER_CTX structure
  EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

  // Set the cipher and key size for the context
  EVP_CipherInit(ctx, cipherType, NULL, NULL, 1);
  EVP_CIPHER_CTX_set_key_length(ctx, keySize);

  return ctx;
}

// Function to encrypt data using AES-GCM or AES-CBC
void encryptData(EVP_CIPHER_CTX *ctx, unsigned char *key, unsigned char *iv, unsigned char *data, int len) {
  // Set the key and IV for the context
  EVP_CIPHER_CTX_set_key(ctx, key, 32);
  EVP_CIPHER_CTX_set_iv(ctx, iv, 16);

  // Encrypt the data using the context
  int outlen = 0;
  unsigned char *outbuf = NULL;
  EVP_EncryptUpdate(ctx, &outbuf, &outlen, data, len);
}

// Function to decrypt data using AES-GCM or AES-CBC
void decryptData(EVP_CIPHER_CTX *ctx, unsigned char *key, unsigned char *iv, unsigned char *data, int len) {
  // Set the key and IV for the context
  EVP_CIPHER_CTX_set_key(ctx, key, 32);
  EVP_CIPHER_CTX_set_iv(ctx, iv, 16);

  // Decrypt the data using the context
  int outlen = 0;
  unsigned char *outbuf = NULL;
  EVP_DecryptUpdate(ctx, &outbuf, &outlen, data, len);
}

// Function to handle errors in the encryption/decryption process
void errorHandler(int err) {
  // Handle error based on the error code
  switch (err) {
    case ERR_LIB_EVP:
      printf("Error in EVP operation\n");
      break;
    case ERR_R_MALLOC_FAILURE:
      printf("Memory allocation failure\n");
      break;
    default:
      printf("Unknown error\n");
  }
}

// Main function to demonstrate the use of the encryption/decryption functions
int main() {
  // Initialize the OpenSSL library
  OPENSSL_init_ssl(OPENSSL_INIT_LOAD_ALL_CIPHERS, NULL);

  // Generate a random key and IV for testing
  unsigned char key[32];
  unsigned char iv[16];
  generateKeyAndIV(key, iv);

  // Initialize the EVP_CIPHER_CTX structure for AES-256-GCM
  EVP_CIPHER_CTX *ctx = initializeCipherContext(EVP_aes_256_gcm(), 32);

  // Encrypt some data using the context
  unsigned char plaintext[] = "Hello, World!";
  int len = strlen((const char *)plaintext);
  unsigned char ciphertext[len];
  encryptData(ctx, key, iv, (unsigned char *)plaintext, len, ciphertext);

  // Decrypt the ciphertext using the context
  decryptData(ctx, key, iv, ciphertext, len);

  // Free the EVP_CIPHER_CTX structure and clean up memory
  EVP_CIPHER_CTX_free(ctx);

  return 0;
}
```
This code demonstrates how to use the OpenSSL library to perform AES encryption and decryption using different key sizes and cipher modes. It also shows how to generate a random key and IV, and handle errors in the encryption/decryption process. The `generateKeyAndIV` function generates two arrays of bytes, one for the key and one for the IV, each with 32 bytes (256 bits) for AES-256 and 16 bytes (128 bits) for AES-192 and AES-128. The `initializeCipherContext` function creates a new `EVP_CIPHER_CTX` structure and sets the cipher type and key size to the chosen values. The `encryptData` and `decryptData` functions use these contexts to encrypt and decrypt data, respectively. The `errorHandler` function handles errors in the encryption/decryption process by printing an error message based on the error code. Finally, the main function demonstrates how to use these functions to perform AES-256 encryption and decryption using a random key and IV.

