use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::thread;

struct CompilerOrchestrator {
    // Map of language extensions to their respective compilers
    compiler_map: HashMap<String, Box<dyn Compiler>>,
    // Map of source files to their compiled results
    cache: HashMap<String, Arc<Mutex<CompilationResult>>>,
}

impl CompilerOrchestrator {
    fn new() -> Self {
        Self {
            compiler_map: HashMap::new(),
            cache: HashMap::new(),
        }
    }

    fn add_compiler(&mut self, extension: &str, compiler: Box<dyn Compiler>) {
        self.compiler_map.insert(extension.to_string(), compiler);
    }

    fn compile(&self, source_file: &str) -> Arc<Mutex<CompilationResult>> {
        let mut result = None;

        // Check if the file is in the cache
        if self.cache.contains_key(source_file) {
            result = Some(Arc::clone(&self.cache[source_file]));
        } else {
            // Otherwise, compile the file and add it to the cache
            let mut compilation_result = CompilationResult::new();
            let compiler = self.compiler_map.get(source_file).unwrap();
            compilation_result.push(compiler.compile(source_file));
            result = Some(Arc::new(Mutex::new(compilation_result)));
        }

        return Arc::clone(&result);
    }
}

struct Compiler {
    extension: String,
    compiler: Box<dyn Compiler>,
}

impl Compiler {
    fn new(extension: &str) -> Self {
        Self {
            extension: extension.to_string(),
            compiler: match extension {
                "rs" => Box::new(RustCompiler::new()),
                "c" => Box::new(CCompiler::new()),
                "py" => Box::new(PythonCompiler::new()),
                _ => panic!("Unsupported file extension: {}", extension),
            },
        }
    }

    fn compile(&self, source_file: &str) -> CompilationResult {
        return self.compiler.compile(source_file);
    }
}

struct RustCompiler {
    cargo: Cargo,
}

impl RustCompiler {
    fn new() -> Self {
        Self {
            cargo: Cargo::new(),
        }
    }

    fn compile(&self, source_file: &str) -> CompilationResult {
        let mut result = CompilationResult::new();
        let package = self.cargo.package(source_file);
        if !package.has_errors() {
            result.push(self.cargo.build(source_file));
        }
        return result;
    }
}

