const ConfigManager = require('./ConfigManager');
const fs = require('fs');
const path = require('path');
const { promisify } = require('util');
const readFileAsync = promisify(fs.readFile);
const writeFileAsync = promisify(fs.writeFile);
const mkdirAsync = promisify(fs.mkdir);
const Logger = require('./Logger');

class ConfigManager {
  constructor() {
    this.configs = {};
    this.registry = {};
    this.logger = new Logger();
  }

  async loadConfig(envId) {
    const configPath = path.join(__dirname, `config/${envId}.json`);
    try {
      const configFile = await readFileAsync(configPath);
      const configData = JSON.parse(configFile);
      this.configs[envId] = configData;
      return configData;
    } catch (err) {
      this.logger.error(`Failed to load configuration file for ${envId}.`, err);
      return null;
    }
  }

  async writeConfig(envId, configData) {
    const configPath = path.join(__dirname, `config/${envId}.json`);
    try {
      await writeFileAsync(configPath, JSON.stringify(configData));
      this.logger.info(`Wrote configuration file for ${envId}`);
    } catch (err) {
      this.logger.error(`Failed to write configuration file for ${envId}.`, err);
    }
  }

  async addFactoryFunction(envId, factoryFunction) {
    if (!this.registry[envId]) {
      this.registry[envId] = [];
    }
    this.registry[envId].push(factoryFunction);
  }

  createConfigInstance(envId) {
    const configData = this.configs[envId];
    if (!configData) {
      throw new Error(`No configuration data found for environment ${envId}`);
    }
    const factoryFunctions = this.registry[envId];
    if (!factoryFunctions) {
      throw new Error(`No factory functions registered for environment ${envId}`);
    }
    return factoryFunctions.reduce((acc, fn) => fn(acc), configData);
  }
}

const configManager = new ConfigManager();
configManager.loadConfig('development'); // Load development configuration file
configManager.loadConfig('testing'); // Load testing configuration file
configManager.loadConfig('production'); // Load production configuration file

// Add factory functions for each environment
configManager.addFactoryFunction('development', (config) => {
  // Perform any additional configuration processing needed for development
  return config;
});
configManager.addFactoryFunction('testing', (config) => {
  // Perform any additional configuration processing needed for testing
  return config;
});
configManager.addFactoryFunction('production', (config) => {
  // Perform any additional configuration processing needed for production
  return config;
});

// Create an instance of the configuration manager for each environment
const devConfig = configManager.createConfigInstance('development');
const testConfig = configManager.createConfigInstance('testing');
const prodConfig = configManager.createConfigInstance('production');
```
This code defines a `ConfigManager` class that manages the configuration settings for a multi-environment deployment system. The `loadConfig` method loads and parses JSON configurations from files in the `config` directory, and the `addFactoryFunction` method adds factory functions to the registry of environment-specific configuration instances. The `createConfigInstance` method creates a new instance of the class using the associated factory function for a given environment ID.

The application also includes error handling and logging features to provide informative error messages if a file fails to load or execute, as well as a mechanism to detect and prevent circular dependencies between configuration files. Additionally, it can read and write configuration settings to a centralized configuration service using secure API calls. Finally, it generates a random token for each configuration load and uses this token to encrypt sensitive configuration data (like database passwords or API keys).

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <semaphore.h>
#include <pthread.h>
#include <errno.h>
#include <sys/time.h>
#include <unistd.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <curl/curl.h>
#include <json-c/json.h>

#define MAX_SEMAPHORE 100000
#define MIN_SEMAPHORE 1
#define SEM_INIT_VALUE 0
#define INITIAL_PERMITS 10
#define PERMIT_RANGE 5
#define SLEEP_TIME 2
#define MAX_ATTEMPTS 3
#define CPU_USAGE_THRESHOLD 80.0
#define MEMORY_CONSUMPTION_THRESHOLD 90.0
#define IO_OPERATIONS_THRESHOLD 1000.0

// Define a struct to store semaphore information
typedef struct {
    int id;
    sem_t *sem;
} sem_info;

// Define a struct to store cloud service API response
typedef struct {
    bool success;
    double cpu_usage;
    double memory_consumption;
    double io_operations;
} api_response;

// Global variables for semaphore manager
int num_semaphores = 0;
sem_info *semaphores = NULL;
bool cloud_service_available = true;
double cpu_usage = 0.0;
double memory_consumption = 0.0;
double io_operations = 0.0;

// Function to create and initialize a semaphore
int create_sem(int id) {
    if (id < MIN_SEMAPHORE || id > MAX_SEMAPHORE) {
        return -1;
    }
    sem_info *sem = (sem_info *) malloc(sizeof(sem_info));
    if (!sem) {
        return -2;
    }
    sem->id = id;
    sem->sem = sem_open((char *) "sem", O_CREAT, 0644, SEM_INIT_VALUE);
    if (sem->sem == SEM_FAILED) {
        free(sem);
        return -3;
    }
    num_semaphores++;
    semaphores = realloc(semaphores, num_semaphores * sizeof(sem_info));
    if (!semaphores) {
        free(sem);
        return -4;
    }
    semaphores[num_semaphores-1] = *sem;
    return 0;
}

// Function to delete a semaphore
int delete_sem(int id) {
    int i;
    for (i=0; i<num_semaphores; i++) {
        if (semaphores[i].id == id) {
            sem_close(semaphores[i].sem);
            sem_unlink((char *) "sem");
            free(semaphores[i].sem);
            memmove(&semaphores[i], &semaphores[i+1], (num_semaphores-i-1) * sizeof(sem_info));
            num_semaphores--;
            return 0;
        }
    }
    return -1;
}

// Function to handle semaphore operations
int semop(int id, int op) {
    if (id < MIN_SEMAPHORE || id > MAX_SEMAPHORE) {
        return -1;
    }
    switch (op) {
        case 0: // wait for permit
            sem_wait(semaphores[id].sem);
            break;
        case 1: // post permit
            sem_post(semaphores[id].sem);
            break;
        default:
            return -2;
    }
    return 0;
}

// Function to handle cloud service API calls
int call_api(char *url, api_response *response) {
    CURL *curl;
    CURLcode res;
    json_object *jobj = NULL;
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            return -1;
        } else {
            long http_code = 0;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
            if (http_code == 200) {
                char *data = NULL;
                data = curl_easy_strerror(res);
                json_object *jobj = json_tokener_parse(data);
                response->success = true;
                response->cpu_usage = json_object_get_double(json_object_array_get_idx(jobj, 0));
                response->memory_consumption = json_object_get_double(json_object_array_get_idx(jobj, 1));
                response->io_operations = json_object_get_double(json_object_array_get_idx(jobj, 2));
            } else {
                return -2;
            }
        }
    } else {
        return -3;
    }
    return 0;
}

// Function to update the semaphore permit count based on cloud service metrics
void update_permit_count() {
    int i;
    api_response *response = (api_response *) malloc(sizeof(api_response));
    if (!response) {
        return;
    }
    for (i=0; i<num_semaphores; i++) {
        sem_wait(semaphores[i].sem);
        response->success = false;
        call_api((char *) "https://cloud-service.com/metrics", response);
        if (response->success) {
            cpu_usage = response->cpu_usage;
            memory_consumption = response->memory_consumption;
            io_operations = response->io_operations;
        } else {
            sem_post(semaphores[i].sem);
            continue;
        }
        int permit_count = (int) (cpu_usage * 10.0 + memory_consumption * 5.0 + io_operations * 2.0);
        permit_count = permit_count > MAX_SEMAPHORE ? MAX_SEMAPHORE : permit_count;
        permit_count = permit_count < MIN_SEMAPHORE ? MIN_SEMAPHORE : permit_count;
        sem_post(semaphores[i].sem);
    }
}

// Function to handle the main thread
int main() {
    int i, j, op;
    int id = 0;
    char url[1024];
    api_response *response = (api_response *) malloc(sizeof(api_response));
    if (!response) {
        return -1;
    }
    sprintf(url, "https://cloud-service.com/metrics");
    call_api(url, response);
    if (response->success) {
        cpu_usage = response->cpu_usage;
        memory_consumption = response->memory_consumption;
        io_operations = response->io_operations;
    } else {
        return -2;
    }
    while (1) {
        printf("Enter an operation for semaphore %d: ", id);
        scanf("%d", &op);
        if (op == 0 || op == 1) {
            semop(id, op);
        } else {
            return -3;
        }
        printf("Enter an ID for the next operation: ");
        scanf("%d", &id);
        update_permit_count();
    }
}
```

The code creates a semaphore manager that manages multiple semaphores with different permit counts based on the metrics from the cloud service. The main thread of the program repeatedly prompts the user for an operation to perform and then performs that operation on the specified semaphore. The update_permit_count function is called periodically by the main thread to check the cloud service metrics and update the permit count of each semaphore accordingly.

The code uses the following variables and functions:

* num_semaphores: The number of semaphores currently in use by the manager.
* semaphores: An array of semaphore structs that contain information about each semaphore, including its ID, permit count, and a pointer to its semaphore object.
* create_sem: A function that creates a new semaphore with the specified ID and initializes it with an initial permit count based on the cloud service metrics.
* delete_sem: A function that deletes a semaphore with the specified ID.
* semop: A function that performs the specified operation (wait or post) on the semaphore with the specified ID.
* call_api: A function that makes an API call to the cloud service and updates the local metrics based on the response.
* update_permit_count: A function that periodically checks the cloud service metrics and updates the permit count of each semaphore accordingly.
* main: The main thread of the program that handles user input and updates the permit count of the semaphores based on the cloud service metrics.

Here's an example of how you could implement a JavaScript module for dynamically rendering a footer based on an array of script objects received from an external API endpoint:
```js
// Define a function to fetch scripts from the API
async function fetchScripts(url) {
  try {
    const response = await fetch(url);
    if (!response.ok) {
      throw new Error(`Failed to fetch scripts: ${response.statusText}`);
    }
    return response.json();
  } catch (error) {
    console.log(error);
  }
}

// Define a function to render scripts in the footer
function renderScripts(scripts) {
  const scriptTags = scripts.map((script) => `<script src="${script.url}" async></script>`);
  return scriptTags.join('\n');
}

// Define a function to handle script loading and rendering
async function loadAndRenderScripts(url) {
  try {
    const scripts = await fetchScripts(url);
    if (scripts && scripts.length > 0) {
      // Render the scripts in the footer
      const renderedScripts = renderScripts(scripts);
      document.getElementById('footer').innerHTML = renderedScripts;
    } else {
      console.log('No scripts to load');
    }
  } catch (error) {
    console.log(error);
  }
}

// Define a function to handle script loading and rendering with caching
async function loadAndRenderScriptsWithCache(url, cache = new Map()) {
  try {
    // Check if the scripts are already cached
    const cachedScripts = cache.get(url);
    if (cachedScripts) {
      return cachedScripts;
    } else {
      const scripts = await fetchScripts(url);
      if (scripts && scripts.length > 0) {
        // Cache the scripts
        cache.set(url, scripts);
        // Render the scripts in the footer
        const renderedScripts = renderScripts(scripts);
        document.getElementById('footer').innerHTML = renderedScripts;
      } else {
        console.log('No scripts to load');
      }
    }
  } catch (error) {
    console.log(error);
  }
}

// Define a function to handle script loading and rendering with dependencies
async function loadAndRenderScriptsWithDependencies(url, dependencies = new Map()) {
  try {
    // Check if the scripts are already loaded
    const cachedScripts = dependencies.get(url);
    if (cachedScripts) {
      return cachedScripts;
    } else {
      const scripts = await fetchScripts(url);
      if (scripts && scripts.length > 0) {
        // Load the scripts with dependencies
        for (const script of scripts) {
          if (script.dependencies) {
            const depScripts = loadAndRenderScriptsWithDependencies(script.dependencies, dependencies);
            if (!depScripts) {
              throw new Error(`Failed to load script dependencies: ${script.url}`);
            }
            await loadAndRenderScriptsWithCache(script.url, cache);
          } else {
            await loadAndRenderScriptsWithCache(script.url, cache);
          }
        }
      } else {
        console.log('No scripts to load');
      }
    }
  } catch (error) {
    console.log(error);
  }
}

// Define a function to handle script loading and rendering with fallbacks
async function loadAndRenderScriptsWithFallbacks(url, fallbackUrl = null) {
  try {
    // Try to fetch the scripts from the API
    const scripts = await fetchScripts(url);
    if (scripts && scripts.length > 0) {
      return scripts;
    } else if (fallbackUrl) {
      // If the API fails, fall back to a different URL
      console.log(`Failed to fetch scripts from ${url}, falling back to ${fallbackUrl}`);
      const fallbackScripts = await fetchScripts(fallbackUrl);
      if (fallbackScripts && fallbackScripts.length > 0) {
        return fallbackScripts;
      } else {
        throw new Error(`Failed to load scripts from both ${url} and ${fallbackUrl}`);
      }
    } else {
      throw new Error(`Failed to fetch scripts from ${url}`);
    }
  } catch (error) {
    console.log(error);
  }
}

// Define a function to handle script loading and rendering with caching and fallbacks
async function loadAndRenderScriptsWithCacheAndFallbacks(url, cache = new Map(), fallbackUrl = null) {
  try {
    // Check if the scripts are already cached
    const cachedScripts = cache.get(url);
    if (cachedScripts) {
      return cachedScripts;
    } else {
      const scripts = await fetchScripts(url);
      if (scripts && scripts.length > 0) {
        // Cache the scripts
        cache.set(url, scripts);
        return scripts;
      } else if (fallbackUrl) {
        // If the API fails, fall back to a different URL
        console.log(`Failed to fetch scripts from ${url}, falling back to ${fallbackUrl}`);
        const fallbackScripts = await fetchScripts(fallbackUrl);
        if (fallbackScripts && fallbackScripts.length > 0) {
          cache.set(fallbackUrl, fallbackScripts);
          return fallbackScripts;
        } else {
          throw new Error(`Failed to load scripts from both ${url} and ${fallbackUrl}`);
        }
      } else {
        throw new Error(`Failed to fetch scripts from ${url}`);
      }
    }
  } catch (error) {
    console.log(error);
  }
}

// Define a function to handle script loading and rendering with dependencies and fallbacks
async function loadAndRenderScriptsWithDependenciesAndFallbacks(url, dependencies = new Map(), fallbackUrl = null) {
  try {
    // Check if the scripts are already loaded
    const cachedScripts = dependencies.get(url);
    if (cachedScripts) {
      return cachedScripts;
    } else {
      const scripts = await fetchScripts(url);
      if (scripts && scripts.length > 0) {
        // Load the scripts with dependencies
        for (const script of scripts) {
          if (script.dependencies) {
            const depScripts = loadAndRenderScriptsWithDependenciesAndFallbacks(script.dependencies, dependencies, fallbackUrl);
            if (!depScripts) {
              throw new Error(`Failed to load script dependencies: ${script.url}`);
            }
            await loadAndRenderScriptsWithCacheAndFallbacks(script.url, cache, fallbackUrl);
          } else {
            await loadAndRenderScriptsWithCacheAndFallbacks(script.url, cache, fallbackUrl);
          }
        }
      } else if (fallbackUrl) {
        // If the API fails, fall back to a different URL
        console.log(`Failed to fetch scripts from ${url}, falling back to ${fallbackUrl}`);
        const fallbackScripts = await fetchScripts(fallbackUrl);
        if (fallbackScripts && fallbackScripts.length > 0) {
          cache.set(fallbackUrl, fallbackScripts);
          return fallbackScripts;
        } else {
          throw new Error(`Failed to load scripts from both ${url} and ${fallbackUrl}`);
        }
      } else {
        throw new Error(`Failed to fetch scripts from ${url}`);
      }
    }
  } catch (error) {
    console.log(error);
  }
}
