fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        println!("Usage: ./program <config-file>");
        return;
    }

    let config_path = &args[1];
    let config = configuration::load(config_path);
    if config.is_err() {
        println!("Failed to load configuration file: {}", config_path);
        return;
    }

    let mut api_clients: HashMap<String, HttpClient> = HashMap::new();
    for (api_name, api_config) in config.as_ref().unwrap().iter() {
        let client = create_api_client(api_config).await?;
        api_clients.insert(api_name, client);
    }

    let mut workers: Vec<Arc<Worker>> = vec![];
    for (i, api_name) in config.as_ref().unwrap().iter().enumerate() {
        let worker = Worker::new(api_name.clone(), Arc::clone(&api_clients[api_name]));
        workers.push(worker);
    }

    let mut shutdown = false;
    while !shutdown {
        for (i, worker) in workers.iter().enumerate() {
            if worker.is_done() {
                println!("Worker {} finished", i);
                shutdown = true;
                break;
            } else {
                worker.run();
            }
        }
    }
}

struct Worker {
    api_name: String,
    client: Arc<HttpClient>,
    queue: Vec<Request>,
    is_done: bool,
}

impl Worker {
    fn new(api_name: &str, client: Arc<HttpClient>) -> Self {
        Self {
            api_name: api_name.to_string(),
            client,
            queue: vec![],
            is_done: false,
        }
    }

    fn run(&mut self) {
        while !self.is_done {
            if let Some(request) = self.queue.pop() {
                let request_id = self.api_name.clone();
                let response = self.client.execute(request).await?;
                println!("Received response for request {}", request_id);
                handle_response(response);
            } else {
                break;
            }
        }
    }
}

struct Request {
