// renderFooterScripts(scripts)
function renderFooterScripts(scripts) {
  // Cache of fetched scripts (key: script URL, value: script content)
  const scriptCache = {};
  // Array of scripts that are still in use
  const activeScripts = [];
  // DOM element to hold the scripts
  const scriptContainer = document.createElement("script");

  function fetchScript(url, callback) {
    // Fetch script from URL
    fetch(url)
      .then((response) => response.text())
      .then((data) => callback(null, data))
      .catch((error) => callback(error));
  }

  function checkScriptUsage(script) {
    // Check if the script is still in use
    return activeScripts.includes(script);
  }

  function renderScript(script, index) {
    // Create a new script element and set its content
    const scriptElement = document.createElement("script");
    scriptElement.innerHTML = script;
    scriptContainer.appendChild(scriptElement);
  }

  // Handle missing properties of scripts by providing defaults
  scripts.forEach((script, index) => {
    if (!script.code) {
      script.code = "";
    }
    if (!script.type) {
      script.type = "text/javascript";
    }
    renderScript(script, index);
  });

  // Fetch scripts dynamically and handle failed requests
  const fetchPromises = [];
  scripts.forEach((script, index) => {
    if (!checkScriptUsage(script)) {
      activeScripts.push(script);
      const url = script.url || `/api/scripts`;
      fetchPromises.push(fetchScript(url, (error, data) => {
        if (error) {
          console.log(`Failed to fetch script ${index}`, error);
          return;
        }
        // Cache the fetched script and render it
        scriptCache[script.url] = data;
        renderScript(data, index);
      }, {}, retryOptions));
    }
  });

  Promise.all(fetchPromises).then(() => {
    // Clean up old or unused scripts in the DOM
    const scriptElements = document.querySelectorAll("script");
    scriptElements.forEach((element) => {
      if (!activeScripts.includes(element.innerHTML)) {
        element.remove();
      }
    });
  });

  // Log errors and cache hits/misses for debugging purposes
  const errorLog = document.createElement("div");
  errorLog.classList.add("error-log");
  document.body.appendChild(errorLog);
  fetchPromises.forEach((promise) => {
    promise.catch((error) => {
      console.log(`Failed to load script: ${error}`);
      errorLog.textContent = `Error loading script: ${error.message}`;
    });
  });

  // Render the footer with the fetched scripts
  const footer = document.createElement("footer");
  footer.appendChild(scriptContainer);
  return footer;
}
