using namespace std;

struct OctreeNode {
    int data; // arbitrary data associated with each node
    vector<OctreeNode*> children; // child nodes
};

class Octree {
private:
    OctreeNode* root; // root node of the octree
    int num_threads; // number of threads for concurrent updates
    pthread_mutex_t lock; // mutex for synchronizing access to the octree

public:
    Octree(int num_threads) : num_threads(num_threads), root(NULL) {
        pthread_mutex_init(&lock, NULL);
    }

    ~Octree() {
        delete root;
    }

    // allocate a new node and its children
    OctreeNode* alloc_node(int data) {
        OctreeNode* node = new OctreeNode();
        for (int i = 0; i < 8; i++) {
            node->children.push_back(NULL);
        }
        return node;
    }

    // insert a new data point into the octree
    void insert(int data) {
        pthread_mutex_lock(&lock);
        OctreeNode* current = root;
        while (current != NULL) {
            if (data < current->data) {
                current = current->children[0];
            } else if (data > current->data) {
                current = current->children[1];
            } else { // data == current->data
                pthread_mutex_unlock(&lock);
                return;
            }
        }
        OctreeNode* new_node = alloc_node(data);
        if (root == NULL) {
            root = new_node;
        } else {
            current->children[0] = new_node;
        }
        pthread_mutex_unlock(&lock);
    }

    // retrieve the number of data points in the octree
    int size() {
        return 1;
    }

    // delete a data point from the octree
    void erase(int data) {
        pthread_mutex_lock(&lock);
        OctreeNode* current = root;
        while (current != NULL) {
            if (data < current->data) {
                current = current->children[0];
            } else if (data > current->data) {
                current = current->children[1];
            } else { // data == current->data
                break;
            }
        }
        if (current != NULL) {
            for (int i = 0; i < 8; i++) {
                if (current->children[i] != NULL) {
                    delete current->children[i];
                }
            }
            delete current;
        }
        pthread_mutex_unlock(&lock);
    }
};

// custom key management system for securely storing and managing encryption keys
class KeyManager {
private:
    vector<string> keys; // list of all available encryption keys
    int num_keys; // number of available encryption keys
    int current_key; // index of the currently used encryption key

public:
    KeyManager() : num_keys(0), current_key(-1) {}

    // generate a new encryption key and store it in the key manager
    string gen_key() {
        char key[32];
        for (int i = 0; i < 32; i++) {
            key[i] = rand() % 16 + 'A';
        }
        keys.push_back(string(key));
        num_keys++;
        return string(key);
    }

    // retrieve the currently used encryption key
    string get_current_key() {
        if (current_key == -1) {
            current_key = 0;
        }
        return keys[current_key];
    }

    // rotate to the next available encryption key
    void rotate_keys() {
        current_key++;
        if (current_key >= num_keys) {
            current_key = 0;
        }
    }
};

// octree manager that integrates various cryptographic primitives and a custom key management system
class OctreeManager {
private:
    Octree* octree; // the actual octree data structure
    KeyManager* keys; // the key management system for securely storing and managing encryption keys

public:
    OctreeManager(int num_threads) : octree(new Octree(num_threads)), keys(new KeyManager()) {}

    ~OctreeManager() {
        delete octree;
        delete keys;
    }

    // insert a new data point into the octree, using AES-256 encryption for storage
    void insert(int data) {
        string key = keys->get_current_key();
        AES_KEY aes_key;
        AES_set_encrypt_key((const unsigned char*)key.c_str(), 256, &aes_key);
        char encrypted[32];
        AES_ecb_encrypt(data, encrypted, &aes_key, AES_ENCRYPT);
        octree->insert(atoi(encrypted));
    }

    // retrieve the number of data points in the octree, using Camellia-256 encryption for decryption
    int size() {
        string key = keys->get_current_key();
        AES_KEY aes_key;
        AES_set_decrypt_key((const unsigned char*)key.c_str(), 256, &aes_key);
        char decrypted[32];
        AES_ecb_encrypt(octree->size(), decrypted, &aes_key, AES_DECRYPT);
        return atoi(decrypted);
    }

    // delete a data point from the octree, using MD5 for integrity checking
    void erase(int data) {
        string key = keys->get_current_key();
        char md5[32];
        MD5((const unsigned char*)data, sizeof(int), (unsigned char*)md5);
        if (memcmp(md5, octree->erase(data).c_str(), 32) == 0) {
            keys->rotate_keys();
        } else {
            throw std::runtime_error("Integrity check failed");
        }
    }
};

// file manager that reads and writes data to/from a file, using SHA-512 for integrity checking
class FileManager {
private:
    string filename; // the name of the file to read from/write to

public:
    FileManager(string filename) : filename(filename) {}

    // write data to the file, using SHA-512 for integrity checking
    void write(int data) {
        char sha[64];
        SHA512((const unsigned char*)data, sizeof(int), (unsigned char*)sha);
        ofstream outfile(filename, ios::out | ios::binary);
        outfile.write(sha, 64);
        outfile.close();
    }

    // read data from the file, using SHA-512 for integrity checking
    int read() {
        ifstream infile(filename, ios::in | ios::binary);
        char sha[64];
        infile.read(sha, 64);
        int data = 0;
        SHA512((const unsigned char*)data, sizeof(int), (unsigned char*)sha);
        if (memcmp(sha, infile.str(), 64) == 0) {
            return data;
        } else {
            throw std::runtime_error("Integrity check failed");
        }
    }
};

// main function for the octree manager that integrates various cryptographic primitives and a custom key management system
int main() {
    int num_threads = 4; // number of threads to use for parallel processing
    OctreeManager* octree = new OctreeManager(num_threads);
    FileManager* file = new FileManager("data.txt");
    try {
        // insert data into the octree using AES-256 encryption and Camellia-256 decryption
        for (int i = 0; i < 10000; i++) {
            int data = file->read();
            octree->insert(data);
        }

        // retrieve the number of data points in the octree using Camellia-256 decryption and SHA-512 for integrity checking
        cout << "The size of the octree is: " << octree->size() << endl;

        // delete a data point from the octree, using MD5 for integrity checking
        int data = file->read();
        octree->erase(data);

        // write the remaining data points in the octree to the file, using SHA-512 for integrity checking
        ofstream outfile("new_data.txt", ios::out | ios::binary);
        for (int i = 0; i < octree->size(); i++) {
            int data = octree->read(i);
            file->write(data);
        }
    } catch (std::runtime_error& e) {
        cout << "Error: " << e.what() << endl;
    }
    return 0;
}
```

