namespace PasswordHasher
{
    public class PasswordHasher
    {
        private readonly Dictionary<string, HashAlgorithm> _hashers = new Dictionary<string, HashAlgorithm>();
        private readonly Dictionary<string, byte[]> _salt = new Dictionary<string, byte[]>();
        private readonly DataTable _userPasswordHashes = new DataTable();

        public PasswordHasher()
        {
            // Add hashers for different algorithms
            _hashers.Add("SHA-256", SHA256Managed.Create());
            _hashers.Add("bcrypt", new BcryptPasswordHasher());
            _hashers.Add("Argon2", new Argon2PasswordHasher());
        }

        public string HashPassword(string password)
        {
            // Generate a random salt for the given password
            byte[] salt = GetSalt();
            // Use the selected hasher to generate the hashed password
            var hashedPassword = _hashers[HashAlgorithm].ComputeHash(Encoding.UTF8.GetBytes(password + salt));
            return Convert.ToBase64String(salt) + Convert.ToBase64String(hashedPassword);
        }

        public bool VerifyPassword(string hashedPassword, string password)
        {
            // Extract the salt from the given hashed password
            byte[] salt = GetSaltFromHash(hashedPassword);
            // Use the selected hasher to verify the password against the stored hash
            var hash = _hashers[HashAlgorithm].ComputeHash(Encoding.UTF8.GetBytes(password + salt));
            return hash.SequenceEqual(Convert.FromBase64String(hashedPassword).Skip(salt.Length * 2));
        }

        public byte[] GetSalt()
        {
            // Generate a random salt for the given password
            var salt = new byte[16];
            using (var rng = new RNGCryptoServiceProvider())
            {
                rng.GetBytes(salt);
            }
            return salt;
        }

        public byte[] GetSaltFromHash(string hashedPassword)
        {
            // Extract the salt from the given hashed password
            var salt = Convert.FromBase64String(hashedPassword).Take(16);
            return salt;
        }

        public void StoreHashedPassword(string userId, string hashedPassword)
        {
            // Insert the hashed password into the database for the given user ID
            _userPasswordHashes.Rows.Add(userId, hashedPassword);
        }

        public string RetrieveHashedPassword(string userId)
        {
            // Retrieve the hashed password from the database for the given user ID
            var row = _userPasswordHashes.Rows.Cast<DataRow>().FirstOrDefault(x => x["UserID"].ToString() == userId);
            return row != null ? row["HashedPassword"].ToString() : null;
        }

        public void UpdateHashAlgorithm(string hashAlgorithm)
        {
            // Set the selected hasher for the given algorithm and update the cache
            _hashers[HashAlgorithm] = GetHasherForAlgorithm(hashAlgorithm);
        }

        private static HashAlgorithm GetHasherForAlgorithm(string hashAlgorithm)
        {
            switch (hashAlgorithm)
            {
                case "SHA-256":
                    return SHA256Managed.Create();
                case "bcrypt":
                    return new BcryptPasswordHasher();
                case "Argon2":
                    return new Argon2PasswordHasher();
            }
        }

        public void Cleanup()
        {
            // Remove any expired or invalid entries from the cache and database
            var now = DateTime.UtcNow;
            _userPasswordHashes.Rows.Cast<DataRow>().Where(x => x["ExpirationDate"].ToString() < now).ToList().ForEach(x => x.Delete());
        }

        public void CacheUserHash(string userId, string hashedPassword)
        {
            // Add the hashed password to the cache for the given user ID
            _userPasswordHashes[userId] = hashedPassword;
        }

        public string GetCachedHashedPassword(string userId)
        {
            // Retrieve the cached hashed password for the given user ID
            return _userPasswordHashes[userId].ToString();
        }

        public void LogActivity(string message)
        {
            // Write a log entry with the given message
            Console.WriteLine(message);
        }
    }
}
