using namespace std;

// define the number of workers to use for processing log files
const int num_workers = 4;
// define the maximum number of retries for failed reads
const int max_retries = 3;
// define the file rotation detection interval in seconds
const int rotate_interval = 60;

struct LogFile {
    char *filename; // the filename of the log file
    int fd; // the file descriptor for the log file
    long size; // the current size of the log file
    time_t mtime; // the last modification time of the log file
};

struct LogLine {
    char *line; // the contents of the log line
    int length; // the length of the log line
    float average; // the average value of the last two numerical fields in the log line
};

void process_log(LogFile &file, sem_t &sem) {
    long pos = 0; // the current position in the file
    int retries = 0; // the number of retries for failed reads
    while (retries < max_retries) {
        try {
            char buffer[1024]; // a temporary buffer for reading lines from the file
            int len = read(file.fd, buffer, sizeof(buffer));
            if (len == 0) {
                break; // no more data to read, exit the loop
            } else if (len < 0) {
                throw "read error";
            }

            string line = string(buffer, len); // the current log line being processed
            int num_fields = 0; // the number of numerical fields in the log line
            float sum = 0.0f; // the sum of the numerical values in the log line

            for (int i = 0; i < line.length(); i++) {
                if (!isdigit(line[i])) {
                    num_fields++;
                } else {
                    sum += stof(line.substr(i));
                }
            }

            if (num_fields >= 2) { // at least two numerical fields, calculate the average
                file.average = sum / num_fields;
            } else { // fewer than two numerical fields, set the average to 0
                file.average = 0.0f;
            }
        } catch (const char *err) {
            retries++; // increase the number of retries if there was an error
            cout << "Error reading from log file " << file.filename << ": " << err << endl;
            usleep(1000); // sleep for 1 second before retrying
        }
    }

    sem_post(&sem); // signal the worker thread is done processing the file
}

void *worker(void *arg) {
    LogFile &file = *((LogFile *) arg);
    sem_t &sem = *((sem_t *) arg + 1);
    pthread_detach(pthread_self()); // detach the worker thread from the main process

    while (true) {
        sem_wait(&sem); // wait for the semaphore to be signaled
        if (file.size == file.mtime) { // check if the log file has been modified since last read
            break; // no new data, exit the loop
        } else { // new data available, process the log file concurrently
            process_log(file, sem);
        }
    }
}

int main() {
    DIR *dirp = opendir("."); // open the current directory for reading
    if (dirp == NULL) {
        perror("Error opening directory");
        exit(1);
    }

    struct dirent *dp; // a pointer to the next directory entry
    while ((dp = readdir(dirp)) != NULL) {
        if (!strcmp(dp->d_name, ".") || !strcmp(dp->d_name, "..")) {
            continue; // skip over "." and ".." directories
        }

        char *filename = dp->d_name; // the filename of the log file
        struct stat st; // a structure for storing file status information
        int fd = open(filename, O_RDONLY); // open the log file for reading
        if (fd < 0) {
            perror("Error opening file");
            continue; // skip over unreadable files
        }

        fstat(fd, &st); // get the file status information
        long size = st.st_size; // the current size of the log file
        time_t mtime = st.st_mtime; // the last modification time of the log file

        LogFile file {filename, fd, size, mtime}; // create a new LogFile structure
        sem_t sem; // a semaphore to synchronize access to the log file
        sem_init(&sem, 0, 0); // initialize the semaphore with a value of 0

        pthread_create(NULL, NULL, worker, (void *) &file); // create a new thread for processing the log file
    }

    closedir(dirp); // close the directory stream
    return 0;
}
```
This program uses the `DIR` structure and the `readdir()` function to iterate over the files in the current directory. It checks if each file is readable and has a filename that does not start with "." or "..", and then opens it for reading using the `open()` function. It stores the file status information in a `struct stat` structure, which includes the file size and last modification time.

The program creates a new `LogFile` structure for each readable file found in the directory, and initializes a semaphore with a value of 0 to synchronize access to each log file. It then creates a new thread using the `pthread_create()` function to process the log file concurrently using the `worker()` function.

The `process_log()` function reads lines from the log file using the `read()` function, and extracts the numerical values in each line using string manipulation functions. It calculates the average of the numerical values in the line if there are at least two numerical fields present, or sets the average to 0 otherwise.

The program uses the `usleep()` function to sleep for 1 second before retrying if there was an error reading from the log file. This allows the program to handle transient errors and continue processing the log files.

The main thread creates a new `LogFile` structure for each log file found in the directory, and initializes a semaphore with a value of 0 to synchronize access to each log file. It then creates a new thread using the `pthread_create()` function to process the log file concurrently using the `worker()` function.

The program uses the `sem_post()` function to signal the worker thread is done processing the file, and the `sem_wait()` function to wait for the semaphore to be signaled. This allows the main thread to monitor the progress of each worker thread and detect when a file has been modified since last read.

The program uses the `pthread_detach()` function to detach the worker thread from the main process, allowing the main thread to exit while the worker threads continue processing the log files.

