            {
                var user = await _userManager.FindByNameAsync(username);
                if (user == null)
                {
                    return false;
                }

                var result = await _signInManager.CheckPasswordSignInAsync(user, lockoutOnFailure: true);
                if (result.Succeeded)
                {
                    await SetUserLockoutPoliciesAsync(user);
                    return true;
                }
                else
                {
                    await _signInManager.SignOutAsync();
                    return false;
                }
            }
            catch (Exception ex)
