<?php
// Authentication System

namespace Auth;

use Bcrypt\Bcrypt;
use Argon2id\Argon2id;
use RandomString\RandomString;
use Database\DatabaseManager;
use Session\SessionManager;
use Cache\CacheManager;

class Authentication {
  private $bcrypt;
  private $argon2id;
  private $randomString;
  private $database;
  private $session;
  private $cache;

  public function __construct(Bcrypt $bcrypt, Argon2id $argon2id, RandomString $randomString, DatabaseManager $database, SessionManager $session, CacheManager $cache) {
    $this->bcrypt = $bcrypt;
    $this->argon2id = $argon2id;
    $this->randomString = $randomString;
    $this->database = $database;
    $this->session = $session;
    $this->cache = $cache;
  }

  public function register(string $username, string $password) {
    // Validate input parameters
    if (empty($username)) {
      throw new \Exception("Username cannot be empty");
    }
    if (empty($password)) {
      throw new \Exception("Password cannot be empty");
    }

    // Generate salt and hashed password
    $salt = $this->randomString->generate(8);
    $hashedPassword = $this->bcrypt->hash($password, $salt);

    // Insert user into database
    $user = [
      'username' => $username,
      'password' => $hashedPassword,
      'salt' => $salt
    ];
    $this->database->insert('users', $user);
  }

  public function login(string $username, string $password) {
    // Validate input parameters
    if (empty($username)) {
      throw new \Exception("Username cannot be empty");
    }
    if (empty($password)) {
      throw new \Exception("Password cannot be empty");
    }

    // Query database for user
    $user = $this->database->find('users', ['username' => $username]);
    if (!$user) {
      throw new \Exception("User not found");
    }

    // Validate password
    if (!$this->bcrypt->verify($password, $user['password'], $user['salt'])) {
      throw new \Exception("Invalid password");
    }

    // Generate token and store in cache
    $token = $this->randomString->generate(64);
    $this->cache->set($username, $token);

    // Update session with token
    $this->session->put('token', $token);
  }

  public function logout() {
    // Clear token from cache and update session
    $this->cache->clear($this->session->get('token'));
    $this->session->forget('token');
  }

  public function getToken(string $username) {
    // Validate input parameter
    if (empty($username)) {
      throw new \Exception("Username cannot be empty");
    }

    // Query cache for token
    $token = $this->cache->get($username);
    if (!$token) {
      throw new \Exception("Token not found in cache");
    }

    return $token;
  }
}
