<?php
// Database Manager

namespace Database;

use PDO;
use PDOException;
use Exception;

class DatabaseManager {
  private $pdo;

  public function __construct(PDO $pdo) {
    $this->pdo = $pdo;
  }

  public function insert($table, array $data) {
    try {
      // Prepare statement and execute query
      $statement = $this->pdo->prepare("INSERT INTO {$table} (username, password, salt) VALUES (:username, :password, :salt)");
      $statement->execute([
        'username' => $data['username'],
        'password' => $data['password'],
        'salt' => $data['salt']
      ]);
    } catch (PDOException $e) {
      throw new Exception("Error inserting into database: {$e->getMessage()}");
    }
  }

  public function find($table, array $where = []) {
    try {
      // Prepare statement and execute query
      $statement = $this->pdo->prepare("SELECT * FROM {$table} WHERE username = :username");
      $statement->execute([
        'username' => $data['username']
      ]);

      // Return result as array
      return $statement->fetchAll();
    } catch (PDOException $e) {
      throw new Exception("Error finding in database: {$e->getMessage()}");
    }
  }
}
