#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <errno.h>
#include <limits.h>

#define MAX_PATH_LENGTH 256
#define MIN_IMAGE_WIDTH 100
#define MAX_IMAGE_WIDTH 5000
#define DEFAULT_TOOL_PATH "/path/to/tool"
#define DEFAULT_CONFIGURATION {.option1 = true, .option2 = false}

typedef struct Configuration {
    bool option1;
    bool option2;
} Configuration;

int convertImageToPdf(const char *inputFileName, const char *outputFileName, const Configuration *configuration) {
    // Validate input file name and output file name
    if (!inputFileName || !outputFileName) {
        fprintf(stderr, "Error: Invalid input file name or output file name\n");
        return 1;
    }

    // Validate image dimensions before conversion
    struct stat sb;
    if (stat(inputFileName, &sb) == -1 || sb.st_size < MIN_IMAGE_WIDTH * MIN_IMAGE_HEIGHT) {
        fprintf(stderr, "Error: Image file too small or does not exist\n");
        return 1;
    }

    // Open input and output files
    FILE *inputFile = fopen(inputFileName, "rb");
    if (!inputFile) {
        fprintf(stderr, "Error: Could not open input file for reading\n");
        return 1;
    }
    FILE *outputFile = fopen(outputFileName, "wb");
    if (!outputFile) {
        fclose(inputFile);
        fprintf(stderr, "Error: Could not open output file for writing\n");
        return 1;
    }

    // Set tool path and configuration settings
    char *toolPath = getenv("TOOL_PATH");
    if (!toolPath) {
        toolPath = DEFAULT_TOOL_PATH;
    }
    Configuration config = configuration ? *configuration : DEFAULT_CONFIGURATION;

    // Run conversion command
    int status = system(toolPath, inputFile, outputFile, config);
    if (status == -1) {
        fclose(inputFile);
        fclose(outputFile);
        fprintf(stderr, "Error: Could not execute tool\n");
        return 1;
    } else if (status != 0) {
        fclose(inputFile);
        fclose(outputFile);
        fprintf(stderr, "Warning: Tool returned non-zero exit status: %d\n", status);
        return 0;
    }

    // Log operation
    char logMessage[MAX_PATH_LENGTH + 128];
    snprintf(logMessage, sizeof(logMessage), "Converted %s to %s with configuration %s\n", inputFileName, outputFileName, config);
    FILE *logFile = fopen("log.txt", "a");
    if (logFile) {
        fputs(logMessage, logFile);
        fclose(logFile);
    } else {
        // TODO: Log error to stderr instead of silently failing
        fprintf(stderr, "Error: Could not open log file for writing\n");
    }

    // Close files and return
    fclose(inputFile);
    fclose(outputFile);
    return 0;
}
