using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Xml;
using System.Xml.Schema;
using System.Xml.XPath;
using System.IO;

namespace XMLParser
{
    public class XMLDocumentManager
    {
        private XmlDocument _xmlDoc;
        private XmlSchemaValidator _xsdValidator;
        private Dictionary<string, object> _cachedData;

        public XMLDocumentManager(XmlDocument xmlDoc, XmlSchemaValidator xsdValidator)
        {
            _xmlDoc = xmlDoc;
            _xsdValidator = xsdValidator;
            _cachedData = new Dictionary<string, object>();
        }

        public async Task ParseAndValidateAsync(Stream stream, CancellationToken cancellationToken = default)
        {
            await _xsdValidator.ValidateAsync(stream, cancellationToken);
            _xmlDoc.Load(stream);
        }

        public bool ValidateXPathQuery(string xpathQuery)
        {
            try
            {
                XPathNavigator navigator = _xmlDoc.CreateNavigator();
                XPathExpression expression = navigator.Compile(xpathQuery);
                return expression.MatchNode(_xmlDoc);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error validating XPath query: {ex.Message}");
                return false;
            }
        }

        public void UpdateCachedData(string xpathQuery)
        {
            try
            {
                XPathNavigator navigator = _xmlDoc.CreateNavigator();
                XPathExpression expression = navigator.Compile(xpathQuery);
                object data = expression.Evaluate(_xmlDoc);
                if (data != null)
                {
                    _cachedData[xpathQuery] = data;
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error updating cached data: {ex.Message}");
            }
        }

        public object GetCachedData(string xpathQuery)
        {
            if (_cachedData.ContainsKey(xpathQuery))
            {
                return _cachedData[xpathQuery];
            }
            else
            {
                return null;
            }
        }

        public async Task UpdateXmlDocumentAsync(Stream stream, CancellationToken cancellationToken = default)
        {
            await _xsdValidator.ValidateAsync(stream, cancellationToken);
            _xmlDoc.Load(stream);
            UpdateCachedData();
        }
    }
}
