from threading import Thread
from concurrent.futures import ThreadPoolExecutor
from time import sleep

class ConfigurationManager:
    def __init__(self):
        self.configs = {}
        self.lock = Thread()

    def fetch_config(self, url: str) -> List[Dict[str, Any]]:
        response = requests.get(url)
        if response.status_code == 200:
            return json.loads(response.content)
        else:
            raise Exception("Failed to fetch config from {}".format(url))

    def parse_config(self, configs: List[Dict[str, Any]]) -> None:
        for config in configs:
            self.configs[config["key"]] = config["value"]

    def get_config(self, key: str) -> Dict[str, Any]:
        return self.configs[key]

    def set_config(self, key: str, value: Any) -> None:
        self.configs[key] = value

    def update_configs(self, configs: List[Dict[str, Any]]) -> None:
        with self.lock:
            for config in configs:
                key = config["key"]
                if key not in self.configs:
                    continue
                value = config["value"]
                self.configs[key] = value

    def insert_into_forward_list(self, position_index: int, key: str) -> None:
        with self.lock:
            if position_index < 0 or position_index >= len(self.configs):
                raise ValueError("Position index out of bounds")
            self.configs.insert(position_index, (key,))

    def hash_password(self, password: str) -> str:
        return hashlib.sha256(password.encode()).hexdigest()

    def log_deserialization_process(self, configs: List[Dict[str, Any]]) -> None:
        for config in configs:
            if "key" not in config or "value" not in config:
                continue
            key = config["key"]
            value = config["value"]
            self.logger.info("Deserialized {}: {}".format(key, value))

    def fetch_and_parse_configs(self) -> None:
        while True:
            try:
                configs = self.fetch_config(self.config_url)
                self.parse_config(configs)
                self.update_configs(configs)
            except Exception as e:
                self.logger.error("Failed to fetch and parse configs: {}".format(e))
            sleep(60)

    def update_configs_from_external_source(self, url: str) -> None:
        while True:
            try:
                response = requests.get(url)
                if response.status_code == 200:
                    configs = json.loads(response.content)
                    self.update_configs(configs)
            except Exception as e:
                self.logger.error("Failed to update configs from external source: {}".format(e))
            sleep(60)

    def realtime_update_configs(self, url: str) -> None:
        while True:
            try:
                connection = create_connection(url)
                for message in connection.recv_text():
                    configs = json.loads(message)
                    self.update_configs(configs)
            except Exception as e:
                self.logger.error("Failed to receive realtime updates from external source: {}".format(e))

    def handle_password_hashing(self, password: str) -> str:
        return self.hash_password(password)

    def handle_deserialization(self, configs: List[Dict[str, Any]]) -> None:
        for config in configs:
            if "key" not in config or "value" not in config:
                continue
            key = config["key"]
            value = config["value"]
            self.set_config(key, value)

    def handle_insertion_into_forward_list(self, position_index: int, key: str) -> None:
        with self.lock:
            if position_index < 0 or position_index >= len(self.configs):
                raise ValueError("Position index out of bounds")
            self.configs.insert(position_index, (key,))

    def handle_password_hashing_and_logging(self, password: str) -> None:
        hashed_password = self.hash_password(password)
        self.logger.info("Hashed password: {}".format(hashed_password))
