import argparse
import os
import re
from collections import defaultdict

class LogProcessor:
    def __init__(self, directory):
        self.directory = directory
        self.logs = {}
        self.total_lines = 0
        self.total_words = 0
        self.total_chars = 0
        self.device_ids = set()
        self.timestamps = []
        self.severity_levels = {
            "INFO": [],
            "WARNING": [],
            "ERROR": []
        }

    def process(self):
        for filename in os.listdir(self.directory):
            if filename.endswith(".log"):
                with open(os.path.join(self.directory, filename), "r") as f:
                    self.process_file(f)

    def process_file(self, file):
        for line in file:
            self.total_lines += 1
            words = re.split(r"\W+", line)
            self.total_words += len(words)
            self.total_chars += len(line)
            device_id, timestamp, severity = self.parse_log_line(line)
            if device_id:
                self.device_ids.add(device_id)
                self.timestamps.append(timestamp)
                self.severity_levels[severity].append(1)
            else:
                print(f"Invalid log line: {line}")

    def parse_log_line(self, line):
        # Regex pattern to match device ID, timestamp, and severity level in a log line
        pattern = r"^([a-zA-Z0-9\-]+) (\d+-\d+-\d+) (INFO|WARNING|ERROR)$"
        matches = re.search(pattern, line)
        if matches:
            return matches.group(1), matches.group(2), matches.group(3)
        else:
            return None, None, None

    def generate_report(self):
        # Generate a report of the processed logs in CSV format
        report = "Device ID,Timestamp,Severity Level,Line Count,Word Count,Character Count\n"
        for device_id in self.device_ids:
            for timestamp in self.timestamps:
                for severity in ["INFO", "WARNING", "ERROR"]:
                    count = 0
                    if (device_id, timestamp, severity) in self.logs:
                        count = len(self.logs[(device_id, timestamp, severity)])
                    report += f"{device_id},{timestamp},{severity},{count},{self.total_words},{self.total_chars}\n"
        return report

if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--directory", type=str, required=True)
    parser.add_argument("--output", type=str, default="report.csv")
    parser.add_argument("--exclude-file-types", nargs="+", type=str, default=[".log", ".txt"])
    args = parser.parse_args()

    log_processor = LogProcessor(args.directory)
    for file_type in args.exclude_file_types:
        log_processor.process_files(file_type)
    report = log_processor.generate_report()
    with open(args.output, "w") as f:
        f.write(report)
