using System;
using UnityEngine;

public class ValueGenerator : MonoBehaviour
{
    // Constructor for the ValueGenerator class
    public ValueGenerator(int min, int max)
    {
        if (min > max)
            throw new ArgumentOutOfRangeException("Minimum value must be less than or equal to maximum value.");
        this.Min = min;
        this.Max = max;
    }

    // Minimum value for the range
    public int Min { get; set; }

    // Maximum value for the range
    public int Max { get; set; }

    // Generate a random integer within the specified range, optionally constrained to be within specific bounds
    public int GenerateInt(int min = null, int max = null)
    {
        if (min != null && max != null)
            return UnityEngine.Random.Range(min, max);
        else
            return UnityEngine.Random.Range(Min, Max);
    }

    // Generate a random float within the specified range, optionally constrained to be within specific bounds
    public float GenerateFloat(float min = null, float max = null)
    {
        if (min != null && max != null)
            return UnityEngine.Random.Range(min, max);
        else
            return UnityEngine.Random.Range(Min, Max);
    }

    // Generate an array of random integers within the specified range, optionally constrained to be within specific bounds
    public int[] GenerateIntArray(int size, int min = null, int max = null)
    {
        if (size < 0)
            throw new ArgumentOutOfRangeException("Size must be non-negative.");
        if (min != null && max != null)
        {
            int[] array = new int[size];
            for (int i = 0; i < size; i++)
                array[i] = GenerateInt(min, max);
            return array;
        }
        else
        {
            int[] array = new int[size];
            for (int i = 0; i < size; i++)
                array[i] = GenerateInt();
            return array;
        }
    }

    // Generate an array of random floats within the specified range, optionally constrained to be within specific bounds
    public float[] GenerateFloatArray(int size, float min = null, float max = null)
    {
        if (size < 0)
            throw new ArgumentOutOfRangeException("Size must be non-negative.");
        if (min != null && max != null)
        {
            float[] array = new float[size];
            for (int i = 0; i < size; i++)
                array[i] = GenerateFloat(min, max);
            return array;
        }
        else
        {
            float[] array = new float[size];
            for (int i = 0; i < size; i++)
                array[i] = GenerateFloat();
            return array;
        }
    }

    // Override ToString method to display the current range and any additional constraints applied
    public override string ToString()
    {
        return $"Range: {Min} - {Max}{(min != null && max != null ? ", Constrained to " + min + " - " + max : "")}";
    }

    // Integration with Unity's MonoBehaviour for use in Unity projects, allowing the ValueGenerator instance to be attached as a component to game objects. Ensure that the class can handle scenarios where the MonoBehaviour context is lost during runtime.
    private void OnDestroy()
    {
        this.Min = 0;
        this.Max = 1;
    }
}
