class SessionIdGenerator {
  private static $generator;

  public function __construct() {
    self::$generator = new \std\mt19937_64();
  }

  public function generateSessionId() {
    // Seed the generator with current time and additional entropy
    $seed = time() + file_get_contents('/dev/urandom');
    self::$generator->seed($seed);

    // Generate a new session ID
    $sessionId = base64_encode(self::$generator->randomBytes(22));

    // Check if the generated session ID is already in use
    while ($this->isSessionIdInUse($sessionId)) {
      // Regenerate a new session ID until a unique one is found
      $sessionId = base64_encode(self::$generator->randomBytes(22));
    }

    return $sessionId;
  }

  public function isSessionIdInUse($sessionId) {
    // Check if the session ID is already in use within the application's database
    try {
      $result = $this->database->query("SELECT COUNT(*) FROM sessions WHERE id='$sessionId'");
      return ($result->fetchColumn() > 0);
    } catch (\PDOException $e) {
      // Handle potential errors during file access or database operations
      error_log($e->getMessage());
      return false;
    }
  }
}

