  try {
    $lines = explode("\n", file_get_contents($file));
    usort($lines, function ($a, $b) { return strcmp($a, $b); });
    if (count($lines) > 0) {
      return intval(end($lines));
    } else {
      return null;
    }
  } catch (\Exception $e) {
    // Handle exceptions gracefully
    error_log($e->getMessage());
    return null;
  }
}
