public class DynamicFileProcessor
{
    private readonly ILogger _logger;
    private readonly IDataStorage _storage;
    private readonly AesEncryption _encryption;
    private readonly FileFormatDetector _formatDetector;

    public DynamicFileProcessor(ILogger logger, IDataStorage storage, AesEncryption encryption, FileFormatDetector formatDetector)
    {
        _logger = logger;
        _storage = storage;
        _encryption = encryption;
        _formatDetector = formatDetector;
    }

    public void ProcessFile(string filePath, int chunkSize = 1024 * 1024)
    {
        var format = _formatDetector.DetectFormat(filePath);
        if (format == FileFormat.Unknown)
        {
            throw new Exception("Unsupported file format");
        }

        using (var stream = new FileStream(filePath, FileMode.Open))
        {
            var reader = new BinaryReader(stream);
            var writer = new BinaryWriter(stream);

            // Read the first chunk and detect if it's encrypted
            var buffer = reader.ReadBytes(chunkSize);
            bool isEncrypted = _encryption.IsEncrypted(buffer);

            if (isEncrypted)
            {
                try
                {
                    buffer = _encryption.Decrypt(buffer);
                }
                catch (Exception ex)
                {
                    _logger.Error("Failed to decrypt file", ex);
                    throw;
                }
            }

            // Process the first chunk and handle any errors
            try
            {
                ProcessChunk(buffer, format);
            }
            catch (Exception ex)
            {
                _logger.Error("Failed to process first chunk", ex);
                throw;
            }

            // Read and process remaining chunks in parallel
            var chunks = Enumerable.Range(1, (int)(stream.Length - buffer.Length) / chunkSize).Select(i => reader.ReadBytes(chunkSize)).ToList();
            Parallel.ForEach(chunks, chunk =>
            {
                if (isEncrypted)
                {
                    try
                    {
                        chunk = _encryption.Decrypt(chunk);
                    }
                    catch (Exception ex)
                    {
                        _logger.Error("Failed to decrypt chunk", ex);
                        throw;
                    }
                }

                try
                {
                    ProcessChunk(chunk, format);
                }
                catch (Exception ex)
                {
                    _logger.Error("Failed to process chunk", ex);
                    throw;
                }
            });
        }
    }

    private void ProcessChunk(byte[] chunk, FileFormat format)
    {
        switch (format)
        {
            case FileFormat.CSV:
                // Process CSV chunk
                break;
            case FileFormat.JSON:
                // Process JSON chunk
                break;
            case FileFormat.XML:
                // Process XML chunk
                break;
            default:
                throw new Exception("Unsupported file format");
        }
    }
}
