#include <iostream>
#include <cmath>
#include <vector>
#include <mutex>

using namespace std;

// Global variables
int globalEnergyCap = 100;
int attackCount[3]; // Track the number of times each attack has been used in a session
double energyLevel = 100.0;

// Function to randomly select one of three attacks for a video game character
void randomAttack() {
    // Create a vector to store the cooldown periods for each attack
    vector<double> cooldownPeriods{5, 7, 10};

    // Calculate the current time in seconds
    double currentTime = (double)time(NULL);

    // Loop through all attacks and check if their cooldown period has passed
    for (int i = 0; i < 3; i++) {
        if (cooldownPeriods[i] + attackCount[i] * 10 > currentTime) {
            // If the cooldown period has not passed, continue to the next attack
            continue;
        }

        // Print the selected attack number to the console
        cout << "Selected attack: " << i+1 << endl;

        // Update the energy level based on the chosen attack
        switch (i) {
            case 0:
                energyLevel -= 10.0;
                break;
            case 1:
                energyLevel -= 15.0;
                break;
            case 2:
                energyLevel -= 20.0;
                break;
        }

        // Update the attack count for this session
        attackCount[i]++;

        // Check if the global energy cap has been exceeded and reset it if necessary
        if (energyLevel < 0) {
            energyLevel = 0;
        } else if (energyLevel > globalEnergyCap) {
            energyLevel = globalEnergyCap;
        }
    }
}

// Function to enforce a global energy cap of 100 points and reset it if necessary
void checkEnergyCap() {
    // Check if the energy level exceeds the global energy cap
    if (energyLevel > globalEnergyCap) {
        energyLevel = globalEnergyCap;
    }
}

// Thread-safe mechanism to handle concurrent calls from different game entities
void randomAttackThreadSafe() {
    mutex mtx;
    lock_guard<mutex> lck(mtx);
    randomAttack();
}
```
This code creates a vector of cooldown periods for each attack, and uses a loop to check if the current time has passed the cooldown period for each attack. If it has, then the selected attack is printed to the console and the energy level is updated based on the chosen attack. The function also updates the attack count for this session and checks if the global energy cap has been exceeded. If it has, the energy level is reset to the global energy cap.

The `randomAttackThreadSafe` function is thread-safe by using a mutex to lock the access to the shared variables.

It's important to note that this code does not handle any errors or exceptions that may occur during execution, so it's recommended to add error handling mechanisms as necessary.

