import java.util.List;
import java.util.concurrent.Executors;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.logging.Level;
import java.util.logging.Logger;

import com.sendgrid.SendGrid;
import com.sendgrid.Method;
import com.sendgrid.Request;
import com.sendgrid.Response;

public class SendNotificationEmails {
    private static final Logger LOGGER = Logger.getLogger(SendNotificationEmails.class.getName());
    private static final int MAX_RETRY_ATTEMPTS = 5;
    private static final long RETRY_INTERVAL = TimeUnit.SECONDS.toMillis(10);

    public void sendNotifications(List<String> recipients, List<NotificationRule> notificationRules) {
        ExecutorService executor = Executors.newFixedThreadPool(5);

        for (String recipient : recipients) {
            NotificationRule rule = getMatchingNotificationRule(recipient, notificationRules);
            if (rule != null) {
                Future<Void> future = executor.submit(() -> sendEmail(recipient, rule));
                try {
                    future.get();
                } catch (InterruptedException | ExecutionException e) {
                    LOGGER.log(Level.SEVERE, "Error sending email to " + recipient, e);
                }
            }
        }

        executor.shutdown();
    }

    private NotificationRule getMatchingNotificationRule(String recipient, List<NotificationRule> notificationRules) {
        for (NotificationRule rule : notificationRules) {
            if (rule.getRecipients().contains(recipient)) {
                return rule;
            }
        }
        return null;
    }

    private Void sendEmail(String recipient, NotificationRule rule) throws IOException, MessagingException {
        SendGrid sendgrid = new SendGrid("<YOUR_SENDGRID_API_KEY>");

        Request request = new Request();
        request.setMethod(Method.POST);
        request.setEndpoint("mail/send");
        request.setBody("{\"personalizations\": [{\"to\": [\"" + recipient + "\"]}], \"from\": {\"email\": \"no-reply@example.com\", \"name\": \"No Reply\"}, \"subject\": \"Notification from Example Inc.\", \"content\": [{\"type\": \"text/html\", \"value\": \"Hello " + recipient + ", this is a test email\"}]}");
        Response response = sendgrid.api(request);

        if (response.getStatusCode() == 202) {
            LOGGER.log(Level.INFO, "Email sent to " + recipient);
        } else {
            LOGGER.log(Level.SEVERE, "Error sending email to " + recipient + ": " + response.getBody());
        }
    }
}
