    }

    class MersenneTwister
    {
        private readonly int[] _mt;
        private int _index = 0;

        public MersenneTwister()
        {
            // Initialize the random number generator with a seed value
            _mt = new int[624];
            _mt[_index] = 397;
        }

        ~MersenneTwister()
        {
            // Clean up resources
            _mt = null;
        }

        public int Next()
        {
            if (_index >= 624)
                _index = 0;

            var mt = new[] { 0, 0, 0, 0, 0, 0, 0, 0 };

            for (var i = 0; i < 12; ++i)
            {
                var j = _index + 1 + i * 7;
                var temp = (_mt[j] & 0x80000000) | ((_mt[j + 1] & 0x7fffffff) << 1);
                mt[i] = _mt[j] = (temp ^ (_mt[j] >> 30)) * 1664525;
            }

            int val = 0;
            for (var i = 0; i < 7; ++i)
                val = val * 31 + mt[_index++];

            return val & 0xffffffff;
        }
    }
}
