class DynamicLoader {
public:
    using FactoryFunction = std::function<std::unique_ptr<Base>()>;

    DynamicLoader() : registry_{} {}

    // Adds a factory function to the registry.
    void addFactoryFunction(const std::string& id, FactoryFunction func) {
        assert(!id.empty());
        assert(func);
        registry_[id] = std::move(func);
    }

    // Updates an existing factory function in the registry.
    void updateFactoryFunction(const std::string& id, FactoryFunction func) {
        assert(!id.empty());
        assert(func);
        registry_[id] = std::move(func);
    }

    // Deletes a factory function from the registry.
    void deleteFactoryFunction(const std::string& id) {
        assert(!id.empty());
        registry_.erase(id);
    }

    // Returns a vector of unique IDs for all registered factory functions.
    const std::vector<std::string>& getRegisteredIDs() const {
        return registeredIDs_;
    }

    // Loads and executes multiple specified JSON and JavaScript files in parallel.
    void loadAndExecuteFiles(const std::vector<std::string>& filePaths) {
        assert(!filePaths.empty());
        for (const auto& path : filePaths) {
            loadFile(path);
        }

        // Asynchronously execute each loaded file in parallel.
        std::for_each(files_.begin(), files_.end(), [this](auto& file) { executeFile(file); });
    }

