const { Worker } = require('worker_threads');
const fs = require('fs');
const path = require('path');
const chalk = require('chalk');

// Logging service
class Logger {
  constructor() {
    this.logs = [];
  }

  log(message) {
    this.logs.push(message);
  }

  getLogs() {
    return this.logs;
  }
}

// Plugin manager
class PluginManager {
  constructor(pluginPath, plugins = []) {
    this.pluginPath = pluginPath;
    this.plugins = plugins;
  }

  addPlugin(name) {
    const pluginPath = path.join(this.pluginPath, name);
    if (!fs.existsSync(pluginPath)) {
      throw new Error(`Missing plugin: ${name}`);
    }
    this.plugins.push({ name, pluginPath });
  }

  removePlugin(name) {
    const index = this.plugins.findIndex((p) => p.name === name);
    if (index < 0) {
      throw new Error(`Unknown plugin: ${name}`);
    }
    this.plugins.splice(index, 1);
  }
}

// Test runner
class TestRunner {
  constructor(label, plugins = [], numWorkers = 4) {
    this.label = label;
    this.plugins = plugins;
    this.numWorkers = numWorkers;
    this.workers = [];
    this.results = [];
  }

  run() {
    // Load plugins
    const pluginManager = new PluginManager(this.pluginPath);
    for (const plugin of this.plugins) {
      pluginManager.addPlugin(plugin.name);
    }

    // Start workers
    for (let i = 0; i < this.numWorkers; i++) {
      const worker = new Worker(`${__dirname}/test-worker.js`, {
        workerData: { label: this.label, plugins: pluginManager.plugins },
      });
      this.workers.push(worker);
    }

    // Run tests
    for (const worker of this.workers) {
      const result = await worker.run();
      this.results.push(result);
    }
  }

  getResults() {
    return this.results;
  }
}

// Test worker
class TestWorker {
  constructor(label, plugins) {
    this.label = label;
    this.plugins = plugins;
  }

  run() {
    const logger = new Logger();
    for (const plugin of this.plugins) {
      try {
        // Load plugin
        const modulePath = path.join(this.pluginPath, plugin.name);
        if (!fs.existsSync(modulePath)) {
          throw new Error(`Missing plugin: ${plugin.name}`);
        }
        const module = require(modulePath);

        // Run tests
        for (const test of plugin.tests) {
          try {
            logger.log(`Running test ${chalk.green(test.name)}`);
            const startTime = Date.now();
            test.callback(module);
            const endTime = Date.now();
            const duration = (endTime - startTime) / 1000;
            logger.log(`Test ${chalk.green(test.name)} completed in ${duration} seconds`);
          } catch (error) {
            console.error(`Error running test ${chalk.red(test.name)}`, error);
            logger.log(`Test ${chalk.red(test.name)} failed with message: ${error.message}`);
          }
        }
      } catch (error) {
        console.error(`Error loading plugin ${chalk.red(plugin.name)}`, error);
        logger.log(`Plugin ${chalk.red(plugin.name)} failed with message: ${error.message}`);
      } finally {
        // Close file handles and release memory
        for (const module of Object.values(require.cache)) {
          delete require.cache[module.id];
        }
      }
    }

    return logger.getLogs();
  }
}
```

