import json
from typing import Dict, List, Optional, Tuple

class JSONObject:
    def __init__(self, data: Dict[str, object], factory_funcs: Dict[str, Callable[[], JSONObject]]):
        self.data = data
        self.factory_funcs = factory_funcs

    @staticmethod
    def from_json(json_string: str) -> "JSONObject":
        data = json.loads(json_string)
        return JSONObject(data, {})

    def to_json(self) -> str:
        return json.dumps(self.data)

    def add_factory_func(self, id: str, factory_func: Callable[[], JSONObject]):
        self.factory_funcs[id] = factory_func

    def create_instance(self, id: str) -> JSONObject:
        return self.factory_funcs[id]()

    @staticmethod
    def deserialize(byte_array: bytes) -> Tuple[JSONObject, Optional[str]]:
        try:
            json_string = byte_array.decode("utf-8")
            obj = JSONObject.from_json(json_string)
            return obj, None
        except Exception as e:
            return None, f"Error deserializing object: {e}"

    @staticmethod
    def hash_password(password: str) -> Tuple[str, Optional[str]]:
        try:
            salt = get_random_bytes(16).hex()
            pwd_hash = hashlib.pbkdf2_hmac("sha256", password.encode(), salt.encode(), 100000)
            return f"{salt}${pwd_hash.hex()}".lower(), None
        except Exception as e:
            return None, f"Error hashing password: {e}"

    @staticmethod
    def insert_string(forward_list: List[str], string1: str, string2: str, position: int = -1) -> List[str]:
        try:
            index = forward_list.index(string1) if position == -1 else position
            return forward_list[:index] + [string2] + forward_list[index:]
        except ValueError:
            return forward_list + [string2]

    @staticmethod
    def read_from_file(filename: str) -> Tuple[List[str], Optional[str]]:
        try:
            with open(filename, "r") as f:
                lines = f.readlines()
                return [line.strip() for line in lines], None
        except Exception as e:
            return [], f"Error reading from file {filename}: {e}"
