import json
from typing import Dict, List

def process_mqtt_message(topic: str, payload: bytes, qos: int) -> None:
    # Validate the payload against a schema
    try:
        payload = json.loads(payload)
        if not isinstance(payload, dict):
            raise ValueError("Invalid payload")
    except (ValueError, json.JSONDecodeError) as e:
        logging.error(f"Failed to validate payload: {e}")
        return

    # Dispatch the message to the appropriate handler based on the topic
    if topic == "lights":
        handle_lights_message(payload)
    elif topic == "thermostat":
        handle_thermostat_message(payload)
    else:
        logging.warning(f"Received unsupported message for topic {topic}")

    # Handle cases where the handler encounters an error
    try:
        # Execute the script and log any errors
        output = execute_script(payload["actionType"], payload["scriptId"])
        logging.info(f"Executed script with id {payload['scriptId']}")
    except (KeyError, TypeError) as e:
        logging.error(f"Failed to execute script: {e}")
    except ScriptNotFoundError:
        logging.warning(f"Script not found for id {payload['scriptId']}")

def handle_lights_message(payload: Dict[str, str]) -> None:
    # Turn the lights on/off based on the payload
    if payload["action"] == "on":
        turn_lights_on()
    elif payload["action"] == "off":
        turn_lights_off()
    else:
        logging.warning(f"Received unsupported action {payload['action']} for lights")

def handle_thermostat_message(payload: Dict[str, str]) -> None:
    # Adjust the thermostat settings based on the payload
    if payload["action"] == "set-temperature":
        set_temperature(payload["value"])
    else:
        logging.warning(f"Received unsupported action {payload['action']} for thermostat")

def execute_script(action_type: str, script_id: int) -> None:
    # Load the script from cache if available
    if script_id in script_cache:
        return script_cache[script_id]

    # Fetch and execute the script asynchronously
    def fetch_and_execute():
        try:
            response = requests.get(f"https://example.com/scripts/{script_id}")
            if response.status_code == 200:
