void loadAndExecuteScript(char* scriptName, NFAPI_CRC_INDICATION_PDU_T* crcIndication) {
    // Load the JavaScript file using a standard library function
    FILE* scriptFile = fopen(scriptName, "r");
    if (scriptFile == NULL) {
        printf("Error: Could not open script file %s\n", scriptName);
        return;
    }
    char* scriptCode = malloc(1024 * 1024);
    int numBytesRead = fread(scriptCode, 1, 1024 * 1024, scriptFile);
    if (numBytesRead < 0) {
