    int result = eval(scriptCode, crcIndication);
    if (result != 0) {
        printf("Error: Could not execute script %s\n", scriptName);
    }
}

// Define a function to read and process a single line of input data
void processLine(char* line, NFAPI_CRC_INDICATION_PDU_T* crcIndication) {
    // Split the line into fields using the delimiter
    char** fields = strtok(line, configOptions.delimiter);

    // Check if the line has at least three numerical values
    int numFields = 0;
    while (fields[numFields] != NULL) {
        ++numFields;
    }
    if (numFields < 3) {
        return;
    }

    // Parse and validate the numerical data in the line
    float values[numFields];
    for (int i = 0; i < numFields; ++i) {
        char* field = fields[i];
        if (!isNumber(field)) {
            printf("Error: Could not parse numerical value %s\n", field);
            return;
        }
        values[i] = atof(field);
    }

    // Compute the average of the last three fields
    float avgCrcIndication[3];
    for (int i = 0; i < 3; ++i) {
        avgCrcIndication[i] = values[numFields - 3 + i] / 3.0;
    }

    // Write the processed data to an output file
    OutputFileData* outputFile = getOutputFile(configOptions.outputDir, configOptions.fileName);
    if (outputFile == NULL) {
        printf("Error: Could not open output file %s\n", configOptions.fileName);
        return;
    }
    fprintf(outputFile->file, "%f %f %f\n", avgCrcIndication[0], avgCrcIndication[1], avgCrcIndication[2]);
    outputFile->numLinesWritten++;
}

// Define a function to read and process multiple input files
void processInputFiles(ConfigOptions configOptions) {
    // Create an array of InputFileData structures for all input files
    AllInputFilesData* allInputFiles = malloc(sizeof(AllInputFilesData));
    allInputFiles->fileNames = calloc(configOptions.numFiles, sizeof(char*));
    allInputFiles->files = calloc(configOptions.numFiles, sizeof(InputFileData));

    // Loop over each input file and read its data
    for (int i = 0; i < configOptions.numFiles; ++i) {
        InputFileData* inputFile = &allInputFiles->files[i];
        inputFile->fileName = configOptions.fileNames[i];
        inputFile->file = fopen(inputFile->fileName, "r");
        if (inputFile->file == NULL) {
            printf("Error: Could not open input file %s\n", inputFile->fileName);
            return;
        }
        inputFile->numLinesProcessed = 0;
        inputFile->numLinesSkipped = 0;
    }

    // Loop over each line of each input file and process it
    for (int i = 0; i < configOptions.numFiles; ++i) {
        InputFileData* inputFile = &allInputFiles->files[i];
        char* line = malloc(1024);
        while (fgets(line, 1024, inputFile->file)) {
            if (!strchr(line, '\n')) {
                ++inputFile->numLinesSkipped;
                continue;
            }
            processLine(line, &allInputFiles->files[i].crcIndication);
            ++inputFile->numLinesProcessed;
        }
    }

    // Close each input file
    for (int i = 0; i < configOptions.numFiles; ++i) {
        InputFileData* inputFile = &allInputFiles->files[i];
        fclose(inputFile->file);
    }
}

// Define a function to read and process multiple output files
void processOutputFiles(ConfigOptions configOptions) {
    // Create an array of OutputFileData structures for all output files
    AllOutputFilesData* allOutputFiles = malloc(sizeof(AllOutputFilesData));
    allOutputFiles->fileNames = calloc(configOptions.numFiles, sizeof(char*));
    allOutputFiles->files = calloc(configOptions.numFiles, sizeof(OutputFileData));

    // Loop over each output file and read its data
    for (int i = 0; i < configOptions.numFiles; ++i) {
        OutputFileData* outputFile = &allOutputFiles->files[i];
        outputFile->fileName = configOptions.fileNames[i];
        outputFile->file = fopen(outputFile->fileName, "r");
        if (outputFile->file == NULL) {
            printf("Error: Could not open output file %s\n", outputFile->fileName);
            return;
        }
        outputFile->numLinesRead = 0;
    }

    // Loop over each line of each output file and process it
    for (int i = 0; i < configOptions.numFiles; ++i) {
        OutputFileData* outputFile = &allOutputFiles->files[i];
        char* line = malloc(1024);
        while (fgets(line, 1024, outputFile->file)) {
            if (!strchr(line, '\n')) {
                ++outputFile->numLinesRead;
                continue;
            }
            processLine(line, &allOutputFiles->files[i].crcIndication);
            ++outputFile->numLinesProcessed;
        }
    }

    // Close each output file
    for (int i = 0; i < configOptions.numFiles; ++i) {
        OutputFileData* outputFile = &allOutputFiles->files[i];
        fclose(outputFile->file);
    }
}

// Define a function to read and process multiple input and output files
void processFiles(ConfigOptions configOptions) {
    // Process the input files
    processInputFiles(configOptions);

    // Process the output files
    processOutputFiles(configOptions);
}

int main(int argc, char** argv) {
    // Read the command-line arguments
    ConfigOptions configOptions = parseArguments(argc, argv);

    // Process the input and output files
    processFiles(configOptions);

    return 0;
}

