function runModuleTests(moduleLabel, testSuite, logLevel) {
  // Load the module using require()
  const module = require(`${moduleLabel}`);

  // Initialize blueslip mocking library before running each test
  const blueslip = new MockingLibrary();

  // Run the tests using a test framework like Mocha or Jest, supporting both synchronous and asynchronous test cases
  testSuite.forEach((test) => {
    if (test.async) {
      it(test.label, async () => {
        const result = await module[test.function]();
        expect(result).toEqual(test.expectedResult);
      });
    } else {
      it(test.label, () => {
        const result = module[test.function]();
        expect(result).toEqual(test.expectedResult);
      });
    }
  });

  // Reset and clean up blueslip mocking library after each test to avoid state interference between tests
  blueslip.reset();
  blueslip.cleanup();

  // Log information to the console based on the specified logLevel, including the name of the module being tested, the name of each test, and any relevant details during the test execution
  if (logLevel === "verbose") {
    console.log(`Module ${moduleLabel} testing started`);
    testSuite.forEach((test) => {
      console.log(`Testing ${test.label}`);
      const result = module[test.function]();
      console.log(`${test.label} Result: ${result}`);
    });
  } else if (logLevel === "info") {
    console.log(`Module ${moduleLabel} testing started`);
    testSuite.forEach((test) => {
      const result = module[test.function]();
      console.log(`${test.label} Result: ${result}`);
    });
  } else if (logLevel === "error") {
    testSuite.forEach((test) => {
      try {
        const result = module[test.function]();
        console.log(`${test.label} Result: ${result}`);
      } catch (err) {
        console.error(`Test failed with error: ${err.message}`);
      }
    });
  }

  // Implement performance optimization techniques to ensure the testing process is efficient, especially when dealing with large modules or numerous tests. This includes minimizing unnecessary module loading and optimizing asynchronous test execution.
  const asyncTests = testSuite.filter((test) => test.async);
  if (asyncTests.length > 0) {
    console.log("Optimizing asynchronous test execution...");
    // Optimize asynchronous test execution by running each test in parallel using Promises or async/await
    const results = await Promise.all(asyncTests.map((test) => module[test.function]()));
    results.forEach((result, i) => {
      console.log(`${asyncTests[i].label} Result: ${result}`);
    });
  }

  // Handle errors gracefully, providing detailed error messages and ensuring that failed tests do not interfere with subsequent tests
  try {
    testSuite.forEach((test) => {
      const result = module[test.function]();
      expect(result).toEqual(test.expectedResult);
    });
  } catch (err) {
    console.error(`Test failed with error: ${err.message}`);
  }

  // Manage resources effectively, including memory and file handles, to prevent leaks and optimize test execution
  const moduleFunctions = Object.keys(module).filter((key) => typeof module[key] === "function");
  moduleFunctions.forEach((funcName) => {
    const func = module[funcName];
    if (typeof func !== "function") return;
    console.log(`Analyzing function ${funcName} for resource leaks...`);
    // Analyze the function for memory leaks using a tool like V8 or jscoverage
    const leakResults = checkForLeaks(func, {});
    if (leakResults) console.log(`Resource leak found in ${funcName}: ${leakResults}`);
  });

  // Reset and clean up the module's internal state before running each test to maintain accurate results
  module.reset();

  // Ensure that the tests are repeatable and isolated from each other to prevent interference between tests
  const isolatedTests = testSuite.filter((test) => test.isolated);
  if (isolatedTests.length > 0) {
    console.log("Running isolated tests...");
    // Run the isolated tests in a separate process or container to isolate them from the rest of the system
    const isolatedResults = await runIsolatedTests(isolatedTests);
    isolatedResults.forEach((result, i) => {
      console.log(`${isolatedTests[i].label} Result: ${result}`);
    });
  }

  // Support concurrent test execution for multiple modules and tests, ensuring that tests do not run into race conditions or conflicts
  const concurrentTests = testSuite.filter((test) => test.concurrent);
  if (concurrentTests.length > 0) {
    console.log("Running concurrent tests...");
    // Run the concurrent tests using a testing framework like Mocha or Jest, allowing them to run in parallel and handle race conditions and conflicts
    const concurrentResults = await runConcurrentTests(concurrentTests);
    concurrentResults.forEach((result, i) => {
      console.log(`${concurrentTests[i].label} Result: ${result}`);
    });
  }

  // Provide meaningful feedback during test execution, such as the status of each test (passed/failed/skipped)
  const passed = testSuite.filter((test) => test.status === "passed");
  console.log(`${passed.length} tests passed.`);
  const failed = testSuite.filter((test) => test.status === "failed");
  if (failed.length > 0) {
    console.error(`${failed.length} tests failed.`);
    failed.forEach((test, i) => {
      console.error(`Test ${i + 1}: ${test.label}`);
    });
  }

  // Analyze test coverage and detect any issues or problems that may have occurred during the testing process
  const coveredFunctions = Object.keys(module).filter((key) => typeof module[key] === "function");
  console.log(`Analyzing test coverage for ${coveredFunctions.length} functions...`);
  // Analyze the test coverage using a tool like istanbul or jscoverage
  const coverageResults = checkCoverage(module, {});
  if (coverageResults) console.log(`Test coverage: ${coverageResults}`);

  // Provide a summary of the testing process and any issues or problems that may have occurred
  console.log("Testing complete.");
}
