#include <stdio.h>
#include <stdarg.h>
#include <string.h>
#include <time.h>
#include <syslog.h>

#define LOG_LEVELS 3
#define LOG_ERROR 0
#define LOG_WARNING 1
#define LOG_INFO 2

typedef struct {
    char *file;
    int fd;
} log_file_t;

static log_file_t log_files[LOG_LEVELS];
static int enable_logging = 1;

void logFormattedError(const char *level, const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);

    // Check if logging is enabled for the given level
    if (enable_logging && strcmp(level, "ERROR") == 0) {
        // Get current time and convert to string
        char time[256];
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(time, 256, "%Y-%m-%d %H:%M:%S", timeinfo);

        // Format message with timestamp and level
        char msg[1024];
        snprintf(msg, 1024, "[%s] [%s]: ", time, level);

        // Use va_list to format the message
        vsnprintf(msg + strlen(msg), 1024 - strlen(msg), fmt, args);

        // Log message to file
        if (log_files[LOG_ERROR].fd >= 0) {
            write(log_files[LOG_ERROR].fd, msg, strlen(msg));
        } else {
            syslog(LOG_ERR, "%s", msg);
        }
    }

    va_end(args);
}

// Function to open and close log files
void logOpenFile(const char *file) {
    int i;
    for (i = 0; i < LOG_LEVELS; ++i) {
        if (strcmp(log_files[i].file, file) == 0) {
            break;
        }
    }

    // Open file and store file descriptor in log_files array
    if (i < LOG_LEVELS) {
        log_files[i].fd = open(file, O_RDWR | O_CREAT, 0644);
    } else {
        // Opening new file, increase size of log_files array
        log_files = realloc(log_files, (LOG_LEVELS + 1) * sizeof(log_file_t));
        log_files[LOG_LEVELS].fd = open(file, O_RDWR | O_CREAT, 0644);
    }
}

void logCloseFile(const char *file) {
    int i;
    for (i = 0; i < LOG_LEVELS; ++i) {
        if (strcmp(log_files[i].file, file) == 0) {
            break;
        }
    }

    // Close file and remove it from log_files array
    if (i < LOG_LEVELS) {
        close(log_files[i].fd);
        memmove(&log_files[i], &log_files[i + 1], sizeof(log_file_t) * (LOG_LEVELS - i));
    }
}
