MAX_CONCURRENT_REQUESTS = 5

# Define a function to fetch weather data from an API endpoint
def fetch_weather(city: str, api: str) -> Dict[str, Any]:
    try:
        response = get(api + city).json()
        return response
    except RequestException as e:
        print(f"Error fetching weather data for {city}: {e}")
        return {}

# Define a function to aggregate weather data from multiple sources
def aggregate_weather(data: List[Dict[str, Any]]) -> Dict[str, Any]:
    results = []
    for d in data:
        if "temp" in d and "humidity" in d:
            results.append(d)
    return {
        "city": ",".join([r["city"] for r in results]),
        "temp": sum([r["temp"] for r in results]) / len(results),
        "humidity": sum([r["humidity"] for r in results]) / len(results)
    }

# Define a function to handle concurrent requests and aggregate data
def handle_concurrent_requests(data: List[Dict[str, Any]]) -> Dict[str, Any]:
    with ThreadPoolExecutor(max_workers=MAX_CONCURRENT_REQUESTS) as executor:
        futures = [executor.submit(aggregate_weather, data)]
        for future in as_completed(futures):
            results.append(future.result())
    return aggregate_weather(results)

# Define a function to fetch and cache weather data for multiple cities
