        public static async Task<List<TestResult>> RunTestsAsync(string moduleName, List<string> testFunctions, CancellationToken cancellationToken)
        {
            var results = new List<TestResult>();

            try
            {
                // Load the Python module dynamically using reflection
                Assembly asm = Assembly.LoadFrom($"{moduleName}.dll");

                // Create a list of all test functions in the module
                var testMethods = asm.GetTypes()
                    .Where(t => t.Name.EndsWith("Tests"))
                    .SelectMany(t => t.GetMethods().Where(m => m.Name.StartsWith("test_") && !m.IsStatic));

                // Filter the test functions to be executed based on the input list
                var filteredTestMethods = testFunctions.Count > 0 ? testMethods.Where(m => testFunctions.Contains(m.Name)) : testMethods;

                // Execute each test function and handle any exceptions that occur
                foreach (var method in filteredTestMethods)
                {
                    try
                    {
                        var result = await RunTestAsync(method, cancellationToken);
                        results.Add(result);
                    }
                    catch (Exception e)
                    {
                        Console.WriteLine($"Error running test '{method.Name}': {e.Message}");
                    }
                }
            }
            catch (Exception e)
            {
                Console.WriteLine($"Error loading Python module: {e.Message}");
            }

            return results;
        }

        private static async Task<TestResult> RunTestAsync(MethodInfo method, CancellationToken cancellationToken)
        {
            var result = new TestResult();

            try
            {
                // Decrypt the input HTML content and validate it against a whitelist of allowed tags and attributes to prevent XSS attacks
                var htmlContent = TripleDES.Decrypt(KEY, IV, method.GetCustomAttribute<HtmlData>().Value);
                var doc = new HtmlDocument();
                doc.LoadHtml(htmlContent);

                // Parse the HTML content and extract all the links
                var links = doc.DocumentNode.SelectNodes("//a[@href]");

                // Filter the links based on the whitelist of allowed tags and attributes
                var filteredLinks = links.Where(l => l.Attributes["href"].Value.StartsWith("http") && IsAllowedTagAttribute(l));

                // Execute each link and handle any exceptions that occur
                foreach (var link in filteredLinks)
                {
                    try
                    {
                        var response = await WebClient.GetAsync(link.Attributes["href"].Value, cancellationToken);
                        if (!response.IsSuccessStatusCode)
                            throw new Exception($"Error retrieving link '{link.Attributes["href"].Value}': {response.ReasonPhrase}");
                    }
                    catch (Exception e)
                    {
                        Console.WriteLine($"Error retrieving link '{link.Attributes["href"].Value}': {e.Message}");
                    }
                }
            }
            catch (Exception e)
            {
                Console.WriteLine($"Error running test '{method.Name}': {e.Message}");
            }

            return result;
        }

        private static bool IsAllowedTagAttribute(HtmlNode link)
        {
            var attributes = link.Attributes;
            if (attributes["href"].Value == null || !Uri.IsWellFormedUriString(attributes["href"].Value, UriKind.Absolute))
                return false;

            foreach (var attribute in attributes)
            {
                // Filter out any attributes that are not on the whitelist
                if (!ALLOWED_ATTRIBUTES.Contains(attribute.Name))
                    return false;
            }

            return true;
        }

        private static readonly string[] ALLOWED_ATTRIBUTES = new string[] { "href", "rel" };

        [Serializable]
        public class TestResult
        {
            public string Name { get; set; }
            public bool Passed { get; set; }
            public List<string> Errors { get; set; }
        }

        [AttributeUsage(AttributeTargets.Method, AllowMultiple = false)]
        public class HtmlData : Attribute
        {
            private string _value;

            public HtmlData(string value) => _value = value;
            public string Value => _value;
        }
    }
