namespace EncryptionDecryptionUtility
{
    public class EncryptionDecryptionUtility
    {
        private const int KEY_SIZE = 256; // in bits
        private const int SALT_SIZE = 32; // in bytes
        private const int NONCE_SIZE = 12; // in bytes

        public async Task<byte[]> EncryptFileAsync(string filePath, byte[] encryptionKey)
        {
            using (var hsm = new Hsm(encryptionKey))
            {
                var salt = GenerateSalt();
                var nonce = GenerateNonce();
                var aesGcm = new AesGcm(hsm, salt, nonce);

                var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.ReadWrite, FileShare.None, 4096, true);
                await aesGcm.EncryptFileAsync(fileStream, CancellationToken.None).ConfigureAwait(false);
            }
        }

        public async Task<byte[]> DecryptFileAsync(string filePath, byte[] encryptionKey)
        {
            using (var hsm = new Hsm(encryptionKey))
            {
                var salt = GenerateSalt();
                var nonce = GenerateNonce();
                var aesGcm = new AesGcm(hsm, salt, nonce);

                var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.ReadWrite, FileShare.None, 4096, true);
                await aesGcm.DecryptFileAsync(fileStream, CancellationToken.None).ConfigureAwait(false);
            }
        }

        private byte[] GenerateSalt()
        {
            var salt = new byte[SALT_SIZE];
            using (var rng = RandomNumberGenerator())
            {
                rng.GetBytes(salt);
            }

            return salt;
        }

        private byte[] GenerateNonce()
        {
            var nonce = new byte[NONCE_SIZE];
            using (var rng = RandomNumberGenerator())
            {
                rng.GetBytes(nonce);
            }

            return nonce;
        }
    }
}
