    private static final boolean USE_EXTERNAL_LOGGING = true;
    private static final String LOGGING_SERVICE_URL = "https://logs.example.com/";
    private static final int LOGGING_SERVICE_TIMEOUT = 10000;

    // Configuration properties
    private Properties configurationProperties;

    /**
     * Constructor for NetworkFramework
     */
    public NetworkFramework() {
        this.configurationProperties = new Properties();
    }

    /**
     * Initializes the framework with configuration properties
     * @param properties The configuration properties to initialize the framework with
     */
    public void init(Properties properties) {
        if (properties != null) {
            configurationProperties = properties;
        }
    }

    /**
     * Connects to a remote server and returns a connection object.
     * @param host The hostname or IP address of the server
     * @param port The port number of the server
     * @return A connected socket
     */
    private Socket connect(String host, int port) {
        try {
            Socket socket = new Socket();
            socket.connect(new InetSocketAddress(host, port), CONNECT_TIMEOUT);
            return socket;
        } catch (IOException e) {
            throw new RuntimeException("Error connecting to remote server", e);
        }
    }

    /**
     * Creates a secure SSL/TLS connection to a remote server using the configured truststore and keystore.
     * @param host The hostname or IP address of the server
     * @param port The port number of the server
     * @return A connected socket with an SSL/TLS context
     */
    private Socket createSslConnection(String host, int port) {
        try {
            SSLContext sslContext = createSslContext();
            SSLSocketFactory sslSocketFactory = new SSLSocketFactory(sslContext);
            SSLParameters sslParams = new SSLParameters();
            sslParams.setCipherSuites(new String[]{CIPHERS});
            sslParams.setProtocols(new String[]{PROTOCOL});
            sslParams.setEndpointIdentificationAlgorithm("HTTPS");

            Socket socket = new Socket();
            SSLSocket sslSocket = (SSLSocket) sslSocketFactory.createSocket(socket, host, port, true);
            sslSocket.setEnabledProtocols(new String[]{PROTOCOL});
            sslSocket.setSSLParameters(sslParams);
            return socket;
        } catch (IOException | GeneralSecurityException e) {
            throw new RuntimeException("Error creating SSL/TLS connection", e);
        }
    }

    /**
     * Creates a secure SSL/TLS context using the configured truststore and keystore.
     * @return An SSLContext object
     */
    private SSLContext createSslContext() {
        try {
            TrustManagerFactory tmf = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
            KeyStore ts = loadKeyStore(SSL_TRUSTSTORE_FILENAME, SSL_TRUSTSTORE_PASSWORD);
            tmf.init(ts);

            KeyManagerFactory kmf = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());
            KeyStore ks = loadKeyStore(SSL_KEYSTORE_FILENAME, SSL_KEYSTORE_PASSWORD);
            kmf.init(ks, SSL_KEYSTORE_PASSWORD.toCharArray());

            SSLContext sslContext = SSLContext.getInstance(PROTOCOL);
            sslContext.init(kmf.getKeyManagers(), tmf.getTrustManagers(), null);

            return sslContext;
        } catch (IOException | GeneralSecurityException e) {
            throw new RuntimeException("Error creating SSL/TLS context", e);
        }
    }

    /**
     * Loads a keystore from the specified file.
     * @param filename The filename of the keystore to load
     * @param password The password for the keystore
     * @return A KeyStore object
     */
    private KeyStore loadKeyStore(String filename, String password) {
        try (FileInputStream fis = new FileInputStream(filename)) {
            KeyStore ks = KeyStore.getInstance("JKS");
            ks.load(fis, password.toCharArray());
            return ks;
        } catch (IOException | GeneralSecurityException e) {
            throw new RuntimeException("Error loading keystore", e);
        }
    }

    /**
     * Sends a request to a remote server and returns the response as a String.
     * @param host The hostname or IP address of the server
     * @param port The port number of the server
     * @param url The URL of the resource to request
     * @return The response from the server as a String
     */
    public String get(String host, int port, String url) {
        try (Socket socket = connect(host, port)) {
            OutputStream outputStream = socket.getOutputStream();
            InputStream inputStream = socket.getInputStream();

            URL requestUrl = new URL("http", host, port, url);
            HttpURLConnection httpConnection = (HttpURLConnection) requestUrl.openConnection();
            httpConnection.setDoOutput(true);
            httpConnection.setInstanceFollowRedirects(false);
            httpConnection.setRequestMethod("GET");
            if (ENABLE_AUTHENTICATION) {
                String authHeaderValue = "Bearer " + getAuthToken();
                httpConnection.addRequestProperty(AUTHORIZATION_HEADER, authHeaderValue);
            }
            httpConnection.connect();

            int statusCode = httpConnection.getResponseCode();
            if (statusCode == HttpURLConnection.HTTP_OK) {
                return readInputStreamAsString(inputStream);
            } else {
                throw new RuntimeException("Error reading response from server, status code: " + statusCode);
            }
        } catch (IOException e) {
            throw new RuntimeException("Error connecting to server", e);
        }
    }

    /**
     * Sends a request to a remote server and returns the response as a String.
     * @param host The hostname or IP address of the server
     * @param port The port number of the server
     * @param url The URL of the resource to request
     * @return The response from the server as a String
     */
    public String post(String host, int port, String url) {
        try (Socket socket = connect(host, port)) {
            OutputStream outputStream = socket.getOutputStream();
            InputStream inputStream = socket.getInputStream();

            URL requestUrl = new URL("http", host, port, url);
            HttpURLConnection httpConnection = (HttpURLConnection) requestUrl.openConnection();
            httpConnection.setDoOutput(true);
            httpConnection.setInstanceFollowRedirects(false);
            httpConnection.setRequestMethod("POST");
            if (ENABLE_AUTHENTICATION) {
                String authHeaderValue = "Bearer " + getAuthToken();
                httpConnection.addRequestProperty(AUTHORIZATION_HEADER, authHeaderValue);
            }
            httpConnection.connect();

            int statusCode = httpConnection.getResponseCode();
            if (statusCode == HttpURLConnection.HTTP_OK) {
                return readInputStreamAsString(inputStream);
            } else {
                throw new RuntimeException("Error reading response from server, status code: " + statusCode);
            }
        } catch (IOException e) {
            throw new RuntimeException("Error connecting to server", e);
        }
    }

    /**
     * Reads an InputStream as a String.
     * @param inputStream The InputStream to read from
     * @return The contents of the InputStream as a String
     */
    private String readInputStreamAsString(InputStream inputStream) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream))) {
            StringBuilder stringBuilder = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                stringBuilder.append(line);
            }
            return stringBuilder.toString();
        } catch (IOException e) {
            throw new RuntimeException("Error reading from InputStream", e);
        }
    }

    /**
     * Gets an authentication token for the user.
     * @return The authentication token as a String
     */
    private String getAuthToken() {
        return "token";
    }
}
