<?php

namespace App\Authentication;

use Symfony\Component\HttpFoundation\Request;
use Symfony\Component\HttpFoundation\Response;
use Symfony\Component\Security\Core\Authentication\Token\UsernamePasswordToken;
use Symfony\Component\Security\Http\Authenticator\AbstractAuthenticator;
use Symfony\Component\Security\Http\Authenticator\Passport\Badge\UserBadge;
use Symfony\Component\Security\Http\Authenticator\Passport\Passport;
use Symfony\Component\Security\Http\Authenticator\Passport\SelfValidatingPassport;
use Symfony\Component\Security\Core\Exception\AuthenticationException;
use Symfony\Component\Security\Core\User\UserInterface;
use League\OAuth2\Client\Provider\GenericProvider;
use Psr\Http\Message\ServerRequestInterface;
use Psr\Http\Message\ResponseInterface;
use Doctrine\ORM\EntityManagerInterface;
use App\Entity\Resource;

class OAuthAuthenticator extends AbstractAuthenticator
{
    private $entityManager;

    public function __construct(EntityManagerInterface $entityManager)
    {
        $this->entityManager = $entityManager;
    }

    /**
     * {@inheritdoc}
     */
    public function supports(ServerRequestInterface $request): bool
    {
        // Check if the request has an authorization header with a valid OAuth token
        return $request->hasHeader('Authorization') && $this->isValidOAuthToken($request);
    }

    /**
     * {@inheritdoc}
     */
    public function authenticate(ServerRequestInterface $request): PassportInterface
    {
        // Extract the OAuth token from the authorization header
        $token = $this->extractOAuthToken($request);

        // Create a new passport with the OAuth token and user ID badge
        return (new SelfValidatingPassport())
            ->setUserBadges([new UserBadge($token, 'oauth_access_token')])
            ->setAttribute('auth_credentials', $token);
    }

    /**
     * {@inheritdoc}
     */
    public function onAuthenticationSuccess(Request $request, TokenInterface $token, string $providerKey): ?ResponseInterface
    {
        // Load the user entity from the database using the OAuth token
        $user = $this->entityManager->getRepository(User::class)->findOneBy(['oauth_access_token' => $token]);

        // Create a new Symfony security token with the user entity and add it to the request
        return (new UsernamePasswordToken($user, null, 'main', $user->getRoles()))->generateResponse();
    }

    /**
     * {@inheritdoc}
     */
    public function onAuthenticationFailure(Request $request, AuthenticationException $exception): ?ResponseInterface
    {
        // If the authentication fails, return a 401 response with an error message
        return new Response('OAuth authentication failed', 401);
    }

    /**
     * Extracts the OAuth token from the authorization header.
     *
     * @param ServerRequestInterface $request The incoming request
     *
     * @return string|null The OAuth token or null if it's not found
     */
    private function extractOAuthToken(ServerRequestInterface $request)
    {
        // Get the authorization header from the request
        $header = $request->getHeader('Authorization');

        // Check if the header is valid and contains an OAuth token
        if (!$header || !preg_match('/^Bearer\s+(.*)$/', $header, $matches)) {
            return null;
        }

        // Return the OAuth token
        return $matches[1];
    }

    /**
     * Checks if an OAuth token is valid.
     *
     * @param ServerRequestInterface $request The incoming request
     *
     * @return bool True if the OAuth token is valid, false otherwise
     */
    private function isValidOAuthToken(ServerRequestInterface $request)
    {
        // Get the authorization header from the request
        $header = $request->getHeader('Authorization');

        // Check if the header is valid and contains an OAuth token
        return preg_match('/^Bearer\s+(.*)$/', $header, $matches) && $this->entityManager->getRepository(User::class)->findOneBy(['oauth_access_token' => $matches[1]]);
    }
}
