```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>

// Structure to represent a node in the FSA
typedef struct {
    int state;
    char* class;
} Node;

// Function to recursively traverse the FSA and return a list of states that match the selector
void *match_selector(Node *fsa, int num_states, char *selector) {
    // Initialize the list of matched states
    List<int>* matched = new List<int>();

    // Iterate over the states in the FSA
    for (int i = 0; i < num_states; i++) {
        Node* node = &fsa[i];

        // Check if the current state matches the selector
        if (node->class == NULL || strcmp(selector, node->class) == 0) {
            matched->append(node->state);
        }
    }

    // Return the list of matched states
    return matched;
}

int main() {
    // Create a sample FSA with three states and one transition
    Node* fsa = new Node[3];
    fsa[0].state = 1;
    fsa[0].class = "foo";
    fsa[1].state = 2;
    fsa[1].class = "bar";
    fsa[2].state = 3;
    fsa[2].class = "baz";

    // Match the selector "foo"
    List<int>* matched = match_selector(fsa, 3, "foo");
    printf("Matched states: %d\n", matched->size());
    matched->print();

    // Match the selector "bar"
    matched = match_selector(fsa, 3, "bar");
    printf("Matched states: %d\n", matched->size());
    matched->print();

    // Clean up
    delete[] fsa;
    delete[] matched;

    return 0;
}
```
