// RandomValueGenerator.js
class RandomValueGenerator {
  constructor() {
    this.random = Math.random;
  }

  generateRandomFloat(min, max) {
    return this.random() * (max - min) + min;
  }

  generateRandomFloatNormal(mean, standardDeviation) {
    const u1 = this.random();
    const u2 = this.random();
    const randStdNormal = Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
    return mean + standardDeviation * randStdNormal;
  }

  generateRandomFloatLogarithmic(base, min, max) {
    const random = this.random();
    const logMin = Math.log(min) / Math.log(base);
    const logMax = Math.log(max) / Math.log(base);
    return Math.pow(base, (random * (logMax - logMin)) + logMin);
  }
}

// FindElementsBySelector.js
async function findElementsBySelector(selector, asyncCallback) {
  const elements = await document.querySelectorAll(selector);
  if (!elements || elements.length === 0) {
    return;
  }
  const results = [];
  for (let i = 0; i < elements.length; i++) {
    const element = elements[i];
    asyncCallback(element, () => {
      results.push(element);
    });
  }
  return results;
}

// Logging.js
class Logger {
  constructor() {
    this.logs = [];
  }

  log(message) {
    this.logs.push(message);
  }

  getLogs() {
    return this.logs;
  }
}

// DOMTraversal.js
async function traverseDOM(rootNode, asyncCallback) {
  const nodes = await findElementsBySelector(rootNode, asyncCallback);
  for (let i = 0; i < nodes.length; i++) {
    const node = nodes[i];
    if (node.children && node.children.length > 0) {
      await traverseDOM(node, asyncCallback);
    } else {
      asyncCallback(node, () => {});
    }
  }
}

// main.js
const rootNode = document.body;
const randomValueGenerator = new RandomValueGenerator();
const logger = new Logger();

async function main() {
  const elements = await traverseDOM(rootNode, async (node) => {
    if (node.id === 'random-float') {
      node.value = randomValueGenerator.generateRandomFloat(10, 20);
    } else if (node.id === 'random-float-normal') {
      node.value = randomValueGenerator.generateRandomFloatNormal(10, 5);
    } else if (node.id === 'random-float-logarithmic') {
      node.value = randomValueGenerator.generateRandomFloatLogarithmic(2, 10, 20);
    }
  });
}

main();
