    # Handle HTTP requests using a simple request-response pattern
    global db_conn
    global cache

    if method == "GET":
        return handle_get_request(path, headers)
    elif method == "POST":
        return handle_post_request(path, headers, body)
    elif method == "PUT":
        return handle_put_request(path, headers, body)
    elif method == "DELETE":
        return handle_delete_request(path, headers)
    else:
        return {
            "statusCode": 405,
            "headers": {},
            "body": json.dumps({"error": "Method not allowed"})
        }


def handle_get_request(path, headers):
    # Handle GET requests for retrieving character attack configurations
    global cache
    global db_conn

    if path == "/character-attacks":
        # Return a list of all character attacks
        return {
            "statusCode": 200,
            "headers": {},
            "body": json.dumps(cache["characterAttacks"])
        }
    else:
        # Return a single character attack configuration
        attack_id = path[1:]
        if attack_id in cache["characterAttacks"]:
            return {
                "statusCode": 200,
                "headers": {},
                "body": json.dumps(cache["characterAttacks"][attack_id])
            }
        else:
            # Return a 404 Not Found error if the attack ID is not found in the cache or database
            return {
                "statusCode": 404,
                "headers": {},
                "body": json.dumps({"error": f"Character attack with ID '{attack_id}' does not exist."})
            }


