using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

namespace SecureUserAuthentication
{
    public class UserAuthenticator
    {
        private const int MAX_CONCURRENCY = 100; // maximum number of concurrent hash calculations
        private const int MIN_HASH_LENGTH = 64; // minimum length of the generated hashes
        private const int MAX_HASH_LENGTH = 256; // maximum length of the generated hashes

        private readonly Dictionary<string, Func<string, byte[]>> _hashAlgorithms = new Dictionary<string, Func<string, byte[]>>()
        {
            { "SHA-256", (input) => SHA256.Create().ComputeHash(Encoding.UTF8.GetBytes(input)) },
            { "bcrypt", (input) => new Bcrypt().ComputeHash(input) },
            { "Argon2", (input) => new Argon2().ComputeHash(input) }
        };

        private readonly List<string> _hashAlgorithmsOrder = new List<string>()
        {
            "SHA-256",
            "bcrypt",
            "Argon2"
        };

        private readonly object _cacheLock = new object(); // locks the cache to prevent concurrent access
        private readonly Dictionary<string, byte[]> _hashCache = new Dictionary<string, byte[]>(); // stores frequently used hashes for performance

        public async Task<byte[]> HashAsync(string input)
        {
            var hashAlgorithmName = GetHashAlgorithm();
            if (_hashCache.TryGetValue(input, out var cachedHash))
            {
                return cachedHash;
            }

            lock (_cacheLock) // locks the cache to prevent concurrent access
            {
                if (!_hashCache.ContainsKey(input))
                {
                    _hashCache[input] = await ComputeHashAsync(hashAlgorithmName, input);
                }
            }

            return _hashCache[input];
        }

        private async Task<byte[]> ComputeHashAsync(string hashAlgorithmName, string input)
        {
            var hashAlgorithm = GetHashAlgorithm(hashAlgorithmName);
            return await Task.Run(() => hashAlgorithm.ComputeHash(Encoding.UTF8.GetBytes(input)));
        }

        private Func<string, byte[]> GetHashAlgorithm(string hashAlgorithmName = null)
        {
            if (hashAlgorithmName == null)
            {
                return _hashAlgorithms[_hashAlgorithmsOrder[0]]; // returns the first algorithm by default
            }

            if (_hashAlgorithms.ContainsKey(hashAlgorithmName))
            {
                return _hashAlgorithms[hashAlgorithmName];
            }

            throw new ArgumentException($"Invalid hash algorithm: {hashAlgorithmName}");
        }
    }
}
