import logging
from logging.handlers import RotatingFileHandler
from os import makedirs, getcwd
from pathlib import Path

def initialize_logging(log_file_path: str, max_bytes: int = 1024 * 1024 * 10, backup_count: int = 5):
    """
    Initialize logging for a distributed web application.
    Handles concurrent access, retrying directory creation for transient errors, and rotating log files based on size or time.
    Dynamically configures logging levels and formats using environment variables and a centralized configuration service.
    Efficiently distributes log rotation and cleanup tasks across all instances to maintain disk space and prevent data loss.
    Integrates with an external logging aggregation service to send logs in real-time, manage log file permissions and ownership, and provide a user-friendly interface for administrators to monitor and manage log settings.
    """
    # create the log directory if it doesn't exist
    try:
        makedirs(Path(getcwd()).joinpath('logs'))
    except FileExistsError:
        pass

    # initialize logging
    file_handler = RotatingFileHandler(log_file_path, maxBytes=max_bytes, backupCount=backup_count)
    formatter = logging.Formatter("%(asctime)s - %(name)s - %(levelname)s - %(message)s")
    file_handler.setFormatter(formatter)
    logger = logging.getLogger()
    logger.addHandler(file_handler)
    logger.setLevel(logging.INFO)

    # configure logging levels and formats using environment variables and a centralized configuration service
    # ...

    return logger
