    private static final String IN_MEMORY = "in-memory";
    private static final String REDIS = "redis";
    private static final String POSTGRESQL = "postgresql";

    // Map of backend storage options to their corresponding cache instances
    private Map<String, CacheInstance> backends;

    public DistributedCacheSystem() {
        backends = new HashMap<>();
    }

    /**
     * Initialize the cache system with a list of backend storage options and their parameters.
     */
    public void init(List<String> backendOptions, List<Map<String, Object>> backendParameters) {
        for (int i = 0; i < backendOptions.size(); i++) {
            String backendOption = backendOptions.get(i);
            Map<String, Object> parameters = backendParameters.get(i);

            if (backendOption.equals(IN_MEMORY)) {
                backends.put(IN_MEMORY, new InMemoryCacheInstance());
            } else if (backendOption.equals(REDIS)) {
                RedisCacheInstance redisCache = new RedisCacheInstance();
                redisCache.init(parameters);
                backends.put(REDIS, redisCache);
            } else if (backendOption.equals(POSTGRESQL)) {
                PostgreSQLCacheInstance postgreSQLCache = new PostgreSQLCacheInstance();
                postgreSQLCache.init(parameters);
                backends.put(POSTGRESQL, postgreSQLCache);
            }
        }
    }

    /**
     * Get a cache instance based on the specified backend storage option and key.
     */
    public CacheInstance getCacheInstance(String backendOption, String key) {
        if (backendOption == null || !backends.containsKey(backendOption)) {
            return new InMemoryCacheInstance();
        } else {
            return backends.get(backendOption).getCacheInstance(key);
        }
    }

    /**
     * Set a cache instance based on the specified backend storage option and key.
     */
    public void setCacheInstance(String backendOption, String key, CacheInstance cacheInstance) {
        if (backendOption == null || !backends.containsKey(backendOption)) {
            return;
        } else {
            backends.get(backendOption).setCacheInstance(key, cacheInstance);
        }
    }

    /**
     * Remove a cache instance based on the specified backend storage option and key.
     */
    public void removeCacheInstance(String backendOption, String key) {
        if (backendOption == null || !backends.containsKey(backendOption)) {
            return;
        } else {
            backends.get(backendOption).removeCacheInstance(key);
        }
    }

