```
#include <iostream>
#include <ctime>
#include <cstdlib>
#include <string>
#include <vector>

using namespace std;

// Function to randomly select an attack from a list of available attacks
Attack selectAttack(const vector<Attack>& availableAttacks, const int cooldownPeriod) {
    // Generate a random number between 0 and the size of the available attacks list
    int randomIndex = rand() % availableAttacks.size();

    // Get the attack at the randomly selected index
    Attack selectedAttack = availableAttacks[randomIndex];

    // Check if the attack is on cooldown
    time_t currentTime = time(0);
    if (currentTime - selectedAttack.cooldownStart < cooldownPeriod) {
        // If it is, try again after a random delay between 0 and the cooldown period
        int randomDelay = rand() % cooldownPeriod;
        this_thread::sleep_for(chrono::seconds(randomDelay));
        return selectAttack(availableAttacks, cooldownPeriod);
    } else {
        // If it isn't, update the cooldown start time and return the attack
        selectedAttack.cooldownStart = currentTime;
        return selectedAttack;
    }
}
