using System;
using System.Data;
using System.Data.SqlClient;

namespace MyApp {
    public class DatabaseUtilities {
        private static readonly string ConnectionString = "Server=myserver;Database=mydatabase;Trusted_Connection=True";

        // Method to execute a query against the database and return a DataTableReader object containing the results
        public static DataTableReader ExecuteQueryAndReturnReader(string query) {
            using (SqlConnection connection = new SqlConnection(ConnectionString)) {
                try {
                    connection.Open();
                    using (SqlCommand command = new SqlCommand(query, connection)) {
                        return command.ExecuteReader();
                    }
                } catch (Exception e) {
                    Console.WriteLine($"Error executing query: {e.Message}");
                    return null;
                } finally {
                    connection.Close();
                }
            }
        }
    }
}
