// Modular Node.js application for processing online transactions securely
const express = require('express');
const app = express();
const path = require('path');
const bodyParser = require('body-parser');
const mongoose = require('mongoose');
const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);
const paypal = require('paypal-rest-sdk');

// Set up MongoDB database connection
mongoose.connect('mongodb://localhost/online_transactions', { useNewUrlParser: true });
const db = mongoose.connection;
db.on('error', console.error.bind(console, 'connection error:'));
db.once('open', () => {
  console.log('Connected to MongoDB');
});

// Set up Express routing and body parsing
app.use(bodyParser.json());
app.use(bodyParser.urlencoded({ extended: true }));
app.get('/api/transactions', (req, res) => {
  // Query transactions from database
  const query = {};
  if (req.query.account_id) {
    query['account_id'] = req.query.account_id;
  }
  db.collection('transactions').find(query).toArray((err, transactions) => {
    if (err) {
      res.status(500).send(err);
    } else {
      res.json(transactions);
    }
  });
});
app.post('/api/transactions', (req, res) => {
  // Create transaction in database
  const transaction = req.body;
  db.collection('transactions').insertOne(transaction, (err, result) => {
    if (err) {
      res.status(500).send(err);
    } else {
      res.json({ message: 'Transaction created successfully' });
    }
  });
});
app.put('/api/transactions/:id', (req, res) => {
  // Update transaction in database
  const id = req.params.id;
  const update = req.body;
  db.collection('transactions').updateOne({ _id: id }, update, (err, result) => {
    if (err) {
      res.status(500).send(err);
    } else {
      res.json({ message: 'Transaction updated successfully' });
    }
  });
});
app.delete('/api/transactions/:id', (req, res) => {
  // Delete transaction from database
  const id = req.params.id;
  db.collection('transactions').deleteOne({ _id: id }, (err, result) => {
    if (err) {
      res.status(500).send(err);
    } else {
      res.json({ message: 'Transaction deleted successfully' });
    }
  });
});

// Set up payment gateway integrations
const paymentGateways = {
  stripe: stripe,
  paypal: paypal
};
app.get('/api/payment_gateways', (req, res) => {
  // Return list of available payment gateways
  const gateways = [];
  for (let gateway in paymentGateways) {
    gateways.push({ name: gateway, enabled: true });
  }
  res.json(gateways);
});
app.post('/api/payment_gateways', (req, res) => {
  // Set up a new payment gateway
  const gateway = req.body.name;
  if (!paymentGateways[gateway]) {
    res.status(404).json({ message: 'Payment gateway not found' });
  } else {
    res.json({ message: `Payment gateway ${gateway} set up successfully` });
  }
});
app.delete('/api/payment_gateways/:name', (req, res) => {
  // Delete a payment gateway from the list of enabled gateways
  const name = req.params.name;
  if (!paymentGateways[name]) {
    res.status(404).json({ message: 'Payment gateway not found' });
  } else {
    delete paymentGateways[name];
    res.json({ message: `Payment gateway ${name} deleted successfully` });
  }
});

// Set up RESTful API for initiating and processing transactions
app.get('/api/transactions/:id', (req, res) => {
  // Return transaction details by ID
  const id = req.params.id;
  db.collection('transactions').findOne({ _id: id }, (err, transaction) => {
    if (err) {
      res.status(500).send(err);
    } else {
      res.json(transaction);
    }
  });
});
app.post('/api/transactions', (req, res) => {
  // Initiate a new transaction
  const transaction = req.body;
  if (!paymentGateways[transaction.gateway]) {
    res.status(404).json({ message: 'Payment gateway not found' });
  } else {
    paymentGateways[transaction.gateway].createOrder(transaction, (err, result) => {
      if (err) {
        res.status(500).send(err);
      } else {
        db.collection('transactions').insertOne(result, (err, transaction) => {
          if (err) {
            res.status(500).send(err);
          } else {
            res.json({ message: 'Transaction created successfully' });
          }
        });
      }
    });
  }
});
app.put('/api/transactions/:id', (req, res) => {
  // Update transaction details by ID
  const id = req.params.id;
  const update = req.body;
  db.collection('transactions').updateOne({ _id: id }, update, (err, result) => {
    if (err) {
      res.status(500).send(err);
    } else {
      res.json({ message: 'Transaction updated successfully' });
    }
  });
});
app.delete('/api/transactions/:id', (req, res) => {
  // Delete transaction by ID
  const id = req.params.id;
  db.collection('transactions').deleteOne({ _id: id }, (err, result) => {
    if (err) {
      res.status(500).send(err);
    } else {
      res.json({ message: 'Transaction deleted successfully' });
    }
  });
});

// Set up error handling and logging
app.use((req, res, next) => {
  const error = new Error('Not Found');
  error.status = 404;
  next(error);
});
app.use((err, req, res, next) => {
  console.error(err.message);
  res.status(500).send({ message: 'Internal Server Error' });
});

// Start server
const port = process.env.PORT || 3000;
app.listen(port, () => {
  console.log(`Server started on port ${port}`);
});
