#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>
#include "json.hpp"
#include "oauth2.hpp"

using namespace std;
using json = nlohmann::json;

// Global variables for the token cache and configuration servers
static unordered_map<string, string> token_cache; // map of token to expiration time
static vector<string> config_servers = {"https://config-server1.com", "https://config-server2.com"}; // list of configuration servers
static mutex cache_lock; // lock for accessing the token cache
static condition_variable cv; // condition variable to signal changes in the token cache

// Function to validate an OAuth2 access token against multiple remote API endpoints
bool validate_token(const string& token, const vector<string>& api_endpoints) {
    bool valid = false;

    // Check if the token is already cached and not expired
    {
        lock_guard<mutex> lock(cache_lock);
        auto it = token_cache.find(token);
        if (it != token_cache.end() && chrono::duration_cast<chrono::seconds>(chrono::steady_clock::now() - it->second).count() < 0) {
            valid = true;
            return valid;
        }
    }

    // Retrieve the latest validation rules from the configuration servers
    for (int i = 0; i < config_servers.size(); ++i) {
        string url = config_servers[i] + "/validate";
        auto result = oauth2::fetch(url, token);
        if (!result.success || result.body["status"] != "ok") {
            // Failed to retrieve validation rules from server, retry with exponential backoff
            this_thread::sleep_for(chrono::seconds(1 << (i + 1)));
            continue;
        }

        valid = validate_token_internal(result.body["data"], token);
        if (valid) {
            // Cache the token and expiration time for future validation
            lock_guard<mutex> lock(cache_lock);
            token_cache[token] = chrono::steady_clock::now() + chrono::seconds(result.body["data"]["expires_in"]);
        }
        break;
    }

    return valid;
}

// Internal function to validate an OAuth2 access token against a single remote API endpoint
bool validate_token_internal(const json& data, const string& token) {
    // Check for the presence and correctness of specific fields
    if (data["token_type"] != "Bearer" || data["expires_in"] <= 0 || !data["access_token"].is_string() || (!data["refresh_token"].is_string() && data["refresh_token"].is_string())) {
        return false;
    }

    // Check for token format and other security considerations
    if (data["access_token"] != token) {
        return false;
    }

    return true;
}

// Main function to call validate_token with multiple API endpoints
bool validate_tokens(const vector<string>& tokens, const vector<string>& api_endpoints) {
    bool valid = false;

    for (auto token : tokens) {
        if (validate_token(token, api_endpoints)) {
            valid = true;
            break;
        }
    }

    return valid;
}
