using System;
using System.Collections.Concurrent;
using System.Threading;
using System.Threading.Tasks;

namespace DynamicValueGenerator
{
    /// <summary>
    /// A dynamic value generator that provides flexible and efficient mechanisms for generating random values from external data sources while adhering to specific operational constraints.
    /// </summary>
    public class DynamicValueGenerator
    {
        private readonly ConcurrentDictionary<string, RangeConfig> _rangeConfigs;
        private readonly SeedManager _seedManager;
        private readonly Random _random;

        /// <summary>
        /// Initializes a new instance of the <see cref="DynamicValueGenerator"/> class.
        /// </summary>
        public DynamicValueGenerator()
        {
            _rangeConfigs = new ConcurrentDictionary<string, RangeConfig>();
            _seedManager = new SeedManager();
            _random = new Random();
        }

        /// <summary>
        /// Generates a random value within the specified range.
        /// </summary>
        /// <param name="rangeType">The type of range to generate (inclusive, exclusive, or half-open).</param>
        /// <param name="min">The minimum value in the range.</param>
        /// <param name="max">The maximum value in the range.</param>
        /// <returns>A random value within the specified range.</returns>
        public int GenerateValue(RangeType rangeType, int min, int max)
        {
            if (min > max)
                throw new ArgumentException("Invalid range", nameof(min));

            var rangeConfig = GetRangeConfig(rangeType, min, max);
            return _random.Next(rangeConfig.Min, rangeConfig.Max + 1);
        }

        /// <summary>
        /// Generates a random value within the specified range using the specified seed.
        /// </summary>
        /// <param name="seed">The seed to use for generating the random value.</param>
        /// <param name="rangeType">The type of range to generate (inclusive, exclusive, or half-open).</param>
        /// <param name="min">The minimum value in the range.</param>
        /// <param name="max">The maximum value in the range.</param>
        /// <returns>A random value within the specified range using the specified seed.</returns>
        public int GenerateValue(int seed, RangeType rangeType, int min, int max)
        {
            if (min > max)
                throw new ArgumentException("Invalid range", nameof(min));

            var rangeConfig = GetRangeConfig(rangeType, min, max);
            return _random.Next(seed, rangeConfig.Min, rangeConfig.Max + 1);
        }

        /// <summary>
        /// Gets the current seed value for the random value generator.
        /// </summary>
        public int Seed => _random.Seed;

        /// <summary>
        /// Sets the seed value for the random value generator.
        /// </summary>
        /// <param name="seed">The new seed value.</param>
        public void SetSeed(int seed)
        {
            _random.Seed = seed;
        }

        private RangeConfig GetRangeConfig(RangeType rangeType, int min, int max)
        {
            if (min > max)
                throw new ArgumentException("Invalid range", nameof(min));

            var rangeKey = $"{rangeType}-{min}-{max}";
            if (!_rangeConfigs.TryGetValue(rangeKey, out RangeConfig config))
            {
                config = new RangeConfig()
                {
                    Type = rangeType,
                    Min = min,
                    Max = max,
                    Seed = _seedManager.NextSeed()
                };
                _rangeConfigs.TryAdd(rangeKey, config);
            }

            return config;
        }
    }

    /// <summary>
    /// Enumeration of range types (inclusive, exclusive, or half-open).
    /// </summary>
    public enum RangeType
    {
        Inclusive = 0,
        Exclusive = 1,
        HalfOpen = 2
    }

    /// <summary>
    /// A class for managing seeds used by the random value generator.
    /// </summary>
    public class SeedManager
    {
        private int _seed;
        private readonly object _syncObj = new object();

        /// <summary>
        /// Gets the next seed value in the sequence.
        /// </summary>
        public int NextSeed()
        {
            lock (_syncObj)
            {
                _seed++;
                return _seed;
            }
        }
    }

    /// <summary>
    /// A class for encapsulating range definitions and associated properties.
    /// </summary>
    public class RangeConfig
    {
        /// <summary>
        /// The type of range (inclusive, exclusive, or half-open).
        /// </summary>
        public RangeType Type { get; set; }

        /// <summary>
        /// The minimum value in the range.
        /// </summary>
        public int Min { get; set; }

        /// <summary>
        /// The maximum value in the range.
        /// </summary>
        public int Max { get; set; }

        /// <summary>
        /// The seed value for generating random values within the range.
        /// </summary>
        public int Seed { get; set; }
    }
}
