import uuid
from datetime import datetime
from flask import Flask, request, jsonify
from flask_cors import CORS
from flask_limiter import Limiter
from flask_limiter.util import get_remote_address
from sqlalchemy import create_engine, MetaData, Table
from sqlalchemy.orm import sessionmaker
from sqlalchemy.exc import IntegrityError
from sqlalchemy.dialects.sqlite import SQLiteDialect
import hashlib
import hmac

app = Flask(__name__)
CORS(app)
limiter = Limiter(app, key_func=get_remote_address)

engine = create_engine('sqlite:///users.db')
metadata = MetaData()
users_table = Table('users', metadata,
    Column('id', uuid.UUID, primary_key=True),
    Column('name', String(255)),
    Column('email', String(255)),
    Column('password', String(1024)),
    Column('created_at', DateTime, default=datetime.utcnow()),
    Column('updated_at', DateTime)
)
metadata.create_all(engine)
Session = sessionmaker(bind=engine)
session = Session()

@app.route('/users/<id>', methods=['GET'])
@limiter.limit("10 per minute")
def get_user(id):
    user = session.query(User).filter_by(id=uuid.UUID(id)).first()
    if user is None:
        return jsonify({'error': 'User not found'}), 404
    return jsonify(user)

@app.route('/users', methods=['POST'])
@limiter.limit("10 per minute")
def create_user():
    name = request.json.get('name')
    email = request.json.get('email')
    password = request.json.get('password')
    if not all([name, email, password]):
        return jsonify({'error': 'Missing fields'}), 400
    user = User(name=name, email=email, password=password)
    try:
        session.add(user)
        session.commit()
    except IntegrityError as e:
        return jsonify({'error': 'User already exists'}), 409
    return jsonify(user), 201

@app.route('/users/<id>', methods=['PATCH'])
@limiter.limit("10 per minute")
def update_user(id):
    user = session.query(User).filter_by(id=uuid.UUID(id)).first()
    if user is None:
        return jsonify({'error': 'User not found'}), 404
    etag = request.headers.get('etag')
    if etag is not None:
        if user.etag != etag:
            return jsonify({'error': 'Precondition failed'}), 412
    name = request.json.get('name', user.name)
    email = request.json.get('email', user.email)
    password = request.json.get('password', user.password)
    try:
        user.name = name
        user.email = email
        user.password = password
        session.commit()
    except IntegrityError as e:
        return jsonify({'error': 'User already exists'}), 409
    return jsonify(user)

@app.route('/users/<id>', methods=['DELETE'])
@limiter.limit("10 per minute")
def delete_user(id):
    user = session.query(User).filter_by(id=uuid.UUID(id)).first()
    if user is None:
        return jsonify({'error': 'User not found'}), 404
    try:
        session.delete(user)
        session.commit()
    except IntegrityError as e:
        return jsonify({'error': 'User already exists'}), 409
    return jsonify({'message': f'Deleted user with id {id}'})

@app.route('/users/deactivate', methods=['POST'])
@limiter.limit("10 per minute")
def deactivate_user():
    id = request.json.get('id')
    if not all([id]):
        return jsonify({'error': 'Missing fields'}), 400
    user = session.query(User).filter_by(id=uuid.UUID(id)).first()
    if user is None:
        return jsonify({'error': 'User not found'}), 404
    etag = request.headers.get('etag')
    if etag is not None:
        if user.etag != etag:
            return jsonify({'error': 'Precondition failed'}), 412
    try:
        user.is_active = False
        session.commit()
    except IntegrityError as e:
        return jsonify({'error': 'User already exists'}), 409
    return jsonify(user)
