using System;
using System.IO;
using System.Xml;
using System.Xml.XPath;

namespace XmlParser
{
    public class Parser
    {
        private const int MaxDocumentSize = 1024 * 1024; // 1 MB

        public static void Parse(string xml, string xpath)
        {
            if (!ValidateXml(xml))
                throw new ArgumentException("Invalid XML document");

            var doc = new XmlDocument();
            doc.LoadXml(xml);

            var navigator = doc.CreateNavigator();
            var nodes = navigator.Select(xpath);

            if (nodes.Count == 0)
                throw new Exception("No element found with the given XPath expression");

            if (nodes.Count > 1)
                throw new Exception("Multiple elements found with the given XPath expression");

            var node = nodes[0];
            Console.WriteLine($"Element {node.Name}: {node.Value}");
        }

        private static bool ValidateXml(string xml)
        {
            if (xml == null || xml.Length > MaxDocumentSize)
                return false;

            try
            {
                var doc = new XmlDocument();
                doc.LoadXml(xml);
                return true;
            }
            catch (Exception)
            {
                return false;
            }
        }
    }
}
