struct TestConfig {
    module: String,
    function: String,
}

async fn run_module_tests_async(config: &TestConfig) -> Result<(), Box<dyn std::error::Error>> {
    // Dynamically import the Python module using reflection
    let module = Module::from_file(&config.module)?;

    // Execute each test function from the module
    for func in module.get(config.function)? {
        func()?;
    }

    // Handle any exceptions that occur during the test execution
    Ok(())
}

