using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using System.Web;
using Newtonsoft.Json;

namespace WebApplication1
{
    public class HttpModule
    {
        public async Task<HttpResponse> UpdateHtmlContent(HttpRequest request)
        {
            var pageSectionId = request.Query["pageSectionId"];
            var elementId = request.Query["elementId"];
            var htmlContent = request.Body;

            if (string.IsNullOrEmpty(pageSectionId) || string.IsNullOrEmpty(elementId))
            {
                return HttpResponse.BadRequest();
            }

            // Validate input
            if (!Guid.TryParse(pageSectionId, out Guid pageSectionIdGuid))
            {
                return HttpResponse.BadRequest($"Invalid page section ID: {pageSectionId}");
            }

            if (!Guid.TryParse(elementId, out Guid elementIdGuid))
            {
                return HttpResponse.BadRequest($"Invalid element ID: {elementId}");
            }

            // Update HTML content in distributed cache system
            try
            {
                await DistributedCache.UpdateHtmlContentAsync(pageSectionIdGuid, elementIdGuid, htmlContent);
            }
            catch (Exception ex)
            {
                return HttpResponse.InternalServerError($"Failed to update HTML content: {ex.Message}");
            }

            // Notify message queue for page refresh
            try
            {
                await MessageQueue.EnqueueAsync("refresh-page", $"{pageSectionIdGuid}-{elementIdGuid}");
            }
            catch (Exception ex)
            {
                return HttpResponse.InternalServerError($"Failed to enqueue message for page refresh: {ex.Message}");
            }

            return HttpResponse.Ok();
        }
    }
}
