// PHP function to generate a secure random string with a specified length using a given character set for use in URL tokens
function generateSecureRandomString($length, $characters) {
    // Validate input parameters
    if ($length < 1 || !is_int($length)) {
        throw new \InvalidArgumentException('Length must be a positive integer');
    }
    if (!is_string($characters) || strlen($characters) === 0) {
        throw new \InvalidArgumentException('Characters must be a non-empty string');
    }

    // Generate random string
    $string = '';
    for ($i = 0; $i < $length; $i++) {
        $string .= $characters[random_int(0, strlen($characters) - 1)];
    }

    return $string;
}

// PHP function to hash a password with customizable hash algorithms (e.g., bcrypt, Argon2id) and include salting for added security
function hashPassword($password, $algorithm = 'bcrypt') {
    // Validate input parameters
    if (!is_string($password)) {
        throw new \InvalidArgumentException('Password must be a string');
    }
    if ($algorithm !== 'bcrypt' && $algorithm !== 'argon2id') {
        throw new \InvalidArgumentException('Algorithm must be either "bcrypt" or "argon2id"');
    }

    // Hash password with chosen algorithm
    $options = [
        'cost' => 10,
    ];
    if ($algorithm === 'argon2id') {
        $options['memory_cost'] = 1024;
        $options['time_cost'] = 2;
        $options['threads'] = 2;
    }
    return password_hash($password, $algorithm, $options);
}

// PHP function to store and retrieve tokens and hashed passwords in a session management system
function manageTokensAndPasswords() {
    // Store token and hashed password in session
    $_SESSION['token'] = generateSecureRandomString(32, '0123456789abcdef');
    $_SESSION['hashedPassword'] = hashPassword('password', 'bcrypt');
}

