function readFile(filePath) {
    // Validate input parameter
    if (!is_string(filePath)) {
        throw new \InvalidArgumentException('File path must be a string');
    }

    const fs = require('fs');
    return fs.readFileSync(filePath, 'utf8');
}

// JavaScript function to upload a file linked from a given URL using a chosen library (e.g., Bluebird, Logger, File Uploader) and return the URL of the uploaded file
function uploadFile(url, library = 'Bluebird') {
    // Validate input parameters
    if (!is_string(url)) {
        throw new \InvalidArgumentException('URL must be a string');
    }
    if (!is_string(library) || !['Bluebird', 'Logger', 'File Uploader'].includes(library)) {
        throw new \InvalidArgumentException('Library must be either "Bluebird", "Logger", or "File Uploader"');
    }

    // Upload file using chosen library
    switch (library) {
        case 'Bluebird':
            const Bluebird = require('bluebird');
            return Bluebird.promisify(require('request-promise'))({ url })
                .then((response) => JSON.parse(response).url);
        case 'Logger':
            const Logger = require('logger');
            return Logger.uploadFile(url)
                .then((file) => file.getUrl());
        case 'File Uploader':
            const FileUploader = require('file-uploader');
            return FileUploader.upload(url)
                .then((response) => response.url);
    }
