using System.Data;
using System.Data.SqlClient;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Redis;
using Polly;

public class DynamicSQLExecutor
{
    private readonly string _connectionString;
    private readonly string _commandTemplate;
    private readonly Dictionary<string, object> _parameters;
    private readonly RedisCache _cache;
    private readonly AsyncPolicy _retryPolicy;

    public DynamicSQLExecutor(string connectionString, string commandTemplate, Dictionary<string, object> parameters, RedisCache cache)
    {
        _connectionString = connectionString;
        _commandTemplate = commandTemplate;
        _parameters = parameters;
        _cache = cache;
        _retryPolicy = Policy.Handle<Exception>()
            .RetryAsync(3, onRetry: (exception, retryCount) =>
            {
                Console.WriteLine($"Encountered an error while executing query. Retrying ({retryCount}): {exception.Message}");
            });
    }

    public async Task<DataTable> ExecuteAsync()
    {
        var connection = new SqlConnection(_connectionString);

        try
        {
            await connection.OpenAsync();

            using (var command = connection.CreateCommand())
            {
                command.CommandText = GenerateSQL(commandTemplate, _parameters);
                command.CommandType = CommandType.Text;

                foreach (var parameter in _parameters)
                {
                    var param = command.CreateParameter();
                    param.ParameterName = parameter.Key;
                    param.Value = parameter.Value;
                    command.Parameters.Add(param);
                }

                using (var reader = await command.ExecuteReaderAsync())
                {
                    var table = new DataTable();
                    table.Load(reader);
                    return table;
                }
            }
        }
        finally
        {
            connection.Close();
        }
    }

    private string GenerateSQL(string template, Dictionary<string, object> parameters)
    {
        var sql = new StringBuilder(template);
        foreach (var parameter in parameters)
        {
            sql.Replace($"@{parameter.Key}", $"'{parameter.Value}'");
        }
        return sql.ToString();
    }
}

public class RemoteServerConnectionManager
{
    private readonly IList<string> _servers;
    private readonly RedisCache _cache;
    private readonly AsyncPolicy _retryPolicy;

    public RemoteServerConnectionManager(IList<string> servers, RedisCache cache)
    {
        _servers = servers;
        _cache = cache;
        _retryPolicy = Policy.Handle<Exception>()
            .RetryAsync(3, onRetry: (exception, retryCount) =>
            {
                Console.WriteLine($"Encountered an error while connecting to server. Retrying ({retryCount}): {exception.Message}");
            });
    }

    public async Task<T> GetAsync<T>(string key)
    {
        var connection = new NioChannel(_servers, _cache);

        try
        {
            return await connection.GetAsync<T>(key);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Encountered an error while getting data from cache. Falling back to remote server: {ex.Message}");
            using (var channel = new TcpChannel(_servers))
            {
                return await channel.GetAsync<T>(key);
            }
        }
    }

    public async Task SetAsync(string key, object value)
    {
        var connection = new NioChannel(_servers, _cache);

        try
        {
            await connection.SetAsync(key, value);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Encountered an error while setting data to cache. Falling back to remote server: {ex.Message}");
            using (var channel = new TcpChannel(_servers))
            {
                await channel.SetAsync(key, value);
            }
        }
    }
}
