// JavaScript component for handling scripts
const scriptManager = {
  // Dictionary of fetched scripts
  scripts: {},

  // Function to fetch a script
  fetchScript(id) {
    if (!this.scripts[id]) {
      this.scripts[id] = {};
      fetch(`https://example.com/api/script/${id}`)
        .then((response) => response.json())
        .then((data) => {
          // Handle missing properties by providing default values
          if (!data.name) {
            data.name = "Untitled";
          }
          if (!data.description) {
            data.description = "";
          }
          this.scripts[id] = data;
        })
        .catch((error) => {
          console.log("Failed to fetch script:", error);
        });
    }
  },

  // Function to load a script asynchronously
  loadScript(id, callback) {
    this.fetchScript(id);
    const script = this.scripts[id];
    if (script) {
      callback(script);
    } else {
      setTimeout(() => {
        this.loadScript(id, callback);
      }, 1000); // Retry after one second
    }
  },

  // Function to cache fetched scripts in local storage
  cacheScripts() {
    const cachedScripts = JSON.stringify(this.scripts);
    localStorage.setItem("cachedScripts", cachedScripts);
  },

  // Function to retrieve cached scripts from local storage
  getCachedScripts() {
    const cachedScripts = localStorage.getItem("cachedScripts");
    if (cachedScripts) {
      this.scripts = JSON.parse(cachedScripts);
    }
  },

  // Function to handle error logging and reporting
  logError(error) {
    console.log(`Error: ${error}`);
    reportErrorToServer(error);
  },
};
