// Define a base class for vehicles
public abstract class Vehicle {
    private String id;
    private String make;
    private String model;
    private String year;

    // Factory functions for creating new instances of subclasses
    public static ElectricCar createElectricCar(String id, String make, String model, String year) {
        return new ElectricCar(id, make, model, year);
    }

    public static HybridCar createHybridCar(String id, String make, String model, String year) {
        return new HybridCar(id, make, model, year);
    }

    public static DieselCar createDieselCar(String id, String make, String model, String year) {
        return new DieselCar(id, make, model, year);
    }

    // Registry of factory functions
    private static Map<String, Function<Vehicle>> registry = new HashMap<>();

    // Add a factory function to the registry
    public static void addFactoryFunction(String id, Function<Vehicle> factory) {
        registry.put(id, factory);
    }

    // Get a factory function from the registry
    public static Function<Vehicle> getFactoryFunction(String id) {
        return registry.get(id);
    }

    // Update the registry with new factory functions
    public static void updateRegistry(Map<String, Function<Vehicle>> newRegistry) {
        registry = newRegistry;
    }

    // Remove a factory function from the registry
    public static void removeFactoryFunction(String id) {
        registry.remove(id);
    }

    // Create a new instance of a vehicle subclass using a factory function
    public static Vehicle createVehicle(String id, String make, String model, String year) {
        Function<Vehicle> factory = getFactoryFunction(id);
        if (factory == null) {
            throw new IllegalArgumentException("No factory function found for vehicle ID " + id);
        }
        return factory.apply(new Vehicle(id, make, model, year));
    }

    // Constructor for the base class
    public Vehicle(String id, String make, String model, String year) {
        this.id = id;
        this.make = make;
        this.model = model;
        this.year = year;
    }
}

