#[derive(Debug)]
struct Compiler {
    driver: Driver,
}

impl Compiler {
    fn new(target_info: TargetInfo) -> Self {
        let driver = Driver::new(&target_info);
        Self { driver }
    }

    fn compile<P>(&self, path: P) -> Result<(), ()>
    where
        P: AsRef<Path>,
    {
        // Initialize the external logging system here
        let _ = self.driver.early_error(ErrorOutputType::Default, | diag | {
            // Log errors into the external system here
            println!("{}", diag);
        });

        let mut compile_start = std::time::Instant::now();
        match self.driver.compile(&[path.as_ref().to_string_lossy().into_owned()]) {
            Ok(()) => {
                println!("Compilation successful!");
            }
            Err(_) => {
                println!("Compilation failed!");
            }
        };
        let compile_end = std::time::Instant::now();
        let compile_time = compile_end - compile_start;
        println!("Compile time: {:?}", compile_time);

        // Get the resident set size of the Rust compiler here
        let mut rss = 0;
        unsafe { libc::getrusage(libc::RUSAGE_SELF, &mut rss as *mut _) };
        println!("Resident set size: {}", rss);

        Ok(())
    }
}

