#include <iostream>
#include <vector>
#include <map>
#include <mutex>
#include <condition_variable>
#include <future>
#include <memory>

// Define the octree node structure
struct OctreeNode {
  // The data stored in each node
  std::vector<float> data;

  // The child nodes of this node, if any
  std::vector<std::shared_ptr<OctreeNode>> children;
};

// Define the octree structure
struct Octree {
  // The root node of the octree
  std::shared_ptr<OctreeNode> root;

  // A map of leaf nodes to their corresponding data points
  std::map<std::string, std::shared_ptr<OctreeNode>> leafNodes;

  // A mutex for synchronizing access to the octree
  std::mutex mtx;

  // A condition variable for waiting on insertions or deletions
  std::condition_variable cv;

  // A future for background processing of BVHs
  std::future<void> bvhFuture;
};

// Define a function to initialize the octree
Octree initOctree(std::string dataSource, int maxConcurrentInserts) {
  // Create an empty octree structure
  Octree octree;

  // Initialize the root node of the octree
  octree.root = std::make_shared<OctreeNode>();

  // Set the maximum number of concurrent inserts
  octree.maxConcurrentInserts = maxConcurrentInserts;

  // Initialize the leaf nodes map
  octree.leafNodes = std::map<std::string, std::shared_ptr<OctreeNode>>();

  // Set the mutex and condition variable for synchronizing access to the octree
  octree.mtx = std::mutex();
  octree.cv = std::condition_variable();

  // Set the future for background processing of BVHs
  octree.bvhFuture = std::async(std::launch::async, [&]() {
    // Run the BVH precomputation and storage in a background thread
    return;
  });

  // Return the initialized octree
  return octree;
}

// Define a function to insert data points into the octree
void insertDataPoints(Octree& octree, std::vector<float> data) {
  // Lock the mutex for synchronizing access to the octree
  std::lock_guard<std::mutex> lock(octree.mtx);

  // Check if there are any concurrent inserts or deletions in progress
  while (octree.maxConcurrentInserts > 0) {
    // Wait for the insertion or deletion to complete
    octree.cv.wait(lock);
  }

  // Increment the maximum number of concurrent inserts
  ++octree.maxConcurrentInserts;

  // Insert the data points into the leaf nodes map
  for (auto& point : data) {
    // Get the corresponding leaf node
    auto& leafNode = octree.leafNodes[std::string(point)];

    // Add the data point to the leaf node's data vector
    leafNode->data.push_back(point);
  }

  // Decrement the maximum number of concurrent inserts
  --octree.maxConcurrentInserts;

  // Notify any waiting threads that there are no more concurrent inserts or deletions in progress
  octree.cv.notify_all();
}

// Define a function to delete data points from the octree
void deleteDataPoints(Octree& octree, std::vector<std::string> ids) {
  // Lock the mutex for synchronizing access to the octree
  std::lock_guard<std::mutex> lock(octree.mtx);

  // Check if there are any concurrent inserts or deletions in progress
  while (octree.maxConcurrentInserts > 0) {
    // Wait for the insertion or deletion to complete
    octree.cv.wait(lock);
  }

  // Increment the maximum number of concurrent inserts
  ++octree.maxConcurrentInserts;

  // Delete the data points from the leaf nodes map
  for (auto& id : ids) {
    // Get the corresponding leaf node
    auto& leafNode = octree.leafNodes[id];

    // Remove the data point from the leaf node's data vector
    leafNode->data.erase(std::remove(leafNode->data.begin(), leafNode->data.end(), id), leafNode->data.end());
  }

  // Decrement the maximum number of concurrent inserts
  --octree.maxConcurrentInserts;

  // Notify any waiting threads that there are no more concurrent inserts or deletions in progress
  octree.cv.notify_all();
}

// Define a function to rebalance the octree based on configurable thresholds and perform asynchronous background processing
void rebalanceOctree(Octree& octree, int maxLeafNodes, float minLeafNodeCapacity) {
  // Lock the mutex for synchronizing access to the octree
  std::lock_guard<std::mutex> lock(octree.mtx);

  // Check if there are any concurrent inserts or deletions in progress
  while (octree.maxConcurrentInserts > 0) {
    // Wait for the insertion or deletion to complete
    octree.cv.wait(lock);
  }

  // Increment the maximum number of concurrent inserts
  ++octree.maxConcurrentInserts;

  // Rebalance the octree based on configurable thresholds
  auto& rootNode = octree.root;

  // Recursively rebalance the child nodes of the root node
  for (auto& child : rootNode->children) {
    rebalanceOctree(child, maxLeafNodes, minLeafNodeCapacity);
  }

  // Check if the leaf nodes count exceeds the maximum limit
  if (rootNode->children.size() > maxLeafNodes) {
    // Rebalance the leaf nodes by reorganizing their data into smaller child nodes
    for (auto& child : rootNode->children) {
      auto& grandchild = child->children;

      // Check if the grandchild nodes count exceeds the minimum limit
      if (grandchild.size() > minLeafNodeCapacity) {
        // Rebalance the grandchild nodes by reorganizing their data into smaller leaf nodes
        for (auto& greatGrandchild : grandchild) {
          auto& greatGrandchildData = greatGrandchild->data;

          // Check if the great grandchild node's data capacity exceeds the minimum limit
          if (greatGrandchildData.size() > minLeafNodeCapacity) {
            // Split the great grandchild node's data into smaller leaf nodes
            for (auto it = greatGrandchildData.begin(); it != greatGrandchildData.end();) {
              auto& point = *it;

              // Check if the point is in the child node's data vector
              if (std::find(child->data.begin(), child->data.end(), point) == child->data.end()) {
                // Add the point to the child node's data vector
                child->data.push_back(point);

                // Remove the point from the great grandchild node's data vector
                it = greatGrandchildData.erase(it);
              } else {
                ++it;
              }
            }
          }
        }
      }
    }
  }

  // Decrement the maximum number of concurrent inserts
  --octree.maxConcurrentInserts;

  // Notify any waiting threads that there are no more concurrent inserts or deletions in progress
  octree.cv.notify_all();
}

// Define a function to perform background processing based on the configured interval and frequency
void processBackground(Octree& octree, int interval, float frequency) {
  // Lock the mutex for synchronizing access to the octree
  std::lock_guard<std::mutex> lock(octree.mtx);

  // Check if there are any concurrent inserts or deletions in progress
  while (octree.maxConcurrentInserts > 0) {
    // Wait for the insertion or deletion to complete
    octree.cv.wait(lock);
  }

  // Increment the maximum number of concurrent inserts
  ++octree.maxConcurrentInserts;

  // Perform background processing based on the configured interval and frequency
  auto startTime = std::chrono::high_resolution_clock::now();

  while (true) {
    // Check if the processing time exceeds the specified interval
    if (std::chrono::duration_cast<std::chrono::seconds>(std::chrono::high_resolution_clock::now() - startTime).count() >= interval) {
      break;
    }

    // Perform background processing based on the configured frequency
    auto& rootNode = octree.root;

    // Recursively perform background processing on the child nodes of the root node
    for (auto& child : rootNode->children) {
      processBackground(child, interval, frequency);
    }
  }

  // Decrement the maximum number of concurrent inserts
  --octree.maxConcurrentInserts;

  // Notify any waiting threads that there are no more concurrent inserts or deletions in progress
  octree.cv.notify_all();
}
