const fs = require('fs');
const path = require('path');
const { spawn } = require('child_process');

class ImageProcessor {
  constructor(config) {
    this.config = config;
  }

  async processImage(imagePath, module) {
    const imageInfo = await this.getImageInfo(imagePath);
    return await this.reduce(imageInfo, module);
  }

  async getImageInfo(imagePath) {
    // Parse the TIFF file and extract image info
    const tiffParser = spawn('tiff-parser', ['--info', imagePath]);
    const output = await new Promise((resolve, reject) => {
      let data = '';
      tiffParser.stdout.on('data', (chunk) => {
        data += chunk;
      });
      tiffParser.stderr.on('data', (chunk) => {
        console.log(`TIFF parser error: ${chunk}`);
      });
      tiffParser.on('close', () => resolve(data));
    });

    // Parse the output and extract image info
    const matches = /(\d+)\s+samples per pixel/.exec(output);
    if (!matches) {
      throw new Error(`Unable to parse TIFF file: ${imagePath}`);
    }
    const [, samplesPerPixel] = matches;
    return { samplesPerPixel };
  }

  async reduce(imageInfo, module) {
    // Load the specified module if not already loaded
    if (!this.modules[module]) {
      this.modules[module] = await import(`${__dirname}/modules/${module}`);
    }

    // Execute the reduction function in the module
    try {
      return await this.modules[module].reduce(imageInfo);
    } catch (err) {
      console.error(`Error executing module ${module}:`, err);
      throw new Error('Module execution failed');
    }
  }
}

// Export the ImageProcessor class for use in other modules
module.exports = ImageProcessor;
