function reduce(arr, initVal, callback) {
  let accum = initVal;
  for (let i = 0; i < arr.length; i++) {
    const currentNum = arr[i];
    const nextAccum = callback(accum, currentNum);
    if (nextAccum instanceof Error) return nextAccum;
    accum = nextAccum;
  }
  return accum;
}

