        executor.execute(() -> {
            while (true) {
                try {
                    loadData();
                    processData();
                    reportStatus();
                } catch (Exception e) {
                    // handle exception
                }
            }
        });
    }

    public void stop() {
        executor.shutdownNow();
    }

    private void loadData() throws IOException {
