        try {
            while (true) {
                DataPoint dataPoint = reader.readObject();
                if (dataPoint == null) break;
                dataPoints.add(dataPoint);
            }
        } finally {
            inputStream.close();
        }
    }

    private void processData() {
        // custom deserialization mechanism
    }

    private void reportStatus() {
        // integrate with external messaging system to report processing status and errors
    }
}
