import java.util.HashMap;
import java.util.Map;
import org.json.JSONObject;
import redis.clients.jedis.Jedis;
import redis.clients.jedis.JedisPool;

public class WeatherMicroservice {
    private static final JedisPool jedisPool = new JedisPool();
    private static final Map<String, JSONObject> cache = new HashMap<>();

    public static void main(String[] args) throws Exception {
        // Initialize Redis connection pool
        jedisPool.getResource().set("weather:cache", "{}");

        // Subscribe to real-time weather updates using WebSockets or a similar technology
        // ...

        // Handle incoming JSON payloads from the API and update cache accordingly
        handleWeatherDataUpdate(payload);
    }

    private static void handleWeatherDataUpdate(String payload) {
        JSONObject json = new JSONObject(payload);

        // Validate JSON payload for data integrity and handling potential errors gracefully
        if (json.has("weather") && json.getJSONArray("weather").length() > 0) {
            String region = json.getString("region");
            cache.put(region, json);
            System.out.println("Updated weather data for " + region);
        } else {
            System.err.println("Invalid JSON payload: " + payload);
        }
    }

    public static JSONObject getWeatherData(String region) throws Exception {
        // Check cache first and return immediately if found
        JSONObject json = cache.get(region);
        if (json != null) {
            System.out.println("Cache hit for " + region);
            return json;
        }

        // If cache miss, retrieve from Redis using in-memory caching and distributed caching solutions like Redis
        Jedis jedis = jedisPool.getResource();
        json = new JSONObject(jedis.get("weather:cache"));
        if (json.has(region) && !json.isNull(region)) {
            cache.put(region, json);
            System.out.println("Cache miss for " + region + ". Retrieved from Redis.");
            return json;
        }

        // If cache miss and no data found in Redis, retrieve from third-party API using lazy loading and pagination
        List<JSONObject> weatherData = new ArrayList<>();
        int pageSize = 100;
        for (int i = 0; i < 10; i++) {
            JSONObject page = getWeatherDataPage(region, pageSize, i);
            weatherData.addAll(page.getJSONArray("weather"));
        }

        // Update cache with latest data from third-party API and return
        json.put("weather", weatherData);
        cache.put(region, json);
        jedis.set("weather:cache", json.toString());
        System.out.println("Cache miss for " + region + ". Retrieved from API.");
        return json;
    }

    private static JSONObject getWeatherDataPage(String region, int pageSize, int page) throws Exception {
        // Retrieve weather data from third-party API using HTTP GET request
        URL url = new URL("https://api.openweathermap.org/data/2.5/weather?q=" + region + "&appid=YOUR_API_KEY");
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("GET");
        if (conn.getResponseCode() != 200) {
            throw new Exception("Failed to retrieve weather data for " + region);
        }
        JSONObject json = new JSONObject(new JSONTokener(conn.getInputStream()));
        return json;
    }
}
```
