```c
#include <semaphore.h>
#include <errno.h>
#include <stdlib.h>
#include <string.h>

// Struct to store semaphore information
struct semaphore {
    int value;                 // Current value of the semaphore
    pthread_mutex_t mutex;     // Mutex for synchronizing access to the semaphore
    pthread_cond_t cond;       // Condition variable for signaling changes in the semaphore value
    char* name;                // Name of the semaphore (for debugging purposes)
};

// Function to create a new semaphore with a specified initial value
struct semaphore* sem_create(int initval, const char* name) {
    struct semaphore* sem = malloc(sizeof(struct semaphore));
    if (!sem) {
        fprintf(stderr, "Error: Failed to allocate memory for semaphore\n");
        return NULL;
    }

    // Initialize the semaphore's value and mutex
    sem->value = initval;
    pthread_mutex_init(&sem->mutex, NULL);
    pthread_cond_init(&sem->cond, NULL);

    // Set the name of the semaphore (for debugging purposes)
    if (name != NULL) {
        sem->name = strdup(name);
    } else {
        sem->name = "unnamed";
    }

    return sem;
}

// Function to destroy a semaphore and free its resources
void sem_destroy(struct semaphore* sem) {
    if (!sem) {
        fprintf(stderr, "Error: Trying to destroy an invalid semaphore\n");
        return;
    }

    // Destroy the mutex and condition variable
    pthread_mutex_destroy(&sem->mutex);
    pthread_cond_destroy(&sem->cond);

    // Free the memory allocated for the semaphore's name
    free(sem->name);

    // Finally, free the memory allocated for the semaphore itself
    free(sem);
}

// Function to acquire a semaphore
void sem_acquire(struct semaphore* sem) {
    if (!sem) {
        fprintf(stderr, "Error: Trying to acquire an invalid semaphore\n");
        return;
    }

    // Acquire the mutex
    pthread_mutex_lock(&sem->mutex);

    // Wait for the semaphore value to become non-zero
    while (sem->value == 0) {
        pthread_cond_wait(&sem->cond, &sem->mutex);
    }

    // Decrement the semaphore value and signal any waiting threads
    if (sem->value > 0) {
        sem->value--;
        pthread_cond_signal(&sem->cond);
    }

    // Release the mutex
    pthread_mutex_unlock(&sem->mutex);
}

// Function to release a semaphore
void sem_release(struct semaphore* sem) {
    if (!sem) {
        fprintf(stderr, "Error: Trying to release an invalid semaphore\n");
        return;
    }

    // Acquire the mutex
    pthread_mutex_lock(&sem->mutex);

    // Increment the semaphore value and signal any waiting threads
    if (sem->value < 10) {
        sem->value++;
        pthread_cond_signal(&sem->cond);
    } else {
        fprintf(stderr, "Warning: Semaphore %s is at maximum capacity\n", sem->name);
    }

    // Release the mutex
    pthread_mutex_unlock(&sem->mutex);
}
```
This code creates a `struct semaphore` that stores the current value of the semaphore, the name of the semaphore (for debugging purposes), and two synchronization primitives: a mutex for protecting access to the semaphore value, and a condition variable for signaling changes in the semaphore value.

The `sem_create` function creates a new semaphore with an initial value of `initval`. If `name` is not NULL, it will be used as the name of the semaphore (for debugging purposes). Otherwise, the semaphore will be given the default name "unnamed".

The `sem_destroy` function destroys a semaphore and frees its resources. It takes a pointer to the semaphore as an argument, and returns nothing.

The `sem_acquire` function acquires a semaphore by waiting for it to become non-zero, decrementing its value if possible, and signaling any waiting threads. It takes a pointer to the semaphore as an argument, and returns nothing.

The `sem_release` function releases a semaphore by incrementing its value if possible, and signaling any waiting threads. It takes a pointer to the semaphore as an argument, and returns nothing.

Note that this code assumes that the caller has already acquired the mutex before calling `sem_acquire` or `sem_release`. The mutex is used to ensure that only one thread can access the semaphore at a time, which is necessary for proper synchronization.

