public class PasswordManager
{
    private const int SHA256_ITERATIONS = 10000;
    private const int BCRYPT_ROUNDS = 12;
    private const int ARGON2_MEMORY_SIZE = 1048576; // 1 MiB
    private const int ARGON2_ITERATIONS = 3;
    private const int ARGON2_PARALLELISM = 1;

    private readonly Dictionary<string, string> _passwordHashes = new Dictionary<string, string>();
    private readonly List<string> _saltStrings = new List<string>();
    private readonly Random _random = new Random();

    public PasswordManager(string resourceFilePath)
    {
        // Load resource bundle from file
        using (var streamReader = new StreamReader(resourceFilePath))
        {
            var bundleSize = int.Parse(streamReader.ReadLine());
            for (int i = 0; i < bundleSize; i++)
            {
                var password = streamReader.ReadLine();
                var hashedPassword = HashPassword(password);
                _passwordHashes[password] = hashedPassword;
            }
        }
    }

    public int GetNumberOfItemsInResourceBundle()
    {
        return _passwordHashes.Count;
    }

    public string HashPassword(string password)
    {
        var salt = GenerateSalt();
        var hashedPassword = BCrypt.HashPassword(password, salt);
        return hashedPassword;
    }

    private string GenerateSalt()
    {
        var saltString = new StringBuilder();
        for (int i = 0; i < 16; i++)
        {
            saltString.Append(_random.Next(97, 123).ToString());
        }
        return saltString.ToString();
    }

    public bool VerifyPassword(string password, string hashedPassword)
    {
        var isValid = BCrypt.Verify(password, hashedPassword);
        return isValid;
    }

    public void StoreHashedPassword(string password, string hashedPassword)
    {
        _passwordHashes[password] = hashedPassword;
    }

    public string GetHashedPassword(string password)
    {
        var hashedPassword = _passwordHashes[password];
        return hashedPassword;
    }

    public void StoreSalt(string salt)
    {
        _saltStrings.Add(salt);
    }

    public string GetSalt()
    {
        var salt = _saltStrings[_random.Next(_saltStrings.Count)];
        return salt;
    }

    public void LoadResourceBundleFromFile(string filePath)
    {
        using (var streamReader = new StreamReader(filePath))
        {
            var bundleSize = int.Parse(streamReader.ReadLine());
            for (int i = 0; i < bundleSize; i++)
            {
                var password = streamReader.ReadLine();
                var hashedPassword = HashPassword(password);
                _passwordHashes[password] = hashedPassword;
            }
        }
    }

    public void SaveResourceBundleToFile(string filePath)
    {
        using (var streamWriter = new StreamWriter(filePath))
        {
            var bundleSize = _passwordHashes.Count;
            streamWriter.WriteLine(bundleSize);
            foreach (var password in _passwordHashes.Keys)
            {
                var hashedPassword = _passwordHashes[password];
                streamWriter.WriteLine(hashedPassword);
            }
        }
    }
}
