fn create_directory(name: &str) -> Result<(), std::io::Error> {
    // Check if an environment variable is already set and use its existing value if available
    let mut env = std::env::var("DIR").unwrap();
    if env.is_empty() {
        // Create a new directory with the given name, ensuring that the directory path is accessible and meets the necessary permissions requirements
        let dir = std::fs::DirBuilder::new().recursive(true).create(name);
