using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Xml;
using System.Xml.XPath;

public class XMLDataManager
{
    private readonly Dictionary<string, object> _cache = new Dictionary<string, object>();
    private readonly HashSet<string> _cachedQueries = new HashSet<string>();
    private readonly XmlDocument _doc = new XmlDocument();
    private readonly XPathNavigator _nav = null;

    public XMLDataManager()
    {
        // Load the XML document and create an XPath navigator
        _doc.Load("path/to/xml/file");
        _nav = _doc.CreateNavigator();
    }

    public object GetElement(string xpathQuery)
    {
        if (string.IsNullOrEmpty(xpathQuery))
            throw new ArgumentException("XPath query cannot be empty", nameof(xpathQuery));

        // Check if the query is cached
        if (_cachedQueries.Contains(xpathQuery))
            return _cache[xpathQuery];

        // Get the first matching element using XPath
        XPathNavigator nav = _nav.SelectSingleNode(xpathQuery);
        if (nav == null)
            throw new Exception($"No element found for query {xpathQuery}");

        // Cache the result
        object result = nav.Value;
        _cache[xpathQuery] = result;
        _cachedQueries.Add(xpathQuery);

        return result;
    }

    public void UpdateCache(string xpathQuery, object value)
    {
        if (string.IsNullOrEmpty(xpathQuery))
            throw new ArgumentException("XPath query cannot be empty", nameof(xpathQuery));

        // Update the cache with the new value
        _cache[xpathQuery] = value;

        // Also update the cached queries set
        _cachedQueries.Add(xpathQuery);
    }

    public void RemoveFromCache(string xpathQuery)
