#include <iostream>
#include <random>
#include <string>

namespace RandomGenerator {
    class SecureMersenneTwister {
        private:
            std::mt19937_64 gen;
            std::seed_seq seed;

        public:
            SecureMersenneTwister(const std::string& seed) {
                this->gen.seed(std::random_device());
                this->seed = std::seed_seq(this->gen());
            }

            ~SecureMersenneTwister() {
                // trivial destructor
            }

            double generateUniformRandomNumber(double min, double max) {
                return std::uniform_real_distribution<>(min, max)(this->seed);
            }

            double generateNormalRandomNumber(double mean, double standardDeviation) {
                return std::normal_distribution<>(mean, standardDeviation)(this->seed);
            }
    };
}
