```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.AsynchronousChannelGroup;
import java.nio.channels.AsynchronousServerSocketChannel;
import java.nio.channels.AsynchronousSocketChannel;
import java.nio.channels.CompletionHandler;
import java.security.GeneralSecurityException;
import java.security.KeyStore;
import javax.net.ssl.SSLContext;
import javax.net.ssl.SSLEngine;
import javax.net.ssl.TrustManagerFactory;

public class NioServer {
    private static final int MAX_CONNECTIONS = 100; // maximum number of simultaneous connections
    private static final int POOL_SIZE = 8; // size of the connection pool
    private static final long KEEPALIVE = 60000L; // timeout for idle connections in milliseconds

    public static void main(String[] args) throws IOException, GeneralSecurityException {
        SSLContext sslContext = createSslContext();
        AsynchronousChannelGroup channelGroup = AsynchronousChannelGroup.withCachedThreadPool(POOL_SIZE);
        InetSocketAddress serverAddress = new InetSocketAddress("localhost", 8080);
        AsynchronousServerSocketChannel serverSocket = AsynchronousServerSocketChannel.open(channelGroup);
        serverSocket.setOption(AsynchronousSocketChannel.SO_REUSEADDR, true);
        serverSocket.bind(serverAddress);
        System.out.println("Listening for incoming connections on port 8080...");

        while (true) {
            serverSocket.accept((channel, attachment) -> {
                channel.configureBlocking(false);
                SSLContext clientSslContext = sslContext;
                SSLEngine engine = clientSslContext.createSSLEngine();
                if (!engine.getEnabledCipherSuites().contains("RSA")) {
                    throw new RuntimeException("Invalid cipher suite");
                }
                engine.setUseClientMode(false);
                channel.pipeline().addLast(new SslHandler(engine));
                channel.pipeline().addLast(new SimpleChannelInboundHandler<ByteBuf>() {
                    @Override
                    protected void channelRead0(ChannelHandlerContext ctx, ByteBuf msg) throws Exception {
                        // handle incoming messages from the client
                    }
                });
            }, null);
        }
    }

    private static SSLContext createSslContext() throws GeneralSecurityException {
        TrustManagerFactory tmf = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
        KeyStore keyStore = KeyStore.getInstance("JKS");
        keyStore.load(NioServer.class.getResourceAsStream("/certs/my_truststore.jks"), "password".toCharArray());
        tmf.init(keyStore);
        SSLContext sslContext = SSLContext.getInstance("TLS");
        sslContext.init(null, tmf.getTrustManagers(), null);
        return sslContext;
    }
}
