<?php
function generateSecureRandomString($length = 32, $characters = 'alphanumeric', $lifetime = 300) {
    // Validate input parameters
    if (!is_int($length) || !in_array($characters, ['alphanumeric', 'alphanumeric_special'])) {
        throw new \Exception('Invalid input parameters');
    }

    // Generate random string
    $randomString = '';
    for ($i = 0; $i < $length; $i++) {
        $randomString .= substr($characters, rand(0, strlen($characters)), 1);
    }

    // Hash and salt the string using Bcrypt algorithm
    $hashedString = password_hash($randomString, PASSWORD_BCRYPT, ['cost' => 12]);

    // Store hashed string in session storage (e.g., Redis)
    $sessionId = session_id();
    $sessionStorage->set($sessionId, $hashedString);

    // Return the token
    return $randomString;
}

function readFilesFromDirectory($directory, $fileType = 'text') {
    // Validate input parameters
    if (!is_string($directory) || !in_array($fileType, ['text', 'binary'])) {
        throw new \Exception('Invalid input parameters');
    }

    // Read files from the directory asynchronously and return their contents as a string using the `fs` library
    $files = scandir($directory);
    $contents = '';
    foreach ($files as $file) {
        if (is_file($file)) {
            $fileHandle = fopen($file, 'r');
            if (!$fileHandle) {
                throw new \Exception('Error opening file: ' . $file);
            }
            if ($fileType === 'text') {
                while ($line = fgets($fileHandle)) {
                    $contents .= $line;
                }
            } elseif ($fileType === 'binary') {
                $contents .= fread($fileHandle, filesize($file));
            }
            fclose($fileHandle);
        }
    }

    // Return the contents of the files as a string
    return $contents;
}
