```javascript
// Read files from a directory asynchronously and return their contents as a string using the `fs` library
const fs = require('fs');
const path = require('path');

function readFilesFromDirectory(directory, fileType) {
    // Validate input parameters
    if (!directory || !fileType) {
        throw new Error('Invalid input parameters');
    }

    const files = fs.readdirSync(directory);
    let contents = '';

    for (const file of files) {
        if (fs.lstatSync(path.join(directory, file)).isFile()) {
            try {
                const fileHandle = fs.openSync(path.join(directory, file), 'r');
                if (!fileHandle) {
                    throw new Error(`Error opening file: ${file}`);
                }
                if (fileType === 'text') {
                    while (true) {
                        const line = fs.readFileSync(path.join(directory, file), fileHandle, null, 0);
                        if (!line) {
                            break;
                        }
                        contents += line;
                    }
                } else if (fileType === 'binary') {
                    const buffer = fs.readFileSync(path.join(directory, file), fileHandle);
                    contents += buffer.toString('utf8');
                }
                fs.closeSync(fileHandle);
            } catch (error) {
                throw new Error(`Error reading file: ${file}`);
            }
        }
    }

    return contents;
}
