const fs = require('fs');
const path = require('path');

// Implement file reading, parsing, and merging in a performant and scalable manner
async function readConfigFiles(dirPath) {
  const configs = {};
  try {
    const files = await fs.promises.readdir(dirPath);
    for (const file of files) {
      const filePath = path.join(dirPath, file);
      const content = await fs.promises.readFile(filePath, 'utf8');
      const config = JSON.parse(content);
      Object.assign(configs, config);
    }
  } catch (err) {
    // Handle error cases such as missing files, invalid JSON format, file read timeouts, and permission issues
    console.error(`Error reading configuration file: ${err.message}`);
  }
  return configs;
}

// Expose an API that allows users to specify file types (e.g., .json, .yaml) and default values for missing configurations
function mergeConfigs(configPath, options = {}) {
  const {
    fileType = 'json', // Default file type is JSON
    defaultValues = {}, // Default values for missing configurations
  } = options;
  const dirPath = path.join(configPath, `*.${fileType}`);
  return readConfigFiles(dirPath).then((configs) => {
    Object.assign(defaultValues, configs);
    return defaultValues;
  });
}

// Unit tests for the module
const assert = require('assert');

describe('Configuration merging', () => {
  it('Merges multiple configuration files', async () => {
    const configPath = path.join(__dirname, 'configs');
    const mergedConfigs = await mergeConfigs(configPath);
    assert.deepEqual(mergedConfigs, {
      foo: 123,
      bar: 'abc',
    });
  });
});
