// Define the exponential backoff strategy for failed requests
#define EXPONENTIAL_BACKOFF_BASE 2

// Define the default output format for scraped data
#define DEFAULT_OUTPUT_FORMAT "text"

// Define the maximum number of URLs to scrape
#define MAX_URLS 1000

// Define the URL list
char *urls[MAX_URLS];

// Define the number of URLs currently being scraped
int num_urls = 0;

