pthread_cond_t url_available;

// Define the thread function for concurrent data retrieval
void *download_url(void *arg) {
  // Get the URL to scrape
  char *url = (char *)arg;

  // Initialize a CURL handle for making HTTP requests
  CURL *curl = curl_easy_init();
  if (!curl) {
    return NULL;
  }

