  curl_easy_setopt(curl, CURLOPT_URL, url);
  curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_response);
  curl_easy_setopt(curl, CURLOPT_WRITEDATA, stdout);

  // Set the error buffer for CURL
  char error[CURL_ERROR_SIZE];
  curl_easy_setopt(curl, CURLOPT_ERRORBUFFER, error);

  // Perform the HTTP request and check for errors
  CURLcode res = curl_easy_perform(curl);
  if (res != CURLE_OK) {
    fprintf(stderr, "CURL error: %s\n", error);
    return NULL;
  }

  // Close the CURL handle
  curl_easy_cleanup(curl);

  return NULL;
}

// Define the function for writing HTTP responses to stdout
size_t write_response(char *ptr, size_t size, size_t nmemb, void *userdata) {
  // Get the number of bytes to write
  size_t num_bytes = size * nmemb;

  // Write the response to stdout
  fwrite(ptr, sizeof(char), num_bytes, stdout);

  return num_bytes;
}

// Define the function for handling failed HTTP requests
void handle_failed_request(CURLcode res) {
  // Print an error message if the request failed
  if (res != CURLE_OK) {
    fprintf(stderr, "CURL error: %s\n", curl_easy_strerror(res));
  }
}

// Define the function for handling partial data fetches due to network interruptions
void handle_partial_fetch() {
  // Print a warning message if the request was incomplete
  fprintf(stderr, "Partial data fetch. Retrying...\n");

  // Retry the request with an exponential backoff strategy
  int delay = EXPONENTIAL_BACKOFF_BASE;
  for (int i = 0; i < MAX_RETRIES; i++) {
    sleep(delay);

    // Perform the HTTP request again
    CURLcode res = curl_easy_perform(curl);

    // Check if the request was successful or if we should retry
    if (res == CURLE_OK) {
      break;
    } else if (i + 1 < MAX_RETRIES) {
      delay *= EXPONENTIAL_BACKOFF_BASE;
    } else {
      fprintf(stderr, "Failed to retrieve data after %d retries\n", MAX_RETRIES);
      return;
    }
  }
}

