use std::time::Instant;
use std::process::Command;
use std::fs;

fn compile_dir(dir: &str) -> Result<(), String> {
    let start = Instant::now();

    // Get all .rs files in the directory
    let rust_files = fs::read_dir(dir)?.filter(|file| file.extension().unwrap_or_default() == "rs");

    // Compile each .rs file using the Rust compiler
    for rust_file in rust_files {
        let mut compile_cmd = Command::new("rustc");
        compile_cmd.arg(rust_file.path());
        let output = compile_cmd.output()?;

        // Log compilation details and errors
        log!(format!("Compiled {} in {:?}", rust_file.path(), start.elapsed()));
        if !output.status.success() {
            log!(format!("Error compiling {}", rust_file.path()));
        }
    }

    // Get the commit message associated with the changes in the directory
    let git_commit = Command::new("git").arg("log").arg("-1").output()?;

    // Measure total compilation time and monitor memory usage
    let end = Instant::now();
    let total_time = start.elapsed();
    let memory_usage = get_resident_set_size(end)?;

    // Report the compilation report
    println!("Compilation Report:");
    println!("Total Time: {}", total_time);
    println!("Memory Usage: {}", memory_usage);
    if !output.status.success() {
        println!("Errors Encountered:");
        for error in output.stderr.lines() {
            println!("{}", error);
        }
    }

    Ok(())
}
