using System;
using UnityEngine;

public class AdvancedCustomRandomGenerator
{
    private Random _random;
    private int _seed;
    private double[] _cache;
    private readonly string _configFilePath = "AdvancedCustomRandomGenerator.xml";

    public AdvancedCustomRandomGenerator()
    {
        _random = new UnityEngine.Random();
        _seed = _random.Seed;
        LoadConfig();
    }

    public float NextFloat(float min, float max)
    {
        if (min >= max) throw new ArgumentException("Minimum value cannot be greater than or equal to maximum value");

        int minInt = Mathf.FloorToInt(min);
        int maxInt = Mathf.CeilToInt(max);
        float range = max - min;
        float randomNumber = (float)_random.NextDouble() * range + min;

        return randomNumber;
    }

    public int NextInt(int min, int max)
    {
        if (min >= max) throw new ArgumentException("Minimum value cannot be greater than or equal to maximum value");

        int range = max - min + 1;
        return _random.Next(range) + min;
    }

    public float NextFloat(float[] limits)
    {
        if (limits.Length == 0 || limits.Length % 2 != 0) throw new ArgumentException("Invalid limits array");

        int index = _random.Next(limits.Length / 2);
        return NextFloat(limits[index * 2], limits[index * 2 + 1]);
    }

    public int NextInt(int[] limits)
    {
        if (limits.Length == 0 || limits.Length % 2 != 0) throw new ArgumentException("Invalid limits array");

        int index = _random.Next(limits.Length / 2);
        return NextInt(limits[index * 2], limits[index * 2 + 1]);
    }

    public float[] NextFloats(float min, float max, int count)
    {
        if (min >= max || count <= 0) throw new ArgumentException("Invalid input parameters");

        float[] randomNumbers = new float[count];
        for (int i = 0; i < count; i++)
            randomNumbers[i] = NextFloat(min, max);

        return randomNumbers;
    }

    public int[] NextInts(int min, int max, int count)
    {
        if (min >= max || count <= 0) throw new ArgumentException("Invalid input parameters");

        int[] randomNumbers = new int[count];
        for (int i = 0; i < count; i++)
            randomNumbers[i] = NextInt(min, max);

        return randomNumbers;
    }

    public float[] NextFloats(float[] limits, int count)
    {
        if (limits.Length == 0 || limits.Length % 2 != 0 || count <= 0) throw new ArgumentException("Invalid input parameters");

        float[] randomNumbers = new float[count];
        for (int i = 0; i < count; i++)
            randomNumbers[i] = NextFloat(limits);

        return randomNumbers;
    }

    public int[] NextInts(int[] limits, int count)
    {
        if (limits.Length == 0 || limits.Length % 2 != 0 || count <= 0) throw new ArgumentException("Invalid input parameters");

        int[] randomNumbers = new int[count];
        for (int i = 0; i < count; i++)
            randomNumbers[i] = NextInt(limits);

        return randomNumbers;
    }

    public float CustomDistribution(float min, float max, Func<float, bool> distributionFunction)
    {
        if (min >= max || distributionFunction == null) throw new ArgumentException("Invalid input parameters");

        float range = max - min;
        float randomNumber = (float)_random.NextDouble() * range + min;

        while (!distributionFunction(randomNumber))
            randomNumber = (float)_random.NextDouble() * range + min;

        return randomNumber;
    }

    public void SetSeed(int seed)
    {
        if (seed == _seed) return;

        _seed = seed;
        _random = new UnityEngine.Random(_seed);
    }

    public void LoadConfig()
    {
        try
        {
            XmlDocument configFile = new XmlDocument();
            configFile.Load(_configFilePath);

            XmlNodeList rangesNodes = configFile.GetElementsByTagName("ranges");
            foreach (XmlElement range in rangesNodes)
            {
                int min = int.Parse(range.Attributes["min"].Value);
                int max = int.Parse(range.Attributes["max"].Value);

                _cache[range.Attributes["index"].Value] = NextInt(min, max);
            }
        }
        catch (Exception e)
        {
            Console.WriteLine("Error loading configuration file: " + e.Message);
        }
    }

    public void SaveConfig()
    {
        try
        {
            XmlDocument configFile = new XmlDocument();
            XmlNode ranges = configFile.CreateElement("ranges");

            foreach (var cacheEntry in _cache)
            {
                XmlNode range = configFile.CreateElement("range");
                range.Attributes["min"].Value = _random.NextInt(cacheEntry).ToString();
                range.Attributes["max"].Value = _random.NextInt(cacheEntry).ToString();
                ranges.AppendChild(range);
            }

            configFile.AppendChild(ranges);
            configFile.Save(_configFilePath);
        }
        catch (Exception e)
        {
            Console.WriteLine("Error saving configuration file: " + e.Message);
        }
    }
}
