<?php

function authenticateUser($provider, $username, $password) {
  // Load provider settings from environment variables
  $settings = getProviderSettings($provider);

  // Authenticate user using OAuth 2.0 client
  $oauthClient = new OAuthClient($settings['client_id'], $settings['client_secret'], $settings['redirect_uri']);
  $accessToken = $oauthClient->getAccessToken($username, $password);

  // Store access token securely in session variable
  $_SESSION['access_token'] = $accessToken;

  // Retrieve user information using access token
  $userInfo = $oauthClient->getUserInfo($accessToken);

  // Log authentication attempt with detailed timestamp and IP address
  logAuthenticationAttempt($username, $password, $_SERVER['REMOTE_ADDR']);

  // Return user information if successful, or an error message if unsuccessful
  if ($userInfo) {
    return $userInfo;
  } else {
    return 'Invalid username and password combination';
  }
}

function getProviderSettings($provider) {
  // Load provider settings from environment variables
  switch ($provider) {
    case 'Google':
      return [
        'client_id' => $_ENV['GOOGLE_CLIENT_ID'],
        'client_secret' => $_ENV['GOOGLE_CLIENT_SECRET'],
        'redirect_uri' => $_ENV['GOOGLE_REDIRECT_URI']
      ];
    case 'Facebook':
      return [
        'client_id' => $_ENV['FACEBOOK_CLIENT_ID'],
        'client_secret' => $_ENV['FACEBOOK_CLIENT_SECRET'],
        'redirect_uri' => $_ENV['FACEBOOK_REDIRECT_URI']
      ];
    case 'Twitter':
      return [
        'client_id' => $_ENV['TWITTER_CLIENT_ID'],
        'client_secret' => $_ENV['TWITTER_CLIENT_SECRET'],
        'redirect_uri' => $_ENV['TWITTER_REDIRECT_URI']
      ];
    default:
      throw new Exception('Invalid provider specified');
  }
}

function logAuthenticationAttempt($username, $password, $ipAddress) {
  // Log authentication attempt with detailed timestamp and IP address
  $timestamp = date('Y-m-d H:i:s');
  $logMessage = "{$username} attempted to authenticate with password {$password} from IP address {$ipAddress} at {$timestamp}";
  error_log($logMessage);
}

function invalidateTokens() {
  // Invalidate tokens if there is suspicious activity, such as multiple failed login attempts from different IP addresses within a short period
  $numFailedAttempts = count($_SESSION['failed_attempts']);
  $numIpAddresses = count(array_unique($_SESSION['failed_attempts'], SORT_REGULAR));

  if ($numFailedAttempts > 3 && $numIpAddresses <= 5) {
    // Invalidate tokens and reset failed attempt counter
    $_SESSION['access_token'] = null;
    $_SESSION['failed_attempts'] = [];

    return true;
  } else {
    return false;
  }
}
