import os
import logging
import random
import time
from threading import Lock
from collections import deque

class DirectoryManager:
    def __init__(self, directory_path):
        self.directory_path = directory_path
        self.lock = Lock()
        self.available_directories = deque([])
        self.used_directories = set()

    def create_directory(self, prefix='', suffix=''):
        with self.lock:
            while True:
                directory_name = f'{prefix}{random.randrange(1000000)}{suffix}'
                directory_path = os.path.join(self.directory_path, directory_name)
                try:
                    os.makedirs(directory_path)
                    self.available_directories.append(directory_path)
                    return directory_path
                except OSError as e:
                    if e.errno != errno.EEXIST:
                        raise e
                    time.sleep(random.uniform(0, 1))

    def delete_directory(self, directory_path):
        with self.lock:
            try:
                os.rmdir(directory_path)
                self.used_directories.remove(directory_path)
            except OSError as e:
                if e.errno != errno.ENOENT:
                    raise e

    def get_available_directories(self):
        with self.lock:
            return list(self.available_directories)

    def get_used_directories(self):
        with self.lock:
            return list(self.used_directories)

class EnvironmentVariableManager:
    def __init__(self, prefix=''):
        self.prefix = prefix
        self.variables = {}

    def set_variable(self, name, value):
        with self.lock:
            self.variables[name] = value

    def get_variable(self, name):
        with self.lock:
            return self.variables.get(name)

class FileProcessor:
    def __init__(self, directory_manager, environment_variable_manager):
        self.directory_manager = directory_manager
        self.environment_variable_manager = environment_variable_manager
        self.lock = Lock()
        self.file_operations = []

    def process_files(self, file_paths):
        with self.lock:
            for file_path in file_paths:
                operation = FileOperation(file_path)
                self.file_operations.append(operation)

    def start_processing(self):
        with self.lock:
            while True:
                if len(self.file_operations) == 0:
                    break
                operation = self.file_operations[0]
                try:
                    operation.process()
                    self.file_operations.popleft()
                except Exception as e:
                    logging.exception(f'Error processing file {operation.file_path}: {e}')
                    time.sleep(random.uniform(0, 1))

class FileOperation:
    def __init__(self, file_path):
        self.file_path = file_path
        self.directory_manager = DirectoryManager('')
        self.environment_variable_manager = EnvironmentVariableManager('')

    def process(self):
        with self.lock:
            directory_path = self.directory_manager.create_directory()
            self.environment_variable_manager.set_variable('directory', directory_path)
            self.file_operations.append(operation)

def get_available_hash_functions():
    hash_functions = []
    for name in ['sha256', 'md5']:
        try:
            hashlib.new(name)
            hash_functions.append(name)
        except ValueError as e:
            if not str(e).startswith('Unknown hash type'):
                raise e
    return hash_functions

def get_available_ciphers():
    ciphers = []
    for name in ['aes-256-cbc', 'camellia-192-cfb']:
        try:
            crypto.Cipher(name)
            ciphers.append(name)
        except ValueError as e:
            if not str(e).startswith('Unknown cipher type'):
                raise e
    return ciphers
