#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <pthread.h>
#include <sys/types.h>
#include <unistd.h>

// Global variables
int num_threads = 50; // Maximum number of concurrent downloads
char *input_dir = "./input"; // Input directory containing URLs
char *output_dir = "./output"; // Output directory for saving downloaded files
int max_retry = 3; // Maximum number of retries before giving up
int timeout = 10; // Timeout value in seconds

// Struct to hold download information
struct download {
    char *url;
    char *filename;
    int id;
};

// Thread pool for managing concurrent downloads
pthread_t thread_pool[num_threads];
int num_active = 0; // Number of active threads
int num_completed = 0; // Number of completed downloads

// Function to handle a download
void *download_handler(void *arg) {
    struct download *dl = (struct download *) arg;
    CURL *curl;
    CURLcode res;
    FILE *fp;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    // Set URL, filename, and retry options
    curl_easy_setopt(curl, CURLOPT_URL, dl->url);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
    curl_easy_setopt(curl, CURLOPT_NOPROGRESS, 0L);
    curl_easy_setopt(curl, CURLOPT_PROGRESSDATA, dl->filename);
    curl_easy_setopt(curl, CURLOPT_VERBOSE, 1L);
    if (max_retry > 0) {
        curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
        curl_easy_setopt(curl, CURLOPT_MAXREDIRS, max_retry);
    }
    // Set timeout option
    if (timeout > 0) {
        curl_easy_setopt(curl, CURLOPT_TIMEOUT, timeout);
    }

    fp = fopen(dl->filename, "wb");
    if (!fp) {
        printf("Error: Failed to open file %s\n", dl->filename);
        curl_easy_cleanup(curl);
        return NULL;
    }

    // Download the file
    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        printf("Error: %s\n", curl_easy_strerror(res));
    } else {
        num_completed++;
        printf("Downloaded %d/%d files (%.2f%%)\n", num_completed, num_active, (num_completed / (double) num_active) * 100);
    }

    // Close file and cleanup
    fclose(fp);
    curl_easy_cleanup(curl);

    free(dl->url);
    free(dl->filename);
    free(dl);

    return NULL;
}

// Function to manage concurrent downloads in the thread pool
void manage_downloads() {
    struct download *dl;
    pthread_t tid;

    // Create a new download structure and initialize it
    dl = (struct download *) malloc(sizeof(struct download));
    if (!dl) {
        printf("Error: Failed to allocate memory for download\n");
        return;
    }
    memset(dl, 0, sizeof(*dl));

    // Get the next URL and filename from the input directory
    dl->url = get_next_url();
    if (!dl->url) {
        free(dl);
        return;
    }
    dl->filename = get_output_filename(dl->url);
    if (!dl->filename) {
        free(dl->url);
        free(dl);
        return;
    }

    // Start a new thread to handle the download
    pthread_create(&tid, NULL, download_handler, (void *) dl);
    printf("Started download %d: %s\n", num_active + 1, dl->url);

    // Increment the number of active threads and wait for the thread to finish
    num_active++;
    pthread_join(tid, NULL);
    num_active--;
}

// Function to get the next URL from the input directory
char *get_next_url() {
    // TODO: Implement this function to retrieve the next URL from the input directory
    return "https://example.com/file1.txt";
}

// Function to generate an output filename for a given URL
char *get_output_filename(char *url) {
    // TODO: Implement this function to generate a unique output filename for the given URL
    return "./output/file1.txt";
}

int main(int argc, char **argv) {
    int i;

    if (argc < 3) {
        printf("Usage: %s [input_directory] [output_directory] [max_concurrent_downloads]\n", argv[0]);
        return 1;
    }
    input_dir = argv[1];
    output_dir = argv[2];
    if (argc > 3) {
        num_threads = atoi(argv[3]);
    }

    // Initialize the thread pool and start downloading files concurrently
    for (i = 0; i < num_threads; i++) {
        pthread_create(&thread_pool[i], NULL, manage_downloads, NULL);
    }

    return 0;
}

