<?php

class ClinicStatusUpdate {
    private $clinicId;
    private $newStatus;
    private $lastModifiedIpAddress;
    private $lastModifiedDate;

    public function __construct($clinicId, $newStatus) {
        $this->clinicId = $clinicId;
        $this->newStatus = $newStatus;
        $this->lastModifiedIpAddress = $_SERVER['REMOTE_ADDR'];
        $this->lastModifiedDate = date('Y-m-d H:i:s');
    }

    public function updateClinicStatus() {
        // Begin transaction
        try {
            $db = getDatabaseConnection();
            $stmt = $db->prepare("UPDATE clinics SET status = :new_status, last_modified_ip_address = :last_modified_ip_address, last_modified_date = :last_modified_date WHERE id = :clinic_id");
            $stmt->bindParam(':new_status', $this->newStatus);
            $stmt->bindParam(':last_modified_ip_address', $this->lastModifiedIpAddress);
            $stmt->bindParam(':last_modified_date', $this->lastModifiedDate);
            $stmt->bindParam(':clinic_id', $this->clinicId);
            $stmt->execute();
            $db = null;
        } catch (PDOException $e) {
            // Log error and rollback transaction
            $logger = getLoggerInstance();
            $logger->error("Error updating clinic status: " . $e->getMessage());
            return false;
        }

        return true;
    }
}

function updateClinicStatus($clinicId, $newStatus) {
    // Validate input
    if (!is_numeric($clinicId) || !is_string($newStatus)) {
        throw new InvalidArgumentException('Invalid argument type');
    }

    // Check if clinic ID exists in database
    $db = getDatabaseConnection();
    $stmt = $db->prepare("SELECT COUNT(*) FROM clinics WHERE id = :clinic_id");
    $stmt->bindParam(':clinic_id', $clinicId);
    $stmt->execute();
    if ($stmt->fetchColumn() == 0) {
        throw new Exception('Clinic ID does not exist');
    }

    // Begin transaction
    $db = getDatabaseConnection();
    $stmt = $db->prepare("UPDATE clinics SET status = :new_status, last_modified_ip_address = :last_modified_ip_address, last_modified_date = :last_modified_date WHERE id = :clinic_id");
    $stmt->bindParam(':new_status', $newStatus);
    $stmt->bindParam(':last_modified_ip_address', $_SERVER['REMOTE_ADDR']);
    $stmt->bindParam(':last_modified_date', date('Y-m-d H:i:s'));
    $stmt->bindParam(':clinic_id', $clinicId);
    $stmt->execute();
    $db = null;

    // Log update
    $logger = getLoggerInstance();
    $logger->info("Clinic status updated for clinic ID " . $clinicId);
}
