function extractOldTestamentBooks($text) {
  // Use regular expressions to identify and extract book names from the text
  $pattern = '/(?<bookName>[^[:space:]]{1,50})/';
  preg_match_all($pattern, $text, $matches);

  // Initialize an empty array to store the book names and their occurrences
  $books = [];

  // Iterate over each match found in the text
  foreach ($matches[0] as $book) {
    // Check if the book name is a valid Old Testament book
    if (in_array($book, ['Genesis', 'Exodus', 'Leviticus', 'Numbers', 'Deuteronomy'])) {
      // Increment the number of occurrences for this book
      $books[$book] = ($books[$book] ?? 0) + 1;
    }
  }

  // Return the object with the extracted book names and their occurrences
  return $books;
}
