using System;
using System.Threading.Tasks;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using Microsoft.Extensions.Logging;

namespace SecureFileManagementSystem
{
    public class FileManager
    {
        private readonly ILogger _logger;
        private readonly AesGcmEncryptionService _encryptionService;
        private readonly KeyManagementService _keyManagementService;
        private readonly Dictionary<string, object> _locks = new Dictionary<string, object>();

        public FileManager(ILogger<FileManager> logger, AesGcmEncryptionService encryptionService, KeyManagementService keyManagementService)
        {
            _logger = logger;
            _encryptionService = encryptionService;
            _keyManagementService = keyManagementService;
        }

        public async Task UploadAsync(string filePath, string bucketName, string objectKey)
        {
            var encryptedFilePath = GetEncryptedFilePath(filePath);
            using (var fs = new FileStream(encryptedFilePath, FileMode.Open))
            {
                var metadata = await _keyManagementService.GetMetadataAsync(objectKey);
                var nonce = metadata["nonce"];
                var tag = metadata["tag"];
                var initializationVector = metadata["initializationVector"];
                var ciphertext = await _encryptionService.EncryptAsync(fs, nonce, tag, initializationVector);
                await UploadCiphertextToStorageAsync(bucketName, objectKey, ciphertext);
            }
        }

        public async Task DownloadAsync(string filePath, string bucketName, string objectKey)
        {
            var metadata = await _keyManagementService.GetMetadataAsync(objectKey);
            var nonce = metadata["nonce"];
            var tag = metadata["tag"];
            var initializationVector = metadata["initializationVector"];
            var ciphertext = await DownloadCiphertextFromStorageAsync(bucketName, objectKey);
            using (var fs = new FileStream(filePath, FileMode.Create))
            {
                var plaintext = await _encryptionService.DecryptAsync(ciphertext, nonce, tag, initializationVector);
                await fs.WriteAsync(plaintext);
            }
        }

        private async Task UploadCiphertextToStorageAsync(string bucketName, string objectKey, byte[] ciphertext)
        {
            var lockObject = GetLockObject(objectKey);
            lock (lockObject)
            {
                try
                {
                    await _storageService.UploadAsync(bucketName, objectKey, ciphertext);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Failed to upload file");
                }
            }
        }

        private async Task<byte[]> DownloadCiphertextFromStorageAsync(string bucketName, string objectKey)
        {
            var lockObject = GetLockObject(objectKey);
            lock (lockObject)
            {
                try
                {
                    return await _storageService.DownloadAsync(bucketName, objectKey);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Failed to download file");
                }
            }
        }

        private string GetEncryptedFilePath(string filePath)
        {
            return Path.Combine(filePath + ".enc");
        }

        private object GetLockObject(string objectKey)
        {
            if (!_locks.ContainsKey(objectKey))
            {
                _locks[objectKey] = new object();
            }
            return _locks[objectKey];
        }
    }
}
