#include <fstream>
#include <iostream>
#include <string>
#include <unordered_map>
#include <variant>

std::unordered_map<std::string, std::variant<int, double, std::string, bool>>
loadConfiguration(const std::string& filePath) {
    // Check if the file exists and is readable
    std::ifstream file(filePath);
    if (!file.good()) {
        // Log an error message
        std::cerr << "Error: unable to read configuration file \"" << filePath << "\"\n";
        return {};
    }

    // Load the JSON file and parse it into a map
    nlohmann::json json;
    try {
        json = nlohmann::json::parse(file);
    } catch (const std::exception& e) {
        // Log an error message if the JSON is malformed
        std::cerr << "Error: unable to parse configuration file \"" << filePath << "\": " << e.what() << "\n";
        return {};
    }

    // Iterate over the keys in the JSON object and create a map of key-value pairs
    std::unordered_map<std::string, std::variant<int, double, std::string, bool>> configMap;
    for (const auto& [key, value] : json.items()) {
        // Check if the key is present in the JSON object and has a valid type
        if (!value.is_number() && !value.is_boolean() && !value.is_string()) {
            // Log an error message if the key has an invalid type
            std::cerr << "Error: invalid type for configuration key \"" << key << "\": expected number, boolean, or string\n";
            return {};
        }

        // Add the key-value pair to the map
        configMap[key] = value;
    }

    return configMap;
}
```
This function uses the `nlohmann::json` library to parse a JSON file and convert it into an `std::unordered_map<std::string, std::variant<int, double, std::string, bool>>`. The map contains key-value pairs where the keys are strings and the values are variants of integers, doubles, strings, or booleans.

The function first checks if the file exists and is readable before attempting to parse it. If an error occurs while reading the file or parsing the JSON, an error message is logged and the map is returned empty.

To ensure efficient memory allocation and reduce the risk of memory leaks, the function uses a `std::variant` to store the values in the map. The variant can hold any of the supported types (integer, double, string, or boolean) for each key-value pair.

The function also includes error handling for cases where specific keys are missing or have an invalid type. In such cases, an error message is logged and the map is returned empty.

Integration with an existing logging system can be achieved by using a logger library like `spdlog` to log any errors encountered during the loading process. The function can then return the map empty if there are any errors encountered, which can be used by the calling code to handle the error gracefully.

