#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <limits.h>
#include <errno.h>

int main(int argc, char **argv) {
    // Initialize variables
    int ret = 0;
    char *filename = NULL;
    char *password = NULL;
    size_t length = 16;
    struct stat st;
    unsigned char hash[SHA256_DIGEST_LENGTH];
    FILE *file;

    // Check command-line arguments
    if (argc != 3) {
        printf("Usage: %s <filename> <password>\n", argv[0]);
        return 1;
    }
    filename = argv[1];
    password = argv[2];

    // Open the file and check if it exists
    if ((file = fopen(filename, "r")) == NULL) {
        printf("Error opening file %s: %s\n", filename, strerror(errno));
        return 1;
    }
    if (fstat(fileno(file), &st) < 0) {
        printf("Error getting file status for %s: %s\n", filename, strerror(errno));
        fclose(file);
        return 1;
    }

    // Read the file and generate a random string based on its contents
    char buffer[BUFSIZ];
    while (fgets(buffer, BUFSIZ, file)) {
        // Hash the password using SHA-256
        SHA256_Init(&hash);
        SHA256_Update(&hash, password, strlen(password));
        SHA256_Final(buffer, &hash);

        // Generate a random string of the specified length based on the hashed password
        char *random_string = generate_random_string(buffer, length);

        // Print the random string and free memory
        printf("%s\n", random_string);
        free(random_string);
    }

    // Close the file and return success
    fclose(file);
    return 0;
}

char *generate_random_string(const char *buffer, size_t length) {
    // Initialize variables
    int i = 0;
    unsigned long seed = 0;
    char *result = NULL;

    // Generate a random string of the specified length based on the buffer contents
    while (i < length) {
        seed = (seed + ((unsigned long)(buffer[i++] & 0xFF))) % UINT_MAX;
        result = realloc(result, i);
        result[i - 1] = 'a' + (seed % ('z' - 'a' + 1));
    }

    // Return the generated string
    return result;
}
