Java Code:
```java
import java.io.*;
import java.util.Random;

public class RandomString {
    public static void main(String[] args) throws IOException {
        if (args.length != 2) {
            System.out.println("Usage: java RandomString <input file> <password>");
            return;
        }
        FileInputStream fis = new FileInputStream(args[0]);
        DataInputStream dis = new DataInputStream(fis);
        String password = args[1];
        int length = 16;
        byte[] buffer = new byte[length];
        while (dis.read(buffer) > 0) {
            // Hash the password using SHA-256
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            md.update(password.getBytes());
            byte[] hash = md.digest();

            // Generate a random string of the specified length based on the hashed password
            String randomString = generateRandomString(hash, length);

            // Print the random string and free memory
            System.out.println(randomString);
        }
    }

    private static String generateRandomString(byte[] buffer, int length) {
        Random rand = new Random();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < length; i++) {
            char c = (char)(rand.nextInt('z' - 'a') + 'a');
            sb.append(c);
        }
        return sb.toString();
    }
}
