// Structure to store the cipher context
struct AESCipherContext {
  AES_KEY* key;
  unsigned char* iv;
  pthread_mutex_t mutex;
};

/**
 * Initialize an AES-256-CBC cipher with a given password, using the OpenSSL library.
 * The function should handle multiple passwords and ensure thread safety.
 * The encryption key and initialization vector (IV) should be derived from the password using the SHA-256 hash function.
 *
 * @param password The password to use for initializing the cipher
 * @return A pointer to the initialized cipher context, or NULL if an error occurs
 */
struct AESCipherContext* init_aes_cipher(const char* password) {
  // Initialize the mutex used for thread safety
  pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

  // Derive the key and IV lengths from the desired key length (between 128 and 256 bits)
  int key_length = 32; // 256 bits
  int iv_length = 16; // 128 bits

  // Load the hashing algorithm and key/IV lengths from an external configuration file if necessary

  // Initialize the cipher context with the derived key length and IV length
  struct AESCipherContext* ctx = (struct AESCipherContext*) malloc(sizeof(struct AESCipherContext));
  ctx->key = NULL;
  ctx->iv = NULL;

  // Generate the encryption key and initialization vector using SHA-256 hash function
  unsigned char* password_sha256 = (unsigned char*) malloc(SHA256_DIGEST_LENGTH);
  sha256(password, strlen(password), password_sha256);

  // Initialize the AES key and IV using the derived SHA-256 hash
  ctx->key = (AES_KEY*) malloc(sizeof(AES_KEY));
  ctx->iv = (unsigned char*) malloc(iv_length);

  int ret = AES_set_encrypt_key(password_sha256, key_length * 8, ctx->key);
  if (ret != 0) {
    // Handle error: disable the cipher and release resources
    free(ctx->key);
    free(ctx->iv);
    free(ctx);
    return NULL;
  }

  AES_ctr128_encrypt((unsigned char*) ctx->iv, (unsigned char*) ctx->iv, iv_length * 8, ctx->key, NULL, NULL);

  // Clean up and disable the cipher when it is no longer needed
  free(password_sha256);

  return ctx;
}

/**
 * Free the resources associated with an AES cipher context.
 * This function should be called when the cipher is no longer needed to release any allocated resources.
 *
 * @param ctx The pointer to the cipher context to free
 */
void free_aes_cipher(struct AESCipherContext* ctx) {
  // Disable the cipher and release any allocated resources
  AES_disable_encrypt();

  if (ctx->key != NULL) {
    free(ctx->key);
  }

  if (ctx->iv != NULL) {
    free(ctx->iv);
  }

  // Clean up the mutex used for thread safety
  pthread_mutex_destroy(&ctx->mutex);
}
