#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>

// Define constants for the command-line options
#define CONCURRENCY_LEVEL 10
#define OUTPUT_FORMAT "json"
#define LOGGING_SETTINGS "info"

// Define a struct to store information about each URL to be scraped
typedef struct {
    char* url;
    int status_code;
    size_t content_length;
} url_data;

// Define a struct to store the results of the web scrape
typedef struct {
    char* data;
    size_t length;
} scraped_data;

// Define a function to retrieve the data for a given URL
void* curl_request(void* url) {
    // Cast the input argument as a string pointer
    char* url_str = (char*)url;

    // Create a new CURL handle and set the URL to be scraped
    CURL* curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url_str);

        // Set the desired output format for the data
        switch (OUTPUT_FORMAT) {
            case "json":
                curl_easy_setopt(curl, CURLOPT_ACCEPT_ENCODING, "application/json");
                break;
            case "text":
                curl_easy_setopt(curl, CURLOPT_ACCEPT_ENCODING, "text/plain");
                break;
        }

        // Set the desired logging level for the output data
        switch (LOGGING_SETTINGS) {
            case "info":
                curl_easy_setopt(curl, CURLOPT_VERBOSE, 1);
                break;
            case "debug":
                curl_easy_setopt(curl, CURLOPT_VERBOSE, 2);
                break;
        }

        // Perform the web request and retrieve the data
        CURLcode res = curl_easy_perform(curl);

        // Check for any errors during the request
        if (res != CURLE_OK) {
            fprintf(stderr, "Error: %s\n", curl_easy_strerror(res));
        } else {
            long http_code = 0;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
            if (http_code != 200) {
                fprintf(stderr, "HTTP Error: %ld\n", http_code);
            } else {
                // Retrieve the data from the request and store it in the struct
                curl_easy_getinfo(curl, CURLINFO_CONTENT_LENGTH_DOWNLOAD, &url_data.content_length);
                url_data.data = (char*)malloc(sizeof(char) * url_data.content_length);
                if (url_data.data == NULL) {
                    fprintf(stderr, "Error: Out of memory\n");
                } else {
                    curl_easy_getinfo(curl, CURLINFO_EASY_HANDLE, &url_data.handle);
                    res = curl_multi_perform(url_data.handle, &url_data.running_handles);
                    if (res != CURLE_OK) {
                        fprintf(stderr, "Error: %s\n", curl_easy_strerror(res));
                    } else {
                        // Send the data back to the main thread for processing
                        pthread_mutex_lock(&url_data.mutex);
                        url_data.status_code = http_code;
                        pthread_cond_signal(&url_data.cond);
                        pthread_mutex_unlock(&url_data.mutex);
                    }
                }
            }
        }

        // Clean up the CURL handle
        curl_easy_cleanup(curl);
    }
}

// Define a function to perform the web scrape and store the results in a struct
void* web_scrape(void* urls) {
    // Cast the input argument as an array of string pointers
    char** url_list = (char**)urls;

    // Create a new CURL handle and set the URL list to be scraped
    CURLM* multi_handle = curl_multi_init();
    for (int i = 0; i < CONCURRENCY_LEVEL; i++) {
        if (url_list[i] != NULL) {
            curl_multi_add_handle(multi_handle, curl_easy_init());
        }
    }

    // Set the desired output format for the data
    switch (OUTPUT_FORMAT) {
        case "json":
            curl_multi_setopt(multi_handle, CURLOPT_ACCEPT_ENCODING, "application/json");
            break;
