            curl_multi_setopt(multi_handle, CURLOPT_VERBOSE, 1);
            break;
        case "debug":
            curl_multi_setopt(multi_handle, CURLOPT_VERBOSE, 2);
            break;
    }

    // Perform the web request and retrieve the data
    int still_running = 0;
    while (still_running) {
        CURLMcode res = curl_multi_perform(multi_handle, &still_running);
        if (res != CURLE_OK) {
            fprintf(stderr, "Error: %s\n", curl_multi_strerror(res));
        } else {
            // Check for any errors during the request
            CURLMsg* msg = curl_multi_info_read(multi_handle, &still_running);
            if (msg && msg->data.result != CURLE_OK) {
                fprintf(stderr, "Error: %s\n", curl_easy_strerror(msg->data.result));
            } else {
                // Retrieve the data from the request and store it in the struct
                CURL* easy_handle = msg->easy_handle;
                char* url = NULL;
                curl_multi_getinfo(multi_handle, CURLINFO_EASY_HANDLE, &url);
                for (int i = 0; i < CONCURRENCY_LEVEL; i++) {
                    if (url == url_list[i]) {
                        curl_easy_getinfo(easy_handle, CURLINFO_RESPONSE_CODE, &url_data.status_code);
                        url_data.data = (char*)malloc(sizeof(char) * url_data.content_length);
                        if (url_data.data == NULL) {
                            fprintf(stderr, "Error: Out of memory\n");
                        } else {
                            curl_easy_getinfo(easy_handle, CURLINFO_CONTENT_LENGTH_DOWNLOAD, &url_data.content_length);
                            url_data.running_handles--;
                            if (url_data.running_handles == 0) {
                                // Send the data back to the main thread for processing
                                pthread_mutex_lock(&url_data.mutex);
                                pthread_cond_signal(&url_data.cond);
                                pthread_mutex_unlock(&url_data.mutex);
                            }
                        }
                    }
                }
            }
        }
    }

    // Clean up the CURL handle
