#include <openssl/aes.h>
#include <openssl/gcm.h>
#include <openssl/conf.h>
#include <openssl/err.h>
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

// Configuration file path
const char* CONFIG_FILE_PATH = "/path/to/config.conf";

// Thread-safe hashing algorithm
static const EVP_MD *HASHING_ALGORITHM = EVP_get_digestbyname("sha256");

// Key length in bits (default: 256)
static const int KEY_LENGTH = 256;

// IV length in bits (default: 96)
static const int IV_LENGTH = 96;

// Authentication tag length in bits (default: 128)
static const int TAG_LENGTH = 128;

// Number of PBKDF2 iterations (default: 10000)
static const int ITERATIONS = 10000;

// Thread-safe key generation function
void generateKey(unsigned char* key, size_t length) {
    // Generate a random key using PBKDF2
    PKCS5_PBKDF2_HMAC(CONFIG_FILE_PATH, HASHING_ALGORITHM, ITERATIONS, NULL, 0, KEY_LENGTH, key);
}

// Thread-safe IV generation function
void generateIV(unsigned char* iv, size_t length) {
    // Generate a random IV using PBKDF2
    PKCS5_PBKDF2_HMAC(CONFIG_FILE_PATH, HASHING_ALGORITHM, ITERATIONS, NULL, 0, IV_LENGTH, iv);
}

// Thread-safe encryption function
int encrypt(unsigned char* plaintext, size_t plaintext_len, unsigned char* ciphertext, size_t* ciphertext_len) {
    // Create a new AES-NI-256-GCM context
    EVP_CIPHER_CTX *ctx = NULL;
    if (!(ctx = EVP_CIPHER_CTX_new())) {
        ERR_print_errors_fp(stderr);
        return -1;
    }

    // Set the key and IV length based on the given parameters
    int key_len, iv_len;
    if (plaintext_len <= 0xffff) {
        key_len = plaintext_len / 8;
        iv_len = plaintext_len / 8;
    } else {
        key_len = plaintext_len / 16;
        iv_len = plaintext_len / 16;
    }

    // Generate a new key and IV using PBKDF2
    unsigned char key[key_len], iv[iv_len];
    generateKey(key, key_len);
    generateIV(iv, iv_len);

    // Set the encryption algorithm and parameters
    EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, IV_LENGTH / 8, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, NULL, NULL);

    // Allocate memory for the ciphertext and plaintext
    *ciphertext_len = plaintext_len + AES_BLOCK_SIZE;
    unsigned char* buffer = malloc(*ciphertext_len);
    if (!buffer) {
        ERR_print_errors_fp(stderr);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Encrypt the plaintext using AES-NI-256-GCM
    int len = 0, outlen = *ciphertext_len;
    EVP_EncryptUpdate(ctx, buffer, &outlen, plaintext, plaintext_len);
    if (EVP_EncryptFinal_ex(ctx, buffer + outlen, &len) <= 0) {
        ERR_print_errors_fp(stderr);
        EVP_CIPHER_CTX_free(ctx);
        free(buffer);
        return -1;
    }

    // Copy the ciphertext to the output buffer and release resources
    memcpy(ciphertext, buffer, *ciphertext_len);
    EVP_CIPHER_CTX_free(ctx);
    free(buffer);

    return 0;
}

// Thread-safe decryption function
int decrypt(unsigned char* ciphertext, size_t ciphertext_len, unsigned char* plaintext, size_t* plaintext_len) {
    // Create a new AES-NI-256-GCM context
    EVP_CIPHER_CTX *ctx = NULL;
    if (!(ctx = EVP_CIPHER_CTX_new())) {
        ERR_print_errors_fp(stderr);
        return -1;
    }

    // Set the key and IV length based on the given parameters
    int key_len, iv_len;
    if (ciphertext_len <= 0xffff) {
        key_len = ciphertext_len / 8;
        iv_len = ciphertext_len / 8;
    } else {
        key_len = ciphertext_len / 16;
        iv_len = ciphertext_len / 16;
    }

    // Generate a new key and IV using PBKDF2
    unsigned char key[key_len], iv[iv_len];
    generateKey(key, key_len);
    generateIV(iv, iv_len);

    // Set the decryption algorithm and parameters
    EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, IV_LENGTH / 8, NULL);
    EVP_DecryptInit_ex(ctx, NULL, NULL, NULL, NULL);

    // Allocate memory for the plaintext and ciphertext
    *plaintext_len = ciphertext_len - AES_BLOCK_SIZE;
    unsigned char* buffer = malloc(*plaintext_len);
    if (!buffer) {
        ERR_print_errors_fp(stderr);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Decrypt the ciphertext using AES-NI-256-GCM
    int len = 0, outlen = *plaintext_len;
    EVP_DecryptUpdate(ctx, buffer, &outlen, ciphertext, ciphertext_len);
    if (EVP_DecryptFinal_ex(ctx, buffer + outlen, &len) <= 0) {
        ERR_print_errors_fp(stderr);
        EVP_CIPHER_CTX_free(ctx);
        free(buffer);
        return -1;
    }

    // Copy the plaintext to the output buffer and release resources
    memcpy(plaintext, buffer, *plaintext_len);
    EVP_CIPHER_CTX_free(ctx);
    free(buffer);

    return 0;
}

// Main function
int main() {
    // Initialize the OpenSSL library
    SSL_library_init();
    ERR_load_crypto_strings();
    OpenSSL_add_all_algorithms();

    // Set up the encryption and decryption functions
    encrypt = &encrypt;
    decrypt = &decrypt;

    // Encrypt a message
    unsigned char plaintext[] = "Hello, World!";
    size_t plaintext_len = strlen((char*)plaintext);
    unsigned char ciphertext[1024];
    size_t ciphertext_len = 1024;
    if (encrypt(plaintext, plaintext_len, ciphertext, &ciphertext_len) < 0) {
        printf("Error: Encryption failed\n");
        return -1;
    }

    // Decrypt the message
    unsigned char decrypted_plaintext[1024];
    size_t decrypted_plaintext_len = 1024;
    if (decrypt(ciphertext, ciphertext_len, decrypted_plaintext, &decrypted_plaintext_len) < 0) {
        printf("Error: Decryption failed\n");
        return -1;
    }

    // Print the results
    printf("Plaintext: %s\n", plaintext);
    printf("Ciphertext: ");
    for (size_t i = 0; i < ciphertext_len; ++i) {
        printf("%02x ", ciphertext[i]);
    }
    printf("\n");
    printf("Decrypted plaintext: %s\n", decrypted_plaintext);

    // Clean up
    EVP_cleanup();

    return 0;
}
