from typing import Dict, List, Optional

def handle_order_batch_processing(orders: List[Dict], api_client: ExternalAPIClient):
    # Initialize variables
    processed_orders = []
    failed_updates = []
    start_time = datetime.datetime.now()

    # Validate order status transitions according to predefined rules
    for order in orders:
        # Check if the order is eligible for update
        if not is_eligible_for_update(order):
            continue

        # Update order status and delivery person assignment
        updated_order = update_order_status(order, api_client)

        # If the update was successful, add it to the list of processed orders
        if updated_order:
            processed_orders.append(updated_order)

        # Otherwise, log the failed update and continue with the next order
        else:
            logging.warning(f"Failed to update order {order['id']}. Reason: {api_client.last_error}")
            failed_updates.append(order)

    # Handle concurrent updates to ensure data consistency
    handle_concurrent_updates(processed_orders, api_client)

    # Optimize query performance based on order status
    optimize_query_performance(processed_orders)

    # Log successful updates and failed updates
    logging.info(f"Successfully processed {len(processed_orders)} orders in {datetime.datetime.now() - start_time}. Failed to update {len(failed_updates)} orders.")

    return processed_orders, failed_updates

def is_eligible_for_update(order: Dict) -> bool:
    # Check if the order status is valid for update
    if order['status'] not in ('Preparing', 'On the Way', 'Delivered'):
        return False

    # Check if the delivery person assignment is valid
    if order['delivery_person'] and api_client.is_valid_delivery_person(order['delivery_person']):
        return True

    # Otherwise, the order is not eligible for update
    return False

def update_order_status(order: Dict, api_client: ExternalAPIClient) -> Optional[Dict]:
    try:
        updated_order = api_client.update_order_status(order['id'], order['status'])

        # If the update was successful, assign a delivery person if necessary
        if updated_order and order['delivery_person']:
            updated_order = api_client.assign_delivery_person(updated_order['id'], order['delivery_person'])

        return updated_order

    except ExternalAPIError as e:
        # Log the error and continue with the next order
        logging.warning(f"Failed to update order {order['id']}. Reason: {e}")
        return None

def handle_concurrent_updates(processed_orders: List[Dict], api_client: ExternalAPIClient):
    # Partition the processed orders into smaller sub-batches if necessary
    sub_batches = partition_orders(processed_orders)

    # Update the orders in each sub-batch concurrently to ensure data consistency
    for sub_batch in sub_batches:
        api_client.update_orders_concurrently(sub_batch)

def optimize_query_performance(processed_orders: List[Dict]):
    # Check if the orders need to be optimized based on their status
    if not needs_optimization(processed_orders):
        return

    # Optimize the query performance based on the order statuses
    optimize_query_performance_based_on_status(processed_orders)

def partition_orders(orders: List[Dict]) -> List[List[Dict]]:
    # Partition the orders into smaller sub-batches if necessary
    sub_batches = [[]]

    for order in orders:
        if len(sub_batches[-1]) >= 50:
            sub_batches.append([])

        sub_batches[-1].append(order)

    return sub_batches

def needs_optimization(orders: List[Dict]) -> bool:
    # Check if the orders need to be optimized based on their status
    for order in orders:
        if order['status'] == 'Preparing':
            return True

    return False

def optimize_query_performance_based_on_status(orders: List[Dict]):
