function dynamicFileNameUpdate(filename, fileType, versionNumber) {
  // Determine if the filename already contains an extension and versioning information
  const hasExtension = /\.[^/.]+$/.test(filename);
  const hasVersioning = /[^/.]+\.v\d+$/.test(filename);

  // Handle cases with multiple extensions or version numbers
  if (hasExtension && !hasVersioning) {
    return `${filename}.${versionNumber}`;
  } else if (!hasExtension && hasVersioning) {
    return filename.replace(/[^/.]+\.v\d+$/, `.${versionNumber}`);
  } else if (hasExtension && hasVersioning) {
    return filename.replace(/\.[^/.]+\.v\d+$/, `.${versionNumber}`);
  } else {
    return `${filename}.${fileType}.v${versionNumber}`;
  }
}
