import psycopg2
from sqlalchemy import create_engine
from sqlalchemy.orm import sessionmaker

class DatabaseConnectionManager:
    def __init__(self, db_type, db_config):
        self.db_type = db_type
        self.db_config = db_config
        self.pool_size = 10
        self.engine = None
        self.sessionmaker = None

    def establish_connection(self):
        if self.db_type == 'postgresql':
            self.engine = create_engine(f'postgresql://{self.db_config["user"]}:{self.db_config["password"]}@{self.db_config["host"]}:{self.db_config["port"]}/{self.db_config["database"]}')
        elif self.db_type == 'sqlite':
            self.engine = create_engine(f'sqlite:///{self.db_config["database"]}.db')

        self.sessionmaker = sessionmaker(bind=self.engine)

    def execute_query(self, query, params=None):
        with self.engine.connect() as conn:
            result = conn.execute(query, params or {})
            return result.fetchall()

    def start_transaction(self):
        with self.engine.begin() as conn:
            self.sessionmaker.configure(bind=conn)
            self.session = self.sessionmaker()

    def commit_transaction(self):
        self.session.commit()

    def rollback_transaction(self):
        self.session.rollback()

    def get_pool_size(self):
        return self.pool_size

    def set_pool_size(self, size):
        if size < 0:
            raise ValueError('Pool size must be greater than or equal to zero')
        self.pool_size = size
