import time
from collections import deque
from threading import Lock

class Cache:
    def __init__(self, size=1024):
        self.size = size
        self.data = {}
        self.queue = deque([], maxlen=self.size)
        self.lock = Lock()

    def put(self, key, value):
        with self.lock:
            if key in self.data:
                del self.data[key]
            self.data[key] = value
            self.queue.append(key)

    def get(self, key):
        with self.lock:
            if key not in self.data:
                return None
            self.queue.remove(key)
            self.queue.append(key)
            return self.data[key]

    def remove(self, key):
        with self.lock:
            if key in self.data:
                del self.data[key]
                self.queue.remove(key)

    def clear(self):
        with self.lock:
            self.data = {}
            self.queue = deque([], maxlen=self.size)

class LRUCache:
