Here's an example implementation of a function in C that initializes an AES-256-GCM cipher with a given password using the OpenSSL library:
```
#include <openssl/aes.h>
#include <openssl/gcm.h>
#include <openssl/sha.h>
#include <stdlib.h>
#include <string.h>

// Initialize an AES-256-GCM cipher with a given password
int init_aes_gcm(const char* password, const size_t iv_len, const size_t tag_len) {
  // Check input parameters
  if (password == NULL || iv_len <= 0 || tag_len <= 0) {
    return -1;
  }

  // Derive encryption key from password using SHA-256 hash function
  unsigned char key[32];
  memset(key, 0, sizeof(key));
  SHA256_CTX sha256;
  SHA256_Init(&sha256);
  SHA256_Update(&sha256, (const unsigned char*)password, strlen(password));
  SHA256_Final(key, &sha256);

  // Initialize AES-256-GCM cipher with derived key and specified IV length
  EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
  int ret = EVP_EncryptInit(ctx, EVP_aes_256_gcm(), key, iv_len);
  if (ret == 0) {
    EVP_CIPHER_CTX_free(ctx);
    return -1;
  }

  // Set tag length for authentication
  ret = EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG_LEN, tag_len, NULL);
  if (ret == 0) {
    EVP_CIPHER_CTX_free(ctx);
    return -1;
  }

  // Return cipher context for further use
  return ctx;
}

// Clean up and disable an AES-256-GCM cipher
int cleanup_aes_gcm(EVP_CIPHER_CTX* ctx) {
  if (ctx == NULL) {
    return -1;
  }

  // Disable cipher context
  EVP_EncryptInit(ctx, NULL, NULL, 0);
  EVP_CIPHER_CTX_free(ctx);

  // Return success status
  return 0;
}
```
This function takes a password as input and uses the SHA-256 hash function to derive an encryption key from it. The derived key is then used to initialize an AES-256-GCM cipher with the specified IV length. The tag length for authentication can also be specified using the `tag_len` parameter.

The function returns a `EVP_CIPHER_CTX*` object that can be used for further encryption and decryption operations. When the cipher is no longer needed, the `cleanup_aes_gcm()` function should be called to clean up and disable the cipher context.

Note that this implementation assumes that the input password is a null-terminated string. If you are using a raw byte array as input, you may need to modify the code accordingly.

