```
// DynamicOctreeSpatialPartitioner class definition
class DynamicOctreeSpatialPartitioner {
public:
    // Constructor for initializing the octree structure with a given capacity
    DynamicOctreeSpatialPartitioner(int capacity) : capacity_(capacity), root_(nullptr) {}

    // Destructor for freeing memory allocated by the octree
    ~DynamicOctreeSpatialPartitioner() { freeMemory(); }

    // Method for initializing the octree structure with a given capacity
    void initialize(int capacity) {
        if (root_ != nullptr) {
            throw std::runtime_error("Cannot reinitialize an already initialized octree");
        }
        capacity_ = capacity;
        root_ = new OctreeNode();
    }

    // Method for adding a data point to the octree
    void addDataPoint(const Point3D& point) {
        if (root_ == nullptr || point.x < 0 || point.y < 0 || point.z < 0) {
            throw std::runtime_error("Invalid input: cannot add a data point outside of the octree bounds");
        }
        OctreeNode* node = root_;
        while (true) {
            int childIndex = getChildIndex(point, node->boundingBox);
            if (node->children[childIndex] != nullptr) {
                node = node->children[childIndex];
            } else {
                break;
            }
        }
        OctreeNode* newNode = new OctreeNode();
        newNode->boundingBox.x = point.x;
        newNode->boundingBox.y = point.y;
        newNode->boundingBox.z = point.z;
        node->children[childIndex] = newNode;
    }

    // Method for querying the octree for all elements within a given bounding box
    std::vector<Point3D> getAllElementsInBoundingBox(const BoundingBox& bbox) {
        std::vector<Point3D> results;
        queryOctreeRecursive(root_, bbox, results);
        return results;
    }

private:
    // Private method for freeing memory allocated by the octree
    void freeMemory() {
        if (root_ != nullptr) {
            delete root_;
            root_ = nullptr;
        }
    }

    // Private method for recursively querying the octree for elements within a given bounding box
    void queryOctreeRecursive(OctreeNode* node, const BoundingBox& bbox, std::vector<Point3D>& results) {
        if (node == nullptr || !bbox.intersectsWith(node->boundingBox)) {
            return;
        }
        for (int i = 0; i < 8; ++i) {
            if (node->children[i] != nullptr && node->children[i]->boundingBox.intersectsWith(bbox)) {
                queryOctreeRecursive(node->children[i], bbox, results);
            }
        }
        for (auto& point : node->points) {
            if (bbox.containsPoint(point)) {
                results.push_back(point);
            }
        }
    }

    // Private method for getting the child index of a given data point within an octree node
    int getChildIndex(const Point3D& point, const BoundingBox& bbox) {
        return (point.x > bbox.center.x ? 1 : 0) + (point.y > bbox.center.y ? 2 : 0) + (point.z > bbox.center.z ? 4 : 0);
    }

    // Private class representing an octree node with a bounding box and a list of data points
    struct OctreeNode {
        BoundingBox boundingBox;
        std::vector<Point3D> points;
        OctreeNode* children[8];
    };

    // Private variable for the octree capacity
    int capacity_;

    // Private variable for the root node of the octree
    OctreeNode* root_;
};

// FindElementsBySelector function definition
function FindElementsBySelector(node, selector, callback) {
    if (node == nullptr) return;
    var results = [];
    findElementsRecursive(node, selector, callback, results);
    return results;
}

// Private recursive function for traversing a DOM tree starting from a given node and returning a list of elements matching a provided selector
function findElementsRecursive(node, selector, callback, results) {
    if (node.matches(selector)) {
        results.push(callback(node));
    }
    for (var i = 0; i < node.children.length; ++i) {
        findElementsRecursive(node.children[i], selector, callback, results);
    }
}
