using Microsoft.Web.Administration;

public static class WebSiteManager
{
    private const int DefaultTimeout = 10 * 1000; // 10 seconds
    private const string WebConfigFile = "web.config";
    private const string SiteNamePrefix = "site_";
    private const string SitePortPrefix = "port_";

    public static async Task AddSiteAsync(string directoryPath, string siteName, int portNumber)
    {
        try
        {
            // Ensure that the directory path is valid and accessible.
            if (!Directory.Exists(directoryPath))
            {
                throw new DirectoryNotFoundException($"The specified directory '{directoryPath}' does not exist.");
            }

            if (!Directory.GetAccessControl(directoryPath).AreAccessRulesProtected)
            {
                throw new UnauthorizedAccessException($"Insufficient permissions to access the directory '{directoryPath}'.");
            }

            // Check if a web.config file exists in the directory, and attempt to generate one if it does not.
            var webConfigFilePath = Path.Combine(directoryPath, WebConfigFile);
            if (!File.Exists(webConfigFilePath))
            {
                using (var configManager = new ConfigurationManager())
                {
                    configManager.ApplyDefaultConfiguration();
                    configManager.SaveAs(webConfigFilePath);
                }
            }

            // Validate the site name to ensure it meets naming conventions.
            if (!IsValidSiteName(siteName))
            {
                throw new ArgumentException($"The specified site name '{siteName}' is not valid.", nameof(siteName));
            }

            // Log any validation errors.
            var validationErrors = ValidateSite(directoryPath, siteName);
            if (validationErrors.Any())
            {
                throw new ArgumentException($"The specified site is not valid: {string.Join(", ", validationErrors)}");
            }

            // Acquire a lock to prevent race conditions.
            using (var processLock = new ProcessLock(directoryPath))
            {
                // Start the site if it is not already running.
                var siteManager = new ServerManager();
                var site = siteManager.Sites[siteName];
                if (site == null)
                {
                    site = siteManager.Sites.Add(siteName, portNumber);
                }

                site.Bindings.Clear();
                site.Bindings.Add("*:80:" + siteName);

                var result = siteManager.CommitChanges();
                if (result != NativeMethods.NO_ERROR)
                {
                    throw new Win32Exception(result, $"Failed to add or start the site '{siteName}' in directory '{directoryPath}'.");
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error adding or starting site: {ex}");
        }
    }

    private static bool IsValidSiteName(string name) => !name.Any(char.IsWhiteSpace);

    private static IEnumerable<string> ValidateSite(string directoryPath, string siteName)
    {
        var validationErrors = new List<string>();

        // Check if the directory contains a web.config file.
        var webConfigFilePath = Path.Combine(directoryPath, WebConfigFile);
        if (!File.Exists(webConfigFilePath))
        {
            validationErrors.Add("The directory does not contain a web.config file.");
        }

        // Check if the site name is unique within the directory.
        var siteManager = new ServerManager();
        foreach (var existingSite in siteManager.Sites)
        {
            if (existingSite.Name == siteName && !string.Equals(existingSite.Path, directoryPath, StringComparison.OrdinalIgnoreCase))
            {
                validationErrors.Add($"The site name '{siteName}' is already in use by another site.");
            }
        }

        return validationErrors;
    }
}

public class ProcessLock : IDisposable
{
    private readonly string _directoryPath;
    private readonly Mutex _mutex;

    public ProcessLock(string directoryPath)
    {
        _directoryPath = directoryPath;
        _mutex = new Mutex(false, $"{_directoryPath}_lock");
    }

    public void Dispose() => _mutex.ReleaseMutex();
}
