const tiff = require('tiff-js');
const imageProcessingPipeline = require('image-processing-pipeline');

// Define the context for module loading and execution
const modules = {};
const moduleSequence = [];

// Load and execute modules in sequence, handling missing or failed modules gracefully
async function loadAndExecuteModules() {
  // Load each module in sequence according to the defined configuration file
  for (let i = 0; i < moduleSequence.length; i++) {
    const moduleName = moduleSequence[i];
    if (!modules[moduleName]) {
      try {
        modules[moduleName] = require(path.join(__dirname, '../node_modules', moduleName));
        console.log(`Loaded module ${moduleName} successfully.`);
      } catch (err) {
        console.error(`Failed to load module ${moduleName}:`, err);
        continue;
      }
    }

    // Execute the loaded module with the appropriate context and arguments
    try {
      const result = modules[moduleName].execute(context);
      console.log(`Executed module ${moduleName} successfully.`);
    } catch (err) {
      console.error(`Failed to execute module ${moduleName}:`, err);
