using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;

namespace DynamicDatabaseConnectionManager
{
    public class DynamicDatabaseConnectionManager
    {
        private readonly string _connectionStringTemplate;
        private readonly Dictionary<string, string> _tenantIdMapping;
        private readonly List<SqlConnection> _pool;
        private readonly IConfigurationManager _configManager;

        public DynamicDatabaseConnectionManager(IConfigurationManager configManager)
        {
            _configManager = configManager;
            _connectionStringTemplate = _configManager.GetValue<string>("ConnectionStrings:Default");
            _tenantIdMapping = new Dictionary<string, string>();
            _pool = new List<SqlConnection>();
        }

        public async Task EstablishConnection(string tenantId)
        {
            if (!_tenantIdMapping.ContainsKey(tenantId))
            {
                // Fetch the latest connection string from an external configuration service if the template is updated externally
                _connectionStringTemplate = await _configManager.GetValueAsync<string>("ConnectionStrings:Default");
            }

            var connectionString = GetTenantConnectionString(tenantId);
            using (var connection = new SqlConnection(connectionString))
            {
                try
                {
                    await connection.OpenAsync();
                    _pool.Add(connection);
                }
                catch (Exception ex)
                {
                    // Handle exception and log it
                }
            }
        }

        public async Task<SqlDataReader> ExecuteQuery(string query, string tenantId)
        {
            var connectionString = GetTenantConnectionString(tenantId);
            using (var connection = new SqlConnection(connectionString))
            {
                try
                {
                    await connection.OpenAsync();
                    var command = new SqlCommand(query, connection);
                    return await command.ExecuteReaderAsync();
                }
                catch (Exception ex)
                {
                    // Handle exception and log it
                    throw;
                }
            }
        }

        public async Task BeginTransaction(string tenantId)
        {
            var connectionString = GetTenantConnectionString(tenantId);
            using (var connection = new SqlConnection(connectionString))
            {
                try
                {
                    await connection.OpenAsync();
                    connection.BeginTransaction();
                }
                catch (Exception ex)
                {
                    // Handle exception and log it
                    throw;
                }
            }
        }

        public async Task CommitTransaction(string tenantId)
        {
            var connectionString = GetTenantConnectionString(tenantId);
            using (var connection = new SqlConnection(connectionString))
            {
                try
                {
                    await connection.OpenAsync();
                    connection.CommitTransaction();
                }
                catch (Exception ex)
                {
                    // Handle exception and log it
                    throw;
                }
            }
        }

        public async Task RollbackTransaction(string tenantId)
        {
            var connectionString = GetTenantConnectionString(tenantId);
            using (var connection = new SqlConnection(connectionString))
            {
                try
                {
                    await connection.OpenAsync();
                    connection.RollbackTransaction();
                }
                catch (Exception ex)
                {
                    // Handle exception and log it
                    throw;
                }
            }
        }

        public string GetTenantConnectionString(string tenantId)
        {
            if (_tenantIdMapping.ContainsKey(tenantId))
            {
                return _connectionStringTemplate.Replace("{tenantId}", tenantId);
            }

            // Fetch the latest connection string from an external configuration service if the template is updated externally
            _connectionStringTemplate = await _configManager.GetValueAsync<string>("ConnectionStrings:Default");
            return _connectionStringTemplate.Replace("{tenantId}", tenantId);
        }

        public void CloseConnection(SqlConnection connection)
        {
            if (connection != null)
            {
                try
                {
                    connection.Close();
                    _pool.Remove(connection);
                }
                catch (Exception ex)
                {
                    // Handle exception and log it
                }
            }
        }

        public void UpdateConfiguration(string newConnectionStringTemplate, Dictionary<string, string> newTenantIdMapping)
        {
            _connectionStringTemplate = newConnectionStringTemplate;
            _tenantIdMapping.Clear();
            foreach (var tenant in newTenantIdMapping)
            {
                _tenantIdMapping[tenant.Key] = tenant.Value;
            }
        }

        public override string ToString()
        {
            return $"Active connection: {_connectionStringTemplate}, Tenants: {string.Join(", ", _tenantIdMapping.Keys)}";
        }
    }
}
